INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Oldu', 'ne-oldu-murat-dere-ht24g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani dünya dönmeyecekti, 

Zaman su olup akmayacaktı, 

Yapraklar kurumayıp çicekler solmayacaktı, 

Peki ama ne oldu, 

Ne oldu be gülüm, 

Ne oldu, 

Ne senin üstünde gürledi gökler 

Ne benim altımda dalgalandı yer 

Hani ayrılmayacaktık, 

Hiç birbirimizi üzmeyecektik, 

Kutuplara gitsek donmayacak, 

Çöle gitsek yanmayacaktık, 

Ne oldu sevgilim ben üşüyoooorruuum, 

Ne olduuuu,', 'Hani dünya dönmeyecekti,  Zaman su olup akmayacaktı,  Yapraklar kurumayıp çicekler solmayacaktı,  Peki ama ne oldu,  Ne oldu be gülüm,  Ne o...', ARRAY['Türk Edebiyatı','Şiir','Murat Dere']::text[], 8.5, '{"poet":"Murat Dere","poet_slug":"murat-dere","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-oldu-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-murat-dere-xn0ic', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünyayı tanımıyorum, 

Tanıyacak gibi oluyorum ya üşüyorum ya yanıyorum, 

Baze titriyor bazen terliyorum, 

Oanda bana ne oluyor bilmiyorum, 

Bazen insanlardan korkuyorum bazen onları çok seviyorum, 

İnsan olduğumu sevdiklerimin yanın da anlıyorum, 

Sevdiklerim beni neden terk ediyor onu anlamıyor ve için için yanıyorum, 

Oanada bana ne oluyor bilmiyorum, 

AMA ARTIK BİR BİLGİĞİM VAR HAYATI SEVİYORUM.', 'Dünyayı tanımıyorum,  Tanıyacak gibi oluyorum ya üşüyorum ya yanıyorum,  Baze titriyor bazen terliyorum,  Oanda bana ne oluyor bilmiyorum,  ...', ARRAY['Türk Edebiyatı','Şiir','Murat Dere']::text[], 8.5, '{"poet":"Murat Dere","poet_slug":"murat-dere","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bilmiyorum-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrencimsi', 'ogrencimsi-abdulkadir-i-lyas-y74yv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öss öss dediler 

Başımın etini yediler

Ben tıp kazanacam dedim

Kafayı yemiş dediler..

Yıllar geçse bitmez acın

Kazanamazsan ağrır başın 

Bir de kaldın mı gelecek seneye 

Durmaz çatlar göbek bağın...

Yok başka çare ya kazanaksın 

Kök sökerken gelişir kasın 

Ağıtın kurtarmaz seni o an 

Yaş döksen de dinmez sızın...

                                          (2005)', 'Öss öss dediler  Başımın etini yediler Ben tıp kazanacam dedim Kafayı yemiş dediler.. Yıllar geçse bitmez acın Kazanamazsan ağrır başın  Bir...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir İlyas']::text[], 8.5, '{"poet":"Abdulkadir İlyas","poet_slug":"abdulkadir-i-lyas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ogrencimsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demiştin', 'demistin-nevher-i-smail-yilmaz-j6md0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'en son sen vardın yanıbaşımda

bir senfoni dinliyorduk birlikte

baş  başa

kadehler elimizde

zil  zurna  sarhoş

ışıkları çok uzaklardaki

bu büyük şehrin büyüsü

öldürür insanı demiştin

zehir zemberek laflar ettirir insana

aşka dair

kah mutlu eder kah ağlatır

öyle bir yanlızlıktırki bazen paylaşılan

çölde su kadar değerlidir

saniyeler

her şey yaşanır yaşanmasınada

kendi gizinde kaybolur

bu büyük şehrin büyüsü

güldürür insanı demiştin

o anlar sanki var gibidir

ama yoktur

değersiz sanma sakın

kimle yaşanıldığı

kimle paylaşıldığı

çok önemlidir

bu büyük şehrin büyüsü

inan bazen

kalabalıklar içinde yanlızlıkla

süründürür insanı

demiştin

öyleymiş

(11.Mart.2005-Denizli)', 'en son sen vardın yanıbaşımda bir senfoni dinliyorduk birlikte baş  başa kadehler elimizde zil  zurna  sarhoş ışıkları çok uzaklardaki bu bü...', ARRAY['Türk Edebiyatı','Şiir','Nevher İsmail Yılmaz']::text[], 8.5, '{"poet":"Nevher İsmail Yılmaz","poet_slug":"nevher-i-smail-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/demistin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükendim artık..', 'tukendim-artik-zeynep-aydinlioglu-7l1nd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'TÜKENDİM ARTIK! 

Tükendim artık tükendim. 

Ayak seslerim gelmiyor, 

Duygularımı özgür bıraktım artık 

Çünkü yaşam bir tat vermiyor. 

Her attığım adım ses çıkarırdı 

Her bakışım bana aşk yaşatırdı 

Tükendim artık tükendim. 

Kalbim bu sese yanıt vermiyor..', 'TÜKENDİM ARTIK!  Tükendim artık tükendim.  Ayak seslerim gelmiyor,  Duygularımı özgür bıraktım artık  Çünkü yaşam bir tat vermiyor.  Her att...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tukendim-artik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sensiz Bırakma', 'beni-sensiz-birakma-sedat-erdogdu-qviv9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BENİ SENSİZ BIRAKMA

Beni sensiz bırakıp, gitme ne olur

Yüreğime oturur, serseri bulut

Gözlerimde dağılır, gül suretin

Çatallanmış kalbimi, ellerinde tut.

Beni sensiz bırakıp, gitme ne olur

Damarımda buz tutar, taze baharlar

Dolaşırım avare, kaldırımlarda

Yanık türküler söyler, solan yapraklar...

Beni sensiz bırakıp, gitme ne olur

Acil kayıt hattımdan, silinir ismin.

Bu can bize emanet, boş çerçevede

Belki çıkmam sabaha, sızlar yüreğin...

Sedat Erdoğdu    - 16.10.2005 -

İskenderun', 'BENİ SENSİZ BIRAKMA Beni sensiz bırakıp, gitme ne olur Yüreğime oturur, serseri bulut Gözlerimde dağılır, gül suretin Çatallanmış kalbimi, e...', ARRAY['Türk Edebiyatı','Şiir','Sedat Erdoğdu']::text[], 8.5, '{"poet":"Sedat Erdoğdu","poet_slug":"sedat-erdogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beni-sensiz-birakma-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeri Var', 'yeri-var-i-brahim-halil-demir-tzltk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevenin halından anlayanın,

Başımın gözümün üstünde yeri var.

Beni sırt üstü bırakıp gidenin,

Bağrımda fokur fokur kaynayan aşkı var.     

Bana sevda suyunu kana kana içirenin,

Tenimden gitmeyen sıcaklığı var.

Beni sevda hançeriyle vuranın,

Başı sevdalı,dumanlı karlı dağı var.

Bana en dertli sevda türkülerini söyletenin,

Kulağımda çınlayan ahenkli bir sesi var.

Aşkın gözyaşıyla ütüleyip giydirenin,

Üstümden hiç soymadığım sevda gömleği var.

Aşkını saklayıp, sevdasını benden kaçıranın,

Parmağımda adının yazılı olduğu yüzüğü var.

Hayatın baharında beni gülmeye küstürenin,

Elimde aşkının ağulu şerbeti var.

16/10/2005', 'Sevenin halından anlayanın, Başımın gözümün üstünde yeri var. Beni sırt üstü bırakıp gidenin, Bağrımda fokur fokur kaynayan aşkı var.      B...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeri-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhammed''e Mektup', 'muhammed-e-mektup-abdulkadir-i-lyas-85dyp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen gittiğin günden beri nice haller tanınmaz oldu

Küffara el öptürenin torunu küffara el etek divan durdu

Ahkam keser oldu ortalıkta daha dünün çakalı kurdu

İnatla kendine gelmedi gafiller kalmadı da üzerinde yatacak yurdu...

Sen giderken bize bıraktın sevgi dostluk kardeşliği

Veren el olmaya gelince sıra akmadı çoğunun dolu ibriği

Henüz cihada başlamadan biz kabüllendik bile yenilgiyi

Belki en korkunç anıydı hayatın yokoluşumuzun sessizliği...

Sen gittin seninle gitti getirdiğin güzellikler

Akıl alınabilecek kim vardı ki ortaya çıkmayınca cesur yürekler

Allah yolunda savaş sır oldu dünden kaçamaklı ödlekler

Dedelerimin kanı dondu da yokoluverdi sanki melekler..

Sen ki bizim için biçilmiş kaftan insanlığa sunulan en yüce ihsan

Değerin bilinemedi yeryüzünde diktiğin çiçeklere sürülünce kan

Doyamadık sana koca hayatta sana yazdık da çoğu zaman 

Dertler hiç dinmedi şunu anladık yaşamalı seni yaşadıkça heran....

Sen bize merhamet etmezsen sonumuz kızgın ateşten ibaret

Külleriiz savrulurken yüce semaya feryat artar kopar kıyamet

Derdimize deva umarız senden olsa da suçumuz sana ihanet

Bağışla biiz ey yüce insan seni sevmek bizde tek ibadet....

                                                                         (2005)', 'Sen gittiğin günden beri nice haller tanınmaz oldu Küffara el öptürenin torunu küffara el etek divan durdu Ahkam keser oldu ortalıkta daha d...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir İlyas']::text[], 8.5, '{"poet":"Abdulkadir İlyas","poet_slug":"abdulkadir-i-lyas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/muhammed-e-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galata', 'galata-nevher-i-smail-yilmaz-9juic', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kulaklarımda eski bir melodi

ve eski siyah beyaz bir resim gözlerimde

bir vapur düdüğünün

yada bir martı çığlığının

beni götürdüğü yerde tanıştım seninle Galata

dedilerki gel vazgeç bu sevdadan

koluma girip sürüklediler

ama bir ay sonra bir ay ışığında

yine sen ve ben sabaha karşı buluştuk Galata

dalga sesleri oldu çok eski bir melodi

gölgelerse siyah beyaz bir resim

ve bekledik durduk vapur düdüğünün sesini

yada bir martının çığlığını

ve sonra

her şafak söktüğünde

gizli, gizli buluştuk seninle Galata

o gün bu gündür

illede galata  hep galata', 'kulaklarımda eski bir melodi ve eski siyah beyaz bir resim gözlerimde bir vapur düdüğünün yada bir martı çığlığının beni götürdüğü yerde tan...', ARRAY['Türk Edebiyatı','Şiir','Nevher İsmail Yılmaz']::text[], 8.5, '{"poet":"Nevher İsmail Yılmaz","poet_slug":"nevher-i-smail-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/galata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğurlar Ola..', 'ugurlar-ola-nurdane-diken-jxz6o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel, kaderim! 

Otur karşıma! 

Şöyle bir dertleşelim seninle.

Ne o kaçıyormusun? 

Yüzün yok mu? 

Yüzüme bakmağa? ..

Tazı gibi koşturuyorsun, peşinde! 

Sen dinlemesende, ben anlatacağım.

Belki, nadim olur, bırakırsın peşimi.

Kararların benim için, vazgeçilmezdi.

Sevgi, hayat rehberimdi...

Ezdin beni...

Bir böcek gibi ayaklarınla.

Ben parçaları birleştirdim.

Bir bütün yaptım.

Sen yıktın! ..

Bin gecenin günâhını,

Bir geceye yükledin....

Ben yokuş tırmandım.

Zirveye çıktım.

Sen aşağı indirdin..

Ben yaptım.

Sen yıktın.

Aradım, bulduklarımı

Sen kaybettirdin! 

Aşkı anlamayanlara,

Sevgiyi bilmeyenlere,

Çerez ettin...

Bin geceden alıp, 

Bir gecede mahvettin....

Gönlümü harap ettin.

En büyük kötülüğü, sen ettin.

Dön! ...

Bir bak bana! ....

Yıkılmadık ne kaldı! 

Küsüm sana.....

Beklentim yok artık.

Anlasana! ....

Nadim olup, beni anlasan.

Bu saatten sonra,

Ne ola ki bana....

Hadi! .....

Kaderim sana.

Uğurlar ola........', 'Gel, kaderim!  Otur karşıma!  Şöyle bir dertleşelim seninle. Ne o kaçıyormusun?  Yüzün yok mu?  Yüzüme bakmağa? .. Tazı gibi koşturuyorsun, ...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ugurlar-ola-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaküstü aşklara yabancı yüreğim', 'ayakustu-asklara-yabanci-yuregim-celal-topo-eb58j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşünmezdim dostlukların bu kadar ucuza satıldığını

Ayaküstü aşklara çok yabancı yüreğim

Böylesi sevgilere merhaba demektense 

Hoşça kal demek gerekiyormuş bilemedim...

Bu deli yürek bu çılgın şair

Yüreğini sana yaslamak istedi

Tutmak istedi ellerini

Sen onu en acı bir şarkıda

Mahkum ettin yalnızlığının karanlığına

Bir başına bıraktın acının dallarında

Artık tomurcuk veremeyecek

Ne gülüşten nede mutluluktan yana

O şimdi yalnız başına

Hüzünlerini mısralarının yüzüne çizip

Dostluğun kalleşliğini acı bir çayla

Her içtiğinde hatırlıyor...

Yaşlı gözlerle zamanın tüketilmişliğinde

Hayalinin penceresinden bakıp ta

Ağlayarak seni seyrediyor....



16./..10../2005

Antalya', 'Düşünmezdim dostlukların bu kadar ucuza satıldığını Ayaküstü aşklara çok yabancı yüreğim Böylesi sevgilere merhaba demektense  Hoşça kal dem...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ayakustu-asklara-yabanci-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Akşamı', 'eylul-aksami-nurcemal-ozturk-fzjh7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir eylül akşamında ayışığı altında

Oturmuş seyrederken şehrin ışıklarını

Yalnızlığı farkettim,bankın öbür ucunda

Bana çevirmiş ürkek,sinsi bakışlarını.

İçimdeki acının tek faili yalnızlık

Gönlümün,sığındığı tek sahili yalnızlık.

Bir bu katil duygudan,bir gurbetten çektim ben

Bu ikisi yüzünden genç yaşımda çöktüm ben

Fırtınaya tutulmuş bir sandal gibi gönlüm

İçimdeki acıyı gözlerimden döktüm ben.

Gözlerimdeki yaşın tek sebebi yalnızlık

Beni mahzun eyleyen,geberesi yalnızlık.', 'Bir eylül akşamında ayışığı altında Oturmuş seyrederken şehrin ışıklarını Yalnızlığı farkettim,bankın öbür ucunda Bana çevirmiş ürkek,sinsi ...', ARRAY['Türk Edebiyatı','Şiir','Nurcemal Öztürk']::text[], 8.5, '{"poet":"Nurcemal Öztürk","poet_slug":"nurcemal-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eylul-aksami-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-nevher-i-smail-yilmaz-49hcc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir koku her soluduğum nefesteki

ve bir adım

her adımda yaklaştığım

bazen sigaramın dumanında

kimi zaman sararmış bir duvarın; 

bakışlarıma çakıldığı yerde

bir korku yaşadığımız kafeste

bir kanat çırpış

her umudumda yaklaştığım

bazen bir içki kadehinde

kimi zamansa bir sokak lambasının

sarhoşluğumu aydınlattığı yerde

bir kuşku her kalp atışında

yüreğim çarptığında uzlaştığım

bazense sımsıcak kollarımda

kimi zaman duygularımın uçurtmasının

takıldığı telde benimlesin

sen

(03.eylül.1998)', 'bir koku her soluduğum nefesteki ve bir adım her adımda yaklaştığım bazen sigaramın dumanında kimi zaman sararmış bir duvarın;  bakışlarıma ...', ARRAY['Türk Edebiyatı','Şiir','Nevher İsmail Yılmaz']::text[], 8.5, '{"poet":"Nevher İsmail Yılmaz","poet_slug":"nevher-i-smail-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-658-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın Çekip Gitmek...', 'ansizin-cekip-gitmek-ulvi-ziya-3nqcu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölümlerde hep denir:

bu ölüm çok zamansız...

Sevenler; birbirinden,

ayrılırlar apansız...

Beklenmedik bir anda

gündüz geceye döner; 

Kararan semâlarda,

kayıp gider bir yıldız...

Her kor ateş,

düştüğü bir parça yeri yakar...

Kiminin bir evleklik,

kiminin çok yeri var...

Yangınlar; 

nice değer,alır götürür bizden...

Kaybeden,kaybolanı

hüzünle anıp; arar...

Günü gelince biçer

Azrâîl''in tırpanı...

Gök ekin,ya da olgun; 

ayırt etmez işinde...

İnsan ona ta''n etmez

bilir de yaptıranı; 

Çâresiz boyun eğer

geliş ve gidişinde...

Sırlar saklı gündüzün geceye dönüşünde...

Hikmet var her yıldızın parlayıp sönüşünde...', 'Ölümlerde hep denir: bu ölüm çok zamansız... Sevenler; birbirinden, ayrılırlar apansız... Beklenmedik bir anda gündüz geceye döner;  Kararan...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ansizin-cekip-gitmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-omer-karakas-l9hmn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine bir sonbahar akşamı

Sahilde yapayalnız yürüyorum; 

Yavaş yavaş çığlıkları kesiliyor martıların

İnlerine çekiliyorlar, görüyorum; 

Soğukça bir rüzgar üzerime çullanıyor,

Yüreğim titriyor ansızın

Sen yoksun, üşüyorum.

Düşüncelerimde anıların dalgınlığı,

Maziden bir an hiç unutamadığım; 

Hani yüzünde tatlı bir tebessüm,

Gözlerin yıldız yıldız tutamadığım; 

Hatırlıyorum da o ayrılığı.....

Tipi yemiş gibi buz kesiyor bedenim,

Sen yoksun, üşüyorum.

Keskin bir yosun kokusu derken

Bir gemiye dalıyor gözlerim

Sesinde yılların yorgunluğu

Ve bir kayık yakamozlar eşliğinde çekiliyor

Kürekleri kavrayan karartıyı süzerken

Sen yoksun, üşüyorum.

Artık, ne bir karartı, ne bir gölge önümde

Ardımda ise süpürülen ayak izlerim

Ve birden düşüyor düşüncelerim

Denize; meçhul, dik bir yamaçtan.

Üzerlerine atılıyorum, iflahsız

Geçmişi silen dalgaların; 

Yavaş yavaş

Bir soğukluk tırmanıyor tenime,

Zemheri soğuğundan daha acı

Sen yoksun, üşüyorum.

15/10/2005 (Aksaray/İST)', 'Yine bir sonbahar akşamı Sahilde yapayalnız yürüyorum;  Yavaş yavaş çığlıkları kesiliyor martıların İnlerine çekiliyorlar, görüyorum;  Soğuk...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karakaş']::text[], 8.5, '{"poet":"Ömer Karakaş","poet_slug":"omer-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/usuyorum-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezar Taşıma', 'mezar-tasima-i-brahim-ethem-bingul-lkawr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dur, dur yâr gitme daha fazla uzağa

Bundan ötesini çekemem

Vur beni, canlı sokma mezara

Kalbime sensizlik ekemem...

Kavruldum kahır rüzgârlarında yıllarca

Gözlerin var diye sabrımın ufkunda

Gideceksen bir adım daha uzağa

Beni de götür, her nereye olsa da...

İhanet değmedi hayalime, rüyama

Ne kalır ki geriye, benden sen çıkınca

Ayrılığın soğuk eli kapımı çalarsa

Durma, bir şiir yaz yâr mezar taşıma...

www.iebingul.com', 'Dur, dur yâr gitme daha fazla uzağa Bundan ötesini çekemem Vur beni, canlı sokma mezara Kalbime sensizlik ekemem... Kavruldum kahır rüzgârla...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mezar-tasima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur da Şiir Yazar mı? Deme...', 'yagmur-da-siir-yazar-mi-deme-bahtiyar-arslan-t1sgt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yağmur da şiir yazar mı? deme...

hele bir gece olsun

hele gece, kara gözlerini, bir bıraksın buluta

düşsün geceye yağmur

pencerenizin kapısını çalsın, tıp tıp...

yağmurda şiir yazar mı? deme...

bel ki ayrılmak istememişti, çok sevdiği buluttan

ne bileyim, belki kar olarak düşmek istemişti, kardelenin üstüne

bel ki bir çiy damlası, çocuğun yanağında...

yağmurda şiir yazar mı? deme...

hele gece olsun

yağsın pencerenize... tıp tıp...

belki özlemişti bir insanın kokusunu

belki minicik ellerini uzatıyordu sizlere

tutup içeri almanızı bekliyordu belki...

belki sokulup  sıcacık  koynunuza, uyumak istiyordu...

ve de düş görmek

kar kar

çiy çiy... sıcacık  düşler...

yağmur da şiir yazar mı? deme...

hele gece olsun 

düşsün pencerenize...tıp tıp...

hele siz,kulak verin onun sesine

belki üşümeye durmuştu yüreği

belki, kıvrılmıştı pencerenizin kenarına...

ah...ellerinizi verin

ah...gözlerinize alın..

ah...yüreğinize katın...

yağmurda şiir yazar mı? deme...

eğer bir gece 

sizinde pencerenize düşerse yağmur, tıp tıp...

tutup minik ellerinden alın içeriye

sarın sıcacık koynunuza ısıtın, ısıtın düşlerinizle...

ve türkü söyleyin, kulağına içinizden

işte o an, ağlamasına izin verin

verin ki, şiir olup aksın gözlerinizden...

yağmur da şiir yazar mı? deme...', 'yağmur da şiir yazar mı? deme... hele bir gece olsun hele gece, kara gözlerini, bir bıraksın buluta düşsün geceye yağmur pencerenizin kapısı...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yagmur-da-siir-yazar-mi-deme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim...', 'gozlerim-ulvi-ziya-yrcn9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim dargın bakar âlemin oyununa...

Bu yüzden biraz donuk,hayretler içindedir...

Oklar fırlatmak ister Âdem''in hâinine

Nazarları delici,devirir biçimdedir...

Haksızlık karşısında hemen şişer,kanlanır

Hatır gönül gözetmez gaddar kardeşi olsa...

İncinmiş duyguları birdenbire canlanır

Gaspedene saldırır nerde bir hak kaybolsa...

Mazlûmu okşar gibi; rahmet nûruyla bakar...

Zâlime alevli ok,saplanır onu yakar...

Kalleşe,düzenbaza ölümü hatırlatır; 

İyiye hoşgörülü,ulvî ziyâlar çıkar...', 'Gözlerim dargın bakar âlemin oyununa... Bu yüzden biraz donuk,hayretler içindedir... Oklar fırlatmak ister Âdem''in hâinine Nazarları delici,...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçekleri Ve Gerçekler', 'kir-cicekleri-ve-gercekler-ulas-guleviz-9ymdb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Milyonlarca  kır  çiçeği, sanki  özgürlük  yuvaları  gibi, rengarenk  ve  bulutlara  yakınlığıyla  tanınırlar.

Bir  insanın, “masumluğunu  ve  temizliğini” anlatır  sanki  güzelliği.

Hayata  karşı  hep  birlikte  hareket  eder  gibi  devam  ettirirler  yaşamlarını. Ve  aynı  yöne  bakarak  karşılarlar  günü.

Bu  yaşamak  onlara  güzel mi  bilemiyorum.

Ama  o  topluluğu  görmek, biz  insanlara  huzur, mutluluk  ve  aşk  getirir.

Bu  zalim  felek, onların  hayatından da  çok  şeyler  siler, götürür. 

YANİ,

Vazomda  bir  demet  kır  çiçeği,

veya  gözbebeklerini  görmek.

Vazomda  üzgün  güller, 

yada, sevdamı  senden  gizlemek.

Yada  güzel  bir  hayatı  sonlandırarak, 

yine  güzel  bir  birliktelik  sağlamak. 

Tutmak  kır  çiçeklerinin  belinden 

ve  kopartmak  hayattan, veya  beni  senden.

Yada  kopartılan  çiçekleri  sulamak, anlamsız.', 'Milyonlarca  kır  çiçeği, sanki  özgürlük  yuvaları  gibi, rengarenk  ve  bulutlara  yakınlığıyla  tanınırlar. Bir  insanın, “masumluğunu  v...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kir-cicekleri-ve-gercekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayağa Kalkmış Rubâî...', 'ayaga-kalkmis-rub-ulvi-ziya-4b3su', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karnı geniş şövalyeler

dârât u sâmânını üleşti...

Zorbalar arttıkça arttı

üç idi

sen say ki onüçleşti...

Her babayiğit,

tuttuğu yerinden,

yedi tüketti yurdu...

Vatanseveri

vatan hâininden ayırmak

çok güçleşti...', 'Karnı geniş şövalyeler dârât u sâmânını üleşti... Zorbalar arttıkça arttı üç idi sen say ki onüçleşti... Her babayiğit, tuttuğu yerinden, ye...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayaga-kalkmis-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Şehr-i Ramazan', 'ey-sehr-i-ramazan-bekir-oguzbasaran-k0b2g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göklerden sessizce gelen kutsal bir fermandır,

Oruçla güzelleşen gönüllere sultandır,

Allah’tan kullarına en güzel armağandır,

Hayâtımıza hoş geldin ey şehr-i Ramazan.

Nefsimizin beton duvarlarını kırandır,

Bütün ayların içinde en mübârek olandır,

Yoksulları giydiren, açları doyurandır,

Hayâtımıza hoş geldin ey şehr-i Ramazan.

Şeytan elçilerini zincirlere vurandır,

Bu ayda tüm müminler daha bir müslümandır,

Hatimle kılınan namaz, okunan Kur’ân’dır,

Hayâtımıza hoş geldin ey şehr-i Ramazan.

Merhametin somut hâle geldiği zamandır,

Câmiler dolup taşar, bereket çağlayandır,

Minâre minâre mahya, mahyalar nurdandır,

Hayâtımıza hoş geldin ey şehr-i Ramazan.

Af ve mağfiret ayı, bu bir mâh-ı gufrandır,

Sabır eğitimiyle dertlilere dermandır,

Yeryüzüne huzûru cömertçe dağıtandır,

Hayâtımıza hoş geldin ey şehr-i Ramazan.', 'Göklerden sessizce gelen kutsal bir fermandır, Oruçla güzelleşen gönüllere sultandır, Allah’tan kullarına en güzel armağandır, Hayâtımıza ho...', ARRAY['Türk Edebiyatı','Şiir','Bekir Oğuzbaşaran']::text[], 8.5, '{"poet":"Bekir Oğuzbaşaran","poet_slug":"bekir-oguzbasaran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ey-sehr-i-ramazan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazdım', 'yazdim-bekir-oguzbasaran-q92v2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdiğimi âlem bilsin

Seni duraklara yazdım

Bütün başaklar eğilsin

Seni oraklara yazdım

Börtü böcek ezberlesin

Gece gündüz benimlesin

Rüzgârlar seni söylesin

Seni yapraklara yazdım

Kalbime giresin diye

Aşkımı göresin diye

Sen beni sevesin diye

Seni mızraklara yazdım

Kimse görmedim demesin

Adın dalga dalga gitsin

Her kumsalda senin ismin

Seni topraklara yazdım

Beni sevgiyle an diye

Tüm bulutlar yuvan diye

Göklerde dalgalan diye

Seni bayraklara yazdım', 'Sevdiğimi âlem bilsin Seni duraklara yazdım Bütün başaklar eğilsin Seni oraklara yazdım Börtü böcek ezberlesin Gece gündüz benimlesin Rüzgâr...', ARRAY['Türk Edebiyatı','Şiir','Bekir Oğuzbaşaran']::text[], 8.5, '{"poet":"Bekir Oğuzbaşaran","poet_slug":"bekir-oguzbasaran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yazdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Îmân...', 'm-n-ulvi-ziya-55aig', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sırat köprüsünde gibi yürüdük dünyâ yüzünde...

Hep dertlendik,mihnet çektik; gecesinde,gündüzünde...

Hardal tanesi kadar değil,dağ kadar îmânımız; 

Îmân kurtuluşa delil,Hz.Peygamberin sözünde...', 'Sırat köprüsünde gibi yürüdük dünyâ yüzünde... Hep dertlendik,mihnet çektik; gecesinde,gündüzünde... Hardal tanesi kadar değil,dağ kadar îmâ...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iman-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-bekir-oguzbasaran-1v4gt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şâirdir o insan ki, yaşar hâtıralarla

Alışverişi yoktur makam ve paralarla

Şâir ona derler ki, dilinde kelimeler

“Beni de sürüne kat” diye durmadan meler

Dili dantel gibi lif lif işleyendir şâir

Rûhu en mahrem yerinde dişleyendir şâir

İnsanları düşünmektir bu işin temeli

İnsanları mutlu görmek onun tek emeli

Yüreğinde herkese yetecek sevgi vardır

Şâir gönlü kocaman okyanus kadardır

Aşk ateşini yakmaktır şâirin görevi

Hasta kalplere bakmaktır şâirin görevi

Coşku potasında pişmeden söz şiir olmaz

Duygu ve düşünceden yoksun öz/şiir olmaz

Şiir, haksıza karşı haykırmak değil midir? 

Esâret zincirlerini kırmak değil midir? 

Şiir, sözü kıvâmında söylemek sanatı

Ustasının elinde şahlanır şiir atı

Yalnız yazı yazmakla nâsir olur mu? 

Allah nasip etmeyince şâir olunur mu? 

“Varsın seni ömrünce azâbın kolu sarsın

Şâir! Sen üzüldükçe ve öldükçe yaşarsın! ”', 'Şâirdir o insan ki, yaşar hâtıralarla Alışverişi yoktur makam ve paralarla Şâir ona derler ki, dilinde kelimeler “Beni de sürüne kat” diye d...', ARRAY['Türk Edebiyatı','Şiir','Bekir Oğuzbaşaran']::text[], 8.5, '{"poet":"Bekir Oğuzbaşaran","poet_slug":"bekir-oguzbasaran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sair-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıfırla Sonsuz Arasında', 'sifirla-sonsuz-arasinda-bekir-oguzbasaran-418bq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Merhum Aydın Baydar’a...

Kulağa ezan okunuyor

Bebek-ihtiyar arasında

Ömür  kumaşı dokunuyor

Doğumla mezar arasında

Vazgeçilemeyecek ne var? 

Doğmakla ölmek iki duvar

Ömrümüz ağlamakla başlar

Sürer yokla var arasında

Hayâtın sırrını kim çözmüş? 

Sükût altın ise söz gümüş

Bin bir çeşit düşünce, görüş

Bütün insanlar arasında

Kimi sevmiş, kimi sevilen

Kimi övmüş, kimi övülen

Kimi dövmüş, kimi dövülen

Mutsuz, bahtiyâr arasında

Dünyâ bir han, konan göçecek

Herkes ektiğini biçecek

Ne insan ebedî, ne böcek

Sonsuz nurla nâr arasında...

Kayseri, 2 Nisan 2002 Salı', '-Merhum Aydın Baydar’a... Kulağa ezan okunuyor Bebek-ihtiyar arasında Ömür  kumaşı dokunuyor Doğumla mezar arasında Vazgeçilemeyecek ne var?...', ARRAY['Türk Edebiyatı','Şiir','Bekir Oğuzbaşaran']::text[], 8.5, '{"poet":"Bekir Oğuzbaşaran","poet_slug":"bekir-oguzbasaran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sifirla-sonsuz-arasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selâm Olsun', 'sel-m-olsun-bekir-oguzbasaran-s6b80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yuvasına helâl rızık götürenlere,

Çalışarak alnının terini silenlere,

Öksüzü, yetimi görüp gözetenlere,

Yoksulu düşünenlere,

Aza kanaat edenlere,

Selâm olsun...

Ülkesini, insanını kendisinden çok düşünenlere,

İyilik, güzellik yolunda beyin yoranlara,

Elle, daktiloyla, bilgisayarla duygu ve düşüncelerini

İnsanlara cömertçe sunan kalem erbâbına,

Selâm olsun...

Namusuyla çalışıp kazananlara,

Haklıyı, haksızı ayıranlara,

İyiye, güzele, yararlıya destek verenlere,

Feragat ve fedakârlık sahibi olanlara,

Selâm olsun...

Hastalara kol – kanat gerenlere,

Güçsüzlere güç verenlere,

Dertlilere devâ arayanlara,

Şifâ dağıtanlara,

Tesellî dağıtanlara,

Doktorlara, hemşirelere, hastabakıcılara,

Selâm olsun...

Çocuklarımızı eğiten bahçıvanlara,

Onların kahrına katlanan insanlara,

Mum gibi eriyerek çevrelerini aydınlatanlara,

Selâm olsun...

Çok okuyan, çok yazanlara,

Bilim yolunda yorulanlara,

Sanat uğrunda yol alanlara,

Bize manevî zenginlikler sunanlara,

Selâm olsun...

Çok üretip az yiyenlere,

Çok dinleyip az diyenlere,

Çok verip az alanlara,

Sabreden fakirlere,

Şükreden zenginlere,

Hepsine, hepsine

Bir ömür boyu

Kucak dolusu

Gönül dolusu

Selâm olsun...

Selâm olsun...', 'Yuvasına helâl rızık götürenlere, Çalışarak alnının terini silenlere, Öksüzü, yetimi görüp gözetenlere, Yoksulu düşünenlere, Aza kanaat eden...', ARRAY['Türk Edebiyatı','Şiir','Bekir Oğuzbaşaran']::text[], 8.5, '{"poet":"Bekir Oğuzbaşaran","poet_slug":"bekir-oguzbasaran","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/selam-olsun-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakış Açım Kim? Eşim...', 'bakis-acim-kim-esim-alper-kuruk-st764', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiirim sana ilk el

İlk duyanım da sensin,

Şiirim sözde güzel

Sen ki özde güzelsin.

Eğer şiir güzelse 

Daha güzelleşirsin,

Bir de yüzün gülerse

Kendin şiirleşirsin.

Şiirde ölçüm sensin

Sensin benim kâfiyem,

İlham isterse gelsin...

Sen bakışta zâviyem...', 'Şiirim sana ilk el İlk duyanım da sensin, Şiirim sözde güzel Sen ki özde güzelsin. Eğer şiir güzelse  Daha güzelleşirsin, Bir de yüzün güler...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bakis-acim-kim-esim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Kardaş...!', 'ey-kardas-ulvi-ziya-desvl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hadisler yol gösterir,fenâdan uzaklaşırız...

Dalıp îmân deryâsına,arınıp,aklaşırız...

Allah ve Resûlüne âşık olmuş mü''minleriz; 

Bir adım yaklaşana birkaç adım yaklaşırız...', 'Hadisler yol gösterir,fenâdan uzaklaşırız... Dalıp îmân deryâsına,arınıp,aklaşırız... Allah ve Resûlüne âşık olmuş mü''minleriz;  Bir adım ya...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ey-kardas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Uymuş', 'ne-guzel-uymus-bekir-oguzbasaran-1noy6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '- Levnî’ye-

Güzellere naz

Dervişe niyaz

Mümine namaz

Ne güzel uymuş

	

Dâvûd’a sadâ

Bilâl’e nidâ

Mecnun’a sevdâ

Ne güzel uymuş

	

Zengine şükür

Fakire sabır

Ölüye kabir

Ne güzel uymuş

	

Âlime bilgi

Tâlibe ilgi

Zamâna silgi

Ne güzel uymuş

		

Süvariye at

Kuşlara kanat

Cennet’e Sırat

Ne güzel uymuş

	

Şâire şiir

Nâsire fikir

Tekkeye zikir

Ne güzel uymuş

	

Kâğıda kalem

Hatibe kelâm

İnsana selâm

Ne güzel uymuş', '- Levnî’ye- Güzellere naz Dervişe niyaz Mümine namaz Ne güzel uymuş 	 Dâvûd’a sadâ Bilâl’e nidâ Mecnun’a sevdâ Ne güzel uymuş 	 Zengine şükü...', ARRAY['Türk Edebiyatı','Şiir','Bekir Oğuzbaşaran']::text[], 8.5, '{"poet":"Bekir Oğuzbaşaran","poet_slug":"bekir-oguzbasaran","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ne-guzel-uymus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahi Sen Kimsin', 'sahi-sen-kimsin-hasan-gorgu-0w5mo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaybettiğimde geceyi gün ışırken

Olmayan yatağımdaki yastığımsın

Titrerken mum ışığının sönüklüğünde

Üstüme örtemediğim yorganımsın

Hayallerimin sokaklarında İstanbul’un

Didişirken yazgılarıyla insanlarım

Yazmaya başlıyamadığım şiirim 

Henüz okuyamadığım romanımsın

Dalarken kavgasına rüyalarımın 

Alacakaranlık kuşaklarında

Çekemediğim tabancamın şarjörü

Patlamayan namlumun kurşunusun

Sarı yapraklar gibi düşerken

Hazan yağmurlarının damlaları 

Gözlerimden aşağı süzemediğim

Akıtamadığım gözyaşlarımsın

           

Neden hala tanımıyorum seni

Sahi sen kimsin

Ne zaman geleceksin

Yoksa sen 

Son nefesimi bekleyen feleğim misin

Öyle de olsan yine gel

Bu hasret bitsin

Bu beden gitsin

Sen yağmurlarla gelen

Rüzgarlarla giden

Hayallerimdeki  sevgilimsin

17.10.2005

Saat  13,40', 'Kaybettiğimde geceyi gün ışırken Olmayan yatağımdaki yastığımsın Titrerken mum ışığının sönüklüğünde Üstüme örtemediğim yorganımsın Hayaller...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sahi-sen-kimsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk', 'terk-sair-sersenis-ype0v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bozuk manasıyla aşkın

kırık camlarından bakıyoruz..

gör ki bitmedi,

ama ayrılıyoruz..! 

Bedenimden dokunuşların düşüyor

uzak yerlere bırakıyoruz gözlerimizi

kirpiklerim ıslanıyor.

Ağlıyorsun,

gidiyorum..

Terkediyoruz birbirimizi...', 'Bozuk manasıyla aşkın kırık camlarından bakıyoruz.. gör ki bitmedi, ama ayrılıyoruz..!  Bedenimden dokunuşların düşüyor uzak yerlere bırakıy...', ARRAY['Türk Edebiyatı','Şiir','Şair Serseniş']::text[], 8.5, '{"poet":"Şair Serseniş","poet_slug":"sair-sersenis","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/terk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttuk', 'unuttuk-devran-demir-7nctq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hava bozdu 

bulutlar ağlamaya durdu

ağlayın bulutlar ağlayın

ağlayın duru duru

ağlayın bulutlar ağlayın 

ağlayın bari siz

ağlayın bulutlar ağlayın

ağlayın hiç değilse siz

ağlayın bulutlar ağlayın 

ağlayın uzun sessiz

ağlayın bulutlar ağlayın

ağlamayı bile artık

unuttuk çünkü biz

2005', 'hava bozdu  bulutlar ağlamaya durdu ağlayın bulutlar ağlayın ağlayın duru duru ağlayın bulutlar ağlayın  ağlayın bari siz ağlayın bulutlar a...', ARRAY['Türk Edebiyatı','Şiir','Devran Demir']::text[], 8.5, '{"poet":"Devran Demir","poet_slug":"devran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unuttuk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Ve Ten', 'can-ve-ten-alper-kuruk-eg5uo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Can tende mahpus değil

Tense can için vardır,

Ten cana eder meyil

Ten,can kadar kutsaldır.

Can ten ile bağlanır

Canı tene eder yâr

Ki o fâni dünyadır

Burada ayrılırlar.

İkisi tekten çıkar

Bir olur mu hiç iki? 

Tene dünyada yer var

Can âhirette bâki.', 'Can tende mahpus değil Tense can için vardır, Ten cana eder meyil Ten,can kadar kutsaldır. Can ten ile bağlanır Canı tene eder yâr Ki o fâni...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/can-ve-ten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Tadında', 'ask-tadinda-sair-yaman-hijoq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yanık kokusu peyda olur

Her biten günün ardından

Yanar yüreğim, geriye külü kalır

Her akşam aşkın yanık tadından...

Çiğ damlası gibi aklar yağar saçıma

Zifir karalar gelir, çöker bahtıma

Küllenmiş hatıralar düşer şansıma

Her gece yanan aşkın narından...

Buram buram kokun gelir, dayanır

Her taraf bir an gülle bezenir

Usulca kopup gelen, hazin bir esintidir

Her seher vakti aşkın bağrından...', 'Bir yanık kokusu peyda olur Her biten günün ardından Yanar yüreğim, geriye külü kalır Her akşam aşkın yanık tadından... Çiğ damlası gibi akl...', ARRAY['Türk Edebiyatı','Şiir','Şair Yaman']::text[], 8.5, '{"poet":"Şair Yaman","poet_slug":"sair-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-tadinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik', 'yitik-devran-demir-s9px7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aşkın arzularla 

sevginin ilgilerle 

karıştığı bir çağda

aşk ve sevgi

iki yitik çocuktur hep 

annelerini arayan

gözyaşlarıyla', 'aşkın arzularla  sevginin ilgilerle  karıştığı bir çağda aşk ve sevgi iki yitik çocuktur hep  annelerini arayan gözyaşlarıyla...', ARRAY['Türk Edebiyatı','Şiir','Devran Demir']::text[], 8.5, '{"poet":"Devran Demir","poet_slug":"devran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yitik-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaş', 'kas-alper-kuruk-517pe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğa sanki bir nakkaş

Güzel eseri bu KAŞ.

Dantel dantel oyulmuş

MEİS seyre koyulmuş...

Dağlar ağaçca fakir

Deniz oldukça bâkir...

Mayo ıslak,dingin baş

Denizle bütün uğraş.

Manzara hoş çak flaş

Gel kendin gör,kendin şaş...

Balık taze ve bol aş

Hayat sade ve yavaş.

Sen de buraya ulaş

İşte:şirin,küçük KAŞ...', 'Doğa sanki bir nakkaş Güzel eseri bu KAŞ. Dantel dantel oyulmuş MEİS seyre koyulmuş... Dağlar ağaçca fakir Deniz oldukça bâkir... Mayo ıslak...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fethiye', 'fethiye-alper-kuruk-kqejx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzelliğin timsalisin FETHİYE

Sana lâyık bu yazılan methiye.

Yıllar boyu güzelliğini niye 

Sakladın da şimdi ettin aşikâr? 

Yeşil orman,mavi denizle ikiz

ÇALIŞ,HİSARÖNÜ ve ÖLÜ DENİZ...

Mercan,Akya,Lagos ile yüzeriz

Bey Dağları tepesi bembeyaz kar.

Karşındaki bekçin:ada ŞÖVALYE 

Bağrında doğayla tarih elele,

Yazın yaylalara,kışın sahile

Fethiye''im göçer,iner de çıkar.

Kucaklaşmış orda denizle yayla

O güzelim el değmemiş FARALYA,

Güneş yarışıyor râkibi ayla

İkisi gün - gece denize bakar.

Kaya mezarları ve KAYA KÖYÜ,

Çözülmemiş hâlâ sendeki büyü,

Kitaplar yazmadı böyle öyküyü 

Taşın ve toptağın Kral''a mezar.

Güzelliklerin dünyaya armağan,

Her koyun bir dantel,her koyun liman

Öpüşüyor sende Umman - Asûman

Sevgi dolu yerde kalır mı efkâr?', 'Güzelliğin timsalisin FETHİYE Sana lâyık bu yazılan methiye. Yıllar boyu güzelliğini niye  Sakladın da şimdi ettin aşikâr?  Yeşil orman,mavi...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/fethiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak İzleri Üstünde', 'ayak-i-zleri-ustunde-cumhur-boratav-ob74q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hissettiğim zaman 

içindeki hissinin ne olduğunu 

bahçen dikene dönüşüyor, 

kardan arta kalan çamura 

-oysa seni seviyorum 

derken sevdiğin sadece sesin

aynanın karşısında 

hiç kırılmıyorrmuş gibi ışığın- 

farkında olmadığın renkler veriyorsun 

çarpıp bölünerek 

kendi keskinliğinde kırıklığının 

hissettiğimde renklerini 

hissediyorum kırıklığını 

kumsalına varıyorsun 

camlaşamayan her kum taneciği gibi

her yerde 

senin üstünde biçimlenmiş 

ayak izleri 

hissettiğim zaman 

ne olduğunu 

bahçen öfkeye dönüşüyor 

üstünde ayak izleri', 'hissettiğim zaman  içindeki hissinin ne olduğunu  bahçen dikene dönüşüyor,  kardan arta kalan çamura  -oysa seni seviyorum  derken sevdiğin ...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ayak-izleri-ustunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usandım', 'usandim-zeliha-ural-40iio', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görmedim dünyada gülen bir  yüzü

İçimde kavruldu hasretin hüznü

Yalan oldu her şey kalmadı gayrı

Vay ben öleydim, ne idi işim

Selam olsun dünyada benden kalana

Gelmem birdaha tövbeler sana

Hani senin olan evladın ana

Canımdan usandım yardan usandım

Bir omuz aradım teselli için

Kor oldu yüreğim yandı içim

Selam olsun sizlere ey dostum eşim 

Yalandan usandım tenden usandım

Uğramam artık elineze ben 

Almam türkünüzü dilimize ben

Seni soranlara  ne diyeyim ben 

Hayaldan usandım candan usandım', 'Görmedim dünyada gülen bir  yüzü İçimde kavruldu hasretin hüznü Yalan oldu her şey kalmadı gayrı Vay ben öleydim, ne idi işim Selam olsun dü...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Ural']::text[], 8.5, '{"poet":"Zeliha Ural","poet_slug":"zeliha-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/usandim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradaki Uzaklık', 'aradaki-uzaklik-alper-kuruk-sekqm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arada olsa da bunca mesafe 

Gidip gelmeyince gönül boş kalır,

Üzgü duymayınız hiçbir esefe

Öyle sağlam,öyle geniş bu kefe

Çok şey taşır,alır, yine boş kalır

Gönüller avunur, böyle hoş kalır...', 'Arada olsa da bunca mesafe  Gidip gelmeyince gönül boş kalır, Üzgü duymayınız hiçbir esefe Öyle sağlam,öyle geniş bu kefe Çok şey taşır,alır...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aradaki-uzaklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yürek Sızım', 'sen-yurek-sizim-zeliha-ural-rbh36', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gece rüyamda kokladım seni

Miski amberdi dokunduğum tenin 

Adını diyemediğim, 

Can diyemedim ey yürek sızım

Sıkıca bağrıma bastım.

Bir gelincik misali,

Boyun bükmüştün sen bana

Kaderdi  bil yürek sızım

Almayın onu benden,

Almayın kollarımdan

O can dediğim candan 

Ayırmayın diyordum gel yürek sızım

Seni aramak boşuna o diyar ilinde

Bülbüle koştum kanadı yaram 

Feryadı figanı duymadı bile 

Duymadı ey yürek sızım', 'Dün gece rüyamda kokladım seni Miski amberdi dokunduğum tenin  Adını diyemediğim,  Can diyemedim ey yürek sızım Sıkıca bağrıma bastım. Bir g...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Ural']::text[], 8.5, '{"poet":"Zeliha Ural","poet_slug":"zeliha-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-yurek-sizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sönse de Yeşil Kandiller', 'sonse-de-yesil-kandiller-hulya-arikan-vjzg3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hangimize vurmadı ki gecenin ayazı

Karanlığın inişi hangimizi gömmedi ki yalnızlığa

Nergisler, nilüferler, papatyalar süslerken düşlerimizi

Bulmadık mı kupkuru çöllerde kendimizi

Yaksak ta sevda limanlarını

Fırtınalar ortasında kalsak ta çaresiz… yapayalnız…

Bebe gibi besler büyütürüz,

Hasreti bir sır gibi gönlümüzde…

Kurusa da hayat pınarımız…

Sönse de yeşil kandiller

Yorgun düşse de çırpınan yüreğimiz

Sensizliği yaşar… sensizliği yaşatırız…

Bir dal çiçeğini beklerken toprağımızda…', 'Hangimize vurmadı ki gecenin ayazı Karanlığın inişi hangimizi gömmedi ki yalnızlığa Nergisler, nilüferler, papatyalar süslerken düşlerimizi ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arıkan']::text[], 8.5, '{"poet":"Hülya Arıkan","poet_slug":"hulya-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sonse-de-yesil-kandiller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mizan Var', 'mizan-var-mehmet-ayhan-gunaydin-piwd3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'MİZAN VAR

Ey yarını unutup,

Bu günü yaşayanlar.

Fakirin hakkını yutup

Ekmeğine, 

Aşına, 

Lokmasına, bile göz koyanlar.

Ey tüyü bitmemiş yetimin

Haklarını çalanlar.

Bilin ki çok büyük yanlıştasınız

Gün gelir hesap sorulur, anlayasınız.

Gününüzü gün edip

Oyunda oynaştasınız.

Har vurup harman savurup

Yan gelip yatmaktasınız.

Biliniz bu devran

Hep böyle gitmeyecek.

En sonunda, en sonunda

Hesap günü gelecek.

Yaşasın, ilahi adalet,

Yaşasın ki ölüm var.

Bu dünyada olmazsa hesap,

Ötekinde mizan var.

M. Ayhan Günaydın.

  28 Temmuz 2005

         Ankara', 'MİZAN VAR Ey yarını unutup, Bu günü yaşayanlar. Fakirin hakkını yutup Ekmeğine,  Aşına,  Lokmasına, bile göz koyanlar. Ey tüyü bitmemiş yeti...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mizan-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Akay''a Dair', 'bir-akay-a-dair-arzu-aytac-miduj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç farkında olmadın,

Fevkinde de.

Eminim ki ''eyvah''larını odalara sığdıramadığın oldu

Hem sebeptin  hem sonuç

Hem hırsız hem evsahibi.

Hey benim memleket kartvizitim,

Sen istifa ettiğinde yerine ismi yazılacak bir kartvizit sahibi yok biliyorsun.

Açıp tombul ellerinin parmaklarını

Sayar mısın yangın halkana değen kaç ömür cızırdadı? 

Ben seçemedim seni,her çocuğun gözlerinin kime benzeyeceğini seçemediği gibi.

Sen... fevkinde olmadan seçtin.

İlla ki dolu cepheli bir bardaktan yana olmak gerekiyorsa

Ey memleket kartvizitim

Hayatta yalnız bu kız için halkanın ateşini kıstın

Ama yine kıpkırmızı yanık atalık tarafım...', 'Hiç farkında olmadın, Fevkinde de. Eminim ki ''eyvah''larını odalara sığdıramadığın oldu Hem sebeptin  hem sonuç Hem hırsız hem evsahibi. Hey ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Aytaç']::text[], 8.5, '{"poet":"Arzu Aytaç","poet_slug":"arzu-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-akay-a-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-adnan-durdagi-okk6c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülen gözlerinde, bir dünya görüyorum

Seninle yeniden,geçmişe yürüyorum

Bir canım var sen iste

Al sana veriyorum

Yeşeren gençliğim

Tomurcuk gülüm

Nar tanem

Bir el verdin bir can aldın kör ettin

Bir kez baktın beni yaktın nar ettin

Bir gülüşle kendini bana yar ettin

Gündüz günüm

Gece ayım

Nur tanem

Sen benim sonbaharımda, pastırma yazım

Kış mevsiminde Ağustos’um

Yaz''da ayazım

Dertli dertli çalan 

İnleyen sazım

Gördüğüm rüyam

Toz pembe dünyam

Yar tanem 

Gönlümün tadı tuzu, biberi balı

Gül veren ağacı, yaprağı dalı

Bağladın Adnan’ı ettin sevdalı

Soluduğum havam

Aldığım gıdam

Bir tanem! 

Aşkımmm...', 'Gülen gözlerinde, bir dünya görüyorum Seninle yeniden,geçmişe yürüyorum Bir canım var sen iste Al sana veriyorum Yeşeren gençliğim Tomurcuk ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durdağı']::text[], 8.5, '{"poet":"Adnan Durdağı","poet_slug":"adnan-durdagi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/askim-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüm Gözlüm', 'uzum-gozlum-muhsin-aktas-7uhbr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zamansız bir bağ bozumunda çıktın hayatımdan

Gitmeseydin üzüm gözlüm

Bozulmaz,pörsümez,koruk kalmazdın

Kalsaydın seni saran kollarımda

Olgunlaşır,nemlenir,tatlanırdın

Beslenirdin can damarımdan

İçimde sen varsın

Damarlarımda,kökümü saran toprakta

Seni toplayacaklar bedenimden

Sonraki bağbozumlarında..', 'Zamansız bir bağ bozumunda çıktın hayatımdan Gitmeseydin üzüm gözlüm Bozulmaz,pörsümez,koruk kalmazdın Kalsaydın seni saran kollarımda Olgun...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uzum-gozlum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-mehmet-ozcan-odhjw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'iSTANBUL

Her hücremde seni hissediyorum,

Yine seni yaşıyorum İstanbul’um.

Geceye bürünmüş, nazlı bir gelin gibi,

Her tarafın, kopkoyu bir aydınlık,

Deli saçması gündüzlerden uzak,

Taşına, toprağına, ilahi bir nur yağar,

Güneşin ilk ışıklarıyla kirlenene kadar.

Gündüzleri İstanbul yoktur akıllarda,

Herkes kendi kavgasında,

Tezgahlar, dümenler ve insanlar,

Tek tip kurulmuş beyinler,

Yaşıyorum, sanılan hayatlar.

Gündüzleri horlanır bu yer,

Kullanılır, sömürülür kirletilir,

Kanı emilir vahşice,

Her bir yanı kırılır dökülür talan edilir,

Çiğnenir öldürülür İstanbul’um, öldürülür,

İstanbul geceleri yaşanır,

Geceleri yaşar İstanbul,

Geceleri hayat bulur,

En kuytu köşesine kadar ağır ağır,

Kan nüfus eder, İstanbul’un,

Geceleri huzur bulur, nefes alır,

Can gelir canına, derin bir oh çeker.

İstanbul geceleri yaşanır,

Geceleri dertleşilir onunla.

Gecelerim İstanbul ve ben,

Sarmaş dolaş gezinirken,

Doyasıya, çılgınca yaşamak,

Sessiz, sakin asude bir derinlikte...

Katıksız solurken benliğimde,

Bir kaç sarhoş paylaşmak istiyor,

Gecelerimi ve seni,

Ayrılır mıyım ben senden hiç,

İmkan mı var, ne mümkün,

Gün doğuyor yavaş yavaş İstanbul’um,

Bak yumdum gözlerimi,

Hadi sende yum! ...', 'iSTANBUL Her hücremde seni hissediyorum, Yine seni yaşıyorum İstanbul’um. Geceye bürünmüş, nazlı bir gelin gibi, Her tarafın, kopkoyu bir ay...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/istanbul-343-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu Devrimine Merhaba', 'anadolu-devrimine-merhaba-vedat-koparan-yfuvm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hey duydunuz mu? 

Zamanın süzgecinde

Cumhuriyet gelmiş

Kutlarız her 29 Ekim’de 

Bir sunucu –bir şair men radyoda 

Kimse demez bu ne diye 

Açılışı yapar Mehter marşıyla 

Tezatlıklar ülkesinde 

Ne akıl ne izan 

Cumhuriyet 

Gel(mi) ş kime ne

Osmanlı kafası 

İnmiş süngüsü 

Hala sürer izini

Burjuva desen çarpık burjuva 

Gelmemiş ki iç dinamiğiyle 

Görgüsüz öngörüsüz ejderha

Kapı kulu olmuş Emperyaliste

Gücü ele geçirince yerle bir edilir tüm değerler 

Kutlanır göstermelik bayramlar seyranlar 

Her şey sistemin bekası içindir vurulur kelleler

Uyu babam uyu avun dur meydanda heykeli

Sızlasın Ankara’nın anıt kabri çatlasın kalbi

Özgürlük adına akan kandan sızlasın tarihi …

-Tüm  takkiyeciler bu kaleyi de katlettiniz 

Namazını kılın gözünüz aydın olsun

Bilesiniz ki gazanız mübarek olmayacak-

Vedat Koparan  17.10.2005', 'Hey duydunuz mu?  Zamanın süzgecinde Cumhuriyet gelmiş Kutlarız her 29 Ekim’de  Bir sunucu –bir şair men radyoda  Kimse demez bu ne diye  Aç...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/anadolu-devrimine-merhaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Seyyahı', 'sevgi-seyyahi-mehmet-ozcan-nortw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gezdim durdum, şu koskoca alemi,

Bir eşsiz duygunun esiri oldum,

Garip aşıkların derdi bende mi? 

Ben mi, aşıkların garibi oldum.

Sevilmeden sevdim, gülmeden güldüm,

Duygulara ben bir yabancı oldum,

Aradım sonunda kendimi buldum

Çileli hayatım, güllerle doldu.

Dağları aştım, ırmaklar geçtim,

Yolumu bulmadan, yollara düştüm,

Düşenle düşerek, koşanla koştum,

Yitik sevgilerin seyyahı oldum.', 'Gezdim durdum, şu koskoca alemi, Bir eşsiz duygunun esiri oldum, Garip aşıkların derdi bende mi?  Ben mi, aşıkların garibi oldum. Sevilmeden...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgi-seyyahi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a', 'i-stanbul-a-mehmet-ozcan-ykvie', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Herkes gidiyor da bende giderim

Hem oraya gider kibar olurum

Kafama göre bir iş bulurum

İstanbul’a gideceğim orası büyük şehir

Çok para kazanır zengin olurum

O paraya koyun kuzu alırım

Şöyle yaylımlara doğru salarım

İstanbul’a gideceğim orası büyük şehir

Köyde herkes bana itibar eder

İstanbullu olmanın havası yeter

Buralarda iş yok hayat çok beter

İstanbul’a gideceğim orası büyük şehir

Hem altın imiş taşı toprağı

Topladın mı buradan tası tarağı

Katık ederim ekmeğime çorağı

İstanbul’a gideceğim orası büyük şehir

Bulurum elbet kalacak bir hemşehri

Birazda akıttın mı alnından teri

Ne iş olsa yaparım hiç durmam geri

İstanbul’a gideceğim orası büyük şehir

Helallik aldım yollara çıktım

Ne uzun yol imiş gitmekten bıktım

Geldik sonunda şöyle bir baktım

Kucağını aç İstanbul ben geldim

Bu kadar büyük olduğunu sanmazdım

Büyükçe olmasaydın zaten gelmezdim

Asker arkadaşımı da bir bulsaydım

Kucağını aç İstanbul ben geldim

Parklarda yattım çektim zahmeti

İki gün aradım buldum Ahmet’i

Birde iş bulursam sen gör rahmeti

Kucağını aç İstanbul ben geldim

Çarşıda iş buldum hamallık ediyorum

Sırtımda yük nere deseler gidiyorum

Her gün patrona hava parası veriyorum

Kucağını aç İstanbul ben geldim

Taşın toprağın altın dediler

Çokça saf görüp beni yediler

Halime gülüyor sokaktaki kediler

Adın gibi değilmişsin İstanbul.

Asker arkadaşım kovdu kibarca

Zalim felek gül yüzüme bir parça

Ailem köyde herhalde naçarca

Adın gibi değilmişsin İstanbul.

Üç gündür elimde yoktur beş para

Bir name yazmışım bizim diyara

Halim harap düşünüyorum kara kara

Adın gibi değilmişsin İstanbul.

Büyük şehir dedik geldik gurbete

Kepçemizi daldırdık ki şerbete

Acı sirke çıktı bizim kısmete

Adın gibi değilmişsin İstanbul.

Üç beş kuruşu bana çok mu gördün

Halime bakmadan defterim dürdün

Hep ayak altında yerlerde sürdün

Adın gibi değilmişsin İstanbul. 

İstanbul’a geldim günah mı ettim

Ardından geleceğim derken ben bittim

Herkesin elinde ezildim gittim

Adın gibi değilmişsin İstanbul.

Bizim köyü görsen sana beş çeker

Gürültün çok,havan kirli,suların beter

Artık bu garibe ettiğin yeter

Adın gibi değilmişsin İstanbul.

Yatacak yerim yok dışarıda üşüyorum

Nedense her zaman yere ben düşüyorum

Düşmekten bıktım artık ben gidiyorum

Adın gibi değilmişsin İstanbul.

Özledim ben köyü davarı, malı,

Burada kimse sormuyor hatırı halı

İstemem gazino,diskotek,barı,

Adın gibi değilmişsin İstanbul.

Millet düşürüyor birbirini kapana

Lanet olsun şu paraya tapana

Kötülükler kar kalıyor yapana

Adın gibi değilmişsin İstanbul.

Toprağında bir tek çiçek açmıyor

Ağaçlarda hiçbir serçe uçmuyor

Ezogelin tarhanalar tütmüyor

Adın gibi değilmişsin İstanbul.

Kucağını aç ben geldim dedim

Bir buçuk yılda tekmeyi yedim

Buraya kadarmış benim kısmetim

Adın gibi değilmişsin İstanbul.', 'Herkes gidiyor da bende giderim Hem oraya gider kibar olurum Kafama göre bir iş bulurum İstanbul’a gideceğim orası büyük şehir Çok para kaza...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/istanbul-a-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile Yolu', 'cile-yolu-mehmet-ozcan-te51t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Efkar bastı yüreğimi dört bir yanım hatıra

Anlatmak istediğim sığmıyor ki satıra

İçim buruk kalbim kırık her taraf hüzün dolu 

Yürüyorum tükenmiyor ömrümün çile yolu', 'Efkar bastı yüreğimi dört bir yanım hatıra Anlatmak istediğim sığmıyor ki satıra İçim buruk kalbim kırık her taraf hüzün dolu  Yürüyorum tük...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cile-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz', 'temmuz-mehmet-ozcan-vfu41', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her temmuz geldiğinde,kendimi tanıyamam,

Düşünce girdaplarında, savrulur dururum.

Temmuz heyecan,temmuz coşku,temmuz sevgi,

Temmuz ayrılık, temmuz nefret, temmuz yalnızlık...

Her temmuz geldiğinde,aşkım tazelenir,

Sevdiğim aklıma gelir bir anda.

Öylesine saf,öylesine sade,öylesine mahçupluğuyla.

Bir temmuz akşamıydı seni görüp, seni sevmem,

Ve bir temmuz günüydü senin evlenmen.

Oysa istanbul kadar sevmiştim seni,

İstanbul kadar özlemiş,

Ve o kadar istemiştim.

Seni,yalnız seni, gecelerime ortak etmiş,

İsmini akdenizle birlikte yazmıştım,

Seni sevmiştim,

Umutsuzda olsa,erişilmezde olsa,sevmiştim.

Şimdi sen yoksun ama,

İstanbulda temmuz akşamları,

Gecem ve yalnızlığım,

Hep var ve hep olacak

Unutma...

Yine bir temmuz akşamı,

Sımsıkı sarılmışım yalnızlığıma,

Aşkımı kalbime gömmüş,

Kalemimin mürekkebinde yeşertiyorum,

Unutma, unutma...', 'Her temmuz geldiğinde,kendimi tanıyamam, Düşünce girdaplarında, savrulur dururum. Temmuz heyecan,temmuz coşku,temmuz sevgi, Temmuz ayrılık, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/temmuz-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanım', 'vatanim-mehmet-ozcan-yys1z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'VATANIM -Ömer’e-

Kıymetini ayrılınca anladım

Huzur dolu imiş taşın toprağın

Vatanımda fakirliğe razıyım

Gurbet elde kıymetini anladım

Dünyada senin bir benzerin yoktur

Uğrunda kefensiz yatanlar çoktur

Ayrılık sinemde sanki bir oktur

Gurbet elde kıymetini anladım

Türkiye’m toprağım canım vatanım

Yüz binler uğrunda şehit yatanım

Başka yerde tütmez benim ocağım

Gurbet elde kıymetini anladım

Canım pahasına korurum seni

İnan hiçbir kuvvet yıldırmaz beni

Yaşatmam sana kem söz edeni

Gurbet elde kıymetini anladım

Yüce bir ibadettir seni sevmek

Ne büyük saadet uğrunda ölmek

Boynumun borcu adını yüceltmek

Gurbet elde kıymetini anladım', 'VATANIM -Ömer’e- Kıymetini ayrılınca anladım Huzur dolu imiş taşın toprağın Vatanımda fakirliğe razıyım Gurbet elde kıymetini anladım Dünyad...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vatanim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emi', 'emi-mehmet-ozcan-w9gho', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'EMİ 

Ben adımı yazamazken sayende şair oldum,

Bir nehir misali taşıp taşıp doldum,

Bu karşılıksız aşkından yaprak gibi soldum,

Bitirdin beni yandım kül oldum,

Sende benden bin beter olasın emi.

Bir başka bakardım ben şu garip dünyaya,

Nereden düştüm bu amansız sevdaya,

Hasret kaldım uykulara dalmaya,

Rüyalarım, kabuslarım hep sen oldun,

Sende benden bin beter olasın emi. 

Ağlamayı bilmezken gözlerim hep yaş oldu,

Yumuşacık yüreğim sayende bir taş oldu,

Gecemi gündüz ettin gündüzüm gece oldu,

Sabah akşam seninleyim her vaktim hep sen oldun,

Sende benden bin beter olasın emi.

Ben seni geceleri hep köşede beklerim,

Dakikaları saate, günleri aya eklerim,

Ben sensiz yapamam ki bu hayatta teklerim,

Yüreğim, aklım, fikrim hep sen oldun,

Sende benden bin beter olasın emi.

Hayatım hüzün doldu gördükten sonra seni,

Viraneye çevirdi sonsuz hasretin beni,

Unutamam, terk etmeden bu can bu teni,

Dertlerim, kederim, çilem hep sen oldun,

Sende benden bin beter olasın emi.

Taşar oldu kelimeler ağzımdan,

Tel tel dökülüyor name sazımdan,

Eser yoktur şimdi sıcak yazımdan,

Baharım, kışım, hazanım hep sen oldun,

Sende benden bin beter olasın emi.', 'EMİ  Ben adımı yazamazken sayende şair oldum, Bir nehir misali taşıp taşıp doldum, Bu karşılıksız aşkından yaprak gibi soldum, Bitirdin beni...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/emi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecem', 'gecem-mehmet-ozcan-7m1d0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.GECEM 

Gecenin içindeyim, her tarafım karanlık,

Her tarafım soğuk, her taraf boğuk,

Tesellim acıların içinde saklı,

Hüzünlerim, hasretlerim, özlemlerim.

Gecenin içindeyim, her yanım ıssız,

Sessizliğin sesi sardı etrafımı,

Korkum benim içimde saklı, ben korkumun,

Umursamaz saniyeler bu düşünce yığınını.

Gecenin içindeyim, yırtılmak istiyor sanki,

Bu durgunluk, bu sessizlik, bu sakinlik,

Büyük ve korkunç bir çığlık saklıyor,

Sinesinde, özünde, her kuytu köşesinde.

Gecenin içindeyim, her yanım kalabalık,

Her taraftan bir ses, bir ızdırap, bir feryat,

Terkedilmiş, aldatılmış,ürkek ve meçhul duygular

Tarifsiz bir girdabın içinde çırpınıyorlar.

Gecenin içindeyim üzerimi örttü,

Sardı beni, bir anne şefkatiyle,

Dinledi acılarımı, dertlerimi, kederlerimi,

Ve ağladı halime.

Doyasıya yaşamak istiyorum geceyi,

Karanlıklar beni sarsın her yandan,

Hissetmek istiyorum, seni bütün hücrelerimde,

Kansam ve doysam bu meçhullükle.

Gecenin içindeyim, yolumu kaybettim,

Düşüncelerimin yönü belirsiz, aklım silik,

Yol gösterenim sigaramın dumanı, bitmeyen yollarda,

Bir döküntü ev kucağını açmış bana.

Tan ağarmaya başladı, yavaş yavaş,

Saltanatım son buluyor artık,

Bembeyaz karanlığımı istila ediyorlar,

Hayatla, insanla, zannedilen aydınlıkla.

Bana gecelerimi verin,

Geceler benim, ben gecenin,

Ayırmayın bizi birbirimizden,

Bekliyorum kulübemde seni Ey GECEM! ...', '.GECEM  Gecenin içindeyim, her tarafım karanlık, Her tarafım soğuk, her taraf boğuk, Tesellim acıların içinde saklı, Hüzünlerim, hasretlerim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gecem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asi Manolya', 'asi-manolya-mehmet-ozcan-rbpy5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ASİ MANOLYA 

Açmamıştım hiç kimseye gönül bahçemi

Sesimi duyurmamıştım hiç kimseye

İsmim anılmamıştı hiçbir ağızda.

Manasız sırların içinde gizlendim

Anlaşılmaz,zırhlara büründüm,

Ne kapı ne pencere hepsini örttüm,

Onca gizine rağmen benliğimin,

Leylakları,sümbülleri,gülleri kovarken,

Yalnız kalmışken,gönül kalemde

Açtı bir asi manolya bahçemde.', 'ASİ MANOLYA  Açmamıştım hiç kimseye gönül bahçemi Sesimi duyurmamıştım hiç kimseye İsmim anılmamıştı hiçbir ağızda. Manasız sırların içinde ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/asi-manolya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Hasret', 'deli-hasret-mehmet-ozcan-28pby', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DELi HASRET 

Hayalin Akdeniz di bu gönlüme,

Dalga dalga çarpıyordu kalbime,

Yakamozlar içinde bir deniz kızı,

Taht kurdu ıpıssızken benliğime.

Çöl içinde kardelenler açtılar,

Umutlarım sonsuzluğa taştılar,

Ruhumun dilinden anlamaz oldum,

Kelimeler hep yetersiz kaldılar.

Başlayan yangınlar hemen söner mi,

Gidenler bir daha geri döner mi,

Her yanımı saran bu deli hasret,

Şarkıyla, şiirle söyle diner mi.', 'DELi HASRET  Hayalin Akdeniz di bu gönlüme, Dalga dalga çarpıyordu kalbime, Yakamozlar içinde bir deniz kızı, Taht kurdu ıpıssızken benliğim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/deli-hasret-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Roman', 'bir-roman-mehmet-ozcan-cxvca', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BiR ROMAN

Esmer tenin, inci dişin, kıvrım kıvrım saçların,

Sürmeli göz, kiraz dudak, keman gibi kaşların,

Gençliğinin baharında, yirmisinde yaşların,

Böyle güzel olmaya hakkın var mı kız senin? 

Uzun boyun selvi gibi süzülür,

Zülüflerin sırma sırma dizilir,

Seni gören sarhoş olur salınır,

Böyle güzel olmaya hakkın var mı kız senin? 

Seni gördüğümde hemen vuruldum,

Engin sel gibiydim birden duruldum,

Aşık oldum sen kalbime kuruldun,

Böyle güzel olmaya hakkın var mı kız senin? 

Yüreğimde derin bir iz bıraktın,

Sen beni amansız aşkınla yaktın,

Sonrada yüz üstü bıraktın kaçtın,

Böyle güzel olmaya hakkın var mı kız senin? 

Dertler açtın sen çilesiz başıma,

Zehir kattın benim tatlı aşıma,

Hiç acımadın akan göz yaşıma,

Böyle güzel olmaya hakkın var mı kız senin? 

Beni sevmen büyükçe bir yalanmış,

Maksadın masum yüreğimi talanmış,

Bilmem gönlüm sana nasıl aldanmış,

Güzelliğin senin olsun istemem! 

İstemezdim bu aşkın böyle bitmesini,

Sevgimin hislerimin silinip gitmesini,

Senin yüzünden benliğimin yitmesini,

Güzelliğin senin olsun istemem! 

Seni gördüğümde insan sanmıştım,

Verdiğin sözlere inan kanmıştım,

Pembe pembe hülyalara dalmıştım,

Güzelliğin senin olsun istemem! 

Güzelliğin hiç beş para etmezmiş,

İnsan için bir güzellik yetmezmiş,

Bu aşk artık bundan öte gitmezmiş,

Güzelliğin senin olsun istemem! 

Adını bir daha anmam ki senin,

Hiç mi yokmuş senin ahlâkın denin,

Semtimde yok senin bir avuç yerin,

Güzelliğin senin olsun istemem! 

O masum maskenin altında yatan,

Aklımı fikrimi başımdan alan,

Hayatıma bir doğup bir de batan,

Güzelliğin senin olsun istemem! 

Adını yazdığım ağacı kestim,

Verdiğin güllerin hepsini ezdim,

Kalpsiz olduğunu sonradan sezdim,

Güzelliğin senin olsun istemem! 

İnsafsız, hayırsız, vefasızmışsın,

Beş para etmeyen bir kansızmışsın,

Kalbi kırık kalemim daha ne yazsın,

Güzelliğin senin olsun istemem! 

O gözlerin şeytan gibi bakarmış,

O dillerin yılan gibi sokarmış,

Geçti gitti bir kısacık romanmış,

Güzelliğin senin olsun istemem!', 'BiR ROMAN Esmer tenin, inci dişin, kıvrım kıvrım saçların, Sürmeli göz, kiraz dudak, keman gibi kaşların, Gençliğinin baharında, yirmisinde ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/bir-roman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-mehmet-ozcan-kbz53', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayrola arkadaş, neden yalnızsın,

Derinden derine düşe dalmışsın,

Gecenin bu vakti yaya kalmışsın,

Hayattır, zalimdir, takma arkadaş

Hele bir sigara yak be arkadaş.

Karanlık kaldırım, uzun yolumuz,

Dertleşe dertleşe çeker gideriz,

Aşıksın herhalde halden anlarız,

Hayattır, insanız, olur arkadaş,

Hele bir sigara yak be arkadaş

Anlat bir derdini, çare olayım

Yaranı söyle de merhem bulayım

Üşümüş gibisin, bir çay alayım,

Hayattır, haindir, bakma arkadaş,

Hele bir sigara yak be arkadaş.

Sevgini sunduğun, zalim mi çıktı

Aşkının ateşi seni mi yaktı

Gözünden durmadan yaşlar mı aktı

Gönüldür, neylersin, ferman dinlemez.

Sigara derdime neyler arkadaş.', 'Hayrola arkadaş, neden yalnızsın, Derinden derine düşe dalmışsın, Gecenin bu vakti yaya kalmışsın, Hayattır, zalimdir, takma arkadaş Hele bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özcan']::text[], 8.5, '{"poet":"Mehmet Özcan","poet_slug":"mehmet-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arkadas-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küllenen Mektup-1', 'kullenen-mektup-1-ozkan-karaca-5p9uf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bulutlar nemli yağmurlarla kirlenmişti. Ruhumun aralanan penceresine senin resmin yanaşmıştı. Yağmurun yüreğime batışında sensizliğin acısı akmıştı...

Hayallerime ittiğim bulutlar gelinlik olarak süslenmişti.Biriken karabulutların kadehleri gözlerimi yıkarak duygularım  kanla ıslanmıştı. Hayatımı saran zincirlerle sukütlar yırtılmıştı. Geçmişin inlerine kapattığım sevda benliğimde yankılanmış

Ufukların bilinmezinde ruhum sislenmişti Acı yüklü nefesim sesini arayarak seni arayıp durmuştum', 'Bulutlar nemli yağmurlarla kirlenmişti. Ruhumun aralanan penceresine senin resmin yanaşmıştı. Yağmurun yüreğime batışında sensizliğin acısı ...', ARRAY['Türk Edebiyatı','Şiir','Özkan Karaca']::text[], 8.5, '{"poet":"Özkan Karaca","poet_slug":"ozkan-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kullenen-mektup-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Kalbinin Gözü İle Bak', 'hayata-kalbinin-gozu-i-le-bak-teoman-bicer-iqrk6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canânı canından sevmeyi unutmuşuz

Yolumuz uzun

Yalan dünyanın gönül dağında

Sele gideli kör olmuşuz

Bilmem ki; nasıl yaşamışız! 

Hasretler, hançer gibi

Gelir olduğu şu zamanlarda				

Öyle acılar vardır ki	

Onlar,sadece

Kalbinin duygularında saklıdır.

Zaman içine kapanmış,

Af dilemek istiyorum

Ama dileyemiyorum

Seviyorum ama 

Bunu ifade edemiyorum.

Duygularımın meleğisin

Kalbimin anahtarı sende! 

Bilmem ki nasıl yaşamışız

Bir tek dileğim var

Hayata kalbinin

Gözüyle bak,', 'Canânı canından sevmeyi unutmuşuz Yolumuz uzun Yalan dünyanın gönül dağında Sele gideli kör olmuşuz Bilmem ki; nasıl yaşamışız!  Hasretler, ...', ARRAY['Türk Edebiyatı','Şiir','Teoman Bicer']::text[], 8.5, '{"poet":"Teoman Bicer","poet_slug":"teoman-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayata-kalbinin-gozu-ile-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum...', 'gidiyorum-selim-bayrak-0fnn0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidiyorum buralardan olmadığın yerlere

Gidiyorum buralardan olmadığım yerlere

Her şeyi bırakmak ö-y-lesine kolay ki

Bugün parçaladığım resimleri

Yeniden yapıştıramam

Bugün terkettiğim seni

Bir daha asla bulamam

Kayıpsın kayıpsın ''ben'' ''siz

kayıpsın kayıpsın kimsesiz

1997 - İstanbul', 'Gidiyorum buralardan olmadığın yerlere Gidiyorum buralardan olmadığım yerlere Her şeyi bırakmak ö-y-lesine kolay ki Bugün parçaladığım resim...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gidiyorum-175-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 47', 'resaran-siir-ve-beyitsiler-47-huseyin-avdic-18bk3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Döndür Gönlünü Sahibine

Dönükse kalbin kendi benine,

Giremezsin Rabbin cennetine.

Döndür şu gönlünü Sahib''ine,

Giriver O''nun saadetine.

******

Her Dua Kabul Edilmez

Her duaya cevap verir Allah, fakat her dileği hemen kabul etmez.

Derdine göre reçete yazar doktor, zararlıysa onu sana vermez.

Berlin, Ekim 2005.', 'Döndür Gönlünü Sahibine Dönükse kalbin kendi benine, Giremezsin Rabbin cennetine. Döndür şu gönlünü Sahib''ine, Giriver O''nun saadetine. ****...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/resarani-siir-ve-beyitsiler-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Dolusu Gözyaşı', 'yurek-dolusu-gozyasi-aysen-safak-xneib', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğim sessiz ve ürkek adımlar atıyordu 

                                 gecenin karanlığında...

Kirlenmişti sokaklar,

Kirlenmişti toprağı deniz kokan şehrim.

O kalabalık yalnızlığı bir çırpıda bırakıverdim.

Ardımda bıraktığım şehir ağlıyordu,

Tıpkı yürüyen kalabalıkların ağladığı gibi...

Uzak memleketlerin kokusu çekiyordu beni

Daha dokunulmamış,kirletilmemiş

Daha kaybolmaya mahkum olmamış.

Yüreğim sessiz sedasız bırakıverdi yaşadığım şehri! 

O öyle bir şehir ki 

Beni içine çekiyordu önceleri...

Ne kadar gittiysem derinlerine,

O kadar kirlendi ellerim,,,bedenim

O kadar kirlendi sevdası büyük yüreğim.

Karanlıkta kimsecikler yoktu sokaklarda 

Gökyüzüne açtım elllerimi,

Gökyüzü ağlıyordu:((

Su oldum,ırmak oldum,ağladım ben de! 

Gökyüzüne  karıştım...

Ben, eeeey ben! 

Gökyüzünden  daha çok ağlıyordum.

Ruhum bedenimi terkedecekti

                             biraz daha ağlasam...', 'Yüreğim sessiz ve ürkek adımlar atıyordu                                   gecenin karanlığında... Kirlenmişti sokaklar, Kirlenmişti toprağı...', ARRAY['Türk Edebiyatı','Şiir','Aysen Safak']::text[], 8.5, '{"poet":"Aysen Safak","poet_slug":"aysen-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yurek-dolusu-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükeniyor', 'tukeniyor-cagla-toygan-8b6q3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'savrulurcasına.. 

bir son lazım artık 

akıp giden bu deli sulara 

nerde nasıl ne zaman olduğunu unuttururcasına 

kayboluyoruz 

tükeniyor.. 

sarılıp tutunmalı bırakmamalı 

tıpkı ağaçların kökleri gibi...', 'savrulurcasına..  bir son lazım artık  akıp giden bu deli sulara  nerde nasıl ne zaman olduğunu unuttururcasına  kayboluyoruz  tükeniyor..  ...', ARRAY['Türk Edebiyatı','Şiir','Çağla Toygan']::text[], 8.5, '{"poet":"Çağla Toygan","poet_slug":"cagla-toygan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tukeniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Öptüm Kızdım Utandım', 'sevdim-optum-kizdim-utandim-dilek-hokkaomeroglu-kjzbp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ağlarken göz yaşını sevdim.

sevdim....sevdim...sevdim...



nede yakışırdı ismim dudaklarına,

yine sevdim.

sesindeki ürkekliği sevdim,

öfkesinde saklı okyanusları,

sevdim...

masumiyetini sevdim,

en son utanan kelimelerinde,

öptüm...öptüm...öptüm...

çocuk oluşunu sevdim,

çocukça şakalarını,

anlamsızlığını bakışlarının,

ellerini sevdim,

kalbini sevdim,

kalbindeki beni.

ve...

kızdım...kızdım...kızdım...

benim için önemi yoktu sevişimin

sordum...

beni sevişini yine sevdim.

o yokken varlığını sevdim,

raks edişini sevdim,

yağmurda ıslanan bedenini sevdim,

baktıkça,,

utandım...utandım...utandım..



bir gülüşü ile,

uyandım...uyandım...uyandım.

seni seviyorum

bende...bende...bende..', 'ağlarken göz yaşını sevdim. sevdim....sevdim...sevdim... nede yakışırdı ismim dudaklarına, yine sevdim. sesindeki ürkekliği sevdim, öfkesind...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevdim-optum-kizdim-utandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-cagla-toygan-j4np2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herşey aynı 

Sabah akşamın 

Akşam gecenin bir aynası sanki 

Sensiz geçen bu zamanı yansıtan 

Yine bir gün bitiyor 

Issız gecenin karanlığıyla örtülüyor bedenim 

Yine derin dalışa geçiyorum 

Seni bulabildiğim tek dünyaya... 

(19/09/2005)', 'Herşey aynı  Sabah akşamın  Akşam gecenin bir aynası sanki  Sensiz geçen bu zamanı yansıtan  Yine bir gün bitiyor  Issız gecenin karanlığıyl...', ARRAY['Türk Edebiyatı','Şiir','Çağla Toygan']::text[], 8.5, '{"poet":"Çağla Toygan","poet_slug":"cagla-toygan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sensizlik-213-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Zaman', 'bu-zaman-mehmet-zekeriya-gulsoy-srtln', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O karaları sermiş dağlar üstüne

Binbir çiçek dermiş bağlar üstüne

Kimine az vermiş ağlar üstüne

Yaradan emrinde döner bu zaman

Şükret her haline islamı yaşa

Bakma siyah beyaz ne yüze başa

Hayat öyle kısa geçirme boşa

Mum gibi ömründe söner bu zaman

Ümmetin diyecek Ogüzel nebi

O na layık olsak biz ona tabi

Temizle günahdan kurtar  hep kalbi

Görmeden deminde yanar bu zaman

Yaradana doğru bağla özünü

Allah kelamından söyle sözünü

Haramlardan sakın elin gözünü

Kısmetin elinde iner bu zaman', 'O karaları sermiş dağlar üstüne Binbir çiçek dermiş bağlar üstüne Kimine az vermiş ağlar üstüne Yaradan emrinde döner bu zaman Şükret her ha...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zekeriya Gülsoy']::text[], 8.5, '{"poet":"Mehmet Zekeriya Gülsoy","poet_slug":"mehmet-zekeriya-gulsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-zaman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Aşk', 'gercek-ask-cagla-toygan-agu9g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yaktım hepsini! gereksiz her bir ayrıntıyı.. 

şimdi içime soluyorum,O''nun mükemmelliğini... 

durduramadığım bu zamani bir an olsun O''nsuz yaşamadan 

gerçek aşkı işliyorum içime saniye saniye.. 

(27/09/2005)', 'yaktım hepsini! gereksiz her bir ayrıntıyı..  şimdi içime soluyorum,O''nun mükemmelliğini...  durduramadığım bu zamani bir an olsun O''nsuz ya...', ARRAY['Türk Edebiyatı','Şiir','Çağla Toygan']::text[], 8.5, '{"poet":"Çağla Toygan","poet_slug":"cagla-toygan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gercek-ask-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alemlere Rahmet', 'alemlere-rahmet-mehmet-zekeriya-gulsoy-bw8d4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alemlere rahmet gelmiş efendim

Herkese merhamet etmiş efendim

İsteyene nimet vermiş efendim

Yaradan aşkına emri üstüne

Rabbim habibine ümmet eylesin

Herkes ehli beyte hürmet eylesin

Salavat-ı Şerif içten söylesin

Yaradan aşkına emri üstüne

Biz garip kulların sensin sahibi

Bizim rehberimiz o güzel nebi

Bizde olabilsek ashabı gibi

Yaradan aşkına emri üstüne', 'Alemlere rahmet gelmiş efendim Herkese merhamet etmiş efendim İsteyene nimet vermiş efendim Yaradan aşkına emri üstüne Rabbim habibine ümmet...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zekeriya Gülsoy']::text[], 8.5, '{"poet":"Mehmet Zekeriya Gülsoy","poet_slug":"mehmet-zekeriya-gulsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alemlere-rahmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Bin Can Gerekir', 'aska-bin-can-gerekir-umit-cetin-3jckr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vuslatlar yetmez aşka... 

Hasret gerekir,

Gurbet gerekir, 

Sevileni yürekte taşımak gerekir...

Masumiyet yetmez aşka.. 

Suçlanmak gerekir, 

Yerlere serilmek gerekir, 

Zindanlara girmek gerekir...

Kılıçlar yetmez aşka... 

Mayınlar gerekir, 

Pusatlar gerekir, 

Bombalar, kurşunlar gerekir...

Mutluluk yetmez aşka... 

Hüzünler gerekir, 

Sürgünler gerekir...

Merhamet yetmez aşka... 

Gözyaşı gerekir, çile gerekir, 

Gamdan dağlar gerekir...

Küçük bir umut yetmez aşka... 

Koskoca dağlar kadar azim, 

Deryalar kadar sabır gerekir...

Denemek yetmez aşka... 

Atılmak gerekir kavgaların orta yerine. 

Gülümsemek gerekir, yaşam denen dertler yumağına...

Boş sözler yetmez aşka.. 

Koca koca ütopyalar gerekir, idealler gerekir, yaralar gerekir...

Hasılı, bir ömür yetmez aşka, 

Gerekirse canı vermek, 

Gerekirse yeniden doğmak, 

Gerekirse yaşamak gerekir...', 'Vuslatlar yetmez aşka...  Hasret gerekir, Gurbet gerekir,  Sevileni yürekte taşımak gerekir... Masumiyet yetmez aşka..  Suçlanmak gerekir,  ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Çetin']::text[], 8.5, '{"poet":"Ümit Çetin","poet_slug":"umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aska-bin-can-gerekir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ecele Banıyor', 'ask-ecele-baniyor-necmi-unsal-73fc2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözümden akan her damla

Yüreğimde soğuyor.

Hasretin bir oldu gamla

Hep hülyamı boğuyor.

Kâr etmez yarama merhem

Gün geçtikçe kanıyor.

Ver ilacından bir dirhem

Aşk ecele banıyor.

10 Temmuz 2004 Cumartesi, Danimarka-Køge 23.22', 'Gözümden akan her damla Yüreğimde soğuyor. Hasretin bir oldu gamla Hep hülyamı boğuyor. Kâr etmez yarama merhem Gün geçtikçe kanıyor. Ver il...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ask-ecele-baniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Meçhul''ün Güncesinden Notlar..! - V', 'bir-mechul-un-guncesinden-notlar-v-turgut-baki-5u5ls', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gece oldu mu? 

baldıran zehir gibi yapışıyor,

geçmişi kınalı dünyanın 

cefası canıma…

dar geliyor odam bana,

duvarlar üstüme, üstüme yürüyor ha bire! 

Delleniyorum,

çok akılıymışım gibi

benim,

bana bile tahammülüm yok böylesi gecelerde…

birde yetmezmiş gibi,

“dışarıda fasıl geceleri

muhtelif zaman gürültüleri

varyeteler, sinekler, kediler

ve fare ölüleri”

doluşup durur usuma 

inadına, inadına…

“hani çok sevmiştim ya,

sevebildiğimin en çoğundan,

ve halen en daha çok

seviyorum ya seni…

sırf bunun hatırına

sırf bu yüzden”

bir tek sen,

sen olmazsın 

bunca karmaşanın arasında…

kendimi mahkum ederim sensizliğe de,

izin vermem sana bulaşmalarına

“her ömrün bir kaybetme mevsimi oluyormuş mutlaka”

öyle diyor, bildiğini iddia edenler.

aşklarını,

inançlarını,

dostlarını,

heyecanını,

merakını,

amacını,

arzusunu kaybedermiş insan zaman, zaman

benimkinin de farkı yok sanırım 

bu yaşananlardan…

“bir mevsimdir bu gelip geçer,

yaz ise fazla terlememeye

kış ise fazla üşütmemeye çalışacaksın

hepsi bu” demişti babam,

tarihini bile hatırlamadığım

vakti zamanın birinde…

işte durup dururken birden geldi aklıma

nerden geldiyse…

ve ne gerek varsa bilmiyorum ama

habire karalıyorum,

kara kaplı defterin bir köşesine tüm bunları

iyi…

yazmak iyide 

bir de başlık bulmak gerekecek tüm bu yazılanlara.

“Bir Meçhulün Güncesinden Notlar” desem? 

dedim bile!', 'gece oldu mu?  baldıran zehir gibi yapışıyor, geçmişi kınalı dünyanın  cefası canıma… dar geliyor odam bana, duvarlar üstüme, üstüme yürüyor...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/bir-mechul-un-guncesinden-notlar-v-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımın içi', 'canimin-ici-celal-topo-obwuh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlamama izin verir misin canımın içi? 

Gözyaşlarım gözlerinde kaybolup gitsin

Tuttuğum ellerini bastıra bilir misin gözlerime? 

Durdura bilir misin gözlerim deki yaşı? 

Bütün renklerinle boyasan da ruhumu

Artık geçmişte kalan

Kurulmuş bir hayal görülmüş bir düşsün

Seni şimdi nereler de bulsam? 

Bulsam da saçlarının her telini koklasam

canımın içi.........

Hani bir elmanın iki yarısıydık biz.....



17 / 10 /2005    Antalya', 'Ağlamama izin verir misin canımın içi?  Gözyaşlarım gözlerinde kaybolup gitsin Tuttuğum ellerini bastıra bilir misin gözlerime?  Durdura bil...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/canimin-ici-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Seni uzaktan Sevmek*', 'seni-uzaktan-sevmek-i-brahim-dikmen-2-b6g7t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '***Gülüm,

Seni uzaktan sevmek

o kadar zor geliyor ki

bilemezsin gülüm bilemezsin

***Aslında,

o kadar yakınsın ki bana

ama bir ok adar da uzaksın

gelemezsin gülüm gelemezsin

***Gülüm,

seni kollarıma alıp sarmayı

har bedeninde sabahlamayı

istemezmiyim gülüm istemezmiyim

istemezmiyim sanırsın

karanlığa nisbet yaparcasına

geceyi ateşinle ısıtmayı

***Aslında,

o kadar zoruma gidiyor ki

yanıbaşımda  olupta

tenine dokunamamayı

hissedemezsin gülüm hissedemezsin

***Hatta,

öpememek seni kanatırcasına

dudaklarında esir kalmayı

bilemezsin gülüm bilemezsin

***Gülüm,

o kadar kolay değil aslında

ikimizde farkındayız bunun

lakin! 

ikimizde seviyoruz yalan değil

öyle değilmi gülüm.

ne olursa olsun,

ben seni böylede seviyorum

işte tabulara nisbet

düşlerimde de olsan

benimsin ya gülüm.

***Ve sen,

sabahlara uyandığımız

güneşe meydan okuduğumuz

aşk ateşiyle ısıttığımız

karanlık zemheriye nisbet

ve sen bütün kadınlığınla

ve sen benimsin gülüm.

ve hep benim kalacaksın

sevgimle kal

***Gülüm.

17/10/2005', '***Gülüm, Seni uzaktan sevmek o kadar zor geliyor ki bilemezsin gülüm bilemezsin ***Aslında, o kadar yakınsın ki bana ama bir ok adar da uza...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/seni-uzaktan-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Gibi...', 'toprak-gibi-pinar-koc-u520a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yumuşacık bir ilkbaharın kollarında

Olsaydım şimdi….

Sımsıcak bir lokma ekmekten çıkan buharlar gibi,

Dumanlar çıksaydı yüreğimden…

Güneş kavursaydı gözlerimin toprak rengini,

Saçlarımı okşasaydı sevgisiyle! ! 

Hafızam dursaydı şaşkınlıktan…

Ölseydim saadetimden…

Vücudum topraklarda açan bir papatya olsaydı baharda

Veya soğuk bir kış gününde beyaz bir kardelen…

Unutsaydım yaşadığımı yıllar sonra…

Ne yıllar öncesi olsaydı benim için,

Nede yıllar sonrası……….

                                                   17.02.05

                                                 perşembe        19:50', 'Yumuşacık bir ilkbaharın kollarında Olsaydım şimdi…. Sımsıcak bir lokma ekmekten çıkan buharlar gibi, Dumanlar çıksaydı yüreğimden… Güneş ka...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/toprak-gibi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Memleket...', 'bir-garip-memleket-pinar-koc-pyq8j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluluk dağ başındaki yalnız çiçek,

sevinçler masum çocukların minik gülücükleri

ve güzel günler,ve güzel günler çok yakın…

seni terk ediyorum …

dağ başındaki yalnız kasaba,

dağ başındaki kalabalık ama ıssız memleket; 

seni terk ediyorum…

mutluluğumun gözlerimden okunduğunu biliyorum.

Sevinçlerim simli göz yaşlarım,

Ve güzel günler,ve güzel günler çok yakın…

Seni terk ediyorum

Sizi terk ediyorum…

Mutsuzluğumun arkasındaki

Umutsuzluğumsunuz…

Umutsuzluğumun peşindeki kara gölgemsiniz siz! 

Seni,sizi,bu memleketi terk ediyorum…

Artık mutluyum…

Artık umutsuzluğumun son bulmasından umutluyum

Ve güzel günler,ve güzel günler çok yakın…

                                                               22.8.2001

                                                              Çarşamba', 'Mutluluk dağ başındaki yalnız çiçek, sevinçler masum çocukların minik gülücükleri ve güzel günler,ve güzel günler çok yakın… seni terk ediyo...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-garip-memleket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ol Hak''ka Yakın', 'ol-hak-ka-yakin-mehmet-zekeriya-gulsoy-702zj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ramazan ayında ol hakka yakın

İbadet Allah''ın hoşuna gider

Haramdan günahdan uzak dur sakın

Tuttuğun o oruç boşuna gider

Muhammed Mustafa, ey güzel rabbim

Sizi söyler dilim, anar bu kalbim

Soran az dünyaya ben niye geldim

Hep dünya işinin peşine gider

Zengin zevk sefada bir eli balda

Merhamet azalmış bugün çok kulda

Yoksul düşüp kalmış sürünür yolda

Herkeste el varda başına gider', 'Ramazan ayında ol hakka yakın İbadet Allah''ın hoşuna gider Haramdan günahdan uzak dur sakın Tuttuğun o oruç boşuna gider Muhammed Mustafa, e...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zekeriya Gülsoy']::text[], 8.5, '{"poet":"Mehmet Zekeriya Gülsoy","poet_slug":"mehmet-zekeriya-gulsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ol-hak-ka-yakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-suleyman-yavuz-jcjmc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Temmuzun ateşi gibi yaktın beni

Martın ayazı gibi dondurdun

Kimseyi koymadığım şu kalbimle 

Bir sana vurgundum 

Sende acımadan 

Hançeri en derine vurdun

Kanadı yüreğim elimde 

Ağladım terk edip gidişinle

Yıkıldım sevmiyorum deyişinle 

Bittim başkasıyla elele görünce 

Ölümdür bana artık çıkar yol

Sen zaten vurmuştun yaralıydı yürek

Şimdi namluyu çevirdim kendime 

Yarım bıraktığın işi bitirmek için

Sen vurdun süründürdün

Ben öldüreceğim kendimi

Görmektense seni başka elde

Ölüm en güzeli bu bedene', 'Temmuzun ateşi gibi yaktın beni Martın ayazı gibi dondurdun Kimseyi koymadığım şu kalbimle  Bir sana vurgundum  Sende acımadan  Hançeri en d...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olum-215-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlizlik Felsefesi', 'yanlizlik-felsefesi-ulya-erkman-e1pw7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yanlizimsimdi kendi kendimle 

   Odalar bos  yok konusacak kimse

   Yanlizimdir bazan insanlar arasindada

   Yanlizimdir yine kimseler olmayinca

   Yanliz birakmaz ama ruyamdaki insanlar

   Yanliz birakmaz ama hayalimdeki hatiralar

   Yanliz degilim dua ederken allaha

   Yanliz degilim o beni koruyunca

   O kuvvetle dusunurum birden

   Yanliz degilimki ben kendi kendimlen

   Dostum kendim arkadasim ben yine

   Dusmanim bile kendim inkar etsem bile

   gulduren beni benim zaman zaman

   Aglatan beni yine kendim bazan

   Teselli veren bana bilirim benim

   Sevindiren beni ise yine kendim

   Ben varim simdi her yerde odalarda

   Bombos degil odalar benim varligimla

   Anladim yeterim ben kendi kendime

   Yanliz degilim artik beraberim kendi benligimle', 'Yanlizimsimdi kendi kendimle     Odalar bos  yok konusacak kimse    Yanlizimdir bazan insanlar arasindada    Yanlizimdir yine kimseler olmay...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yanlizlik-felsefesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kawa''nın Torunları', 'kawa-nin-torunlari-i-sa-tekin-fb1ad', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün bayram 

Bugün newroz

Eğlenin halay çekin

Güneşin çocukları

Kawa nın ruhu sizinle

Ortadoğu Mezopotamya''da

Yaşıyor binlerce yıl

Yakın gür ateşleri dağlarıma

Müjdeler olsun halkıma 

Bügun Newroz

Kutlu olsun

Ortadoğu Mezopotamya''da

Biz direniş ateşinden doğduk

Anka kuşu gibi

Zor da olsa

Kan da olsa 

Katliam da olsa

Söndüremediler

Direnişimizin ateşini

Çünkü biz direnişin çocuklarıyız

Kawa''nın torunları

Bin selam özgürlük ateşine

Bin selam özgürlük için

Özgürlüğe gidenlere

Kawa''nın ruhuna 

Bin selam', 'Bugün bayram  Bugün newroz Eğlenin halay çekin Güneşin çocukları Kawa nın ruhu sizinle Ortadoğu Mezopotamya''da Yaşıyor binlerce yıl Yakın gü...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kawa-nin-torunlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Anne', 'ozledim-anne-i-brahim-halil-demir-pbj6y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ÖZLEDİM ANNE 

Gurbetin ışıkları gönlümü aydınlatmıyor anne!

Toprağı ise buram buram, mis gibi kokmuyor anne!

Gurbetin hiçbir nimeti, beni mutlu etmiyor anne!

Gözlerimin önünden, yurdumun hiçbir şeyi gitmiyor anne!

Duygularım kördüğüm olmuş, gözyaşım gelmiyor anne!

Şakır şakır konuşan dilim, şimdi konuşmuyor anne!

Ne geceler, ne de gündüzler geçmiyor, durmuş sanki anne!

Sevdiklerim aklıma geliyor, adlarını söyleyemiyorum anne!

Nereden çıktı gurbette yaşamak, bilemiyorum anne!

Ölüme yavaş, yavaş gidiyorum sanki anne!

İnsanlar somurtmuş, telaşlı hep izdiham içinde anne!

Ne olacak benim bu halim, şaşırdım kaldım anne!

Gaz lambasının ışığını, özledim anne!

Gurbetin rengareng projektörleri, mutlu etmiyor beni anne!

Kuru ekmeğimi, çorbaya doğradığım günleri özledim anne!

Koyun yoğurdundan yapılmış, buz gibi ayranı kana, kana içmeyi özledim anne!

Gurbetin albenisi güzel, ama içimi güldürmüyor anne!

Buranın rüzgarları bir hoş esmiyor, serinletmiyor anne!

İnsanların bakışları, ürkütüyor beni, küstürüyor anne!

Ne yersem yiyeyim, lezzet alamıyorum anne!

Adım çıkmış zengine, ama ben mutlu fakirliğimi arıyorum anne!

Helal kazanılmış lokmaları, arar oldum anne!

Bu genç yaşımda, kamburlaşmış belim, yüzüm asık anne!

Manevi zenginliğimi, kaybedeceğime üzülüyorum anne!

Soframdaki bereketi, evimdeki eski huzurumu, özledim anne!

Büyüklere saygılı, küçüklere sevgili, olmayı arıyorum anne!

Ahde vefayı, ihlası ve bir lokmayı birlikte paylaşmayı özledim anne!

Maheretli ve nasırlı ellerinden, doyasıya öpmeyi özledim anne!

Süzülmüş mercimek çorbasını kaşıklarken, buharındaki mutluluğu özledim anne!

Bismillah ile başlayıp, Elhamdulillah diyerek sofradan kalkmayı özledim anne!

İnsanların canı gönülden, birbirlerine gidip gelmelerini özledim anne!

Mevlana nın dediği gibi, ''"ya göründüğün gibi ol, ya da olduğun gibi görün" olanları özledim anne!

Yapmacık hareketler,  kendine iyi bak, cümlesi bana yavan geliyor anne!

Dostça kucaklaşmayı, kucaklaşırkende samimiyeti özledim anne!

İçi boş olan, " görüşelim tamam mı" cümlesini sevmiyorum anne!

Erkekçe el sıkışmayı, sevdiğini asla ve asla yarı yolda koymamayı, özledim anne!

Güneşte ısınmış su ile, yıkanmayı özledim anne!

Komşuların dayanışmasını, birbirlerine yemek göndermesini, özledim anne!

Herkesin kendi kapısının önünü yıkayıp, temizlemesini özledim anne!

İnce uzun sokakların, güzelliğini ve temizliğini özledim anne!

Gurbette ölmek hoşuma gitmiyor, korkuyorum anne!

Bir Fatihanın okunup okunmayacağını, düşünüyorum anne!

Mezarımın üstünde, kuşların cıvıldaştığı bir ağaç istiyorum anne!

Bunları hep tasavvur etmekten, gurbet hayatı beni uyutmuyor anne!

Tezek dumanının tütmesini, çeşitli hayvan seslerini özledim anne!

Tezek ateşinde pişirilen yemeklerin, damakta bıraktığı lezzeti özledim anne!

Kırlarda, kor ateşte demlenen, kaçak çayın tavşan kanına benzemesini, özledim anne!

Başımı dizlerine koyup, şekerlemeyi özledim anne!

Kim ne derse desin, ben patika yolların, tozunu özledim anne!

Ben bir bağbancının, her geçen yolcuya, salkımlarca üzüm vermesini özledim anne!

Ben insanların selamlaşmasını, "kolay gelsin, bereketli olsun" demelerini özledim anne!

Ve ben kuşların insanlardan, ürkmeden özgürce uçmalarını özledim anne!

Bu hayata alışamadım, sesim soluğum kesildi, takatim tükendi anne!

Yarını karanlık, geleceği meçhullerden, oldum anne!

Kavuşmak için eski günlerimdeki mutluluğuma, hep dua ediyorum anne!

Başka annelerin şefkati, beni mutlu etmiyor, yorgunluğumu gidermiyor anne!

Babamın yorgun argın işten gelirken, gözlerindeki,

mutluluğu ve sevinci özledim anne!

Biz çocukların ise etrafında dönmesini ve "hoş geldin babacığım" demesini özledim anne!

''"Bugün çok yoruldum" "taş duvar inşaatında çalıştım" "ama yine de şükürler olsun" diyerek tebessüm etmesini özledim anne!

Damda yıldızları bir bir saymaya çalışırken, derin uykuya dalmayı özledim anne!

Bahar gelince, gül bahçelerinden, gül toplamayı özledim anne!

Topladığım gülleri, öğretmenime vermeyi ve başımın sevgiyle sıvazlanmasını özledim anne!

O şevk ile eve geldiğimde, ekmeğimi gün pekmezine bandırarak, karnımı doyurmayı özledim anne!

Sonra da musluktan akan hamravat suyundan, doyasıya içmeyi özledim anne!

Sınıfın en çalışkanı olmak için harcadığım gayreti özledim anne!

Ödevlerimi yapabilmek için, büyüklerimin bilgilerine danışmayı özledim anne!

Sonra da ödevimi yapmış olmamın, rahatlığını ve sevincini özledim anne!

Ödevler kontrol edilirken "afferin en güzeli seninki olmuş" denmesini özledim anne!

Ve öğretmenimin sadakatini, annemsi şefkatini ve de takdirini özledim anne!

19/10/2004', 'ÖZLEDİM ANNE  Gurbetin ışıkları gönlümü aydınlatmıyor anne! Toprağı ise buram buram, mis gibi kokmuyor anne! Gurbetin hiçbir nimeti, beni mu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/ozledim-anne-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pırpırella', 'pirpirella-oktay-safak-l6q4k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sekse doymayan 

Bir serçe kanadında üşümekteyim 

Gün batımının kollarında 

Uzanıyor aşk

Dokunduğum her yer 

Ten mavili

Dağ kokusuna bürünmüş bütün 

Kahverengiler çıplak 

Sallanıyor dudaklarında 

Akşam seranat(ı)

Avuçlarında yakamoz 

Gülüşünde mehtap 

İlkbaharına uyanmış 

Bir masal gibi 

Aşikar / bir vuslat

Saçları ay / yıldızı 

Beli karanfil dallı 

Parmak uçlarınla 

Dokun dünyama 

Tenim soluyor../', 'Sekse doymayan  Bir serçe kanadında üşümekteyim  Gün batımının kollarında  Uzanıyor aşk Dokunduğum her yer  Ten mavili Dağ kokusuna bürünmüş...', ARRAY['Türk Edebiyatı','Şiir','Oktay Safak']::text[], 8.5, '{"poet":"Oktay Safak","poet_slug":"oktay-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/pirpirella-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Attila İLHAN da Ölür...', 'attila-i-lhan-da-olur-suleyman-saylan-imchs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ATTİLA İLHAN DA ÖLÜR...

Eee...

Bu dünya böyledir işte; 

ne hatır tanır ne gönül,

ne zengin tanır ne sefil...

Ne kadar sevinsen de,

ne kadar üzülsen de; 

kimisi doğar,

kimisi doğum gününü, 

yaşlanışını kutlar,

kimisi de ölür

Attila İLHAN da olsa...

Ne şöhret kurtarır insanı,

ne milyonlarca seveni, 

hayranı...

Bu dünyanın düzeni bu; 

sapına kadar ayrımsız,

sapına kadar adil,

köküne kadar, 

baştan tırnağa acımasız...

Zamanı gelince

ya da zamansız; 

padişahlık, ustalık, 

şöhret, maharet, 

iyilik-kötülük vesaire, vesaire...

kurtaramaz insanı.

Attila İLHAN da ölür,

her canlı gibi.

Zamanlı ya da zamansız,

sen de, ben de öleceğiz

Canlıysak eğer! 

Süleyman SAYLAN

İzmir, 12-19.10.2005, Saat: 10.48-11.20', 'ATTİLA İLHAN DA ÖLÜR... Eee... Bu dünya böyledir işte;  ne hatır tanır ne gönül, ne zengin tanır ne sefil... Ne kadar sevinsen de, ne kadar ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/attila-ilhan-da-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar çiçeğim', 'kar-cicegim-suleyman-yavuz-fj0t8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen bende ki bir kar çiçeğiydin

Yaz kış bende açardın 

Mutluluk ve neşe saçardın

Bir durdun sanki

Soldun sanki çiçeğim

Sarardı rengin 

Nerede o eski parlak rengin

Bembeyaz el değmemiş tenin

Kayboldu birden kar çiçeğim

Anladım yıllardı onu solduran 

Anladım herkes solacaktı bir gün

Ben bile

Ama sen gittin gideli kar çiçeğim 

Kardelenim benim sen gittin ya

Kimin umurunda geçen yıllar 

Biten hayatlar 

Sen gittiğinden beri 

Bende soldum inan 

Seni çok özledim çiçeğim 

Bekle bende bir gün sana geleceğim

Bekle kardelenim 

Kar çiçeğim', 'Sen bende ki bir kar çiçeğiydin Yaz kış bende açardın  Mutluluk ve neşe saçardın Bir durdun sanki Soldun sanki çiçeğim Sarardı rengin  Nered...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kar-cicegim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kredi Kartı Mağdurunun Duası', 'kredi-karti-magdurunun-duasi-hakan-kilic-f1a0p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karides yedim ben,yetmedi simit

Bir vardı,on aldım savurdum saçtım

Girdi en sonunda dolunca limit

Yıkıldım adeta,sonuca şaştım

Sadece limit mi? Haddimi aştım

Ne yaptım diyerek kafama vurdum

İş işten geçtikten sonra,ulaştım

Sorumsuz davrandım,boşa savurdum

Değilmiş meğer,borç yiğide kamçı

İçini kemiren,bir lanet virüs

Kıvrandıran spazm,ölümcül sancı

Aptallık,salaklık,bu bir düpedüz

Yasal tefeciler bekler başımda

Bir leşe üşüşmüş,akbaba gibi

Ne yaptım kendime,bu genç yaşımda

Eloğlunu bildim,akraba gibi

Uzanan ayağım yorganı aştı

Minumum,asgari,ödenmez oldu

Çıkamaz oldum ben,Allah''ım şaştı

Bindikçe faizler ışığım soldu

Dualar ederim faizler insin

Emeğim faize gider bitmiyor

Dilerim artık bu dertlerim bitsin 

Ya Rabbim bu hayat böyle gitmiyor

Düştüm imansıza yardım isterim

Eritdi namussuz emeklerimi

Körelir artık bu iyi hislerim

Mevlam hayra çıkar dileklerimi

Hakan''ım feryadı inler mağdurun

Kulaklar duyuyor,gözler görmekte

Yardım et devletim bunu durdurun

Tükenmiş insan yaşarken ölmekte', 'Karides yedim ben,yetmedi simit Bir vardı,on aldım savurdum saçtım Girdi en sonunda dolunca limit Yıkıldım adeta,sonuca şaştım Sadece limit ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kılıç']::text[], 8.5, '{"poet":"Hakan Kılıç","poet_slug":"hakan-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kredi-karti-magdurunun-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla', 'anla-oktay-safak-zhh04', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Titrek bir el Ürkekliğinde tanıdım seni

Adı günah../ Adı yasak../ Adı telaş... 

Nasılsa Bütün mektupların Dili mavi 

En sonunda Yine sahipsiz Kalacak o aşk... 

Bırak kelebeğin kanatlarında 

Dönsün dünya

Sen yine ayıp gibi 

Öp beni 

Kanasın 

Ellerindeki çığlık... 

Sal gemilerini 

Zamanı kemiren dudağa 

Zaten bir mevsim gibi 

Girdin kanıma 

Ne olur ölüm gibi 

Bakma bana 

Ne ayrılığa koşmaya 

Gücüm var 

Ne de bu sevdaya 

Beni anla../', 'Titrek bir el Ürkekliğinde tanıdım seni Adı günah../ Adı yasak../ Adı telaş...  Nasılsa Bütün mektupların Dili mavi  En sonunda Yine sahipsi...', ARRAY['Türk Edebiyatı','Şiir','Oktay Safak']::text[], 8.5, '{"poet":"Oktay Safak","poet_slug":"oktay-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anla-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç', 'saklambac-oktay-safak-y6i4x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesinde yangın saklayan bahar 

Uyan delirmeye hazır aşk! 

Artık her gülüşüne 

Muştu yazgılayacak sabah 

Gerisi ölümü mühürleten gözlerinde 

Gerisi kıyamet edimlerinde! 

Öpüşür su üstüne yazılan 

Bütün masallar 

Kırık bir dudağın çatlak aralığında 

Bileklerimde kızıl bir intihar

Yeterki sen ay''sız gecelerde hiç yıldızsız kalma 

Yüzünü / yüzüme sür sevgili 

İliğimde bir mevsim ağlıyor her yanı deli 

İstersen avuçlarımdaki rüzgara dokun 

Kimliksiz üşürsün / arama güneşi 

Mehtaba perde çekiyor / kollarındaki yıldız 

Düğümleniyor firarımdaki gül dikeni 

Düşlerimi çizsemde üç nokta diplerine 

Kirpiklerin fırtına

Hırpala aşkı

İtibarını kaybetti mavi../', 'Sesinde yangın saklayan bahar  Uyan delirmeye hazır aşk!  Artık her gülüşüne  Muştu yazgılayacak sabah  Gerisi ölümü mühürleten gözlerinde  ...', ARRAY['Türk Edebiyatı','Şiir','Oktay Safak']::text[], 8.5, '{"poet":"Oktay Safak","poet_slug":"oktay-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/saklambac-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazan''a', 'nazan-a-mehmet-ayhan-gunaydin-hocx2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'NAZAN! A

Sen; 

Çocuklarımın anası.

Sen; 

Can yoldaşım.

Sevgilim, aşkım, sırdaşım, 

Ve en iyi arkadaşım.

Sen; 

Geceme dolunaysın,

Günüme zevalde güneş.

Sen; baharımsın. Sen; yazım.

Ve sen,

Sonbaharımda, kışımda da

Yanımda olasın.

Bin ömür verseydi eğer Tanrım.

Seninle paylaşırdım.

Aşkım.

Sevgili karım.

M. Ayhan Günaydın.

   26 Şubat 2004

         Ankara', 'NAZAN! A Sen;  Çocuklarımın anası. Sen;  Can yoldaşım. Sevgilim, aşkım, sırdaşım,  Ve en iyi arkadaşım. Sen;  Geceme dolunaysın, Günüme zeva...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nazan-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Bozkırda Kuş Ötüşleri...', 'bozkirda-kus-otusleri-naime-erlacin-18a08', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'süt kokusu duyarız bozkırda

çayır çekirgeleri

tarla kuşu

ve kevenlerin rüzgâr dansında

gölgeleri sorarız 

saydam güz ikindisinden

soprano vurur kuş ötüşleri

yalın bir aksisedâdır ses

geçmiş yazların mahmur seherinden

müthiş bir 

su dağı olma özlemi yüreğimizde 

kıpır kıpır

biliriz 

orası bizimdir

savrulur kalp öğrendiğinde

elmasın salt elmasla şekillendiğini

geceleri ağladığını ayçiçeklerinin

aşkın kanaviçesi kaplar havayı

izini bırakır ince sis

vaatkâr birer çığlığa dönüşür şakımalar

ki açlığımızdır

kim doyurur çocukları 

analar olmasa

aşıkları

kim? 

.....! 

yitik elması arayan şairler

ve hazan sarısı toprak

ve bozkır...

(17 Ekim 2005)   

(2006 Yeni Şiirler Antolojisi - S''İMGE Yay.)', 'süt kokusu duyarız bozkırda çayır çekirgeleri tarla kuşu ve kevenlerin rüzgâr dansında gölgeleri sorarız  saydam güz ikindisinden soprano vu...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bozkirda-kus-otusleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-gonul-ozdemir-v0qia', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoksun

Gurbetellerde ömrüm tükendi

Sevdam uğrunda çilem hiç bitmedi

Kader sonunda yollarımızı birleştirdi

Seni buldum yoksun,yine yanımda yoksun.

Nice yılları tüketip geldim

Sevdan uğrunda bir ömür verdim,

Bu ne tükenmez bitmez çile

Seni buldum  yoksun, yine yanımda yoksun.

Yaşamaya yok artık eski gücüm,

Bırak bizi bulsun artık ölüm

Bitmez tükenmez çileler düştü payımıza,

Seni buldum yoksun,yine yanımda yoksun...

30.4.2005. Gönül Özdemir

Bergkamen

[email protected]', 'Yoksun Gurbetellerde ömrüm tükendi Sevdam uğrunda çilem hiç bitmedi Kader sonunda yollarımızı birleştirdi Seni buldum yoksun,yine yanımda yo...', ARRAY['Türk Edebiyatı','Şiir','Gönül Özdemir']::text[], 8.5, '{"poet":"Gönül Özdemir","poet_slug":"gonul-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yoksun-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimliğimiz İ n s a n l ı k', 'kimligimiz-i-n-s-a-n-l-i-k-ozkan-sahin-ggvz6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'esaretiyle yaşam

esir aldı bizi

köle olduk kör köle

yönetti hepimizi.

_____görmedik göremedik

_____didik didik dedik

_____tutsak olduk ölüme

_____ölüp ölüp dizildik.

tarih, ilim, bilim, din

hep oldu bir filim

bing-bang teorisini

kabul de edelim.

_____yıldızlar kaydırdınız

_____kaymadığı halde

_____güneşler doğurdunuz

_____dünya dönerken gün de

kendi yalanımıza 

kendimiz inan dık

çıkarımıza göre

saçma sapan davran dık

_____en büyük kaosları

_____cahillik ten aldık

_____el ele tutuşmayı

_____nedendir? anlamadık.

aşk, bir duygu dedik

içine de ettik

yaşamın aşk''ıyla

ölmeyi de seyrettik.

_____zengin, fakir hep köle

_____kendi kendimize

_____cahiller atar para

_____kurnaz dilenciye.

kader''in esiriyiz

kendi çizdiğimiz

ele güne bakarız

nedir? bu ettiğimiz.

_____bitmez sefilliğimiz

_____ezilmişliğimiz

_____boğun eğdik yanlışa

_____eğriye hep düz deriz

yaşamın mantığıyla

ölmeyi öğrendik

söyle herşeye rağmen

sevmeyi de öğrendik mi? 

_____tarihe laf atıl dı

_____sor  ırk, dil, din kırık

_____bırakın savaşmayı

_____k i m l i ğ i m i z   i n s a n l ı k.

dünya esaretin de

zaman esiriyiz

sev ki can''ı gönül''den

sürsün kardeşliğimiz.

_____ve son nefesimizi

_____verene dek kalsın

_____İ N S A N l ı k   ölümsüzce

_____A Ş K  edasıyla y a n s ı n.

                                     15-10-2005_16-10-2005', 'esaretiyle yaşam esir aldı bizi köle olduk kör köle yönetti hepimizi. _____görmedik göremedik _____didik didik dedik _____tutsak olduk ölüme...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/kimligimiz-i-n-s-a-n-l-i-k-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reçete', 'recete-h-hikmet-esen-qt9rz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabah,akşam,

Birer kıta 

Şiir okuyacaksın 

Kardeşim.

İki lokma yedikten sonra,

Tok karnına.

Kişinin,

Kendini nasıl gördüğü değil; 

Nasil göründüğü önemli,

Aynalarda...

Yürüyüş yapacaksın,

Sıhhatin için.

Bol Oksijen alacaksın; 

Oksijen''i bulurmusun bilmem

Bu hava kirliliğinde ama,

Biliyorsun,

Hava bedava..

Bir de kardeşim,

Sözcüklerine, yazdıklarına,

Dikkat edeceksin.

Ağzından çıkan,

Her söz,

Kaleminden düşen satır; 

Her adımında,

Demokles''in kılıcı gibi,

Tepende asılı kalır.

H.Hikmet Esen', 'Sabah,akşam, Birer kıta  Şiir okuyacaksın  Kardeşim. İki lokma yedikten sonra, Tok karnına. Kişinin, Kendini nasıl gördüğü değil;  Nasil gör...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/recete-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek İster İnsanca Yaşamaya', 'yurek-i-ster-i-nsanca-yasamaya-h-hikmet-esen-blbeb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneş’in  gölgesini,

Islak dalgalarında,

Taşıyorken 

Deniz; 

Nem yüklü bulutlarına

Kanıp ta ömrün,

Her adımda,

Kaldırım taşlarına

Yağmur değil,

Aslında,

Ter dökmedeyiz..

Rüzgarın Şehvetiyle,

Uçuşurken polenler; 

Sicim gibi damlalarla

Dökülen,

Gözyaşlarımızdır yaşama...

Tutkularımız anı olur bazen,

Umuda savrulurken.

Yiten zamana rağmen,

Görüş mesafesindedir,

Beynimiz; 

Oysa zavallı yüreğimizle,

Kimbilir nerelerdeyiz..? 

Boşver gönül; 

Yetmez bu ömür,

Her tohumda, 

Yeniden var olmaya..

İnsan bir kere doğar ama; 

Yürek ister,

İnsanca yaşamaya..! !', 'Güneş’in  gölgesini, Islak dalgalarında, Taşıyorken  Deniz;  Nem yüklü bulutlarına Kanıp ta ömrün, Her adımda, Kaldırım taşlarına Yağmur değ...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yurek-ister-insanca-yasamaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ölmüş Armut*', 'olmus-armut-ozkan-sahin-psdja', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tüm olgunluğuyla

düştü armut yere

ah! bir de 

orta dan ayrılmasay dı ikiye

tadına varama dı beşer

börtü böcekler, sinekler

bir onlar anla dı

ölmüş armudun tadını

                                   15-10-2005', 'tüm olgunluğuyla düştü armut yere ah! bir de  orta dan ayrılmasay dı ikiye tadına varama dı beşer börtü böcekler, sinekler bir onlar anla dı...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olmus-armut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alem-i devran', 'alem-i-devran-h-hikmet-esen-uyaye', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürek,

Yağmur sıkıntısında

Yağdı, yağacak.

Bulutlar boşaldıkça toprağa,

Güldür,güldür akan su; 

Kimbilir kaç ay sonra,

Hangi gülün

Goncasından,

Can bulup fışkıracak..

Deniz olacak belki,

Karışamayıp taşa toprağa.

Binlerce canı üretecek içinde.

Kah çıkacak gökyüzüne,

İki dirhem, 

Bir oksijen,

Buharlaşıp giderken…

Hava yine yağmurlara gebe; 

Bulutlar, 

Yine çökecek Yeryüzü’ne,

Seyreyle gözüm,

Yaşam, 

Devr-i alemde…', 'Yürek, Yağmur sıkıntısında Yağdı, yağacak. Bulutlar boşaldıkça toprağa, Güldür,güldür akan su;  Kimbilir kaç ay sonra, Hangi gülün Goncasınd...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/alem-i-devran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel gözler', 'guzel-gozler-abdullah-ozcan-gokcen-rmce6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gördüm ama 

Baktım da farkedemedim

gözlerindeki güzelliği

manalıymış meğer

Rengini bu manalı bakıştan alırmış

Yağmur damlası değil

Gözyaşıymış

Güzel gözlerden süzülen.

Kirpiklerindeki nemi 

Öperek kurutmak için 

Ne yapmam lazım.

Karanlıktan geçiyorken

Hissettim gözbebeklerini

ıslanmıştı yine

Aydınlığa erişince güzel gözler.

Sevgiyle bakıyordu

Ama ben farkedemedim

Gözlerindeki  güzelliği

Benimle konuşuyormuş meğer

Güzel gözler.', 'Gördüm ama  Baktım da farkedemedim gözlerindeki güzelliği manalıymış meğer Rengini bu manalı bakıştan alırmış Yağmur damlası değil Gözyaşıym...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Özcan Gökçen']::text[], 8.5, '{"poet":"Abdullah Özcan Gökçen","poet_slug":"abdullah-ozcan-gokcen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guzel-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlerim Seni', 'ozlerim-seni-metin-usengec-pmsxt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özlerim içimden kimseler bilmez 

İsterim anlatamam kendime dahi derdimi

Çok sevdim içimde kaldı hançer gibi 

Doyamadığım zamansız biten hayallerim,sevgim

Sonunu bilemediğim istemediğim bir ömür geriye kalan

Ne kadar uzak olsan da benden, o kadar yakınsın bana sevdiğim..

17-Ekim-2005   11:00

İsterim Seni Daha Sana Doymadım ki; Özlerim Seni Henüz Senden Kopmadım ki..', 'Özlerim içimden kimseler bilmez  İsterim anlatamam kendime dahi derdimi Çok sevdim içimde kaldı hançer gibi  Doyamadığım zamansız biten haya...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlerim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Ülkücü Olmaz', 'benden-ulkucu-olmaz-ramazan-ates-l8156', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ülkü bir kutsal dava,

Benden ülkücü olmaz.

Ülkücü demeyin bana,

Ülkücü uyuşup durmaz.

Zamanla yarış eder,

Sonsuzda fedakardır.

Ömrünü etmez heder,

Faydalı bir insandır.

Okuyup yazandır o,

Boş zamanı hiç olmaz.

Abdestli gezen dir o,

Kini gıybeti bilmez.

Bana ülkücü demeyin,

Benden ülkücü olmaz,

Davayı küçültmeyin,

Yoksa ülkücü kalmaz.

Ramazan Ateş/Enschede-07.02.2003', 'Ülkü bir kutsal dava, Benden ülkücü olmaz. Ülkücü demeyin bana, Ülkücü uyuşup durmaz. Zamanla yarış eder, Sonsuzda fedakardır. Ömrünü etmez ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benden-ulkucu-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zorlaştı Be Dostum', 'zorlasti-be-dostum-ramazan-ates-9thfk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Değer yargıları değişti mi ne dersin? 

Mert olarak yaşamak zorlaştı be dostum.

Yağcılık yapmadan, eğilip bükülmeden,

Dürüst insan kalması zorlaştı be dostum.

Yamuksan değerli, yağcı isen saygılı,

Kaypak isen gözdesin, kalleşe itibar,

İki yüzlülerin toplumda yeri artar,

İyi bir insan olmak zorlaştı be dostum.

Hayatın zorlukları hep üst üste gelir,

Dürüst olanı kim artık bir değer verir? 

Menfaati yoksa bekle ki selam verir,

Bu halde iyi kalmak zorlaştı be dostum.

Bu zamanda yaşamak zorlaştı be dostum.

Ramazan Ateş/Enschede-04.09.2002', 'Değer yargıları değişti mi ne dersin?  Mert olarak yaşamak zorlaştı be dostum. Yağcılık yapmadan, eğilip bükülmeden, Dürüst insan kalması zo...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zorlasti-be-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amorti Sevdalar', 'amorti-sevdalar-osman-karatas-blza9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Onu Kaf Dağımda bıraktığımda,

Ayyüzü, karanlığa bakıyordu.

Yüreğimde aşkı her tadışımada,

Karayüzüm, Mevlaya dönüyordu.

O, cesur cesur hayata yürüdü,

Yaşamına intihar süsü verdim.

Bedenimi, ondan öte aşklar bürüdü,

Titrek adımlarla, Rahmana erdim.

Amorti sevdalar birer basamak,

Gerçeğe yürürken merdiven oldu.

Suretten, suraatla aslına varmak,

Aşk ile secdeye varmakla oldu.', 'Onu Kaf Dağımda bıraktığımda, Ayyüzü, karanlığa bakıyordu. Yüreğimde aşkı her tadışımada, Karayüzüm, Mevlaya dönüyordu. O, cesur cesur hayat...', ARRAY['Türk Edebiyatı','Şiir','Osman Karataş']::text[], 8.5, '{"poet":"Osman Karataş","poet_slug":"osman-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/amorti-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım.', 'yalnizim-ramazan-ates-dp4vq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızım...

Aylar yıllar geçsede,

Yaşım, işim bitsede,

Bir düşman, bin dostum olsada benim,

Yalnızım.

Yalnızım...

Yaşıyorum bomboş şu dünya,

Kimsesizim, yalnız görünüyor rüya,

Sevdiğim çok, gönlüm boş benim,

Yalnızım...

Yalnızım...

Kimse yok boş dünyamda,

Güzel kimse gönlüm onda,

Çok güzelde gönlüm olsada benim,

Yalnızım...

Yalnızım...

Geçsede günler,

Haftalar, hatta mevsimler,

Yollar yıllar bitsede,

Sevsemde bütün dünyayı ben

Yalnızım, yalnızım bilmem ki neden? 

			Nevşehir/1983', 'Yalnızım... Aylar yıllar geçsede, Yaşım, işim bitsede, Bir düşman, bin dostum olsada benim, Yalnızım. Yalnızım... Yaşıyorum bomboş şu dünya,...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalnizim-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İş İşten Geçti', 'i-s-i-sten-gecti-ramazan-ates-l8zhj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi dünyasının tireni kaçtı,

Çok pişmanım amma iş işten geçti.

Umut bir küçük  kuş elimden uçtu,

Çok pişmanım amma iş işten geçti.

Cahildim ben, gençtim delikanlıydım,

Yarı deli dolu, yarı baygındım.

Dur diyende oldu kulak asmadım,

Çok pişmanım amma iş işten geçti.

Bu günleri düşünmedim  yaşadım,

Neşeli, zevkli, biraz hoppaydım,

Zevk için günleri boşa harcadım,

Çok pişmanım amma iş işten geçti.

Bir işe giremem yaşlı diyorlar,

Okumak istesem geçti diyorlar,

Arkadaş senin iş bitti diyorlar,

Çok pişmanım amma iş işten geçti.

Öğüdüm gençlere okusun onlar,

İmanı kalbine dokusun onlar,

O zaman sevilir kıymeti artar,

Çok pişmanım amma iş işten geçti.

Ben pişmanım amma iş işten geçti.

			Enschede/22.02.1998', 'Sevgi dünyasının tireni kaçtı, Çok pişmanım amma iş işten geçti. Umut bir küçük  kuş elimden uçtu, Çok pişmanım amma iş işten geçti. Cahildi...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/is-isten-gecti-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emir Verdim', 'emir-verdim-ramazan-ates-x9a64', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben gönlüme emir verdim,

Sevmeyecek bundan sonra.

Yalan yanlış her sözlere,

Kanmayacak bundan sonra.

Acı keder hep yasadı,

Ömrünce sevgi aradı,

Güzellere boşa yandı,

Yanmayacak bundan sonra.

Ayrılığı çok yaşadı,

Sızım sızım sızıladı.

Kadın gördü, kıza baktı,

Bakmayacak bundan sonra.

Yeter artık hep eridi,

Lime lime hep çürüdü,

Gel dediler hemen gitti,

Gitmeyecek bundan sonra.

Yalan, yanlış, sahte sevgi,

Bulamadı kendi dengi.

Nefret etti cana yetti,

Yetmeyecek bundan sonra,

Sevmeyecek bundan sonra.

Enschede, 13.10.2005', 'Ben gönlüme emir verdim, Sevmeyecek bundan sonra. Yalan yanlış her sözlere, Kanmayacak bundan sonra. Acı keder hep yasadı, Ömrünce sevgi ara...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/emir-verdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yer göstericisi', 'yer-gostericisi-zati-erbas-ii5tq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YER GÖSTERİCİSİ

Penceremden gözüken dört duvara bakıyorum saatlerdir. 

Ne resimler çizdim bilseniz evlerinizin dışa açılan odalarına.

Sessiz ve kimsesiz duran zaman,karla karışık  yağmur olarak dökülüyor fark ettin mi? 

Anlamsız anlamlar yükledim ayak izlerine.

Hiç bir yere ulaşmadıklarını fark ettim birden bire,sana ulaşmadıklarını.

Çöp kovalarına açılan kapılardan geçtim manava da,fırına da giderken.

Sonra ekmeğin sıcaklığını duydum bedenimde; tok olmanın sıcaklığını. 

Soğuk; suyun kayaların incecik çatlaklarına sızması gibi sızıyor parmak uçlarıma:

Her dokunuşu ellerinin ellerime  un ufak ediyor kuşları. 

Telaşsız bir güneş var üstümde.

Sokaklarda ayna kırıkları ve kaygan zamanlarda mutlu olanlar sadece çocuklar sanki. 

Kavgasız geçen bir tek günümüz olmadı mı? 

Olmadı.

Koca bir kayanın parçalanması gibi parçalandık. 

Nereye gideceğimi bilmiyorum.

Bu kadar kısa mı sürecekti yolculuğumuz? 

Deniz kıyısında yalın ayak dolaştığım zamanlar kadar uzaksın bana.

Dünden kalanlarsa kum saati gibi sahil boyunca. 

Oysa sokağın karşı köşesinde parçaları reçineyle tutturulmuş birileri de vardı.

Güneş onlara da bana olduğu kadar uzaktı. 

Soluk alışında donan zamana ışık tuttum bir yer göstericisi gibi.

Şimdi filmin sonundaki gibi ıslak gözlerim.

92', 'YER GÖSTERİCİSİ Penceremden gözüken dört duvara bakıyorum saatlerdir.  Ne resimler çizdim bilseniz evlerinizin dışa açılan odalarına. Sessiz...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yer-gostericisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmayı Unuttum', 'unutmayi-unuttum-ahmet-selcuk-i-lkan-3v1kc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'UNUTMAYI UNUTTUM

Gittiğin gün

Bütün ayrılıkların hesabı benden soruldu

Bütün  acılı şarkıların

Bütün hazin sevdaların

Gittiğin gün 

Her çiçeğe bir gözyaşı

Her kelebeğe bir ağıt

Bana da yüzlerce şiir düştü

Yazmaya mahkum

Gözlerin için...

Ben ki

Dönüşüne hasret yaşadım bütün nisanları

Ve gülüşüne hasret bütün baharları

Gel gör ki

Bir dağa çarpar  gibi çarptı yüreğim yokluğuna

Bir ben bilirim

Gururumu hangi taşlara vurduğumu

Başımı hangi duvarlara

Ve hangi uçurumlara köprüler kurduğumu

Bir sana kavuşmak için

Sen gideli

Bütün yollarımın yolları kesik

Bütün dallarımın dalları kırık

Kaç geceye bekçi

Kaç sabaha nöbetçi

Ve kaç uykusuz trene biletçi oldum

Gelmedin

Oysa hep karlar içinde sakladım umutlarımı

Yağmurlar içinde kuruttum göz yaşlarımı

Ve kanatarak açtım gölgene avuçlarımı

Bir sana sarılmak için

Bir ucu kalbimde kaldı bu sevdanın

Bir ucu ellerinde

Bir adımı sende kaldı sonumun

Bir adımı sabrımda

Çünkü

Bulutlara çizilmiş

Yıldızlara yazılmış

Ve yüreğime kazılmış bir kara sevdaydı  bu

Günlerce

Kışlardan  güneş

Karlardan ateş topladım

Ve bütün ölümleri erteledim

Bir sana dokunmak için

Oysa daha gittiğin gün

Uykularımı çaldım göz bebeklerimden

Dizlerimde uyuttum

Acılarımı kopardım yüreğimden 

İzlerinde avuttum

Ve sözümü de tuttum

Yanarak için için 

İşte bugün

Unutmayı da unuttum

Bir tek seni 

Unutmamak için....

		Ahmet Selçuk İLKAN

“Erkekler hep yalnız ağlar”.kitabından

www.ahmetselcukilkan.com.tr', 'UNUTMAYI UNUTTUM Gittiğin gün Bütün ayrılıkların hesabı benden soruldu Bütün  acılı şarkıların Bütün hazin sevdaların Gittiğin gün  Her çiçe...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/unutmayi-unuttum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Henüz Kurumadım', 'henuz-kurumadim-abdullah-ortak-6my60', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pembe günaydınlara dokundu karanlık

Siyaha büründü gün

Ve gece iniyor usul usul gökyüzünden

Ve damla damla üşüsüyor yağmur pencemin denizliğine

Sen yoksun

Gece karanlık

Ve bedenim ıslak

Farkında değilim yağmur altında kalbim

Sonra

Bir sokak lambasına ilişiyor gözlerim

Damla damla süzülüyorum huzmelerinden

Ve Kaldırım taşlarını ıslatıyorum

Gecenin orta yerinde bela sarıyor, yakıyorum

Sonra sular geçiyor ayaklarımın altından,

Faili meçhul aşklar mı yağmurun süpürdüğü

Tövbesiz günahlar mı  yıkadığı

Onlara takılıyorum

Sen  yoksun,

Endişeleniyorum

Hangi uzak gecenin koynunda yatmakta,

Hangi geceye akmaktasın

Bir sis

 ve bir ünlem

 ve bir soru işaretiyle belki

Tanımlayamadığım perdenin ötesinde

Pembe sabahlara uzanmaktasın

Günaydın diyeceğim ama

Henüz gece kesmedi sütünü karanlıktan

Güneşi alamadım avuçlarıma

Ve her şeyden öte Sen Yoksun

Ve Yağmur çekmedi ellerini benden

Henüz kurumadım

Abdullah ORTAK –Islak  Bir Eylül Gecesinden

 (msn: [email protected])', 'Pembe günaydınlara dokundu karanlık Siyaha büründü gün Ve gece iniyor usul usul gökyüzünden Ve damla damla üşüsüyor yağmur pencemin denizliğ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/henuz-kurumadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Yangın', 'i-cimdeki-yangin-ramazan-ates-0do0f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimdeki yangını söndüremiyorum,

Alev alev yakıyor içimi,

Elim kolum tutmaz oldu,

Parçalamak istiyorum kendimi.

Beni yakan kin mi? Nefret mi? 

Zarar mı vermeliyim bir şeylere? 

Bende olmayan mal mı? Servet mi? 

Göçüp gitmeli miyim yoksa bir yerlere? 

Gururum yerlerde süründü durdu,

Yal verdiğim hayvan beni sırtımdan vurdu.

Sevmezdim böyle karalar baglamayı,

Sevmezdim bir köşede oturup ağlamayı.

Beni once bilen şimdi tanımaz.

Olanı anlatsam kimse anlamaz,

İçimdeki yangını söndüremiyorum,

Geçmiş zamanı geriye döndüremiyorum.

Enschede, 12.10.2005', 'İçimdeki yangını söndüremiyorum, Alev alev yakıyor içimi, Elim kolum tutmaz oldu, Parçalamak istiyorum kendimi. Beni yakan kin mi? Nefret mi...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/icimdeki-yangin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın Gelen Sonbahardı Gözlerin', 'ansizin-gelen-sonbahardi-gozlerin-abdullah-ortak-pgx0l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ansızın gelen sonbahardı gözlerin

Ve döküldü yaprakları ömrümün damla damla,

Matem havasında bir şeyler var hissettiğim

hüzünle dökülüyor saçların omuz başlarına

ve binbir bilmeceyle düşüyor perçemleri yüzünü

kalbimin dinmeyen sızılarından sızarak

Kıvrılarak girdiğini hissediyorum 

Değil bedenim, değil tenimden,

Ruhumdan içerde bir yerlere sokulduğunu

.ve içimi aysız gecelerle doldurduğunu

Hadi susma

Konuş benimle,

Gitmen gerektiğini söyle,

Yağmala ömrümün sensiz geçecek geceleri de

Senden bir şey kalmasın geriye, 

Savur küllerimi en ulaşılmaz sandığın yerine,

..ve ben

Öleyim

Bir daha dirilmeden, 

Zerreciklere ayrılsın ruhum sende

El ayak çekilsin odanın aya bakan penceresinde

Bir daha süzülmesin hüzmeler,

Ben dokunamaz olayım bu kadar uzaklardan gözlerine

Ben seni böyle bilmedim

Ben bu şehri böyle düşlemedim,

Bir çiçeğin kirpik uçlarından,

Böyle düşmemeliydim

Abdullah ORTAK / 2005

 [email protected]', 'Ansızın gelen sonbahardı gözlerin Ve döküldü yaprakları ömrümün damla damla, Matem havasında bir şeyler var hissettiğim hüzünle dökülüyor sa...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ansizin-gelen-sonbahardi-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkekler Hep Yalnız Ağlar', 'erkekler-hep-yalniz-aglar-ahmet-selcuk-i-lkan-mkx23', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ERKEKLER HEP YALNIZ AĞLAR

Günlerdir sınırında yaşıyoruz aşkın

Günlerdir uçurumunda

Bu kaçıncı atışım kendimi

Kollarından yalnızlığa

Bu kaçıncı dargınlık

Bu kaçıncı barışma

Belli ki

Sensizliğe sürgün artık bu gözler

Sensizliğe sürgün bu dudaklar bu eller

Şimdi yorgun bir çınar gibi kalbim

Artık sana değil

Sensizliğe yaslanacağım

Hoşçakal güz çiçeğim hoşçakal

Seni artık

Göz yaşlarınla ıslanmış

Yastıklara bırakacağım

Oysa yıllarca

Yemyeşil bir orman köyünde sakladım gözlerini

Dağ başlarında çoban ateşleri yaktım üşümeyesin diye

Ellerine kör gecelerin karanlığında sarıldım

Ve haykırdım

En dipsiz kuyulara adını

Ezberlettim seni kurtlara-kuşlara

Sense beni sokaklara vurdun

Ve en zehir şarkılara

Bilirsin

Rüzğara bıçak

Yağmura ateş

Buluta kurşun işlemez

Sende öylesine vurdun ki beni

Artık bana

Hiçbir acı kar etmez

Neylersin 

Önce melekler terk etti bizi

Sonra masmavi düşler

Öpüşler- gülüşler-çiçekler

Büyüsü kalmadı artık kavuşmaların

Bundan böyle

Bizi her köşede

Bambaşka bir cehennem bekler

Sen de bundan böyle

İçi boş şarkılarla avut kendini

En ucuz aşklarla yıka kirli ruhunu

Açılırsın

Taşlar yosuna sarılır bilirsin

Sarmaşıklar duvarlara

Geceler karanlığa

Sende yalnızlığa sarılırsın

Ve kadınsın

Ağlayabilirsin gönlünce

Göz yaşların pınarlar misali çağlar

Unutma ki erkeğim ben

Ve erkekler hep yalnız ağlar.

		Ahmet Selçuk İLKAN

“Erkekler hep yalnız ağlar” kitabından

www.ahmetselcukilkan.com.tr', 'ERKEKLER HEP YALNIZ AĞLAR Günlerdir sınırında yaşıyoruz aşkın Günlerdir uçurumunda Bu kaçıncı atışım kendimi Kollarından yalnızlığa Bu kaçın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/erkekler-hep-yalniz-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koklarsam Namerdim', 'koklarsam-namerdim-ramazan-ates-t3bhv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sen kalsan dünyada gül olarak,

Koklarsam namerdim, koklamam seni.

Deseler ki sana yoldaş olacak,

Beklersem namerdim, beklemem seni.

Üzüntün kederin onla bitecek,

Sıkıntın kalmayıp, yüzün gülecek,

İlaçtır derdine derman olacak,

İstersem namerdim, istemem seni.

Pişmanmış yaptığına özür diliyor,

Gelmezse ölecek ille geliyor,

Hatta kapında kölen oluyor,

Beslersem namerdim, beslemem seni.

İyi gün dostuna meylim yok artık,

Yok ettim, unuttum, benden çık artık.

Ağzınla kuş tutsan faydasız artık,

Dinlersem namerdim, dinlemem seni.

Gözümden yaşları boşa dökmedim.

Yalvardım, yakardım ne dil dökmedim,

Sana mı? İllallah neler demedim,

Dilersem namerdim, dilemem seni.

Desen ki bana bir kelime söyle,

İstersen deli de, bagla zincirle,

Cehennem yakacak yolumdan eyle,

Eylersem namerdim, eylemem seni.

Cehennem atesi yakarken görsem,

Elini uzatıp imdat dilesen,

Üfleyince hemen ateşi sönsün,

Üflersem namerdim, üflemem sana.

Ayrılık ateşi beni yakacak,

Gözlerim hasretle başka bakacak,

Adını söylersem herşey bitecek,

Söylersem namerdim, söylemem seni.

Enschede, 12.05.2005', 'Bir sen kalsan dünyada gül olarak, Koklarsam namerdim, koklamam seni. Deseler ki sana yoldaş olacak, Beklersem namerdim, beklemem seni. Üzün...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/koklarsam-namerdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tandırın kızı', 'tandirin-kizi-yusuf-ziya-leblebici-saqi8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elinde oklava açar yufkayı

Gözleri sürmeli tandırın kızı

Sıcaktan kavrulup açar yazmayı

Yüzleri gamzeli tandırın kızı

Kırmızı basmadan giymiş eteği

Özenip pişirir yağlı bükmeyi

Tezekten samandan besler ateşi

Köyümün güzeli tandırın kızı

Başında sevdanın yelleri eser

Gönlünde aşkının gülleri biter

Yolları beklerken hasretlik çeker

Toprağın çiçeği tandırın kızı

Kınalı avuçta döner oklava

Peynirli hamurdan pişer bazlama

Kızgın ateş vurur yanaklarına

Hamurun bezesi tandırın kızı

Hamur tablasına aşkını çizer

Unlar arasında kendinden geçer

Tandır havasında erişte biçer

Gözleri sürmeli tandırın kızı', 'Elinde oklava açar yufkayı Gözleri sürmeli tandırın kızı Sıcaktan kavrulup açar yazmayı Yüzleri gamzeli tandırın kızı Kırmızı basmadan giymi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tandirin-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satırlarıma Kan Damlıyor', 'satirlarima-kan-damliyor-sadik-dogan-2rd5g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgilim; 

acı biberim 

şekersiz çayım 

tuzsuz çorbam 

ne zaman güldüreceksin yüzümü 

benim olacaktın hani, ne zaman 

son sigaramı da içiyorum gözyaşları içerisinde 

fitile dayandı artık ateş 

satırlarıma kan damlıyor 

duymuyor musun? 

Sevgilim; 

kanlı gömleğim 

kelepçeli bileğim 

kırık yüreğim 

ezik bir ses ile haykırıyorum sana 

ahtı çıkmış gözlerime bak 

bak da gör yaşarken ölmenin ne demek olduğunu 

yüreğime sapladığın hançeri geri al 

hiçbir izin kalmasın cesedimde 

adam öldürmenin ne demek olduğunu 

bilmiyor musun? 

Sevgilim; 

tutmayan yanım 

akmayan kanım 

kapısız hanım 

kilidini kır artık, kör düğüm olmuş 

anahtarını çoktan kaybettim 

senin ellerinde tüm akıbetim 

amansız bir yara olmuşum 

görmüyor musun? 

Sevgilim; 

kısık gülüşüm 

vatansız ölüşüm 

dara düşüşüm 

yolunu kaybetmiş bir turnayım 

uzak kalmışım vatan ocağında 

hasretim sana ana kucağında 

gayri yaşayamam artık 

öl, de öleyim 

neden susuyorsun neden 

yoksa sen beni 

sevmiyor musun? 

Sevgilim; 

karanlık çağım 

boş yatağım 

başsız otağım 

gel demeyecek misin artık gel 

cennetinde yer yok mu bana 

mezarını talan etti bu hainler 

ahrette de kavuşmamız yasakmış 

yoksa sen, bu yalanlara 

inanıyor musun? 

16.10.2005/Osmancık', 'Sevgilim;  acı biberim  şekersiz çayım  tuzsuz çorbam  ne zaman güldüreceksin yüzümü  benim olacaktın hani, ne zaman  son sigaramı da içiyor...', ARRAY['Türk Edebiyatı','Şiir','Sadık Doğan']::text[], 8.5, '{"poet":"Sadık Doğan","poet_slug":"sadik-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/satirlarima-kan-damliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatıcının Yaşamak Derdi', 'anlaticinin-yasamak-derdi-gultekin-mustafa-fpg5h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'farkında olmamanın farkında olmak

işte size önemli bir mesele

bir düşünsenize günlerinizi

sabah haberleriyle başlayıp

gece özetleriyle biten

asfalt yollarda şerit değiştirmekle

bir sürü gereksiz evrakı oradan oraya

yetiştirmekle

 birer birer harcarsınız

kaç hakkınızın kaldığını dahi bilmeden

saatin içindeki sayılı kum taneciklerini

yaşamakta olduğunun farkında olmak

işte size daha önemli bir mesele

ey insan

ey bitişi önceden belli bir yolun 

şaşkın yolcusu

farkında mısın yaşadığının

kaç türlü duyguyu anlayıp

kaç türlü çiçeği koklayacağının

ey insan

 “şimdi”den daha iyi bir zamanın olmayacak

farkındasın değil mi?', 'farkında olmamanın farkında olmak işte size önemli bir mesele bir düşünsenize günlerinizi sabah haberleriyle başlayıp gece özetleriyle biten...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anlaticinin-yasamak-derdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlam gayırmış', 'mevlam-gayirmis-sair-ahbaboglu-4aqw2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben seni severim ta ezelden,

Mevlam gayırmış gülüm seni.

Sensiz olursam ölürüm kederden,

Mevlam gayırmış gülüm seni.

Ben seni sevdim de sen n''aptın,

Gittin başkasıylan dolandın,

Beni hergün ateşlere attın,

Mevlam gayırmış gülüm seni.

Bir gaşı var gören yay sanır,

Gözlerini görenler sanki ok sanır,

Halim gören bende can yok sanır,

Mevlam gayırmış gülüm seni.

Ahbaboğlum çektiğim çile yeter,

Hali benim mecnundan da beter,

Canım her an seni ister, seni bekler,

Mevlam gayırmış gülüm seni.', 'Ben seni severim ta ezelden, Mevlam gayırmış gülüm seni. Sensiz olursam ölürüm kederden, Mevlam gayırmış gülüm seni. Ben seni sevdim de sen ...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahbaboğlu']::text[], 8.5, '{"poet":"Şair Ahbaboğlu","poet_slug":"sair-ahbaboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mevlam-gayirmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nar Suyuna Kandığım Geceler', 'nar-suyuna-kandigim-geceler-ahmet-nural-ozturk-8w0lu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocukluğumun bayramları

Bahçemizdeki nar ağacının çiçek açışı

Nar suyuyla kandığım geceler

İlk bisikletimin oluşu

Okula başladığım Eylül''ün sabahı

Kendimden sakladığım gençliğim

Sevdiklerimin teker teker terkedişi

Hüzünler ve sevinçler 

Bulutların sınır tanımaz dostluğu

Çoban yıldızına türkü söyleyişim

Genlerimin ilk aynasına bakışım

Ve mezar yerimi alışım

İşte benim aşklarım

Unutur muyum onları

Anımsamam mı rüyalarımı

Vedasız olsa bile gidişim

Sen olmasan da yanımda', 'Çocukluğumun bayramları Bahçemizdeki nar ağacının çiçek açışı Nar suyuyla kandığım geceler İlk bisikletimin oluşu Okula başladığım Eylül''ün ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nar-suyuna-kandigim-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-hilal-ozdemir-kye82', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Serseri gibi yollara vurdum kendimi

Kaldırımlar inledi acımdan

Ve sen ince bir sızı geçtin içimden

Ağıtlar nehir akıyor yüreğimden

Akıyor nice günler haftalar aylar sensiz

Sessiz bir melodi gibi inliyor hayat

İşte sonbahar yine hüzün

Ayrılık gözlerinden sözlerinden ve senden...

(27.9.2005)', 'Serseri gibi yollara vurdum kendimi Kaldırımlar inledi acımdan Ve sen ince bir sızı geçtin içimden Ağıtlar nehir akıyor yüreğimden Akıyor ni...', ARRAY['Türk Edebiyatı','Şiir','Hilal Özdemir']::text[], 8.5, '{"poet":"Hilal Özdemir","poet_slug":"hilal-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayrilik-295-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yargı Çemberi', 'yargi-cemberi-aysel-zengingul-3db42', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'öznesiz kalmış bir cümleyim

söylenmeye hazırlıklı,

kerpiç duvar misali dağılmaya meyilliyim

            tenhasına duruyorum gecelerin,

                 geceler kör kuyu…

hep sana uçurum kalıyorum gittikçe

sebepsiz kırılıyorum inceden inceye

el değmemiş sevdalar biriktirdim 

şehirlerarası kalmış yüreğimde

belki sana verilecek kadar 

ağırlığını taşıdım yüreğimin

şimdi bir kuş kadar uçucu

ne verdiğimden alacaklıyım

ne aldığımdan  verecek pay kaldı

       deniz üstü köpükleri gibiyim şimdi limanlara

       dalga dalga sen oldukça ciğerlerim

       ben ölüme hazırlanıyorum

       sus pus bi körfezde

ve sen hazırlıklı değilsin henüz ölüm haberlerine

gazete afişleri sarmaz seni çay tadında..

yeni sevdalar peşinde koşarsın,

 	sevda denmeyecek kadar çoğul yaşantılarına…

bi gün sende öznesiz kalıp,

bütün kelimelerini anlamsız bulacaksın

ve bilki! 

o an ölüme daha yakın kalacaksın; 

belki de ölmüş....

en fazla acını yada yokoluşunu,

karalar bağlayan dostların; 

bir kaç gün yaşayacak.

ve sen aslında hep yalnız olduğun dünyanda

çoğul yaşasan da, 

hep yalnız kalacaksın; 

işte bu gün gibi…', 'öznesiz kalmış bir cümleyim söylenmeye hazırlıklı, kerpiç duvar misali dağılmaya meyilliyim             tenhasına duruyorum gecelerin,      ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yargi-cemberi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değersiz Dünya', 'degersiz-dunya-emre-uslu-wp51q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk bir kuyu gibidir,

Düştün mü sevdiğinin sana el uzatması gerekir,

Dünya ise onun kazanıdır,

Herkesi yakacak kadar büyük ama paylaşılamayacak kadar küçük,

Ve değerli,

Bazen sevgiye bile değişilebilecek kadar değerli,

Ama o gözler,

Dünya elinde olsa da,

O gözler sana bakmadıkça,

Ve eli elini tutmadıkça,

Ve sevgini paylaşacak bir aşkın yoksa,

O koskoca dünyada tek başınaysan,

Ve kimse sana bakmıyorsa,

Ve ilgilenmiyorsa yardım etmek için bile,

Yapayalnız hissediyorsan,

Ve değersiz,

Eğer bir de bekliyorsan bulmak için gerçek aşkı,

Zaman geçiyor, ama kimse yoksa,

Ne önemi var dünyanın?', 'Aşk bir kuyu gibidir, Düştün mü sevdiğinin sana el uzatması gerekir, Dünya ise onun kazanıdır, Herkesi yakacak kadar büyük ama paylaşılamaya...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/degersiz-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Güzeldir', 'hayat-guzeldir-emre-uslu-blcar', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat

Anlıktır.

Yaşamak,

Anlamsız,

Tadımlık.

Gelecek güzel.

Ürkek bir,

Zambak gibi,

Ellerin.

Leylak kokar.

Düşün her zaman

İyiler kazanır, diye ve

Rahatla..', 'Hayat Anlıktır. Yaşamak, Anlamsız, Tadımlık. Gelecek güzel. Ürkek bir, Zambak gibi, Ellerin. Leylak kokar. Düşün her zaman İyiler kazanır, d...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayat-guzeldir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-emre-uslu-sksrp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Meltem olurum hafif ve sessiz,

Bir çığlık olurum duyulmayan

Ve bir ırmak, kimsenin yaklaşamadığı

Ancak sevgi dolu birinin anlayacağı.

Çöl olurum sıcak, uçsuz bucaksız

Burçak tarlası olurum bire on veren

Ve bir yol sonu her zaman güzel bir yere

Varacağı düşünülen, iki tarafı ağaçlı.

Bir türkü olurum herkesin bildiği,

Bulut olurum memleket memleket dolaşan

Hızır, herkesin yardımına yetişen,

Kim ne zaman istese yanında bulunan.', 'Meltem olurum hafif ve sessiz, Bir çığlık olurum duyulmayan Ve bir ırmak, kimsenin yaklaşamadığı Ancak sevgi dolu birinin anlayacağı. Çöl ol...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-1282-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leylim', 'leylim-emre-uslu-7o7ev', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç bahar geçti, kaç bahar

Bakarken yıldızlara

Görmek yüzünü tekrar.

Seni bulabilmek seni

Sonsuz göklerde,

Seni görebilmek seni

Sonsuz yüzlerde..

Seni aramak seni 

Bulabilmek için

Uçsuz bucaksız çöllerde.

Sana bakabilmek sana

İstediğim kadar

Seni sarabilmek seni

Bırakmayana kadar.

Kaç leylim bahar geçti, 

Güzler geçti, güller geçti,

Bir sen geçmedin gönlümden..', 'Kaç bahar geçti, kaç bahar Bakarken yıldızlara Görmek yüzünü tekrar. Seni bulabilmek seni Sonsuz göklerde, Seni görebilmek seni Sonsuz yüzle...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/leylim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki', 'sanki-emre-uslu-9ncvh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanki, hiç mi acımayacak? 

Sanki, hiç mi bitmeyecek? 

Sanki, hiç mi sevmeyeceğiz tekrar? 

Sanki, her gün üzülmeye devam mı edeceğiz? 

Sanki, hiç mi geçmeyecek zaman? 

Sanki, ölmeyecek miyiz biz de? 

Sanki, çocuklarımıza bahsedecek miyiz yaşadıklarımızdan? 

Sanki, bir daha seni görebilecek miyim? 

Sanki, görsem tanıyabilecek miyim? 

Sanki, sen beni hayatın boyunca bekleyecek misin? 

Sanki, güneş batmayacak mı bir daha? 

Sanki, yakamozları bir daha izlemeyecek misin? 

Sanki, o saçlarını bir daha kimse sevmeyecek mi? 

Sanki, hatıraları tekrar hatırlayacak mısın? 

Sanki, beni özleyecek misin tekrar, benim seni özlediğim kadar? 

Sanki, “beyaz atlı prensini” bulmayacak mısın, benden sonra? 

Sanki, anlamayacak mısın verilen sözlerin yalan olduğunu? 

Sanki, bir daha “sanki” diyebilecek misin bu şiirden sonra? 

Sanki, kendini inandırabilecek misin, beni hiç sevmediğine? 

Sanki, bensiz mutlu mu olacaksın, “mutluyum” diye rol yaparak? 

Sanki, hiç bitmeyecek gibi başlayan hiç bir şey bitmeyecek mi? 

Sanki, bu şiir yaşadıkça sana hayat vermeyecek mi?', 'Sanki, hiç mi acımayacak?  Sanki, hiç mi bitmeyecek?  Sanki, hiç mi sevmeyeceğiz tekrar?  Sanki, her gün üzülmeye devam mı edeceğiz?  Sanki,...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sanki-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen, ben, biz..', 'sen-ben-biz-emre-uslu-7t0vu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hava rüzgarlı, güneşsiz, soğuk,

Yüreğim, acılı, sensiz, sevgisiz

Her yer neden böyle bugünlerde? 

Bana yine göründü yolu İstanbul’un,

Sen geldin aklıma birden,

Nedense? 

Rüzgarlı bir günde 

Bana bakarken gördüğüm sarı saçların

Dalgalınıyordu yine,

Kıskanmıştım rüzgarı.

Yeşil gözlerinden damlalar düşerken

Anlıyordum,

Belki de hayatımda hiç anlamadığım kadar.

Sen geldin aklıma çünkü

Her hafta gözükürken yolu İstanbul’un

Bir acı duyuyorum nedensizce

Çoğu zaman unutuyorum yine,

Neden ben ve sen,

Neden ben ve sensiz,

Neden bizsiz?', 'Hava rüzgarlı, güneşsiz, soğuk, Yüreğim, acılı, sensiz, sevgisiz Her yer neden böyle bugünlerde?  Bana yine göründü yolu İstanbul’un, Sen ge...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-ben-biz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden önce, senden sonra', 'senden-once-senden-sonra-emre-uslu-ustuj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmezdim insanları insan değiller diye,

Sevmezdim kedileri işe yaramazlar diye,

Sevdim insanları, seni görünce,

Sevdim kedileri de, sen seviyorsun diye. 

Ne anlamı var ki yaşamanın, sen olmayınca? 

Ne anlamı var savaştan sonra barışın? 

Ne anlamı var sen olmadığın zaman, aşkın? 

Ne anlamı var İstanbul’un, sen içinde olmadığında? 

Ne anlamı var telefonumun, senle konuşmadıkça? 

Ne anlamı var güneşin, benim güneşim olmadıkça? 

Ne anlamı var bir kızı sevmenin, o kız sen olmadıkça? 

Ne anlamı var yalnız kalmanın, bırakan sen olmadıkça? 

Ne anlamı var yürümenin, yanımda sen olmadıkça? 

Ne anlamı var gözlerimin, sana bakmadıkça? 

Ne anlamı var ellerimin, saçını okşamadıkça? 

Ne anlamı var ki evin, senle yaşamadıkça? 

Ne anlamı var benim, sen olmadıkça?', 'Sevmezdim insanları insan değiller diye, Sevmezdim kedileri işe yaramazlar diye, Sevdim insanları, seni görünce, Sevdim kedileri de, sen sev...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/senden-once-senden-sonra-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana dair', 'sana-dair-emre-uslu-0v8v2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Değemedim sana doya doya,

Solacaksın diye.

Bakamadım sana doya doya,

Nazar değer diye.

“Aşkım! ” diyemedim doya doya,

Aşkımın ömrü kısa diye.

Tutamadım elini doya doya,

Elim kabadır, incitir diye.

Yüzünü okşayamadım doya doya,

Çizgiler oluşur diye.

Seninle yaşayamadığım doya doya,

Yaşlandığını görmek istemedim diye.

Şimdi çok pişmanım,

Yanımda sen yoksun,

Yapayalnız,

Ve de en önemlisi,

Sen yoksun diye..', 'Değemedim sana doya doya, Solacaksın diye. Bakamadım sana doya doya, Nazar değer diye. “Aşkım! ” diyemedim doya doya, Aşkımın ömrü kısa diye...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-dair-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylemek zordur sevdiğine, sevdiğini, eğer gerçekten seviyorsan...', 'soylemek-zordur-sevdigine-sevdigini-eger-gercekten-seviyorsan-emre-uslu-jdf6p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlık aslında koymuyordu bana, 

Yalnızlık

Ama şimdi, 

Sen yoksun yanımda,

-yalnızlık-

Değil bu, 

Daha acı bir şey yalnızlıktan, 

Seni beklemek,

Seni bekliyorum çaresizce,

Ve yalnız  -yapayalnız-

Karar verdim söyleyemiyorum bir türlü, 

-yalnızken bile-

Sevdiğime, -başkasına değil sana- 

Sadece sana,

Seni

Seni ne kadar çok sevdiğimi...', 'Yalnızlık aslında koymuyordu bana,  Yalnızlık Ama şimdi,  Sen yoksun yanımda, -yalnızlık- Değil bu,  Daha acı bir şey yalnızlıktan,  Seni be...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soylemek-zordur-sevdigine-sevdigini-eger-gercekten-seviyorsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var olmak', 'var-olmak-emre-uslu-3ibqz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Var olmak,

Yalnız, yapayalnız,

Yada bir sürü kişiyle,

Neresi olduğu da önemli değil,

Neden yaşadığı da,

Sadece var olmak,

Hiçbir şey düşünmeden,

Hiçbir kaygı yaşamadan,

Bir saniye sonra ne olacağını bilmeden,

Sadece oturmak, ve beklemek,

İhtimalleri bile göze almadan,

Zaten sona ermeyecek mi,

Her güzel şey gibi? 

O zaman neden bu kavgalar,

Neden bu kaygılar,

Neden? 

Madem er geç sonu var,

Her şeyin,

Boş ver her şeyi,

Gel sen de sev kendini,

İnsanların ölümsüzlüğü sevdiği gibi..', 'Var olmak, Yalnız, yapayalnız, Yada bir sürü kişiyle, Neresi olduğu da önemli değil, Neden yaşadığı da, Sadece var olmak, Hiçbir şey düşünme...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/var-olmak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanımda yoksun yine', 'yanimda-yoksun-yine-emre-uslu-8id2y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneş batalı olmuyordu 2 saatten fazla,

Aklım sevdiğimdeydi,

Haber aldım, bana dedi ki; 

“Çok sıkı sarıl bana, 

Bir daha hiç bırakmayacakmış gibi,

Vücutlarımız tekmiş gibi, 

Ellerin belime kenetlenmiş gibi sıkı sarıl,

Ve gözlerin gözlerime..

Gözyaşlarım hep göğsüne damlayacakmış gibi..

Ve öyle uykuya dalalım sevgilim,

Sabah hiç olmayacakmış gibi..”

Cevap verdim çaresizce, dedim ki; 

“Dokunamaz bu ellerim ellerine,

Bakamaz bu gözlerim gözlerine,

Akamaz bu gözyaşlarım göğsüne,

Değemez bedenim bedenine,

Ve şu seni seven kalbim mutlu olamaz,

Yanında sen yoksun diye..”', 'Güneş batalı olmuyordu 2 saatten fazla, Aklım sevdiğimdeydi, Haber aldım, bana dedi ki;  “Çok sıkı sarıl bana,  Bir daha hiç bırakmayacakmış...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yanimda-yoksun-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümseyiş', 'gulumseyis-aysel-zengingul-v97eq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Atmosferine otursam

          Şu koca dünyanın,

Yine fikrime sığmaz haylazlığım.

Gel geç yolcuları izledikçe; 

Gıdıklıyorum avuçlarımı.

Bi hainlik var ki içimde,

Aramızda kalsın,

Ben biraz fena düşünüyorum.

Size denk geldi mi?', 'Atmosferine otursam           Şu koca dünyanın, Yine fikrime sığmaz haylazlığım. Gel geç yolcuları izledikçe;  Gıdıklıyorum avuçlarımı. Bi h...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gulumseyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin..', 'nerdesin-i-lknur-i-din-7wvmd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine içiyorum 

Yine özledim 

Bu acılar sensiz azalmıyor nerdesin 

Nerdesin yağmur rengim 

Reddeden gökkuşağım nerdesin 

Hani rakının suya karışması gibi 

Değince elin elime,nerdesin 

Gözleri zeytin bakan yarim nerdesin..', 'Yine içiyorum  Yine özledim  Bu acılar sensiz azalmıyor nerdesin  Nerdesin yağmur rengim  Reddeden gökkuşağım nerdesin  Hani rakının suya ka...', ARRAY['Türk Edebiyatı','Şiir','İlknur İdin']::text[], 8.5, '{"poet":"İlknur İdin","poet_slug":"i-lknur-i-din","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nerdesin-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem..', 'ozlem-i-lknur-i-din-08g4j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşi kızıla boyayan 

Martıları çığlık çığlık havalandıran 

Geceleri susuzluktan uyandıran 

Yeşili yağmur görünce canlandıran 

Sevgi var aramızda 

Gel susma bir tanem 

Suskunluk özlem getirir bana', 'Güneşi kızıla boyayan  Martıları çığlık çığlık havalandıran  Geceleri susuzluktan uyandıran  Yeşili yağmur görünce canlandıran  Sevgi var ar...', ARRAY['Türk Edebiyatı','Şiir','İlknur İdin']::text[], 8.5, '{"poet":"İlknur İdin","poet_slug":"i-lknur-i-din","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ozlem-265-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret', 'nefret-rukiye-i-rge-nypaj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuk ve sisli bir gündeyim yine,

üşüyorum,ürperiyorum,yürüyorum karanlıkta,

Hatırlamak istemiyorum geçmişimi,

Kötü maziimi.

Yeni bir sayfa açmak istiyorum,

Ama açamıyorum,kovalanıyorum.

Şimdi yanlızlık var hayatımda,

Sessiz odalarda, karanlıklarda.

Üşüyorum, titriyorum soğuklarda,

Aşkı arıyorum,sevdayı, bulamıyorum

Canımın acısını dindirmek istiyorum,

Aşkı arıyorum akıtıyorum gözyaşlarımı

İçimde biriken nefretimi gizleyemiyorum artık,

Dışa vurmak, herkesten nefret etmek istiyorum.

Gözlerime vuruyorum ateşimi

Canımı yakanları nefretimle eritmek istiyorum...', 'Soğuk ve sisli bir gündeyim yine, üşüyorum,ürperiyorum,yürüyorum karanlıkta, Hatırlamak istemiyorum geçmişimi, Kötü maziimi. Yeni bir sayfa ...', ARRAY['Türk Edebiyatı','Şiir','Rukiye İrge']::text[], 8.5, '{"poet":"Rukiye İrge","poet_slug":"rukiye-i-rge","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nefret-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakmayın Siz', 'bakmayin-siz-aysel-zengingul-50qnh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakmayın ağaçların kırgınlığına,

Kuşların ‘terkidiyar’ lığına.

Bakmayın siz; 

 Musa’nın çarıklarına,

 Gülcan’ın tasasına,

 Bebenin patisine…

Kış geldi! 

Erken yada erken fark eder mi? 

Geldi işte koca kış,

Tepemize bi sürü yağacak şimdi…

Şimdiyi geçiyorum da şöyle…

Kayısı çiçeğe duracak,

Kuşlar yanılgısını anlayıp geri dönecek,

Musa, çarıklarını da fırlatıp atacak,

Gülcan tasalarını balkondan sirkeleyip, 

Toz edecek,

Bebe yalıncak yalıncak gezecek,

Büyük büyük büyücek…

Bakmayın siz,

Bu yıl bahar erken gelecek…

13/10/2005', 'Bakmayın ağaçların kırgınlığına, Kuşların ‘terkidiyar’ lığına. Bakmayın siz;   Musa’nın çarıklarına,  Gülcan’ın tasasına,  Bebenin patisine…...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bakmayin-siz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yamalı Hırka', 'yamali-hirka-ayvaz-ciftci-y8oxy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yamalı bir hırkaydı sevdan

Bir yanı düzgünse bir yeri imlek atmıştı muhakkak,

Yakalarıda bozulmuştu artık, 

İlikleri genişlemiş, düğmeleri tutmuyordu.

Anlayacağın bir zamanlar beni ısıtan sevdan artık beni ısıtmıyordu..', 'Yamalı bir hırkaydı sevdan Bir yanı düzgünse bir yeri imlek atmıştı muhakkak, Yakalarıda bozulmuştu artık,  İlikleri genişlemiş, düğmeleri t...', ARRAY['Türk Edebiyatı','Şiir','Ayvaz Çiftçi']::text[], 8.5, '{"poet":"Ayvaz Çiftçi","poet_slug":"ayvaz-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yamali-hirka-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karartı Işıklar', 'kararti-isiklar-aysel-zengingul-yaq0u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karartı ışıklarda 

             Ders çalışma ihtimallerine kaçmak…

Karartı ışıklarda

             …  görüşlü pankartlar hazırlamak…

Karartı ışıklarda

             Tanrıya biraz daha yakınlaşmak…

Karartı ışıklarda

             ………………………………………………

Karartın ışıkları…

13/10/2005', 'Karartı ışıklarda               Ders çalışma ihtimallerine kaçmak… Karartı ışıklarda              …  görüşlü pankartlar hazırlamak… Karartı ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kararti-isiklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat', 'saat-ulya-erkman-a53wy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kiminiz kolumdasiniz

   Kiminiz duvarlarda

   Kiminiz kulede calarsiniz

   Kiminiz kolye boyunlarda

   Durmadan calisirsin

   Bildirmek icin vakti

   Yorulmak nedir bilmessin

   Islersin gunun her saati

   Zaman zaman bakariz sana

   Ogrenmek icin saati

   Gidecegimiz yer varsa

   Bilmeliyiz diye tam vakti

   Dusunmeyiz ki aslinda

   Sen zamanin gecisisin

   Hayatimizin her aninda

   Gelip gecen bir saniyesin

   Caldin  mazimi insafsizca

   Cevirip dakikayi senelere

   Gecti zaman hizlica

   gireceksin simdi gelecege

   Bilinmez kalan seneler

   Ne kadar olacaksin benimle

   Durmayacakki saniyeler 

   Benim omrum bitince

   Duracaksin  ama benimle 

   Ne yazik son nefesimde

   Gireceksin baskasinin hayatina

   Dunyaya bir bebek geldiginde

   Neden bakariz bilmemki sana

   Hatirlatirken bize gecen zamani

   En iyisi kiymet vermeliyiz bu hayata

   Yasamaliyiz doluca her ani', 'Kiminiz kolumdasiniz    Kiminiz duvarlarda    Kiminiz kulede calarsiniz    Kiminiz kolye boyunlarda    Durmadan calisirsin    Bildirmek icin...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/saat-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''a Çok Yakınız', 'allah-a-cok-yakiniz-alper-kuruk-f9lxc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allah''a çok yakınız mezarlıklarda

Selvilerin ucundan,

Bir yanda  o bir yanda biz

Aramızdaki mesafe:can.

Allah''a çok yakınız câmilerde

Minareler ucundan,

Bir yanda o bir yanda biz

Aramızdaki mesafe: ezan.

Allah bize bizden yakın

Dilimizin ucunda,

İçinize dönüp bakın

İşte orada Allah,işte bizi Yaratan.

Biz demişiz çok mu sanki; 

Bismillah,maşaallah,inşaallah...

Ölüme gidiyor da Mehmetçik

Temiz ağzında tek temiz isim var ki 

Belki son nefesiyle çıktı çıkan:

ALLAH! ALLAH! ALLAH! ALLAH! ...', 'Allah''a çok yakınız mezarlıklarda Selvilerin ucundan, Bir yanda  o bir yanda biz Aramızdaki mesafe:can. Allah''a çok yakınız câmilerde Minare...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/allah-a-cok-yakiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam...', 'babam-emirhan-bala-pp1dg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk göz ağrım dediğini,

Yay gibi kızılcık sopanı,

Sarhoşken çenemdeki yumruğunu,

Nasıl unuturum…Baba….

Anlatırken bize özünü,

Billur gibi parlayan gözünü,

“her şey olma! adam ol” sözünü,

Nasıl unuturum…Baba….

ufukta kalan dokunuşlarını,

Yüzünün süsü palabıyıklarını,

takma dişlerinin enseme batışını,

Nasıl unuturum…Baba….

Nasıl unuturum, Nasıl unuturum…

Musalla taşındaki güleç yüzünü,

Nasıl unuturum…Baba….', 'İlk göz ağrım dediğini, Yay gibi kızılcık sopanı, Sarhoşken çenemdeki yumruğunu, Nasıl unuturum…Baba…. Anlatırken bize özünü, Billur gibi pa...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/babam-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşat Nuri Güntekin İçin', 'resat-nuri-guntekin-i-cin-alper-kuruk-s213t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat bu kardeşim 

Bozar bozar harcar

Birgün seni,bir gün beni...

İşte harcadı şimdi de

Reşat altını gibi merhum Reşat''ı...

Nesine gerek mezar taşı onun

Edebî hayatının yokuşundan

Uçup selviler üzerine konar

Ağıt söyler Çalıkuşu

Ninni söyler Çalıkuşu

Ebedî hayatına doğru...', 'Hayat bu kardeşim  Bozar bozar harcar Birgün seni,bir gün beni... İşte harcadı şimdi de Reşat altını gibi merhum Reşat''ı... Nesine gerek mez...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/resat-nuri-guntekin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*-Bana Yalnızlığını Gönder', 'bana-yalnizligini-gonder-erhan-demir-32two', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana saçlarından bir tel gönder

Içinde bahar kokuları olsun

Öyle bir sarsın ki bütün evreni

Sevdalı yüreklerin umudu olsun

Bana bakışlarından bir bakış gönder

İçinde kin, nefret, öfke de olsun

Dünyanın kahrını gönder öylece

Bütün hüzünlerin kabulüm olsun

Bana gözlerinden bir damla yaş gönder

İçinde masmavi bir deniz olsun

Tarifsiz kederler dolsun içine 

Kuruyan güllerin yağmuru olsun

Bana yalnızlığını gönder

İçinde sensizliğin rengi olsun

Avutsun böylece bütün benliğimi

Bir ömür boyu sensiz olsun

Şiir ve Yorum: Erhan DEMİR', 'Bana saçlarından bir tel gönder Içinde bahar kokuları olsun Öyle bir sarsın ki bütün evreni Sevdalı yüreklerin umudu olsun Bana bakışlarında...', ARRAY['Türk Edebiyatı','Şiir','Erhan Demir']::text[], 8.5, '{"poet":"Erhan Demir","poet_slug":"erhan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bana-yalnizligini-gonder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstek', 'i-stek-alper-kuruk-e4ukx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dallarda asılı umutlarım 

Senden bol güneş olsun Tanrı''m,

Almaya uzanır kollarım

Koparamıyorum,koparamıyorum.

Güzellere takılı gözlerim

Saçın sarısında,gözün yeşilinde,

Aşk içinde hep ağlarım

Açılamıyorum,açılamıyorum.

Göğüs kafesinde olmuş bülbül 

Her çiçeği gül sanan deli gönül,

Bir öpücük verseydin bana ödül

Ki olurdu o tüm varım.

Kopsun telleri sazımın

Saçlarını al gel bana

Her telinden bir garip türkü çıkaracağım

Ben çalıp,ben yanacağım

Ağlayacağım,ağlayacağım.', 'Dallarda asılı umutlarım  Senden bol güneş olsun Tanrı''m, Almaya uzanır kollarım Koparamıyorum,koparamıyorum. Güzellere takılı gözlerim Saçı...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istek-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susma', 'susma-can-zozan-xtr54', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Susma; 

Konuş zamanımız sınırlı

Belki bugün, belki yarın, belki de sonraki gün,

Gideceksin biliyorum

Bir daha fırsatımız olacak mı? 

Susmanın sebebini; 

''Söyleyemedim,... Yazamadım,..

Sen ''Konuş'' dedikçe

Artan suskunluğumun

Nedeni hep aynıdı

''Seviyorum! '' 

Desem anlarmısın? 

Diyorsun, 

Seven insan hiç susarmı? 

Susma konuş

Susma; 

Zamanımız sınırlı

Yoksa; 

Yoksa, bir daha fırsatımız olacak mı?', 'Susma;  Konuş zamanımız sınırlı Belki bugün, belki yarın, belki de sonraki gün, Gideceksin biliyorum Bir daha fırsatımız olacak mı?  Susmanı...', ARRAY['Türk Edebiyatı','Şiir','Can Zozan']::text[], 8.5, '{"poet":"Can Zozan","poet_slug":"can-zozan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/susma-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vedalarımız', 'vedalarimiz-can-zozan-414w2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vedalarımız uzun olur seninle

Bazen sen çıkmak istemezsin

Bazen de ben

Bir sonraki güne sözleşiriz

Ben seni sana emanet ediyorum

Sende beni bana

Biz ne zaman kavuşacağız? 

Bize hiç kavuşmak olmayacak mı? 

Olmayacak mı? 

..........

..........

17.10.2005', 'Vedalarımız uzun olur seninle Bazen sen çıkmak istemezsin Bazen de ben Bir sonraki güne sözleşiriz Ben seni sana emanet ediyorum Sende beni ...', ARRAY['Türk Edebiyatı','Şiir','Can Zozan']::text[], 8.5, '{"poet":"Can Zozan","poet_slug":"can-zozan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vedalarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma Sakın Gözlerime', 'bakma-sakin-gozlerime-ahmet-nural-ozturk-jr39a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dilim bilmez de her dili gözlerim bilir

Evrensel yağmurlar içeren

Gezici bir bulut 

Sınır tanımaz damlalarla ağlayan

Bir sevi selidir

Bakma sakın gözlerime

Gör sadece yeterlidir.', 'Dilim bilmez de her dili gözlerim bilir Evrensel yağmurlar içeren Gezici bir bulut  Sınır tanımaz damlalarla ağlayan Bir sevi selidir Bakma ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bakma-sakin-gozlerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık -1-', 'ayrilik-1-alper-kuruk-qwwb3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dizim dizim dizildi gözümde yaşlar

Boğum boğum boğuldu boğazda hıçkırık

İşte böyle başladı bizim ayrılık.

Gün yeni doğuyordu

Günü batıyordu tatlı hayatımızın

En acısıydı bu ânımızın.

Son öpüşe hazırlandık ikimiz de 

İlk defa birbirinden utandı dudaklarımız

Bir soldu,bir güldü,bir ateşti yanaklarımız 

Ve zangır zangır titredi ayaklarımız.

Öpüşün tadını unutturdu bize 

Hasretin ağzımızı buran acılığı 

Ondandır sevmiyorum ben ayrılığı.

Ölümden bir andı yaşadığım

Bir mendilli el uzandı pencereden

Oydu giden bendim burada ölen.

Dizim dizim dizildi gözümde yaşlar

Boğum boğum boğuldu boğazda hıçkırık,

Bir düdük öttü öylesine yanık 

Ve böyle başladı bizim ayrılık...', 'Dizim dizim dizildi gözümde yaşlar Boğum boğum boğuldu boğazda hıçkırık İşte böyle başladı bizim ayrılık. Gün yeni doğuyordu Günü batıyordu ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayrilik-1-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgalarımız', 'kavgalarimiz-can-zozan-qh27t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kavgalarımızda oluyor elbet

Bazen sen bazen ben

Ama bizim kavgalarımız saman alevi gibi

Ne sen bensiz olursun

Nede ben sensiz

Darılmalarda yakışıyor sana

Biliyormusun? 

Sonra bir kedi gibi usulca

Yanıma sokulup

Ne dememi bekliyorsun? 

Diyorsun ya

O anki sevincimi heyecanımı görmeni 

Ne çok isterdim

Bir bilsen

Ya bir gün,

Ya bir gün; 

Hiç  dönmezsen........

............

............

17.10.2005', 'Kavgalarımızda oluyor elbet Bazen sen bazen ben Ama bizim kavgalarımız saman alevi gibi Ne sen bensiz olursun Nede ben sensiz Darılmalarda y...', ARRAY['Türk Edebiyatı','Şiir','Can Zozan']::text[], 8.5, '{"poet":"Can Zozan","poet_slug":"can-zozan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kavgalarimiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halıcı Kız', 'halici-kiz-alper-kuruk-g4xxv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İpten yapılmış 

Bir porte üzerinde

Yer yer serpiştirilmiş

Renk renk yumaklar

Nota olur çıkar 

Halıcı kızın ellerinde.

Bu renk âleminin 

İnce uzun parmaklı halıcı kızı

Sihrine kapılır bestesinin 

Renkler akıştıkça önünde...

Hele şarabî kırmızı 

Büyüler halıcı kızı.

Çözülür,erir yumaklar

Bizim halıcı kız ne besteler yapar...', 'İpten yapılmış  Bir porte üzerinde Yer yer serpiştirilmiş Renk renk yumaklar Nota olur çıkar  Halıcı kızın ellerinde. Bu renk âleminin  İnce...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/halici-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zengine Nispet', 'zengine-nispet-munevver-senol-e3eae', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sizin evinizde kanarya kuşunuz mu var? olsun.

Bizim bahçemizde serçeler ötüyor.

Sizin sofranızdan pahalı balıklar eksik olmazmış.

Olsun, bizim hamsimiz neyimize yetmiyor.

Hııım, sizin süs köpeğiniz varmış, evin ortasında oturan.

Bizimde karabaşımız var, kapıda arslan gibi kükreyen.

Siz vakkodan giyinirmişsiniz, öyle mi? 

Gelin bizim pazarda görün, daha ne çeşitleri var.

Siz camınızdan denizi seyredermişsiniz, olsun.

Bizim buralarda, yağmur yağınca deniz oluyor.

Ama, yüzme bilen kurtuluyor, bilmeyen boğuluyor.

Yaşlılar, bebeler, eşyalar, hepsi ölüyor

Çünki onlar, yüzme bilmiyor, 

Olanlar gene garibe oluyor.

 Not: 1999''da dere yatağına yapılan evlerin, sel felaketi anısına yazmıştım.', 'Sizin evinizde kanarya kuşunuz mu var? olsun. Bizim bahçemizde serçeler ötüyor. Sizin sofranızdan pahalı balıklar eksik olmazmış. Olsun, biz...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zengine-nispet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ETNİK DAYATMA ve ÜST KİMLİK', 'etni-k-dayatma-ve-ust-ki-mli-k-dursun-elmas-0yayk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'AB üyeliği yolunda her geçen gün yeni yeni tavizler koparılan Türkiye''nin AB yanlısı siyasetçileri, sözde aydınları sık sık etniklikten, etnisiteden söz ederek ve sanal bazı azınlıklar yaratmaya devam etmekteler.

       Özellikle Türkiye''mizde ''üst kimliğe'' bağlı ''alt gruplar'' kaşınmakta ve bu alt gruplara ''etnitisite'' gömleği giydirilip, ''azınlık'' statüsü verilmeye çalışılmaktadır. Etnolojik olarak ''üst kimlik''aynı kökene bağlı alt grupların ''ana'' kimliğidir. İşte bu ''ana kimlik'' birleştiri- ci ve bütünleştirici özelliğinden sıyrındırılabilmesi için bu kökene bağlı alt kimliklere, etnik kimlikler vererek yeni azınlıklar yaratarak ülke insanımız ufalanarak, lime lime ya pılarak Yugoslavya haline getirmenin son safhalarını yaşıyoruz.

       Bu manada; Türklük; Kırgızlar, Özbekler, Kazaklar, Azeriler, Türkmenler, Yakutlar, Gaga-vuzlar.....  için bir üst kimliktir.   Üst kimlik, bazı durumlarda aynı coğrafyayı paylaşan, benzer kültürlere sahip, tarihi pay- laşımları olan grupların temsili kimliği olarak da tanımlanabilir. Örneğin: ''Çerkezlik''; her biri

farklı kökene ve farklı dile sahip  Adigeler,  Abhazlar,  Çeçenler, Ubıklar, Ossetler, Dağıstanlılar vs gibi Kuzey Kafkasya topluluklarının üst kimliğidir. Çerkez olarak tanımlanan bu grupların içinde  Karaçaylar ve Balkarlar Türk''tür ve Türkçe konuşurlar. 

       Siyasi manada ise üst kimlik, farklı etnik gruplara mensup kişilerin, vatandaşlık bilinciyle benimsediği ''temsili'' ulusal kimliktir. Bu kimlik genelde

ülkenin kurucu egemen unsurunun kimliğidir.TC Anayasasının 66.maddesinde de ulusal kimlik bu anlamda ''TÜRK'' olarak  tanımlanmıştır. Bu gün birçok ülkede de, ulusal kimlik kurucu egemen unsurun kimliğidir. Örneğin, Fransa halkının ulusal kimliği olan; ''Fransızlık'' coğrafi bir aidiyeti değil, 5.yy''da 

Galya''yı ele geçirerek Fransa''yı kuran Franklar''ın soyuna mensubiyeti ifade etmektedir.

       Ancak bu kimlik Fransa''daki etnik gruplar için temsili ulusal kimliktir.

       Bu günlerde sun''i olarak ülkemiz gündemine sıkça getirilen ve dayatılan ''Türkiyelilik''  tanımın  hiç bir tarihi ve meşru dayanağı yoktur. Kaldı ki, Türk ulusunun %90''ı aşan bir  çoğunluğu kendisini Türk olarak tanımlamakta, Türk kimliğini benimsemektedir.

       Burada kimlik tanımıyla ilgili olarak belirtilmesi gereken önemli bir husus, kişinin özgür ifadesiyle bilinçli olarak duyumsadığı, özümsediği kimliğin o kişi için bir üst kimlik değil, asli kimlik olduğudur. Bu temelde farklı bir kökene sahip olsa da Türküm diyen bir kişi için  Türklük bir üst kimlik olmayıp asli kimliktir. Kaldı ki bu devleti kuran irade ve etnik köken de  ''TÜRK'' unsuru değil midir? 

       Türklüğün Yeni Dünya Düzeninde ana harç olan ''TÜRK'' kimliği daha da genişletilerek bütünüyle Türklük alemi ve Türklükleri unutturulmuş soydaşlarımızı da ana kimliklerine kavuşturarak ''TÜRKLÜK'' şemsiyesi altında toplanmasının adıdır bir bakıma düzenimiz.   Aynı zaman da Yeryüzünün neresinde bir Türk varsa, arz üzerinde en çok nüfusa sahip bu yüce yaratılmış kavmin ''DİLDE; FİKİRDE İŞTE''  birliğinin sağlanmasıdır.

BOP ''ta GOP''ta BİP'' te değil; 

''Birleşik Türk Devletleri Projesi''nde buluşalım.

       İnşallah devam edeceğiz. Türk''çe düşünün, Türk''çe sayıklayın, Türk''çe

yaşayın, Türk''çe kalın.





--------------------', 'AB üyeliği yolunda her geçen gün yeni yeni tavizler koparılan Türkiye''nin AB yanlısı siyasetçileri, sözde aydınları sık sık etniklikten, etn...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/etnik-dayatma-ve-ust-kimlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Dünyamdan', 'gitme-dunyamdan-ufuk-coban-rx53d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle zor buldum ki yüreğimin beklediğini,

Öyle çok kabullendim ki sendeki mutluluğun ışığını.

Bir yarım sende kendini buldu solurken hayatı,

Bir yarım bende kaldı özlerken gözlerini.

Gitme dünyamdan sen bendeki hayatsın artık,

Gidersen ne nefesim kalır ne de umudum,

Gitme gözlerimden görmez yüreğin senden öte,

Kal ellerimde bir ömür boyu, bir yemin boyu.

Bugün gitmiyorum yanından uzaklara inan bana,

Bugün bir kök salıyorum yanına dalları uzanan mutluluğa.

Senden bir gülüş alıyorum yanıma saklamak için yarına,

Yarın öyle yakın ki inanamazsın, güven bana.

Gitme sakın dünyamdan dünyam senden kurulmuş,

Yıkma beni hayatım sensiz sürmez yağmurlardan ıslanmış.

Gitme ellerimden sensiz üşür kalır soğuklarda,

Karanlıklar korkutmuyor beni sensizlik kadar.

Bir yarın ellerimde tutuyorum bir yanı sen bir yanı ben,

Bir ümit besliyorum toprağı ben hayat suyu sen.

Yalnız bırakma bizi bekliyor aşkını kenarındaki bir denizden,

Kalk gel ilk bahar rüzgarları ile yapraklar çiçeklerini açmadan.

Gitme olur mu benim hayallerimden,

Gidersen kızamam hayatıma verdiğin sondan.

Sen hep kal mutluluk olsun sendeki küçük bir tekmeden,

Yüreğimde bir ses sen oldu duymasın kimse biz istemeden.

Seni nasıl sevdim göremezsin, görme de zaten,

Kimseyi sevemem böyle,korkarım nazar değmesinden.

Sen benim bitanem, üstüne titrediğim nazlı çiçeğim,

Gitme dünyamdan, gitme kokumdan, kal canıma dokun ölüm bizi bulmadan...

17/10/2005 21:15', 'Öyle zor buldum ki yüreğimin beklediğini, Öyle çok kabullendim ki sendeki mutluluğun ışığını. Bir yarım sende kendini buldu solurken hayatı,...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gitme-dunyamdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetermi Sanıyorsun?', 'yetermi-saniyorsun-can-zozan-0y8v7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yetermi sanıyorsun seni uzaktan sevmek,

Yetermi; 

Oysaki ben; 

Ellerini tutmak,

Parklarda dolaşmak,

Tahtaravellide sallanmak,

Olurda bana küsersen,

Barışmak için sana şiirler okumak,

Yollarına sevdiğin çiçekleri,

Papatyaları sermek,

Şöyle köhne bir kahvede,

İnce belli narin bardaktan

Tavşan kanı çay içmek istiyorum.

Aynı havayı tenefüs etmek,

Aynı sigaradan yudum almak,

Radyodan dinlediğim şarkılardan

Sırayla şarkı seçmek istiyorum

Bundan sonraki senin şansına diye,

Aynı göğe bakmak,

Aynı yıldızı seyretmek,

Aynı sevinci paylaşmak,

Aynı hüzne ortak olmak,

Beşiktaş yenildiğinde seni kızdırmak,

Şöyle birgün birlikte

Bir dağın başına çıkıp,

Seni seviyorum, 

Sana aşığım CAN demek istiyorum,

Unuttum sanma; 

Bir sözümüz daha vardı,

Seninle bir gün bir yetmişlik içmek,

Zil zurna sarhoş olup,

Yürümek istiyorum,

Yetermi sanıyorsun; 

Seni uzaktan sevmek,

Yetermi CAN? 

Yetmez elbet yetmez......

.................

.................

17.10.2005', 'Yetermi sanıyorsun seni uzaktan sevmek, Yetermi;  Oysaki ben;  Ellerini tutmak, Parklarda dolaşmak, Tahtaravellide sallanmak, Olurda bana kü...', ARRAY['Türk Edebiyatı','Şiir','Can Zozan']::text[], 8.5, '{"poet":"Can Zozan","poet_slug":"can-zozan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yetermi-saniyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arada Hiç Kere', 'arada-hic-kere-aysel-zengingul-d2gk0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Silik bi gözyaşı,

Verilmemiş-alınmamış fotoğraflar

İçilmemiş bi kadeh rakı,

Yarımca sevişmeler…

Çokça olamasa da,

    Düşünüyorum seni azca,

        Az buçuk,

        Az çok,

        Arada bir,

        Arada yüz, 

             Arada milyon,

                      Arada hiç kereler….

(15,10,2005 - 20; 25)', 'Silik bi gözyaşı, Verilmemiş-alınmamış fotoğraflar İçilmemiş bi kadeh rakı, Yarımca sevişmeler… Çokça olamasa da,     Düşünüyorum seni azca,...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/arada-hic-kere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir sallandı', 'i-zmir-sallandi-mehmet-halil-3c5qa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İzmir sallandı bu gün,

5,6 ve 5,9 şiddetinde ardı ardına.

İzmir sallandı bu gün,

Artarak ''''bir sonraki gelebilir! '''' dediler.

Bakıp binalardaki çatlaklara

''''Bir gün evlere girmeyin! '''' diye, anons ettiler.

Ama, nerede kalacağız? 

Ne kadar kalacağız? 

Bir çiçek gibi…

Çocukların umudu açsın istiyoruz.

peki bunu nasıl anlatacağız? 

Bütün binaların,

Fenni sorumluluğunu yüklenen,

Belediyelerin ve resmi kurumların,

Binaları zarar görüyorsa,

Artık siz anlayın.

Hiç olmazsa yetkililer,

Ne ektiğini biliyorlar.

Kabul edildi paranın galibiyeti.

Bütün resmi daireler,

Tatil edildi.', 'İzmir sallandı bu gün, 5,6 ve 5,9 şiddetinde ardı ardına. İzmir sallandı bu gün, Artarak ''''bir sonraki gelebilir! '''' dediler. Bakıp binalard...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/izmir-sallandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme Bebek', 'gelme-bebek-i-lhan-kirbac-sx5hd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geleceksin de ne olacak,

Şu fani dünyaya bebek? 

Nelerle karşılaşacaksın bir bilsen,

Belki o zaman vazgeçersin.

Yoksulluk içinde belki ailen,

Hastanede rehin kalacak belki de annen.

Babanın işi var mı, sana nafaka getirebilecek mi? 

Yokluklar içinde büyüyeceksin.

Özel okullara, kolejlere göndermeyi bırak,

Belkide kitap, defter alamayacak baban.

Varlık içinde büyüyen akranlarına bakıp,

Kahrolacaksın, kahredeceksin.

Büyüdüğünde iş bulamayacaksın,

Yüksek okulları bitirmene rağmen.

Acılar içinde yaşayıp,

Şu kısa ömrünü tamamlayacaksın.

En acısı, en kötüsü,

Seveceksin ama sevilmeyeceksin.

Kalbin ihanetlere dayanamayacak,

Dünyaya gelmeye hala kararlı mısın bebek?', 'Geleceksin de ne olacak, Şu fani dünyaya bebek?  Nelerle karşılaşacaksın bir bilsen, Belki o zaman vazgeçersin. Yoksulluk içinde belki ailen...', ARRAY['Türk Edebiyatı','Şiir','İlhan Kırbaç']::text[], 8.5, '{"poet":"İlhan Kırbaç","poet_slug":"i-lhan-kirbac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelme-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-hasan-kutsal-eker-cbjm9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kulağım sesinde gözüm izinde

Gelişin ilkyazı müjdeler bana

Başımdır dinlenen şimdi dizinde

Güller çiğdemler sunarım sana

Tükenir acılar sancılar susar

Uğramaz bahçeme artık sonbahar

Sürüp gider bu düş sonsuza kadar

Bir dünya sığdırdım inan bu ana', 'Kulağım sesinde gözüm izinde Gelişin ilkyazı müjdeler bana Başımdır dinlenen şimdi dizinde Güller çiğdemler sunarım sana Tükenir acılar sanc...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kutsal Eker']::text[], 8.5, '{"poet":"Hasan Kutsal Eker","poet_slug":"hasan-kutsal-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bekleyis-144-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gel Bebek', 'hadi-gel-bebek-i-lhan-kirbac-9lkni', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hala ne duruyorsun orada,

Doğsana ilk nefesini alsana bebek.

Bilsen ne güzellikler var bu fani dünyada,

Bilsen bir saniye durmazsın orada.

Ebeveynlerin bayram edecek,

Allah''a şükredecekler.

Sağ salim doğdun diye.

Dünya bir güzellik daha kazanacak.

El bebek gül bebek büyüyeceksin,

Her başarında aileni sevindireceksin.

Onların göz bebeği olacaksın,

Okullar bitirip, büyük adam olacaksın.

Sevgililer bulacaksın sevgi ırmağında,

Kalbin pır pır edecek ona her baktığında.

Mutlu edeceksin, mutlu olacaksın.

Hala ne diye duruyorsun doğsana bebek.', 'Hala ne duruyorsun orada, Doğsana ilk nefesini alsana bebek. Bilsen ne güzellikler var bu fani dünyada, Bilsen bir saniye durmazsın orada. E...', ARRAY['Türk Edebiyatı','Şiir','İlhan Kırbaç']::text[], 8.5, '{"poet":"İlhan Kırbaç","poet_slug":"i-lhan-kirbac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hadi-gel-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usul bir sallantıda', 'usul-bir-sallantida-ahmet-nural-ozturk-xehi3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'usul bir kıpırtıda

yüreği hop oturup hop kalkan kız

biliyor musun

benim hep sallanır yüreğim fırtınalar içinde

bir damla yağmurla

sırılsıklam kalan kız

biliyor musun

benim hep ağlar çilem

yaşlar çağlar içimde...', 'usul bir kıpırtıda yüreği hop oturup hop kalkan kız biliyor musun benim hep sallanır yüreğim fırtınalar içinde bir damla yağmurla sırılsıkla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/usul-bir-sallantida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LaLa Ürekdir', 'lala-urekdir-ahmet-hani-wc01w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir damcı yaş,

qara bextli,

qara gözden,

yere düşdü.

ve o yerden,

lala bitdi.

aç gözleri,

bax torpağa,

her yerinde,

lala vardı.

qara bextli,

qara gözler,

üreklerin,

damcı damcı,

ağlayıblar,

yer üzüne.

17.10.2005', 'Bir damcı yaş, qara bextli, qara gözden, yere düşdü. ve o yerden, lala bitdi. aç gözleri, bax torpağa, her yerinde, lala vardı. qara bextli,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/lala-urekdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minnetim Yok Hiç Kimseye', 'minnetim-yok-hic-kimseye-munevver-senol-mtgqk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah yataktan kalkarken, 

beni sakın ha görme, ağlarsın.

Şov programındaki, Hüsmen Aga gibi,

düşüp düşüp kalktığımı görür.

Belkide bu yaptıklarımı oyun sanar,

kahkahalar atarsın.

Gerçi, benimde zaman zaman 

güldüğüm olur kendi halime.

Size bir sır vereyim mi? 

Çoğu zamanda ağlarım.

Mutluluk maskemi taktım da sizlere hep güldüm ben.

Amaa içimde fırtınalar koptu,

günde yüzbinkere öldüm ben.

Poliannacılık oynadımda, sizleri hiç üzmedim.

Hastalığımın ciddiyetini geç kalınca gördünüz.

Müniş gerçekte hastaymış bee deyip,

belkide üzüldünüz.

Kabahat bende dostlar,

naz saz nedir hiç bilmedim.

Bırakın gidin benikendi halime,

ben yanlızda yaşarım.

Minnetim yok Tanrım,

senden başka hiç kimseye.', 'Sabah yataktan kalkarken,  beni sakın ha görme, ağlarsın. Şov programındaki, Hüsmen Aga gibi, düşüp düşüp kalktığımı görür. Belkide bu yaptı...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/minnetim-yok-hic-kimseye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şeyler Ölüyor İçimde', 'bir-seyler-oluyor-i-cimde-hasan-kutsal-eker-my5b3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün yaşam buluyor dal uçlarında

Deniz, uykusuz ve yorgun

Özenle saklayıp beslediğim

Karaya vuruyor tüm umutlarım

Kimse almıyor maviyi tuvaline

Gökyüzü paramparça anlamsız

Tüm denizler delik deşik

Kuşlar tedirgin, kuşkulu, şarkısız

Artık ne gül ne karanfil açıyor

Bahçelerim öksüz ve yalnız

Yeşermeden kazıyorlar ölümü

Körpe dalların damarlarına

Akdeniz mavisinde rüzgâr

Martılarla oynaşıyor açıklarda

Acılar içinde çırpınıyor dalgalar

Ruhumda bir şeyler ölüyor', 'Gün yaşam buluyor dal uçlarında Deniz, uykusuz ve yorgun Özenle saklayıp beslediğim Karaya vuruyor tüm umutlarım Kimse almıyor maviyi tuvali...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kutsal Eker']::text[], 8.5, '{"poet":"Hasan Kutsal Eker","poet_slug":"hasan-kutsal-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-seyler-oluyor-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bu Sevda', 'ah-bu-sevda-yavuz-agir-idmzm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağlara,taşlara yazsam adını

Pınarlara akıtsam gözyaşımı

Selvi boylum söylesen ya adını

Yaşasam bugüzel aşkın tadını

Göz görür,gönül söyler

Yara bir çift söz eyler

Gücenmesin sakın bana

Neylerse gönül eyler.

Koy desinler aşkımıza kara sevda

Kimseye getirmez  fayda

Kader ağlarını örsede orada

İnanki kavuşuruz birgün sılada

Şu gönlümün çilesi görünmez

Akan gözyaşlarım silinmez

Sevda yağmurları yağar üstüme

Dinermi dinmezmi bilinmez...', 'Dağlara,taşlara yazsam adını Pınarlara akıtsam gözyaşımı Selvi boylum söylesen ya adını Yaşasam bugüzel aşkın tadını Göz görür,gönül söyler ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-bu-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Susar', 'ask-susar-sinan-goztas-ha5ao', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir toz yığını kalır 

Gitmeye yakın

Arkadaş dediğin gözlerindir

Bir anı yakalarsın

Susar baktığında.

Umudu yakalar son kez ellerin

Düşmeye yakın, tutar seni yanılgı

İçine işlemiş aşkları yargılar

Gece kendi izinden gider,yolunu kaybedersin

Çıkmazdır her gidiş birazda

Avuçların terlemiştir sorguda

Hüküm giymeye bir aşk kalır

Arkadaş dediğin gözlerindir

Bir anı yakalarsın

Susar baktığında.', 'Bir toz yığını kalır  Gitmeye yakın Arkadaş dediğin gözlerindir Bir anı yakalarsın Susar baktığında. Umudu yakalar son kez ellerin Düşmeye y...', ARRAY['Türk Edebiyatı','Şiir','Sinan Göztaş']::text[], 8.5, '{"poet":"Sinan Göztaş","poet_slug":"sinan-goztas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-susar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Gerekir Kayseri', 'bana-gerekir-kayseri-nafiz-caglar-yasar-6c3wl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Niğde Nigğde dedikleri 

Bir cadde biraz da zilli 

İsteyene ver belayı 

Bana gerekir Kayseri 

Sazım yok ki çalayım 

Sevenler yok tek ağlayim 

Siz yanmayın ben yanayım 

Bana gerekir Kayseri 

Çiksam Erciyes yoluna 

Seyretsem Anadolu''yu 

Çağırsam bi türkü daha 

Bana gerekir Kayseri 

ilmi bellemeye geldik 

Gördüm ki hepsi rezillik 

Sıcakta açılır gençlik 

Bana gerekir Kayseri 

Duydum kar yagmış oraya 

Ayak basılmaz toprağa 

Niğde''de geldik ayaza 

Bana gerekir Kayseri 

Çağlar''ım hasretim bitmez 

Yol şurdan şura gidilmez 

Gidince gelmek istenmez 

Bana gerekir Kayseri', 'Niğde Nigğde dedikleri  Bir cadde biraz da zilli  İsteyene ver belayı  Bana gerekir Kayseri  Sazım yok ki çalayım  Sevenler yok tek ağlayim ...', ARRAY['Türk Edebiyatı','Şiir','Nafiz Çağlar Yaşar']::text[], 8.5, '{"poet":"Nafiz Çağlar Yaşar","poet_slug":"nafiz-caglar-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bana-gerekir-kayseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir Kayseri', 'bu-sehir-kayseri-nafiz-caglar-yasar-sc8dm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu şehirde yine akşam olur 

Yosmalar dökülür kaldırımlara 

Bu şehirde yine güneş doğar 

Anadolu insanı ekmek kazanmakta 

Canim topraklarim gurbet derdinde 

Çaresi yoktur gidemez o illere 

Çoluk çocuk ağlar köy köy diye 

Dağlara çiksa çay içse derelerde 

Usandım artik taş bloklardan 

Bunaldim dostum kömürlü havadan 

Tek tesellim bu Kayseri''de 

Erciyes''in taşından toprağindan 

Ahh anneciğim canim emmoğlu 

Gide gele belledim ben bu yolu 

Sevmiyorum gayri musluk suyunu 

Seni özledim canim memleketim', 'Bu şehirde yine akşam olur  Yosmalar dökülür kaldırımlara  Bu şehirde yine güneş doğar  Anadolu insanı ekmek kazanmakta  Canim topraklarim g...', ARRAY['Türk Edebiyatı','Şiir','Nafiz Çağlar Yaşar']::text[], 8.5, '{"poet":"Nafiz Çağlar Yaşar","poet_slug":"nafiz-caglar-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-sehir-kayseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Satır', 'kirik-satir-sinan-goztas-0uwaq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlayamam,

Şarap canımı yakar

Ağaç bedeninde eskimişlik düşer

Çizgili alınların ortasına.

Kelimeler karışmıştı,sen orada değildin

Çerçeveleri dökülmüş bir portreydin

Gülen incitilmişlikler geçerken içinden.

Dayanaklar tedariksiz

Uzun bir koşturmaca dillerin

Düşünerek seni

Yürümek güzeldir.', 'Ağlayamam, Şarap canımı yakar Ağaç bedeninde eskimişlik düşer Çizgili alınların ortasına. Kelimeler karışmıştı,sen orada değildin Çerçeveler...', ARRAY['Türk Edebiyatı','Şiir','Sinan Göztaş']::text[], 8.5, '{"poet":"Sinan Göztaş","poet_slug":"sinan-goztas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kirik-satir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Aşk!', 'ey-ask-gunduzalp-kayihan-jfi24', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adın al beni olsa alınmazsın

Tadın ab-ı hayat olsa tadılmazsın

Lokman olsan yaram sarmazsın

Senin adın aşk; hep kenardan bakarsın

İzin kağıdı olursun bazen 

Bazende yolcu bileti.

Her ne olursan ol farketmez sana

Senin adın aşk; hep hayallerde varsın

Salarsın çokluğun içine

Aynı anda itersin derde

Akıl koymazsın sen serde

Senin adın aşk; hep yalnızlıklarda varsın

Yıkarsın hayalleri de sanma ki insaflısın

Nede olsa sen,hep esef dalısın

Ne olursa olsun yine de canın canısın

Anlamadım seni Ey Aşk! Ne karın ağrısısın', 'Adın al beni olsa alınmazsın Tadın ab-ı hayat olsa tadılmazsın Lokman olsan yaram sarmazsın Senin adın aşk; hep kenardan bakarsın İzin kağıd...', ARRAY['Türk Edebiyatı','Şiir','Gündüzalp Kayıhan']::text[], 8.5, '{"poet":"Gündüzalp Kayıhan","poet_slug":"gunduzalp-kayihan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-ask-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirimsin', 'siirimsin-aysel-zengingul-sy4ok', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanık bi özlem içindeyim; 

Toprak kokusu gibi taze,

Ana sütü gibi helal! 

   Memleketimsin…

Dalıp dalıp gitmekte gözlerim; 

Nice Ummanlardan geçip,

Sahralar aştım! 

    Hudutsuzluğumsun…

Yeditepe zindanlarında 

Kanlı bıçaklıyım, 

Yaralıyım,

Kızılırmak gibi acıyor canım

     Esirliğimsin…

Göklerde meşk eden kartal gibiyim; 

Dünya kanatlarımın altında

Bir inci tanesi…

     Özgürlüğümsün…

Vakitli vakitsiz 

Baskın yerim gecekondularda

Hiç olmadık suçlardan,

     Yoldaşımsın…

Yaz sonu hüzünleriyle

Sözcük yüklüyüm.

Mısralar biriktiriyorum adına

Yazımda iz

Düşümde gizsin sen

Şiirimsin…

Şiirimsin…

14/10/2005   02; 07', 'Yanık bi özlem içindeyim;  Toprak kokusu gibi taze, Ana sütü gibi helal!     Memleketimsin… Dalıp dalıp gitmekte gözlerim;  Nice Ummanlardan...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/siirimsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sen', 'hep-sen-metin-yalti-td1j0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamak için yapılacaksa bir seçim

Ne kadar erişilmez olsanda

Yok başka seçeneğim

1979', 'Yaşamak için yapılacaksa bir seçim Ne kadar erişilmez olsanda Yok başka seçeneğim 1979...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hep-sen-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Yaşam', 'sensiz-yasam-mehmet-yucel-zb5vv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşam bir kartalın kanat çırpışı  kadar özgürce

bir yılanın zehirleyişi kadar acımasız

bir bebeğin hıçkırıkları kadar masum

ve güneş kadar parlak

ve gök yüzü kadar masmavi berrak

yaşam giden sevgilinin kalbi kadar vefasız

bitmeye mecbur ömür kadar zamansız

ayrılık kadar amansız

seni sevdiğim kadar 

özlediğim kadar yaşam

gözlerine susadığım

ellerine açlığım

bunaldığım

bulutlandığım

umutlandığım

sensin yaşam desem yeridir

sensizlik azrailin esreridir

öyle yenik 

öyle kopmuş

öyle iflah olmazım ki

sorsalar kelimeler düğümlenip boğacak beni

sen yaşamı yaşamak seni

işte bu değil dahası var

anlatılamaz

kelimelere sığmayan

bir yaşamamak bilirim o da sen olmayan', 'yaşam bir kartalın kanat çırpışı  kadar özgürce bir yılanın zehirleyişi kadar acımasız bir bebeğin hıçkırıkları kadar masum ve güneş kadar p...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel']::text[], 8.5, '{"poet":"Mehmet Yücel","poet_slug":"mehmet-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sensiz-yasam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DüŞLeRim ÇıRıLçıPLaK', 'duslerim-cirilciplak-aysel-zengingul-ejj24', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '......yürüyorum yalınayak,

 .......kafiyesiz düşlerimle…

 .......sokaklarda ıslıklar,

 .......sokaklarda çığlıklar! 

  ......yürüyorum karanlığa ilişmeden

            ....................düşlerim çırılçıplak…

16/10/2005  24; 45', '......yürüyorum yalınayak,  .......kafiyesiz düşlerimle…  .......sokaklarda ıslıklar,  .......sokaklarda çığlıklar!    ......yürüyorum karan...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/duslerim-cirilciplak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Üç Kişiydik', 'biz-uc-kisiydik-mehmet-kucukkarahan-lm83k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatımın en güzel günleriydi o günler. 

Yaş yirmi üç, yirmi dört uçarıydı geceler. 

Gündüz gezer tozar, gece demlenirdik. 

Deniz Kenarında muhabbet ederdik. 

Biz üç kişiydik, üç deliyürek 

Kimimizin elinde olta, kimimizinkinde tüfek, 

Ne çıkmışsa avda, akşam mangal başında; 

Kadın olmasa da; hayaliyle ederdik sohbet. 

Geçerdik kendimizden, Emmioğlu derken. 

Gece sabah olurdu, biz yeni rakı ararken. 

Birden bir türkü, adı Kara Yılan.

Sonra yanımız dolardı, kızardı Karaoğlan. 

Hasbel kader geldi, geçti yıllar. 

Şimdi mazide saklıdır, anılar. 

Ayrılmışız üzerinden geçmiş yıllar, 

Anlatırken gözümden dökülüyor yaşlar. 

Dedim ya biz üç kişiydik. 

Üçümüzde iyi içerdik! 

Hep bir ağızdan türkü söylerdik. 

Güzeldi o günler hem de çok güzel.

Keşaplının Günlüğünden 

Mehmet KÜÇÜKKARAHAN', 'Hayatımın en güzel günleriydi o günler.  Yaş yirmi üç, yirmi dört uçarıydı geceler.  Gündüz gezer tozar, gece demlenirdik.  Deniz Kenarında ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Küçükkarahan']::text[], 8.5, '{"poet":"Mehmet Küçükkarahan","poet_slug":"mehmet-kucukkarahan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/biz-uc-kisiydik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zafer', 'zafer-aysel-zengingul-mlqfq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kararmış umutlara yer yok artık yüreklerimizde.

Ne senden öncesine sus, ne senden sonrasına mahpus,

Elerimizde zincirlerle dil dökmek yok yalnızlığımıza! 

Fikirlerimizin olgunluğu, çağ atladıkça varoluşumuza

Biz demiri un etmesini de biliriz elbet! 

İmgelerimizi şerbet süzgecinden geçirip

Misafir etmek değil mi, harcımızı şiirlere.

Bir tutam gök mavisi o ateşin sancılarını almaya 

Ve özgürlüğe varmaya kanıt değil mi artık? 

Biz yazmasını da biliriz elbet! 

Bıçak kemiğe dayanmadı henüz,

Ölüm çaresizlikten sayılır…

Nice celladın pençesindeyken bile

Ölüme korkumuzu sezdirmedik.

Ölmesini de biliriz elbet! 

11/10/2005   02; 22', 'Kararmış umutlara yer yok artık yüreklerimizde. Ne senden öncesine sus, ne senden sonrasına mahpus, Elerimizde zincirlerle dil dökmek yok ya...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zafer-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte O Zaman Beni Hatırla', 'i-ste-o-zaman-beni-hatirla-kamil-soylemez-vluvt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zülüfün düşmüşte suya

Akıp gidiyor unutma

Tel dediğin bir tutam saç 

Bir ömür yok satıyor

Geçen yıllar ardı sıra

Üzümün sapı

Armudun çöpü

Alıyorda ömrünü

Sen almıyorsun 

İki damla yaş dökene inat

Gelecekten gerçek gönlünü

Şimdi varsın yarin yok

Ha zenginsin 

Ha karnın tok

Değildirki sevda

Canım himi hiç yok

Bir gün olur sende tutuşursun

Unutma diyen karnım tok

Sırtım pek diyen cana

İşte o zaman beni hatırla', 'Zülüfün düşmüşte suya Akıp gidiyor unutma Tel dediğin bir tutam saç  Bir ömür yok satıyor Geçen yıllar ardı sıra Üzümün sapı Armudun çöpü Al...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iste-o-zaman-beni-hatirla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınara Konan Çığlıklar', 'cinara-konan-cigliklar-ercan-cengiz-wzfrg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlıktı, emeğe göz koyarlardı,

Kol gezinirdi Çınar ağacına

Yüklü teknikle gövdesine isimler kazındığında

Ve namlunun ucundan sipere yatıldığında

Kurşunlanırdı,

Yutardı gecenin karanlığı.

Bilinmezin bilinmesiydi suçlu kılan

Peşinden kurşun attıran...

Yeniliğin bir hamlesiydi

Yarınlara açılı

Asırlık Çınarın kendi bir bedeldi

Gecenin karanlığı yutardı

De lo lo lo 

Çığlıklar yükselirdi

Öfkeler

İşlenirdi bilince.

Gövdeleri kazınırdı Çınarların 

Dal dal koparılırdı,

Gezinirdi ki bir kara bulut 

Yurdumun üstünde,

Kurt uluması serpilirdi toprağa

Doğumla - ölümle

Bir arada giderdi.

Karanlıktı, emeğe göz koyarlardı 

Gövdeleri kazınırdı Çınarların

Kentler, köyler arasında

Karış karış toprağında yurdumun,

Bombalar dökülürdü

Köklerini sökercesine 

Meşe ağaçlarının... 

Gidendim belki de uzaklara

Bir gece vakti

Karanlıklar içinde

Gövdelerini bulurdum Çınarların

Çığlıklar arasında...

(Ezgilerde Kaldı Yüreğim 1.Kitap)', 'Karanlıktı, emeğe göz koyarlardı, Kol gezinirdi Çınar ağacına Yüklü teknikle gövdesine isimler kazındığında Ve namlunun ucundan sipere yatıl...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/cinara-konan-cigliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim (Canım Kızım Berfu’ya)', 'bebegim-canim-kizim-berfu-ya-mehmet-kucukkarahan-kdoa5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baharın ilk ışıklarıyla,

Merhaba de hayata.

Yağmur damlası gibi,

Sende doğ Nisan Yağmurunda.

Seviyorum seni bebeğim.

Özlüyorum seni bebeğim.

Bekliyorum seni bebeği.

Sende doğ Nisan Yağmurunda.

Adını koydum dünden.

Bağrıma bastım ezelden.

Bekletme çık karşıma birden.

Sende doğ Nisan Yağmurunda.

Canımın canı, biricik kızım BERFU

Keşaplının Günlüğünden 

Mehmet KÜÇÜKKARAHAN

13.04.1998

Saat:23:35', 'Baharın ilk ışıklarıyla, Merhaba de hayata. Yağmur damlası gibi, Sende doğ Nisan Yağmurunda. Seviyorum seni bebeğim. Özlüyorum seni bebeğim....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Küçükkarahan']::text[], 8.5, '{"poet":"Mehmet Küçükkarahan","poet_slug":"mehmet-kucukkarahan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bebegim-canim-kizim-berfu-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşarsam Gerçeklerle Yaşarım', 'yasarsam-gerceklerle-yasarim-salim-erben-6okcp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni avuttuğun yerden geliyorum 

Hatırlatma kendini

Burası son durak dediğin yer 

Çok iyi biliyorum 

Yaşarşam ben, zalım

Gerçeklerle yaşarım 

Bırak bütün güzellikleri 

Mazide kalsın

Ağustos da yağan kar gibi

İçimdeki, bir yalansın...', 'Beni avuttuğun yerden geliyorum  Hatırlatma kendini Burası son durak dediğin yer  Çok iyi biliyorum  Yaşarşam ben, zalım Gerçeklerle yaşarım...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasarsam-gerceklerle-yasarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmen Geçikti Be Kızım....', 'gelmen-gecikti-be-kizim-mehmet-kucukkarahan-6gtqn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur damlası gibi,

Ciğ tanesi gibi,

Yeni doğan bebek gibi,

Heyecanlıyım gel artık.

Seni seviyorum.

Seni istiyorum.

Seninim diyorum.

Heyecanlıyım gel artık.', 'Yağmur damlası gibi, Ciğ tanesi gibi, Yeni doğan bebek gibi, Heyecanlıyım gel artık. Seni seviyorum. Seni istiyorum. Seninim diyorum. Heyeca...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Küçükkarahan']::text[], 8.5, '{"poet":"Mehmet Küçükkarahan","poet_slug":"mehmet-kucukkarahan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gelmen-gecikti-be-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasana', 'anlasana-mehmet-kucukkarahan-e68q4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen insanın içine hüzün çöker ya, 

Yüreği sıkışır dertlerini anlatamaz ya, 

Birden bire öyle bir şey oldu bana. 

Halime bakıp, dertlerimi anlasana. 

Şimdi kanadı kırık kuş gibiyim. 

Aşk kemendi boynumda esir gibiyim. 

Ben sevdalı ben âşık birisiyim. 

Halime bakıp, aşkımı anlasana.

Baharda günlerim kış oldu. 

Sevda çiçeğim, sararıp soldu. 

Aşkın yüreğimde küllendi, köz oldu. 

Halime bakıp, sevdamı anlasana. 

Seni kalbime nakış nakış işledim; SİLEMEZSİN', 'Bazen insanın içine hüzün çöker ya,  Yüreği sıkışır dertlerini anlatamaz ya,  Birden bire öyle bir şey oldu bana.  Halime bakıp, dertlerimi ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Küçükkarahan']::text[], 8.5, '{"poet":"Mehmet Küçükkarahan","poet_slug":"mehmet-kucukkarahan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anlasana-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-aysel-zengingul-0gsee', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşündüğümden ibarettir ki,

Sevdamın kıyısına vurmaktayım.

Bir *boşuna*lığın tam ortasıyım

Ne boşa boş oluyorum 

              ne doluya dolmaktayım

Derin bir hasret iklimindeyim

     Ne sevdiğim yakınımda! 

             Ne yakınım can damarımda! 

Bir takvim yaprağına bölüyorum da kendimi; 

Yine yetişemiyorum sevdama

Ya bir mendil gibi kanıyorum ardına,

          Ya bir kör bıçak ağzı varıyorum sonuna.

17/08/2005    00; 04', 'Düşündüğümden ibarettir ki, Sevdamın kıyısına vurmaktayım. Bir *boşuna*lığın tam ortasıyım Ne boşa boş oluyorum                ne doluya dol...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bosluk-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyarbekir Ortasında Vurdular Beni', 'diyarbekir-ortasinda-vurdular-beni-i-sa-tekin-hkrey', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Diyarbekir ortasında 

vurdular beni

Ağıt yakmayın ardımdan

Alın yakın bedenimi

Dicle''ye atın küllerimi

Suya düşen küllerim

Umuda fide olsun

Çünkü ben Dicle''yim

Diyarbakır ortasında

Vurdular beni

Ağlamayın ardımdan

Ağıtlar yakmayın

Dicle''ye atın bedenimi

Vursun dalgalar beni taştan taşa

Alsın götürsün

Ülkemin dört bir yanına

Umut yeşersin, fidan olsun

Mezopotamya''nın bereketli topraklarında

Çınar olsun, doğan güneşi selamlayarak.

Diyarbekir ortasında

Vurdular beni

Alın kanlı bedenimi

Dicle''ye atın

Dicle anlar beni

Çünkü ben Dicle''yim

Sonsuza dek akarım.

Setler ile durduramazsınız

Çünkü ben Dicle''yim

Fırtına olur

Dalga olur patlarım

Yedi kapı ardında olsa

Ben yine akarım.', 'Diyarbekir ortasında  vurdular beni Ağıt yakmayın ardımdan Alın yakın bedenimi Dicle''ye atın küllerimi Suya düşen küllerim Umuda fide olsun ...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/diyarbekir-ortasinda-vurdular-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsın', 'varsin-suheyl-turkoglu-cojir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seviyorum

Bana cansın,

Ellerimiz

Ayrılmasın.

Kader gülsün

Hiç susmasın,

Mutluluğu

Bırakmasın.

Kalbi delen

Bakışların

Benim olsun,

Bize kalsın.

Unuttuğum

Kıpırtılar

Deprem olup

Yaşı yıksın.

Geçmi kaldım

Bilmiyorum,

Sevgin gelip

Ateş yaksın.

Çok şey çaldı

Hırsız yıllar,

Beynimdesin

Hep sen varsın.

Bestelenebilir.', 'Seviyorum Bana cansın, Ellerimiz Ayrılmasın. Kader gülsün Hiç susmasın, Mutluluğu Bırakmasın. Kalbi delen Bakışların Benim olsun, Bize kalsı...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/varsin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-suheyl-turkoglu-lvuqk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakışların

Hüzün dolu,

Dertlerini

Koy ver gitsin.

Hasret seni

Eritiyor,

Ayrılığa

Yol ver gitsin.

Gülümsedin,

Cennet geldi.

Kederleri

Kov ver gitsin.

Sana bakan

Kem gözlere

Aldırma hiç,

Gül ver gitsin.

Kavuşmamız

En güzeli,

Ele, güne

Boş ver gitsin.

Kara bulut

Aşktan korkar,

Mutluluğa

El ver gelsin.

Bestelenebilir.', 'Bakışların Hüzün dolu, Dertlerini Koy ver gitsin. Hasret seni Eritiyor, Ayrılığa Yol ver gitsin. Gülümsedin, Cennet geldi. Kederleri Kov ver...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bekliyorum-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-suheyl-turkoglu-blwmd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgi denen

Sonsuzluğa

Düştüm işte,

Gel de kurtar.

Aşk denilen

Mutsuzluğa

Girdim işte,

Gel de kurtar.

Hayat suyum

Tükeniyor,

Gördün işte

Gel de kutar.

İsyanım var

Sensizliğe,

Bittim işte

Gel de kurtar.

Bestelenebilir.', 'Sevgi denen Sonsuzluğa Düştüm işte, Gel de kurtar. Aşk denilen Mutsuzluğa Girdim işte, Gel de kurtar. Hayat suyum Tükeniyor, Gördün işte Gel...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-213-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatıcının Aşk Derdi', 'anlaticinin-ask-derdi-gultekin-mustafa-380a5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ayaklarınız en son ne zaman kesildi yerden

yani ne zaman rastladınız aşka yakınlarda

size göre zor bir iş mi mu aşık olmak

oysa umulmadık yerlerde 

aşkı yakalamak elde

şehir içi aktarmalı-aktarmasız hatlarda

bilet kuyruklarında

bir süpermarketin şarküteri reyonunda

bir sinemanın bekleme salonunda

ufkun güneşle buluşmasında

çokça ahmet altan bir kitap sayfasında

gökyüzünün yağmur uygulamasında

ya da gayet naçizane bir şiir tiyatrosunda

hadi durmayın - bırakın bir kenara

çıkarıp atın - hadi boş verin 

bütün kazandıklarınızı

bakın sokaklarda hayat

cıvıl cıvıl akıyor

manasız didişmeler zaten duvar üstü duvar 

hadi temizlenin uyarması bugün bizden 

yarın başkasından olacaktır

ve bize göre

bu yalan hengame, bu kepazelik içinde 

sağ kalabilen hiçbir ruh 

aşksızlığı kaldıramayacaktır', 'ayaklarınız en son ne zaman kesildi yerden yani ne zaman rastladınız aşka yakınlarda size göre zor bir iş mi mu aşık olmak oysa umulmadık ye...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anlaticinin-ask-derdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatıcının Anlaşılma Derdi', 'anlaticinin-anlasilma-derdi-gultekin-mustafa-ewgmz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir gün

yapma çiçeklerin de solduğu bir gün

anlaşılacak solan her şey gibi

bizim de sahte olduğumuz

bu alkışlar, bu temaşa, bu yaygara

altı üstü bir deste şiirde koparılan fırtına

sevgiden anlaşılan 

hep sahip olması bir tarafın öbür tarafa

aşağıdan yukarısına,

eninden boyuna,

karıncasından kararına kadar

bütün mevzular

bir gün hak ettiği değersizliğe kavuşacak

ve her zamanı gelişinde

bütün birliktelikler gibi

kendi yalnızlığına kavuşmak için

ruh ve beden de

birbirinden ayrılacak

ve yine varken anlaşılmayan her varlığın değeri

ancak 

yok olduğunda anlaşılacak', 'bir gün yapma çiçeklerin de solduğu bir gün anlaşılacak solan her şey gibi bizim de sahte olduğumuz bu alkışlar, bu temaşa, bu yaygara altı ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anlaticinin-anlasilma-derdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Hakkı', 'sevda-hakki-deniz-ciloglu-selmi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ansızın girdin hayatıma bir gün. 

Önce farkına bile varamadım ne olduğunun. 

Sonra zamanla garip bir şey oluştu içimde. 

Çözülmesi zor,anlatamadığım garip bir şey işte.

Duygu mu,zevk mi, hayal mi,alışkanlık mı,sevgi mi yoksa aşk mı bu bilemedim.

Düşündükçe,çözmeye çalıştıkça sonu olmayan bir yere sürüklüyordu beni. 

Tıpkı bir girdap gibiydi. 

Gizem çoğaldıkça inanılmaz derecede seninle,seni yaşama arzusu belirdi içimde. 

Yaşadıkça çözülecekti bu gizem. 

Bu arzumu geri çevirmedin. 

Yaşamaya,paylaşmaya dair bir adım attık seninle. 

Bu yolda seninle yürümek mutlu ediyordu beni. 

Tek sebebim oldun sonra. 

''sen ve hayat, '' 

Hiçbir lisanda yoktu bunun manası. 

Senin yanında her şey manasız kalıyor,hayatın anlamını gözlerinde buluyordum. 

Artık sensiz bir hayat düşünemiyordum. 

Sensiz tek bir saniyem bile en büyük kaybımdı.

Seninle yaptığım hatalar ise benim tek doğrumdu

Senli  hiçbir şeyden pişman olmadım

Seninle nefes alıyor,sensiz defalarca ölüyordum

Sonunda bulmuştum yolumu

Artık hayata isyan etmiyor,neden yaşıyorum diye sormuyordum

Çünkü cevabını bulmuştum

İlk defa yaşadığımı hissetmiştim

Hayatı sende tanımıştım

Ne çok şeyi paylaştık seninle 

Ne çok mutluluk,ne çok heyecan yaşadık

Hüzün bile güzeldi seninle

Milyonlarca kişi arasından yalnızca seni seçti yüreğim

Yanında kalakaldım

Senin yanında dünya durdu,tek dünyam sendin

Gözlerine baktıkça nefes alabiliyordum

Seni benden ayıracak hiçbir gücün olmadığına inandım

Ayrılık neydi bilmiyordum

Ama sen hayatıma ansızın girdiğin gibi,

Ben hiç beklemezken,aniden çıkıverdin

Şimdi anladım senden daha çok senin mutluluğunu istiyormuşum ben

Eğer sen böyle mutlu olacaksan bende olurum

Eğer gitmek seni mutlu edecekse yolun açık olsun...

Bu kalp,bu bedende attığı sürece sen hep içinde olacaksın

Seni benden ayıracak bir güç varmış belki ama:

Unutturacak asla

Ben seni sevme hakkımı kullanıyorum

Ve ömrümün sonuna kadar da kullanacağım

Buna sen bile karşı koyamazsın... (13 ekim 2005 sa.o1:08)', 'ansızın girdin hayatıma bir gün.  Önce farkına bile varamadım ne olduğunun.  Sonra zamanla garip bir şey oluştu içimde.  Çözülmesi zor,anlat...', ARRAY['Türk Edebiyatı','Şiir','Deniz Çiloğlu']::text[], 8.5, '{"poet":"Deniz Çiloğlu","poet_slug":"deniz-ciloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/sevda-hakki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanca yaşam/ak!', 'i-nsanca-yasam-ak-kerime-kaya-imbpn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dur durak demeden

geçmişimin yıllarını

gömüyorum kor-karanlık

zindanlarıma.

bugünü düşlemekteyim 

beyaz bulutlu gökyüzünün

derinliklerinde.

sarı pencerenin açılıp

mavi yeşil sularında 

görmek,

geç kalmış değiliz,

…...savaşmalıyız beyinlerde,

……….buluşmalıyız ellerde,

……………bütünleşmenin gücüyle.

…………………amacımız 

…………………….insanca yaşam/ak! 

toprağın suya

suyun yağmura gereksinimi, 

insanca yaşam hakkım/ız.

gitmekteyiz kurulu düzenin

verilmiş kararlarında

dünü sorgulamadan

açılacak sürprizlere. 

bilmez(midir)    insan 

emeksiz olmaz hayatta düzen

verir mi sana sahip olmadan

hediyesini pakette? . 

kaybolmuşuz iş, ev, magazin 

düşünmez olmuşuz…

……………………………….nerden 

……………………………….nereye 

……………………………….gider 

……………………………….insan/lık.

hep iyi görmüşüz yolu, suyu

her yıl değişen kaldırım taşlarını

oysa değişmekte olan; 

hür akıl, vicdan, demokrasi.

ilelebet bağımlı/lık

borçlu düzenimizde…

…...savaşmalıyız beyinlerde,

……….buluşmalıyız ellerde,

……………bütünleşmenin gücüyle.

…………………amacımız 

…………………….insanca yaşam/ak! 

buğday başağa

başak buğdaya dönüşür; 

üretilen nerde? 

üreten neresinde? 

boş vermişliğin gerçeği.

ithal etmeyi biliriz, en iyisinden. 

kanayan içimizi

sarmalamayı başaran, bizler

sorgulamayı da unutur olduk.

örülmüş dört bir yanımız

gizliden gizliye

görme/mek nerde? 

görüp de bilenlerden olduk; 

aramızdaki konuşmalarda

yeri geldi ayyuka çıkardık

ne çare dedik sonunda.

her evde elektrik, su

gelmedi mi? 

geldi.

bilmez(miyiz)    sanki 

neyin

nereden 

nasıl 

getirildiği.

işte yine başak misali

üretilen ne

üreten ne…? 

kim bizi anlar da 

anlatır içler acısı tablomuzu.

kol gezdi bir zamanlar

düşünceler yasaklandı

düşünüp/yazanlar.

gidenlerin arkasından 

baktık 

üzülürcesine 

görülen gerçekte.

…...savaşmalıyız beyinlerde,

……….buluşmalıyız ellerde,

……………bütünleşmenin gücüyle.

…………………amacımız 

…………………….insanca yaşam/ak! 

insan olduğumuzu hatırla/tmak….', 'dur durak demeden geçmişimin yıllarını gömüyorum kor-karanlık zindanlarıma. bugünü düşlemekteyim  beyaz bulutlu gökyüzünün derinliklerinde. ...', ARRAY['Türk Edebiyatı','Şiir','Kerime Kaya']::text[], 8.5, '{"poet":"Kerime Kaya","poet_slug":"kerime-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/insanca-yasam-ak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtuluşumsun', 'kurtulusumsun-suheyl-turkoglu-9yts4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevginle atarken

Şaşırdı kalbim,

Bozuldu ritmi,

Gel de ayar ver.

Kaldıramıyorum

Artık hüsranı,

Kurtar karanlıktan

Gel de ümit ver.

Seni meze yaptım

Sensizliğime,

Avuç açıyorum

Gel de hayat ver.

Beni benden aldın,

Bana geri ver,

Ben sende kayboldum,

Gel de buluver.

Kaderim değişti

Bakışlarınla,

Bundan sonrasını

Gel de yazı ver.

Bestelenebilir.', 'Sevginle atarken Şaşırdı kalbim, Bozuldu ritmi, Gel de ayar ver. Kaldıramıyorum Artık hüsranı, Kurtar karanlıktan Gel de ümit ver. Seni meze...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kurtulusumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmgelem', 'i-mgelem-melih-coskun-5hxe3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen kendi ruhunun resmini çizebiliyor musun? 

Aynalarda görünmeyişinin 

Otuz iki dişinle gülemeyişinin

Sen kendi ruhunun resmini çizebiliyor musun? 

Koskoca evrenin 

Bir cümleye sığdırılmış şiirini 

İçinde bir yerlerde 

Koşup oynarken düşen çocuğun 

Kanayan dizini,

Neşter vurdukça 

Durdurabiliyor musun kanamasını cümlelerinin? 

Acılarınla yoldaş olup yalnızlığında

Başkaldırabiliyor musun yapılan haksızlıklara? 

Kalemsiz kağıtsız kalsan da

Kanınla yazabiliyor musun umudun şiirini 

Göğsünün yıkılmaz duvarlarına...

2005', 'Sen kendi ruhunun resmini çizebiliyor musun?  Aynalarda görünmeyişinin  Otuz iki dişinle gülemeyişinin Sen kendi ruhunun resmini çizebiliyor...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/imgelem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milenyum', 'milenyum-faruk-tak-3lic7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Demir kapı

Mazgal

Taş duvar

Değişen ne var?', 'Demir kapı Mazgal Taş duvar Değişen ne var?...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tak']::text[], 8.5, '{"poet":"Faruk Tak","poet_slug":"faruk-tak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/milenyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatıcının Final Derdi', 'anlaticinin-final-derdi-gultekin-mustafa-ohan4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sana bir sır daha; 

ya yaşama numarası yaptın şimdiye dek

ya da hep ölüydün

ya şiiri sevdin şimdiye dek

ya da hep yorgundun

şiir yalnızca tesellidir sihrine inanana

bizim duamızdır ki tanrıdan

şiir gibi bir ömür isteriz

uzun, kısa, cömert, dalgacı, huysuz

anlatılamayanı anlatsın

yaşanamayanın hayalini isteriz

ama bir sorun var? ...

Söndü mü ışıklar

Yorgunluk başlar

Cetvelle çizilmiş bir koca dünya

Uykusuna gömülecek

Yandı mı ışıklar

Koşturma başlar

Yaşıyor numarası yapar ölüler

ama bir sorun var? ...

güzel mesaileriniz sizleri bekler

bundan sebep ki

onuncu ışık da söner

ve biz şiirlerimizi gömmeye gideriz', 'sana bir sır daha;  ya yaşama numarası yaptın şimdiye dek ya da hep ölüydün ya şiiri sevdin şimdiye dek ya da hep yorgundun şiir yalnızca te...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anlaticinin-final-derdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-suheyl-turkoglu-yixpv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalpte açsın

Güzel çiçek,

Kokladıkça

Aşk gül olur.

Damla, damla

Aksın sevda,

Hiç ummazsın

Aşk göl olur.

Sevgi taşır

Bakışmalar,

Kavuşmaya

Aşk yol olur.

Kusurların

Lütuf bana,

Görmüyorum

Aşk kör olur.

Arzuları

Taşırırsak

Bir bakarsın

Aşk sel olur.

Tut elimi

Sarıl bana,

Biz istersek

Aşk kul olur.

Değerini 

Bilemezsek

Hemen biter,

Aşk pul olur.

Bestelenebilir.', 'Kalpte açsın Güzel çiçek, Kokladıkça Aşk gül olur. Damla, damla Aksın sevda, Hiç ummazsın Aşk göl olur. Sevgi taşır Bakışmalar, Kavuşmaya Aş...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ask-466-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-ayse-pehlivan-qvbxc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ucu kanarya yüreğinin

Kanar işte öylesine

Hani seversin birden

Seversin ölesiye....

Büyük bir uçurumdur

Gün ile dün arası

Ne ordasın ne burda

Durursun öylesine....

Hep demek istersin ya

Sözlerin de hazırdır

Zorunludur adeta

Susarsın öylesine....

Kimi görsen umarsızdır

Senin yaran kanarken

Kaçınılmazdır artık

Gülersin öylesine.....', 'Bir ucu kanarya yüreğinin Kanar işte öylesine Hani seversin birden Seversin ölesiye.... Büyük bir uçurumdur Gün ile dün arası Ne ordasın ne ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Pehlivan']::text[], 8.5, '{"poet":"Ayşe Pehlivan","poet_slug":"ayse-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oylesine-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-ayse-pehlivan-hxp42', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman delifişek yüreğimde

Şeytan değil ben doldurdum içini

Kimse değil ben işledim suçumu

Kim soracak,

Kim bilir ki kaçını

Şimdi artık zaman 

Benim zamanım

Ben zaman içinde; 

Hem yolcu 

Hem hanım

Daha dün diyordum

Sığınmalıyım

Daha dün diyordum,

Kırılmalıyım

Daha dün diyordum

Bağlanmalıyım

Bu güne gelince 

Dünde kaldılar

Beni yakmak zordu

Onlar yandılar….', 'Zaman delifişek yüreğimde Şeytan değil ben doldurdum içini Kimse değil ben işledim suçumu Kim soracak, Kim bilir ki kaçını Şimdi artık zaman...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Pehlivan']::text[], 8.5, '{"poet":"Ayşe Pehlivan","poet_slug":"ayse-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaman-242-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlasana', 'hatirlasana-ayse-pehlivan-wtyf4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birden yine estin derin bir ruzgar gibi

Eğdi tüm ağaçlar başlarını

Sana selamdı

Sana merhaba,

Oysa seninki veda

Kaç bahçe geçtik biz

Ben korkak ve ürkektim

Hatırlasana

Kaç çiçek büyüttük

Bizden sonrakiler için

Hiç dönüp bakmadan

Öncekilerin yaptıklarına…

Durağı kaybedeli

Yıllar oldu diyorken sana

İnanmazdın

Anlamazdın 

Ve işte tam da bu nedenle ağlamazdın

Hatırlasana

Kaç kez tökezlediler bizi

Durağı fark edemedik yine

Yine vazgeçmedik

Derin uçurumlar geçtik.

Paylaşmak için

Sahip olmaya çalışmaktı bizimki

Sen kızardın

Bozardın

Oynardın kendi kalene gol atarak

Hatırlasana

Oysa ki galiptin kendi galibin

Alkışlayanlar körlermiş meğer

Şimdi fark edince

Sağırlara anlattıklarımızı

Kızmasana

Ne çok konuşurdum ben

Bazen dinlemek istemediğini bilerek

Bilmen gerektiğine iman ederek

Sen bilmiyormuş gibiydin

Bilmen gerektiğini

Hatırlasana

O günün luzumsuz cümlesi

Bu gün muhtaç olduğun

Ben yorulmam 

Yine yeniden ne cümleler kurarım

“Kendine güven ne olur

Önemlisin

Asilsin

Bilgilisin

Ama

İnan bana

Eğer dünün seni yakalarsa

Sen delisin…..”

Ben anlatırdım hani

Duyman dinlemen için

Sen dinlemesen,

Senin yerine 

kendime kulak kesilirdim

Sen dinlerken yabancıydın

Gülerken, yalancı

Hatırlasana

Dürüst olmaya benim ihtiyacım var

Sen de ihtiyaçlarına baksana

Gerçek bir okul hatıralar,

Okuduklarını anlasana..

Hani birgün sevinerek gelmiş ve

Şimdi aştık o yolu demiştin

Oysa ki başında olduğumuzu 

Görmezden gelmiştin

Hatırlasana

Yorulmuştuk, 

Yormuştuk, 

Yollar aşmıştık,

Ama o yolun anlamına sonunda ulaşmıştık.

Biz dostum,

Biz aslında

Başkasının yolunu aşmıştık, bizim  sanarak

Dertleri çekiyorduk, yarım yarım sayarak

Sonra birgün

Yılları saydık

Birden bire ne çokmuş fark ettik

Oysaki bir’den diğer bir’e

Ama ne çok 

Çok ne ama

Aslında 

Boşver hatırlama

Sonra bir gün, hani o gün

Fark ettin vazgeçmedin

Neyse ki ben senin yerine

Tüm intikamlardan vazgeçtim

Senden değil,

Senin yerinden değil,

Senin yerine..

Anlasana..

Hadi şimdi

Gücün varsa ağlasana

Ağlasan haa zayıf derler sonra

Doğru değil mi bu

Doğrunun farkına varan

Suçlanır mı? 

Doğruya ulaşılmasından korkulur mu? 

Bu payımıza düşenin bölümü

Hep büyük parçaları bize verdiler

En ağır yüktü

Onlar vazgeçtiler

Sonra sahiplendik

Sevdik bunu

Onlar adına kazanmayı

Bilmiyorduk, söylemediler

Kendi adımıza kaybetmekte olduğumuzu

Sıfatımıza sıfatlar eklendi

Falancanın çocuğuyduk

Filancanın öğrencisi

Mahallenin yaramazı

Yaşlı hastanın kabusu

Camcının arkadaşı

Hatırlasana 

Büzülerek yatsak ta yatakta

Büyüyorduk işte

Farkında olmadan, ayırdına varmadan

Hadi hatırlasana

Önceki korkularımıza rağmen yaptıklarımızı

Şimdi korkmadığımız sadece onlar kaldı…

Hep büyümek isterdik

Uzaklara gidelim derdik

Uzak dediğimiz yer

Olduğumuz yerin dışıydı

Bizden biraz aşırıydı

Hatırlasana

Uzak dediğimiz yer

Mecburiyetlerimizin ulaşamadığıydı

Mecburiyet sayardık

Bakkala gidip ekmek almayı

Mecburiyet sanırdık

Akşamın karanlığında

Oyundan eve çağrılmayı.

Bugün uzaklardayız

Büyük tuzaklardayız

Hatırlasana 

Gitmiş gibi hayal ederdik

Hep zengin olurdun sen

Çocuklara para verirdin

Oyuncak alsınlar diye

Sonra büyüdük

Oyuncakçı dükkanında izimiz kaldı

Oyuncaklarda gözümüz

Birbirimize verdiğimiz sözümüz kaldı…

Sen mecburiyetlerin mahkumu

Ben de duygularımın

Boşver deme

Boş aldık zaten

Boş verme sen…

Şimdi gittin 

Gitmek istedin ve gittin sen

Şimdi de vaktini

Bizimle yaşadıklarına verdin…

Şimdi de oralardan hep buralara gelmek isterdin.

Boşver deme

Boş aldık zaten

Baş ver ama boş verme

Nasıl hesap veririz bastığımız yerlere

Boş verme….', 'Birden yine estin derin bir ruzgar gibi Eğdi tüm ağaçlar başlarını Sana selamdı Sana merhaba, Oysa seninki veda Kaç bahçe geçtik biz Ben kor...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Pehlivan']::text[], 8.5, '{"poet":"Ayşe Pehlivan","poet_slug":"ayse-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":160,"source_url":"https://www.antoloji.com/hatirlasana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanıyorum', 'utaniyorum-suheyl-turkoglu-5hl4y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Esti yine

Aşk rüzgarı,

Kalbime gir,

Gönlüme bak.

Yangındayım

İçin, için,

Dokun bana

Nabzıma bak.

Utanırım

Anlatamam.

Gel yanıma

Gözüme bak.

İstiyorken

Gizliyorum.

Anla beni

Yüzüme bak.

Açtım sana

Kapıları,

Geç kalmadan

Girmeye bak.

Bestelenebilir.', 'Esti yine Aşk rüzgarı, Kalbime gir, Gönlüme bak. Yangındayım İçin, için, Dokun bana Nabzıma bak. Utanırım Anlatamam. Gel yanıma Gözüme bak. ...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/utaniyorum-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaktadır Yavrucak', 'sokaktadir-yavrucak-ayse-pehlivan-ty660', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sokaktadır yavrucak

Elindeki oyuncak

Yerdeki o kumlardı

Beynindeki hayali

Büyük adam olmaktı

Hep düşlerdi evleri

Evdeki şenlikleri

Onun sokaktı evi

Gönlündeki hayali

Bir evde yaşamaktı

Üşümüştü bak yine

Soğuk doldu içine

Özlem de yüreğine

Yine olanlar oldu

Gözleri yaşla doldu

Nasılsın dese biri

O ağlayıverirdi

Saçını okşasalar

Yavaşça eğilirdi

İyiliği bilirdi

Küçücük bir tebessüm

Ona dünyalar verdi

Hani dün işte ordan

Biri sevgiyle geldi

Ona yiyecek verdi

Gelir mi ki diyerek

Hep orada bekledi

Ümitleri yükledi

Ha bugün yarın derken

Günler sabrı tüketti

Kimse umursamadan

Yanından geçip gitti

Açtı o üşüyordu

Evi de yoktu şimdi

İlikleri titredi

O böyle kederdeyken

Başka birisi geldi 

Açlığı önemsedi

Al hepsi senin dedi

Yüreğini gösterdi

Sevilmek buydu işte

İnsanlık işte burda

İnsandı işte o da

Oda oldu tüm dünya

O daldı rüyalara

Bütün güzelliklere

Verecek tek cevabı

Gönlündeki sevdaydı

Gözüyle güller saçıp

Yarından ümitvardı.', 'Sokaktadır yavrucak Elindeki oyuncak Yerdeki o kumlardı Beynindeki hayali Büyük adam olmaktı Hep düşlerdi evleri Evdeki şenlikleri Onun soka...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Pehlivan']::text[], 8.5, '{"poet":"Ayşe Pehlivan","poet_slug":"ayse-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/sokaktadir-yavrucak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Biterse', 'ya-biterse-suheyl-turkoglu-vzvic', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlüm dolu

Sevgin ile,

Korkuyorum

Ya biterse.

Bakışların

Sevda yolu,

Korkuyorum

Ya biterse.

Sen gülerken

Açan güller,

Korkuyorum

Ya biterse.

Bitmeyecek

Sandığım aşk,

Korkuyorum 

Ya biterse.

Direndim hep

Ayrılığa,

Beraberlik

Ya biterse.

Bestelenebilir.', 'Gönlüm dolu Sevgin ile, Korkuyorum Ya biterse. Bakışların Sevda yolu, Korkuyorum Ya biterse. Sen gülerken Açan güller, Korkuyorum Ya biterse...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ya-biterse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-burhanettin-akdag-ajjfv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatımda kendimi bildiğim andan itibaren öncelikle sevmeyi, sevgiyi, acımayı hep annemden öğrendim doğal olarak...

     Ama, hayatın dik uçurumlarından aşağıya düşmeden ve kaymadan inmeyi; dimdik tepelere de, hayatın dallarına sıkıca tutunarak tırmanmayı ve bu şekilde, o özlemini duyduğum zirvelere ulaşmayı da babamın sert mizacından öğrendim. Hele ki çocukluğumdan beri kulağımda çınlayan bir sözü var ki, hayatın ince sırrı gibiydi: ''Oğul, sen işten korkma, iş senden korksun''...

     Geriye adım atmama felsefesinin ilk tohumlarıydı bu kelimeler benim için. Sonra da, sert rüzgarlarda sağa sola hafifçe esneyerek,  amma yere çok sıkı ve sağlam basarak yıkılmamayı ve hep dimdik durmayı öğrendim...

     Daha küçük çocukken, babam pazar günleri de çalışırdı. Her pazar biz üç kardeş uyanır uyanmaz hemen babamın yatak odasına koşardık, ama tabii sonuç hüsran olurdu, çünkü babam yine erkenden çalışmaya gitmiş olurdu. İçimiz burkulurdu ama annem, babamızın çalışması gerektiğini, yoksa bizim rahat okuma hayatı sürdüremiyeceğimizi söyleyerek yatıştırırdı. İşte daha o zamandan anlamıştım hayatla mücadelede en önemli unsurun ''çalışmak, çalışmak. hatta daha da çok çalışmak'' felsefesinde yattığını...

     Liseyi bitirip üniversite sınavına girdim ama tatminkar yerler kazanamadım 1972 yılında. Babam zararı yok seneye kazanırsın diyerek teselli etmişti. Ama aradan bir ay bile geçmeden birgün bana kızdı ve böyle boş oturacağına gazeteyi incele, İstanbul''da bir hazırlık kursuna yazıl dedi. O dönemde Zonguldak''tayız ve ben bir keresinde 4 günlüğüne 1968 yılında gelmiştim İstanbul''a. Kaldı ki o zamanlar bu kurslar yeterince yoktu ve yeniydiler. Ama babam nasıl olduysa bu noktayı yakalamıştı, kendisi ilkokuldan sonra istediği halde dedem rahmetli okutmamıştı kendisini. Başarının sırrını görerek o meşhur tarihi sözü söylemişti: ''sen yeter ki oku, ben ceketimi satacağım yine seni okutacağım''. Bu sözü her hatırlayışımda bugün bile gözlerim doluyor hüzünle...

     Ve ben böylece İstanbul''un yollarına koyuldum, bir sonbahar akşamının kışa dönmeye başlayan kızıllığının, ayaza çaldığı soğuk ve puslu bir gecede başladı umuda yolculuğum. Geliş o geliş buralara, kaldık ki ne kalmak. Başlarda acemiliğim nedeniyle pek çok sıkıntı ve zorluğu yaşadım. Hayatı tanıdım, yeni dostluklara yelken açtım. Acı tatlı birçok şey yaşadım.

     Şimdi babamlar da İstanbul''dalar. Ve ben birgün babama dedim ki: ''Baba Allah senden razı olsun, sen beni o zamanlar evden kovmasaydın, bugün hayatı bu kadar dolu yaşayan ve tanıyan bir insan olamazdım. Zonguldak''ta sıradan bir insan olarak kalırdım, amaçsız, sıradan ve statükonun dişlilerine kendini teslim eden birisi olurdum''.

     Ayrıca beni Zonguldak''tan yolcu ederken söylediğin tarihi cümleyi de unutamadığım gibi, hayatımın akışında hep yön gösteren bir kuzey yıldızı gibi parladı. Annem bana binlerce tembih, nasihat ve telkinlerde bulunurken,  sen sadece tebessüm ettin. Sıra seninle vedalaşmaya gelince de şunları söyledin: ''Oğlum, ben sana hep güvendim, yine çok inanıyor ve de güveniyorum. Sen ne yapacağını bilirsin, yolun açık olsun''. İşte bütün sır da bu cümlede saklıydı...

     Bütün yaşantımdaki çetrefil ve hengame içinde ne zaman yanlışa ve dara düşsem, hemen hafifçe gözlerimi kısarak, babamın bilgece sarfettiği o unutulmaz sözleri söylediği anı gözlerimin önünde canlandırdım. Her yerde karşıma çıktı babamın o sözleri sarfettiği an'' ın fotoğrafı. Her seferinde önce irkildim, sonra düşündüm, daha sonra da  babamın hayaliyle hasbıhal ederek kendi kendime ''haklısın baba'' diye mırıldandım. Bugün bu kadar sevecen, duyarlı ve yürekli isem, babamın hakkını hep teslim ederim...

     Ve bugün bu yaşımda babama şunları söyledim: ''Baba, sen beni en zor şartlarda,  en yokluklarda ve hatta yanımda bile değilken o veciz cümlenle doğruluğa yönlendirdin. Ben de işte bugün sana, hayırlı bir evlat olarak vefamı gösteriyor ve evlat olmanın sana hizmet etmenin tadını çıkarıyorum. Üzerinize titriyorum, ama bütün bu yaptıklarımla bile, sizlere olan evlatlık ve vefa borcunu ödeyemem. Dünyadaki en değerli hazineyi önünüze sersem, değerinizi ölçemez. Siz beni öylesine yetiştirdiniz ki, hep alacaklısınız benden. Dünya döndükçe de hiç değişmeyecek bu gerçek. Sizleri bütün ömrümce sırtımda taşısam bile hakkınızı ödemekte aciz kalırım''.

     Sen benden hep alacaklısın baba, ama ben de iki çocuk babası olarak diyorum ki; onlara babalığın tüm gerek ve inceliklerini senden aldığım feyz ve bilgi birikimi ile yerine getirmeme rağmen, onlardan zerre alacaklı değilim. Yeter ki onlar benden alacaklı çıkmasınlar. Yaşadığımız şu devir, çok ama çok zor şartlar dayatıyor hayatımıza. Değil bana evlatlık yapmaları, ayakta durmayı başarsınlar yeter benim için...

     Benim yiğit ve bilge babam, işte ben seni o günlerle bu günleri kıyasladığım zaman, gözümde, beynimde, yüreğimde ve duygularımda bu yüzden yıkılmaz abide yaptım. Öylesine abidesin ki yiğit babam, bazan azametine bakarken, ışıltısından gözlerim kamaşıyor bakamıyorum...

     Allah senden razı olsun baba, sana biz evlatlarınla daha nice uzun seneler yaşamak nasib etsin. Ve bana da daha nice uzun yıllar sana evlatlık yapmak nasib etsin...

     Darısı da, bir baba olarak bana nasib olur inşallah...

     Sevgi ve saygılarımla, derin muhabbetlerimle ellerinden öperim baba...

(Şiir Tarlası Grubu ''Baba'' konulu etkinlik için yazılmıştır.)            

(17.10.2005)', 'Hayatımda kendimi bildiğim andan itibaren öncelikle sevmeyi, sevgiyi, acımayı hep annemden öğrendim doğal olarak...      Ama, hayatın dik uç...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/babam-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat Diyorsun', 'anlat-diyorsun-erhan-demir-1qqju', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''''Bana aşk''ı anlat'''' diyorsun

Aşk''ı nasıl anlatayım sana 

Bilmem ki...

Bilseydim aşk''ı eğer

Belkide şair olurdum

Anlatırdım sevgimi mısralarda

Uğruna şiir olurdum

''''Bana gözlerimi anlat'''' diyorsun

Anlatamam ki...

Anlatabilseydim gözlerini eğer 

Belki de ressam olurdum

Çizerdim güzelliğini defalarca,

Uğruna kağıt, kalem olurdum.

''''Bana biraz sevgiyi anlat'''' diyorsun

Anlatamam ki...

Anlatabilseydim sevgiyi eğer 

Belkide gözyaşı olurdum

Akardım gözlerinden ağlayarak

Uğruna nehir olurdum...

ŞİİR VE YORUM ERHAN DEMİR

__T__E__Ş__E___K___K___Ü___R__ 

Bu şiirmin sesli Demo kayıdı için, müziğiyle eşlik eden SN Hasan Cihat Örter'' çok teşekkür ederim

KAYIT TARİHİ: OCAK 2002', '''''Bana aşk''ı anlat'''' diyorsun Aşk''ı nasıl anlatayım sana  Bilmem ki... Bilseydim aşk''ı eğer Belkide şair olurdum Anlatırdım sevgimi mısralar...', ARRAY['Türk Edebiyatı','Şiir','Erhan Demir']::text[], 8.5, '{"poet":"Erhan Demir","poet_slug":"erhan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anlat-diyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'I ş ı k gözlerime / ı ş ı k gelenleri...', 'i-s-i-k-gozlerime-i-s-i-k-gelenleri-zafer-zengin-etnika-i18jy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.

ben yaşamaya gidiyorum usta

uçurtmam nerede

ya memeleri

yeni çıkmış sevgilim

annemim keteleri

iç’li ‘canımı kavuran

gelmişim on sekize

yakındır vurulmam

ben yaşamaya gidiyorum ‘usta

kefenim nerede

elimde tutuşmuş gül

yüzüme sürdüğüm ‘sevda rüzgarı

kolları lime gömleğim

ucu kırılmış kalemim

usta’üstüme bulut isterim

kalemim nerede

dar ağacı cebime

sıcaklık tutuşsun elime

ışık seriver usta

ışık gözlerime

gelirse sevgilime

yaşamaya gitti ‘de

13 10 2005

.', '. ben yaşamaya gidiyorum usta uçurtmam nerede ya memeleri yeni çıkmış sevgilim annemim keteleri iç’li ‘canımı kavuran gelmişim on sekize yak...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/i-s-i-k-gozlerime-i-s-i-k-gelenleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sen Varsın', 'hep-sen-varsin-suheyl-turkoglu-v7kmm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saçlarının 

Her teline

Şiir yazdım,

Şarkı yaptım.

Gözlerinde

İlk baharı

Hep yaşadım,

Sana baktım.

Ayrılığın

Kabus gibi,

Özlemine

Ağıt yaktım.

Dudak bükme

Üzülürüm,

Gülüşünden

Neş''e kaptım.

Gök yüzünde

Yüce Allah,

Yer yüzünde

Sana taptım.

Bestelenebilir.', 'Saçlarının  Her teline Şiir yazdım, Şarkı yaptım. Gözlerinde İlk baharı Hep yaşadım, Sana baktım. Ayrılığın Kabus gibi, Özlemine Ağıt yaktım...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hep-sen-varsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher vakti s a n dım / s a n gelmeleri...', 'seher-vakti-s-a-n-dim-s-a-n-gelmeleri-zafer-zengin-etnika-abzmk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ılık gözlerinin

perde yaptığı kirpiklerinde

gece vakti üstelik

seher vakti sandım

saçlarına uyandım

nasıl uyku anlatsam

gözümle bilmesem inanmazdın

onlara neli bilmem

ben sevdalı türküler sardım

düşüme baktım

seher vakti uyanmasam

öldüğümü anlamazdım

öyle sevdim ki

uyuduğum yerde mektup kaldım

seher vakti yine

gözlerinle yüzümü yıkadım

günaydınım...

28 06 2005', 'ılık gözlerinin perde yaptığı kirpiklerinde gece vakti üstelik seher vakti sandım saçlarına uyandım nasıl uyku anlatsam gözümle bilmesem ina...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seher-vakti-s-a-n-dim-s-a-n-gelmeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'C a n ımız / c a n gelmeleri...', 'c-a-n-imiz-c-a-n-gelmeleri-zafer-zengin-etnika-b4x5e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'canımız...

ağıt''

koyna sakladığımız

ağrı''

sahip çıktığımız

dost''

harmanımız

sesinden''

anladığımız

canımız''

can kattığımız

vay le le 

türkü'' 

düşmüş dilimize

ölmeden kalkanız''

can gelmiş iç’e

vay le le

gül yakmış dalını''

ateşiyle

ölüm sarılmış rengine''

kırmızı adı''

