INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-kenan-ulusahin-khi4x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaybedince seni yazılarımda

Kalemimi kırdığım ansın sen,

Yüreğimi döktüğüm yazılarıma,

Sanatıma sövdüğüm ansın sen…

Derdimden içtiğim aşk şarabına

Gözyaşımın karıştığı ansın sen,

Şarabın kabına sığmazcasına

Yerlerime döküldüğü ansın sen…

Sensiz bir hayatı düşündüğümde

Umudumu kaybettiğim ansın sen,

Sana hibe ettiğim bu yüreği,

Bir kurşunla yitirdiğim ansın sen…', 'Kaybedince seni yazılarımda Kalemimi kırdığım ansın sen, Yüreğimi döktüğüm yazılarıma, Sanatıma sövdüğüm ansın sen… Derdimden içtiğim aşk şa...', ARRAY['Türk Edebiyatı','Şiir','Kenan Uluşahin']::text[], 8.5, '{"poet":"Kenan Uluşahin","poet_slug":"kenan-ulusahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-659-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hem De Ne Sevmek', 'hem-de-ne-sevmek-burhanettin-akdag-i5x47', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmurlu, fırtınalarla boğuşan

Puslu ve kara bir sonbahar günüydü o gün

Yol bulamıyordu sular,  kavga ediyordu akmak için

Soğuk, rutubetli ve kötü bir akşam vaktiydi

Büzülmüş kalmıştın, merdiven kuytusunda

Kömür karası gözlerin parlıyordu, karanlıkta

Ürkmüş, üşümüştün.

Sarmaya çalışıyordun korkularını, çaresizce

Isıtmaya çalışıyordun, titrek bedenini...

İşte böyle bir anda uzattım sana, ellerimi

Korkmuştun önce, kavuşturdun ellerini karnında

Kapattın kendini kirpi gibi, iki büklüm

Artmıştı korkun, titriyordun zangır zangır

Dişlerinin takırtısı geliyordu bana kadar...

Dokundum omuzuna hafifçe

Okşadım ıslak ve yapış yapış saçlarını

Sıcak ve sevecen avuçlarımda, ısıttım

Açıldı bedenin yelpaze gibi, ağır ağır

Tuttun ellerimi sıkıca, doğrulmak istedin 

Yoktu ki mecalin, devrildin geriye tekrar

Kucakladım narin vücudunu

Sarıldım sevgiyle, koruma duygusuyla

Ağladı bakışların, aktı yüreğime bir ateş topu

Bu kadar mı ağırdı çaresizliğin, umutsuzluğun? 

Atmışlardı sokağa seni, ölen eşinin ailesi

Koparmışlardı çocuklarından, yuvandan

Kalmamıştı umarın, sığınacak kapın

Ölümü bekliyordun sanki, son çare 

Ama, takılmıştın bir kere gözlerime orada

Karaltı halindeki çaresiz kıpırtılarınla

Gidememiştim ne bir adım ileriye, ne de geriye

Kilitlenmişti adeta zaman, durmuştu yelkovan

Böylesine hazin, acılı, elem doluydun

Yuvasız kuşlar gibiydin, solgun, bitkin...

Sevdim seni bu mahzun halinle, kömür gözlüm

Isındı yüreğim sana, ıslak sevdalım

Bu, hayatta son yıkılman olacak senin

Düşüncelerindeki son yılgınlıkların olacak

Üzülmeyeceksin, unutacaksın acılı geçmişini

Dönmeyeceksin artık gerilere, küllenmiş anılarına...

Tabii bu, son ağlaman olmayacak elbet

Hatta, daha da çok ağlayacaksın kömür gözlüm

Acıyla akmayacak artık, yaşlar gözünden

Sevinç gözyaşları dökülecek, sevda pınarından

Kurumayacak yüreğin, taşacak yatağından ırmağın

Okyanuslara dönecek, biriktirdiğin özlemlerin...

Sevdim seni bir kere kömür gözlüm, sevdim

Hem de ne sevmek, tarifsiz, anlatılmaz. sonsuz...

(18.10.2005)', 'Yağmurlu, fırtınalarla boğuşan Puslu ve kara bir sonbahar günüydü o gün Yol bulamıyordu sular,  kavga ediyordu akmak için Soğuk, rutubetli v...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/hem-de-ne-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamoz', 'yakamoz-kenan-ulusahin-vuq46', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimde yalnızlık şarkıları

En acı makamında çalmakta,

Elimde sigaramın sıcaklığı,

Ay gizliden bakmakta…

Gözlerime düşen yakamozda,

Yırtık resmimi gördüm avuçlarında,

Unutmak istiyordun sanki beni,

Ben yoktum artık yarınlarında…

İsterdim ay mutluluğumuzu yansıtsa,

El ele görünsek her yakamozda,

Unuttuğun hatalarım olsa,

Yarınlarında olsam, dünlerin hatırına….', 'Yüreğimde yalnızlık şarkıları En acı makamında çalmakta, Elimde sigaramın sıcaklığı, Ay gizliden bakmakta… Gözlerime düşen yakamozda, Yırtık...', ARRAY['Türk Edebiyatı','Şiir','Kenan Uluşahin']::text[], 8.5, '{"poet":"Kenan Uluşahin","poet_slug":"kenan-ulusahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yakamoz-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkum', 'korkum-kenan-ulusahin-okv7e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boğulmaktan korktum da

Bakamadım gözlerine

Yüksekten korktum da

Kuramadım hayalini

Uyanmaktan korktum da

Göremedim rüyamda

Düşmekten korktum da

Koşamadım peşinden

Gitmenden korktum da

SEVEMEDİM SENİ BEN....', 'Boğulmaktan korktum da Bakamadım gözlerine Yüksekten korktum da Kuramadım hayalini Uyanmaktan korktum da Göremedim rüyamda Düşmekten korktum...', ARRAY['Türk Edebiyatı','Şiir','Kenan Uluşahin']::text[], 8.5, '{"poet":"Kenan Uluşahin","poet_slug":"kenan-ulusahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/korkum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvar Yazısı', 'duvar-yazisi-yusuf-ter-bjvk4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çarkı döndermek  istiyorsan

