INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz ve Aşkımız', 'biz-ve-askimiz-fahri-emiroglu-1o092', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce yüreğimizde bir umuttu aşkımız 

Sonra büyüdü ve dünyaya ışık oldu

Her ağlayan çocuga üzülmeyi bir borç bildik

Geceleri kaldırımlar inlerdi yalnızlıktan

Biz ilelebet sürecek aşkımız için yemin ettik', 'Önce yüreğimizde bir umuttu aşkımız  Sonra büyüdü ve dünyaya ışık oldu Her ağlayan çocuga üzülmeyi bir borç bildik Geceleri kaldırımlar inle...', ARRAY['Türk Edebiyatı','Şiir','Fahri Emiroğlu']::text[], 8.5, '{"poet":"Fahri Emiroğlu","poet_slug":"fahri-emiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/biz-ve-askimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aralıklar...', 'bir-araliklar-pinar-koc-v7mf3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir aralık kapı buldu benliğim.

Dışarı çıkıp kedimi mi aşmalıydım,

Yoksa içeride kalıp kendimi mi asmalıydım…

Bir aralık kapı buldu bencilliğim.

Kapıları arkamdan mı kapatmalıydım,

Yoksa kapıları yüzüme mi kapattırmalıydım…

Bir aralık bencil benliğimi sordum! ! 

Önce kapıları kırdım,

Sonra kendimi buldum…

1 Aralık! ta iyi bir kul oldum…

                                                         19.10.05      04:48     KDH', 'Bir aralık kapı buldu benliğim. Dışarı çıkıp kedimi mi aşmalıydım, Yoksa içeride kalıp kendimi mi asmalıydım… Bir aralık kapı buldu bencilli...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-araliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz İstanbul...', 'sessiz-i-stanbul-pinar-koc-83pc6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbul’un sessiz gemileri vardı,

Yüzer geçerdi yüreğimin en kuytu köşelerinden…

İstanbul’un sessiz geceleri vardı,

Kaybolurdu benliğim kimsesiz ve sevgisiz sevinçlerimden…

Yaşanmışlığım vardı,

Yaşamaktan korkup sokaklarında sakladığım…

Evsizlerin ısınmak için aldığı,

kocaman ve ateş topu gözlerim vardı! 

Ağlamaktan,göz yaşlarımın donup kalmasından korktuğum

Alev topu gözlerim…

Gerçeklerim vardı,

Dar sokaklarına ürküp,sinmiş

Kalabalığın sindirdiği gerçeklerim…

Yüzen gemilerim vardı,

Hayallerimi içine koyup gezdirdiğim…

Batık gemilerim vardı,

Hayallerimin suya düşüp ıslandığı ve kurumadığı

Çocuk hayallerim…

İstanbul’un sessiz gemileri vardı

Sessiz gecelerinde,

Yüzer geçerdi yüreğimin en kuytu köşelerinden…

                                                                                      19.10.05    03:53     KDH', 'İstanbul’un sessiz gemileri vardı, Yüzer geçerdi yüreğimin en kuytu köşelerinden… İstanbul’un sessiz geceleri vardı, Kaybolurdu benliğim kim...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sessiz-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saki', 'saki-emin-acil-5gx6s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'doldur saki 

boş kalmasin kadehim

öp beni yar

öp beni

boş atmasın yüreğim', 'doldur saki  boş kalmasin kadehim öp beni yar öp beni boş atmasın yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Emin Açıl']::text[], 8.5, '{"poet":"Emin Açıl","poet_slug":"emin-acil","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/saki-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Denizi...', 'sevda-denizi-i-brahim-ethem-bingul-1s69f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Med-cezir akşamlarında

Vurur sahile yüreği ile

Yazar sevdasını kumlara

Görsün sevdiği diye süsler midyelerle

---------- Can deniz

Dalgalarını susturup bekler öylece

Gelen yok diye puslanır grilerle

Bazen de ümitle mavileşir gökyüzüyle

---------- Hayat deniz

Karanlıktır ay göndermez şulelerini

Yakamozlarına ağlar

Unutup bulutların münasebetsizliğini

Mehtaba küser

---------- Sevdalı deniz

www.iebingul.com', 'Med-cezir akşamlarında Vurur sahile yüreği ile Yazar sevdasını kumlara Görsün sevdiği diye süsler midyelerle ---------- Can deniz Dalgaların...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevda-denizi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siir İzi', 'siir-i-zi-i-lknur-er-4hqx2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Okuduğum her şiirde bir parça ben bulurum

Sanki benim için yazılmış cümleler

Hemen yazarına bakarım 

Yüreğimle tebrik ederim 

Beynime kazırım her bir cümlesini

Şiir olur girersin düşüncelerime

Şiiri sana armağan ederim sen hiç bilmesende

Okuduğum her şiir bir iz bırakır bende

Öyle içten okurumki

Kendimi içinde bulurum cümlelerin

Hüzünse hüzünlenirim, sevinçse sevinirim

Kendimde yazarım yalan yanlış

Hepsinde de şımarırım

Birazda kızarım kendime

Hepsi sanadır şiirlerimin

Ya gelişine yada gidişine

Biraz nankörüm

Gelişinde unuturumda kağıdı kalemi

Her gidişinde sıkıştırırım küçük kağıtlara

Kocaman Kalbimi', 'Okuduğum her şiirde bir parça ben bulurum Sanki benim için yazılmış cümleler Hemen yazarına bakarım  Yüreğimle tebrik ederim  Beynime kazırı...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siir-izi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyeceksin...', 'ozleyeceksin-mustafa-i-smailoglu-2h40n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'beni bir gün o kadar özleyeceksin ki

her gün resimlerime bakacaksın,

bazen sinirlenip birkaçını yakacaksın,

ama birini mutlaka saklayacaksın.

beni bir gün o kadar özleyeceksin ki,

eski ajandalarda adımı arayacaksın,

sonra gidip onu da çöpe atacaksın.

ama bir yerde ismimi mutlaka anacaksın.

beni bir gün o kadar özleyeceksin ki,

bensizlik mi çok yakıyor,ateş mi deneyeceksin,

yanan ellerinin acısını hissetmeyeceksin, 

düşündükçe çıldıracak, delireceksin.

beni bir gün o kadar özleyeceksin ki,

telefon açıp sesimi dinleyeceksin,

ama sen olduğunu bildiğimi hiç bilmeyeceksin,

hep bizim şarkılarımızı dinleyeceksin.

beni bir gün o kadar özleyeceksin ki,

gözlerini dikip yıldızları izleyeceksin,

benden aldıklarını dolabında gizleyeceksin,

ismimi yazıp bir kağıda etrafını süsleyeceksin.

beni bir gün o kadar özleyeceksin ki,

sana yazdığım şiirleri okuyacaksın,

verdiğim kazağı buram buram koklayacaksın,

beni düşünürken odana kimseyi sokmayacaksın.

beni bir gün o kadar özleyeceksin ki,

birisiyle beni kıskandırmak isteyeceksin,

cevap alamayınca sevgimden şüphe edeceksin,

sonra bir gün benim için ağladığını sezeceksin.

beni bir gün o kadar özleyeceksin ki,

o gün gittiğine pişman olacaksın,

yaşadıkça değerimi,biraz daha anlayacaksın,

sakın kendini öldürmeye kalkma,

çünkü sen bana dayanamayıp öleceksin…', 'beni bir gün o kadar özleyeceksin ki her gün resimlerime bakacaksın, bazen sinirlenip birkaçını yakacaksın, ama birini mutlaka saklayacaksın...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İsmailoğlu']::text[], 8.5, '{"poet":"Mustafa İsmailoğlu","poet_slug":"mustafa-i-smailoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ozleyeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittinya sen yanımdan hani...', 'gittinya-sen-yanimdan-hani-mustafa-i-smailoglu-w7xe2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen gittinya yanımdan hani

bütün ağaçlar döktü yapraklarını,

fırtınalar koptu İstanbul da,

bütün şehri sular bastı.

sen gittinya yanımdan hani,

bütün melekler ağlar oldu,

hiç kimsenin yüzü gülmedi,

hiç akşam olmadı,

güneş hiç doğmadı.

sen gittinya yanımdan hani

hiçbir vapur bağırmadı bir daha

hiçbir araba basmadı kornaya,

hiçbir aşık bakmadı dolunaya.

sen gittinya yanımdan hani,

her gün ellerim titrer oldu,

evdeki kuşlar ötmez,

balıklar yüzmez oldu.

sen gittinya yanımdan hani,

hiçbir sevdalı yan yana gelmedi bir daha,

çocuklar top oynamadı sokakta,

hiçbir yıldız hiçbir gece göz kırpmadı,

şiirler anlatmadı aşkları,

yemekler yetmedi açlıkları gidermeye,

suysa gidermedi susuzlukları.

sen gittinya yanımdan hani,

hiçbir bülbül yan yana gelmedi,

bahçelerdeki güller açmadı,

hiçbir çiftçi tohum saçmadı,

uçaklar kalkmadı,arabalar gitmedi,

sen gittin ya yanımdan hani,

sanki bu şehir yaşamaya yetmedi.

bir tek; 

bir tek ben yaşadım her şeyi,

kandırdım kendimi.

bir sır veriyim mi sana? 

sen gittinya yanımdan hani,

gittiğini kalbim hiç bilmedi…', 'sen gittinya yanımdan hani bütün ağaçlar döktü yapraklarını, fırtınalar koptu İstanbul da, bütün şehri sular bastı. sen gittinya yanımdan ha...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İsmailoğlu']::text[], 8.5, '{"poet":"Mustafa İsmailoğlu","poet_slug":"mustafa-i-smailoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gittinya-sen-yanimdan-hani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O’da Olsun İsterdim', 'o-da-olsun-i-sterdim-ferit-gursoy-3ezv6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar tükenmiş

Geçmiş ömür.

Yorgun bedenimde

Yaşanmamış hiçler.

Ne ağıtlarım oldu

Ne sevdalarım 

Olmadı da  pişmanlıklarım 

Ama

Korkularım oldu

Hüzünlü anlarım

Karamsarlıklarım 

Küçük küçük aşklarım

Ve de yalanlarım

Yıllar tükenmiş

Geçmiş ömür.

Yar diye bağrına

Can diye canına

Katanım olmamış

Bakmayacağım dedikçe mazime

Mazim yüzleşir benimle

Bense

Can diye canına katmasa da

“O” olsun isterdim

Yar diye bağrıma', 'Yıllar tükenmiş Geçmiş ömür. Yorgun bedenimde Yaşanmamış hiçler. Ne ağıtlarım oldu Ne sevdalarım  Olmadı da  pişmanlıklarım  Ama Korkularım ...', ARRAY['Türk Edebiyatı','Şiir','Ferit Gürsoy']::text[], 8.5, '{"poet":"Ferit Gürsoy","poet_slug":"ferit-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-da-olsun-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sokak Çocuğuyum', 'ben-sokak-cocuguyum-ferit-gursoy-6cstt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adım Haşim

Soyadım Garip

Ben yalnızlığın çelişkisi

Karanlığın efendisi

Ben kimsesizliğin abidesiyim.

Terkedilmiş duyguların

Hırçın bağırışların

Acının çocuğuyum

Korkak, ürkek bedenimin 

Tek taşıyıcısı

Ama asla sahibi değilim

Ben deli fikirlerin 

Aptal düşüncelerin 

Terkedilmişliğin, kavganın 

Mahsülüyüm.

Ben sokak çocuğuyum

Ben babasızlığın acısını 

Yüreğinde hisseden 

Ben anasızlığın 

Soğukluğuyla büyüyen 

Ben çamurdan, yağmurdan 

Çıkış arayan

Ufku geniş, yaşamı dar biriyim

Hep karanlıktan korkardım 

Hep aydınlığa koşardım

Birgün karanlığın dostum olacağından habersiz

Hayata başladım

Dedim ya adım Haşim 

Hepsi bu kadar

Ne malım var söyleyecek 

Ne mülküm var beyan edecek

Ne hatıram var anlatacak 

Nede umudum var yaşanacak

Tüm servetim ve bildiğim adım Haşim 

Sokak çocuğu Haşim...

Hırsız Haşim...

Pis kokulu Haşim...

Çapulçu Haşim...

Dilenci Haşim...

Buda size göre Haşim...

Ben bu değilim

Böylede doğmak istemedim

Beni görmek istedikleri gibi

Gördüler..

Korktular..

Tiksindiler..

Dışladılar..

İttiler..

Ben hep onlardan korktum..

Yalnızlıktan korktum 

Kıskandım, bacayı kıskandım

Dumanın nazire yaparcasına

Havayı ısıtmasını

Soğuğa tokat atışını kıskandım

Miflonlu paltoları 

Kadife pantolonu kıskandım

Dua ettim hep güneş

Doğsun diye

Yağmasın yağmur

Açlığa dayanıyorum

Soğuğa asla...

Kendimi sanslı hissediyorum 

Park bahçesinde

Temmuz akşamında,

Yıldızların altında yatarken,

Mart ayında donerken değil

Kıskanıyorum Ali''yi 

Annesinin elinden tutupta 

Okula gidişini,

Beslenme çantasını,

Benim bir ayda yediğim yiyeceği

Bir öğünde yediğini

Kıskanıyorum 70 yaşında ki

Ahmet amcanın selasının okunuşunu

Adım Haşim! 

Ben sokak coçuğuyum...', 'Adım Haşim Soyadım Garip Ben yalnızlığın çelişkisi Karanlığın efendisi Ben kimsesizliğin abidesiyim. Terkedilmiş duyguların Hırçın bağırışla...', ARRAY['Türk Edebiyatı','Şiir','Ferit Gürsoy']::text[], 8.5, '{"poet":"Ferit Gürsoy","poet_slug":"ferit-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/ben-sokak-cocuguyum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harap', 'harap-omer-liman-l521l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne bir aşka medar oldu

Yüreğimiz,

Nede bir nefrete kab,

Yürüyoruz,

Çelimsiz adımlarla,

Yorgun dizler üstünde,

Harap ve bitap.

Kısacık ömürde,

Uzun bir hayat,

Keder yastığında,

Hüzün döşeğinde,

Elem yorganında,

Güneşten habersiz

Aydan uzakta,

Garbın ufukları

Ardında,

Bir gemideyiz

Dost düşman bir arada,

Bir tarafta karanlık,

Diğer tarafta ehli kilab,

Her kafada bir dünya,

Her dünyada serap,

Birinin zevki

Ötekine azap,

Nuru şarka

Sırt çevirmiş kulubla,

yuvasını yitirmiş gurab.

Bi adap

Bi esvap.

Bi hesap.

Ne olacak halimiz,

Ya Rab!', 'Ne bir aşka medar oldu Yüreğimiz, Nede bir nefrete kab, Yürüyoruz, Çelimsiz adımlarla, Yorgun dizler üstünde, Harap ve bitap. Kısacık ömürde...', ARRAY['Türk Edebiyatı','Şiir','Ömer Liman']::text[], 8.5, '{"poet":"Ömer Liman","poet_slug":"omer-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/harap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şansını Zorlama', 'sansini-zorlama-munevver-senol-uerb4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şansını zorlamak boşuna olur

Yaşamın son durağına geldiysen eğer.

On elle sarılsan neye yarar ki? 

Tirenin o acımasız düdüğü çaldıysa eğer.

Tüm yaşamını getir gözünün önüne.

Ne kadar anlamsız boş değil mi ki? 

Az yaşa çok yaşa akibet gelecek başa.

Yaşamın son durağına geldiysen eğer,

Trenin o acımasız son düdüğü çaldıysa eğer

Dünyaya gülümsüyerek bir veda yeter.

Mutluluk ve acı o anda biter biter.', 'Şansını zorlamak boşuna olur Yaşamın son durağına geldiysen eğer. On elle sarılsan neye yarar ki?  Tirenin o acımasız düdüğü çaldıysa eğer. ...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sansini-zorlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Ol', 'i-nsan-ol-derya-aslan-5refu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seher yeli ile saldım yüreğimi engin deryaya 

Bulutlarla mutluluk yağdırdım fani dünyaya

Yürekler nasır tutmuş benzemiş kayaya

Sen dünyayı, insanı sev, sev seni yaradanıda

........................................................................', 'Seher yeli ile saldım yüreğimi engin deryaya  Bulutlarla mutluluk yağdırdım fani dünyaya Yürekler nasır tutmuş benzemiş kayaya Sen dünyayı, ...', ARRAY['Türk Edebiyatı','Şiir','Derya Aslan']::text[], 8.5, '{"poet":"Derya Aslan","poet_slug":"derya-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/insan-ol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Rüya Bitmesin', 'bu-ruya-bitmesin-ahmet-tevfik-ozan-w70k6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mehtaplı gecelerde, alemi seyre dalarız 

Aşkın meze olduğu, sofralarda doyarız.. 

Bizler; görünmez olduk, bir aşkın büyüsünde.. 

En güzel perilerin dudağını, yalarız! ..', 'Mehtaplı gecelerde, alemi seyre dalarız  Aşkın meze olduğu, sofralarda doyarız..  Bizler; görünmez olduk, bir aşkın büyüsünde..  En güzel pe...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bu-ruya-bitmesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şeyler Değişmiş', 'bir-seyler-degismis-ahmet-tevfik-ozan-ls6t5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bulutlar yorgan oldu, yağmurlar; ninni bize..

Kavalın ahengini; çobanlar; verdi bize 

Bastığımız çimenler, acıdan inlemedi..

Çimenler aynı çimen, şimdi; ne oldu bize? ..', 'Bulutlar yorgan oldu, yağmurlar; ninni bize.. Kavalın ahengini; çobanlar; verdi bize  Bastığımız çimenler, acıdan inlemedi.. Çimenler aynı ç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-seyler-degismis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-ahmet-tevfik-ozan-hthmo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Martı kanadında ışıyan gün

Bir kibritle tüttürdüğüm sigara..

Ben üzgünüm... onlar üzgün

Bugün, benim sevdiğimi aldılar! ..

Bu sabah, kahvaltı etmedim 

Karnım acıkmış, ne çıkar..

Öğleyin camiye de gitmedim 

Bugün, benim benliğimi aldılar

Ezanlar okunacak, geceleri.. 

Boynum utancımdan, yana düşecek

Ve inecek, nurlu evlerin pencereleri.. 

Bugün, beni karanlığa saldılar..

Gözleri, aynı kalır mı dersiniz? 

Beni görünce, kızarır mı? 

Ve dökülür mü; dudaklarından, bir:

‘‘Geceyi sever misiniz? ..’’

Bugün, benim düşlerimi yıktılar! ...', 'Martı kanadında ışıyan gün Bir kibritle tüttürdüğüm sigara.. Ben üzgünüm... onlar üzgün Bugün, benim sevdiğimi aldılar! .. Bu sabah, kahvalt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bugun-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leylanın sırrı', 'leylanin-sirri-ali-riza-unal-iyhfv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kays-ı mecnun eden, leylâda Mevlâ şulesi,

Leylâdan bi haberdir, ahmak-ı nefs hilesi,

Aşk hicap olmuş beden ilinde,sırrı mevlâya,

Sinei-i sırdan mahruma Leylâ ne gerek..', 'Kays-ı mecnun eden, leylâda Mevlâ şulesi, Leylâdan bi haberdir, ahmak-ı nefs hilesi, Aşk hicap olmuş beden ilinde,sırrı mevlâya, Sinei-i sır...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/leylanin-sirri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Aşk', 'bitmeyen-ask-ahmet-tevfik-ozan-oc2vu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdim seni, ruh çiçeğim; Leyla’yı severcesine..

Bir günahkar gecenin, koynuna girercesine.. 

Ağzımda kan, burnumda kan, gönlümde kan.. ne çare? 

Kanmadım dudağına, kanını emercesine! ...', 'Sevdim seni, ruh çiçeğim; Leyla’yı severcesine.. Bir günahkar gecenin, koynuna girercesine..  Ağzımda kan, burnumda kan, gönlümde kan.. ne ç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bitmeyen-ask-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Güneş', 'bitmeyen-gunes-ahmet-tevfik-ozan-tnuni', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yaradan kanayan, irin olsa günahım..

Şefkati, bu güneşin; bu güneşin şefkati..

Verir nurunu gene, katreleri yıkarım! 

Ne mümkün çıldırmamak; kimin var ki, takati! ..', 'Bir yaradan kanayan, irin olsa günahım.. Şefkati, bu güneşin; bu güneşin şefkati.. Verir nurunu gene, katreleri yıkarım!  Ne mümkün çıldırma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bitmeyen-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dönüş', 'geri-donus-ahmet-agdere-l46dy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceler, geceler, geceler,

Öcüler benim yolu gözler.

Ayın yüzünden süzülen ter

Benden fazla telaş içinde.

Pervasız beklerim rücuyu,

An dese de, git yavrum uyu,

İçimde çıngıraklı kuyu

Sallanır, sallanır, sallanır...', 'Geceler, geceler, geceler, Öcüler benim yolu gözler. Ayın yüzünden süzülen ter Benden fazla telaş içinde. Pervasız beklerim rücuyu, An dese ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/geri-donus-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşuna Sitem', 'bosuna-sitem-ahmet-tevfik-ozan-7hk4w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zulmetti gönül, ne çare; ben kader mahkumuyum..

Ne yar, hançer olmuş bana; ne, gurbetteki diyar! ..

Ben ki; şu Kainatın Halikı’nın kuluyum..

Şerrinde de (!)  Hayır var, hayrında da Hayır var! ...', 'Zulmetti gönül, ne çare; ben kader mahkumuyum.. Ne yar, hançer olmuş bana; ne, gurbetteki diyar! .. Ben ki; şu Kainatın Halikı’nın kuluyum.....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bosuna-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-ahmet-tevfik-ozan-1i2mk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnız karanlıkların, çıplak çocuklarıyız..    

Bir yıllanmış şarabın, toprak çanaklarıyız..

Dudağını ıslatan şarapta bir hasret var 

Biz hasret ağacının, solgun yapraklarıyız! ..', 'Yalnız karanlıkların, çıplak çocuklarıyız..     Bir yıllanmış şarabın, toprak çanaklarıyız.. Dudağını ıslatan şarapta bir hasret var  Biz ha...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/biz-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşuna Zahmet', 'bosuna-zahmet-ahmet-tevfik-ozan-c6z7q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalpsiz insanlar için, anıtlar dikmek niye? ..

Rabbim; taşı, kayayı onlar için yaratmış! ..', 'Kalpsiz insanlar için, anıtlar dikmek niye? .. Rabbim; taşı, kayayı onlar için yaratmış! .....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bosuna-zahmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma', 'sorma-erdem-yalcin-ffru1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün beni sormuşsun yine dostlara

Ellerin uzanmıyor mu yoksa telefona

Yoksun mu kaldın yoksa ayaklarından

Vazgeçemedin mi hala büyük gururundan

Sen bırakıp giderken haince beni

Hiç mi düşünmedin o güzel geçmişimizi

Bu kadar kolaymıydı silmek hayatından beni

Affedemiyor şu kalbim asla seni

Ben sürünürken sensizliğin içinde

Hayalin yinede bir ışıktı içimde

Çabalarken unutmak için derin sevgini

Kaybettim uzun yıllar  benliğimi

Deli dediler bak.. işte bir garip zavallı

Anlamadılar çoğu kez yaşamı bıraktığımı

Bir delicesine çarpıntıydı sevdan içimde

Aradım hep Seni karanlıklar içinde

Sorma artık neredeyim ve kiminle

Bırak kalayım sessizliğin içinde 

Öldür beni artık düşüncelerinde

Sensizim ya..gerisini düşünme', 'Dün beni sormuşsun yine dostlara Ellerin uzanmıyor mu yoksa telefona Yoksun mu kaldın yoksa ayaklarından Vazgeçemedin mi hala büyük gururund...', ARRAY['Türk Edebiyatı','Şiir','Erdem Yalçın']::text[], 8.5, '{"poet":"Erdem Yalçın","poet_slug":"erdem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sorma-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buzdan Saraylar Yaptım', 'buzdan-saraylar-yaptim-ahmet-tevfik-ozan-66jrp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duydum ki: Yarim beni, gözümdeki yaş ile; bir anlık anıp geçmiş..

Ne bilsin ki; gözyaşı, bu gönül havuzundan taşan en son katredir...

Buzdan saraylar yaptım, kor ateş sevdasına.. belli ki bakıp geçmiş! 

Kahpedir, nice sonra anladım bitmez rüya... buz sarayın, kahpedir! ...', 'Duydum ki: Yarim beni, gözümdeki yaş ile; bir anlık anıp geçmiş.. Ne bilsin ki; gözyaşı, bu gönül havuzundan taşan en son katredir... Buzdan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/buzdan-saraylar-yaptim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyükada Güzellerine', 'buyukada-guzellerine-ahmet-tevfik-ozan-urkh3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerim, gözlerine tutkun 

Ellerim, ellerine...

İnan ki, böyle giderse

Lanet yağacak 

Büyükada güzellerine! ...', 'Gözlerim, gözlerine tutkun  Ellerim, ellerine... İnan ki, böyle giderse Lanet yağacak  Büyükada güzellerine! ......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/buyukada-guzellerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Dostum', 'gercek-dostum-ahmet-ormanci-p30ym', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kadar çok isterdim birine dostum demeyi,

Yanıma çıkarsızca yaklaşan,

Riyasızca konuşan benimle,

Gerçek gülüşlerinde saklı benim dostum.

Severse olduğum gibi sever beni,

Eleştirirse, elbette iyi olmam içindir.

İşlerimde beni hep yüreklendiren,

Gerçek görüşlerinde saklı benim dostum.

Başarıya beraberce koşturan,

Kaldıran eğer düşersem yere,

Hızlı olsa bile benden, 

Yarışı benimle bitiren,

Gerçek düşlerimde saklı benim dostum.', 'Ne kadar çok isterdim birine dostum demeyi, Yanıma çıkarsızca yaklaşan, Riyasızca konuşan benimle, Gerçek gülüşlerinde saklı benim dostum. S...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gercek-dostum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutların Göz Yaşı', 'bulutlarin-goz-yasi-ahmet-tevfik-ozan-i8tih', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlıyorsa bir bulut, semada iç çekerek..

Bir ağaç, gözyaşını; meyvesine alıyor...

Dağılıyor göz yaşı, dillerde eriyerek

Bir göze, renk oluyor..bin bir yürek çalıyor! ...', 'Ağlıyorsa bir bulut, semada iç çekerek.. Bir ağaç, gözyaşını; meyvesine alıyor... Dağılıyor göz yaşı, dillerde eriyerek Bir göze, renk oluyo...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bulutlarin-goz-yasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cam İlminden Bihaberler Ülkesi', 'cam-i-lminden-bihaberler-ulkesi-ahmet-tevfik-ozan-beseq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mağrur Kral, bir gün; belki binlerce

Camdan kadeh, fanus, vazo, kavanoz..

Toplayıp, görkemli salona dizdi...

Renk renk şerbet ve su

Süt. limonata...

Doldurdu camları,ağzına kadar..

Geldi misafirler: Bir hayret... bir şevk 

Gözlerde şaşkınlık, nefesler titrek.. 

Hepsi baygın baygın düştü, yerlere:

''Sen, sulara şekil veren, Hükümdar.. 

Sen, bir ömür tapılacak Mabut''sun! .. 

Sen artık anıtla, putla yaşayan 

Bir ruhsun… tebaan, nasıl unutsun? ...''', 'Mağrur Kral, bir gün; belki binlerce Camdan kadeh, fanus, vazo, kavanoz.. Toplayıp, görkemli salona dizdi... Renk renk şerbet ve su Süt. lim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cam-ilminden-bihaberler-ulkesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar', 'bir-zamanlar-ahmet-tevfik-ozan-dc18e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir pınardan su içip, çölleri; kıskandırdık..

Yağmurlar bizim oldu, selleri; kıskandırdık..

Kalbimizle yükseldik, ufkun sırrına erdik

Büyüyen aşkımızla,devleri kıskandırdık! ..', 'Bir pınardan su içip, çölleri; kıskandırdık.. Yağmurlar bizim oldu, selleri; kıskandırdık.. Kalbimizle yükseldik, ufkun sırrına erdik Büyüye...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-zamanlar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk', 'dostluk-ahmet-ormanci-l5jdo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi midir insanın içini ısıtan,

Yoksa saygı görmek mi? 

Yoksa bütün bunları içine alan,

Dostluk mudur bizim özlediğimiz.', 'Sevgi midir insanın içini ısıtan, Yoksa saygı görmek mi?  Yoksa bütün bunları içine alan, Dostluk mudur bizim özlediğimiz....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dostluk-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Yürek...', 'islak-yurek-dilek-egri-nv8kn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gökyüzü ağla  isyanlarıma,

ağlaki ihanetin ayak izleri silinsin sularınla...

//..benim gözyaşlarım ancak bağrımı ıslatmaya yetiyor..//

yar yüreğime alamam artık seni 

yaşa oturursan üşürsün...

gözlerim ıslattı yüreğimi..

20/10/05

gel/me sırılsıklamım..', 'gökyüzü ağla  isyanlarıma, ağlaki ihanetin ayak izleri silinsin sularınla... //..benim gözyaşlarım ancak bağrımı ıslatmaya yetiyor..// yar y...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/islak-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gönül Bu Yürek', 'bu-gonul-bu-yurek-ahmet-tevfik-ozan-4ydor', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakarsın, bir beyaz duvakta; sevinç..

Bir bitmez gecede, damla damla yaş..

Hüzün, çam sakızı..ak saçlarında

Bu gönül, bu yürek; böyle arkadaş! ..

Yağmur yağmur durulansa, geceler

Rüyalara oluk oluk, kan gelir! ...

Dertlerin taş yürek sokaklarında

Ölüm şerbetiyle, bize can gelir! ..

Uzak, yakın köyümüzün birinde

Her gece bir mezar ağlar derinden! ...

Toprak saklayamaz, gözyaşlarını..

Her seher, bir pınar; fışkırır yerden! ...

Kur’an: gökyüzünden yağan beyaz nur! 

Turan: gözyaşını yıkayan yağmur! 

Ve kan: son şehidin göz bebeğinde

Aslına uçmakta, bir nurdan çamur! ...

Bakarsın, bir beyaz duvakta; sevinç..

Bir bitmez gecede, damla damla yaş! ..

Hüzün, çam sakızı.. ak saçlarında

Bu gönül, bu yürek; böyle arkadaş! ..', 'Bakarsın, bir beyaz duvakta; sevinç.. Bir bitmez gecede, damla damla yaş.. Hüzün, çam sakızı..ak saçlarında Bu gönül, bu yürek; böyle arkada...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-gonul-bu-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ödünç Ver Düşlerini', 'odunc-ver-duslerini-salim-erben-4jjna', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ödünç olsun bu gece

Bana ver bir bakayım

İşlerinde ben varmıyım 

Ben varmıyım 

Bir göreyim, 

Hadi bir yalan söyle

Sana uzak olmayan

Çaktırmadan durumu,

De ki sen varsın 

Sen yaşıyorsun her birinde

Çocuk gibi inandır beni 

Hadi geç karşıma

Gözlerim bak ve gülümse

Merak ediyorum 

Bu gece bana bırak 

Ödünç olsun be zalım

Düşlerinde kendime, 

Senin yüreğinde 

Benim gözümle bakayım', 'Ödünç olsun bu gece Bana ver bir bakayım İşlerinde ben varmıyım  Ben varmıyım  Bir göreyim,  Hadi bir yalan söyle Sana uzak olmayan Çaktırma...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/odunc-ver-duslerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün Kutlu Olsun', 'dogum-gunun-kutlu-olsun-erdem-yalcin-yv87s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep sevdam oldun hayat yolunda

Beraberce yürüdük nice umutlara

Kah neşem oldun kah hüznüm 

Seninle katlandım tüm acılara

Bazen yağmur yüklü bulutlar gibiyim

Dolup dolup boşanıyor yüreğim 

Kimi zaman öksüz çocuklar gibi

Senin sıcaklığını arıyor ellerim

Sen  eşten de öte hep arkadaşım oldun

Yüreğimde yıkılmaz bir taht kurdun

Dar günümde olurken herkes el

Sen benim için hakikatli  dost oldun

Mutluluğun tarifi benim için sensin

Yüreğim çarpar hep senin için

Nasıl anlatmalıyım bilmiyorum

Seni tarifsizce çok seviyorum 

Tüm yaşamın mutlulukla dolsun

Her günün taze bir başlangıç olsun

Asla dert vermesin tanrım bedenine

Sevgilim.. doğum günün kutlu olsun', 'Hep sevdam oldun hayat yolunda Beraberce yürüdük nice umutlara Kah neşem oldun kah hüznüm  Seninle katlandım tüm acılara Bazen yağmur yüklü ...', ARRAY['Türk Edebiyatı','Şiir','Erdem Yalçın']::text[], 8.5, '{"poet":"Erdem Yalçın","poet_slug":"erdem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dogum-gunun-kutlu-olsun-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolum', 'anadolum-ahmet-ormanci-asvyy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey bahtsız yurdum,Anadolum.

Nice divaneler gezer de üzerinde,

Hiç yakınmazsın, belki de yakınamazsın,

Çünkü sen Anadolu''sun.

Ah o ana şefkâti yok mu sende,

Basarsın bağrına bir bir hepsini,

Çünkü onlar da senin öz evladın.

Belki de bekliyorsun,

Bir gün kendine gelirler de,

Uyanırlar mı acep? 

Görürler de mahsunluğu mu,

Benim için uykuları kaçar mı? 

Birkez olsun hatrımı sorarlar mı diye.', 'Ey bahtsız yurdum,Anadolum. Nice divaneler gezer de üzerinde, Hiç yakınmazsın, belki de yakınamazsın, Çünkü sen Anadolu''sun. Ah o ana şefkât...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anadolum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus Gibi', 'yunus-gibi-hikmet-uzun-y83x9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk bahrine dalana,

Aşk oduna yanana,

Aşktan nasip alana,

Ayak öpesim gelir.

Sevmişşe Onu sevmiş,

Gül demiş,Leyla demiş,

Kimi bilmiş,bilmemiş,

Bir ün edesim gelir.', 'Aşk bahrine dalana, Aşk oduna yanana, Aşktan nasip alana, Ayak öpesim gelir. Sevmişşe Onu sevmiş, Gül demiş,Leyla demiş, Kimi bilmiş,bilmemi...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Uzun']::text[], 8.5, '{"poet":"Hikmet Uzun","poet_slug":"hikmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yunus-gibi-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-ahmet-ormanci-8drym', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle olmak zor,

Sensiz olmak daha da zor.

Karanlıkları yırtarcasına,

Doğarsın güneş gibi ruhuma.

Avutur beni geliş-gidişlerin,

Ya bir de gelmezsen..? 

KAranlıları iğne iğne delen,

Yıldızlar gibisin aslında,

Yanıp, sönen.

Parladığın anlar,

Benim seyrânım,

Ya bir de sönersen..?', 'Seninle olmak zor, Sensiz olmak daha da zor. Karanlıkları yırtarcasına, Doğarsın güneş gibi ruhuma. Avutur beni geliş-gidişlerin, Ya bir de ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korku-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dûn''um... (4''lük) ''Torun''uma...''', 'd-n-um-4-luk-torun-uma-atakan-kartaltepe-x6f7q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Odun'' dedin de bana...ben de yazdım ''Odun''um! ''

Ama...anlamadın be...anlamadın be...dûn''um...

Bir bilene sorsaydın! ..madem ki anlamadın...

Ben 24 ayâr''ım! ..sensin ODUN! ..Odunum! ..

NOT: Bu şiirin altına rumuz ''müzikbenimhytm'' tarafından

           ''24 ayar kamçı'' şeklinde yazılmış olan görüş her-

           halde amirlerinden ''SİL'' emri geldi ki sonradan si-

           linmiştir...Üstelik de hiç yazılmamış gibi bir tutumla...

           Mesajlar Antoloji üzerinden gönderilmekte ve de 

           hotmail''de durmaktadır...Bu o rumuza cevaptır...

           Hem ''24 ayar kamçı'' de! ..hem emir alınca kaç...

           Seni almış ki içine...almış ki öyle bir kıskaç

           Bilirim sizi...sizi! sizi! ..siz salîp görünen haç! ..

           Madem kaçtın...al! bu da sana 24 ayar kırbaç!', '''Odun'' dedin de bana...ben de yazdım ''Odun''um! '' Ama...anlamadın be...anlamadın be...dûn''um... Bir bilene sorsaydın! ..madem ki anlamadın......', ARRAY['Türk Edebiyatı','Şiir','Atakan Kartaltepe']::text[], 8.5, '{"poet":"Atakan Kartaltepe","poet_slug":"atakan-kartaltepe","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dun-um-4-luk-torun-uma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlenirsin', 'ozlenirsin-ahmet-ormanci-icsod', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte bak kapım çalıyor yine,

Ama biliyorum bu sen değilsin.

Az sonra telefonum da çalar, biliyorum.

Sanki arayan sen misin? 

Kalabalıklar içinde,

Yalnızlığın ne olduğunu bilemezsin.

Bilemezsin sen hiç özlemeyi,

Sen ancak özlenirsin.', 'İşte bak kapım çalıyor yine, Ama biliyorum bu sen değilsin. Az sonra telefonum da çalar, biliyorum. Sanki arayan sen misin?  Kalabalıklar iç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlenirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hançer', 'hancer-muhammet-faruk-koca-2sts2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerime hayat verdin, 

Sonra uçup gittin, 

Yüreğime bir hançer salıp gittin, 

Gözlerim kan çanağı gibi, 

Geri dön demek çok geç artık, 

Ben bir yolcu, 

Sen hancı misali, 

Aşk kadehlerinden sor beni, 

Duvarlar dile gelmiş konuşacak ellerim, 

Ellerim semada duaya duracak, 

Ellindeki hançeri sal kalbime. 

10.05.2000', 'Gözlerime hayat verdin,  Sonra uçup gittin,  Yüreğime bir hançer salıp gittin,  Gözlerim kan çanağı gibi,  Geri dön demek çok geç artık,  Be...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hancer-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Olan Çocukluğum1 (Çocuklar İçin)', 'kus-olan-cocuklugum1-cocuklar-i-cin-ahmet-ormanci-w2tox', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kuştu çocukluğum

Yavru bir kuş, yerlerde gezinen.

Küçük yaramaz çocuklar yakalamadan,

Takılmadan çalılara, dikenlere,

Uçmayı öğrendi sonunda.

Ve bir kanat çırptı,

Kondu bahçemizdeki nar ağacına.

Bir süre seyretti etrafı sessiz sessiz.

Sonra uçtu gitti gökyüzüne,

Bakakaldım ardından, kaybettiklerimin.

Ne tuzaklar kurdum yakalamak için,

Ne yemler döktüm bahçemize,

Ama nafile,

Ne yakalayabildim onu,

Ne de bir daha görebildim.

Evet biliyorum,

Kuş oldu benim çocukluğum,

Uçtu gitti ellerimden,

Uçtu gitti benim çocukluğum.', 'Bir kuştu çocukluğum Yavru bir kuş, yerlerde gezinen. Küçük yaramaz çocuklar yakalamadan, Takılmadan çalılara, dikenlere, Uçmayı öğrendi son...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kus-olan-cocuklugum1-cocuklar-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretlik Olmaz', 'hasretlik-olmaz-hikmet-uzun-y040b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerini aşk bürüyen,

Sinesine dert yürüyen,

Ayrıyız zannı çürüyen,

Aşıka hasretlik olmaz.', 'Gözlerini aşk bürüyen, Sinesine dert yürüyen, Ayrıyız zannı çürüyen, Aşıka hasretlik olmaz....', ARRAY['Türk Edebiyatı','Şiir','Hikmet Uzun']::text[], 8.5, '{"poet":"Hikmet Uzun","poet_slug":"hikmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hasretlik-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlattın Bu Gece....', 'aglattin-bu-gece-omer-golge-9wm2c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak işte ağlattın beni bu gece

Bu kadar seneden sonra ilk defa

İki damla zehir,ateş parçası

Akkor gibi düştü yorgun gönlüme

Oysa ne çetin kavgalar yaşamıştım

Kanlı savaşlardı,hep ölümüne

Kurşun sağnağında top ateşinde

Azrail şaşmıştı gülümsememe.....

Dudağından çıkan iki kelime

Gecenin içinde yıldırım oldu

''O aradı'' dediğin zaman inan

Serseri bir kurşun kalbimden vurdu

Sarsıldı.. yıkılmaz sandığım beden

Müebbet mahkumları gibi aniden

Ruhumdu adeta bedenden firar eden

Aklım karıştırdı bildiği yolu

Bir kör gibi kalakaldım şuursuz

Durabilmek için ayak üstünde

Güllere tutundum dikenle dolu

Birde bütün bunlar yetmezmiş gibi..

Gelde yüzleş dedin tatlı sesinle...

Depremlerin yıkamadığı seni..

Tek hamlede deviren hayaletinle.

Şimdi bir şey anlatayımda sana

Belki tuz basılır ağır yarama

Savaş meydanında mertlik Ali işidir

Bu işin sırrını ondan öğrendim

Kırılıp paramparça olmak varsada

Hayatım boyunca hiç eğilmedim

Bu açık senettir sana verilmiş

Gönlüme başka umut ekmeyeceğim

Hiç hamle bekleme benden haince

Kazanana kadar bekleyeceğim', 'Bak işte ağlattın beni bu gece Bu kadar seneden sonra ilk defa İki damla zehir,ateş parçası Akkor gibi düştü yorgun gönlüme Oysa ne çetin ka...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aglattin-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azize', 'azize-muhammet-faruk-koca-imf3t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevda gibidir azize, 

Aşkı anlatır sevdayı anlatır lakin 

Kuşların ötüşünü yuvalarını terk edişini anlatmaz, 

Yaban bir göle kanan turnaları hiç anlatmaz, 

Ama kendisi bir kuş gibi uçup gitti uzaklara, 

Yansızlıkla boğulan nefesin yalnız azize için almakta, 

Anlatmaktayım insanlar ne kadar aciz olduklarını, 

Ama azize bunu anlamamakta. 

25.07.2000', 'Bir sevda gibidir azize,  Aşkı anlatır sevdayı anlatır lakin  Kuşların ötüşünü yuvalarını terk edişini anlatmaz,  Yaban bir göle kanan turna...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/azize-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-umut....', 'umut-erhan-demir-eojpb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeni doğmuş bir bebek 

Sevinçle bakar ya dünyaya

Güven veren annenin 

O tatlı ve şevkatli bakışlarında

Umut vardır yalnızca...

Umut 

Bir çiçek tanesidir saksıda.

Otobüs bekleyen bir ninenin

Sımsıcak bir gülümseyişidir durakta.

Mutluluk denizine açılan bir gemidir gönülde.

Ve ulaşmak istediğimiz yolun,

Tek aracıdır umut.

Gün batımında, karanlık bir odada,

Bir aşığın serapsı gözleri,

Işığıyla aydınlatır ya geceyi,

Hüzün dolu yalnızlıkların karamsarlığında; 

Sevda şiirleridir umut.

Umut, Hatice ablanın kafeteryasında,

Dostlarla içilen demli bir çay tadında

Sevgi yüklü bir aşkın ilk molasıdır dolunayda,

Ve barışa giden bir yolcunun,

En son durağıdır umut.

Seher vaktinde, ezan sesleriyle uyandığımızda,

Acıkan kuşları,

Kırık ekmek taneleriyle doyurdugumuz zaman,

Kalplerimizin ''''sevgi,sevgi'''' diye atış seslerinde; 

Sevinci ve mutluluğu paylaşmaktır umut

Sabahın taze kokularını hissettiğimiz an yüregimizde,

Güneşin ilk ışıkları gözlerimize vurduğunda

Ve derin bir nefes aldığımızda o an,

Sanki, dünyanın bütün yükü sırtımızdan inivermişcesine; 

Yaşamın bizlere verdiği en büyük armağandır umut. 

UMUT, budur işte! ...

ŞİR VE YORUM: ERHAN DEMİR

NOT: Ses dosyasını indirip dinlemek için, alttaki  ''Download'' link ''ini tıklayınız

Yaklaşık indirme süresi 1 - 5  Dakikadır 

Not: Sesli mp3 şiirlerimi kaliteli kulaklıklarla dinlemenizi tavsiye diyorum...

Paylaşımlarınız için teşekkürler.', 'Yeni doğmuş bir bebek  Sevinçle bakar ya dünyaya Güven veren annenin  O tatlı ve şevkatli bakışlarında Umut vardır yalnızca... Umut  Bir çiç...', ARRAY['Türk Edebiyatı','Şiir','Erhan Demir']::text[], 8.5, '{"poet":"Erhan Demir","poet_slug":"erhan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/9829-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekten Ayrıldık mı?', 'gercekten-ayrildik-mi-tercan-keskin-dbeea', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılalım sözünü kulaklarım duydu da

İnan aklım almıyor gerçekten ayrıldık mı? 

Verdiğin ümitlerle gönül aşka uydu da

Sensiz iflah olmuyor gerçekten ayrıldık mı? 

Dünya benim olmuştu bir küçücük busenle

Kan ağlıyordu gönlüm kederinle tasanla

Bu sevdanın bedeli idam olsa yasanla

Elden ödül bilmiyor gerçekten ayrıldık mı? 

Severken gidiyorsun bakışlarından belli

Sensiz gözümden yaşlar akar yağmurlu selli

Hicranınla yıkılmış yüreğime teselli

Versen bile almıyor gerçekten ayrıldık mı? 

Sende çıkar yol buldum sevda bilmecesinden

Senle sabaha çıktım ızdırap gecesinden

Ne Nur ne Ayşe ne de Fatma’nın bahçesinden

Mutluluk derilmiyor gerçekten ayrıldık mı? 

Beni sana bağlayan değildi bir özellik

Sendeydi deli gönlün isteği her özellik

Tek sana özgü olan mütevazi güzellik

Hesaba vurulmuyor gerçekten ayrıldık mı? 

Yaktığın parmağımı ısırdığın kolumu

Unutamam eşkıya kesmiş olsa yolumu

Azrail şakağıma dayasa da ölümü

Can sensiz verilmiyor gerçekten ayrıldık mı? 

Yüreğimin yıllarca düşlediği o bakış

Sende kor alevlere eşlediği o yakış

Gönlüme gözlerinin işlediği o nakış

Bu candan ayrılmıyor gerçekten ayrıldık mı? 

Saçlarını saklamak boynumun borcu olsun

Öpüp öpüp koklamak boynumun borcu olsun

Yollarını beklemek boynumun borcu olsun

Sensiz yüzüm gülmüyor gerçekten ayrıldık mı? 

Sil gözyaşını sana tebessüm yakışıyor

Gönül bahçemde hisler aklımla çakışıyor

Düşlerim paramparça yüreğim sıkışıyor

Gönül huzur bulmuyor gerçekten ayrıldık mı? 

Seni suçlamam yavrum sitem edemem sana

Sevgimi düşünmeden kıymış olsan da bana 

Sen yoksan rüyalarım hayra yormak bir yana 

Şerre de yorulmuyor gerçekten ayrıldık mı? 

Beni sensiz bırakma ocağında azap ver

Kes elimi kolumu yıllarca ızdırap ver

Sevdin mi sevmedin mi son kez olsun cevap ver

Hissetmekle olmuyor gerçekten ayrıldık mı? 

Yaktın sitem okuyla ateş ettiğin yeri

Sen olmasan ömrümün sanma kalır değeri

Sapık herif desen de bu divane serseri

Tek sana darılmıyor gerçekten ayrıldık mı? 

Mutlu olacak mısın ben ağlarken düşünde? 

Koyacak mısın beni yalnızlık ateşinde? 

Asırlarca kaçsan da gönül senin peşinde

Koşmaktan yorulmuyor gerçekten ayrıldık mı? 

Son defa görmek için sakalımı da kestim

Sen de gidiyorsun ya sevdayı dama astım

Gönül deryam köpürdü lodos misali estim

Fırtınam durulmuyor gerçekten ayrıldık mı? 

Demek siyah gözlerin mezarım olacakmış

O zoraki sözlerin mezarım olacakmış

Baş koymadan dizlerin mezarım olacakmış

Başka çarem kalmıyor gerçekten ayrıldık mı?', 'Ayrılalım sözünü kulaklarım duydu da İnan aklım almıyor gerçekten ayrıldık mı?  Verdiğin ümitlerle gönül aşka uydu da Sensiz iflah olmuyor g...', ARRAY['Türk Edebiyatı','Şiir','Tercan Keskin']::text[], 8.5, '{"poet":"Tercan Keskin","poet_slug":"tercan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/gercekten-ayrildik-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denge', 'denge-bulent-kiraz-i3fny', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırılmaya görsün

Yüreğimde ışık

Bedenim nereye çarpar

Gözlerim nereye? ..

Şizofrenik algılar içinde

Yalnız kalmış

Bir çocuğun paniğiyle

Patilerini çamura bulayarak

Yıkıntılar dünyasında

Kaybolan sevdalılar,

Okunan kitapların kahramanı oldular

Ve hayatın tekrarı.

Hangi aşık

Hangi hücre patladığında

Düşeceği yeri kendi seçer? ..

Patlamaya görsün

Yüreğimde şah damar

Bedenim nereye çarpar

Düşlerim nereye? ..

Hala panikle

Düşeceği yeri hesaplayan

Kar taneleri

Tane tane döküldüler,

Tane tane

Hayallerimdeki evin 

Çardağından

Ve paspası oldular tarihin...

 

                                                     Bülent KİRAZ

                                                     19.04.2001

                                                     Antalya', 'Kırılmaya görsün Yüreğimde ışık Bedenim nereye çarpar Gözlerim nereye? .. Şizofrenik algılar içinde Yalnız kalmış Bir çocuğun paniğiyle Pati...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kiraz']::text[], 8.5, '{"poet":"Bülent Kiraz","poet_slug":"bulent-kiraz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/denge-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyceğiz Gölünde', 'koycegiz-golunde-cengiz-manga-w3wro', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O günün batımında martılar,

Birbirine küsmüş dalgalarda,

Benimle alay edercesine,

Köşe kapmaca oynuyorlardı...

Köyceğiz gölünde,

Seni aradım...Mevsim bahardı...

Sen yine yoktun...Yapayalnızdım...

Sevgi bu muydu,sevda bu muydu...

Bırakıp gitmek,bize yakışmaz...

Sen bunu hiç bilmedin ama hiç...

Trakya''yı ege''ye getirdim,

Yeşil gözlerini köyceğiz''e...

Siyah saçlarını ortaca''ya...

İnadın dalyanda''ki ağlarda..

İzlerin kral mezarlarında...

Allah kahretsin,sen yine yoksun.

Köyceğiz sokakları yine boş.

Ben yine sensiz yapayalnızım.

Dönen plakta ''Vedâ busesi''

Kördüğümle yumak yaptın beni,

Sevinçten, kına yak ellerine.....

                    Mayıs-1967    Köyceğiz/MUĞLA', 'O günün batımında martılar, Birbirine küsmüş dalgalarda, Benimle alay edercesine, Köşe kapmaca oynuyorlardı... Köyceğiz gölünde, Seni aradım...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Manga']::text[], 8.5, '{"poet":"Cengiz Manga","poet_slug":"cengiz-manga","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/koycegiz-golunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işığım ol', 'isigim-ol-sacide-yaylaz-zmmnd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tıpkı bir güneş gibi

Sevginle,dostluğunla

Aydınlat gecemi.

Işığım ol bitanem,

Karanlıkta bırakma beni,

Yiter kaybolurum,

Gündüzümde gece olur,

Bulamam yolumu

Işığım ol bitanem

Bırakma beni....', 'Tıpkı bir güneş gibi Sevginle,dostluğunla Aydınlat gecemi. Işığım ol bitanem, Karanlıkta bırakma beni, Yiter kaybolurum, Gündüzümde gece olu...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/isigim-ol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamparalık Destanı', 'zamparalik-destani-tercan-keskin-8327o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canım cicim ayları yok benim mevsimimde

İcraat da olmalı sözle yetinmiyorum

Aşk narına yanmaktır arzum da hevesim de

Yakan ateş olacak közle yetinmiyorum

Ne düşünsem söylerim tarzım değil kinaye 

Başka bir tat aramam zevk olmalı tek gaye

Kız tavlama kitabı dersi falan hikaye

Teoriyle kitapla tezle yetinmiyorum

Utanmak nedir bilmem üç beş astar yüzlüyüm

Alenidir her işim epey açık sözlüyüm

Zamparalık babında katıyım aç gözlüyüm 

Tavuğu kenara koy kazla yetinmiyorum

Bazen birkaç güzel söz bazen dua alarak

Aşk fakiri gönlümü cennetlere salarak

Yapıyorum bu işi kutsal görev bilerek

Yolum iniş olacak düzle yetinmiyorum

Birinin gözü varsa onda sıram olacak

Ne evetçi ne asi birazcık ram olacak

Güzelliği endamı her yeri tam olacak

Keman gibi kaş mühür gözle yetinmiyorum

Değeri eksilir mi koklamakla altının

Kıymet bulur benimle ey güzel yufka tenin

Benim olması gerek üstünün ve altının

Yatacak yumuşak bir dizle yetinmiyorum

Oturduğu mevkide hayli namlı olmalı

Gül cemalinden yana epey zamlı olmalı

Oturup kalkışıyla ihtişamlı olmalı

Kalbi iyi olsa da gizle yetinmiyorum

Seçeceğim hatunu güzelce bir süzerim

İki bakıştan sonra iş çıkar mı sezerim

Çorabı çıkarmadan düğmeleri çözerim

Malumdur sonrası bu hızla yetinmiyorum

Kadın kurnazsa aman korkacaksın vallahi

Yakayı kaptırırsan ters giyersin külahı

Ya tank ya da havandır bu mesleğin silahı

Tetikle arpacıkla gezle yetinmiyorum

Yapacaksan bu işi hilafın olmayacak

Yazdığın şiirlerde ithafın olmayacak

Evlilik mi tövbe de zifafın olmayacak

Birine bağlanamam azla yetinmiyorum

Aşktan yana fazlaca alıyorum yükümü

Mevsim bazen ilkbahar bazen yaprak dökümü

Zamparalık tahtından sökemezler kökümü

Üçü beşi geç on beş kızla yetinmiyorum', 'Canım cicim ayları yok benim mevsimimde İcraat da olmalı sözle yetinmiyorum Aşk narına yanmaktır arzum da hevesim de Yakan ateş olacak közle...', ARRAY['Türk Edebiyatı','Şiir','Tercan Keskin']::text[], 8.5, '{"poet":"Tercan Keskin","poet_slug":"tercan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/zamparalik-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-sair-pinarkirci-m7yze', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yagmur çiseliyordu yine sicim gibi akıyordu gözyaşları

bir sonbahar akşamı ve yine hüzün denizi

hüzne dönmüştü herdem baharlar

esrik gecen hayatımın sonbaharında

ömre sıgmaz bedeller

gecenin kızıllıgında karanlık geceler

sisli bulutlu bir hava da yürüdüm 

ışıksız yollarda ıssız sokaklarda

yüreginden gelen sesleri dinledim sakince

hüznün son demi yasanıyor şimdi', 'yagmur çiseliyordu yine sicim gibi akıyordu gözyaşları bir sonbahar akşamı ve yine hüzün denizi hüzne dönmüştü herdem baharlar esrik gecen h...', ARRAY['Türk Edebiyatı','Şiir','Şair Pinarkırcı']::text[], 8.5, '{"poet":"Şair Pinarkırcı","poet_slug":"sair-pinarkirci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sonbahar-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş''i Ateşlemek', 'gunes-i-ateslemek-h-hikmet-esen-n1q6f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşlerim

Dolaşırken sokaklarda 

O mahur şarkılarla 

Saatleri kovalıyor 

Yüreğimde yelkovan.

Çocukken korkudan

Islık çaldıran

O simsiyah akşamlar

Ürkütmüyor artık

Kör karanlıklara bulansa da

Eskisi kadar.



Zulamda

Sabahın maviliği,

Dalga dalga

Deniz yeşili

Başımdaki

Kavak yelleri.



Dilimde Ege türküleri

Zeybek kesilir

Her diz vuruşunda

Dellenir yüreğim

Sığmaz kafesine

Taşar Deniz''lerim.



Zor değil

Karanlık geceleri

Kibrit yakarak geçmek.

Ve görsün diyerek

Cümle Alem

Güneşi ateşlemek..



Son Düzenleme Tarihi..07/07/2007

.............H Hikmet Esen.................', 'Düşlerim Dolaşırken sokaklarda  O mahur şarkılarla  Saatleri kovalıyor  Yüreğimde yelkovan. Çocukken korkudan Islık çaldıran O simsiyah akşa...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gunes-i-ateslemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyamdaki Kadın', 'ruyamdaki-kadin-bedri-demirdas-yv1fv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kadın görürüm düşümde 

Yağmuru bekleyen toprak gibi

Baharı bekleyen çiçek gibi

Bekler beni her gece

Bir kadın görürüm düşümde

Yaklaşır bana yavaş yavaş

Soğuk kış gecelerinde

Isıtır yatağımı beni

Bir kadın görürüm düşümde

Uzanmış yatağa çırılçıplak

Bir şeyler giyiyor üzerine 

Beni her görüşünde

Bir kadın görürüm düşümde

Bütün düşlerde güzel

Mavi denizlerde yüzer

Bedrican''ı arar gezer', 'Bir kadın görürüm düşümde  Yağmuru bekleyen toprak gibi Baharı bekleyen çiçek gibi Bekler beni her gece Bir kadın görürüm düşümde Yaklaşır b...', ARRAY['Türk Edebiyatı','Şiir','Bedri Demirdaş']::text[], 8.5, '{"poet":"Bedri Demirdaş","poet_slug":"bedri-demirdas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruyamdaki-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mustafa Kemâl İçin', 'mustafa-kem-l-i-cin-alper-kuruk-vh2lr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir an irkildi şehit

Ve sonra toparladı kendini sevinçle 

Müjdeler dağıttı ölümsüz ecdadına.

O an tüm ihtiramındaydı yiğit

Ayakta dimdik

Başı eğik 

Gözleri bakıyordu kadere hınçla.

Toplandık bu yanda biz fâniler

Ötedeyse ölümsüzler,

Üzüntüyle sevinç ikiz kardeşti

Biri bize düştü 

Diğeri onların kısmetine.

Biz ağladık,onlar güldü,

Bizce hâlâ yaşar Mustafa Kemâl

Onlarcaysa Tanrı emri bu:öldü...

Biz Ata''yı bize çekeriz

Onlar kendilerine,

Biz yine çekeceğiz

Ölene dek çekeceğiz

Gerçeği görmek istemez bir türlü gözlerimiz.

Ölüm,gece gibi karanlık

Aydın güncesine gerçek.

Nasip olsaydı dilerim herkese

Mustafa Kemâl gibi doğmak,

Mustafa Kemâl''cesine yaşamak ve yaşatmak 

Mustafa Kemâl gibi ölmek...', 'Bir an irkildi şehit Ve sonra toparladı kendini sevinçle  Müjdeler dağıttı ölümsüz ecdadına. O an tüm ihtiramındaydı yiğit Ayakta dimdik Baş...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mustafa-kemal-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku!', 'korku-bedri-demirdas-qn5kj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yuva kuruyor beyninin tam ortasında

Sarıveriyor düşünceni mantığını biranda

Kurtuluş yoktur diyorsamda sen inanma

Güzel günlere inat göster biraz gayret

Gelip bana korkuyu dehşeti anlatma

Hiç unutmadım ki yenik düştüğüm zamanları

Yaptığın her yanlışta ecel terleri döktürüyor sana

Bütün doğrulara inat göster biraz gayret

Korku neydi ben hiç bilmezdim

Taki seni gördüğüm güne kadar

Hep kaybetme korkusu hep ayrılık hep hüzün

Bütün sevenlere inat göster biraz gayret

Bak yıllar geçiyor çar çabuk

Dün gibi bügün gibi seviyor yürekler

Kurtuluş yoktur diyorsamda sen inanma

Güzel günlere inat göster biraz gayret', 'Yuva kuruyor beyninin tam ortasında Sarıveriyor düşünceni mantığını biranda Kurtuluş yoktur diyorsamda sen inanma Güzel günlere inat göster ...', ARRAY['Türk Edebiyatı','Şiir','Bedri Demirdaş']::text[], 8.5, '{"poet":"Bedri Demirdaş","poet_slug":"bedri-demirdas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/korku-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göster Nurlu Yüzünü', 'goster-nurlu-yuzunu-i-brahim-halil-demir-g74sz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rahmetin olmazsa halimiz ne olur daracık kabirde

Göz gözü görmez o korkulu karanlık yerde

Envai türlü mahlukun rızkı var bedenimizde

Ağlamamız lazım şimdiden acınacak halimize

İnsanlar zevk-ü sefa içinde düşünmüyorlar sonlarını

Dünya menfaati için hemen koparıyorlar bağlarını

Vermiyorlar mallarının farz olan zekatlarını

Hep israf ediyorlar değerlendirmiyorlar zamanlarını

Tapmışlar fani dünyanın görünmeyen gerçek yüzüne

Çok  güveniyorlar hiç bitmeyecek gibi görünen ömürlerine

Şükrederdiler hemen başlarını kaldırıp baksaydılar gökyüzüne

Günlerini heder etmezlerdi  çok da inanırlardı Resulullah’ın sözüne

Göster nurlu yüzünü seninle ziyalansınlar 

Cehennemlik iken  belki de cennetlik olsunlar

Görmezlerse Habibullah’ın yüzünü tutmazlarsa mübarek elini

Söylesene bu fani dünyada  nasıl gülsün, nasıl mutlu olsunlar

Güneş ol doğ gönüllerine, aydınlat karanlık dünyalarını

Öyle bir sevda çektir ki anlatsınlar birbirlerine sevdalarını

Yavan ekmek gibi bile değildir sevdansız bu hayat

Güllendir neşelendir perişan olan dertli gönül bağlarını

06.02.2005', 'Rahmetin olmazsa halimiz ne olur daracık kabirde Göz gözü görmez o korkulu karanlık yerde Envai türlü mahlukun rızkı var bedenimizde Ağlamam...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/goster-nurlu-yuzunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Dediğin Yar Kokmalı', 'gul-dedigin-yar-kokmali-i-brahim-halil-demir-ydoq7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağ dediğin, doruğunda kar bulundurmalı!

Yar dediğin, daim sevdiğinin yanında olmalı!

Yürek dediğin, hep onun için çarpmalı!

Sevda dediğin, köşe bucak herkes onu anlatmalı!

Gül dediğin, ölesiye sevdiğin yar kokmalı!

Vuslat dediğin, Kerem gibi Aslı için yanmalı!

Şevk dediğin, Ferhat gibi dağı delip su getirmeli!

Mertlik dediğin, Tahir gibi Zühre için başını vermeli!

Sevgi dediğin, husumetleri dostluğa dönüştürmeli!

Göz dediğin, sadece onu görmeli onu gözetlemeli!

Cesaret dediğin, Hz Ali gibi ölüm yatağına yatmalı!

Sadakat dediğin  Hz Ebubekir’i andırmalı!

Dost dediğin, sevdiği için her fedakarlığı yapmalı!

Maşuk dediğin, çok uzaklarda da olsa gelmeli.

Bülbül dediğin, gül için usanmadan ötmeli.

Toprak dediğin, her yarin ektiğini filizlendirmeli.

Kitap dediğin, seni anlatmalı kalem ise seni yazmalı!

Dil dediğin, her mekanda herkese seni konuşmalı! 

Ay dediğin, gökyüzünde seni yansıtmalı!

Asil kan dediğin, şah damarında seni akmalı!

Çoban dediğin, yaz kış hep bu aşkı gütmeli!

Aşk dediğin, destanlaşıp dilden dile dolaşmalı!

Menzil dediğin, ulaşmak için herkesi özendirmeli!

Irmak dediğin, Ağustos'' ta bile buz gibi bana seni akmalı!

Rüzgar dediğin, seni esmeli kokunu bana solutmalı!

Sıcaklık dediğin, yüreklerde aşkını fokurtmalı!

Sabır dediğin, Hz Eyyup gibi "ya sabır" çekmeli!

Şükür dediğin, sabahlara dek ibadet ettirmeli!

Özlem dediğin, şiirler bestelemeli türküler yakmalı!

Sevinç dediğin, sevene sevinç gözyaşları döktürmeli!

Tabip dediğin, sevenlerin yaralarını sarmalı!

Ölüm dediğin, herkese canı gönülden fatiha okutmalı!

25/01/2005', 'Dağ dediğin, doruğunda kar bulundurmalı! Yar dediğin, daim sevdiğinin yanında olmalı! Yürek dediğin, hep onun için çarpmalı! Sevda dediğin, ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gul-dedigin-yar-kokmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sacide-yaylaz-buaqp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir çırpınış oldun,

Umutsuzluğuma umut,

Sessiz sevdama giz,

Uğurum oldun benim.

Feri oldun gözlerimin.

Resmin duruyor karşımda,

Ebediyyen diyor gözlerin,

Söz veriyor sanki bana,

Sevdamda,dostluğumda ebediyyen,

Aşkım bitanem canımın içi,

Mazi olma hep yanımda ol  sen.......', 'Yüreğimde bir çırpınış oldun, Umutsuzluğuma umut, Sessiz sevdama giz, Uğurum oldun benim. Feri oldun gözlerimin. Resmin duruyor karşımda, Eb...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-660-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kalan Şiir', 'yarim-kalan-siir-muhammet-faruk-koca-emizz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlatamadım gülüm anlatamadım, 

Yarım kaldı şiir, 

Nerde kim bilir ne halde yürek? 

Sorgusuzca vurup gitti, 

Hani nerde şimdi sisli lamba? 

Yarım kalan şarkılar hani nerede? 

Sen neredesin? 

Sensiz bir yolculuk başlıyor şimdilerde, 

Gemim sessiz sessiz yol alıyor sensizliğe, 

Sen yarım kalan şiir, 

Bir yarım hep yarım sende, 

Ey yarım kalan şiir, 

Sende gel bir gün benim olduğum yerlere. 

19.09.2005', 'Anlatamadım gülüm anlatamadım,  Yarım kaldı şiir,  Nerde kim bilir ne halde yürek?  Sorgusuzca vurup gitti,  Hani nerde şimdi sisli lamba?  ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yarim-kalan-siir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzzam Şarkı–2', 'huzzam-sarki-2-muhammet-faruk-koca-lktx8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ruhuma işler ansızın bir müzik, 

İçim sen dolar her kelimede, 

Uzakları anlatır keman ilintisi, 

Ne kadar uzak olduğunu, 

Hep düşlerim senle gezinir, 

Sen dolusundur her adım atışında, 

Şimdi suskun yüreğim, 

Neredesin kim bilir ne halde, 

Sensizliğe küskünüm be güzelim, 

İçimden her dakika kopan bir fırtına, 

Gözlerim kapıda, 

Bir sese kilitlenmiş kulaklarım, 

Resmin duvarda yalnız ağlamaklı, 

Gece kararır ürkek bakışlım, 

Sen gittin İstanbul suskun şimdilerde, 

Denizim dalgalı be güzelim, 

İçimi koparıp ta astım resminin yanına, 

Göz yaşlarım pınar oldu be güzelim, 

Sen gideli her şey deyişti, 

Üsküdar yalnız ağlamaklı, 

Parklar sana kuskun be güzelim, 

Ben yani sevgili, 

İçimde kara bulutlar çarpar her dakika, 

Yalnız sokak lambasının altında, 

Bir yabancı İstanbul artık bana, 

Kuskunum şimdilerde hayata sevgili, 

Ey sevgili, 

Fedakar bir aşkla başlayan, 

Ben bahardım sen girdin kanıma, 

Ben olmuşun sokuldun yanıma, 

Açmış çiçeklerimi kuruttun be güzelim, 

Baharken döndürdün beni hazana, 

Baharken neden çevirdin sonbahara, 

Yapraklarıma vuruyor şimdi bir asi rüzgar, 

Sevgili ey sevgili, 

Bir hüzzam şarkı gibi dökülüyor yapraklarım neden? 

Oysa içim hala sen diye ağlar, 

Her kelimede sen har adımla senle dolar taşar, 

Oysa şimdilerde yoksun sevgili, 

Oysa bütün yolarım sana çıkar be güzelim. 

07.10.2005', 'Ruhuma işler ansızın bir müzik,  İçim sen dolar her kelimede,  Uzakları anlatır keman ilintisi,  Ne kadar uzak olduğunu,  Hep düşlerim senle...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/huzzam-sarki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzzam Şarkı–1', 'huzzam-sarki-1-muhammet-faruk-koca-g5wqa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim yorgunluğa yenik düştü sevgili, 

Sen gittin gideli şarkılar suskun, 

Keman inlemiyor eskisi gibi, 

İçimden koparıp ta çaldın beni benden, 

Şimdi kalp suskun göz sensizliğe kör, 

Dün sizin oradan geçti gönül, 

Pencerene baktım kırılmış sokak lambasından, 

Küskünlüğüm geçti içimden be güzelim, 

Sen gittin gideli, 

Sizin oradan geçti gönül, 

İçim koptu sokak başında, 

Kalbimi çıkardım bir solukta, 

Astım sokak lambasına, 

Penceren kapalı perden çekikti be güzelim, 

Hiç dönmeyeceksin bilirim ben, 

İçimde bir parçaydın neden aldın benden, 

Hiç bir şey kalmadı be güzelim, 

Suskundur gece fırtına saklar içinde, 

Kararır gece sokak lambası sönük, 

Yanmaz oldu odanın lambası be güzelim, 

İçimde yanıyorum gel desem, 

Sensizlik zindana döndü dön desem, 

Döner misin be güzelim. 

27.09.2005', 'Gözlerim yorgunluğa yenik düştü sevgili,  Sen gittin gideli şarkılar suskun,  Keman inlemiyor eskisi gibi,  İçimden koparıp ta çaldın beni b...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/huzzam-sarki-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anacığım', 'anacigim-i-brahim-halil-demir-ywfrs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzat ellerini doyasıya öpeyim

Gerekirse kulun kölen olayım

Yeter ki dualarını esirgeme benden

Emret uğrunda seve-seve öleyim

Anacığım

Bu hayatın tadı tuzu yok sensiz

Nasıl olurum söylesene gamsız kedersiz

Ben yanmazsam kim yansın hasretinle 

Gezerim gurbet ellerinde ağlarım sessiz-sessiz

Anacığım

Sen benim ahirette cennetimsin

Ben senin külfetin sen ise benim nimetimsin

Veysel Karani gibi de olsam hakkını ödeyemem

Sen benim iki cihanda da yüreğimin ateşisin

Anacığım

 Bilemedim gerektiği gibi kıymetini

 Hep sen çektin hayatımın sıkıntı ve zahmetini

Allah seni nuruyla nurlandırıracaktır

Zira rüyamda verdiler bunun müjdesini

Anacığım

Tatlı uykularını bozdun ninni söyledin bana

Hep şefkatle merhametle davrandın bana

Yaptıklarının karşılığını hiç ödeyemem

Şayet hakkını helal etmezsen bana

16-01-2005', 'Uzat ellerini doyasıya öpeyim Gerekirse kulun kölen olayım Yeter ki dualarını esirgeme benden Emret uğrunda seve-seve öleyim Anacığım Bu hay...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anacigim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen-lll', 'sen-lll-okan-nar-xgue1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zemheride yudumladım sevgiyi,hasreti..! 

Bakarken senin gözlerine,

Kor ateşleri avuçladım hep yanında..! 

Eridi bedenim,ruhum yanındayken.

Ama hiç belli etmedim her ayrılışında..! 

Fırtınalar,tufanlar yaşadım,

Her defasında  aşk adına..! 

Sen hazan sonrasında gelen baharsın..

Sana boynum kıldan ince..!', 'Zemheride yudumladım sevgiyi,hasreti..!  Bakarken senin gözlerine, Kor ateşleri avuçladım hep yanında..!  Eridi bedenim,ruhum yanındayken. A...', ARRAY['Türk Edebiyatı','Şiir','Okan Nar']::text[], 8.5, '{"poet":"Okan Nar","poet_slug":"okan-nar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-lll-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlık Bir Düşüncenin Şerhidir', 'anlik-bir-dusuncenin-serhidir-cumhur-bulut-uztw7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gece yarısı; 

Yokluğunun duvarlara çizilmiş resmi

Vakit, zamanın seni

Mekanın seni/ bulduğu an...

Ürpertiler ard arda

Keskin keskin tekrarlanan avuntu cümlesi

Bütün saatler/ damla damla

Yok olan kum saati

Kent: asılmaya giden insanlar.

Şehir: yeniden doğan insanlar.

Mücadelesinin resmi

Bırakma ne olur derdimi,

Gülü bırakma,

Ateşi bırakma/ Yandığımın resmi! 

Bu karanlık gecede

Varlıktan üryan biri var; 

Senin olan her yerde

Sen olan her yerde

Nefes dar/ hayat har

Bu taş medresede biri var

Davran ey çizdiğim şeklin aynası

Seni düşünürken

Hep böyle ürperiyorum/ titriyorum

Korkuyorum

Her gece yarısı

                                    05.08.2000', 'Her gece yarısı;  Yokluğunun duvarlara çizilmiş resmi Vakit, zamanın seni Mekanın seni/ bulduğu an... Ürpertiler ard arda Keskin keskin tekr...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Bulut']::text[], 8.5, '{"poet":"Cumhur Bulut","poet_slug":"cumhur-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/anlik-bir-dusuncenin-serhidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki Bu Yürek', 'bendeki-bu-yurek-i-brahim-halil-demir-e0zg7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bendeki aşkın sokakları yosunlu ve de ıslak

Bendeki bu yürek çok yufka ama o kadar da korkak

Böyle değildim aşkın şerbetini içmeden önce bardak-bardak

Yakalamasaydı keşke bu sevdan beni kıskıvrak

Bendeki bu aşk ateşi Ferhat gibi dağı deler

Deldikçe dağı ha bire ya sabır çeker

Anlatmak istesem de anlatılmaz bu kötü kader    

Kum etti aşkın beni kürek kürek ha bire eler

Bendeki bu özlem destanlar yazdırır

Sevmeyi bilmeyenlere bile sevmeyi öğretir

Kış mevsiminde yazı yaz mevsiminde de kışı yaşatır

Taş kalplilere de sevda bahçesinde fidan diktirir

Bendeki bu yürek sendeki gibi ne taş ne kaya 

Geçiyor günler su gibi bilmem kim saya

Nur cemalin benzerdi bir zamanlar dolunaya

Kalmadı yaşanacak gün dön de bir bak arkaya

Bendeki aşkın tarifi kolay kolay anlatılmaz

Yaşanır ancak yüreğin derinliklerinde yazılamaz

Dünya bir araya gelse beni bu sevdadan caydıramaz

Yaradan yazmıştır ondan başkası da bozamaz

Bendeki bu beden senden başkasına etmezdi eyvallah

Sadece sen varsın başkası da olmayacak inşallah

Hafsalım almıyor şaşırdım kaldım

Yardımına çok ihtiyaç  duydum ya Resulullah

 19.01.2005', 'Bendeki aşkın sokakları yosunlu ve de ıslak Bendeki bu yürek çok yufka ama o kadar da korkak Böyle değildim aşkın şerbetini içmeden önce bar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bendeki-bu-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Attila İlhan Öldü', 'attila-i-lhan-oldu-cumhur-bulut-ocjwh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ardından söyle müteveffanın

Sımsıcak şarkılar bildiğini

Sonbahardır nasıl olsa vakit/

Yaprak dökümü / Sen de git! 

Caridir her şartta ölümün daveti…

Neydi ki yaşadıklarımız

Bir sisin ardında kalacak tüm hatıralarımız

İstersen kal! 

Dayanabileceksen sonrasına

Ölüm: miad

Attila İlhan Öldü, heyhat! 

Ki kimler ağlasın? 

“Ölüme Mecburuz” be Usta

İnsan lal, kelime ve mısra yasta! 

Köprü ki taştan yapılır

Sebepsiz bir silleyle yıkılır

İster zelzele vursun

İster viran olsun

Burada bir hisar bıraktın

Varım, yıkılmam diye haykırır! 

                                                            11. 10. 2005', 'Ardından söyle müteveffanın Sımsıcak şarkılar bildiğini Sonbahardır nasıl olsa vakit/ Yaprak dökümü / Sen de git!  Caridir her şartta ölümün...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Bulut']::text[], 8.5, '{"poet":"Cumhur Bulut","poet_slug":"cumhur-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/attila-ilhan-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Vardın', 'sen-vardin-i-brahim-halil-demir-riajy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecelerin zifiri karanlığında,

Garibanların mutluluğunda, sen vardın!

Ulu dağların doruğunda,

Ummanların maviliğinde, sen vardın!

Karıncaların yuvalarındaki ahenginde,

Çöplükte açan papatyanın güzelliğinde, sen vardın!

Göçmen kuşların uçuşundaki düzende,

Yaratılan her şeyin mükemmelliğinde, sen vardın!

Yıldızların semayı süslemesinde,

Kar tanelerinin birbirine değ memesinde, sen vardın!

Yalçın kayalardan kaynayan suyun serinliğinde,

Annelerin çocuklarına olan sevgi ve merhametinde, sen vardın!

Bilinmeyenlerin bilinmesinde,

Kalplerden geçenlerin okunmasında, sen vardın!

Dilediğine hidayetin verilmesinde,

Vicdanların sızlanmasında sen vardın!

Bizlere verilen nimetlerin bereketinde,

Yumurtadan henüz çıkan civcivin yüzmesinde, sen vardın!

Hiç kimsenin hiç kimseye benzememesinde,

Kimsenin başkasının rızkını yiye memesinde, sen vardın!

Yüz binlerce canlının görevli olarak yaratılmasında,

Yapılan ibadetlerin neticesinde, sen vardın!

Taşlaşmış kalplerin yumuşamasında,

İçin için ağlayan gözlerden yaşların gelmesinde, sen vardın!

22/01/2005', 'Gecelerin zifiri karanlığında, Garibanların mutluluğunda, sen vardın! Ulu dağların doruğunda, Ummanların maviliğinde, sen vardın! Karıncalar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-vardin-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bağışladım Çünkü Beni Çok Üzdün', 'seni-bagisladim-cunku-beni-cok-uzdun-koray-feyiz-xg6ka', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İzzet öldü,sen bana bir mektup yazdın.

Sarmaşıklarla örülmüş bahçede bütün bir yaz 

Bana yazdığın mektubu okuyarak ağladım.

Ağlamak; bir umutsuzluktu belki ben hep umutsuzdum 

Ağlamak; bir kaçışdı belki ben hep kaçtım 

Ağlamak; bir yanılgıydı belki ben hep yanıldım 

Ağlamak; bir hataydı belki ben hep hata yaptım.

sarmaşıklarla örülmüş bahçede bütün bir yaz 

Seni bağışladım çünkü beni çok üzdün.

Yaz geçti,yağmur yağdı,sonbaharın pası birikti içime 

Kurumuş yapraklar,ozan askerden geldi, 

Daha neler oldu kimbilir benim bilmediğim? 

Benim bilmediğim bir beş vakit namaz var aslında,

Ayrılıkları da bilirim ihaneti de 

Kardeşliği de bilirim ölümün soğuk elini...

Koynumda gezerdi yılan gibi sokardı sessizce, 

Herkes sessizliği sever,ben sevmem nedense.

İzzet de koltuğunda taşımayı pek sevmezdi 

Hukuk kitaplarını ama okumayı çok severdi 

Bir de şiiri,geceyi severdi ancak karanlığı sevmezdi 

Bu kenti değil kentin kalabalıklığını severdi, 

Yalnızdı...kendi gibi yaralı olan ne varsa severdi,

Bu yüzden hiç solmadı yakasındaki karanfil.

İzzet öldü,sen bana bir mektup yazdın.

sarmaşıklarla örülmüş bahçede bütün bir yaz 

Bana yazdığın mektubu okuyarak üşüdüm.

Üşümek; bir mutsuzluktu belki biz hep mutsuzduk 

Üşümek; bir korkuydu belki biz hep korktuk 

Üşümek; bir yalnızlıktı belki biz hep yalnızdık 

Üşümek; bir şiirdi belki biz hep şairdik.', 'İzzet öldü,sen bana bir mektup yazdın. Sarmaşıklarla örülmüş bahçede bütün bir yaz  Bana yazdığın mektubu okuyarak ağladım. Ağlamak; bir umu...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seni-bagisladim-cunku-beni-cok-uzdun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-meram-yalinizoglu-i8ha4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neredesin biliyor musun? 

Umudumu bağladığım sen,

Rüyalarımı süsleyen sen,

Uçsuz bucaksız sen,

Lüle lüle, salkım salkım sen,

Lacivert yalnız gecelerde sen,

Aç kalbimi bak

Her yerinde sen.

Yaz akşamı sıcağı sen,

Ay parçası sen,

Lodos sen,Poyraz sen,

Ilık esen Meltem sen,

Nadide bir çiçek sen,

Issız bir sokak çeşmesi sen,

Zamansız aşk sen,

Onlarca çocuk mutluluğu sen,

Gel aç kalbimi

Leylaklarla sümbüllerle

Umutlarımın içerisinde yalnız sen.', 'Neredesin biliyor musun?  Umudumu bağladığım sen, Rüyalarımı süsleyen sen, Uçsuz bucaksız sen, Lüle lüle, salkım salkım sen, Lacivert yalnız...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-661-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla''ya Söyleyin...', 'leyla-ya-soyleyin-cumhur-bulut-xwj1e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Leyla Gelir Rüyalarıma

Mihrace kuşanmış

Soğuk kış gecelerinde 

Ninem anlatırdı:

Leyla bir masal mış…

Kış böyle gelir bizim ellere/

Ihlamur gibi kokar zaman

Kuzine aleviyle

Gönüller sımsıcak

Ve Leyla’ dan bir şeyler bırakarak…

Leyla, ah Leyla! 

Bütün aşkların kahramanı.

Leyla, Leyla, ah Leyla

Bütün aşklarımızın masalı

Bırak zülfünü çağlar tarasın

Sen Babil’ in değil

Gönüllerimizin ışığısın

En güzel dil ile anlatsın yine 

Fuzuli seni 

Okusun münzevi Mecnunlar 

Mihraplarda virdini

Leyla ki beklenen kadın

Her şarkıda geçer

Gizliden gizliye adın

Bu zaman sana hasrettir

İnsanlar taşlardan bir yığın

Cemiyet sensiz bir kasavettir

Leyla, ah Leyla! 

Bütün aşkların kahramanı.

Leyla, Leyla, ah Leyla

Bütün aşklarımızın masalı

Neredesin ey nur-u nisa

Neredesin ey gülgeşt-i sahra? 

Söyle seni hangi mısradan sorayım

Gel ki, gönül köşkünde mihmandarın olayım.

Günler katar oldu Leyla

Her biri yayından fırlamış ok

Yaralı bedenlerde 

Ruhundan eser yok…', 'Leyla Gelir Rüyalarıma Mihrace kuşanmış Soğuk kış gecelerinde  Ninem anlatırdı: Leyla bir masal mış… Kış böyle gelir bizim ellere/ Ihlamur g...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Bulut']::text[], 8.5, '{"poet":"Cumhur Bulut","poet_slug":"cumhur-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/leyla-ya-soyleyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oda', 'oda-ferit-gursoy-odn99', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dört tarafı duvarla çevrili oda

Işık sızmaz

Güneş almaz

Buz gibi oda

Yıkılınca duvarlar 

Yemyeşil dünya 

Umutlara 

Düşlere

Yetmeyen oda

Nice insanlar, düşünceleri

Masum hayalleri

Tüm sevinçleri

Yok ettin yok ettin

İçinde oda

Birgün gelir

Hesabını sorarlar ama! 

Kaç insan kaç ana

Yanar be oda...! 

                                     1992', 'Dört tarafı duvarla çevrili oda Işık sızmaz Güneş almaz Buz gibi oda Yıkılınca duvarlar  Yemyeşil dünya  Umutlara  Düşlere Yetmeyen oda Nice...', ARRAY['Türk Edebiyatı','Şiir','Ferit Gürsoy']::text[], 8.5, '{"poet":"Ferit Gürsoy","poet_slug":"ferit-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/oda-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gecenin Hal Tercümesidir', 'bir-gecenin-hal-tercumesidir-cumhur-bulut-yxp04', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gir düşlerime bu gece

İbrahim’ in ülkesinde yine

Yangın göreceksin! 

Ateş yanar; 

Yürek yanar, can yanar! 

Acısı bir âbidin heybesinde 

Öylece katışıksız

Bedelince karşılıksız,

Pahası gönül yakar, dil yakar! 

Bu sırrı dudaklarımda saklıyorum

İfşâsı anlık bu zulmün

Kimseler duymasın diye

Ve kanamasın diye yeniden acılarım

..........

..........

Gel bu gece,

İbrahim gibi beni de

Yanarken  göreceksin

İsyansız, mutmain...

Baş eğmiş kahra ve lûtfa

Ateş har, ateş yar! 

Çırpınışlar...

Izdıraptan ötelere

Uzanan  kaygısız yollar,

Zûlümden ikbale

Açılan kollar.

Sonra...

Huzur  veren bir nidâ:

Her şey sana, her şey sana! 

                                                       11.08.2001', 'Gir düşlerime bu gece İbrahim’ in ülkesinde yine Yangın göreceksin!  Ateş yanar;  Yürek yanar, can yanar!  Acısı bir âbidin heybesinde  Öyle...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Bulut']::text[], 8.5, '{"poet":"Cumhur Bulut","poet_slug":"cumhur-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-gecenin-hal-tercumesidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nafile', 'nafile-ferit-gursoy-9a4wf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni kaderimle başbaşa bırakanlara

Söz verip arkamdan iş yapanlara

Merhamet diye dilendiğimde rüşvet sanana

Bir kurşun değil bin kurşun sıksamda Nafile...

Orospu çocukları, fahişeler, asfalt kadınlarına

Namussuz, asalak, manyak tiplere

Selamsız Sabahsız yollara çıkanlara

Bir küfür değil bir küfür etsem Nafile

			24.08.1991', 'Beni kaderimle başbaşa bırakanlara Söz verip arkamdan iş yapanlara Merhamet diye dilendiğimde rüşvet sanana Bir kurşun değil bin kurşun sıks...', ARRAY['Türk Edebiyatı','Şiir','Ferit Gürsoy']::text[], 8.5, '{"poet":"Ferit Gürsoy","poet_slug":"ferit-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nafile-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Bitsin', 'hasret-bitsin-semsettin-veli-erbilli-ftg2q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün bir daha gördüm her gün gördüğüm kızı

Çırpınan yüreğimde oldu yaman bir sızı

Bu güzel ya öldürür ya deli eder bizi

Onunla ya konuşum ya da bırakıp gitsin

Her karşılaştığımda gönlüm hıçkırıp ağlar

Hicran yarası gibi sessiz bağrımı dağlar

Koşmaca bitmez oldu onu bana kim bağlar

Tutum elinden birgün içimde hasret bitsin

Ne olur adın bilsem dese adım sevcandır

Düyunca söyleyeyim bu can sende ne candır

Hem de güzelliğine söylesem can kurbandır

Şan olsun sevdalılar bizimle bayram etsin', 'Bugün bir daha gördüm her gün gördüğüm kızı Çırpınan yüreğimde oldu yaman bir sızı Bu güzel ya öldürür ya deli eder bizi Onunla ya konuşum y...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Veli Erbilli']::text[], 8.5, '{"poet":"Şemsettin Veli Erbilli","poet_slug":"semsettin-veli-erbilli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasret-bitsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sinema Karesi...', 'bir-sinema-karesi-cumhur-bulut-nplb1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sana sonteşrinde vuruldum,

Ey koca şehir; 

Ürkek adımlarla tozarken 

Dar sokaklarını.

Kederi kuş kanatlarından,

Acıyı sessiz akşamlarından,

Sevgiyi de saman pazarından

Bedelsiz  aldım.

Ben sana yağmurlu bir günde

Vuruldum,

Ey garip şehir; 

Nasırlı elleri bile sırılsıklamdı

O ihtiyar adamın.

Kendi sustu

Nemli gözleri konuştu

Bulutlar ağladı

Ben senden kopamadım

Ey ihtiyar şehir! 

Taş taş sıralanır yollarıma

Hatıraların 

Ne hüznün bırakır ellerimi

Ne de sevincin

Ben senden ayrılamadım

Ey ihtiyar şehir! 

Söyle çocuklarına 

Oyunları hiç bitmesin

Pazaryeri öksüz kalır sonra

Selam söyle lastik ayakkabılı

Simitçi kadına 

Herşey güzel olacak merak etmesin.

Beni hep böyle derde bıraktın

Ey sessiz şehir! 

Gül dalıyla sardın yükü omuzlarıma          

Duysan içini parçalar

Hıçkırıklarım

Muhabbet taşırım kanlı sevdalarıma...

                                                              

                                                                 07.04.2002 Çankırı', 'Ben sana sonteşrinde vuruldum, Ey koca şehir;  Ürkek adımlarla tozarken  Dar sokaklarını. Kederi kuş kanatlarından, Acıyı sessiz akşamlarınd...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Bulut']::text[], 8.5, '{"poet":"Cumhur Bulut","poet_slug":"cumhur-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bir-sinema-karesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genetiği Değiştirilmiş Kuyruklu Şiir', 'genetigi-degistirilmis-kuyruklu-siir-veysel-toprak-1enme', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Homines quod volunt credunt *

                                          

                                        

                             

" Kendisini mesih zanneden bir kedinin, 

Orhan Veli''ye yanıtıdır. "

                                

                               

minik bir kediyim ben

günlerdir fare sürüleri akıyor gözlerimden

damla damla çöplüklere vuruyorum kendimi

ciğerimsi bir ağrıyla dolaşıyorum günlerdir

sanki bütün Orhan Veliler 

geçip gitmiş bu sokaklardan...

                                      

                            

kalbim sevgi dolu, uyuşuruz kardeşlerim 

Sen ciğercinin kedisi, Sen sokak kedisi 

ben öperim sizin kuyruklu şiirinizi 

bir kuşun kanadını okşar gibi!

bakmayın bu hırçın konuşmalarıma

uysal bir kediyim ben

günlerdir 

martıların kanatları teğet geçer gözlerime

bütün canlarını şehvete heba eden 

ben değilim

oturmuş azgınlığımı tırmalıyorum

keşfetmek için nankörlüğümü....

yapayalnız bir kediyim ben

kimseler görmedi ağladığımı

yenik bir serçeye gülümserken...

kimseler görmedi martılara özendiğimi

beni koyup giden annemi bulmak

kolay olurdu belki de...

ben iyiyim de yordu beni dünyanız 

altı kat daha iyi görürüm karanlıkta 

siz nasıl görmezsiniz beni 

kalbimde taşırken dünyayı bir çocuk resmî!

ben iyiyim de karnım aç 

60 kHz ile duyarım 

metrelerce uzaktaki böceği 

siz nasıl duymazsınız beni 

ben iyiyim de sizler kötü 

tane tane aldınız canımı 

ey insanlık zulmünüz hep sürdü!

hadi kutsayın beni

ellerimle aldım altı canımı

minyatür kuşlara sakladım sonuncusunu!

                          

kimseler bilmeyebilir

hep ayrılıkları saydım

yine de iliştirdim 

nankör bir sevinci bıyıklarıma!

kimse bilmeyebilir

Meryem kadar masumum

İsa kadar yaslıyım

ve Orhan Veli kadar şairim!

kimse bilmeyebilir

kayıp ciğerler için

tanrılar kadar çok yaşamayı arzuladım!

kimse bilmeyebilir

iblis kadar ibranice bilirim

ve Sina dağı 

bir beden küçük gelir intiharlarıma!

miyavlasam

sesimi duyan yok uzaklarda

ve ben nerede ölsem

nerede ölsem de

bir çocuğun gözyaşı değse leşime!

                  

ahh birileri beni çok sevse

dağıtsam özlemlerimi ben bu kente

tutulsam en fiyakalı çöplükteki dilber kediye

'' sarıl bana ''  desem...

ve kuşlar hep uzak kalsa bana

bir kasabın önünden öylesine geçsem

hal hatır sormak için ciğerciye uğrasam

...salıncakta bir fareyi sallasam

...   ...    ...   ....  ..

...       ...    .. ...    ...

yedinci canımı da bırakıyorum işte

hem de top secret kaydı ile...

VARLIKTIR, 

VARLIK VAROLAN VARLIĞA GÖRE !

son canımı kendi varlığıma

bırakma ihaneti geldiğinde

kedi olmak bir yalnızlıktır

nankörlüğe göre...', 'Homines quod volunt credunt *                                                                                                               ...', ARRAY['Türk Edebiyatı','Şiir','Veysel Toprak']::text[], 8.5, '{"poet":"Veysel Toprak","poet_slug":"veysel-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/orhan-veliye-mesih-kediden-cevap-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Aldırma', 'aldirma-talip-kaplan-iz2c3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boş ver be

Aldırma benim ağrıma

Yıkılmışlık nasır bağlamış zaten

Yüreğimin harcı yıkıntılardan

Sen aldırma

Dert etme bir de beni

Hem ben

Ama aldırma

Ne önemi var

Sen o derya deniz

Sen o güzel kız

Dalga dalga hırçın sular

Bir damla n ömre bedel

Ömürlerce

Sen bana aldırma...

(31 Temmuz 2004)', 'Boş ver be Aldırma benim ağrıma Yıkılmışlık nasır bağlamış zaten Yüreğimin harcı yıkıntılardan Sen aldırma Dert etme bir de beni Hem ben Ama...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aldirma-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneye özlem', 'anneye-ozlem-mustafa-kayin-xagwb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canından can verdin bana

Kanından kan annem

Yaşam verdin,hayat verdin

Karşılıksız,menfaatsiz,beklentisiz

Asil bir şey bu yaptığın

Ne cefalar çektin ne çileler

Borcum var sana; 

Ödenilmez bir borç bu annem

Ne yapsam ödemek mümkünmü

Tek istediğin; 

Çocuklarını mutlu görmekti

Her anne istemezmi bunu

Her anne dilemezmi bunu

Yaşam bazen acımasız

Düşler her zaman gerçek

Gerçekler her zaman

Güzel olmuyor annem

Düşündükçe eski günleri

Hep çocuk olası geliyor insanın

Hayat her zaman gülmüyor insana

Mutluluk bazen çok uzaklarda kalıyor

Batan güneş ve ufukta kaybolan gemi misali

Uzanıp yakalamak geliyor insanın içinden

Tıpkı şimdi yanımda olmanı istediğim gibi

Sende çok uzaklara gittin ya

Dayanmak çok zor özlem ise çok

Eski günler çocukluğum geliyor aklıma 

Keşke hep çocuk kalsaydım seninle birlikte

Kaybetmezdim belki o zaman seni

Yokluğuna alışmayı,seni kaybettiğimi

Düşünmezdim o zaman annem', 'Canından can verdin bana Kanından kan annem Yaşam verdin,hayat verdin Karşılıksız,menfaatsiz,beklentisiz Asil bir şey bu yaptığın Ne cefalar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kayın']::text[], 8.5, '{"poet":"Mustafa Kayın","poet_slug":"mustafa-kayin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/anneye-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Namına Sembolik', 'senin-namina-sembolik-cumhur-bulut-vqlh9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Matmazel Albertini; Süryani kadın.

Bütün kadınlardan daha güzel gözleri

Neydi ruhunda gizlediğin kadın

Kör ediyor sana bakan gözleri

Göçmen kuşlar gelip geçti kadın,

Gökyüzü şimdi  ayrılığın yasında 

Gamzeli gülüşün gelip geçer kadın

Beni bırakacaksın göz yaşlarımla

Albertini; sen aynalardaki en güzel kadın

Nasılda çekersin gül tütünü ciğerlerine 

Dudaklarından başka bir yol mu var kadın

Beni de çek, bir nefeste, öylece içine

Albertini; ilk ağladığım peri kadın

Yok oluyorum senin olduğun her yerde 

Beni böyle bırakıp giden ecnebi kadın

Gül olup açacaksın öldüğüm yerde 

Şimdi şarkılar yazıyorum senin aşkına 

Ölüm getiren şarkıların muazzez kadını

Ne vardı doğmasaydın böyle ufuklarıma

Sen, bulduğum cennetin Süryani kadını.

                                                               23.12.1999 Foça', 'Matmazel Albertini; Süryani kadın. Bütün kadınlardan daha güzel gözleri Neydi ruhunda gizlediğin kadın Kör ediyor sana bakan gözleri Göçmen ...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Bulut']::text[], 8.5, '{"poet":"Cumhur Bulut","poet_slug":"cumhur-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/senin-namina-sembolik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklara', 'uzaklara-cumhur-bulut-7xxk7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben gidiyorum,

Her ne ise 

Faydası yok artık yalnızlığın

Saçlarının dağıttığı 

Şehir omuzlarımda

Büyüyor geride bıraktığım bütün çocuklar

Her gün avuçlarına umut bıraktığım

 Simitçiye el sallıyorum 

Ben gidiyorum! 

Hatırla sana söylediğim 

Bütün gizemli sözleri

Bir türlü duyuramadığım feryadımı 

Hatırla.

Ben gidiyorum,

Her ne ise 

faydası yok

Artık yüzüstü bırakılmışlığın,

Acı da olsa  gülümsüyorum... Ben gidiyorum

Eskiden duyduğum bir şarkıyı 

Geride bıraktığım 

Çocuklara ve

Tezgahında umut biriktiren Simitçiye 

Söylüyorum...

Her ne ise faydası yok artık

İtilmişliğin,

Yürüyorum...Ve ben gidiyorum! 

Bahçenizden kopardığım

Gül elimde; 

Kurumuş...

Güzel bir hali var yine de /

Yine de diyorum...

Yakama takıyorum, ben gidiyorum! 

                                                              18.03.2001', 'Ben gidiyorum, Her ne ise  Faydası yok artık yalnızlığın Saçlarının dağıttığı  Şehir omuzlarımda Büyüyor geride bıraktığım bütün çocuklar He...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Bulut']::text[], 8.5, '{"poet":"Cumhur Bulut","poet_slug":"cumhur-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/uzaklara-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kullanın', 'kullanin-necati-keceli-ucix6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zamanla çeksen de türlü eziyet

    Her zaman neşeli yanı kullanın

    İnsanlarda vardır değişik niyet

    Siz onurlu olun, şanı kullanın

    Kefil olmamak için dost birine

    Merak edip inme fazla derine

    Sevgiyi gösterin restin yerine

    Siz sevimli olun hanı kullanın

    Yardım isteyene iyilik yapın

    Hoş görülü olun sevgiye sapın

    Bir kötü gününde çalarsa kapın

    Güler yüzlü olun canı kullanın

    Yaşayıp görsen de sarayı, hanı

    Kırmayın insanı sevin her canı

    Yaşatmak istersen hasta insanı

    Siz sağlıklı olun kanı kullanın

    Dostluğu bitirip dostuna küsme

    Yanlış yöne girip fırtına esme

    Diline hâkim ol hiç asıp kesme

    Siz akıllı olun zan’ı kullanın

    Necati duysan da iyi, kötü laf

    Dünyada gördüğün gelmesin tuhaf

    Her insanda vardır birazcık zaaf

    Siz iyi düşünün anı kullanın

    Necati KEÇELİ

    ADANA 20.10.2005', 'Zamanla çeksen de türlü eziyet     Her zaman neşeli yanı kullanın     İnsanlarda vardır değişik niyet     Siz onurlu olun, şanı kullanın    ...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kullanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minareler Hüzün Konuşur', 'minareler-huzun-konusur-cumhur-bulut-wl95z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kötü adamlara benzeyen yüzleriyle

Bu duvarlar buz gibi soğuktur.

Oysa benim limanlarım

Hala buharlı gemilerle doludur.

Bir yanda atlı tramvaylar,

Alınlarında boncuk boncuk  ter,

Gemilere Yük taşıyan hamallar....

	

İşte böyle

Zamana veririm gözlerimi.

Her geçen gün çaldıkça benden gelecek

Aradığım oradadır

Vakur, latif  ve gerçek! 

Dilersen al ellerini benden

Bu duvarlar gibi 

Süse muhtaç kadın

Benim bu devirle bir hesabım var

Beton binaları yıkacak feryadım

Hala ahşap bir konaktan 

Bakıyorum hayata

Sabahın ilk ışıklarıyla

Selamlar şehri balıkçılar

Vira vira Bismillah! 

Hala deniz manzaralı

Bir konaktan 

Bakıyorum hayata...

Sen de fark edersin; 

Hüzün konuşur bu şehirde 

Biz olanlar

Bir ayrılık bestesinin nameleri gibi 

Hıçkırarak ağlar! 

Pervasız yükselir bu şehirde

Binalar,

Binbir  pençe ile

Hücum eder ruhumuza

Zalim ve gaddar... 

Bu duvarlar buz gibi soğuktur

Oysa benim sokaklarım

Ahşap konaklarla doludur! 

									24.05.2002 Cuma', 'Kötü adamlara benzeyen yüzleriyle Bu duvarlar buz gibi soğuktur. Oysa benim limanlarım Hala buharlı gemilerle doludur. Bir yanda atlı tramva...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Bulut']::text[], 8.5, '{"poet":"Cumhur Bulut","poet_slug":"cumhur-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/minareler-huzun-konusur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerimi hayal ederim', 'hayallerimi-hayal-ederim-zeliha-ural-2hdl9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçükken hayallerim vardı

kendimden büyük.

Sevgimi saklamıştım.

Şefkatimin kollarını açtım,

Özlem çekerek yıllara.

İşte adını söylemiyorum kime, niye diye

Varsın hasret bilsinler 

İçimdeki yanan ateşi 

Bundan sonra biliyorum alışmalayım.

Aman Allahım bu nasıl hasret.

Hasret dedikçe korlanan bir ateş

İçim acıyor.

Ama nasıl olur alışamam 

Biz onunla büyüdük

Başı öne eğen 

Gönle söz dinletemeyen, o çocuk.

Ne kadar güzelmiş hayallerim

Ne gariptir ki şimdi o hayallerimi hayal ederim', 'Küçükken hayallerim vardı kendimden büyük. Sevgimi saklamıştım. Şefkatimin kollarını açtım, Özlem çekerek yıllara. İşte adını söylemiyorum k...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Ural']::text[], 8.5, '{"poet":"Zeliha Ural","poet_slug":"zeliha-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayallerimi-hayal-ederim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tedavülden Kalkan Bir Aşk''a Aittir: 12 Eylül', 'tedavulden-kalkan-bir-ask-a-aittir-12-eylul-cumhur-bulut-1n7h5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 've buğulu 

bir camda kırılır ellerin; 

sana uzanan güllere dokunamazsın bile

sanıktır hala çocukları bu şehrin

darağaçları gizlidir  gülücüklerinde

kalır buğulu bir camda

güzelliğin; 

yansıyan, senden başka her şey artık

bir meçhûlde gizli ve derin

hayra yorulan düşlerdeki kutsal varlık

buğulu bir camda

saklıdır; senin hatıraların

eylülde sonbaharın ve yalancı nisanın

....nasıldı.....? 

.....asıldı......! 

kendi hikayende öz adın! 

12 Eylül....', 've buğulu  bir camda kırılır ellerin;  sana uzanan güllere dokunamazsın bile sanıktır hala çocukları bu şehrin darağaçları gizlidir  gülücük...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Bulut']::text[], 8.5, '{"poet":"Cumhur Bulut","poet_slug":"cumhur-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tedavulden-kalkan-bir-ask-a-aittir-12-eylul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuş Anne', 'konus-anne-i-lknur-er-74zko', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karşımdasın

Ellerim,yüreğim avuçlarında

Yılların biriktirdiği

Hasret dumanı tüte tüte gelmişim

Koynuna 

Ama sen

Tanımıyorsun beni

Biricik oğlunu

İnanmak ne zor anne

Oğlum dediğini duyamamak

Yaşarken ölmek ne acı

Başkasında duyunca

Ah, vah deriz ya

Ahlar vahlar  gelmiyor kulağıma anne

Sağır oldum senden başka sese 

O şen diline yakışıyor mu susmak

Konuş anne ne olur konuş

Dindir içimdeki fırtınaları

Alzheimer a yenilme anne 

Ne olur yenilme', 'Karşımdasın Ellerim,yüreğim avuçlarında Yılların biriktirdiği Hasret dumanı tüte tüte gelmişim Koynuna  Ama sen Tanımıyorsun beni Biricik oğ...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/konus-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek’te Gitti', 'melek-te-gitti-figen-aydogmus-xklp7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Melek’te Gitti

Gittiği anda kaldı saat

Saatin yelkovanı onu gösterir

Benim doğum günüm onunsa ölümü

Ölümlü dünyaya kapandı gözleri

Sıkıştı boğazım darağacına

Takılı ilmekte asılı bedenim

Gittiğin günden üç gün sonra

Öğrendim bir daha göremeyeceğim.

Ne garip bir yaşam döner dururuz

Gidenlere rahmet

Kalana sağlık

Başımızın nuru meleklerimiz

Kalmadıkça nasıl huzur buluruz

Bırakıp giderken acılardaydı

Bıraktı da beni acılardayım

Huzura erdin mi söyle Melek’im

Anacığım sensiz Ben sensiz kaldım

Hoşça kal canparem gülen gözlerim

Hasretini artık gizli çekerim

Sır vermem nineciğim kimseciklere

Özleminle böyle yaşar giderim', 'Melek’te Gitti Gittiği anda kaldı saat Saatin yelkovanı onu gösterir Benim doğum günüm onunsa ölümü Ölümlü dünyaya kapandı gözleri Sıkıştı b...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/melek-te-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birinci Yirmi', 'birinci-yirmi-suleyman-eser-cvvnr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gölgeli yüzlerin ardında

Gökyüzüne ulaşan merdivenler

Bulutları kucaklayan denizler vardı

Şen şakrak çocuk cıvıltısı

Kulaklarım uğul uğul

Bir çılgınlık arıyorum

Sen yine yoksun

Yüksek gerilim hatlarını

Atardamar niyetine 

Kalbime bağlıyorum

Paslı demirlerle asılmışım

Çürük ahşap çerçevelere

Gönül vermişim yıllarca 

Sarı bir posta arabasına 

Ya da mermer musalla taşına 

Senin yokluğun sinmiş odama 

Ağrı kesiciyi de 

Durmadan değiştiriyorum

Ben hala benim

Kurduğum cümlelerde kayboluyorum

Nevresim takımım kirlendi

Onu bile yatağımdan

Söküp atamıyorum

Balkonun önündeki akşam sefaları

Sensizken bir kez bile açılmadı

Ve gönül fuarımın ziyaretçi kartları

Yılardır kullanılmadı.     

                                      –ÜMRANİYE-

                                        01.09.2005', 'Gölgeli yüzlerin ardında Gökyüzüne ulaşan merdivenler Bulutları kucaklayan denizler vardı Şen şakrak çocuk cıvıltısı Kulaklarım uğul uğul Bi...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Eser']::text[], 8.5, '{"poet":"Süleyman Eser","poet_slug":"suleyman-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/birinci-yirmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzin Kalmasın', 'i-zin-kalmasin-i-lknur-er-3jq3u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kahroldum

Aşkın yalan 

Yıkıldım

İhanetinden

Körmüşüm

Görmedim

Sağırmışım

Duymadım

Sen Açtın 

Gözlerimi

Sen Kapattın

Huzurum yok

Darmadağınım

Gel Topla

Artıklarını

Sonra git

İzin Kalmasın', 'Kahroldum Aşkın yalan  Yıkıldım İhanetinden Körmüşüm Görmedim Sağırmışım Duymadım Sen Açtın  Gözlerimi Sen Kapattın Huzurum yok Darmadağınım...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/izin-kalmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülünce', 'gulunce-sair-saheser-8i7m3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gülünce yüzünde güller açıyor

güzelleşiyor gözlerin

sarp kayalıklarda açan

kır çiçekleri gibi

uçsuz bucaksız okyanuslarda salınan

yelkenli gibi

gül, son nefesine kadar gül

ve unutma sakın

gülmek sana çok yakışıyor', 'gülünce yüzünde güller açıyor güzelleşiyor gözlerin sarp kayalıklarda açan kır çiçekleri gibi uçsuz bucaksız okyanuslarda salınan yelkenli g...', ARRAY['Türk Edebiyatı','Şiir','Şair Saheser']::text[], 8.5, '{"poet":"Şair Saheser","poet_slug":"sair-saheser","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gulunce-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulunmaz', 'bulunmaz-tercan-keskin-ca975', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdim bir zalimi yıkıldı tahtım

Yüzüme birazcık gülen bulunmaz

Ben doğdum doğalı karadır bahtım

Derdime bir derman bilen bulunmaz

Uydum tozpembe bir aşkın sesine

Sevilen sevmiyor her şey tersine

Gelip çattım ömrün son nefesine

Bir tas su vermeye gelen bulunmaz

Dermansız yarama tuzlar basarım

Feryatlarım dinmez nasıl susarım

Sevilmedim diye aşka küserim

Sevgi cennetine salan bulunmaz

İsyanlar bellidir her bir sözümde

Çizgiler belirir asık yüzümde

Tesellisiz ağlar iki gözüm de

Boşalan yaşları silen bulunmaz

Düşmanın başına bahtın karası

Sarhoş yüreğimin dinmez narası

Bu sevda başıma yürek yarası

Gönlüm avutmaya yalan bulunmaz', 'Sevdim bir zalimi yıkıldı tahtım Yüzüme birazcık gülen bulunmaz Ben doğdum doğalı karadır bahtım Derdime bir derman bilen bulunmaz Uydum toz...', ARRAY['Türk Edebiyatı','Şiir','Tercan Keskin']::text[], 8.5, '{"poet":"Tercan Keskin","poet_slug":"tercan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bulunmaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Yükü', 'askin-yuku-tercan-keskin-p5z4u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkın yükü ağır gelir boynuma

Dertler artık gözyaşımla beslenir

Sevdiğimi alamadım koynuma

Yarim şimdi başkasına süslenir

Eridiler sevgi denen dağlarım

Hasretiyle viran oldu bağlarım

Yardan ayrı sevinemem ağlarım

Acıların hepsi bana yaslanır

Bu bozduğum kaç yüzüncü and oldu

Kader bizim aramıza bend oldu

Gülümseyen gözlerime kan doldu

Yanaklarım al kanlarla ıslanır

Dindirmedi barımdaki ağrıyı

Mecnun oldum seçemedim doğruyu

Azrail’den dinliyorum çağrıyı

Ölüm bana “Gel, Gel! ” diye seslenir

Soldu gönlüm hazan vakti gelmeden

Ömrüm bitti bir kez olsun gülmeden

O yar gelip bana derman olmadan

Sanmıyorum deli gönül uslanır', 'Aşkın yükü ağır gelir boynuma Dertler artık gözyaşımla beslenir Sevdiğimi alamadım koynuma Yarim şimdi başkasına süslenir Eridiler sevgi den...', ARRAY['Türk Edebiyatı','Şiir','Tercan Keskin']::text[], 8.5, '{"poet":"Tercan Keskin","poet_slug":"tercan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askin-yuku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yer Ararken Gel', 'bir-yer-ararken-gel-sair-saheser-i66si', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sessizliği yaran bu çocuk çığlıkları

yayılırken çoğu şeyden habersiz

karanlığı silen bu araba farları

parıldarken gönülden gönüle

denizin maviliklerinde bir balık sürüsü

sürüklenirken nereye gittiğini bilmeden

ormanın ıssızlığında bir ala geyik

sığınırken korkudan korkuya

güzellikler aleminde ben de bir yer 

ararken gel', 'sessizliği yaran bu çocuk çığlıkları yayılırken çoğu şeyden habersiz karanlığı silen bu araba farları parıldarken gönülden gönüle denizin ma...', ARRAY['Türk Edebiyatı','Şiir','Şair Saheser']::text[], 8.5, '{"poet":"Şair Saheser","poet_slug":"sair-saheser","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-yer-ararken-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Falcı', 'falci-suleyman-eser-ej2k1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeter artık falcı kapat çeneni

İsyanım var senin baktığın fala

Çevir fincandan,çevir gözlerini

Keder akar benden baktığın yana

Gülleri yabancı bana bu yerin

Göğsüme açtığı yaralar derin

Her dalda duran o iğnelerin

Uçları bulandı baktığın kana.

Ellerim tutamaz, gözlerim görmez

Mazlumlar ölse de zalimler ölmez

Ecelim gelirde, Şirinim dönmez,

Kastı vardır belki baktığın cana

                                                  =Üvezli= 

                                               08.06.2002', 'Yeter artık falcı kapat çeneni İsyanım var senin baktığın fala Çevir fincandan,çevir gözlerini Keder akar benden baktığın yana Gülleri yaban...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Eser']::text[], 8.5, '{"poet":"Süleyman Eser","poet_slug":"suleyman-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/falci-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuh Olsun', 'yuh-olsun-suleyman-zaman-so2g8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çıktım sokaklara, insan ararım

Vicdan pazarında dara kurarım

Bilirim denk olmaz, her gün kararım

İnsanlığı bozan, cana yuh olsun

Ona başka, buna başka söz eden

Mervan’ın peşine, takılıp giden

Hep kendi nefsine, çıkarlar güden

Banalca duruşa, hepten yuh olsun

Bir sürü yığınlar, gezer dolaşır

Kimisi cahilce, kırıyor hatır

Kimi çok söz eder, yazmaz bir satır

Kendin bilmeyene, hepten yuh olsun

Herkesin sırtından, çalıp geçinen

Yapmacık pozlarla, yüzlere gülen

Yalan dolan ile, akıllar çelen

Riyakar duruşa, hepten yuh olsun

Güzel sözler ile, okşar tinini

Bitince işleri, döner yönünü

İnkar eder ise, eğer dününü

Kimliksiz olana, hepten yuh olsun

Bozulmuş kiminin, özü değeri

Kalmamış hayatta, doğrunun yeri

Zamanıma bunca, verdin kederi

Heder yükleyene, hepten yuh olsun

                  14.01.2003', 'Çıktım sokaklara, insan ararım Vicdan pazarında dara kurarım Bilirim denk olmaz, her gün kararım İnsanlığı bozan, cana yuh olsun Ona başka, ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yuh-olsun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Seni', 'seviyorum-seni-sair-saheser-sn8iv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk gördüğümde sevdim seni

bulutlarda uçuyorum sanki

rüyalarım gerçek oldu şimdi

aşık oldum sana deli gibi

hayallerim gerçek oldu

işit beni gör beni 

seviyorum işte seni

masal değil gerçğin ta kendisi

......

dedilerde inanamadım

en güzel günlerimi seninle yaşadım

melek olduğunu sandım

içimdeki çoşkuyla savruldum

rüya olmadığına artık inandım

hayatın gerçek anlamını

seni sevince anladım

ne olur sen de söyle

beni çok sevdiğini

bozulmasın bu rüya

seviyorum işte seni', 'İlk gördüğümde sevdim seni bulutlarda uçuyorum sanki rüyalarım gerçek oldu şimdi aşık oldum sana deli gibi hayallerim gerçek oldu işit beni ...', ARRAY['Türk Edebiyatı','Şiir','Şair Saheser']::text[], 8.5, '{"poet":"Şair Saheser","poet_slug":"sair-saheser","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seviyorum-seni-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş ile ay...', 'gunes-ile-ay-emirhan-bala-ctwln', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlemimi külledim sana kadar,

Zifiri şeytanlıklar ne yazar,

Nihavent ceremeler ruhuma işler,

Uslu gönlüm seninle azar,

Raks ederler sevdamıza güneş ile ay….', 'Özlemimi külledim sana kadar, Zifiri şeytanlıklar ne yazar, Nihavent ceremeler ruhuma işler, Uslu gönlüm seninle azar, Raks ederler sevdamız...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gunes-ile-ay-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçarken Kuşlar', 'ucarken-kuslar-sair-saheser-zniif', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'uçarken kuşlar

büyüyen özgürlüklere

kayarken yıldız

korkutan boşluklara

yağarken yağmur

kurumuş topraklara

eserken rüzgar

uçuşan yapraklara

parlarken güneş

coşan kalplere

gezerken bulut

mavi göklerde

bütün bunlar

seni bana getirir', 'uçarken kuşlar büyüyen özgürlüklere kayarken yıldız korkutan boşluklara yağarken yağmur kurumuş topraklara eserken rüzgar uçuşan yapraklara ...', ARRAY['Türk Edebiyatı','Şiir','Şair Saheser']::text[], 8.5, '{"poet":"Şair Saheser","poet_slug":"sair-saheser","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ucarken-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet', 'cumhuriyet-i-brahim-seker-h3cx7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir güneşin doğuşu, bir ışıktır: Cumhuriyet! 

Özgürlüğe düşkün Türk''e çok layıktır: Cumhuriyet! 

Yıkılmış Osmanlı''nın yerine diriliştir: Cumhuriyet! 

Düşmanların karşısına dikiliştir: Cumhuriyet! 

Halk''ı yönetime katan özgürlüktür: Cumhuriyet! 

Hürriyetle vatanımı saran kürktür: Cumhuriyet! 

Büyük Atamın armağanı güzelliktir: Cumhuriyet! 

Türk''ün özgürlük beratı özelliktir: Cumhuriyet! 

Dökülen kanların bedeli, emanettir: Cumhuriyet! 

Türk''ün Atasından miras bir servettir: Cumhuriyet!', 'Bir güneşin doğuşu, bir ışıktır: Cumhuriyet!  Özgürlüğe düşkün Türk''e çok layıktır: Cumhuriyet!  Yıkılmış Osmanlı''nın yerine diriliştir: Cum...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Şeker']::text[], 8.5, '{"poet":"İbrahim Şeker","poet_slug":"i-brahim-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cumhuriyet-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanılmalı', 'kiskanilmali-ertugrul-sakar-q9vuo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pınarlar çağlasa da çöller kıskanılmalı 

Yağmurlar rahmet ise seller kıskanılmalı 

Ufkun sırrı dediğim bir serapa yükseklik 

Aşkın cezbesindeki güller kıskanılmalı', 'Pınarlar çağlasa da çöller kıskanılmalı  Yağmurlar rahmet ise seller kıskanılmalı  Ufkun sırrı dediğim bir serapa yükseklik  Aşkın cezbesind...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kiskanilmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 50', 'resaran-siir-ve-beyitsiler-50-huseyin-avdic-m2aiw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En Son Konağın

Kâinat ağacından düşmekte olan bir sonbahar yaprağısın.

Cennet veya cehennem olacaktır, düşeceğin en son konağın.

******

Vahşî Hayvanlar Olmazsa

Sürüden bir kuzu kapmaktır, yırtıcı hayvanların vahşiliği.

Onlarin varlığı olmazsa, kim yapar leşlerin temizliğini? 

Berlin, Ekim 2005.', 'En Son Konağın Kâinat ağacından düşmekte olan bir sonbahar yaprağısın. Cennet veya cehennem olacaktır, düşeceğin en son konağın. ****** Vahş...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/resarani-siir-ve-beyitsiler-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki', 'sanki-i-brahim-seker-jnl1f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O masmavi gözlerinle bakıyorsun ya,

Sanki beni gözlüyorsun uzaklardan...

Hani o üniformalı resimlerin var ya,

Sanki çıkıverecek gibisin fotoğraflardan...

Bilmesem öğretmeseler 10 Kasım''ları bana,

Sanki gelip tutacaksın ellerimi gibi geliyor...

Bakınca anlıyorum iyi işler yaptığımda,

Sanki masmavi gözlerin gülümsüyor...

Eğer bir yanlışım olsa bakamıyorum sana,

Sanki beni azarlayacaksın gibi geliyor...

O yüzden daha dikkat ediyorum adımlarıma,

Sanki masmavi gözlerin bunu biliyor...

Artık şüphe etmiyorum izliyorsun bizi uzaklardan,

Sanki gençleri görünce o masmavi gözlerin

Daha yapacak çok işler var diyor...', 'O masmavi gözlerinle bakıyorsun ya, Sanki beni gözlüyorsun uzaklardan... Hani o üniformalı resimlerin var ya, Sanki çıkıverecek gibisin foto...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Şeker']::text[], 8.5, '{"poet":"İbrahim Şeker","poet_slug":"i-brahim-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sanki-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kimsin', 'sen-kimsin-seyfettin-bilal-ozluk-gu6wd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşünüpte düşüme sığdıramadığım zamanlarımdasın

Sevdiğimi hissedipte haykıramadığım zamanlarda

Hani hayal kurarım ya hep

''Bir gitsem'' neler yapacağım diye

Bir anlamsız duygudur bu.

Ben gelirsem herşey biter

Hayallerim düşünceler

Toz oluverir hepsi.

Umarsızca kendimden geçerim

Sonra kollarıma alırım seni

Gözlerime bakarsın

Yeniden çocuk olurum

Şımartırım seni

İşte bu yüzden seviyorum seni.

Bana; unuttuğum herşeyi yeniden anımsatıyorsun

Hemde sadece bir bakış, bir dokunuş yeter günlerimi sarmaya.

Mektuplar biriktiriyorum hep günlüğümün arasında

Şiirler yazıyorum sana dair

Bazısını okutturuyorum sana ama

Bazısını sır tutuyorum özel zamanlara.

Notalarını bir türlü tutturamadığım bir türküsün sen

Adını bir türlü koyamadığım sevdam

Her bittiğinde yeniden başlayan bir parçamsın

Dolu dolu yaşadığım

Tek güne sığdıramadığım hikayem.

Sen! 

Dizelerimde anlatıpta bitiremediğim

Kelimelere sığdırmadığım herşeyimsin...', 'Düşünüpte düşüme sığdıramadığım zamanlarımdasın Sevdiğimi hissedipte haykıramadığım zamanlarda Hani hayal kurarım ya hep ''Bir gitsem'' neler ...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-kimsin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk - 1 -', 'ataturk-1-alper-kuruk-7zr4d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ihtiyar yaşardı bir zamanlar

600 yaşlarında bir ihtiyar.

Oyuncak olmuş sultan elinde

Kurtulmak için ölümü arar.

Barut olmuş bütün vatan

Ateş olmuş hürriyet,

Bir kurşun fırladı vatan bağrından 

Bir kurşundu ATATÜRK evet.

Saplandı ihtiyarın kalbine 

Bir anda devrildi dev vücud

Artık nâil olmuştu emeline.

Tüfek oldu Anadolu 

Anıt-Kabir  namlu,

Aramızdan eksik 

Kurşun yerleşti yerine.

Güven Ata''m gençlerine 

Elinde tetik

Bekliyor GENÇLİK...', 'Bir ihtiyar yaşardı bir zamanlar 600 yaşlarında bir ihtiyar. Oyuncak olmuş sultan elinde Kurtulmak için ölümü arar. Barut olmuş bütün vatan ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ataturk-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimi Sıkan Birşey Var', 'i-cimi-sikan-birsey-var-cagla-toygan-ch3oh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimi sıkan bir şey var

Umutsuzluk mu

Yine aradığını bulamamak mı..

Geçmişe özlem mi..

Doyumsuzluk? 

Mutlu olmak istiyorum

Huzur duymak

Geçmişe sine çekmek

Gereksizleri silmek

Değer vermek

Değer görmek

Aşık olmak

Heyecan…

Çıldırmak aşktan

Çocuk olmak onunla..

Elektrik kaplasın tüm bedenimi

Gözyaşları olsun ona baktığımda

Tutku gözyaşları

Kaybetme korkusu..

İçimde tuhaf o his..

Onu görmek için saniyeleri sayayım

Dakikalar hızlı geçsin onunla yine

Zaman kavramı olmasın..

Kararsızlık olmasın

Huzur olsun yalnız huzur..

Neşe olsun

Kalbim tüm bedenimde atsın..

Aşk acısıyla yeniden tanışalım

Sillesine razıyım onun..

Hayat çekilmiyor..

Geçmiyor bu zaman..

Tat vermiyor 

Neden neden! 

Bu soru delirtiyor..

İstediğim çok mu? 

Sadece sevmek..

Sevmek istiyorum ta derinden! 

O virüsü istiyorum..

Kör olmak istiyorum…

Yeni bir dünya..

İkimizin yarattığı...

Oraya taşınmak istiyorum! 

(20/10/2005)', 'İçimi sıkan bir şey var Umutsuzluk mu Yine aradığını bulamamak mı.. Geçmişe özlem mi.. Doyumsuzluk?  Mutlu olmak istiyorum Huzur duymak Geçm...', ARRAY['Türk Edebiyatı','Şiir','Çağla Toygan']::text[], 8.5, '{"poet":"Çağla Toygan","poet_slug":"cagla-toygan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/icimi-sikan-birsey-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünkü Çocuk', 'dunku-cocuk-zahide-handan-erengil-czkk3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl geçiyor günler,haftalar,aylar

Birbiri ardına koşan zalim yıllar.

Ömrümüzü nasıl da çaldılar? 

Sevdiklerimizi hep elden aldılar.

Her gün bir sonraki günü bekler,

Belki neşe,belki keder ekler.

Hesapsız,plan,program yapıyoruz,

Halbuki,gün be gün sona yaklaşıyoruz

Ömür dediğin nedir? 

Ne kadarı mutluluk,ne kadarı keder? 

İşte gelip geçiyor yıllar, ne fark eder.

Bilinmeyen bir yolda hızla koşuyoruz,

Kim bilir,kiminle,ne için savaşıyoruz.

Direniyoruz hayata, nasıl bir yaşam hırsıysa,

İçinde bir umut bir gizem saklıysa

Daha dün topaç çevirip,ip atlıyorduk,

Ne zaman,ne çabuk büyüdük unuttuk

Hep deriz ya,daha dünkü çocuktuk.', 'Nasıl geçiyor günler,haftalar,aylar Birbiri ardına koşan zalim yıllar. Ömrümüzü nasıl da çaldılar?  Sevdiklerimizi hep elden aldılar. Her gü...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dunku-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiracıyım', 'kiraciyim-seyfettin-bilal-ozluk-bltyf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman ve niye geldim bu dünyaya diye düşünürken

Yine sen geldin zamansız biçare aklıma

Seyrettim son defa duvardaki resmine

Hem ağladım hemde isyan ettim

Sessizce gecenin uçsuz karanlığında...

Resmini indirdim duvardan gizlice

Ve utandım duvarlardan

Bir parça koptu zavallı beynimden

Ağladım sanki duvarlar ağladı benimle...

Neden üç günlük dünyada acılarla yaşamak var,

Varolmak için yok olmak mı gerekir

Tezatlar dünyasında...

Kiramı öderim dünya yapma bunu bana

İstemiyorsan üç gün huzurlu yaşamamı

Boşaltırım evimi kiracıyım nasıl olsa...

Yalvarıyorum bana biraz zaman

Sende üstüme gelme vakitsiz be kahpe dünya...

Yaşamaktı hevesim

Birde duvardaki o kadın,

Şimdi boşaltacağım içimdeki sessiz isyanı...

Ve duvardaki resim indi yere

Duygularımı bilen duvarlar benimle ağladı...

Ağlama duvar sen ne anlarsın diyemiyorum

Çünki seninle paylaştım yalnızlığımı hep

Bırak dursun deme o resim yerinde

Gidiyorum çünki kiracıydım  bu dünya da

Resimler kalmasın başkalarına

Ben yok oldum

Onlarda benimle birlikte gelsin

Kefenime sarılsın.

Dünya artık kiracılığım bitti

Yeni ev aldım gidiyorum...', 'Ne zaman ve niye geldim bu dünyaya diye düşünürken Yine sen geldin zamansız biçare aklıma Seyrettim son defa duvardaki resmine Hem ağladım h...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kiraciyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle bi şeydir sevgi....', 'boyle-bi-seydir-sevgi-hasan-esat-heptunali-fdlbo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nasıl istiyorsan öyle yaşa hayatı..

ama...

sen olarak yaşa…

her nasıl hissediyorsan öyle işte...

sıyrılıp tüm yaşanmışlıklarından

uç...uçabildiğince

özgür bırak düşüncelerini…

kendini….

ayrıl etten kemikten 

bir ruh ol gök yüzünde sadece

özgürce süzülen...

ve...

dilediğin an dön bana

ya da hiç dönme...

gülümse sadece

kaybolurken gecenin içinde

verdim...

almasam ne olur ki..

sevdim ben seni....', 'nasıl istiyorsan öyle yaşa hayatı.. ama... sen olarak yaşa… her nasıl hissediyorsan öyle işte... sıyrılıp tüm yaşanmışlıklarından uç...uçabi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/boyle-bi-seydir-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine 10 Kasım', 'yine-10-kasim-alper-kuruk-8aqnv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana ne yazsam ki ben 

Toprağın kadar yazılanın var...

Şu  küçücük kuş,

Şu dağ,şu taş,

Şu Türk,şu beşer,

Kemâl''im,Ata''m,Mustafa''m diye ağlar.

10 Kasım ah 10 Kasım...

İnan Ata''m bu ağaç

Yazın yeşil yapraklıydı.

10 Kasımı duydu da bir kez

Yapraklarını döktü senin için.

Sakarya böyle bulanık akmazdı

O şerefli 22 gününden

Bugüne gelinceyedek.

İnan Ata''m duydu bir kere

Bir kere daha duydu 10 Kasımı

Eğilmez başlılar düşük başla ağlarken.

Uykusuzluk değil gözümüzü yaşartan

Tek göz olmuş Millet,tek göz olmuş ağlıyor Vatan.

Hıçkırıklar sarmış koca dünyayı

Bir Koca Türk ki âlemi içten içten ağlatan

Sensin,sensin,sensin yine Ata''m.

Ah yine o 10 Kasım

Biz bir kere daha öldük

Sen bir kere daha dirildin tüm heybetinle,

Ruh ruh parçalandın

Ve girdin benliğimize bu ölüm günümüzde 

İki ruhlu oluverdik hepimiz

Ruhumuzun biri:TÜRK

Biri:KEMAL ATATÜRK.

Ata''m ya rüyalarımda gördüm seni

Ya Koca Tepedeki resminde seyrettim seni.

Koca Tepedeki o resminde 

Anlıyorum,seni göremiyeceklerin kaderini düşündüğünü...

Onlar da seni düşünürler Ata''m

Yalnız 10 Kasımda değil

Her akıla gelişte....

Seni koynunda ısıtan toprak

Allah''ına ne şükürler ederdir toprak olduğuna 

Ve üstünde yürüyen Türk''ün

Allah''a şükrederiz yüzü ak

Ölümsüzlerin uykusu gibi...

10 Kasım ah 10 Kasım 

Neden dolandın dilime 

Tutuştu dilim,ağzım.

Hıçkırıksız çıksa avazım

Bağır bağır bağırırım,

Kemâl''im,Mustafa''m,Ata''m...

Sen yat uykularımın tümü senin

Yalnız,toprağından toprağıma 

Bir zerrecik maya katam...', 'Sana ne yazsam ki ben  Toprağın kadar yazılanın var... Şu  küçücük kuş, Şu dağ,şu taş, Şu Türk,şu beşer, Kemâl''im,Ata''m,Mustafa''m diye ağlar...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/yine-10-kasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah be ciğerim...', 'ah-be-cigerim-hasan-esat-heptunali-cez8k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah be ciğerim …

Sen bilmezsin bu sevdayı

Ne menem bi şeydir…

Kodu mu oturtur şerefsizim…

Rakı şişelerindeki balıklara öykünür için…

Akar gidersin

Ah be ciğerim

Oturmuş...akıp gidiyorum… 

Sen bilemezsin…', 'Ah be ciğerim … Sen bilmezsin bu sevdayı Ne menem bi şeydir… Kodu mu oturtur şerefsizim… Rakı şişelerindeki balıklara öykünür için… Akar gid...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ah-be-cigerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '///*/// Sevgimle Kal Canım ///*///', 'sevgimle-kal-canim-i-brahim-dikmen-2-yrlhl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba yakamoz gözlüm

yüreği sevgi yüklü

yağmurun asi kızı

düşlerimin kadını merhaba

Bu gün öyle heyecanlıydım

öyle bir çıkmazdaydım

bilemezsin

yine karşımdaydın

nefes kadar yakındın

lakin yıldızlar kadar

uzaktın

Oysa ben

ne hayaller kurmuştum

sana sarılıp kollarıma alacaktım

al yanaklarına buseler

dudaklarına kor bırakacaktım

ellerim saçlarında dolaşacaktı

küçük bir kızı okşar gibi

Lakin yapamadım bitanem

hani sana demiştim ya

bir nefes kadar yakınsın ama

yıldızlar kadar uzaksın diye

bu gün işte o anı yaşadım

Ellerini avuçlarımda hapsedememek

kollarımın arasında saramamak seni

üşüyen yüreğini ısıtamamak

ve saçlarını okşayamamak

öyle zoruma gittiki bilemezsin

Veda anı bile hüzünlüydü benim için

al yanaklarına öpücük konduramadım

teninin sıcaklığını hissedemedim bile

ve sadece tutsak kaldı gözlerim

seni bıraktığım yerde

ya sen bebeğim sen de hüznü tattın mı

Sevgimle kal canım.

20/10/2005', 'Merhaba yakamoz gözlüm yüreği sevgi yüklü yağmurun asi kızı düşlerimin kadını merhaba Bu gün öyle heyecanlıydım öyle bir çıkmazdaydım bileme...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevgimle-kal-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Teselli', 'teselli-canan-palabiyik-gzg0q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hadi be dostum boş ver,

Gir koluma iki tek atalım,

Göreceksin; 

Ne savaş kalacak, ne açlık,

Ne ekmek parası,

Nede evdekinin dırdırı, 

Yarın sabah mı? 

Of hadi dostum uzun etme,

Vuralım şişenin dibine...

(20 Ekim 2005 / İstanbul)', 'Hadi be dostum boş ver, Gir koluma iki tek atalım, Göreceksin;  Ne savaş kalacak, ne açlık, Ne ekmek parası, Nede evdekinin dırdırı,  Yarın ...', ARRAY['Türk Edebiyatı','Şiir','Canan Palabıyık']::text[], 8.5, '{"poet":"Canan Palabıyık","poet_slug":"canan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/teselli-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem', 'kalem-alper-kuruk-r3v0p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalemin dost olabileceğini 

Bilmezdim bu kadar,

Her dediğimi dinledi bir bir 

Usanmadı

Ama biraz boşboğazlığı var

Sır tutmuyor hiç,

Söylediklerimin hepsini kâğıda

Anlatmaktan utanmadı...', 'Kalemin dost olabileceğini  Bilmezdim bu kadar, Her dediğimi dinledi bir bir  Usanmadı Ama biraz boşboğazlığı var Sır tutmuyor hiç, Söyledik...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kalem-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papağan', 'papagan-alper-kuruk-99f3k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk insanı bir papağan

Aynı şeyi söyler her an.

Dilinde sevgilinin ismi

Gözünde sevgilinin cismi

Sevgiliye dönüşmüş artık

Kalbindeki kan.

Aşk insanı bir papağan

Ezberlemiş tek kelime; 

Onu söyler güler

Onu söyler ağlar:

Yâr,yâr,yâr...', 'Aşk insanı bir papağan Aynı şeyi söyler her an. Dilinde sevgilinin ismi Gözünde sevgilinin cismi Sevgiliye dönüşmüş artık Kalbindeki kan. Aş...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/papagan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Uyurken', 'ben-uyurken-volkan-yoruc-mrguv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yattım uykulara

Uzandığım yerden kaybolur oldum

Yürüdümde gittim yalnızlıklar yolunda

Ve ümitlerimi bir meşe dibine ektim düşler ormanında

Hor görmeden sevdim

Hor görülmeden geçtim sevda yolunda

Hor nedir bilmeden tuttum yıldızları dilekler gibi

Bir düş içinde saklı kaldım bu uğurda

Toza dumana sarmalanmadan yaşadım

Düş, rüya yada hülya

Değmeden kimsenin ahına

Kendi düşlerimi pembelere boyadım umarsızca

Yattım uykulara

Yattım, kalkmadan hayallerimi süsledim yıldızlarla

Bir yanda ay''dan bir sima

Bir yana da çizdim güneşten bir pencere

Ve saldım kendimi düşler ormanında sevdanın kollarına', 'Yattım uykulara Uzandığım yerden kaybolur oldum Yürüdümde gittim yalnızlıklar yolunda Ve ümitlerimi bir meşe dibine ektim düşler ormanında H...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-uyurken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan!', 'uyan-abdurrahim-karakoc-b03zq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uyu uyu yat uyu masallarını bırak

Uyan sen, karış karış toprakları uyandır.

Çiçek açsın her taraf sizinle revnak revnak

Uyan çocuğum, çalış, yaprakları uyandır.', 'Uyu uyu yat uyu masallarını bırak Uyan sen, karış karış toprakları uyandır. Çiçek açsın her taraf sizinle revnak revnak Uyan çocuğum, çalış,...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uyan-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Sevemedin', 'sen-beni-sevemedin-erhan-bozkurt-477n0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzelliğindi aklıma çizdiğim,

Yırtık terliklerimle voltalarken.

Aradım seni yarım kalmış sigaralarda

Dumanın arasında elimden kayboldun.

Ama hiç gün saymadım,

Ne aşıklar gördüm biri on sayan

Ama ben saymadım.

Ben o delikte karşılığı olmayan

Aşkı yaşadım.

Beni sen hiç mi sevmedin

Yarını olmayan günlerde yaşattın

Mutluluğun ayazlarından kıskandın.

Ben sevdim ama sevilmedim.', 'Güzelliğindi aklıma çizdiğim, Yırtık terliklerimle voltalarken. Aradım seni yarım kalmış sigaralarda Dumanın arasında elimden kayboldun. Ama...', ARRAY['Türk Edebiyatı','Şiir','Erhan Bozkurt']::text[], 8.5, '{"poet":"Erhan Bozkurt","poet_slug":"erhan-bozkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-beni-sevemedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Aşk Bu', 'bi-ask-bu-mehme-arslan-a5bst', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'teslim ol çağrısına 

ateşle karşılık veren bi aşk bu

meskun mahalde karışıklıklar çıkaran

hiçbi vekilin güvenoyu vermediği

üstelik referandumda çoğunluğu

hayır çıkan bi aşk bu

cumhurbaşkanının veto ettiği

ve hiçbi değişiklik yapılmadan

tekrar gönderilen bi aşk bu

en üst mahkemenin karar verdiği

ve temyizi olmayan bi aşk bu

plakaya yazılan ve 

adrese gönderilen bi aşk bu

itiraz hakkı saklı

tutuklu ve hükümlü arasındaki 

farkı bilmeyen bi aşk bu

birinin beraat diğerinin tahliye edildiği

eş durumundan büyük şehirlerde 

görevli bi aşk bu

düzmece evliliklere neden olan

ve adı mahfuz kutsallığını 

unutttuğum bi aşk bu

recep, şaban, ramazan', 'teslim ol çağrısına  ateşle karşılık veren bi aşk bu meskun mahalde karışıklıklar çıkaran hiçbi vekilin güvenoyu vermediği üstelik referandu...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bi-ask-bu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Bahardı Kendi Yurdunda-', 'bahardi-kendi-yurdunda-ercan-cengiz-ht108', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitirmenin hıncındandır bunca zindan

Sürgünler, katliamlar ardında

Barbarlıklarıyla bilindiler

Karanlıktan beslenenler.

Bu bahar Alişer''den gelir ülkeye.

Kor ateşte duman gökçüle doğru,

Kuş cıvıltıları eşlik ederken inleyişine

Ve vakitsizce sararıp düşen meşe yaprağı

Kimbilir, ki sürgünlerden haber verirdi.

Çocuklar ya hiç bilmediler oyunu

Ya da patikalara bıraktılar çocukluğunu

Ve el bombasını oyuncak bilip

Parçalananları katmazsan eğer,

Diğerleri büyürler,

Büyüdüler ezgili yüreklerde...

Damar damar toprağın derinliğinde

Ateşte kavrulan bir direnç gülü,

Acı bir gülümsemede...

Meşe ağacı bu

Seyit Rıza''dan torunlarına bağdaş olmuş

Ki kırılır da eğilmezdi.

Bir direniş destanı, bedeninde kor ateşi taşır

Duman yükselir, buruşur, kızıllaşırdı

Aşiret boyu kururdu fidan,

Sürülürdü toprağından ırak

Kabile kabile...

Yoğrulurdu külü

Potin diplerinde pul pul

Rüzgara savrulurdu

Soysuza, hal bilmeze inatla

Sığmazdı ki bir kaba

Meşe ağacı.

Asiliğiydi dünden bugüne

Ve ülke, güneşin renklerini alırken üstüne

Vurmaya gelirdi tayyere, kobra

Ve tepe başlarındaki termal kamera

Kilittir hedefine,

İçindeki potin - kepe bürünü yoksun

Komutla yatıp kalkardı

Sorgusuzca...

Ve gölgemde büyüyen yılan asıl

Ve de keklik soyu...

Kimbilirdi ki,

Bunca acıdan sonra...

Ellerinin nasırı, kamburu ile ora insanı 

Daha çok

Yüz çizgilerinde anlatırdı kendini

Ve patikada yürürcesine yürürdü asfaltta.

Ve de dili,

Giysisi,

Hele tütün sarması

Ele verirdi kendini metropol sokaklarında.

Emeğini çalmaya gelenler yarış içindedirler

Eli kırılası yoksullukta

Emeğini elin işine kaptırıp düşürürdü kendini.

İşgal edilmiş bir ülke

Kökü toprağın derinliğinde 

Saklanırdı

Budayıp uzaklara attılar dallarını

Atamadıklarını ateşe verdiler

Bir tek meşe

Yüklendi damarlarına...

Elin kapısına ekmek için

Kendi yurdunda yurtsuz

Ve bir de çocuğunun hasreti ki

Asıl boynuna binen...

Bir tek aş için

Ölmek vardı hücre hücre

Kendine yabancılaşma

Kolay çalınırdı 

Açlığın böylesi

Ve nice şatavatlı sözlerden sonra asıl

Cayır cayır tutuşuncaya

Toprağın kalbi...

Yoktu bir allahın kulu,

Yok.

Gözbebeği insanın

Gözbebeği

Kendinindir

Kolay kolay girmez ayak altına

Ve ayrı değildir bedenden

Öyle kendini tüketen göz ise

Maketlerde olurdu ancak...

Ellerim ellerinden ağırdır beğefendi

Yanındaki kadının midesi de bulanır

Bilmez miyim

Rengi

Kokusu karışmış insan maketi

Horlanırım elbet

Ellerim horlanır

Emeğim horlanır

Rengim horlanır

Dilim horlanır...

Sığamam bir yerlere

Sığamam

Ülkemin toprağından gayrı.

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)       

Vura Vura Düşülmez Bu Toprak 

Bu mevsimde vadilerin sesi gürleşirdi

Bir gerillanın kopan dizkapağında

İrkildiğinde meşenin damarı 

İki dalını verirdi, sedye için...

Yaşanmazlıklar

Tarihin karanlığında kalırdı

Meşe ağacı, su, güneş ve ezgiler

İç içe gireli derin vadilerde

Ve kıymet bileli Munzur,

Fırat, Dicle, Ararat''ın eteği...

Çağlayandı yataktan yatağa

Nehirlere

Uzayıp giderdi suya değen kan

Kaçışırdı çiyanlar bu toprağın sesinden.

Miladı yazan günden öncesinedir

Soysuzlara yenik düşmeler,

Laç Deresi,

Ali Boğazı,

Kutu Deresi...

Karış karış değmiş toprağa

İnsan kanı 

Ayağa kalkmanın bedeli olmuş 

Bu kan

Çığlık,

Bu diriliş

Milad olmuş diğer yandan.

Dağlar oyulmuş dağlar

Yüreğimi saran ezgilerle

Vietnam tünellerinden öte

Gözden göze

Beyinden beyine

Elden ele

Taşınırken yarınlara

Yıldızları toplarcasına

Patikalar gidilirdi.

Dağlar oyulmuş dağlar

Asırların biriktirdiği ezgilerle

Ülkenin bir ucundan diğerine

Destanlar yazılıyor destanlar

Kimsenin tanımadığı ellerde.

Vura vura düşülmezdi toprak elbet

Dövmekle bu toprağın ezgilerini 

Tükenmezdi

Paramparça olmuş bedenlerde

Nice ölümler yenilirdi

Yükselirdi güneşe bu toprağın ezgisi

Kurtarmak için onurunu.

Bir başka mevsime dururdu toprağın ezgileri

Her şafak vaktinde vurulurken meşe ağacına

Bir başka mevsim doğardı doğacında

Mevsim bozgunlarına karşı.

İnsan maketleri türerdi nice topraklar üzerinde

Yaşadığımızdan öte

Çarkın kolları gibi

Yenik de düşülürdü karanlığa

Son damla kanda

Daha da gür 

Filizlenirdi de meşe ağacı

Kendi damarından.

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)      

Koparılan Dalın Kökleri 

Gidilecek bu yol 

Aşılacak bu dağlar

Çarpışa çarpışa zalimle

Çarkın dişlilerinde kalan ezgilerle.

Ülkede, Munzur''un eteğinde

Dere yatakları,

Vadiler

Seyreltili tepeler içinde...

Binlercesini barındırır bu dağlar

Çok şey var ardında heval 

Çok şeyler...

Otuzsekiz''den de öncedir

Alıkonan toprağın metropol ayağı.

Toros''larda ırgat,

Toros''larda hamal,

Çukurova''da pamuk toplayıcıları

Dört bir yanında Anadolu''nun

Modern köleleri olmuş memur,

Varoşlarda köylü...

Avrupa''da temizlikçi...

Fabrika işçileri

Sokaklarında ise süpürgecidirler.

Her dalı bugün 

Her dalı kökünü aramaktadır.

Asfaltlı yollardan patikaya düşer ayağı

Yitik kalbin ezgisiyle

Dağlarına ülkenin insanı 

Tepelerine girmiş oyuk oyuk

Mevzide

Siperde

Patikalarda

Hain pusuda

Çarpışmalarda

Ölümüne

Zindan direnişlerinde

Yeni günü 

Baharı yaratan 

Ceylandırlar...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)     

Sesin Duyurmaz mı Çektiğin Acıları 

Zaman prangalara vurulmuştu

Acıya durulurdu

Kamburun tokuşurdu eldeki kadehle

Acın tutuşurdu tutuşmasına

Nedendir, bilinmezdi de

Ayağının sarp yollara düşmesi.

Konuşamaman zamana kurulmuştu

Uzun uzun kahır çekilirdi

Ayaklarının üzerinde taşıdığın beden

Karşı duramazdı zalime

Ürperirdi insanoğlu.

Karanlığa yükselirdi ezeli yüklü komut

Dirhem dirhem kazınırdı bedenin,

Sesin duyurmazdı acını

Boğuktu

Bitmezdi, tükenmezdi açlığın

Çilen bitmezdi...

Köy köy

Mahalle mahalle

Ev ev

Sokak sokak

Gizemidir devranın kendi

Bundandı karanlıkta boy vermesi...

Midede tutuşurdu kadeh

Açlık

Acı içinde sürüklenirdi özü

Demiyorsan bir süre daha eğer

Al kadehi vur yere...

Zaman prangalara vurulmuştu

Karanlıklar içinde acının gizemi

Beyinlere oturtulmuş bir yelkovan

Eldeki kadehle

Tokuşurdu emeğin

Çaresizliğindir

Yükündür

Kamburundur.

Ayağın sarp yollara düşerdi

Konuşmamanın

Konuşamamanın ölçütü

Duyuramadığın

Çığlığındı

Karanlığın gizemi...

Katledilen doğacındı damar damar

Yayılmış

Acıların bileşkesi,

Tarihin o acılardadır senin

Sallanır

Kazınır dirhem dirhem.

Konuşamaman zamana kurulmuştu

Zaman prangalara vurulmuştu

Ürperirim ki 

Boğuk sesin duyurmaz çileni

Acını 

Açlığını gidermez.

Karanlığın gölgesi yükselirdi

Ağırdır

Vurunca da sırtından vurur

Uyan

Uyan ki

Kendinin olman için...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)    

Toprağa Sarısını Verirken Üşürdü 

Karanlığın dehşetidir, çilenin pençesi

Kara bir bulut yapışırdı

Toprağın yüzüne.

Çaresizlikti köylünün elinde

Babasından kalan miras

Açarak ellerini allaha yakarırdı.

Yağmur yağacaktı 

Yağmur yağacaktı

Yağmur,

Serpilen kımıldı oysa

Deli bir rüzgarla

Çoktan sarmaladı ekini.

Gün hesabındaydı hamile bir kadın

İlk bebeğine

Düşüyorken aydan

Gün be gün

Bir yaprak daha duvar takviminden

Koparırdı akşam vakti.

Zamansız tutulut sancıya

Doğuramazsa Anası gibi

Ana olamamak vardı,

Beyninde kurt kemiriği

Benzi soluk

Karıncalanırdı teni...

Titreşimi neydi yarı kentlinin

Pamuk üretirdi,

Üşürdü ekin başakları

Sarısını verirken toprağa.

Kaplumbağa sabrıyla bir demirci

Yapardı sipariş gelen orağı,

Hava karardığında ikindi vaktiydi

Bedenini saran karanlık,

Sırtından girmişti

Soğurdu bedeni

Kara bulutun ardında...

İklimi değildi bu ülkenin,

Bu coğrafyanın iklimi değil

Bir yanda düşünürdü 

Ak saçınan

Kor ateşe damlardı 

Soğumuş teri...

Bir ömür gelip geçerdi

İnadına

Çile yüklenirdi sanki,

Kendi toprağında ağzı dolu

Gülemezdi insan...

Bir ömür geçerdi

Babadan kalma miras

Bir adım büyütmez,

Bir gün götürmezdi

Babadan bilme yaşardı 

Bir ömür

Sınır geçmez

Yol geçmezdi

Çilesini yüklenirken omuzlarına...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)   

Kaçıncı Bin Hanesindeydin Çocuk

Kirlenmiş bir atmosfer içinde

Çarkın dişlerinde boy verirken birileri

Güneş göremezdi ellerini.

Sekizinde bir çocuksun sen

Küçücük bir ışıktan yola düşmüş

Küçük adımlarla,

Sen ki çarkın dişlerinde boy verirken

Kendinden uzaktın.

Ve çocuk senden uzaktı,

Köşe taşı olmayacaktı karanlığa

Bekçiliğine de sermadedarların

Bakmazdı kirletilmiş ekmeğe

Vermezdi de emeğini.

Kır çiçeği olmak 

Ve solumak için insanca...

Küçücük bir ışıktan yola girmişti çocuk.

Toprak yanar

Vadilere uzanırdı şarkısı

İnsanoğlu

Ayağa kalkardı

Kızıl kayalarda

Sözün bedeli candı

Ateşin şarkısı dillerde

Yaprak dökümünde

Tomurcuğun ilk yaprağı daha

Kolay düşerdi toprağa.

İnsan suretlerinin adı saklı

Pazarlık ettiler üstüne

Sessizce

Karanlıkta dolaşırken 

Bu çarkın dişlerinde.

Kaçıncı bin hanesinden çocuk

Bulurdu resmini 

Ve tam kafanın üstünden 

Bir daire çizerdi kırmızı kalemle.

Çarkın dişlisi böyle beslenirdi

Efendisi gibi

Toprak yanardı çocuk senin adına

Şarkısı uzanırdı yollara.

Kır çiçeğinin sırtındaydı ölüm

Bundandır dönmezdi yüzünü

Dönen çarka.

Yağmurun gördüğü tohumdu

Yanan toprağın yüzünde dolaşan

Damlalar üzerinden düşerdi

Çocukların üstüne

Güneş görürdü çocuklar.

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)  

Karanlığın Baharı Yoktur 

Alınteri karanfil sıcaklığında

Suya da

Balığa da vurgun

Umut

Acı içinde doğarken bebek

Boğarcasına mazluk yüzü

Kara değer yüzüne.

Karanfil sıcaklığında doğa

Herşeye

Herşeye rağmen

Serpilirdi yollara gözbebeğinin çığlığı

Suya da balığa da vurgun.

Kara akar gözlerine

Döngülü uykuda

Toprak çoraktı

Bulanık sudaydı balık

Tuzlu suda

Tatlı sudaydı balık

Her şeye rağmen

Yollardaydı,

De ki şafağın bir yerinde...

Sular berraklaşırdı.

Alınteri karanfil sıcaklığında

Suya da balığa da vurgun

Gün içinde tarih

Gün içinde tarihin mirası

Sabırla beklerken toprak

İki mevsimini vermedi karaya,

Baharı yoktu karanlığın

Yazı yoktu.

Geldiler,

Geldiler ayrı ayrı hamurdan

Yoğruldular yumruk yumruk

Bir bilip acılarını

Sevinçlerini

Orta yere kattılar

Alınterini

Paylaştılar.

Ayrı ayrı hamurdan gelip

Yoğruldular

Çarkın dişlilerinden kopanlar

Bir başka mevsimde patikalarda

Sıraçtılar

Gecenin melekleri...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap) 

Kır Çiçeklerinin Aşkı Büyük Olur 

Acıyla işlenmiş yaşam

Sevdalıydı ölesiye

Bilmediği yüzlerin yarınlarına

Yüreğinin sıcaklığını verirdi.

Dağlarda kır çiçekleri.

Ot bitmezdi

Dağlar beyaza kaplanmış,

Kış kıyametidir

Ölüm sessiz olur.

Dağlarda kır çiçekleri

Çığlık içinde

Karanlık çatlarken çığlıklarına

Sevilirdi kır çiçekleri,

Her defasında

Yenilirken ölüm

Gün içinde tarih

Kazınırdı.

Pusular atılır pusular

Patikalara pusular

Yürekleri parça parça 

Yayılırdı

Ağrına giderdi toprağın vurulması,

Olmazın yasası kırılırdı

Gün içinde 

Toprağın gülüşünde...

Çatırdıyordu altından üstünden

Karanlık çatırdıyordu

Bin yılların hükmü ile donatılmış karanlık 

Çatırdıyordu.

Kılık değiştirse de ölüm mangası.

Şafak sabırsızdı

Şafak erken gelirdi dağlara

Dağlar

İnsafına gelmezdi zalimin

Ölüme ölümcül 

Şafaklar karşılanırdı

Vururdu kır çiçeklerinin sancısı.

Bilmediği yüzlerin yarınlarına

Yüreğinin sıcaklığıyla

Dağlarda kır çiçekleri.

Yaşamak demekti kır çiçeği

Çalışmak demekti,

Alanı daralırdı karanlığın

Lokması küçülürdü efendilerinin.

Filizlenir gün be gün 

Şafaklayanların mevsimi

Doğardı yeniden

Yeniden doğardı.

Karanlık çatlıyordu karanlık 

Altından üstünden

Kolay değildi

Olmayacaktı da

Kolayın adına hiç bir şey...

Dağlarda kır çiçekleri

Damar damar

Gün içinde

Yaşamsaldı.

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)

Bu Senin Düğünün mü Oğul 

Gün aşılırdı,

Gün dağların doruklarında.

Bense uzaklardayım

Gece akar üstüme.

Bir Anaydım bir Ana

Yüreğimde taş değil

Yürek taşırım yürek

Yüreğim kıvratıyor beni,

Alacaklar yine elimden

Vakti gecede

Kalleşce alacaklar

Dokunmadan kapının ziline...

Akan kandır, kan...

Yetişemiyorum gözlerimin gördüğüne.

Bırakmadım oğul bir damla gözyaşını

Bırakmadım yere,

Aktı

Yüreğime serpilircesine aktı,

Kinimi bilendi de aktı oğul

Öfkemi bilendi...

Gün aşılırdı dağların doruklarında

Bense uzaklardayım

Sıcaklığını saramadan doya doya

Bir Ana gibi

Vakti gecede çaldılar elimden

Alçakca çaldılar

Kır çiçeklerine sordum oğul,

Tililiye durdum oğul

Sevdiklerinin tümü

Aklanmış sakalları

Gelinlikleri ile

Kirlenmiş sırt çantaları,

Oyuncakları ile 

Koluma girdiler oğul.

Senin düğünün oğul

Bu da senin düğünün olsun

Senin düğünün diyorum onlara

Zılgıtlar içinde

Zılgıtlar içindeyim oğul...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap) 

Dirilirdi Yeniden Yeniden 

Fırtına kopardı,

Kar yağardı

Ura bağlanan insan hayatında.

Çark dönerdi 

Dişlerinin arasında

Yol alırdı karanlığın hükmü.

Bozguncunun mevsiminde

Dal düşerdi gövdesinden.

Serine kurulurdu devran

Karanlıkta

Kalan bir gül.

Dayanırdı,

Acıya dayanırdı 

Toprağın ezgisi

Rengini vermeden karaya

Toprağa düşerdi 

Gelecek için 

Yolun orta yerinde

Dirilirdi.', 'Bitirmenin hıncındandır bunca zindan Sürgünler, katliamlar ardında Barbarlıklarıyla bilindiler Karanlıktan beslenenler. Bu bahar Alişer''den ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":532,"source_url":"https://www.antoloji.com/bahardi-kendi-yurdunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahve', 'kahve-yasemin-sezer-tulgar-41suc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kahvaltı sonrası buruk..

Şekersiz kahve, acı olurmuş

Unutmuşum.

Elim gidiyor iki fincana

Tekiyle dönüyor avucuma...

Harlı ateşte pişen

Köpürmezmiş

Unutmuşum.

İçiyorum yana yana..

Soruyorum

Son yudumda; 

Kimin eli şekerli? 

Şekerin kim bundan sonra? 

09.07.2005', 'Kahvaltı sonrası buruk.. Şekersiz kahve, acı olurmuş Unutmuşum. Elim gidiyor iki fincana Tekiyle dönüyor avucuma... Harlı ateşte pişen Köpür...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kahve-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-yasemin-sezer-tulgar-n5zzf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hasreti bölüyorum

bir parça yüzüme

bir parça yüzüne

bulamacı sıvıyorum

________saklıyorum

vuslatımın adını

''Sen'' koyduğum günüme...

06 09 2005', 'hasreti bölüyorum bir parça yüzüme bir parça yüzüne bulamacı sıvıyorum ________saklıyorum vuslatımın adını ''Sen'' koyduğum günüme... 06 09 20...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vuslat-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yerim Yarım', 'yerim-yarim-yasemin-sezer-tulgar-45gme', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ruhunla uyandığım beden

Bunca aradan sonra

Bu özlem

Anlamıyorum

Neden? 

Damarlarımın içi sızlıyor

Kan akmıyor

Kalp de durmuyor

Sızım sözümde

Acım yüzümde

Yamalı yorgunum

Dolanmış ara yollar

Çıkışları hep sensiz şehir

Kaçak yolcuyum

Kaçtığımdan değil

Düşman sevişler

Sevişmeler korkunç

Bunca aradan sonra

Anlıyorum

Tenim yarım

Yerim yarım

Benim yerim 

Senin yanın

20.08.2005', 'Ruhunla uyandığım beden Bunca aradan sonra Bu özlem Anlamıyorum Neden?  Damarlarımın içi sızlıyor Kan akmıyor Kalp de durmuyor Sızım sözümde...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yerim-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akif''im', 'akif-im-i-brahim-kilinc-cvaid', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Diyordun ya ''hangi çılgın şaşarım

Vuracakmış Türk''e zincir'' Akif''im

Ne yazık ki, o günleri yaşarım

İçerden vurdular zincir Akif''im

Bizi Avrupa''ya köle yaptılar 

Gidip gelip kapısında yattılar

Vatanımın toprağını sattılar

Kime oy verdiysek, kime Akif''im

Hainlere ada tahsis ettiler

Teröristle pazarlığa gittiler

Bu millete bilsen neler ettiler

Kime oy verdiysek, kime Akif''im

Kerkürk Kürde Kıbrıs Rum''a hediye

Telâfer''de sorma durum ne diye

İncirlik''ten bomba gider hediye

Kime oy verdiysek, kime Akif''im

Böyle gitmez elbet devran her zaman

Düşecek iş başa bilmem ne zaman

Tüm hesaplar sorulacak o zaman

Kime oy verdiysek, kime Akif''im', 'Diyordun ya ''hangi çılgın şaşarım Vuracakmış Türk''e zincir'' Akif''im Ne yazık ki, o günleri yaşarım İçerden vurdular zincir Akif''im Bizi Avru...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akif-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahane', 'bahane-yasemin-sezer-tulgar-bsp4t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sucularla eskici

Bağırdıkça pencerene

Su alır, gazete satardım

Aralanınca perden

Tebessüme

Bahanemdin... 

Evcil törenlerin mahallesinde

Sakinleriydik burnu büyük

Kaçarcasına koşardık işimize

Bakkal kapısında sıkıştık bir gün

Zayıfladım

Bahanemdin...

Sular kesildi tam 5 gün

Sinekler sardı muslukları

Alt sokağın çeşmesinde

Sıralı kovalar su peşinde

5.nin yerini çaldım

Arkandaydım

Hırsızım

Bahanemdin...

Gitmiyordu ayaklarım

Sıkıntı düştü bedene

Çoklu plaklarmış 

Çok korktum

Yakarmadım 

Bahanemdin...

Mahalle sarmıyor mor salkımları

Çağrılardan uzak kaldı baharlarım

Güzel dizeler çıksın istedim

Bahanesizdim olmadı

Kokmuyor çiçeğin

Geçmiş olsun notunda saklı

Vicdanına

Bahanendim... 

Mayıs 2005', 'Sucularla eskici Bağırdıkça pencerene Su alır, gazete satardım Aralanınca perden Tebessüme Bahanemdin...  Evcil törenlerin mahallesinde Saki...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bahane-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus', 'sus-yasemin-sezer-tulgar-aeao6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sus

Anlatma

/sıkıldım

Dur

Bu son öpüş

/uzaklaş

Git

Çok mutluyum

/dönme asla

Diyemedim

/Hiç

Bile bile lades

Aklımda idi

/aldım çektim

Yenildim

Zaferin

/zaferim 

Sus 

Bu akıllı işi değil

Selamına 5 takla

Yolum yokuş

Alkışlama

/Oyun bitti

Yalan 

Koca yalan

İnandım sandık

İnanmadım 

Hiç inanmadım

.

.

.

.

.

.

Ne olur dön! 



Ağustos 2005', 'Sus Anlatma /sıkıldım Dur Bu son öpüş /uzaklaş Git Çok mutluyum /dönme asla Diyemedim /Hiç Bile bile lades Aklımda idi /aldım çektim Yenildi...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sus-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel...', 'guzel-hasan-dogan-g1q1y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Girdim denize,

Deniz rüyalarıma girmesin diye...

Tuzlu suyu yutunca karıştı aklım,

Sonra bir an boğuldum sandım,

Tuzgölünün ötesindeki güzelin gözlerinde...

                        

                                                    16.08.2005', 'Girdim denize, Deniz rüyalarıma girmesin diye... Tuzlu suyu yutunca karıştı aklım, Sonra bir an boğuldum sandım, Tuzgölünün ötesindeki güzel...', ARRAY['Türk Edebiyatı','Şiir','Hasan Doğan']::text[], 8.5, '{"poet":"Hasan Doğan","poet_slug":"hasan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/guzel-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tespih', 'tespih-yasemin-sezer-tulgar-he3gt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Prangalar kolyem

Gülen/nadide sabahların

Tespih niyetine

01.09.2005', 'Prangalar kolyem Gülen/nadide sabahların Tespih niyetine 01.09.2005...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tespih-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '8 Mart', '8-mart-zati-erbas-jjytb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüzünü duvara dön 

ve 

dur.

düşün sevdiğin kadının yüzünü

ve çiz.

gülümse; 

başaramadın.

kaç kişi başardı.

hiç kimse.

votka içen

..................aşık olan 

aldatan 

Nazımdan başka.', 'Yüzünü duvara dön  ve  dur. düşün sevdiğin kadının yüzünü ve çiz. gülümse;  başaramadın. kaç kişi başardı. hiç kimse. votka içen ..............', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/8-mart-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Rapunzel, Dağ, Deniz ve Olasılık Üzerine Birkaç Mülahaza', 'rapunzel-dag-deniz-ve-olasilik-uzerine-birkac-mulahaza-mehme-arslan-nzxzx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kaç prensi odasına almıştır

beline kada inen saçlarıyla

kim bilir kaç denizci gözlerinde boğuldu

fırtınalı zamanlarda

kaç dağcının planında vardır

burnundaki zirveye ulaşmak

kaçıncı dereceden denklem hesaplar

yüzündeki sadeliği

ve acaba

bana aşık olma olasılığı var mıdır

olasılık hesaplarında

15/10/2005', 'kaç prensi odasına almıştır beline kada inen saçlarıyla kim bilir kaç denizci gözlerinde boğuldu fırtınalı zamanlarda kaç dağcının planında ...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/rapunzel-dag-deniz-ve-olasilik-uzerine-birkac-mulahaza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvarda Durur', 'duvarda-durur-sait-muharrem-say-mlghy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duvarda durur yüzün

o günden beri

gittiğinden beri

tüm el fenerleri gecenin

seni aydınlatan

kaçamadığım hayalin

yerde durur yüzün basamam

ne kadar haketsede

yanlızlığı bu beden

iskemleyi kurup yaşamın güzelliklerini

bir çırpıda asamam

senden kalan yüzün

gördüğüm göremediğim 

her yer hüzün

hep mi ıslak kalacak 

soğukta titreyen ellerim

duvarda yüzün

akar ayaklarıma

yürüyemem yanlız

senin iniltin dolaştığımız 

sokaklarda

su birikintisinde yüzün

ve gözyaşın gördüğüm

yüzünü gömdüm içime

her yanım hüzün...

Ekim 2005', 'Duvarda durur yüzün o günden beri gittiğinden beri tüm el fenerleri gecenin seni aydınlatan kaçamadığım hayalin yerde durur yüzün basamam ne...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/duvarda-durur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup Sevdiğime Mektuplar', 'mektup-sevdigime-mektuplar-durdane-demirkoparan-iyggh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhabalarla başlayan

Bilmem kaçıncı mektuptayım şimdi

Yokluğunun intikamını alırcasına

Sıralıyorum ardı ardına

Seviyorum seni,

Özlüyorum 

Buralar hala bildiğin gibi

Ben bıraktığın gibi

Senden başkasını hiç düşünmedim

Bakmadım bile

İçimdeki aşk aynı

Saçlarım, onlar uzuyor senin istediğin gibi

Seversin sen uzun, rüzgar da uçuşan saçlarımı

Senin sevdiğin her şeyi

Sanki buradaymışsın gibi yapıyorum

Her an her saniye seni düşünüyorum

Seni beynime kazıyorum

Resimlerimizi ise kalbimin her köşesine

Gece olunca yıldızlara bakıyorum

Sana selam gönderiyorum kutup yıldızıyla

Senin sevdiğin bluzumu giyiyorum geceleri

Sende başka hiç kimse göremesin

Buralara kış geldi

Sen kışı sevmezsin

Hastalanırım diye

Merak etme iyiyim

Sadece üşüyorum 

Bilirsin ısınamam ben, sen olmayınca

Sen olmayınca yatağım da buz kesiyor

Sıcacık yatağımızı, sıcacık tenini özlüyorum

Yapayalnız bu şehirde seninle geçtiğimiz yollarda yürüyorum

Sanki kokun sinmiş bu şehre

Her köşesinde senin kokunu duyuyorum

Şimdilik her şey  yolunda

Senin yokluğun dışında

Meraklanma seni mektupsuz koymam

Son olarak en çok duymak istediğin kelimeleri yazıyorum

Seni kocaman seviyorum bitanem…', 'Merhabalarla başlayan Bilmem kaçıncı mektuptayım şimdi Yokluğunun intikamını alırcasına Sıralıyorum ardı ardına Seviyorum seni, Özlüyorum  B...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/mektup-sevdigime-mektuplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Türk*', 'turk-munevver-duver-upgdv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Masallardan çıkmadım ben, 

Ünü dünyaya nam salmış Türkoğlu Türküm ben 

Nesli dünyaya açılmış, 

Emsali dünyaya gelmemiş.., Türküm ben 

Vatan yoluna başkoymuş 

Vatan toprağıyla yoğrulmuş 

Estergon dan gelmiş Türkoğlu Türküm ben 

Vatana ölmeyi borç bilmiş.., Türküm ben..,

Savaş OĞUZ

NOT: Benim adıma bu şiir''i yazan 

Savaş Oğuza sonsuz teşekkürlerimi bildiririm.', 'Masallardan çıkmadım ben,  Ünü dünyaya nam salmış Türkoğlu Türküm ben  Nesli dünyaya açılmış,  Emsali dünyaya gelmemiş.., Türküm ben  Vatan ...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/turk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengin', 'rengin-rengin-alacaatli-tubs2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ekim yağmurlarında ıslanmak isterim

Toprağın kokusuna bulanmış gibi.

Hazan sarısına boyanmış günlerde

Seni düşünüp umutlanmak isterim.

Kırmızı bir gülün kokusunu duymak isterim

Yarınımda senden bana ulaşmış gibi

Uzak şehrin sokaklarında tükenmiş

Yitik sevdalarda tomurcuklanmak isterim

Düşen ilk karın soğuğunda üşümek isterim

Beyazlığında arınmak sevgimiz gibi

Çıkarsız beklentilerin odağındaki

Yüreğinde gizlice büyümek isterim

Gözlerinin mavisinde kaybolmak isterim

Uçsuz bucaksız denizler gibi

Yelken açmışım yarınsız bugünlere

Zamansız zamanlarda yitmek isterim

Başucumda seni bulmak isterim

Uyanırsam eğer siyah uykulardan

Çıplaklığın bedeninden değil

Geçmişindense sende varolmak isterim

Ve kendi rengini bulmanı isterim

Tükenmiş, yitip gitmiş, yarınsız

Dünlerden öte rengarenk yarınlarda

Ve rengini bulmanı isterim...', 'Ekim yağmurlarında ıslanmak isterim Toprağın kokusuna bulanmış gibi. Hazan sarısına boyanmış günlerde Seni düşünüp umutlanmak isterim. Kırmı...', ARRAY['Türk Edebiyatı','Şiir','Rengin Alacaatlı']::text[], 8.5, '{"poet":"Rengin Alacaatlı","poet_slug":"rengin-alacaatli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/rengin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli şair', 'deli-sair-sair-gaddar-16-zok32', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarhoşum şimdi dolaşmaktayım,

Boş sokaklarda,

Doğan güneşte doğan günde,

Adım yazılı gülüm,

Ben Deli Şair...

...

Fırtınaya dönüştürdün ey yar,

Bak! her tarafa savurdun,

Gül ağacı dedin,

Kopara kopara kuruttun,

Ne yaptın ey yar,

Bak! adım olmuş Deli Şair,

...

Sadece sana yazdığım için,

Bi tek sana yandığım için,

Herşeye adın söylediğim için,

Bak! adım olmuş Deli şair.

...

İçimde deli fırtına var,

Dışarda hüzün,

Bak! bağırmaktan ağlamaktan,

Kör oldu iki gözüm,

Kırıldı elim kolum parçalandı yüzüm,

Delirdim cane adım olmuş Deli Şair.

...

Aşkın vurmuş beynime,

Sökülmez kırılmaz sanki bir demir,

Yeter artık oynama candır cigerdir,

Bak! sayende adım oldu Deli Şair.

...

Şairlerde ağlar yadıkları zaman,

Sayıklarlar ismi yaşatırlar kalpte durmadan,

Sayende yaza yaza gözlerde doldu kan,

Bedenden çıktı can,

Delirttin beni adım olmuş Deli Şair.

...

Bak! ne mutlu gözyüzü,

Herkeste var tebessüm tatlı yüzlü,

Bide bana bak deli şair,

Izdırap özlü beddua sözlü,

Yazık be adım olmuş Deli şair,

Nasılda başardın delirtmeyi.

...

Yağmur hala yağmakta,

Şimşek durmayı bilmez çakmakta,

Adım koydun deli şair,

Delirdi sonunda,

Aylardır hastanede yatmakta.

...

Delilerin aşkını bilirmiisn,

Belkide yaklaşamıyor konuşamıyor,

Ama yazmayı biliyorlar,

Tıpkı benim gibi,

Ama aramızda tek fark var,

Çoğunluk doğuştan delirdi,

Kimisi dertten,

Bazısı şoka girdi delirdi,

Kimisi acı çekmekten,

İşte bende delirdim,

Sayende, seni sevmekten,

Adım Bile olmuş Deli Şair.

...

Artık isyanlardayım adım olmuş isyankar,

Ben kış yaşıyorum herkes bahar,

Ah! ulan canavar,

Yukarda ALLAH var,

Ne yaptın böyle,

Adım olmuş Deli Şair.

.

.

.

Kanındasın çıkmayı bilmez,

Bir o yana bir bu yana gider gelirsin,

Çıkarmayın onu dedi,

Çıkmazsan içinden söylim şimdiden,

Kaldığın sürece o bir,

Deli Şair.

...', 'Sarhoşum şimdi dolaşmaktayım, Boş sokaklarda, Doğan güneşte doğan günde, Adım yazılı gülüm, Ben Deli Şair... ... Fırtınaya dönüştürdün ey ya...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/deli-sair-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-sair-gaddar-16-6tnew', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Olur eşin dostun, varsa cebinde para,

Tek tek kaybedersin onları, girdinmi dara,

Bırakırlar izlerini açılmış yara...

Söyledim sana ey! oğul,

...

Delikanlısın yiğitsin dağ gibisin,

Güvenme kimseye gittikçe erirsin,

Dostun cebindir bunu bilesin,

Aklını başına topla ey oğul.

...

İki güne kalmaz kapanır gözler,

Bu dünya hep yalan söyler,

İnsanlar sahte yüzler,

Yıkılırsın kalırsın tek oğul.

...

Üç günlük dünya,

İki günü anlamazsın zaten rüya,

İşte tek gün dünya,

Akıllı ol oğul.

...

Yüce rabbimiz kabul etmez,

Haram mal, kul hakkı yedirmez,

Bunları yapan cennet yüzü göremez,

Sana son nasihatlar ey oğul.

...

Aç ellerini yaradana,

Duaet anana babana dostuna,

Oda ışık aydınlık versin yollarına,

Yoksa yanarsın be oğul.

...

Çalış adam gibi der yüce ALLAH,

Otur kalk de La ilahe illallah,

Sen yücesin resullullah,

Yoksa vurursun başını çekersin ah.

...', 'Olur eşin dostun, varsa cebinde para, Tek tek kaybedersin onları, girdinmi dara, Bırakırlar izlerini açılmış yara... Söyledim sana ey! oğul,...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/nasihat-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Safiye', 'safiye-bekir-mutlu-gokcesu-l6sva', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koynunda cıncık şıkırtısı

Kulaklarında tınısı aşkın

Yaşamadığı diyarlar kadar 

Bilinmez ve hoş uzaktan.

Biçerek rüzgarı ceylan gibi

İner çeşme başına bayır aşağı

Kış gümüşi sabahlardan.

Üç kuş uçuşu ferahlanır önce

Çarpar bir avuç suyu yüzüne

Bir yudumda içer dağı, nehri

Bir nefeste çeker göğü içine.

Yanakları al, al, doğal mı doğal

Bakracı dolu su dönerken evine

Mutludur tebessümler içinde

Ne kadar da kendisine benzer

Şu aşkı hiç bilmez haliyle...

Ne bir sevgili geçer aklından

Ne de hayal kurar geleceğe dair

Tek kederi anası ‘ah bir iyileşse’

Kolay değil koca bir evin yükü

Mecburiyetten ara verdi derse

Sabırlı kız, eli de yatkın her işe

Pes vallahi baldan tatlı diliyse.

Ortayı bitireli halı da dokur

Öyle inanılmaz bir kız ki Safiye

Okur, okur yine okur.', 'Koynunda cıncık şıkırtısı Kulaklarında tınısı aşkın Yaşamadığı diyarlar kadar  Bilinmez ve hoş uzaktan. Biçerek rüzgarı ceylan gibi İner çeş...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/safiye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir göz bir can', 'bir-goz-bir-can-sair-gaddar-16-kobzg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl gözleri vardı bi bilsen,

Sanki, gecenin karanlığından almış gözlerini,

Nasıldı kimse bulamadı bu soruyu,

O gözlerle ağa düşürdü beni.

...

Kurtulamadım o gözlerden,

Ve hergün hayal edip o gözleri,

Verirdim bir can,

Göle dönüştü,

Bu yürekten akan kan.

...

Vaybe bunudamı yapacaktın,

Nasılda kandım nasılda yandım,

Ve hergün artık,

Veriyorum o gözlere can.

...

Haykırmak istemiyorum seni,

Nasılda insafsız nasılda vefasızsın,

Başlarda derdim cansın kansın,

En güzel yarsın,

Yanılttın beni be,

Sen bir romansın,

Bende oyuncu baş kahraman,

Şimdi mutlumusun,

Bak! her gece,

Veriyorum o gözlere can.

...

Sen eskicisin aşkı satan,

Sen azrailsin can alan,

Biliyormusun Senşn adında yalan,

Kanında yalan,

Sen olmuşsun yalan,

Ama helal aldın o gözlere can,

Ey yüce rabbim olurmu böyle zalim insan.

...', 'Nasıl gözleri vardı bi bilsen, Sanki, gecenin karanlığından almış gözlerini, Nasıldı kimse bulamadı bu soruyu, O gözlerle ağa düşürdü beni. ...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-goz-bir-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Senin Şiirlerin*', 'senin-siirlerin-ahmet-kesici-7g2bv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '*******Senin Şiirlerin******', '*******Senin Şiirlerin******...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kesici']::text[], 8.5, '{"poet":"Ahmet Kesici","poet_slug":"ahmet-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/senin-siirlerin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebebini Bilemedim', 'sebebini-bilemedim-i-smail-kocamaz-x32g2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir görünüp kaçıyorsun

Hem işve naz saçıyorsun

Başıma iş açıyorsun

Sebebini bilemedim.

Gündüzümde gecemde sen,

Dilimdeki hecemde sen,

Her türlü bilmecemde sen,

Sebebini bilemedim

Bilemedim aşk mıdır bu? 

Gözlerime girmez uyku.

Aklımda var binbir kuşku.

Sebebini bilemedim.

İşte aşkın ta kendisi.

Hep sokulur sinsi sinsi.

Farklı mıydı benimkisi? 

Sebebini bilemedim.(1975)', 'Bir görünüp kaçıyorsun Hem işve naz saçıyorsun Başıma iş açıyorsun Sebebini bilemedim. Gündüzümde gecemde sen, Dilimdeki hecemde sen, Her tü...', ARRAY['Türk Edebiyatı','Şiir','İsmail Kocamaz']::text[], 8.5, '{"poet":"İsmail Kocamaz","poet_slug":"i-smail-kocamaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sebebini-bilemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin sesi', 'gecenin-sesi-sair-gaddar-16-dwiid', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin sessizliği yine yanaştı,

Dondu kaldı dünya, yine ben kaldı,

Oda sen gibi usulca yanaştı,

Sonra tek vuruşta yara açtı.

...

Gecenin sesiymiş hiç duymadım,

Gecenin sesimi olur, işte ona şaştım,

Kulağım çınladı geçen gece, dondum kaldım,

Peşine verdim elime aldım.

...

Neler varmış onda,

Tıpkı ben ve  sen,

Sen aşk oyunu,

Bense garip aşık,

İşte hem oyun,

Hem aşk katili,

İşte gecenin sesi.

...

Kimisinin yüzündeki neşesi,

Kiminin tek dostu eşi,

İşte o gece serserisi,

Çünkü o gecenin sesi.

...

Gecenin sesini dinliyorum,

Sanki bana gir vur öldür dermişcesine,

Haykırmakta seni,

Ah! ulan be ezgim,

Yine bak bıraktın beni,

Yine ben ve gecenin sesi.

...', 'Gecenin sessizliği yine yanaştı, Dondu kaldı dünya, yine ben kaldı, Oda sen gibi usulca yanaştı, Sonra tek vuruşta yara açtı. ... Gecenin se...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gecenin-sesi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni bir tek sen anladın', 'beni-bir-tek-sen-anladin-aysegul-toker-974jz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni Bir Tek Sen Anladın

Aslında beni bir tek sen anladın

Ama tamamlamadın.

Umut çiçeklerimi elimden aldın.

Beni yalnız bıraktın.

Hani cam fanuslarda saklayacaktın? 

Cam kırıldı. Kalp kırıldı.

Can yandı. El yandı.

Sevgimiz yarıda kaldı.

K....''a..', 'Beni Bir Tek Sen Anladın Aslında beni bir tek sen anladın Ama tamamlamadın. Umut çiçeklerimi elimden aldın. Beni yalnız bıraktın. Hani cam f...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beni-bir-tek-sen-anladin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benide Askere Alın', 'benide-askere-alin-munevver-duver-4dble', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnanın bana gururla görevimi yaparım..

Ne olur beni de, beni de askere alın...

Kim bilir belki de  birkaç P. K. K''lı haklarım

Ne olur beni de, beni de askere alın...

Vücudumda asil kan taşıyorum,

Sizinle askerlik yapmaya can atıyorum

Beni de askerliğe almanızı istiyorum..

Ne olur beni de, beni de askere alın...

O üniformayı giyip üstüme

Anamdan emdiğim helel sütüme 

Dokunmayın! ..vatan aşkıyla dolu zihniyetime.

Siz sadece, beni de, beni de askere alın...

Sizlerle çalışmak gurur verici bir duygudur

Bir kızın askere söz söyletmemesi, olgunluğudur,

Kuru söze gerek yok, anlatmak istediğim şudur,

Ne olur beni de, beni de askere alın...

Elime bir silah, sırtıma bir yük,

Ayağıma potinler, bileğime biraz güç,

Koşarak şehitliğe gitmek çok güç

Ne olur beni de, beni de askere alın...

Komutanlarım ne olur kızlarıda askere alın

Anacığım güzel duygularla beni askere salın

Eğer şehitlik mertebesine ulaşırsam..

Ağlamayın, dualarla beni mezara salın

Bir ricam var size komutanlarım,

Af olunsun, eğer varsa hatalarım

Vatanım için, bütün sevgi dolu duygularım

Ne olur beni de, beni de askere alın..

Buradan seslenmek istiyorum onlara

Münevver dahil, üniforma verin kızlara

En fazla iki yıl, ama iki yıl sonra

Ne olur beni de, beni de askere alın..

05-06-1998-saat: 15.32

ADANA', 'İnanın bana gururla görevimi yaparım.. Ne olur beni de, beni de askere alın... Kim bilir belki de  birkaç P. K. K''lı haklarım Ne olur beni d...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/benide-askere-alin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felek', 'felek-ahmet-hani-p3ta4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oldun ecel can alasan ay felek? 

Başımdan el çek solasan ay felek.

Öyretmeyib atan sene mürüvet,

Ona göre pıs balasan ay felek.

Xoş günleri el obadan apardın,

Görmeyim ki xöş olasan ay felek.

Gözelerin sularını qurutdun,

İplere yox day döl asan ay felek.

Sındırıbsan çox qıçları,çox başı,

Boynuna çoxdur qol asan ay felek.

Toyuqların altında laqq olubsan,

Fikr etmeki sen falasan ay felek.

Ayrılığın bir dadasan dadını,

Ta bilesen ne belasan ay felek.

Ayrı saldın el obadan sen meni,

Ayrı düşüb tek qalasan ay felek.

1992', 'Oldun ecel can alasan ay felek?  Başımdan el çek solasan ay felek. Öyretmeyib atan sene mürüvet, Ona göre pıs balasan ay felek. Xoş günleri ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/felek-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Doğduğum Gün', 'yeniden-dogdugum-gun-ali-varol-yh37l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koyu bir sis basmış ülkemin üstüne

Dört bir yanda istila istila üstüne

İstila ki irin gibi kokuyor

Geçtiği yeri kokuyla boğuyor

Ve o kokuyla beldeme kadar gelmiş

Beldem ki efeler diyarı Ödemiş

Burada çocuklar uçurtmayı, çocuklar neşeyi

Çocuklar cıvıldaşmayı özlemiş 

Anam hamur açmayı

Anam cepheyi su taşımayı özlemiş

Babam barut kokusunu

Babam mavzeri özlemiş

Artık benim ülkem

Ülkemin bağrından doğmayı özlemiş

Deniz yakası yer yer estikçe

Barut kokusu geliyordu üstüme üstüme

Efeler dedeler gençler coşuyordu

Coşuyordu saatler geçtikçe

Başında yazması ayağında şalvarı ile bir nine

Bağırıyordu yiğitlere olanca nefesiyle

“Atamın her sözü vasiyettir bizlere

Esaret yakışmaz Türk milletine

İlkemiz ya istiklal ya ölüm” diye

Vakit geçmeden bir haber yayıldı

Dar sokaklarda çeşme başlarında

Ve çocuklar ok gibi fırladı evlerinden

Genç kızlar türkü söylüyor artık yürekten 

Ve söz verdik o gün biz hepimiz

Bağımsızız biz bağımsız kalacağız ebediyen

Ve gün gelirde bir gün yine

Depremler olursa benim ülkemde

Çığ düşerse beldemin üstüne

Kara bulut kaplarsa mavi gökyüzüne

Gölge ettirmeyelim Cumhuriyetimin üstüne', 'Koyu bir sis basmış ülkemin üstüne Dört bir yanda istila istila üstüne İstila ki irin gibi kokuyor Geçtiği yeri kokuyla boğuyor Ve o kokuyla...', ARRAY['Türk Edebiyatı','Şiir','Ali Varol']::text[], 8.5, '{"poet":"Ali Varol","poet_slug":"ali-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yeniden-dogdugum-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş Çocukları', 'savas-cocuklari-ulas-akcay-n1fsz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ölüm yakışmıyor sana çocuk

yaşamak bu denli anlamlı iken

                                        varlığınla

oysa ölümlere inat

uçsuz bucaksız mavilikler olmalı

                                         her yanın

bahar toprağı kokmalı

çiçekler açmalısın rengarenk

her mevsim güneşle dolmalı

                                         gözlerin

barış olmalısın sen

her zulme her kıyıma

ve de her yok edişe karşın 

                                         barış

kimi zaman aya sevdalı bir

                                         yakamoz

kimi zaman yakamoza sevdalı

                                         deniz

gülmelisin sen çocuk 

haykırmalısın özlemlerini

dolup taşmalı kar beyazı 

                                         yüreğin

karanlıklar diz çökmeli önünde

cellat boyun eğmeli

kırmalı zincirlerini esaretin

bil ki zafer senin olmalı çocuk

                                         bil ki dünya senin', 'ölüm yakışmıyor sana çocuk yaşamak bu denli anlamlı iken                                         varlığınla oysa ölümlere inat uçsuz bucaksı...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Akçay']::text[], 8.5, '{"poet":"Ulaş Akçay","poet_slug":"ulas-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/savas-cocuklari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Sevgili', 'vefasiz-sevgili-mustafa-alpaydin-yi4dz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yara ayan olsun yanar yüreğim

O güzel yüzünü son kez göreyim

Şu koca dünyadan o gün göçeyim

Ömrün son deminde bunalttın beni.

Bu sevda bedende takat bırakmaz

Kulağım işitmez gözlerim bakmaz

Dilim söyleyemez kollarım kalkmaz

Ömrün son deminde unuttun beni.

Haberin gelmiyor duyulmaz sesin

Vefasız sevgili şimdi nerdesin

Durmadan nefesim gelip göresin

Ömrün son deminde ağlattın beni.', 'Yara ayan olsun yanar yüreğim O güzel yüzünü son kez göreyim Şu koca dünyadan o gün göçeyim Ömrün son deminde bunalttın beni. Bu sevda beden...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vefasiz-sevgili-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Yakamı', 'birak-yakami-mehmet-bicik-t0btf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çektirdiğin çile yeter, bırak yakamı.

Bırak da artık biraz nefes alayım…

Düşürdün dillere, bozdun fiyakamı.

Bırak da bir ömür dillerde olayım…

Yıktın dünyamı hayatımı bitirdin.

Aşktan, sevgiden nefret ettirdin.

Tüm güzellikleri aldın götürdün.

Bırak çirkinlikler içinde yaşayayım…

Bir insan bu kadar acımasız olamaz.

Zulmeden insanlar huzur bulamaz.

Sevdiğini ağlatan kendi gülemez.

Bırak beni de rahat rahat öleyim…

Hiç sevmedim senin iğrenç yapını,

Onun için çabuk dürdüm kitabını,

Dünya’da, Âhiret’te çalmam kapını,

Yeter ki senden bir kurtulayım…

20 Ekim 2005, Burhaniye 21:00', 'Çektirdiğin çile yeter, bırak yakamı. Bırak da artık biraz nefes alayım… Düşürdün dillere, bozdun fiyakamı. Bırak da bir ömür dillerde olayı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birak-yakami-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın adı', 'askin-adi-mustafa-murat-aydogdu-brw1a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şeyimi yitirdim sevda uğruna

Daha genç yaşımda bir ceset oldum

Aşkın tarifi yok derlerdi ama

Ben aşkın adını ayrılık koydum

İnsanın ruhunu bir anda saran

Olmadık hayali gerçek sandıran

Bazen mutlu eden,sonunda yıkan

Ben aşkın adını ayrılık koydum

Gözlerde yaş olup usulca akan

İnsanı dünyada yalnız bırakan

Bazen çağlayan,bazen durulan

Ben aşkın adını ayrılık koydum

Bu acı,bu hüzün sanma doğuştan

Bir zamanlar mutlu,neşe doluydum

Gözümde yaş varsa sebebi aşktır

Ben aşkın adını gözyaşı koydum

Eğer gülmüyorsam sebebi sensin

Ben mutluluğu sende bulurdum

Sana aşkı sorsam,bilmem ne dersin? 

Ben aşkın adını ayrılık koydum

Sevene,sevmeyene,gülene,ağlayana

Gökteki güneşe,aya,yıldıza sordum

Ve üstümüze bir yağmur yağdı

O yağmur sevenlerin gözyaşlarıydı

Ben aşkın adını; gözyaşı,

Ben aşkın adını; yalnızlık,

Ben aşkın adını; ayrılık koydum!', 'Her şeyimi yitirdim sevda uğruna Daha genç yaşımda bir ceset oldum Aşkın tarifi yok derlerdi ama Ben aşkın adını ayrılık koydum İnsanın ruhu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/askin-adi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koparılan Dalın Kökleri', 'koparilan-dalin-kokleri-ercan-cengiz-uywdb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gidilecek bu yol 

Aşılacak bu dağlar

Çarpışa çarpışa zalimle

Çarkın dişlilerinde kalan ezgilerle.

Ülkede, Munzur''un eteğinde

Dere yatakları,

Vadiler

Seyreltili tepeler içinde...

Binlercesini barındırır bu dağlar

Çok şey var ardında heval 

Çok şeyler...

Otuzsekiz''den de öncedir

Alıkonan toprağın metropol ayağı.

Toros''larda ırgat,

Toros''larda hamal,

Çukurova''da pamuk toplayıcıları

Dört bir yanında Anadolu''nun

Modern köleleri olmuş memur,

Varoşlarda köylü...

Avrupa''da temizlikçi...

Fabrika işçileri

Sokaklarında ise süpürgecidirler.

Her dalı bugün 

Her dalı kökünü aramaktadır.

Asfaltlı yollardan patikaya düşer ayağı

Yitik kalbin ezgisiyle

Dağlarına ülkenin insanı 

Tepelerine girmiş oyuk oyuk

Mevzide

Siperde

Patikalarda

Hain pusuda

Çarpışmalarda

Ölümüne

Zindan direnişlerinde

Yeni günü 

Baharı yaratan 

Ceylandırlar...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)', 'Gidilecek bu yol  Aşılacak bu dağlar Çarpışa çarpışa zalimle Çarkın dişlilerinde kalan ezgilerle. Ülkede, Munzur''un eteğinde Dere yatakları,...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/koparilan-dalin-kokleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-umut-ve-yasam-g8ll4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden Gittin ki Sanki

Neden Gözlerini bende bırakıp Gittinki

Her nereye baksam seni görmem için mi? 

yoksa her nereye baksam

Bir kez daha ÖLMEM için mi?', 'Neden Gittin ki Sanki Neden Gözlerini bende bırakıp Gittinki Her nereye baksam seni görmem için mi?  yoksa her nereye baksam Bir kez daha ÖL...', ARRAY['Türk Edebiyatı','Şiir','Umut Ve Yasam']::text[], 8.5, '{"poet":"Umut Ve Yasam","poet_slug":"umut-ve-yasam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/neden-188-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğreniyorum', 'ogreniyorum-mustafa-murat-aydogdu-c71cc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğim bir nehir,çağladı seninle

Coşmayı da bilir,durulmayıda

Ne zaman,nasıl,bilmem nerede

Susmayı da bilir,unutmayıda

Silinir bir gün acılar tenden

Duygular yenilir bir gün mantığa

Kader ayrılıksa ne gelir elden

Sevmeyi de bilirim,unutmayıda

Her şeyi unutur giderim buradan

Adı bilinmeyen meçhul bir yere

Eğer bir gün beni anlarsan

Gitmeyi de bilirim,beklemeyide

Gönlümün perdesi kapandı seninle

Açmayı da bildim,kapatmayıda

Hasretle yandığım zor gecelerde

Gülmeyi de bildim,ağlamayıda

Sevgiler ölümsüz,bitmez sanırdım

Beni bırakıpta gitmez sanırdım

Onu sevdim diye kızmaz sanırdım

Umudu bildim,yanılmayıda

Sendin öğreten bana gülmeyi

Yine seninle yitirdim bütün neşemi

Bir hayale kanan şu yüreğimi

Yakmayıda bildim,avutmayıda

Ben miyim yoksa sen mi,duygu katili

Bilmedim ayrılığın sebebi neydi

Bir nisan günüydü kaybettim seni

Bağlanmayı bildim,yitirmeyide.', 'Yüreğim bir nehir,çağladı seninle Coşmayı da bilir,durulmayıda Ne zaman,nasıl,bilmem nerede Susmayı da bilir,unutmayıda Silinir bir gün acıl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ogreniyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göklerde Salınıyorum', 'goklerde-saliniyorum-yilmaz-ozturk-1edo9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstanbul`dan bir haber geldi dostluk adına

Sevinçle çıktım dünyadan kutup yıldızına

Göklerde geziyorum tarifsiz bir huzurla

Allah nasip etsin bu huzur her kuluna

İstanbul`dan gelen bir telefon can verdi Manavgat`a

Dünya titredi sevincinden dostluk hatırına

Sonsuz şükürler olsun yüce Yaratıcı`ya

Göklerde salınıyorum ''''GÖKSAL`LANDI

Asil dostluk şerefini yaşıyorum göklerde dost tadını', 'İstanbul`dan bir haber geldi dostluk adına Sevinçle çıktım dünyadan kutup yıldızına Göklerde geziyorum tarifsiz bir huzurla Allah nasip etsi...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Öztürk']::text[], 8.5, '{"poet":"Yılmaz Öztürk","poet_slug":"yilmaz-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/goklerde-saliniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşün', 'gulusun-mustafa-murat-aydogdu-mlh9v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ardından dökülen yaşlar ölünün

Gurbetten sılaya geri dönüşün

Aşk,hasret kokan bir gonca gülün

Adıydı bende; masum gülüşün

Umutlar kaybolup yıkıldığın an

Çaresiz hayata boyun büküşün

Beni bırakıpta gittiğin zaman

Hayata vedaydı; masum gülüşün

Asık suratlara edilen sitem

Hayatın içinden mutlu bir dönem

Her geçen günde usulca sönen

Bir ışıktı bende; masum gülüşün

Saatler durmuştu,durmuştu zaman

Ruhumu sarmıştı korkunç bir hüzün

Elini elimden ayırdığın an

Hayata vedaydı; masum gülüşün

Kalmadı hayatın anlamı artık

Kalmadı artık anlamı gülün

Beni bırakıpta gittin ne yazık

Bilirim olmaz artık dönüşün

Kalmadı anlamı artık; gülüşün!', 'Ardından dökülen yaşlar ölünün Gurbetten sılaya geri dönüşün Aşk,hasret kokan bir gonca gülün Adıydı bende; masum gülüşün Umutlar kaybolup y...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gulusun-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tezgâh', 'tezg-h-ahmet-kurt-vf54b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Önce süslenmekte, çare denmekte,

Ardından makyajla halka dönmekte,

Her gün yeni yeni ocak sönmekte,

Bu tezgâh, ne gaflet, ne de cehalet,

Başka izahı yok, resmen ihanet.

Dün Filistin, Lübnan, bugün Türkiye,

Herkes düşman olmuş milli ülküye,

Ölüm sessizliği, artık Türküye, 

Bu tezgâh, ne gaflet, ne de cehalet,

Başka izahı yok, resmen ihanet.

Toprağında köylü köle edildi,

Devlet boşaltıldı, reform denildi,

İçim kurutuldu, narkoz verildi,

Bu tezgâh, ne gaflet, ne de cehalet,

Başka izahı yok, resmen ihanet.

Demokrasi güya listeler hazır,

Nerede olursa onlar hep vezir,

Sünepe bürokrat, bitliler nâzır,

Bu tezgâh, ne gaflet, ne de cehalet,

Başka izahı yok, resmen ihanet.

Kaynak İMF plan Dünya Bankası,

Borçların kesilmez oldu arkası,

Bunların amblemi Siyon markası,

Bu tezgâh, ne gaflet, ne de cehalet,

Başka izahı yok, resmen ihanet.

Sanki ölçü koyar, aslı inkarda,

Amacı zarardır, görüntü kârda,

Kurdoğlu isyanda, yüreğim nârda,

Bu tezgâh, ne gaflet, ne de cehalet,

Başka izahı yok, resmen ihanet.', 'Önce süslenmekte, çare denmekte, Ardından makyajla halka dönmekte, Her gün yeni yeni ocak sönmekte, Bu tezgâh, ne gaflet, ne de cehalet, Baş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tezgah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin Duyurmaz mı Çektiğin Acıları', 'sesin-duyurmaz-mi-cektigin-acilari-ercan-cengiz-ae4s4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaman prangalara vurulmuştu

Acıya durulurdu

Kamburun tokuşurdu eldeki kadehle

Acın tutuşurdu tutuşmasına

Nedendir, bilinmezdi de

Ayağının sarp yollara düşmesi.

Konuşamaman zamana kurulmuştu

Uzun uzun kahır çekilirdi

Ayaklarının üzerinde taşıdığın beden

Karşı duramazdı zalime

Ürperirdi insanoğlu.

Karanlığa yükselirdi ezeli yüklü komut

Dirhem dirhem kazınırdı bedenin,

Sesin duyurmazdı acını

Boğuktu

Bitmezdi, tükenmezdi açlığın

Çilen bitmezdi...

Köy köy

Mahalle mahalle

Ev ev

Sokak sokak

Gizemidir devranın kendi

Bundandı karanlıkta boy vermesi...

Midede tutuşurdu kadeh

Açlık

Acı içinde sürüklenirdi özü

Demiyorsan bir süre daha eğer

Al kadehi vur yere...

Zaman prangalara vurulmuştu

Karanlıklar içinde acının gizemi

Beyinlere oturtulmuş bir yelkovan

Eldeki kadehle

Tokuşurdu emeğin

Çaresizliğindir

Yükündür

Kamburundur.

Ayağın sarp yollara düşerdi

Konuşmamanın

Konuşamamanın ölçütü

Duyuramadığın

Çığlığındı

Karanlığın gizemi...

Katledilen doğacındı damar damar

Yayılmış

Acıların bileşkesi,

Tarihin o acılardadır senin

Sallanır

Kazınır dirhem dirhem.

Konuşamaman zamana kurulmuştu

Zaman prangalara vurulmuştu

Ürperirim ki 

Boğuk sesin duyurmaz çileni

Acını 

Açlığını gidermez.

Karanlığın gölgesi yükselirdi

Ağırdır

Vurunca da sırtından vurur

Uyan

Uyan ki

Kendinin olman için...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)', 'Zaman prangalara vurulmuştu Acıya durulurdu Kamburun tokuşurdu eldeki kadehle Acın tutuşurdu tutuşmasına Nedendir, bilinmezdi de Ayağının sa...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/sesin-duyurmaz-mi-cektigin-acilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G i t! .. G i t! ..', 'g-i-t-g-i-t-mehmet-ali-demircan-r5ojk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen! .. 

Sen gidiyorsun ha? 

Git bakalım. 

Bunca yaşanmışlığı hiçe sayarak,

Ardına bile bakmadan, 

Beni buralarda yalnız, 

Tek başına, çaresiz, 

Dört duvar arasında, 

Bırakıp ta gidiyorsun ha? 

Şu gözlerimi demi görmüyorsun? 

Yeşil  yeşil değil gülüm, 

Kara  kara, bakan yaş dolu gözlerimi. 

Hüzün çöktü içime, 

Volkanlar kaynıyor yüreğimde, 

Ha aldı alacak gibi Azrail canımı, 

Ha gitti gidecek gibi oluyor nefesim. 

Kelimeler düğüm  düğüm, 

Çıkmak bilmiyor, 

Yolunu şaşırmış serseri mayın gibiyim, 

Islak, donmuş, titreye  titreye, 

Soğuk ayazlarda kalmış gibi, 

Ürkek, utangaç ve masumca. 

Git! .. 

Bedenimin, ruhumun, kalbimin, 

Yarısını ödünç almış gibi git, git. 

Peki! .. 

Peki git öyleyse. 

Git! .. git de, 

Ben; kime canım diyeceğim? 

Kime aşkım diyeceğim? 

Kimin gözlerine bakıp? 

Kimin saçlarını okşayacağım? 

Ya beni kim? Kim kızdıracak? 

Kim etrafımda! ..

Ağır aksak seke  seke dolanacak? 

O neşesiyle beni kim güldürecek? 

Ben kiminle lokmalarımı bölüşecek? 

Kiminle çayımı yudumlayacağım? 

Ya o gülüşün! .. 

Tınısı hala kulaklarımda, 

Ve kulaklarımdan hiç gitmeyecek. 

Ya o,''Aşkım, aşkımmm'' deyişin, 

Çağıl çağıl çağlayacak kulaklarımda,

Her ses duyduğumda sesini arayacak, 

Ve hüzünlere kapılacağım. 

Hıçkırıklara boğulacak, 

Her seste seni arayacak, 

Kara topraklara girmiş gibi olacağım.

Susacağım! .. 

İçime akıtacağım göz yaşlarımı,

Zehir misali parçalaya parçalaya,

Yüreğime kanlı yaşlar boşalacak,

Damarlarımdaki kanım çekilecek,

Kalbimin atışı bedenimi yıkacak,

Yokluğun hançer gibi parçalayacak yüreğimi, 

Kanlı gözyaşlarımı tutmaya çalışacağım, 

Yada varsın aksın, 

Varsın aksın,

Bu benim, 

Bu benim gül sevdam dı diyeceğim. 

Dayanağım, yaşam kaynağım,

Gözlerin di içinde ki varlığım,

Soluduğum nefesimdin,

Ya şimdi, ya şimdi! ..

Gidişin, gidişim oldu,

Yaşayamıyacağım yaşamım,

Seninle hayel kurduğum hasretim oldun,

Sol yanıma inen vurgunum, yokluğum oldun.

Varlığınla cennetim,

Yokluğunla cehennemim oldun.

Ben seni çok sevdim gülüm, 

Bir ana gibi, baba gibi.

Ben seni çok sevdim gülüm,

Bir gül gibi, yar gibi, eş gibi. 

Ben seni çok sevdim gülüm, 

Mecnunun Leyla'' yı, 

Ferhatın Şirin'' i, 

Yunusun Mevla'' yı sevdiği gibi sevdim.

Ben, ben seni çok sevdim gülüm,

Çok sevdim, çok sevdim gülüm. 

Ben seni sevdim, açmamış tomurcuk gibi, 

Güzelliğini, sevimliliğini, tazeliğini. 

Ben seni sevdim, yiğitliğini, masumluğunu, 

Ben seni sevdim,yarim gibi, canım gibi, 

Ben! .. 

Ben seni sevdim, kızım gibi, yavrum gibi. 

Ben seni,

Ben seni aşkım gibi sevdim,

Biliyorsun değil mi, seni çok özleyeceğim,

Özlemin kara basanlar gibi 

Dermansız dert gibi çöreklenecek içime 

Belki götürmeyecek, öldürmeyecek,

Ama hasretin azar azar,

Parça parça bitirecek yüreğimi,

Ölümden beter edecek beni.

Ama sana olan sevgime,

Sana olan aşkıma leke çalamayacak,

Tükenmiş son nefesime dair,

Bu benim...

Bu benim gül sevdam diye haykıracağım. 

Bazen hüzünlere kapılıp ta dalarsan, 

Canın sıkılır da ağlarsan, 

Hayat sana çekilmezmiş gibi gelirse, 

Kalbinin, beyninin bir köşelerinde,

Az da olsa yerim varsa, 

Beni hatırla, beni an, beni ara, 

Bil ki, ömrünün sonuna kadar, 

Seni seven, seni anan ve hiç unutmayan, 

Bir can, bir yürek, bir beden var buralarda. 

Senin için gülümsüyor, 

Ve dualar ediyor olacağım. 

Git! .. 

Git, sana en derin sevgiler, 

Git! .. 

Her şeyin gönlünce olacağı özgür ülkelere git, 

Git, doğan güneşin aydınlığı ile git. 

özgür uçuşan kuşlar gibi, 

Etrafında koşuşturan meleklerle git. 

Git! .. Git! .. Git! .. 

MAD.', 'Sen! ..  Sen gidiyorsun ha?  Git bakalım.  Bunca yaşanmışlığı hiçe sayarak, Ardına bile bakmadan,  Beni buralarda yalnız,  Tek başına, çares...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Demircan']::text[], 8.5, '{"poet":"Mehmet Ali Demircan","poet_slug":"mehmet-ali-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":120,"source_url":"https://www.antoloji.com/g-i-t-g-i-t-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-serhat-aksungur-sbc0n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel

Yalnız kaldım burda

Tut ellerimden

Kopma

Sen

Hep sendin hiç olmayan

Söylediklerimden

Korkma

Yelkovan akrebin üstünde

Sözcüklerin içimde gölge

Rüyamda bir adam ağlıyor

Ben söylemeden gel diye

Bir

Şair öldü geceye

Ayışığı şahitti

Sadece

Gün

Döndüğü andan şimdiye

Bir ömür

Her saniye

Gidiyorsun ardına bakmadan

Bir umut bırak kapıma vurmadan

Benden aldığın ne varsa

Sakla sandıklarında kokmadan', 'Gel Yalnız kaldım burda Tut ellerimden Kopma Sen Hep sendin hiç olmayan Söylediklerimden Korkma Yelkovan akrebin üstünde Sözcüklerin içimde ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Aksungur']::text[], 8.5, '{"poet":"Serhat Aksungur","poet_slug":"serhat-aksungur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/golge-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimin Elinde', 'kimin-elinde-bilal-altuntas-6nga8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bahar akşamından merhaba sana! 

Biliyorum hataydı seni sevmek,

Biliyorum hataydı gönül vermek,

Soruyorum sana kimin elinde,

Bir defa doğup bin defa ölmek

Eğer seviyorsan seni,

Seninim  işte al! 

Ya köle gibi kullan,

Yada özgürlüğüme sal..', 'Bir bahar akşamından merhaba sana!  Biliyorum hataydı seni sevmek, Biliyorum hataydı gönül vermek, Soruyorum sana kimin elinde, Bir defa doğ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Altuntaş']::text[], 8.5, '{"poet":"Bilal Altuntaş","poet_slug":"bilal-altuntas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kimin-elinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağa Sarısını Verirken Üşüdü', 'topraga-sarisini-verirken-usudu-ercan-cengiz-3zhdj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlığın dehşetidir, çilenin pençesi

Kara bir bulut yapışırdı

Toprağın yüzüne.

Çaresizlikti köylünün elinde

Babasından kalan miras

Açarak ellerini allaha yakarırdı.

Yağmur yağacaktı 

Yağmur yağacaktı

Yağmur,

Serpilen kımıldı oysa

Deli bir rüzgarla

Çoktan sarmaladı ekini.

Gün hesabındaydı hamile bir kadın

İlk bebeğine

Düşüyorken aydan

Gün be gün

Bir yaprak daha duvar takviminden

Koparırdı akşam vakti.

Zamansız tutulut sancıya

Doğuramazsa Anası gibi

Ana olamamak vardı,

Beyninde kurt kemiriği

Benzi soluk

Karıncalanırdı teni...

Titreşimi neydi yarı kentlinin

Pamuk üretirdi,

Üşürdü ekin başakları

Sarısını verirken toprağa.

Kaplumbağa sabrıyla bir demirci

Yapardı sipariş gelen orağı,

Hava karardığında ikindi vaktiydi

Bedenini saran karanlık,

Sırtından girmişti

Soğurdu bedeni

Kara bulutun ardında...

İklimi değildi bu ülkenin,

Bu coğrafyanın iklimi değil

Bir yanda düşünürdü 

Ak saçınan

Kor ateşe damlardı 

Soğumuş teri...

Bir ömür gelip geçerdi

İnadına

Çile yüklenirdi sanki,

Kendi toprağında ağzı dolu

Gülemezdi insan...

Bir ömür geçerdi

Babadan kalma miras

Bir adım büyütmez,

Bir gün götürmezdi

Babadan bilme yaşardı 

Bir ömür

Sınır geçmez

Yol geçmezdi

Çilesini yüklenirken omuzlarına...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)', 'Karanlığın dehşetidir, çilenin pençesi Kara bir bulut yapışırdı Toprağın yüzüne. Çaresizlikti köylünün elinde Babasından kalan miras Açarak ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/topraga-sarisini-verirken-usudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senek', 'senek-ahmet-hani-tdf6u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yoxdur indi yar senin,

O günkü vüqar senin.

Sen kimidin ay senek,

Ne xoş iyin var senin.

.............................................Senek:Bardaq', 'Yoxdur indi yar senin, O günkü vüqar senin. Sen kimidin ay senek, Ne xoş iyin var senin. .............................................Senek:...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/senek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhamet (sesli şiir)', 'merhamet-sesli-siir-fatih-ozkonyali-ub69f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yorumlayan: Semih Yücel Yücetürk 

