INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba''m', 'merhaba-m-yasemin-sezer-tulgar-oa7vf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen hala kozandan sıyrılıp kelebek olamadın mı? 

eylül de kelebek olmak zordur,

eylül nazı

nazla süzül penceremden

ki tozların karışmasın haksız esen yelden

yeknesaklığına yandığın bu hayat

bil ki sunacaktır

bir değil beşbin gün 

çoğalacaksın

artacaksın

her yeni güne

yeni renkleriyle

kozasız 

hayat...

.......

Seviyorum seni

merhaba''m

......

22.09.05', 'sen hala kozandan sıyrılıp kelebek olamadın mı?  eylül de kelebek olmak zordur, eylül nazı nazla süzül penceremden ki tozların karışmasın ha...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/merhaba-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duydum', 'duydum-yasemin-sezer-tulgar-41f4h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Orgi danslarından 

