INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç-Beş', 'uc-bes-yasemin-sezer-tulgar-1pyog', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmur

İstanbul günüm

Kadıköy iskele

Büfe yanı

Rüzgar, çay, sigara

Peşi sıra insan

Koşturmaca

Renkli şemsiyeler

Ters dönen

Kırılan

Ihlamur ağaçları

Üç-beş

Beton zeminden 

Kök dilenen

Şimdi

Vapur

Baş taraf

Sol kenar

Banko ıslak

Sigara tüten insan

Üç-beş

Dumanından

Dem bulan

Ilık esinti

Yüzüm soğuk

Sol taraf fazlaca

Son adam

Hadi koş

Kapanıyor kapılar

Bekleme daha

Yarım saat

Martı bir

Martı iki

Süzülüyor 

Üç-beş

Denizde balık arayan

_NOT: Adam yetişti

Çaycı: Var mı içen çay? 

Yok içtim sağol

Karşımda

Yaş kırk-kırkbeş

Kır saç

Kır sakal

Yeşil güderi mont

(Bende de 

Yeşil deri pardesü) 

Elinde gazete

Seçemedim adı

Katlamış

Ayaklar çapraz 

Banko altı

Kadın, sarışın

Yanında

Tanış değil belli ki

Göz ucuyla gazete

Tanışırlar belki

Tanrım 

Bu nasıl bir eşortman

Pijama giyseydi daha iyi

_gülümseme

Yol almışız

Yazmaktan ancak fark

Dalgakıran Harem arası

Gene aralardayım ya

Peh! 

Dalgakıran üstü

Karabataklar 

Üç-beş

Yağmuru duş sayan

Boyunları dik

İlerisi

Topkapı

Ayasofya

Sultanahmet

En yakından

On minare toplam

Haktan bu şehre

Derman uman

Başka vapur geçti

Yolcu

Yolcularına 

Çeyrek kala

Deniz

İğde yeşili

Hafif köpük dalga

Üç-beşten epey fazla

Karadeniz akıyor Ege’ye

Rüzgardan hızla

Okulum

M.S.Ü.

Sol karşı

Az mı tuttuk istavrit

Çinekop

Hatta yanlışlıkla

Martı

Oh! 

Mangalda sefa

Kaçak demirden şarap

Okul gibi okul yani

Eski heykel bölümü yok

Yerinde yeni bina

Ne propagandaydı ama

Kestirmemek için

Ulu çınarı

Kestiler

Sağolsun rektör

Şimdi

İçiyordur sigarasını

Demlerken meziyetini

Kız Kulesi karşısı

Doku

İstanbul’umun dokusu

Hangi

Üç-beş

Binlerce bina

Milyonca insan

Göçünden

Bir kıçımlık 

Yer uman

Canım

Dolmabahçe öncesi

Molla Çelebi Camii

Hala bakımsız

Uzundur

Geçmedim önünden

Denk gelirdim çoğu

İçeriden taşanların

Namaza duran popolarına

_Allah affetsin aman! 

Vapur

Tam çark

Islandım

İçeri esiyor rüzgar

İlerledim 

Hafifçe

Yaklaştık gibi

Beşiktaş an

Üç-beş 

Zamandan kal/an 

Millet

Aceleci

İniyor aşağıya

Üç-beş

Neyse bekledikleri? 

Yüzmek? 

_Gülümseme

Bekliyorum

Keyif yerinde

Tamam

Sigaram bitsin hele

Yanaşıyor

Karşım Salacak

İlerisi Üsküdar

Hatırladım

Alacaklıyım Üsküdar’dan

Lokum

Üç-beş

Yoluma arkadaş

Şimdi

Taksi

Bastırdı yağmur 

İyice 

Sıçan oldum

Şöför

Evlere şenlik

Akşamdan kalma ses

Neyse yol kısa

Bu havada

Sabret

Işıkları geçtik

Sola

Akaretler yokuşu

Çeşmeden sağa

Tamam

İkinci soldan sap

Bırak yazmayı

Kızım para

Para

Bedava olmuyor

Ofis

Sohbet

Üç-beş

Zordu konu

Olsun son değildi ya

Şiir mi? 

Bilemem

Çektim 

Temize

Takdir 

Sizden

Sevgilerimle...

01.10.05', 'Yağmur İstanbul günüm Kadıköy iskele Büfe yanı Rüzgar, çay, sigara Peşi sıra insan Koşturmaca Renkli şemsiyeler Ters dönen Kırılan Ihlamur a...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":192,"source_url":"https://www.antoloji.com/uc-bes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pinokyo', 'pinokyo-refik-senol-cetin-di15o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sus-pus işte her yan yine

İnsanlar içine mahpus

Penceresi olmayan odalar

Ve kedi sadakatindeki sevdalar ve kalın kitaplar

Ve içimize sinmeyen bir hayat

Siz olsanız ölümü 

Nasıl tarif ederdiniz? 

“İçiniz acısın istiyorum

Ama bunu hissedin istemiyorum”

Anlıyorum aslında tüm olup bitenleri

Durduk yerde yitip gidenleri

Telefonlar çalıyor 

Ama açmıyor hiç kimse 

Hava serin üzerimdekiler

Gözyaşımdan ince

Siz olsanız aşkı 

Nasıl tarif ederdiniz? 

Susmak bilmiyor sessizlik

Bireyselliğin devrinde

Kıymetin alametleriyiz hepimiz

Karamsar aynalardaki aksi akislerimiz

Yanıltmasın hiç kimseyi

Hele güzel olan şeyler

Var bu dünyada

Siz olsanız yalanı

Nasıl tarif ederdiniz

Burnu upuzunken Pinokyo’ya?', 'Sus-pus işte her yan yine İnsanlar içine mahpus Penceresi olmayan odalar Ve kedi sadakatindeki sevdalar ve kalın kitaplar Ve içimize sinmeye...', ARRAY['Türk Edebiyatı','Şiir','Refik Şenol Çetin']::text[], 8.5, '{"poet":"Refik Şenol Çetin","poet_slug":"refik-senol-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/pinokyo-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül''üm Gül', 'gul-um-gul-yasemin-sezer-tulgar-959z5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sarmaşık 

karışık 

adaletsiz 

hüzün 

ah 

hazan 

sil avuçlarımızı 

yalan yazan 

Çin Gülü''mde 

gördüm 

böylesi 

yalnız 

böylesi 

hüzün 

ürktüm 

korktum 

___endişe 

ışıt ilkyaz___ışıt 

canına 

yandığımın 

sevmedim 

gül dem hüznü 

yakışmıyor 

gül''e 

ey bülbül 

şakıyacaksan şakı 

soldurma 

Gül''ümün 

Gün yüzünü

