INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçarım Ben', 'ucarim-ben-halil-colak-ljf9p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seherin dar vaktinde

Senin hayalinle uykuya dalarım ben

İçimde yanan aşk ateşinde

Kül olur rüzgârında uçarım ben

Güzel gözlerinin renginde

Çimenlere rüyamda senle uzanırım ben.

Geceleri rüyalarımda

Mutlu olur senle uçarım ben.

Geceleri ay ışığı olmasa da

Yıldızların ışıkları sönse de

Sen aşkın ışığında Leyla 

Yol bulur giderim ben.

Halil Çolak 23.10.2005 Ankara', 'Seherin dar vaktinde Senin hayalinle uykuya dalarım ben İçimde yanan aşk ateşinde Kül olur rüzgârında uçarım ben Güzel gözlerinin renginde Ç...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ucarim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yerimde Duramıyorum', 'yerimde-duramiyorum-mehmet-emin-altun-9b23z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki ilk aşkımsın kendimi tutamıyorum

İlkmi sonmu olacak bilemiyorum

Resmin bile yok bende isteyemiyorum

Seni seviyorum vede özlüyorum

Elimde değil kalbimdesin biliyorum

Ne güzel şey seni sevmek yerimde duramıyorum', 'Belki ilk aşkımsın kendimi tutamıyorum İlkmi sonmu olacak bilemiyorum Resmin bile yok bende isteyemiyorum Seni seviyorum vede özlüyorum Elim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Altun']::text[], 8.5, '{"poet":"Mehmet Emin Altun","poet_slug":"mehmet-emin-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yerimde-duramiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelsin sen', 'guzelsin-sen-halil-colak-0z0qd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece gündüz hayalimde

Çiçeklerden güzelsin sen

Neşeme neşe katan yarım

Güllerden de güzelsin sen

Hangi yöne baksam sen varsın

Can yoldaşım sevgilim arkadaşım

Sana kollarımı açmış koşuyorum

Orkidedense cananım güzelsin sen

Bak artık zaman bitti

Sensiz ömür boşa gitti

Sakin deme aşklar bitti

Lale sümbülden güzelsin sen 

Gönül yükler kervanını

Her yaşta süreceksin devranını

Okuyacaksın gece gündüz Kuran’ını

Menekşeden daha güzelsin sen

Göremedim ne zamandır ben yüzünü

Beni yaralayan yeşil gözünü

Saramadım kollarımla ince belini

Karanfil, papatyadan aşkım güzelsin sen

Halil Çolak 23.110.2005 Ankara saat.01.15', 'Gece gündüz hayalimde Çiçeklerden güzelsin sen Neşeme neşe katan yarım Güllerden de güzelsin sen Hangi yöne baksam sen varsın Can yoldaşım s...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/guzelsin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Kıyıdan Düşler', 'baska-kiyidan-dusler-birsen-ates-u38tq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gülüşüme aldanma hayat

güzelliğime de

gizledim gölgemi

geri götür beni

tutundum

yüreğimin pervazlarından

sıkı sıkı

aynada bıraktım gözlerimi

gri şehirde yalnızlığımı

garip bir ironi

yapışmış ruhuma

ne kaldı ki

soyut bir tablodan arta kalan

gölgemi kandırıyorum

içinde mavisi çok gökyüzü

bir de deniz çiziyorum

arası beyaz boşluk temiz 

sahte mutluluğum

aldanma

bir adım ilerisindeyim

bu defa senin

görüyorum

maviye tutukluyum nedensiz

lacivert geceye sakladım gözlerimi

hala güneşi arıyor', 'gülüşüme aldanma hayat güzelliğime de gizledim gölgemi geri götür beni tutundum yüreğimin pervazlarından sıkı sıkı aynada bıraktım gözlerimi...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/baska-kiyidan-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turkuaz Mavide Ayrılmak', 'turkuaz-mavide-ayrilmak-meral-vurgun-a3t23', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Abschied in Türkisblau

Ich misstraue mir, wenn es um die Liebe geht

Kalter Wind und kalte Sonne

waschen den Traumsand aus meinem Kopf

Der Küchentisch ist wie die Stadt:

Die unterschiedlichsten Dinge stehen nebeneinander

und nehmen Beziehung auf

Der Sonntag bettet die Stadt wie eine Geliebte

die den Tag verschläft

Das scheppernde Lachen der Trambahn steht

neben dem Kirchengeläut

wie der türkisblaue Himmel über den Dächern

im Norden neben der fahlen Traurigkeit in

deinem Gesicht

Als du zum Abschied in der Tür eines düsteren

Flures deine Hand hebst...

Die Augen brennen an der Luft

Meine Füße führen mich durch die sonntagsträgen

Straßen und Gassen vorbei an den Dingen, die das Leben

nebeneinander in alter Gewohnheit verträumen

hin zu dem, was wir Realität nennen

Im „Scharfen Eck“ lasse ich mich nieder

Das Bier ist mein Goldwasser

Ich misstraue mir, wenn es um die Liebe geht

Ich liebe den goldenen Oktober

und die melancholischen Rauchkringel in dem

Schankraum der Kneipe

Ich liebe die Frauen wie frischen Käse

... ist die Sehnsucht wie ein Muskel, der meine Seele

zusammenpresst

Turkuaz Mavide Ayrılmak

aşka gelince güvensizim kendime

soğuk rüzgar ve soğuk güneş 

yıkıyor kafamdan rüya kumlarını

mutfak masası şehir gibi 

yanyana duruyor farklı şeyler 

ve ilişkili birbirleriyle

bir sevgili gibi yatırıyor şehri 

günü uykuya daldıran pazar 

tramvay raylarının takırdayan gülüşü 

yanında duruyor kilise çanının 

çatılar üzerindeki turkuaz mavi gökyüzü gibi

Kuzey’deki soluklukların yanındaki hüzün

yüzünde senin

ayrılırken, karanlık bir koridorun kapısında 

elini tuttuğunda... 

gözler yanıyor havada 

ayaklarım çekiyor beni pazar tembelliğine 

caddelerden ve çıkmaz sokaklardan hayatın nesnelerine

yanyana eski alışkanlıkların rüyalarında

adına gerçek dediğimiz şeylere doğru

“Scharfen Eck” te salıyorum kendimi derine

bira altın suyum 

aşka gelince güvensizim kendime

altın gibi Ekim’i seviyorum

ve melankolik sigara dumanı halkalarını

meyhanenin dolap gibi köşesinde 

taze peynir gibi seviyorum kadınları

...özlem bir kas

ruhumu sıkıştıran

Ralph Raske

 Çeviri (übersetzt)  Meral Vurgun', 'Abschied in Türkisblau Ich misstraue mir, wenn es um die Liebe geht Kalter Wind und kalte Sonne waschen den Traumsand aus meinem Kopf Der Kü...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/turkuaz-mavide-ayrilmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum’um', 'erzurum-um-halil-colak-5i39h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Erzurum’a lapa lapa kar yağıyor

Gönül her zaman o diyarı arıyor

Dokuz ay beyaz gelinlik giyiyor

Beyaza boyanmış güzel Erzurum

Ağaçlar duvara yaslanmış gelin

Çeşmelerin etrafı buzla örtülmüş

Yollar kardan  kaybolmuş gitmiş

Beyaza boyanmış o güzel Erzurum

Halil Çolak 23.10.2005 Ankara', 'Erzurum’a lapa lapa kar yağıyor Gönül her zaman o diyarı arıyor Dokuz ay beyaz gelinlik giyiyor Beyaza boyanmış güzel Erzurum Ağaçlar duvara...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/erzurum-um-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni bekledim', 'seni-bekledim-mehmet-emin-altun-ob3e3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben hiç gülemedim gülmedim

İyilik nedirgüremedim gürmedim

Rahat huzur bilemedim bilmedim

Sana kalbim yandı heveslendim

En soğuk havalarda bile öşümedim

Nedense hep seni seni bekledim', 'Ben hiç gülemedim gülmedim İyilik nedirgüremedim gürmedim Rahat huzur bilemedim bilmedim Sana kalbim yandı heveslendim En soğuk havalarda bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Altun']::text[], 8.5, '{"poet":"Mehmet Emin Altun","poet_slug":"mehmet-emin-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-bekledim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Şiirini Yaşar', 'sair-siirini-yasar-atilla-guler-nmfsq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sırtlan dişlerini gösterdi gizliden

kimse görmedi/ben gördüm

anlamak istediğince anladığın müddetçe

bu gidiş nereye böyle

sen bilirmişsin doğrusunu

pardon! bilemedim

kırılgan bir yürekte çakarsa şimşekler

kudurur deli çaylar gibi

savurur çağlayanlar

gecelere saklanan bir yarasa ruhu yerleşmiş içine

kör gözler okumayı bilemez ki

anlayamayacağı gibi gerçekleri

çok bilir/çok satarım

çük kafalı birine bularım dışkıyı

sıyrılırım aradan

yaşamın yorgunluğu vurmuşsa yüreğine

çek bir kalem düşlerinin üzerine

sönsün volkanlar

kalem kırıldı

yazdığını yalanlayan bir ruh bedendeki

şiir(in)  öldü/şairin ruhu ince', 'sırtlan dişlerini gösterdi gizliden kimse görmedi/ben gördüm anlamak istediğince anladığın müddetçe bu gidiş nereye böyle sen bilirmişsin do...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sair-siirini-yasar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-ahmet-zeki-karali-lefxh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ilık kadınım

Ağustos sıcağım

Üşüyorum sensiz,

Ayaklarım ve tüm bedenim titriyor

Sensiz bir mezar kadar soğuk evren.

Her yer rutubetli ve ıslak

Bu ıslaklığı yalnızca

Senin nefesin kurutacak', 'Ilık kadınım Ağustos sıcağım Üşüyorum sensiz, Ayaklarım ve tüm bedenim titriyor Sensiz bir mezar kadar soğuk evren. Her yer rutubetli ve ısl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zeki Karali']::text[], 8.5, '{"poet":"Ahmet Zeki Karali","poet_slug":"ahmet-zeki-karali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kadinim-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlgisizlik', 'i-lgisizlik-ahmet-zeki-karali-tke6f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seviyorum seni

Benliğimi titreten güzel

İçim kıpır kıpır seninle dolu

Seni seviyorum

Kalınca felek ben bir başıma

Sanki anılar benimle dansediyor

Seviyorum seni

Keman, çocuk gelişimi,edebiyat, resim,

Telefon, para

Seviyorum seni.

İlgisizlik,

Tapıyorum sana...', 'Seviyorum seni Benliğimi titreten güzel İçim kıpır kıpır seninle dolu Seni seviyorum Kalınca felek ben bir başıma Sanki anılar benimle danse...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zeki Karali']::text[], 8.5, '{"poet":"Ahmet Zeki Karali","poet_slug":"ahmet-zeki-karali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ilgisizlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalından Koparılan Gülümsün', 'dalindan-koparilan-gulumsun-yusuf-ter-zl9g7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dalından koparılan gülümsün

Yaprakları yeşil yeşil dalımsın

Hem kırmızım hem de yeşil alımsın

Ey sevdalım benim güzel çiçeğim

Koklamaya kıyamam ki ben seni

Aşk oduna  düşürürsün sen beni

İsmin bende ama o cismin hani

Ey sevdalım benim güzel çiçeğim

Yusuf Ter  23.10.05

Saat 00:03 İsviçre', 'Dalından koparılan gülümsün Yaprakları yeşil yeşil dalımsın Hem kırmızım hem de yeşil alımsın Ey sevdalım benim güzel çiçeğim Koklamaya kıya...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dalindan-koparilan-gulumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Adam', 'yalniz-adam-ahmet-zeki-karali-eu558', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnız bir adam

Ama yapayalnız

Caddede bakındı etrafına

Tüh... dedi.

Neden dedi acep,

Kimbilir! ...

(1979 Kasım)', 'Yalnız bir adam Ama yapayalnız Caddede bakındı etrafına Tüh... dedi. Neden dedi acep, Kimbilir! ... (1979 Kasım)...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zeki Karali']::text[], 8.5, '{"poet":"Ahmet Zeki Karali","poet_slug":"ahmet-zeki-karali","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalniz-adam-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-ahmet-zeki-karali-g9c36', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İsmi beş harften oluşan sevgilim

Esmerim, birtanem

Bir gün birliktelik 

Yıllara değer

Dolu dolu bir yıl ise

Bir ömre bedel seninle...', 'İsmi beş harften oluşan sevgilim Esmerim, birtanem Bir gün birliktelik  Yıllara değer Dolu dolu bir yıl ise Bir ömre bedel seninle......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zeki Karali']::text[], 8.5, '{"poet":"Ahmet Zeki Karali","poet_slug":"ahmet-zeki-karali","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevgiliye-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Ne Ola ki...', 'mutluluk-ne-ola-ki-ulug-celik-ul79l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce evlendiğimizde hayatın daha iyi olacağına inandırırız kendimizi.

Evlendikten sonra, bir çocuğumuz doğduktan hatta ardından bir tane daha olduktan

sonra hayatın daha iyi olacağına inandırırız kendimizi.  Sonra çocuklar

yeterince büyük olmadıkları icin kızar, onlar büyüyünce daha mutlu olacağımıza

inanırız.  Bundan sonra, ergenlik dönemlerinde çocuklarla uğraşmamız gerektiği

için öfkeleniriz.  Kendimize, çocuklarımız bu donemden çıkınca daha mutlu

olacağımızı, yeni bir araba alınca, güzel bir tatile çıkınca, emekli olunca,

yaşantımızın dört dortluk olacağını söyleriz.  Gerçek ise şu andan daha iyi bir

zaman olmadığıdır.  Eğer şimdi değil ise ne zaman? ... Hayatınız her zaman

mücadelelerle dolu olacaktır.  En iyisi bunu kabul edip her ne olursa olsun

mutlu olmaya karar vermektir.  En sevdiğim sözlerden biri Alfred D.  Souza'' ya

aittir.  Der ki; ''Uzun zamandan beridir hayatın -gerçek hayatın- başlamak üzere

olduğu izlenimine kapılmıştım.  Fakat her zaman yolumun üzerinde bir engel,

oncelikle erişilmesi gereken birşey, bitmemiş bir iş, hizmet edilecek zaman,

ödenecek bir borç oldu.  Sonra hayat başlayacaktı.  Sonunda anladım ki bu

engeller benim hayatımdı.'' Bu görüş açısı, mutluluğa giden bir yol olmadığını

gösterdi.  Mutluluk yoldur, öyleyse sahip olduğunuz her anın kıymetini bilin ve

mutluluğu, vaktinizi harcayacak kadar özel biriyle paylaştığınız için, ona daha

fazla değer verin. Unutmayın, zaman hiç kimse için beklemez.  Öyleyse; Okulu

bitirene kadar, 100 milyar kazanana kadar, Çocuklarınız olana kadar,

Çocuklarınız evden ayrılana kadar, Işe başlayana kadar, Evlenene kadar, Cuma

gecesine kadar, Pazar sabahına kadar, Yeni bir araba, ya da ev alana kadar,

Borçları ödeyene kadar, İlkbahara kadar, Yaza kadar, Sonbahara kadar, Kışa

kadar, Maaş gününe kadar, Şarkınız söylenene kadar, Emekli olana kadar, Ölene

kadar.....

MUTLU OLMAK İÇİN İÇİNDE BULUNDUĞUNUZ ''AN'' DAN DAHA İYİ

BİR ZAMAN OLDUĞUNA KARAR VERMEK İÇİN BEKLEMEKTEN VAZGEÇİN.

MUTLULUK BIR VARIŞ DEĞİL, BİR YOLCULUKTUR.

''PEK ÇOKLARI MUTLULUĞU İNSANDAN DAHA YÜKSEKTE ARARLAR,

BAZILARI DA DAHA ALCAKTA.  OYSA MUTLULUK İNSANIN BOYU HİZASINDADIR.''

Unutmayin ''YARIN KIMSEYE VAAD EDILMEMISTIR''', 'Önce evlendiğimizde hayatın daha iyi olacağına inandırırız kendimizi. Evlendikten sonra, bir çocuğumuz doğduktan hatta ardından bir tane dah...', ARRAY['Türk Edebiyatı','Şiir','Uluğ Çelik']::text[], 8.5, '{"poet":"Uluğ Çelik","poet_slug":"ulug-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/mutluluk-ne-ola-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Babam Da Gelir Bu Düğüne', 'belki-babam-da-gelir-bu-dugune-mehmet-sah-erincik-yrq95', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yazamadığım zamanlar için süzülüyorum içeri, damla damla veremle 

korkunun kollarına atlıyorum birdenbire öksürerek 

Atıyorum bu geçimsiz nesneleri içine dünlerin, bu her şeyleri, kitapları 

ve yakmak eylemi Yeni bir hal alıyor sancılı kaldığım her dönemeçte, 

şimdi sen ey kuş olacak güzel 

yaktığım kitapların hangi sayfasında kaldın

dosdoğru gidilen bir yola sapıyor bu savaş, bu dermansız soluklar 

Uzayan bir şey için uzayan bir ömür, sevişmek kalkıyor aramızdan 

aramıza bir cumhuriyet giriyor, leylakları soruyoruz biz o zaman 

biz o zaman Cummings okuyoruz sonra ansızın biraz da şaşırtarak 

bir mısranın derinliklerinde Cumnings, Kafka oluveriyor iyi mi? 

artık Kalk bize gidelim, bir çay kesinlikle iyi gelir bir sigara daha iyi 

Durulanıyor zaman aşkın kollarında biz duruyoruz bak şekiller elips 

şakaklarım iyiden iyiye çöküyor mor şarkılar gözlerimin siperi 

her şeyi bırak, biz biz olalım şu zamanın yakımında

derdime babam geldiği zaman anlaşılır dinlediğimiz şarkılar

Hayatın dışında bir yerdeyim, gişelerde arabalar ve yollar dolanıyor birbirine 

Ben bu özlemekleri anlamıyorum, bu hayatları bu kullanım ücretlerini son sürat 

Bir araba çarpsın diyorum, yüzümü parça parça etsin o köpek 

Ve birden ortaya atlıyor bir nergis, dur atlama boğulur gidersin 

Dur ne olur atlama, bildiğinin ötesinde her şey, sen ey kuş olacak güzel 

Buralarda kızlar hemen kaybolur, şimdi kimi sevsem 

Böyle ağlamaklı bir aşk gibi 

Düğünsüz bir ev nasıl kursam, yapmacıksız bir gülümsemedir buradan oraya evlenmem 

Şimdi geçmişlere özeniyorum yalnızlık burgaçlarında, dördü bende beş big beng… 

Artık  her mısrada bir dağ, alıp beni senden uzaklara

Kötü ve korkak bir şey oluyorum şu karanlığın en küskün noktasında

Mesela sen adımını atınca yüreğim titriyor ve şarkılarda çılgın bir Bon Jovi hey 

Yazamamak bir daha giriyor devreye, bir kuş kanat çırpıyor kenarlarına doğmanın 

Babam geliyor başköşesine bu düğünün, ben oldukça şaşkın ve kediler 

Mermerlere yanaşıyor, ölmek bağrını açıyor toprağa, sevişmek kalkıyor aramızdan 

Nasıl kalkıyorsa, işte bir dert toparlanıyor içimde, bir avuntu darmadağın 

Bir kötü şair oluyorum, yırtıyorum şiirlerimi bir bir, Bak! Bu Yak devrede 

‘Ben korkağın tekiyim’ bunu bildikçe içimde kanatlanıyor mutluluk atı 

‘Sen korkağın tekisin’ bunu bildikçe içim o nergise benziyor 

Durma at kendini ortaya durma boğulup git içimde', 'Yazamadığım zamanlar için süzülüyorum içeri, damla damla veremle  korkunun kollarına atlıyorum birdenbire öksürerek  Atıyorum bu geçimsiz ne...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şah Erincik']::text[], 8.5, '{"poet":"Mehmet Şah Erincik","poet_slug":"mehmet-sah-erincik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/belki-babam-da-gelir-bu-dugune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-aysel-zengingul-g4bsy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şehirler dolusu,

Sokaklar dolusu,

Caddeler dolusu,

İnsan iskeletleri..

Yürüyorlar, koşuyorlar,

Bakıyorlar, gülüyorlar…

Kalabalıkmış gibi görünüyorlar,

Kendilerinden habersiz…

21/10/2005 istanbul   04; 47', 'Şehirler dolusu, Sokaklar dolusu, Caddeler dolusu, İnsan iskeletleri.. Yürüyorlar, koşuyorlar, Bakıyorlar, gülüyorlar… Kalabalıkmış gibi gör...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/insanlar-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-aysel-zengingul-ro2uu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni seviyormuş…

Hadi adam sen de! 

Seviyorsun madem; 

Neden hala yoksun…

13/10/2005 ist.  20; 20', 'Beni seviyormuş… Hadi adam sen de!  Seviyorsun madem;  Neden hala yoksun… 13/10/2005 ist.  20; 20...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/celiski-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-aysel-zengingul-b4d7f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir çok şair var tanıdığım.

Hepsinin de sohbetleri sıkıcı…

Şimdi düşünüyorum da; 

Onların ruhları,

Kalemlerinde asılı…

16/10/2005 ist.03; 05', 'Bir çok şair var tanıdığım. Hepsinin de sohbetleri sıkıcı… Şimdi düşünüyorum da;  Onların ruhları, Kalemlerinde asılı… 16/10/2005 ist.03; 05...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sitem-195-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar', 'kuslar-basak-hilal-wyeqv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuşlar…

Beni de alın yanınıza…

Kanatlarınızın altına alın beni ve götürün sevdiğime…

Uçurun beni onun yanına… 

Özlemim dinsin kollarında,

Avunsun ellerim avuçlarının içinde….

Uçurun beni kuşlar…

Sevdiğime götürün beni…

Gözlerimiz kenetlensin birbirine,

Dudaklarından kulaklarıma aşk sözcükleri dökülsün yavaş yavaş…

Çiseleyen yağmur gibi  fısıldayalım aşkımızı birbirimize….

Yağmur damlaları seller oluştursun etrafımızda, 

Ve götürsün bizi uzaklara…

Kavuşturun bizi kuşlar… 

Yolları, dağları,taşları aşıp bırakın aşkımın kollarına…

Giderken ona aşkımı  haykırayım göklere sizinle birlikte…

Bütün alem duysun kavuşacağımızı… 

Bütün evren sevinsin bizim için…

Kutlasınlar kavuşma anımızı..

Rüzgar essin, deniz dalgalansın. 

Yapraklar dans etsin rüzgarın ritmiyle…

Biz sarılalım birbirimize,

Ve aynı anda şarkı söyleyin bize kuşlar…

Bizim için ötün hep birlikte…

Siz koloni halinde devam ederken yolunuza,

Bizde aşk pınarımızda kaybolalım…

Aşkımızı haykırdığımız anda 

Sizde aşkımızı anlatmak için başka başka yerlere gidin,

Duyurun sesimizi duymayanlara…

Duyurun sevgimizi aşktan anlayanlara…', 'Kuşlar… Beni de alın yanınıza… Kanatlarınızın altına alın beni ve götürün sevdiğime… Uçurun beni onun yanına…  Özlemim dinsin kollarında, Av...', ARRAY['Türk Edebiyatı','Şiir','Başak Hilal']::text[], 8.5, '{"poet":"Başak Hilal","poet_slug":"basak-hilal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kuslar-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki - II', 'celiski-ii-aysel-zengingul-6c1wu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'içi olgun meyva,

dışı kabak misali,

bi çelişki var bu dünyada…

yaşamın içindesin,

ama yaşam senin dışında…

13/10/2005 ist.02; 47', 'içi olgun meyva, dışı kabak misali, bi çelişki var bu dünyada… yaşamın içindesin, ama yaşam senin dışında… 13/10/2005 ist.02; 47...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/celiski-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki - III', 'celiski-iii-aysel-zengingul-oem13', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'baktı 

gözlerime,

      öylece baktı…

giden benmişim gibi…

13/10/2005 ist.02; 30', 'baktı  gözlerime,       öylece baktı… giden benmişim gibi… 13/10/2005 ist.02; 30...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/celiski-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Sana Geldim', 'yine-sana-geldim-burhanettin-akdag-sz1li', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgilim, sana günaydın demeye geldim				

Sabah oldu yeniden, güneş bile uyandı, esniyor				

Hadi sen de uyan uykundan, kalk artık				

Gülümse bana gözlerinle, hayallerine gireyim				

Bak, işte ben yine sana geldim…				

				

Elbiseni de getirdim bugün, mavi olanını				

Hani sana çok yakışan, en çok sevdiğin				

Tarağını da unutmadım bak, yanımda getirdim				

Hadi doğrul artık da, tarayayım saçını				

Bak, işte ben yine sana geldim…				

				

Aşkım, hırkanı da getirdim bugün, unutmadım				

Havalar da serinledi zaten, bu aralar				

Mermer çok soğuktur şimdi, buz gibidir				

Üşümüşsündür de şimdi sen				

Hadi doğrul da, giydireyim seni				

Bak, işte ben yine sana geldim…				

 				

Sevgilim, bugün gözlerimi de getirdim sana				

Hani, daralınca, birlikte ağlardık ya				

Yine burkuldu içim acınla, hüzünlendim birazcık				

Toprağın da kurumuştur şimdi senin				

Hadi uzan da yıkayayım günahsız yüreğini, yaşlarımla				

Bembeyaz, saf, ama kadersiz kaderini				

Bak, işte ben yine sana geldim…				

 				

Güzelim, tatlım, sevda ateşim				

Üşüyorum sensiz, soğudum artık hayattan				

Yaşamıyor kalbim, küt küt atıyor yalnızca				

Görmüyor gözlerim, istemiyor artık sensiz dünyayı				

O büyük afette yıkılan evimizin enkazında takılı, yıllardır				

Duymuyor yüreğim, yok olmuş zaman kavramı				

Adımlarımı bile ezberledim, tam üçyüz elli iki adım				

Başka mekan bilmiyorum ki artık, durdu beynim				

Bak, işte ben yine sana geldim…				

 				

Tebessüm ediyordun en son, kucağıma aldığımda				

Sanki, ilk evlendiğimiz günkü gibiydin, umutlu				

Oysa sonun başına gelmiş de, gidiyordun bensiz				

İstemiyordun bırakmayı, ayrılmak istemedin benden				

Ama dediler ki, sen artık kalamazmışsın bende				

Ebeden selvi ağacı bekçilik edecekmiş sana				

Peşinden ben de geliyorum hergün				

Sen bir kez öldün, bense her şafakta yeniden 				

Bak, işte ben yine sana geldim…				

 				

Sevgilim, aşkım, sevdalım, iki gözüm				

Bak, işte ben yine geldim, yanındayım				

Ama bu sefer dönmeyeceğim artık,  geriye				

Ne zaman alacaksın beni yanına, güzel kadınım				

Artık sende kalmaya geldim, kalmakta kararlıyım				

Nefes almak bile zor geliyor bedenime				

Dizlerim taşımıyor artık, gidip gelmelerden yorgun				

Uzat artık kollarını, al artık yanına beni				

Bak, işte ben yine sana geldim…	

(23.10.2005)', 'Sevgilim, sana günaydın demeye geldim				 Sabah oldu yeniden, güneş bile uyandı, esniyor				 Hadi sen de uyan uykundan, kalk artık				 Gülüm...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/yine-sana-geldim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renkler', 'renkler-vedat-okkar-i4wpy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece dışarıda bir ayaz 

İnsanlar 

Aşk''ları 

Sevgileri 

Ne kadar da beyaz 

Bir bulut geçiyor sanki 

İçimizdeki 

Beynimizdeki 

Ellerimizdeki 

Bazen var, bazen yok olan mutluluk gibi mavi 

Nedir bu kızların tasaları 

Umudumuza engel yasaları 

Bakışları 

Var oluşları 

Benzin gibi sap sarı 

Benim Gönlüm bu gecede sende 

Masallar, 

Hatıralar, 

Hikayeler, 

Çoğu zaman hep pembe 

Yarınlarda ki gelecek nesil 

Cocuklar, 

Ağaçlar, 

Umutla yarınlara baktığım gözlerim gibi yeşil', 'Bu gece dışarıda bir ayaz  İnsanlar  Aşk''ları  Sevgileri  Ne kadar da beyaz  Bir bulut geçiyor sanki  İçimizdeki  Beynimizdeki  Ellerimizdek...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/renkler-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik ne zormuş', 'sensizlik-ne-zormus-vedat-okkar-tqfbe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizlik ne zormuş, bunu şimdi anladım 

Gözlerin aklıma gelince ağladım 

Senden ayrılalı uzun zaman oldu 

Geceleri yastığım gözyaşımla doldu 

Sıgaramın tadı yok, meyhaneler evim oldu 

Bir kadeh biterken diğeri doldu 

Gelen geçen üzüntülü bir gözle bana sordu 

Bu acı neden sana böyle ne oldu 

Ben her gece gözyalarımla umudumu yıkarken 

Oysa ki ölüm bana daha çok erken 

Bugün de seni sevdiğimi söylerken 

Senin bu kaçışların neden', 'Sensizlik ne zormuş, bunu şimdi anladım  Gözlerin aklıma gelince ağladım  Senden ayrılalı uzun zaman oldu  Geceleri yastığım gözyaşımla dold...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizlik-ne-zormus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kokusu kalır', 'kokusu-kalir-vedat-okkar-1d7ql', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gül tuttu ellerim 

Ne kadar dikeni olsada benim onu bırakmak istemeyişim 

İçime çekerek koklayışlarım 

Her gece ona bakışlarım 

Karşılıksız sevişlerimle dopdoluydu 

Benim onu her tutuşumda 

Gülün benden uzaklaşması 

Dikenlerinin acısını artırışı 

Benden kaçışı gönlümün hüznünün artmasıydı 

Oysaki güzelim bir kere tuttum bu gülü 

Sen ne kadar benden kaçsanda 

Ne kadar uzaklara gitsende 

Gül gider ama kokusu hep ellerimde kalır.', 'Bir gül tuttu ellerim  Ne kadar dikeni olsada benim onu bırakmak istemeyişim  İçime çekerek koklayışlarım  Her gece ona bakışlarım  Karşılık...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kokusu-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıplara Karıştık', 'kayiplara-karistik-hikmet-uzun-zcaqk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hedef olduk aşk okuna,can evinden vurulduk. 

Düşmek için yar peşine,bir yay gibi kurulduk.

Seller gibi çağladıkda,deniz olduk durulduk.

Karıştık kayıplara,ne arandık ne sorulduk.', 'Hedef olduk aşk okuna,can evinden vurulduk.  Düşmek için yar peşine,bir yay gibi kurulduk. Seller gibi çağladıkda,deniz olduk durulduk. Karı...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Uzun']::text[], 8.5, '{"poet":"Hikmet Uzun","poet_slug":"hikmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kayiplara-karistik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem deyipte geçme', 'kalem-deyipte-gecme-mikdat-bal-ain60', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalemin uçu nokta, kıvranır yazı olur

Kalemşörün aleti, kemence sazı olur

Söz harflere dönüşür, yazarın ağzı olur

Kalem deyipte geçme, kılıcı sollamıştır

Nice kalem tutanı, zindana yollamıştır

Kalemdir açıklayan, kalemdir izah eden

Kalemdir rüşvay eden kalemdir mizah eden

Kalemdir hakkı yazan, kalemdir ıslah eden

Kalem deyipte geçme, kılıcı sollamıştır

Nice kralı tahtıyla, yerinden sallamıştır', 'Kalemin uçu nokta, kıvranır yazı olur Kalemşörün aleti, kemence sazı olur Söz harflere dönüşür, yazarın ağzı olur Kalem deyipte geçme, kılıc...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kalem-deyipte-gecme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyordum ama gene şaşırdım Doslara mektuba gelen cevaplar üzerine', 'biliyordum-ama-gene-sasirdim-doslara-mektuba-gelen-cevaplar-uzerine-mikdat-bal-q793d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aldığım haberler ağlattı beni

Biliyordum ama gene şaşırdım

Gurbete sımsıkı bağlattı beni

Biliyordum ama gene şaşırdım

Değişen bir şey yok, halk aman diyor

Buna alışmıştır her zaman diyor

Ancak sabrı bitmiş el aman diyor

Biliyordum ama gene şaşırdım

Yok mu bu millete nefes verdiren

Yok mudur bu zulmü sona erdiren

Raydan çıktı kaza yaptı her tiren

Biliyordum ama gene şaşırdım

Baş köşeyi tutmuş üç kağıtçılar

Çoğalmış zalime itaatçılar

Bitirdi bütçeyi kaptı kaçtılar

Biliyordum ama gene şaşırdım

Enflasyon düşmüşse bakın illete

Satın alma gücü yoktur millette

Bizler layık mıydık böyle zillete

Biliyordum ama gene şaşırdım

Mikdat Bal kalkıpta neyi sorarmış? 

Açlar çöplüklerde ekmek ararmış

Para yok ucuzluk neye yararmış

Biliyordum ama gene şaşırdım', 'Aldığım haberler ağlattı beni Biliyordum ama gene şaşırdım Gurbete sımsıkı bağlattı beni Biliyordum ama gene şaşırdım Değişen bir şey yok, h...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/biliyordum-ama-gene-sasirdim-doslara-mektuba-gelen-cevaplar-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçegim', 'cicegim-ali-aydogan-os2i7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen Benden Gidiyorsun ÖyLemi

Hemde Ardına Hiç Bakmadan

Kalbimden Kalbimi Koparıp

Dur Diyemem Dilim TutuLur Çiçegim

AnıLarımızıda Götürüyorsun  ÖyLemi

Bilinmez Bir Şehrin Sabahına

Beni AteşLere Atıp ÖyLemi

Dur Diyemem Dilim TutuLur Çiçegim

Yüregimide Götür Gittigin Yere

GözLerin Kalsın GözLerimde

Beni HayaLinsiz Bırakıyorsun ÖyLemi

Dur Diyemem Dilim TutuLur Çiçegim

MutLuLukLar SeninLe oLsun İsterim

SevmeLer SeninLe GüzeLLikLer Seninle 

Bir Adın Kalsın DudakLarımda Git Gideceksen 

Dur Diyemem Dilim TutuLur Çiçegim', 'Sen Benden Gidiyorsun ÖyLemi Hemde Ardına Hiç Bakmadan Kalbimden Kalbimi Koparıp Dur Diyemem Dilim TutuLur Çiçegim AnıLarımızıda Götürüyorsu...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydogan']::text[], 8.5, '{"poet":"Ali Aydogan","poet_slug":"ali-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cicegim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavna', 'mavna-bulent-guldal-im3x1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saçlarını tarayarak yüzlerce yılın

külhan aşkları besleyerek koynunda

tanrıya akran zamandan geliyor

Ne suyun farkında ayışığının ne de 

akıyor dağların içli sesiyle

yorgun mu desek tükenmiş mi yoksa

Döndüğü kıvrımların ucu uçurum

girdaplarda boğuldu boğulacak

yolcuları bitkin rota sormaktan

İş bilmez dümenciler elinden aman

iniltiler içinde korsan kayalarında

tufanlara kafa tutan hüzünlü mavna

Kalbine iniyor kanlı baltalar

sırtlan yuvaları şölen sofrası

kanlı rüzgarlar esiyor konaklardan

İlmeği senin motifi benimdi

elbirliğiyle dokunan kilim bizimdi

satıyorlar şimdi aymaz kaptanlar

Sinmişliğin altında uyuyan dev

yekinmeleri görüyor düşlerinde

''Darağacında Üç Fidan''ın haykırışını

Sırmalarını bir kir gibi fırlatan

daha da gerilerde Mustafa Kemal''i

çağırıyor kurtuluşun şafağına

Depremler yaratacak silkinişiyle

uyanır koca dev yüzer bu mavna

tüneklerinde boğulur alıcı kuşlar

Koltuk sevdaları kor ateş olur

firar planlarıyla yatıp kalkarlar

korsandan dönme kirli kaptanlar', 'Saçlarını tarayarak yüzlerce yılın külhan aşkları besleyerek koynunda tanrıya akran zamandan geliyor Ne suyun farkında ayışığının ne de  akı...', ARRAY['Türk Edebiyatı','Şiir','Bülent Güldal']::text[], 8.5, '{"poet":"Bülent Güldal","poet_slug":"bulent-guldal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mavna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Bir Yanım.', 'bir-yanim-tevfik-mengulluoglu-ox5tw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin zehirli yüzüne ışık tutuyor,

saçlarının gölgesinde,bir kumru gibi

tüneyen gözlerin...

Bu yüzden bakamıyorum işte.

Her nefes alışında 

ciğerimdeki oksijen, 

Tükenecek gibi oluyor! 

Kuş olup uçacak,kanatlarının 

Arasında,dağılacak soluğumun 

yankısı...

Kah düşüyorum,kah kalkıyorum.

Yüreğimin tellerine 

vurduğun her mızrap, 

ayrı bir bestesini nakşediyor, 

vuslat arzusunun...

Beynimin labirentlerinde dolaşan, 

Cümlelerle,tehlikeli oyunlar 

oynuyor kalbim...

Yazdığım bütün mısralarda,

namlunun ucuna sürülmüş, 

bir deyim gözler menzilini.

Seviyorum seni...', 'Gecenin zehirli yüzüne ışık tutuyor, saçlarının gölgesinde,bir kumru gibi tüneyen gözlerin... Bu yüzden bakamıyorum işte. Her nefes alışında...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-yanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**(*) Kıskanırım (*) **', 'kiskanirim-i-brahim-dikmen-2-4chh6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben seni,yağmurlardan

Sevda yüklü,bulutlardan

Kıskanırım,yıldızlardan

Hüzün saklı,hazanlardan

Düşlerimden,kıskanırım.

23/10/2005', 'Ben seni,yağmurlardan Sevda yüklü,bulutlardan Kıskanırım,yıldızlardan Hüzün saklı,hazanlardan Düşlerimden,kıskanırım. 23/10/2005...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kiskanirim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Hedef *', 'hedef-enver-herguler-7ahzt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluğu aradım aydınlıklarda

Bulamadığımdandır ki

Biçareyim, halim perişan.

Yarasa olmak  varmış

Zifiri karanlıklarda dahi

Hedefine mutlak ulaşan.', 'Mutluluğu aradım aydınlıklarda Bulamadığımdandır ki Biçareyim, halim perişan. Yarasa olmak  varmış Zifiri karanlıklarda dahi Hedefine mutlak...', ARRAY['Türk Edebiyatı','Şiir','Enver Hergüler']::text[], 8.5, '{"poet":"Enver Hergüler","poet_slug":"enver-herguler","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hedef-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşerim Senin Aşkına', 'duserim-senin-askina-mehmet-sait-akkus-547to', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kara gözlüm seline

Düştüm aşkın seline

Sanki yağmur seline

Kapıldım senin aşkına

Ben seveli kaç yıl oldu

Tükendim ben sabrım doldu

Bak ektiğim güller soldu

Eririm senin aşkına

Seviyorum bilen yokki

Halimden anlayan yokki

Seni seven bak diyorki

Ölürüm senin aşkına

Olacaksa olsun artık

Saatleri güne sattık

Bütün köprüleri attık

Düşerim senin aşkına', 'Kara gözlüm seline Düştüm aşkın seline Sanki yağmur seline Kapıldım senin aşkına Ben seveli kaç yıl oldu Tükendim ben sabrım doldu Bak ektiğ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duserim-senin-askina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evimi Çok Özledim', 'evimi-cok-ozledim-munevver-senol-hdoau', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimi zaman üzülüp, kimi zaman sevinsem de.

                   Hani şöyle bir dalıp, eskileri düşünsem de.

                   Geceleri yatağımda gözyaşımı gizlesemde.

                    Tutmayın, bırakın beni, evime gitmek istiyorum.

                    Evime gitmek istiyorum, 

Çünki evimi çok özledim.

                    Özledim, dostlarımı, hatta olmayanları da.

                     Körfezin kokusunu, kafesteki kuşumu,.

                     Kapıdaki tekiri, 

Tekirr kız seni bile özledim.

                     Evi otel gibi kullanan, bir işin bile  ucundan tutmayan.

                     Yaralı parmağa bile etmeyen.

                     Etkisiz eleman, seni bile özledim.

                     Şimdi göçebe kuşlar gibiyim, 

Kah ordayım, kah burdayım.

                      Tutmayın, bırakın beni, evime gitmek istiyorum.

                      Evime gitmek istiyorum.

Çünki evimi çok özledim. 

                        14.8.2000', 'Kimi zaman üzülüp, kimi zaman sevinsem de.                    Hani şöyle bir dalıp, eskileri düşünsem de.                    Geceleri yatağı...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/evimi-cok-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piyonlar...', 'piyonlar-neslihan-i-sler-rrz6t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Piyonlar

Evet bitti sonunda bu oyunda en kötü sonla

Belkide başladığından daha derin bir noktada

Bizler sadece bir piyonduk aslında

Peki kim mat oldu veya şah oldu sonunda

Aslında  farketmez bu sonun sonu nasıl olsa

Bazı kumarbazlar vardır görmek istemez ya...

Sadece kendinden intikam alır dibe vurdugunda

Hep kazanmaya oynar her hamle yapışında

Her oyunun bir kaybedeni olur bir tek vuruşta

Kazanan kim tüm kozlarını koyan mı yoksa 

Sinsice yaklaşıp son darbede hazmı duyanda

Bilmiyorum  vahşice bir zevk tutkunumu

Yoksa kirlenmişliğin içinde depelenen bir son vuruşmu

Farketmeyecek artık hiçbir zaman bilemeyecek nerde son buldu

Bir tutku oyununa yenik intikamın acı sonu

HAYAT DENEYIMLERDEN IBARET

NE USTUNE CIKABILIRSIN HAYATIN

NE DE OLABILDIGINCE DIBE BATARSIN....', 'Piyonlar Evet bitti sonunda bu oyunda en kötü sonla Belkide başladığından daha derin bir noktada Bizler sadece bir piyonduk aslında Peki kim...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/piyonlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demokrasi Adına...', 'demokrasi-adina-alper-kuruk-csirc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kişiyle düzelmez yurdumun pis işleri,

Çıkar gruplarının egemen oluşları.

Seçim adı altında bu gidiş-gelişleri

Yıllar sürdü, sürecek,bitmez var oluşları.

Hani,demokraside çoğunluk yönetirdi? 

Öyle bir sistem bulduk kendisini bitirdi,

Yönetime dâima azınlıklar getirdi,

Şehir kendi yarattı bu tümör varoşları.

Orta yerde duruyor fırından çıkmış börek

Bu böreğin çoğunu sıcakken yemek gerek,

Çok parçaya bölersen soğutursun bilerek,

Sal ortaya,kartalın parçalasın kuşları...

Dünyanın düzeni  bu:herkes birbirini yer,

Büyük küçüğü yutar,küçük,didik didikler,

Para ile kudreti elde etmişse eğer

Düzleri yokuş eder, düz eder yokuşları...', 'Bir kişiyle düzelmez yurdumun pis işleri, Çıkar gruplarının egemen oluşları. Seçim adı altında bu gidiş-gelişleri Yıllar sürdü, sürecek,bitm...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/demokrasi-adina-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyasal Sülükler', 'siyasal-sulukler-alper-kuruk-jgppo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanın vazgeçilmez hakkıdır özgürlükler,

Ulusun belâsı,bazı siyasal sülükler...

Ensemize yapışıp kanımızı emiyor

Doyunca şişip şişip,çatlayıp geberiyor.

Sonu yok bu zincirin,bir gitse beş geliyor

Eksildikçe büyüyor,koptukça ekleniyor...

Sırtlarda yükseliyor,kanımızla yaşıyor,

Bedenler bu kamburu sevâp diye taşıyor.

Demokrasi adına kurulmuş ''Tahta At''tan

Kurtuluş yok ne yapsak siyasal hacımattan.

Şükür ki bîteviye emdiği pis kanımız

Yoksa dayanır mıydı bu emişe canımız? 

Kanımız temizlenir,yenilenir diyerek

Sülükleri ensede taşımaya ne gerek? 

Toplumca bilinçlenip arı kan yaratalım

Artık bu sülükleri üstümüzden atalım.

Bunun tek bir yolu var: hakka saygılı olmak,

Sınırları aşmadan özgürlüklerle dolmak...

Yaşam fırsatı kalmaz,bu başarıldığı an

Siyasal sülüklere kalmaz emilecek kan...', 'İnsanın vazgeçilmez hakkıdır özgürlükler, Ulusun belâsı,bazı siyasal sülükler... Ensemize yapışıp kanımızı emiyor Doyunca şişip şişip,çatlay...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siyasal-sulukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercinler Ve Yemciler', 'guvercinler-ve-yemciler-alper-kuruk-k2jun', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gittim ''Yeni Cami''ye

Kuş yemi aldım yemciden.

Güvercinler tarla oldu

Çiftçi de ben...

Birkaç avuç yem attım

İki aç boğaz kapattım.', 'Gittim ''Yeni Cami''ye Kuş yemi aldım yemciden. Güvercinler tarla oldu Çiftçi de ben... Birkaç avuç yem attım İki aç boğaz kapattım....', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/guvercinler-ve-yemciler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Sofrasında', 'aksam-sofrasinda-rifki-kaymaz-h99p8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her akşam sofrada beraber olur, 

Akşam yemeğini birlikte yeriz. 

Ve sonra açarak ellerimizi, 

“Çok şükür Ya Rabb’i! ” 

“Çok şükür! ” deriz. 



Nasıl anlatayım bilmem sizlere, 

Bizim soframızda bin bereket var. 

Soframızda paylaşırız her şeyi, 

Babamın yorgunluğu birden azalır. 

Annemin sevgisi sofraya taşar. 

Her pazar birlikte çıkarız babamla, 

Pazardan yiyecek şeyler alırız. 

Annem sevgiyle pişirir yemekleri, 

Öylesine tatlı, öylesine lezzetli ki, 

Bayılırız. 

İsterim her yemek vaktinde yine, 

Her sofrada bir araya gelmeyi. 

Ne var ki babam işe gider erkenden, 

Ben kardeşimle okula. 

Annem bizleri yolcu eder her sabah, 

Unutmaz öpmeyi, gülümsemeyi. 

Dilerim sonsuza değin mutluluk, 

Evimizde sevgi hiç eksilmesin. 

İsterim herkesin sofrası da, 

Bezenerek sevgiyle, 

Bizimkine benzesin.', 'Her akşam sofrada beraber olur,  Akşam yemeğini birlikte yeriz.  Ve sonra açarak ellerimizi,  “Çok şükür Ya Rabb’i! ”  “Çok şükür! ” deriz. ...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aksam-sofrasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy Kahvesi', 'koy-kahvesi-alper-kuruk-5feqs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dışarda soğuk,içerde sıcak

Buzlu cam gibi olmuş camlar.

Acı rüzgârın zehrini akıtıyor

Parmaklarını sıkarak

Kahveye giren adamlar.

Ağası,çiftçisi,çobanı gelmiş kahveye

Kimi altmış altı atıyor köşede,

Kimi dinliyor ağaların sohbetini,

Kimi arıyor ocak başında bucak...

Tavla,domino taşlarının şıkırtısına 

Katılıyor ağaların sesleri,

Hamama döndürüyor odayı

Sigara dumanıyla karışık

Sıcak nefesleri.

Köyde olup bitenler...

Yosmalarla yiğitlerin aşk hikâyeleri...

Geçmişe ait efsâneler

Dökülüyor ağaların ağzından,

Kahvenin dumanlı havasına.

Şu çatı altında duyulan sesler

Açılan ağızlar hep ağaların,

Nasıl ki dağda,ovada,açık havada 

Kavalı dinlenirse sadece çobanların...', 'Dışarda soğuk,içerde sıcak Buzlu cam gibi olmuş camlar. Acı rüzgârın zehrini akıtıyor Parmaklarını sıkarak Kahveye giren adamlar. Ağası,çift...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/koy-kahvesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 53', 'resaran-siir-ve-beyitsiler-53-huseyin-avdic-75nwb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görünmeyen Varlar İnkâr Edilmez

Lambadaki ışığın ruhudur, tinidir ceryan, gözle görülmez.

''Konuşan Sen''deki ışığın ceryanı da ruh''tur, inkâr edilmez.

******

Gözle Görülmeyene İnanmalısın

Allah da bir ruh gibidir, gözle görülmez.

''Gözle görülmüyor'' diye, inkâr edilmez.

******

Ölümsüzlük İstersen

Ölümün yok ediciliğine razı olma arkadaş.

Din ve inanç, ölümsüzlüğü kazandıracak bir araç.

Berlin, Ekim 2005.', 'Görünmeyen Varlar İnkâr Edilmez Lambadaki ışığın ruhudur, tinidir ceryan, gözle görülmez. ''Konuşan Sen''deki ışığın ceryanı da ruh''tur, inkâr...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/resarani-siir-ve-beyitsiler-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgem', 'golgem-alper-kuruk-i157z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabah küçültür beni gölgem

Küçüklük çöker ruhuma.

Öğleden sonra büyültür

Haddimden fazla.

Set çekilmez olur 

Artık gururuma.

Gece olur

Başım bu dertten kurtulur.

Gölgemle kaybolur

Küçüklüğüm,gururum,

Sıyrılır çıkar meydana 

Gerçek,mütevazi vücudum...', 'Sabah küçültür beni gölgem Küçüklük çöker ruhuma. Öğleden sonra büyültür Haddimden fazla. Set çekilmez olur  Artık gururuma. Gece olur Başım...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/golgem-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döngü', 'dongu-huseyin-ciplak-001p0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne denli romantik,

Duygu dolu.

Duyguların yörüngesinde,

Sevdalara dönelim.

Sevdanın yumuşacık yüreği,

Bir ana kucağı gibi,

Sımsıcak bizleri kucaklamaya hazır.

O sevdanın iklimi

Yaşamak nasıl olurki,

Bir bile bilsen.

Ancak payımıza düşen,

Sisler bulvarı gibi...', 'Ne denli romantik, Duygu dolu. Duyguların yörüngesinde, Sevdalara dönelim. Sevdanın yumuşacık yüreği, Bir ana kucağı gibi, Sımsıcak bizleri ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çıplak']::text[], 8.5, '{"poet":"Hüseyin Çıplak","poet_slug":"huseyin-ciplak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dongu-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Direnç', 'direnc-huseyin-ciplak-h85w3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne oldu bizlere

Bir gerçek kesitimiydi yoksa serüvenmi

Maceracılar nerde kaldı.

Nerde hayallerimiz,

Hayallerimize ne oldu.

Yoksa...

Aşkın mimarları yokmu oldular.

Yinede sevda bitermi,

Bitermi sevda.

Asla...

Eğer biterse,yaşamda biter...', 'Ne oldu bizlere Bir gerçek kesitimiydi yoksa serüvenmi Maceracılar nerde kaldı. Nerde hayallerimiz, Hayallerimize ne oldu. Yoksa... Aşkın mi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çıplak']::text[], 8.5, '{"poet":"Hüseyin Çıplak","poet_slug":"huseyin-ciplak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/direnc-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavaş Yavaş', 'yavas-yavas-neslihan-oksuz-p4hbv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'YAVAŞ  YAVAŞ

Cümle âşıkların yandığı bu âteş ile, 

Yüreklerdeki yangının âhı bu yaş ile, 

Verilen sözlerdeki bilinmez telâş ile,

Tutan ellerim tutmaz oluyor yavaş yavaş.

Ağlayan gözlerin bitmeyen feryâtlarından,

Yürünen yolların sonsuz uçurumlarından,

Kapanan kapıların ardındaki âhlardan, 

Gören gözlerim görmez oluyor yavaş yavaş.

Suya kanmış toprak bağrındaki yangın ile, 

Oda yanmış pervâne özündeki deryâ ile, 

Cümle cümle mahlûkât içindeki aşk ile, 

Dönen dillerim dönmez oluyor yavaş yavaş. 

Yüreğim kurtulup o simsiyah yalnızlıktan,

 Kucak açıyor sıyrılıp bu karanlıklardan,

Uyanılmayan bir uykunun rüyâlarından,

Ayaklarım toprağa basıyor yavaş yavaş.', 'YAVAŞ  YAVAŞ Cümle âşıkların yandığı bu âteş ile,  Yüreklerdeki yangının âhı bu yaş ile,  Verilen sözlerdeki bilinmez telâş ile, Tutan eller...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Öksüz']::text[], 8.5, '{"poet":"Neslihan Öksüz","poet_slug":"neslihan-oksuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yavas-yavas-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dem''a', 'dem-a-neslihan-oksuz-64yxk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DEM’A

Hicrân ateşi yüreğimi nasıl yakıyor 

bilemezsin.

Öyle yalnızım ki kalabalıklar içinde 

Öyle yalnızım ve öyle suskunum ki

	sen gittiğinden beri.

Hiçbir dost yüzü ve hiçbir 

					dost sözü dolduramadı yerini.

				Ey dil-ber, gittiğinden beri

				Gülşenler içinde ve gülüşlerle beraber

				Her yâd edişimde seni

				Her geçirişimde aklımdan

				Bir damla gözyaşı olup aktın yüreğime.

				Gittiğinden beri ey dil-ber

				Nasıl şaşkınım ve hayretler içindeyim

					bilemezsin.

				Seni bu kadar sevdiğimi bilirdim de 

				Bu kadar arayacağımı inan,

					inan bilmezdim.

				Sen, ey mihr-i cân,

				Yani canın dostu,güneşi,

				Yani gözlerimin aradığı,

				Hicrânıyla yüreğimin yandığı,

				Vuslatıyla avunduğu,

				Yokluğunda kıymetini daha bi anladım.

				

				Bu gönül seni arar,

					    seni sever,

					    seni bekler.

				Gel artık özlem bitsin,

				Gel artık,yüreğim daha fazla kanamasın.

								acımasın.

								yanmasın.', 'DEM’A Hicrân ateşi yüreğimi nasıl yakıyor  bilemezsin. Öyle yalnızım ki kalabalıklar içinde  Öyle yalnızım ve öyle suskunum ki 	sen gittiğin...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Öksüz']::text[], 8.5, '{"poet":"Neslihan Öksüz","poet_slug":"neslihan-oksuz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dem-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü mevsimler', 'huzunlu-mevsimler-huseyin-ciplak-9804v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mevsimlerde en fazla hüzün yakışır sonbahara

Hayal ve düşlere yakışır birazda...

Ama bilirsiniz,sevdalar olmasa,

Yani...

Hüznün,aşkın ve umudun yaşandığı yerler.

Sevincin eksik kalırdı biraz.

Onlarsız bizim eksik kaldığımız gibi.

Büyütürken yüreğini tüm güzellikleri,

Bilirimki hissedebilen her yürek için,

Sevdanın her yeri başka,başka şeyler söyler.

hüznün yaşandığı mevsimler gibi...', 'Mevsimlerde en fazla hüzün yakışır sonbahara Hayal ve düşlere yakışır birazda... Ama bilirsiniz,sevdalar olmasa, Yani... Hüznün,aşkın ve umu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çıplak']::text[], 8.5, '{"poet":"Hüseyin Çıplak","poet_slug":"huseyin-ciplak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/huzunlu-mevsimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalpler', 'kalpler-alper-kuruk-ys7ob', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir doktorunki kadar 

Acıyla delik deşik olmuş,

Bir kadınınki kadar ürkek,

Ananınki kadar yufka,

Çocuğunki kadar sâf,

İnsafsızınki kadar pek,

Katı,yumuşak,yaralı kalpler

Çarpar çeşit çeşit...

Aşk olmasa kalpleri 

Birbirine  ne ekler? 

Yıkılır mı insafsızın sur gibi kalbi

İncecik merhamet oklarıyla? 

Esir eder tabiat şair kalbini

Sonbahar yapraklarıyla...

Yavrum diye çarpar

Ananın yufka kalbi,

Dolaşır damarlarında kan kan

Al kandan da sâf yavrusu.

Aşıkların kalbini burkan 

Kavuşamamak korkusu.

Vicdanı deler insaf.

Yumuşatır yufka kalbi

Acındırıcı bir lâf.

Namus diye çarpan kalpler

Değişmez cana namusu.

Bütün bunların yanında

Geleceğe ilk açılışında 

Uykulu gözlerle bakan,

Herşeyden temiz ve kaygısız

Yeni doğan yumurcağın kalbi var

Hayat...Hayat...Hayat...diye atar...', 'Bir doktorunki kadar  Acıyla delik deşik olmuş, Bir kadınınki kadar ürkek, Ananınki kadar yufka, Çocuğunki kadar sâf, İnsafsızınki kadar pek...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kalpler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi', 'mavi-neslihan-oksuz-fhcw2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'MAVİ

Mavi kaplamış her yanı

Ortalık alabildiğince mavi

Toprak mavi kokuyor

Çocuklar mavi görüyor

Mavi duyuyor, mavi yaşıyor.

Ortalık  alabildiğince mavi

Yüreklerse alabildiğince gri kaplı.

Ey mavi! 

Ne yaparsan yap

Ne kadar masum olursan ol,

İnsanlar var oldukça

Yürekler hep gri kalacak.

Toprak mavi kokacak,

Çocuklar mavi görecek,

Mavi duyacak, mavi yaşayacak

Ama yürekler büyüdükçe

Hep griyle kaplanacak.', 'MAVİ Mavi kaplamış her yanı Ortalık alabildiğince mavi Toprak mavi kokuyor Çocuklar mavi görüyor Mavi duyuyor, mavi yaşıyor. Ortalık  alabil...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Öksüz']::text[], 8.5, '{"poet":"Neslihan Öksüz","poet_slug":"neslihan-oksuz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mavi-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadık', 'unutmadik-neslihan-oksuz-adsw5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'UNUTMADIK

						            - Emine İmamoğlu’ya  ithâfen-

				En unutulmaz şarkılardı söylediklerimiz

				Mevsim-i  barânı yaşarken

				İnce ince yağan yağmur

				Nevbaharı müjdelerken

				Ellerinden dökülen inciler gibiydi göz yaşlarımız.

				İnciler ki okyanusun derinliklerinde gizliydi

				Mevsim-i baranda yağmur

				Anne sütü gibiydi çatlayan toprağa

				Meyve veren ağacın dallarıydık hepimiz

				Orhun’un kıyısında şanlı bir tarih yazan

				Gül alıp,gül satan bir neslin torunlarıydık.

				Lâlezârlarda  büyümemiştik belki ama 

Unutmamıştık meyve veren ağacın                                                  Ecdâdımızın kanıyla sulandığını....', 'UNUTMADIK 						            - Emine İmamoğlu’ya  ithâfen- 				En unutulmaz şarkılardı söylediklerimiz 				Mevsim-i  barânı yaşarken 				İnce...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Öksüz']::text[], 8.5, '{"poet":"Neslihan Öksüz","poet_slug":"neslihan-oksuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/unutmadik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal', 'kal-neslihan-oksuz-15ylz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'KAL

				Eğer gidersen, vedâ bile etmeden

				Bil ki bir daha dönemezsin

				Vedâ edersen gidemezsin.

				Şimdi, ya git hiçbir şey düşünmeden

				Arkana bile bakmadan

				Yâhut, bir vedâyı esirgeme benden

				Ve kal bir ömür boyu vedâ edemeden.', 'KAL 				Eğer gidersen, vedâ bile etmeden 				Bil ki bir daha dönemezsin 				Vedâ edersen gidemezsin. 				Şimdi, ya git hiçbir şey düşünmeden...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Öksüz']::text[], 8.5, '{"poet":"Neslihan Öksüz","poet_slug":"neslihan-oksuz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kal-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Gel', 'sen-de-gel-neslihan-oksuz-txid5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SEN  DE  GEL

			Vuslatına  bir türlü nâil olamadığım dilber

	 		Sen gittiğinden beri

			Bir şeyler hep eksik kalıyor yüreğimde

			Bir şeyler hep yarım kalıyor

			Mutsuzum

			Umutsuzum

			Çaresizim

			Sen gittiğinden beri hiç gülmedi şu yüzüm

			Diyemem...

			Güldüm çünkü, mutlu da oldum

			Hele umudumu hiç yitirmedim.

			Nice kahkahalar attım batan güneşlere karşı

			Ne gülücükler savurdum hoyrat rüzgârlara

			Ve ne fırtınalarda savruldum umarsızca...

			

			Senin gidişinle, inan yalnız da kalmadım

			Hele dostsuz, kimsesiz hiç kalmadım

			Ama neden bilmiyorum

			Bir yanım hep eksik kaldı

			Çünkü giderken

			Sadece sana ait olanları almadın yanına

			Benden de çok şeyler alıp götürdün

			Ve ben hepsini sana gönüllü verdim.

                                   Yanlış anlama beni

			Alıp götürdüklerinden şikâyetçi değilim inan

			Keşke daha çok şey alsaydın

			Ve ben daha çok yarım kalsaydım

			

			Bilmezlikten gelme

			Biliyorum; biliyorsun

			Sen de acı çektin ben yokken

			Uzun ve aysız geceler boyu sen de ağladın

			Sen de yandın, yakıldın

			Pervane oldun, düştün ateşe

			Ve yeri geldi her şeyi unutup

			Kahkahalar attın batan güneşlere karşı

			

			Bilmezlikten gelme

			Ayrıyken bile bir çok şeyi beraber yaptık

			Biliyorum...

			Biliyorsun...

			Vuslatına bir türlü nâil olamadığım dilber; 

			Vakit yaklaştı

			Gidiyorum.

			İstiyorsan sen de gel', 'SEN  DE  GEL 			Vuslatına  bir türlü nâil olamadığım dilber 	 		Sen gittiğinden beri 			Bir şeyler hep eksik kalıyor yüreğimde 			Bir şeyler...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Öksüz']::text[], 8.5, '{"poet":"Neslihan Öksüz","poet_slug":"neslihan-oksuz","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sen-de-gel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Şey İstememiştim', 'cok-sey-i-stememistim-neslihan-oksuz-mydsu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÇOK ŞEY İSTEMEMİŞTİM

			Su üstüne yazı yazdım

			Kimse okuyamadı

			Oysa ben okuyabiliyordum

			Kumsala yazdım aynı yazıyı

			Başkaları okuyamadan

			Dalgalar alıp götürdü içine.

			Bu kez taşa yazdım yüreğimi

			Herkes okuyabilsin istedim

			Taş kaldı yerinde, yüreğim silindi...', 'ÇOK ŞEY İSTEMEMİŞTİM 			Su üstüne yazı yazdım 			Kimse okuyamadı 			Oysa ben okuyabiliyordum 			Kumsala yazdım aynı yazıyı 			Başkaları okuy...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Öksüz']::text[], 8.5, '{"poet":"Neslihan Öksüz","poet_slug":"neslihan-oksuz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cok-sey-istememistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-huseyin-ciplak-3jpj5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkta çark etmek olmaz,

Çark edene sevgi neylesin...

Sensiz muhabbet bir tutam acı,

Sensiz muhabbeti neyleyeyim...

Yürek dilberden vaz geçmem der.

Dilbersiz ben bu yüreği neyleyeyim.

Edasıyla ezelden savurur beni

Zülfünü yan taramış,bir ok saplarda geçer.

Salınır gider,badem gözleriyle,

Bağrımı delerde geçer.

Yar kendisi olmazsa,

Neylesin bu yürek sevdayı.

Gönül ister,yana gelmiş zülfünü.

Badem gözlerini,bir tutam muhabbetini...', 'Aşkta çark etmek olmaz, Çark edene sevgi neylesin... Sensiz muhabbet bir tutam acı, Sensiz muhabbeti neyleyeyim... Yürek dilberden vaz geçme...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çıplak']::text[], 8.5, '{"poet":"Hüseyin Çıplak","poet_slug":"huseyin-ciplak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cagri-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı''ya Yakarış', 'tanri-ya-yakaris-munevver-senol-qrz8a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zengine mal mal üstüne verme Tanrım 

Verme Tanrım.

Fakire ise açlık zülüm verme Tanrım,

Verme Tanrım.

Şanssız doğan şanssız ölür,

Zenginse şımarır öğünür.

Fakir kulunun yüzünü güldür,

Senin hazinen boldur Tanrım.

Şanssız doğan birde benim,

Kime şikayet edeyim? 

Tek ümidim gerçek yerim,

Bari orada güldür Tanrım.

Not:1968''de görev icabı Merzifonda garajın yanında oturuyorduk. Bir sabah lapa lapa kar yağıyor, camdan baktım bir sürü kadın erkek yaşlı biribirlerine sokulmuş bekleşiyorlar. Hemen karşı dairemdeki ev sahibine sordum. Hıı,onlar fakir aylığı alıyorlar herkes biryerlerden gelmiş bankanın açılmasını bekliyorlar, o kadar  üzüldüm ki bir mutfağa koşuyorum çaydanlığım onlara yetmez eve çağırsam yaşlılar 5 kat çıkamazlar çaresizlik içinde o gün karaladığım şiir 2 yıl sonra uluslar arası bir gazetede yayınlanmaya değer bulundu onu hala saklarım.', 'Zengine mal mal üstüne verme Tanrım  Verme Tanrım. Fakire ise açlık zülüm verme Tanrım, Verme Tanrım. Şanssız doğan şanssız ölür, Zenginse ş...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tanri-ya-yakaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilsiz Aşkı', 'dilsiz-aski-alper-kuruk-kqmhe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkta dil ha olmuş ha olmamış

Zaten olsa daha beter...

Gerçk aşkı duymasa kalpler

Diller konuşur

Yalancı aşkı terennüm eder.

Dilsizlere sorun siz esas aşkı...

Diler susar,kalpler konuşur,

Gözleri rehberidir aşklarının.

Gözle âşık olurlar

Göz ve kalple konuşurlar...

l

Dilleri açık olsaydı eğer

Başlardı yalancılığa.

Dille bağlanılsa bile bir an

O yalanlar filiz aşkı ezer

Boşa gider geçen zaman.', 'Aşkta dil ha olmuş ha olmamış Zaten olsa daha beter... Gerçk aşkı duymasa kalpler Diller konuşur Yalancı aşkı terennüm eder. Dilsizlere soru...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dilsiz-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoktan Soldum Ben', 'coktan-soldum-ben-sezen-akoluk-3lzaf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz olduğum için,

su verilmeyen bir çiçek gibi soluyor ve ölüyorum.

Hani benim suyum sen olaçaktin? 

Hani beni hep sevginle suluyacaktin? 

Hani topragimi kurutmayacaktin? 

Oysaki eskiden bu çiçek için ölürdün.

Hic ihmal etmezdin.

Gözün gibi bakardın.

Hatta kendinden bile kıskanırdın beni.

Yani simdi solmus olan cicegi.

Oysaki ne kadar seviyordun ciceklerimi acdiklarinda.

Bayılıyordun renklerime, canlılığıma, enerjime.

Kendinden nazar değer diye korkardın hep.

Ne oldu peki sana? 

Niye bana bir kere olsun bakip, canlandirmiyorsun? 

Canlanmam icin bir bakisin yeterli benim icin.

Ama hayir.

Donmuş bir şekil de, olduğun yer de duruyorsun.

Bakıyorsun camdan dışarı.

Gözlerin açık bir şekil de.

Korkuyorum.

Korkutuyorsun beni.

Haykırıyorum, ama halen beni duymuyorsun.

„fazla günüm kalmadı, öldüm öleceğim“  diyorum,

ama halen birşey demiyorsun 

ve de cansız bedeninle camdan dışarı bakıyorsun.

MEGER BENDE SENI SULAMAYA UNUTMUŞUM! ! ! 

SENDE ŞOKTAN ÖLMÜŞSÜNDE HABERIM YOK! 

ÖMÜR BOYU SENINLE BERABERIM; 

TAKI ÖLÜM BIZI AYIRANA DEK.

Sezen akoluk', 'Sensiz olduğum için, su verilmeyen bir çiçek gibi soluyor ve ölüyorum. Hani benim suyum sen olaçaktin?  Hani beni hep sevginle suluyacaktin?...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/coktan-soldum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yudumun Manzarası (I)', 'yudumun-manzarasi-i-dursun-elmas-5k7rz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Burası Türkiye,başkent Ankara

Vatandaş Hasan''la geziniyoruz.

İki bin beş yılı işte manzara

İbretle hüzünle seyrediyoruz.

Enflasyon düşmüşmüş(!) ,biz bilmiyoruz

Kesede beş kuruş göremiyoruz.

Bu nice yalandır diyemiyoruz

Gerçek mi sanal(!)     mı bilemiyoruz.

Salamın, sucuğun adın unuttuk

Vallahi billâhi tadın unuttuk

Pastırma ne idi yadın unuttuk

Bakıp tezgâhlara yalanıyoruz.

Açlık sınırımız yedi yüz elli

Varoşta tek oda iki yüz elli.

İşçinin aldığı pul zaten belli

Yokluklar içinde avunuyoruz.

Banka kuyrukları hâlâ uzuyor

Kapkaç çeteleri pusu kuruyor.

Bu nasıl kanundur,aklım duruyor

Bir celse dolmadan bırakıyoruz.

Memurun halini sakın sormayın

Anlatması müşgül,beni yormayın

Ne haldedir şimdi; bana sormayın

Evdeki avrattan kaçınıyoruz.

Nerede verimli bir toprak varsa

Ediyoruz hemen parselli arsa.

Satıp savıyoruz dünden ne varsa

Hazır tüketmekle ünleniyoruz.

Üretme deniyor,tütünü çayı

Biz size satarız unu buğdayı.

Ekmeyin pancarı,fındık,soyayı

Emret beyim ile geniriyoruz.

Zina ile rüşvet,artık suç değil

Salipin adı da şimdi haç değil

Hırsızlık haydutluk zaten hiç değil

Lime lime olduk dökülüyoruz.

Şaşırdık vallahi bize ne oldu? 

İftar sofraları keşişle doldu.

Balat''taki patrik ekümen oldu

Cüppe giydik(!)   diye övünüyoruz.

Bir sonraya kaldı esas ahtımız

Elbet yazılacak gümrük kapımız.

Pazara sürüldük,bilin hepimiz

Baba malı gibi satılıyoruz....', 'Burası Türkiye,başkent Ankara Vatandaş Hasan''la geziniyoruz. İki bin beş yılı işte manzara İbretle hüzünle seyrediyoruz. Enflasyon düşmüşmüş...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yudumun-manzarasi-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düngece...', 'dungece-neslihan-i-sler-7mdwh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düngece sonkez senin için ağladım

Düngece sonkez bir dostla seni andım

Nerde yanlış diye sordum

Ben hatalı sen hatalı onlar hatalı

Kim eteklerindeki taşları ortaya yaymalı

Anlamadığım bir deliliğe zorlandım

Neydi nezamandı son nerde başlamıştı

Deneyelim mi denmişti 

Yeterince deneyimlenmemişmiydi

Keşke hiçbiryerdeyken karşılaşmasaydık

Ne yollarımız birdi ne ruhlarımız birleşti

Düngece tüm gerçekliğinde seni anladım

Meğer hayalimkinden nekadar uzaktın

Sadece bir hayale ağladım.....

Düngece aslında hiç tanımadığım bir sen tanıdım

Meğer ne cok aldanmısım aldanmanın binbir çesidini anladım

Düngece ağladım çünkü herdamlada içimden sen aktın

En sonunda ruhumu senden arındırdım

Gerçeklik yoktu bir tek senin gerçeklerin 

Telafisi olmayan bir eksiklik senin yüreğinin

Biliyorumki ruhun huzursuz ebedi arayısının 

Düngece sonkez senin için ağladım

Belki de sokez senin için ağlayan bir ben vardım....

Bir bende yokum artık...............', 'Düngece sonkez senin için ağladım Düngece sonkez bir dostla seni andım Nerde yanlış diye sordum Ben hatalı sen hatalı onlar hatalı Kim etekl...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dungece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmış', 'yalanmis-sezen-akoluk-w1wuh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yemin ettim ben aşka,

Sevmeyeceğim başka! 

Seni sevdim de ne oldu? 

Hüsran ile son bul du

Oldum ben bir şaşkın,

Hep söylerdin aşkım maşkım,

Olmuşun sen bir taşkın.

Yalanmış senin aşkın,', 'Yemin ettim ben aşka, Sevmeyeceğim başka!  Seni sevdim de ne oldu?  Hüsran ile son bul du Oldum ben bir şaşkın, Hep söylerdin aşkım maşkım, ...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalanmis-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbrahimi Aşk', 'i-brahimi-ask-abdullah-yasar-erdogan-x89jn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bin kez mancınıktan atsınlar bizi de,

Nemrutlar elbet yanacak har içinde,

Yolumuz varmakta put kıran izine

Yâkub’i hasret yakar yüreğimizi.

İlâhi emir dahilinde pervaneyiz,

Nebiler serverinin gönüllü eriyiz.

Biz İlahi yolun deli divanesiyiz,

İbrahimi ateş yakar yüreğimizi.

Varlığımız sekerat-ül-mevt* içinde,

Ruhumuz her an itikaf* mevkiinde,

Nefes hanemiz iman-ihlas derdinde,

Yâkub’i hasret yakar yüreğimizi.

Mugâlatayı* reddettik, benimsemedik,

Özümüzü Hakk’a açıp ona yöneldik,

Biz, bu  beşer teni bu yolda erittik,

İbrahimi ateş yakar yüreğimizi.

*Sekerât-ül-mevt: Ölüm sarhoşluğu, can çekişmesi hali.

*İtikaf: İnzivaya çekilip devamlı ibadetle meşgul olmak.

*Mugalata: İnsanı her şeyin ölçüsü kabul eden felsefi düşünce.', 'Bin kez mancınıktan atsınlar bizi de, Nemrutlar elbet yanacak har içinde, Yolumuz varmakta put kıran izine Yâkub’i hasret yakar yüreğimizi. ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ibrahimi-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Var', 'olum-var-abdullah-yasar-erdogan-yj21l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dertler senin imtihan şeklin,

İmam elbet verecek telkin,

Sabır var sabır, sabır, sabır,

Sabretmenin sonu mükafattır.

Değmez dünyaya ehemmiyet,

Senle gitmez ki bu mülkiyet,

Dünya ve dünya, dünya, dünya,

Bak geçmişe kaldı mı burada.

Devran-ı âlemden kopuş var,

Her daima yaratana yalvar,

Ölüm var ölüm, ölüm, ölüm,

Ölüm ötesi hayat var gülüm.

Ne ettin ne buldunsa senin,

Cebi bulunmazmış kefenin,

Cennet var cennet, cennet, 

Cennet için bu dünyayı terk et.', 'Dertler senin imtihan şeklin, İmam elbet verecek telkin, Sabır var sabır, sabır, sabır, Sabretmenin sonu mükafattır. Değmez dünyaya ehemmiye...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-var-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçer Elbet', 'gecer-elbet-resul-ustun-mp1un', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bekle sen,

bekle ey sevdasız.

Can pazarından döner gelirim elbet.

Bu yollar,caddeler

bu dağlar unutmaz ihaneti.

Bu ölü şehir canlanır elbet.

bekle sen,

bekle ey sevdasız.

ay tutulması geçer,

gökte yıldızlar parlar elbet.

Bu çığlık biter,

bu yangın söner elbet.

Bu yürek,

bu bilek

daha ne sevda tohumları eker.', 'Bekle sen, bekle ey sevdasız. Can pazarından döner gelirim elbet. Bu yollar,caddeler bu dağlar unutmaz ihaneti. Bu ölü şehir canlanır elbet....', ARRAY['Türk Edebiyatı','Şiir','Resul Üstün']::text[], 8.5, '{"poet":"Resul Üstün","poet_slug":"resul-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gecer-elbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diasporaşk', 'diasporask-mehme-arslan-kbapi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'benim asıl yurdum senin kalbin

başka yüreklerde sürgünüm ben

üstelik kendi isteğimle de gitmedim

devlet-i âli osman''ın tehciriylen

23/10/2005', 'benim asıl yurdum senin kalbin başka yüreklerde sürgünüm ben üstelik kendi isteğimle de gitmedim devlet-i âli osman''ın tehciriylen 23/10/200...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/diasporask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet Olsun', 'lanet-olsun-ugur-kilic-z50pg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Attığın beşinci adımdan altıncı adıma

Gelen kuvvete ve kudrete lanet olsun! ! 

Paradır insanın nazarı ve miktarı 

Her yerde kurulmus bir orospu pazarı 

Bizde olduk bu alemin okur yazarı 

Böyle okur yazarın kağıdınada kaleminde 

Lanet olsun! 

Sosyete dediğin bir ilim irfandır 

Bizde delikanlılık sultandır,

Biz kim sosyete kim 

Bizki efkarı aleme girmiş dost canlısıyız.. 

Yolun düşerse dar bir yokusa 

Yürüyüşlerin gitmiyor hiç hoşuma 

Masaya çıkınca tek bir kurusa,

Sana değil gülüm

Sana gönül verene

Sana talip olana

Lanet olsun......

(Halkın dilinden)', 'Attığın beşinci adımdan altıncı adıma Gelen kuvvete ve kudrete lanet olsun! !  Paradır insanın nazarı ve miktarı  Her yerde kurulmus bir oro...', ARRAY['Türk Edebiyatı','Şiir','Uğur Kılıç']::text[], 8.5, '{"poet":"Uğur Kılıç","poet_slug":"ugur-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/lanet-olsun-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küllenen Mektup-12', 'kullenen-mektup-12-ozkan-karaca-xorw1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana bir gül veremedim

Güllerin kanlarını yüreğimizde ısıtamadık

Sana bin gün veremedim

Günlerin anlarını sözlerimizde ısıramadık

Sana bir yol veremedim

Yolların uzun dillerinde millerce bulunamadık

Sana bin göz veremedim

Gözlerin izli dallarında mimlerce buluşamadık

Sana bir taş veremedim

Taşların alev bakışında güzlerce savuramadık

Sana bin yaş veremedim

Yaşların sancı akışında seslerce sunamadık

Sana bir su veremedim

Suların serin sebilinde saatlerce içemedik

Sana bin hu veremedim

hu ların ince nefesinde anılarca itemedik', 'Sana bir gül veremedim Güllerin kanlarını yüreğimizde ısıtamadık Sana bin gün veremedim Günlerin anlarını sözlerimizde ısıramadık Sana bir y...', ARRAY['Türk Edebiyatı','Şiir','Özkan Karaca']::text[], 8.5, '{"poet":"Özkan Karaca","poet_slug":"ozkan-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kullenen-mektup-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Atı', 'deniz-ati-erkan-arslan-hcj1d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deniz Atı

Bozulsun tılsımlar deniz atında

Bu büyü tılsımdan bozulsun artık

Kırılsın mühürler deniz atında

Bu sihir mühürde çözülsün artık

Düşümde eskiden kalma bahtsızlık

Gamsız baykuş gamlı gönül e karşı

Tenimde ölmez ruh tüten yalnızlık

Bu bedbaht hayalim zamana karşı

Dünya da var olmak güya bilinmek

Bir ok gibi inmek vurulmak vahşi

Hayali anlamak güya bilinmek

Sevdiğim önümde oluver yahşi

Karşımda mahşeri bir kalabalık

Okunsun tılsımlar deniz atında

Bu büyü bu rüya çözülsün artık.

Kırılsın mühürler deniz atında…

                                    5  5  2004', 'Deniz Atı Bozulsun tılsımlar deniz atında Bu büyü tılsımdan bozulsun artık Kırılsın mühürler deniz atında Bu sihir mühürde çözülsün artık Dü...', ARRAY['Türk Edebiyatı','Şiir','Erkan Arslan']::text[], 8.5, '{"poet":"Erkan Arslan","poet_slug":"erkan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/deniz-ati-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben küçükken', 'ben-kucukken-ugur-kilic-xihzv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben çocukken

Telden arabalarımız

Demirden kızaklarımız

Uzun çıtalardan

Atlarımız vardı

Ben çocukken

Büyüklerimizde sevgi

Küçüklerde saygı vardı

Ben küçükken

Büyüklerden öğrendim

Aşk vardı

Aşkta sadakat

Aşkta bağlılık

Aşkta heyecan vardı

Ben küçükken

Küçükler büyüklerden

Örnek alırdı

Ben küçükken

Sevgililer ayrıldığında

Bağırlar yanardı

Gözler yaş dolardı

Özlemler başlardı

Bu söylediklerim hep

Ben küçükken yaşanırdı......', 'Ben çocukken Telden arabalarımız Demirden kızaklarımız Uzun çıtalardan Atlarımız vardı Ben çocukken Büyüklerimizde sevgi Küçüklerde saygı va...', ARRAY['Türk Edebiyatı','Şiir','Uğur Kılıç']::text[], 8.5, '{"poet":"Uğur Kılıç","poet_slug":"ugur-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-kucukken-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Koptu Bizde', 'ayrilik-koptu-bizde-riyaz-demirci-30zle', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmiştim bir güzeli onu benden ettiler

Aşkımızı kökünden hep dağıdıp gitler

Görün dostlar buzulmu bakın bize netiler

Dağılmış yuva gibi ayrılık koptu bizde

Ogünden ayrılalı gör halimiz noldu yar

Son bahar gülü gibi bak rengimiz soldu yar

Yazık ayrılmalıyız artık vekit doldu yar

Dağılmış yuva gibi ayrılık koptu bizde

Gözüne baka baka daldım derin ruyaya

Keşke seni görmiyip gelmeseydim dunyaya

Senden ayrıldı gönlüm birde düşmez sevdaya

Dağılmış yuva gibi ayrılık koptu bizde.', 'Sevmiştim bir güzeli onu benden ettiler Aşkımızı kökünden hep dağıdıp gitler Görün dostlar buzulmu bakın bize netiler Dağılmış yuva gibi ayr...', ARRAY['Türk Edebiyatı','Şiir','Riyaz Demirci']::text[], 8.5, '{"poet":"Riyaz Demirci","poet_slug":"riyaz-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayrilik-koptu-bizde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anı Ovacıktan - Pydnai ye', 'ani-ovaciktan-pydnai-ye-zati-erbas-qc6bt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ovacıktan Baba dağa uzanan patika

Ölü denizin tepesine kadar taşıdı bizi,her yer göz alabildiğine deniz.

Kalbim bir martı gibi,kanat çırpıyor

Patika dağlara kalbim evine dönüyor.

Uçurumdan Kelebekler vadisine bakarken akşam üzeri 

Bilmezler aslında karanlığın nereden geldiğini

Bir köşeye gizleyip kendimi yalnızlığımı salıyorum dışarı. 

Ateşte oluşan köz unutamadığım geçmiş acılar denizden yükselen buğu,başımızı ağrıtacak kadar içilen içki 

Kabak koyuna giderken duyduğum davul zurna sesi düğün habercisi iki sohbet azıcık bahşiş 

Cemalin ruhuyla oynadığı Muğla zeybeği

O mu döndü

Dünyamı Ona uydu bilmiyorum.

Yürüdük kumsalda sahilde bıkmadan bir şeyler arayan Deniz 

ve yolu dağlara doğru giden biz.

Yola düşme vakti gelince kıvrılarak giden patika bulutlara taşıyor bizi Alınca ya

Son demini yakalamak Günün

Güneş ve biz aslında aynı yerdeyiz.

Zamanı geri döndürmek mümkün mü? diye sorarken binlerce yıl öncesinin sokaklarında buldum kendimi sütunlar,kaldırım taşları,evler öteki dünyaya giden kayıklar gibi mezarlar. Sdyma

Baykuş sesi hakim olunca geceye uykuya doğru yöneldi yol bilemez ki insan kümes olmayan köyde tavuklar ve horozlar her ağaca tüner ve her saat başı öterler uykuda uçup gider.

Yedi burunlar; her birinde bir fener olsam yol göstersem sevgilere,rüzgar olsam essem,essem,essem', 'Ovacıktan Baba dağa uzanan patika Ölü denizin tepesine kadar taşıdı bizi,her yer göz alabildiğine deniz. Kalbim bir martı gibi,kanat çırpıyo...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ani-ovaciktan-pydnai-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaveyla', 'vaveyla-omer-faruk-cakir-hluev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir damla hüzün düştü yüzüme, ruhum kırıldı,

Bedenimden savruldu kırık can parçaları,

Kim dolaştıysa gizli bahçemde kesildi sesi.

Bir çocuğun vaveylası karıştı gecelerime,

Bir an olsun eksilmedi kulağımdan körpe sesi.

Geçmişle geleceğin terkibindeyim şimdi,

Nazarımda bir sen varsın, gece, ihtiyar saki

Öyleyse sen söyle, derunum neden firaka ram? 

Hüzne serhat seyrinden usandı ömrüm saki,

Bir lahza kesilse vaveyla ve uykuya dalsam.', 'Bir damla hüzün düştü yüzüme, ruhum kırıldı, Bedenimden savruldu kırık can parçaları, Kim dolaştıysa gizli bahçemde kesildi sesi. Bir çocuğu...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vaveyla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen (güfte Nagahan Akay-beste Erol Güngör)', 'kardelen-gufte-nagahan-akay-beste-erol-gungor-nagahan-orbay-akay-rp5u6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her meclise hoş gelensin 

Gönlümüzde gül derensin 

Neş’e saçan, kalp coşturan 

İnce zarif kardelensin..

Tüm çiçekler örnek alsın 

Raks eden bir ince dalsın 

Kış gelse de sen baharsın 

Şarkılara renk katarsın.. 

Meltem gibi hafif esen 

Her görüşte nefes kesen 

Huzur veren yüz güldüren 

Sensin canım sen kardelen.. 

Nagâhan (Orbay)     Akay', 'Her meclise hoş gelensin  Gönlümüzde gül derensin  Neş’e saçan, kalp coşturan  İnce zarif kardelensin.. Tüm çiçekler örnek alsın  Raks eden ...', ARRAY['Türk Edebiyatı','Şiir','Nagahan Orbay Akay']::text[], 8.5, '{"poet":"Nagahan Orbay Akay","poet_slug":"nagahan-orbay-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kardelen-gufte-nagahan-akay-beste-erol-gungor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Bayramım', 'benim-bayramim-durmus-karakus-fguvj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu yıkılasıca kara gurbetin,

Ne kaşına ne gözüne hayranım.

Nekadarki kalmak istemesemde,

Hep gurbette geçer benim bayramım.

Acılar kederler saçımı döktü,

Koca bir çınardım belimi büktü,

Gözlerime kara bulutlar çöktü,

Hep gurbette geçer benim bayramım.

Gelde sen Bozkırı köyü özleme,

Burnumda tütüyor sıcak közleme,

Hasret kaldım inan yeşil gözlüme,

Hep gurbette geçer benim bayramım.

Duydumki hastaymış dedem le ninem,

Acılar içinde yanıyor sinem,

Arzu halim böyle canım Eminem,

Hep gurbette geçer benim bayramım.', 'Şu yıkılasıca kara gurbetin, Ne kaşına ne gözüne hayranım. Nekadarki kalmak istemesemde, Hep gurbette geçer benim bayramım. Acılar kederler ...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-bayramim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler (güfte Nagahan Akay-beste Erol Güngör)', 'gozler-gufte-nagahan-akay-beste-erol-gungor-nagahan-orbay-akay-340qa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mavi gözler, deniz derya 

Yeşil gözler, umut hülya 

Kahverengi, efsunludur 

Siyah gözler, gizli dünya.. 

Gözün bir de elası var 

Yeşil mavi, karması var 

Kimi ok yay, hare hare 

Bakıp canlar yakanı var.. 

Ruha ayna olur gözler 

Gözle anlam taşır yüzler 

En güzeli duru gören 

Can gözüyle bakan gözler.. 

Nagahan Akay', 'Mavi gözler, deniz derya  Yeşil gözler, umut hülya  Kahverengi, efsunludur  Siyah gözler, gizli dünya..  Gözün bir de elası var  Yeşil mavi,...', ARRAY['Türk Edebiyatı','Şiir','Nagahan Orbay Akay']::text[], 8.5, '{"poet":"Nagahan Orbay Akay","poet_slug":"nagahan-orbay-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozler-gufte-nagahan-akay-beste-erol-gungor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu', 'duygu-i-smail-hakki-cengiz-7h7gy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ya Rab! Bu ne yüce duygu ki gözler yaşardı,

Erler zaferleri bu duyguyla mı başardı? 

                           Ramazan Bayramı Namazı, Sandıklı / 1976

[email protected]', 'Ya Rab! Bu ne yüce duygu ki gözler yaşardı, Erler zaferleri bu duyguyla mı başardı?                             Ramazan Bayramı Namazı, Sand...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Cengiz']::text[], 8.5, '{"poet":"İsmail Hakkı Cengiz","poet_slug":"i-smail-hakki-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/duygu-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma (güfte Nagahan Akay-beste Erol Güngör)', 'unutma-gufte-nagahan-akay-beste-erol-gungor-nagahan-orbay-akay-s91lm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu dünya dediğin, koca meyhâne 

Diğer bir adı da, sanki derthâne 

Ağlanır gülünür, efkâr dürülür 

Ne olursa olsun, hayat şâhâne..

Onu bunu şunu, etme bahâne 

Sev sevil mutlu ol, yeter daha ne 

Sevgi yüce duygu, gerçek zenginlik 

Aslında her gönül, birer kâşâne.. 

Hayat değmez dostum, ah vah etmeye 

Unutma mecburuz, geldik gitmeye 

Aynaya gül de bak, gülmek istersen 

Sen kendin kendine, alış yetmeye.. 

Nagâhan (Orbay)     Akay', 'Şu dünya dediğin, koca meyhâne  Diğer bir adı da, sanki derthâne  Ağlanır gülünür, efkâr dürülür  Ne olursa olsun, hayat şâhâne.. Onu bunu ş...', ARRAY['Türk Edebiyatı','Şiir','Nagahan Orbay Akay']::text[], 8.5, '{"poet":"Nagahan Orbay Akay","poet_slug":"nagahan-orbay-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutma-gufte-nagahan-akay-beste-erol-gungor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyor Mehmetcik Mehmet', 'geliyor-mehmetcik-mehmet-nagahan-orbay-akay-fmlag', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Al beyaz güller derin 

Yollara halı serin 

Dizilip selâm verin 

Geliyor Mehmetcik Mehmet.. 

Her zaman dimdik duran 

Hâine hesap soran 

Düşmana kan kusturan 

Geliyor Mehmetcik Mehmet.. 

Bayrağı gökte tutan 

Barışa çiçek atan 

Dostluğa saygı duyan 

Geliyor Mehmetcik Mehmet.. 

Ne mutlu bana Türk’üm 

Vatana hizmet ülküm 

Ata’ma selâm diyen 

Geliyor Mehmetcik Mehmet.. 

Nagâhan (Orbay)    Akay', 'Al beyaz güller derin  Yollara halı serin  Dizilip selâm verin  Geliyor Mehmetcik Mehmet..  Her zaman dimdik duran  Hâine hesap soran  Düşma...', ARRAY['Türk Edebiyatı','Şiir','Nagahan Orbay Akay']::text[], 8.5, '{"poet":"Nagahan Orbay Akay","poet_slug":"nagahan-orbay-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/geliyor-mehmetcik-mehmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinin mavisine (güfte Nagahan Akay-beste Erol Güngör)', 'gozlerinin-mavisine-gufte-nagahan-akay-beste-erol-gungor-nagahan-orbay-akay-repmd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinin mavisine 

Sözlerinin nağmesine 

Gönül verdim ölesiye 

Ne olacak, söyle şimdi.. 

O gün çıktın, sen karşıma 

Döndüm bak ben, bir şaşkına 

Yorgun kalbim, bu aşkına 

Dayanır mı, söyle şimdi.. 

Geçti bahar, geçti yazlar 

Mevsim oldu bir sonbahar 

Yaşanmamış arzu aşklar 

Geç değil mi, söyle şimdi.. 

Nagahan Akay', 'Gözlerinin mavisine  Sözlerinin nağmesine  Gönül verdim ölesiye  Ne olacak, söyle şimdi..  O gün çıktın, sen karşıma  Döndüm bak ben, bir şa...', ARRAY['Türk Edebiyatı','Şiir','Nagahan Orbay Akay']::text[], 8.5, '{"poet":"Nagahan Orbay Akay","poet_slug":"nagahan-orbay-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerinin-mavisine-gufte-nagahan-akay-beste-erol-gungor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalacaksın Kalbimde', 'kalacaksin-kalbimde-hadi-onal-1wfgy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ümitsiz yaşantımı süsleyen hayalinle

Dolsa da bütün ömrüm kalacaksın kalbimde

Kaderim küskün olsa sevginin yokuşunda

Dolsa da bütün ömrüm kalacaksın kalbimde', 'Ümitsiz yaşantımı süsleyen hayalinle Dolsa da bütün ömrüm kalacaksın kalbimde Kaderim küskün olsa sevginin yokuşunda Dolsa da bütün ömrüm ka...', ARRAY['Türk Edebiyatı','Şiir','Hadi Önal']::text[], 8.5, '{"poet":"Hadi Önal","poet_slug":"hadi-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kalacaksin-kalbimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tadına Varamadım', 'tadina-varamadim-mehmet-sait-akkus-kga24', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanarım senin aşkına yanarım

Ateş olurum köz olur yakarım

İlmik ilmik gözlerinde eririm

Öldürür beni sevdalı bakışın

Ateş olup yaksaydın beni ey yar

Deli edip salsaydın beni ey yar

Kapına kul yapsaydın beni ey yar

Mahkumum ben savdalı bakışına

Bak yanıyorum aşkına gün be gün

Çiçekler bıraktım kapına her gün

Hani öpüştüğümüz vardıya o gün

Tadına varamadım bakışının', 'Yanarım senin aşkına yanarım Ateş olurum köz olur yakarım İlmik ilmik gözlerinde eririm Öldürür beni sevdalı bakışın Ateş olup yaksaydın ben...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tadina-varamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehtap, keman', 'mehtap-keman-nagahan-orbay-akay-rpr64', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mehtap inmiş yüceden 

Keman inler inceden 

Şu şarabın lal rengi 

Çarptı beni sineden.. 

Mehtap, keman ve şarap 

Büyülendim ben Yarap 

Çıldırdı tüm arzular 

Etme aşkı sen serap.. 

Gönül teli kemanda 

Titriyor hoş zamanda 

Anılar raks ediyor 

Başta tüten dumanda.. 

Nagahan Akay', 'Mehtap inmiş yüceden  Keman inler inceden  Şu şarabın lal rengi  Çarptı beni sineden..  Mehtap, keman ve şarap  Büyülendim ben Yarap  Çıldır...', ARRAY['Türk Edebiyatı','Şiir','Nagahan Orbay Akay']::text[], 8.5, '{"poet":"Nagahan Orbay Akay","poet_slug":"nagahan-orbay-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mehtap-keman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Benim Göbek Adım', 'huzun-benim-gobek-adim-hayati-yavuzer-vnz9o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hüzün benim göbek adım 

yoksul ninnilerle 

beşiğimde o uyudu, o sallandı

pencerelerden sızan

soğuk kış gecelerimde

idare lâmbalarımda boy verip titredi

ve fitil olup yandı

uçsuz bucaksız yeşillikler

ılık yağmurları süzerken

deniz görmemiş gözlerimde

hüzün denizleri yıkandı

hüzün benim göbek adım 

cinler, periler ve devlerle gelerek

çocuk masallarıma damladı

bir şehzâde ikliminde yaşarken

masal kızları gönlüme girdiğinde 

beni en iyi o anladı

hüzün benim göbek adım

gök kuşağının ardından yetişemediğim 

nefessiz kaldığım zamanlarda

masalsız gecelerime konakladı

 (02 aralık 2001/üsküp)', 'hüzün benim göbek adım  yoksul ninnilerle  beşiğimde o uyudu, o sallandı pencerelerden sızan soğuk kış gecelerimde idare lâmbalarımda boy ve...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/huzun-benim-gobek-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem yüklü gemiler', 'ozlem-yuklu-gemiler-nagahan-orbay-akay-4557m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlem yüklü gemiler 

Demir attı kalbime 

Küsmüş gibi denizler 

Yol vermiyor sevgime. 

Hüzün dolu bir aşkı 

Yaşıyorum gizlice 

Dilimde hep o şarkı 

Ağlatıyor her gece. 

Hasret dolu tüm aşklar 

Bir efsane masal mı? 

O güzelim umutlar 

Boşa çıkan yalan mı? 

Nagahan Akay', 'Özlem yüklü gemiler  Demir attı kalbime  Küsmüş gibi denizler  Yol vermiyor sevgime.  Hüzün dolu bir aşkı  Yaşıyorum gizlice  Dilimde hep o ...', ARRAY['Türk Edebiyatı','Şiir','Nagahan Orbay Akay']::text[], 8.5, '{"poet":"Nagahan Orbay Akay","poet_slug":"nagahan-orbay-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozlem-yuklu-gemiler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzüm', 'yuzum-zati-erbas-rlt8p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gök

.......yüzü--(m)  

...............bulutlar bozar sessizliği.

gözlerimden 

yağmur eksilmezdi hiç.

kuşlar uyandırır

beni

gitmelere gönlümü kaptıralı beri

bulutlar nereye gider

kanadı kırık 

turnanın çığlığı; 

rüzgar

-----aklımda 

--------rüzgardan arta kalanlar

mavi

sen

gökyüzüyüm son zamanlarda ben.', 'gök .......yüzü--(m)   ...............bulutlar bozar sessizliği. gözlerimden  yağmur eksilmezdi hiç. kuşlar uyandırır beni gitmelere gönlümü...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yuzum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-ahmet-kumcu-t1ksr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanın içindeyim,

Kaybolmuşum dakikalarda.

Yüreğimden cılız bir ses,

Dakikada altmış kez.

Bilmem fark ettin mi seni seviyorumlarımı? 

(17 Temmuz 2005 Ahmet  Kumcu)', 'Zamanın içindeyim, Kaybolmuşum dakikalarda. Yüreğimden cılız bir ses, Dakikada altmış kez. Bilmem fark ettin mi seni seviyorumlarımı?  (17 T...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kumcu']::text[], 8.5, '{"poet":"Ahmet Kumcu","poet_slug":"ahmet-kumcu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zaman-243-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cerbeze', 'cerbeze-erol-dal-h6b5o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiçliğimizden başlar asıl yolculuk,

İlmek, ilmek dokunur rahimlerde kan.

Hissizliğimizden ise kaybederiz.

Başladığı yere döner herşey.

Yani hiçliğin kaynama noktasına.

Cehennem çukurlarına yakın yerlerinde yaşamaktır onun serüveni artık.

Oysa sen, 

Var olmak için yaşamayı

Ve kaybetmeyi sunuyorsun bana.

Var olanı yaşamak ne öyleyse

Esir olmak mı nefislere…

Tüm görevimiz kulluk ve ibadet,

Bunca mezhep, farklılıklar niye? 

Hepsi çukursa; 

Ve asıl sen çukursan; 

Üst nere? 

Alt nere? 

Cerbeze derler sorarsan,

Cezp etmek için söylerler cerbeze; 

Cerbezeleri cezp olur,

Cezpten cebe varır cerbeze.

Anla smileman anla …

Cebren yaptım cerbeze.

Mekan/2005', 'Hiçliğimizden başlar asıl yolculuk, İlmek, ilmek dokunur rahimlerde kan. Hissizliğimizden ise kaybederiz. Başladığı yere döner herşey. Yani ...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cerbeze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkin Yumrugu', 'askin-yumrugu-guner-kaymak-wtkxt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın yumrugunu gözün üstüne

Yediysen sen beni anlarsın dostum

Viran bahçelerde gonca gülleri

Derdiysen sen beni anlarsın dostum

Vefasız birini candan sevdiysen

Her çeşit zorluga gögüs gerdiysen

Yapayalnız tek başına kaldıysan

Çok iyi anlarsın sen beni dostum

Sıfırı tüketip iflas ettiysen

Yüzüne güleni dostun bildiysen

Ayagın kayıpta yere düştüysen

Eminim anlarsın sen beni dostum

Ömrünü yediyse amansiz yıllar

Saçına yagdıysa bembeyaz karlar

İhanet ettiyse dostun olanlar

O zaman anlarsın sen beni dostum

Çaresiz kaldıysan eli koynunda

Kim anlar seni,kimin umurunda

Ozan Güner gibi yolun sonuna

Vardıysan anlarsın sen beni dostum

Ozan Güner Kaymak / Amsterdam 22.10.2005', 'Aşkın yumrugunu gözün üstüne Yediysen sen beni anlarsın dostum Viran bahçelerde gonca gülleri Derdiysen sen beni anlarsın dostum Vefasız bir...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askin-yumrugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Gül Pıhtısı', 'kan-gul-pihtisi-ertugrul-sakar-dc41r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmek acı çekmek midir sence 

Hep beklemek midir yolcuyu 

Sevmek bulutlar gibi 

Güneşe örtmek midir örtüyü 

Kaybolmak mıdır yıldızlarca 

Uzaklaştırmak mıdır bulguyu 

Hep kar,hep tipi 

Denizde özlemek martıyı 

Acı,her acıdan ince 

Boynumda sanki güneşin ipi 

Kaybettim tat danilen algıyı 

Kan gül pıhtısı koyu 

Acıyı kaldır sevgiden 

Tatlandır gülüşlerinden', 'Sevmek acı çekmek midir sence  Hep beklemek midir yolcuyu  Sevmek bulutlar gibi  Güneşe örtmek midir örtüyü  Kaybolmak mıdır yıldızlarca  Uz...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kan-gul-pihtisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın Coğrafyasındayım Şimdi', 'sevdanin-cografyasindayim-simdi-selahattin-yetgin-f1rta', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu mutluluk salvolarında bütün yorumları acılarımızla büyüttük

Aşk, bizim için bütün iklimlerden, yalnız sevgi için geri dönüştü

Yokluğunda ne çok üşüdü parmaklarım, yüreğim, bir bilsen ne çok

Senden öğrendim bir ışığın yüzünden sulara çağlayarak dökülüşünü.

Şimdi yeni bir coğrafyanın sularına kırılacak sevda dümenimiz. Asil ve ikiz bir aşkın küllerinden doğarak, yorgun gönüllerimizi yeşil kırlara salacağız. Kırık kanatlarımızla belki de yüreğimizdeki bizi dolaşacağız. Uykusuz gecelerin pastil hazımsızlığını o sol yanımıza gömecek, bu yalnızlar gemisinde sevginin şiirlerini yazacağız. Gece bitmekte yunus gözlü. Gündüzlerin kurt kapanından esmer yüreğini uzak tut. Çünkü benim yüreğim artık kangrenli.

Yorumsuzluğumuzun mecburi salvolarında ikimiz de en çok kendimizi yorumlamayı seçerek, büyülü ve yalan bir gökkuşağına gülümsemeler bağladık. Ozanları, sahte şövalyeleri ve sönük yıldız düşlerini sudaki şiirlere çağırdık. Aşk ise hep suskun kaldı güzelim, hep tanımsız ilahilerle bizden uzaktı. Yıldız kaydı, şövalye vuruldu, gülümsemeler de, suların çekilmesini bekleyen garip bir rüyaydı.

Dilinin göğsümü ezen can sularında bu gece de seni  düşünerek sapladım hasret hançerimi gönlüme. Nefesinle ısındım soğuk gecelerin yaman çarklarında seni sürdüm tarifsiz yalnızlığıma melhem diye. Kollarını ruhuma, ruhumu yoluna döndüm, kaleminle, aşkınla ben bir kez daha senin için öldüm. Yüreğime kutsal ellerinle dokundukça, içlenmişliğim, fişlenmişliğim ve gücenmişliğim diz üstü yalvarılara dönüşüyor yeniden. Sevdan sarıyor benligimi gül bakışlım, bal süzüşlüm, yumuk gülüşlüm.

Hangi aşktır ki yokluğunda ince sızılarla canımı böyle  kıyarak ağlattı. Hangi aşka sarılıp gönlümü o geceki gibi gidişinle içlendirip ağlattı. Zaman gül dudaklım, öpüşünü saklayan, geceleri yalnızlığımı kucaklayan ayıpsız, aşikare bir saatti. Ve hangi sevgilidir bizi kavgalarda ve hasrette sonu evrende saklanan, tamamı olmayan bir mesaj gibi beklenen bir geceye bıraktı. Sevdan yine dilimdeki dualarla melekleri sana yollasın, öpsünler benim için doyasıya gözlerinin her zerresini.

Konuştuğum tüm coşkular adına uçurum kıyıları ezberledi adımı. Kendimden her söz edişimde bile seni dinlemeyi severek, senden öğrendim bir ışığın yüzünden sulara dökülüşünü. Küskün durmak adına sensizlikle konuşmayı denedim, iyimser suskunluklarımla. Oysa ne çok üşüdü parmaklarım bir bilsen, ne çok. Sımsıcak merhabalar yazdım adını her andığımda dizelere. Senden öğrendim ne varsa benliğimde, ne varsa senin için öğrendim taşlar fırlatırken durgun denizlere.

Senin için kendimi yıkadığım bu ak denizlerde, kendimi ararken bile sana ulaştım ben en onulmaz işkencelerle. Soluğum kesildiği zaman ağlamalardan, avuç içindeki çeşmelerden sular içtim kana kana. Sesini duydukça kavruldum, sönmeyen bir yangınla küle döndüm. Nereye gitsem, nereye yürüsem gölgendi peşim sıra yürüyen, hangi aynaya baktımsa seni gördüm, her acıyı şarkıya dönüştürdükçe seni düşündüm. Sevdam sevişti sensizken şiirlerinle. Kendimden koptuğum anlarda bile senin oldum, hasretinin kor alevlerinde öksüz kaldıkça dudaklarının esiri oldum.

İçimde yaşlı çınarların hüznü oluyordun kimi. İmgeler yaratıp iğde dallarından sığınaklar yapıyordum kendime. Sevdaydı içimizdeki özgürlük dirençlerini coşkuya çeviren. Maviler özlüyorduk, yeşil korkular ekiyorduk yüksek dağlara. Delinmiş yelkenleri onarıp onarıp uzun yolculuklara çıkıyorduk kimi. Eskimiş pencerelerde kendimizi izliyor, kirlenmiş odalarda birbirimizi bekliyorduk. Yalnızlığın kuşları göğümüzde kanat çırptıkça, biz sessiz gecelerde birbirimize çığlık çığlık şiirler ekiyorduk.', 'Bu mutluluk salvolarında bütün yorumları acılarımızla büyüttük Aşk, bizim için bütün iklimlerden, yalnız sevgi için geri dönüştü Yokluğunda ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdanin-cografyasindayim-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorun', 'sorun-numan-eksioglu-6yu52', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bunca derdi hiçbir kanat taşımaz

Zaten kanatlarımız birbirine yapışmış

Aynaların ön tarafı da sırlı

Sevginin çerçevesi gün geçtikçe minyatür

Yaralar büyüdükçe sargılar küçülüyor

Eksiler sıfırlardan uzaklaşıyor her an

Artılar tartıları kıpırdatmaktan aciz

Sıfırları saymalardan bunaldık

Gerçekler teleskopla birazcık seçiliyor

Hiçbir şeyden emin değiliz artık

Sadece sanıyoruz

Mutluluğa yanılgı sunuyoruz

Yüreklerin anahtarı kaybolmuş

Penceresi de yok oradan girsek

Ruhlar alçaldığınca bedenler yükseliyor

Aşksız düşsüz kin ve nefret aşınmaz

Zaten sevinçlerimiz ve coşkumuz yatışmış', 'Bunca derdi hiçbir kanat taşımaz Zaten kanatlarımız birbirine yapışmış Aynaların ön tarafı da sırlı Sevginin çerçevesi gün geçtikçe minyatür...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sorun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşmak/yazmak üzerine/dayatma ve sus güncesi..', 'kosmak-yazmak-uzerine-dayatma-ve-sus-guncesi-zafer-zengin-etnika-tw809', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '. DİKKAT! uzun uzun okumayı sevmeyenler giremez

Koşmak üzerine; 

Kimse koş demedi. O gün taktım kafaya, birazda rampa olan yerden aşağı doğru koştum. Yolun bitimi karayoluna çıkıyordu..Topuklarım kalçalarıma vuruyordu önce..hızımı alınca artık adımlarım beni alıp götürmeye başladı..Yüreğimin atışını duyuyordum. Karayoluna 30 metre falan kalmıştı ki durayım dedim duramadım..Aklımdan kendimi bırakmak geçti..Bıraktım ama ayaklarım arkamdan öyle tuhaf geldiler ki yerde 3 metre falan sürüklendim. Çenem acıyordu..Dizlerim göğsüm ve ellerimde ne kadar acı varsa toplamışlardı. Avuç içlerimden derimin içinden kum taş buğday sapları çıkıyordu.. Nereme dokunsam sancıyordum.. öyle acımıştım ki yinede onun gidişine benzemiyordu. Kendime sövdüm sonra

Ne zaman bir akılsızlık yapsam söverdim kendime. Kendimle gittiğim maceralarım hep benle. Oturdum yolun kenarına hem bana hem ona ağladım.

Yazmanın nedenleri; 

Konuşmayı unutmak için yazmaya başladım..Sonra tesadüfen susun ne  olduğunu öğrendim..İlla orada olayım diyorum bazen..Dışardan bakanların manyakça bulduğu  bir şeymiş gibi ne zaman sevişmek desem yüzüme bakıyorlar..Dünyanın en acı  en garip kelimesi sanki sevişmek.. Oysa aç bir insan, kadın erkek fark etmiyor..ne kadar da hasret başka bir insana.. şanslı saydım kendimi hep.. Aşık olmasam bile  beni seven  kadınlarım oldu.. İnsan yaşayıp da güzel şeyleri gördükçe sırf bozulmasınlar diye azaltıyor onları geri yaşamayı. Rutinliğin gölgesi örtmesin istiyorsun.. Çok beğendiğin bir şarkının bile bir süre sonra insanı canından bezdirmesi gibi haller işte..  Sevgi çeperinin yanında kalıyor içeri giremiyor.. Yaban bulanların sana yaklaşımı da böyle.. yenecek bir şey değil diyorum insan.. dilimizin açlığımı, içimizin mi daha baskın diye izliyorum.. Yanlış

kapıdan gelen misafir gibi geliyor bazı insanlar.. Vermeden dostluk sevgi kapısı açılsın istiyorlar.. Oysa güven kapısı kurulmadıysa servet parada geçmez orada diyorum.. Geçse zaten paylaşılır senin benim söylemleri ölür kalır.. Kendime saklıyorum fikirlerimi  bir duş alsam ıslansam cesurca soğuk su altında kendime gelsem, hoş gelsem diyorum

Sakallarımı da keserim.. Temiz görünmek yakışıyor bana ve insanlara.. oysa serseri bir  Gezgin olmak hep aklımda kalan şey..kimsenin aramadığı şeyleri aramak.. duyulmamışları duymak.. öğrenilmemişleri öğrenmek ne güzel olurdu.. sadece ne güzel olurdu da kalacak şeyler belki..hem kimin umurunda..herkes düşmüşken kendi kuyusuna..Sözler dönüp dolaşıp

Geliyor züleyha ile  yusuf’a..yusufun bile kuyusu var..sanki kaçıp kendini

Saklayan insanların sığınakları evleri barkları..inzivaya çekilen dağ evleri

Ya da çile haneler gibi..yusufun bile kuyusu..sanki bizim yok..Kör karanlıkta şiir ışığından bulmak bir şeyleri..yazmak kuyudan cıkmak belki

Belki de belki.

Dayatmalar ve kurallar üzerine ve mesela dilbilgisi; 

Özgürlük ve uçmak aklıma nasıl geldi bilmem..sanki bu eylemi yapan herkes aynı çizgiye gelince garip bir şekilde içinden uçma isteği geçiyor.. “Pink floyd” dinlerken bile özellikle “learning the fly”çalınca kulağımın dibine kolonları koyup hele yalnız kaldığım zaman o gecelerde uçup giderdim ki.. uyku bir güzel uçmaktı bence..hele ne zaman uyudum nasıl daldım bilmemek en keyifli işlerden biriydi..ne zaman yalnız kalsam dinler uçardım..hep o uçurum ve uzakta görünen  uçurum dibi gelirdi aklıma.. Nedense dibinde bir göl düşünüyordum.Sanki o yükseklikten düşersem ölmeyecekmişim gibi oysa 30 metreyi geçen yükseklikten insan düştü mü biliyorum ki su beton etkisi yapar taş kesilir resmen..Hiç yapmadım ya Rüyalarımda düşlerimde yapıp kolayına kaçıyorum..Ölmek adına değil de o korku ve o heyecan nasıl bir şeydir bilmek isterdim hala..Belki de hala çok korkuyorum.. Kendinden ve başkalarının düşüncelerinden çok korkanların bile düşleyemediği şeyleri düşlüyorum..En olmazlar en olurlar arasında farkları görmek tek sıradan insan kimliğinden koparıyor insanı kaldırımdan inerken bile binlerce şey düşünenlerin olduğunu düşünüp iyi ki..Onlar gibi değilim diyorum

Gidip sigara alsam çok içmeye başladım.. ne zaman yazmaya otursam ipin ucunu kaçırıyorum..  tütün rengini alacağım diye düşünüyorum.. Ali’ye gitsem keşke.. bir sinemaya giderdik.. o ses bombardımanı içinde mısır yer kola içip kaybolurduk. Ne çok çalışıp ne az şey yapıyoruz bu son aylarda ona şaşıyorum.. ne için kim için bu iç parçalama aklım almıyor

Alsa da görmezden geliyor..su akar yatağını bulur, olursa olurlarda bir 

Yanım..

 Zor beğeniyor insanlar artık.. Güvenmiyorlar çok didikliyorlar insanı..demek ki hatalardan bundan dolayı oluyor diyorum.. ne kadar çok güvensizlik kokuyor ortalık bu koku beni hem ürkütüyor hem tiksindiriyor artık.. korkmaktan değil bu kokudan tiksindim artık.. ve düşünmek diyorum

En fazla bir insandan sevgi beklemek.. ne anlar ki bu durumdan o da çok şüpheli.. Kimse düşünmüyor sanki herkes bir telaş içinde yaşayıp hemen mutlu olayım derdinde.. Bunu o kadar kolay görüyorum ki.. Keşke görmesem daha rahat olurdum diyorum.  Şu son filmde güzeldi.. O eski bize güzel gelen aşkların olduğu filmlerde yok artık.. En son “melekler şehri”aklıma geliyor bir de “Leon” adlı film garip işler belki ama oradaki tam teslim olmuş aşklara imrenmemek elde değil..Sonra dönerim bu konuya belki.. şimdi bir şişe bira olsa da içseydim boğazımı yaka yaka inseydi şöyle aşağıya ne iyi olurdu..Sarhoşluğu sevmiyorum..Az azık

biraz su ve sırtta yatakla gezginliğe çıkmak sanıyorum çakır keyifliği.

Bu yüzden belki en çok kaçmalarım geceleri..Ne ye lazım ki hangi

Yöne gittiğin..belki soğuk olmayan bir yer..dışarıda da yatsan üşümezsin.

Üşümek halen canımı sıkıyor. Daha kemiklerim ısınmadan yazda bitti.

İçimi daraltan kendini kanırta kanırta tanıtan hüzün mevsimi de geldi.

Yağsın yağmur elbette şöyle iki saat sonra açsın hava..anlayalım

kapalının ardından açığın içimize faydalarını..hani depresiflik değil bu aslında..ışık insanı tutuyor bazen ayakta..şimdi ne kadar çelişki varsa yazıyorum..hepsi benim..ne kural ne kaide ve korkmakta yok.

Sus’a giderken; 

Her sabah bir sus geliyor kapıma..Gözlerimi zor açıyorum, el yordamıyla tutuyorum ışığı..Ortamıza bırakıyorum..Her sabah böyle..Çok sonraları anlıyorum ki bir kuş bu..Ağladığını seziyorum bazen kendime gücüm yetmezken teselli havuzunda el uzatıyorum ona..seviyorum..Birbirimizi

Görmesek  saçımızdan teller düşüyor.. Bazen dünyanın en çaresizi oluyorum..bir gün ne yaşadın diye sorduklarında az şey diyeceğim..ne çok yaşattım bana kalacak belki..önemsemiyorum..dağların ardını göremesem de denizin içinde küçük balıkları görüyorum..onlarla geziyorum dipleri..seviyorum bu gezmeleri..en çokta öğlen üzeri

Sessizliğin dinlendiği saatleri..akşamlar yine çakırkeyif beklemek

Kalemi elime alıp yazmak içimin gördüklerini..en sevdiğim iş şimdi

Aklım emekli olsam ne yaparımlar da..o zamanlar gelsen otursan yanıma

Çay içsek seninle..bazen susarız uzaklara bakarız..bakarız.

Sus nedir, bana görenin yazılı hali; 

Sevişirken tanrının bile adının anılmadığı yer  diyorum..O son nokta

Bana göre hiçliğin hissedildiği tek yer..sonrası sigara yakmak

İçi tekrar hatırlamak..inansam başka adlar koyardım..Benlik bir şey yok

Sırf  onlar anlasınlar diye “sus”a orgazm anı diyorum şimdi..Güzel isim

Değil mi hani top atılsa duymuyorsun..Sen senlikten çıkıp isminden

Milliyetinden dininden ve statünden sıyrılıp yalın insan kalıyorsun orada

Herkesin ortak ve aynıya yakın hissettiği tek şey belki..Tartışırdım

Yorgunum diye dokunmuyorum..tekrarlar baygınlık veriyor bazen

Kendime susuyorum..Ben’imin ellerini ısıtıp yanaklarıma sürüyorum

Kendime kendimi hatırlatmak ancak böyle oluyor.

Sus sana anlatmadığım bu şey işte..merak eder sorardın ya senle hiç yaşamadığımdandı..Hani istersin başımı belaya sokarsın diye saklayıp “boş” ettiğimdi. Hiçlik ve boşluk üzerine söylediklerimi düşünüyorum..Genel bilgilerle anlatamadıklarımı ya da sakladıklarımı bilmem kaç cilt kitaptan okumuş, anlatmaya çalışan kendi dışında okudukları olan “o insanlar” geliyor aklıma..haklarıdır diyor ses çıkarmıyorum..Oysa başka dünya olmalı kendilerini tanıma yolunda..kaç yol var..kaça bölünmüş onu anlıyorum Benden bu kadar şimdi gidiyorum..Tercihimi dilediğimce yapıyorum..Dünyanın en güzel gözleri,sözleri ve memeleri kandırmıyor beni..çirkin şeylere teslim oluyorum..kuralları daha sade..en ilgincide kurnazlığın “iç” için kullanıldığı ender yerlerden diyorum..hırs yok orada..seni istiyor ve alıyor..Donanımların tecrübelerin öldüğü yer işte..yalnızlığın karşılıklı değişildiği yer..kendimi kandırsam da teslim oluyorum..oysa biliyorum sonuçlarını.. aldırmıyorum işte bir kereye mahsus kendimi yol kenarında meyve vermiş erik ağacı yapıyorum..ya da susamış bir yolcuya ucu yosun tutmuş çeşme..uykum geldi gitmeliyim..Güzel gülmeyi unutma.. Gözlerinden öperim..yanaklarından ve alnından..aklım karışmasın diye öpücük almıyorum dudaklarından..

Sus nedir derken, bildiklerimi unutuyor..sırada ne var onları bekliyorum...

..', '. DİKKAT! uzun uzun okumayı sevmeyenler giremez Koşmak üzerine;  Kimse koş demedi. O gün taktım kafaya, birazda rampa olan yerden aşağı doğr...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/kosmak-yazmak-uzerine-dayatma-ve-sus-guncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızların Şairi', 'yalnizlarin-sairi-harun-senel-t23bj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimden yüreğine gönderiyorum bu şiiri

Sen gittin ya şimdi ne ölüyüm ne de diri

Bulunmaz,dönülmez,çıkılmaz bir yoldayım

Avare bir halim,karmakarışık biriyim

Yatağım geceleri diken,yüreğim kor 

Aklım her geçen gün çıkmaza giriyor

İçimin sızısını yıldızlara sor

Parçalansa da yüreğim,aşkıma sadık biriyim

Duamda ellerimin sayısız çizgisindesin

Dilimde tabiri tanımsız kelimelerdesin

Senelerin yorgunluğundaki alnımın izindesin

Yine de sen bir zalim,ben hep aşık biriyim

Aşk sürgün,sevdam sürgün,ben sürgün

Sürgün bedenim çürümektedir hergün

Pişman olup döneceksen de birgün

Sen bir hain,ben yolların eriyim

Kaderimle hiç bitmeyecek savaşım

Gecemde yıldızlar oldu sırdaşım

Kalemim davamda bir yoldaşım

Avare bir halim,YALNIZLARIN ŞAİRİyim

         Yalnızların Şairi

     (05.10.2005)', 'Yüreğimden yüreğine gönderiyorum bu şiiri Sen gittin ya şimdi ne ölüyüm ne de diri Bulunmaz,dönülmez,çıkılmaz bir yoldayım Avare bir halim,k...', ARRAY['Türk Edebiyatı','Şiir','Harun Şenel']::text[], 8.5, '{"poet":"Harun Şenel","poet_slug":"harun-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalnizlarin-sairi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Doydu Ki Ölüm', 'oyle-doydu-ki-olum-numan-eksioglu-g4kgi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Attila İlhan''a

Dün bir sürü kelebek 

Baş sağlığına geldi

Birşey söyleyemedim

Yalan 

Beni çaresiz kılandı o

Diye konuşma yaptı

Maske 

Benim saçımı yolandı o

Diye nutuklar çekti

Sorunlarsa bizim artık yarınlar

Diye bayram ettiler

Birşey söyleyemedim

Sevgi bir büyük içti

Sevda kendinden geçti

Saygı çok kaygılıydı

Birşey söyleyemedim

Bir şiir yazdım ancak

Öyle yoruldu ki garip azrail

Bir ay tatil yapsa da dinlenemez

Öyle doydu ki ölüm

Artık uzun süre acıkmayacak', 'Attila İlhan''a Dün bir sürü kelebek  Baş sağlığına geldi Birşey söyleyemedim Yalan  Beni çaresiz kılandı o Diye konuşma yaptı Maske  Benim s...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oyle-doydu-ki-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim', 'kalbim-i-brahim-sahutoglu-5u6uy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her telefon çaldığında 

