INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Zaten', 'ben-zaten-aysel-zengingul-kqd54', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim sevdasını avans bıraktı

Camlı parlak vitrinlere…

Hangisine yakışıyordu

En çok kırmızı…

Yorulanlar yollarda mı kaldı? 

Geriye dönme olanağı taşımadan..

Ben ne geriyim sana, 

ne önde gideniyim sevinçlerimin

orta halli bir dağınıklığım,

toparlanmaya çabalı…

Hangi sevdalı en çok seviyordu

Yalanını kendisinden...

Kitaplarda umduğunu bulamamak

Kimin fikri azizliğiydi…

Seni yazmamışlar yine…

Düşüncelerim soru işareti

Çengelinde intihara gitmiyor mu ya? 

Bu defa diyorum; 

Bu defa olmasın artık! 

Karlı geçitlerinden Erzincan’ım,

O esmer çocukluğum

Üşümesin, kırılmasın artık…

Kimler öznesini özelleştirip

Vurgunlara kaçmadı ki..

Hayat arşivlerini kaldırmış,

Gün tutuyor iri gözler…

Ne zaman bir mevzuya başlasam senden; 

Mevzu beni aşıyor…

Mevzusuz kalmıyor muyum? 

Susuyorum, sus oluyorum…

Melullenmiş sevda sakinleri,

Karanlık ayaza çekiliyor.

Beyoğlu’nda bu vakitler,

Efkara yükleniyor bakışlar.

Serseri zamanlarım çoktan geri kalmış.

Ortalarda henüz yayla zamanlarımın; 

Bu ne efkar diyor! 

Bu ne bitim! 

Dur hele dur diyor ki! 

....Ben

 ............ zaten 

               ..................durmaktayım…

24/09/2005 ist. 04; 52', 'Kim sevdasını avans bıraktı Camlı parlak vitrinlere… Hangisine yakışıyordu En çok kırmızı… Yorulanlar yollarda mı kaldı?  Geriye dönme olana...', ARRAY['Türk Edebiyatı','Şiir','Aysel Zengingül']::text[], 8.5, '{"poet":"Aysel Zengingül","poet_slug":"aysel-zengingul","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ben-zaten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar Temizdik', 'bir-zamanlar-temizdik-banu-balat-rtkiq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamanın gölgesinde 

Bir salıncaktayım şimdi 

Usul esen akşam rüzgarının 

İçinden geçiyorum 

Bir ileri, bir geri 

Yüzüme dokunuyor elleri 

Tıpkı anneminki gibi 

Saçımı okşuyor sanki 

Ve 

Gözlerimi kapatıp 

Bırakıyorum kendimi 

Bir de bakıyorum ki 

İçinde olduğum yer 

Anıların bahçesi 

Gerçek dostluk ve sevgi 

Hepsi orda dipdiri 

Kirlenmişlik sadece 

Elbiselerimizdeydi.....', 'Zamanın gölgesinde  Bir salıncaktayım şimdi  Usul esen akşam rüzgarının  İçinden geçiyorum  Bir ileri, bir geri  Yüzüme dokunuyor elleri  Tı...', ARRAY['Türk Edebiyatı','Şiir','Banu Balat']::text[], 8.5, '{"poet":"Banu Balat","poet_slug":"banu-balat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-zamanlar-temizdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk''çe Dertleşmek...', 'turk-ce-dertlesmek-dursun-elmas-2n9xp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk duyduğum ninni,ağaç beşikte

Türkçe söyleşirdi,Türkçe gülerdi

Ay şafak gecede,ninem eşikte

Türkçe ağlaşırdı,Türkçe inlerdi.

Düğünde dernekte, çalınan sazlar

Aşığın dilinden, çıkan avazlar

Pınarbaşlarında, gelinler kızlar

Türkçe çağlaşırdı,Türkçe dinlerdi.

Çoban kavalında içli nağmeler

Yunus''tan duyduğum; ilk ilâhiler

Çevrede gördüğüm; tüm esamiler

Türkçe dertleşirdi,Türkçe derlerdi.

Sevda yüreklerin; yanık türküsü

Çelik bileklerin; Turan ülküsü

Şimşekte parlayan, gök gürültüsü

Türkçe konuşurdu,Türkçe gürlerdi.

Böyle değil idi,eskiden dostlar

Hep bizi söylerdi,dilde şarkılar

Bostanda sekiyen, kınalı kuşlar

Türkçe gülüşürdü,Türkçe ünlerdi.', 'İlk duyduğum ninni,ağaç beşikte Türkçe söyleşirdi,Türkçe gülerdi Ay şafak gecede,ninem eşikte Türkçe ağlaşırdı,Türkçe inlerdi. Düğünde derne...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/turk-ce-dertlesmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Delinin Öyküsü', 'uc-delinin-oykusu-husam-hasret-ncn7o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birinin vapurları dalgalara tutulmuş

Duyguları kaybolmuş sınırsız bir limanda

Yaşamak öyküsü de öyle ki unutulmuş

Nesi var, ya nesi yok o bir boş konu ancak

saplanmış yüreğine eziyetsiz bir bıçak

Ne yaşamı seviyor, ne de gözü zamanda

Birinin dil ucunda yarım horyat dolaşır

Ağlar başlangıcına, güler bitmemesine

Ne bir yorum tasarlar, ne sonuca ulaşır

Boş bir çember içinde salı verir huyunu

Horyatını kovalar bitmeyince oyunu

Gelişin nefretini sunar gitmemesine

Birinin elinde var bir parça kırık ayna

Yüzünü kaybetmış ki cizgisini arıyor

Ne halka benzer, ne de bir halk benzer kendine

Kah aynayı temizler, kah aynaya tükürür

Kah olur öfkelenir alev alev püskürür

Ne yazık bu kavgayla günden güne eriyor', 'Birinin vapurları dalgalara tutulmuş Duyguları kaybolmuş sınırsız bir limanda Yaşamak öyküsü de öyle ki unutulmuş Nesi var, ya nesi yok o bi...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uc-delinin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi', 'simdi-husam-hasret-wvpsq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazık olur satma beni

Gücden düşen kulum şimdi

Çarşılara atma beni

Harcanmayan pulum şimdi

Hayalim geç, düşüm erken

Seraba açmışım yelken

Her bir şeyi ak görürken

Siyahlanmış tülüm şimdi

Boş yaşamı ne sandım ki

Kılığına aldandım ki

Hırsımdan bir tür yandım ki

Savruluyor külüm şimdi

Kaybolunca bölüm bölüm

İstemezdim böyle olum

Belli değil sağım solum

Karanlıktır yolum şimdi

Gömülünce dert sinemde

Umut kaldı bilmem nemde

Bir değil, çok bir nesnemde

Anıklanır ölüm şimdi', 'Yazık olur satma beni Gücden düşen kulum şimdi Çarşılara atma beni Harcanmayan pulum şimdi Hayalim geç, düşüm erken Seraba açmışım yelken He...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/simdi-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Acısı', 'gurbet-acisi-ahmet-ormanci-1ocan', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutuldum bu uzaklarda,

Ne bir selâm var, ne bir haber,

Kimse hatırlamaz mı beni? 

Ne kapımı çalan var, ne beni soran.

Ruhum gurbetler içinde gurbetlerde,

Anlamıyorum insanların dilinden,

Ne konuşan var benimle, ne elimden tutan.

Dilinden tek anladığım işte bu ezan,

İşte tek ses bu, sizleri bana yaklaştıran.

Bir de sigaram var,

Biri sönen biri yanan,

Her çekişte hasretimi körükleyen sigaram.

Her şeye hasretim burada,

Sevgiye, dostluğa, huzura.

Kimse bilmez derdimi,

Kimse sormaz, halim nasıl.

İnsanlar hep yabancı,

Tanıdık bir sima arar gözlerim,

Kimse dönüp bakmaz.

Bazen duygulanır ağlarım,

Ağlarım doyasıya.

Kimse gözyaşımı silmez.

Hastalanırım bazı günler,

Düşerim yataklara,

Kimse gelip görmez.

İşte bu gurbet elde,

Hasretim ben her şeye.

1992', 'Unutuldum bu uzaklarda, Ne bir selâm var, ne bir haber, Kimse hatırlamaz mı beni?  Ne kapımı çalan var, ne beni soran. Ruhum gurbetler içind...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gurbet-acisi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimkisi Çiçeğe Duyulan Özlemdi', 'benimkisi-cicege-duyulan-ozlemdi-baris-sevinc-eb9x5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zaman soyunsa ağaçlar çıplaklığa,

Bırakıp gitse yapraklar dalları

Ve güneş terk etse göğü,

Dünya üşüse

Ve o tek rengin hakim olduğu

O mevsimde,

Ben de üşüyerek,

Ben de yalnız,

Mavi gök ve gri dallar gibi 

Ben de terkedilmişken yazdım şiirlerimi.

Yeter ki gün doğsun renk renk,

Boşaltsın tohumlarını bahar

Doğanın  rahmine,

Toprağı zorlasın milyonlarca fidecik,

Yeni güne merhaba desin  binlerce yavru

Ve yeniden çiçeklensin dünya…

Ben şiir yazmasam da olur.', 'Ne zaman soyunsa ağaçlar çıplaklığa, Bırakıp gitse yapraklar dalları Ve güneş terk etse göğü, Dünya üşüse Ve o tek rengin hakim olduğu O mev...', ARRAY['Türk Edebiyatı','Şiir','Barış Sevinç']::text[], 8.5, '{"poet":"Barış Sevinç","poet_slug":"baris-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benimkisi-cicege-duyulan-ozlemdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-emin-acil-slb15', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir yağmur yağsa

Oturur seni düşünürüm

Sen yolunu gözlediğim olursun

Ben camdan bakan arap kızı

Gözlerim gözlerini arar 

Ellerim ellerini....

Bulamaz

Ve öyle bir boşluk doğarki içimde o an

İnan ama inan

Sen olmadan dolduramam

Ne zaman bir yağmur yağsa

Pişmanlıklarım hortlar

Başlar dır dır etmeye özlemlerim

Keşke de keşke.....

Sonra sen yolunu gözlediğim olursun

Ben şefkate muhtaç bir çocuk

Şiirlerim asılı kalır niyetlerimde

Çabalarım ıslak ıslak sinerler

Sürülmüş bir mahkum olur ömrümün delikanlı günleri

Biçare kendime dönerim

Ve bilirim beyhudedir bütün bildiklerim

Bir kaç söz ederim sonra 

Sonra ağlamaklı olur sesim

Bir başkası olurum

Tenim tenini arzular

Sarhoş olurum

Ve öyle bir yalnızlık kaplarki içimi o an

İnan ama inan

sana  sarılmadan anlatamam

Ne zaman bir yağmur yağsa

Sen güneşli bir bahar günü olursun

Ben yağmurdan nefret eden adam

Canım o kadar cok sıkılır ki yağmura o an 

İnan ama inan 

Ağlamadan anlatamam.', 'Ne zaman bir yağmur yağsa Oturur seni düşünürüm Sen yolunu gözlediğim olursun Ben camdan bakan arap kızı Gözlerim gözlerini arar  Ellerim el...', ARRAY['Türk Edebiyatı','Şiir','Emin Açıl']::text[], 8.5, '{"poet":"Emin Açıl","poet_slug":"emin-acil","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yagmur-231-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-ahmet-ormanci-fhhou', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum.

İşte bak, seni seviyorum diyorum,

Sen duymasan da.

Seni özlüyorum,

Sensiz geçen her gün eritiyor yüreğimi,

Sen hissetmesen de.

Kavuşmak istiyorum sana,

Şu yolları geçmek,

Şu dağları aşmak istiyorum.

Tatlı sesini duymak,

Sıcak elini tutmak,

Rüyalarda bile olsa,

Seni görmek için.

1992 – Mardin', 'Seni seviyorum. İşte bak, seni seviyorum diyorum, Sen duymasan da. Seni özlüyorum, Sensiz geçen her gün eritiyor yüreğimi, Sen hissetmesen d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-seviyorum-297-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumartesiler', 'cumartesiler-ahmet-ormanci-xkxl6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte hüzün dolu bir cumartesi daha,

Bütün cumartesiler gibi.

Çünkü; sensizliğin doruğu bugün, 

Alışılmış bir zaman.

Senin sesini hep o gün beklerim.

Neden mi? 

İlk sesini o gün duymuştum,

Tabi son sesini de.

Belki bu cumartesi, belki bugün,

Yeniden başlarız diyorum kendi kendime.

Ama boşuna bekliyorum galiba,

Baksana yine akşam oluyor,

Bitiyor bu cumartesi de.

Eriyor bütün hayallerim,

Tıpkı sular gibi akıp gidiyor,

Kayboluyor gözden.

İşte bir cumartesi daha bitti.

Ama ben bekleyeceğim yine yılmadan,

Diğer cumartesileri.

Sensiz geçen bütün cumartesiler gibi.

21/11/1992 Cumartesi – Mardin', 'İşte hüzün dolu bir cumartesi daha, Bütün cumartesiler gibi. Çünkü; sensizliğin doruğu bugün,  Alışılmış bir zaman. Senin sesini hep o gün b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cumartesiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ahmet-ormanci-m0los', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şeyimde sen varsın,

İçimde, dışımda,

Benliğimde, hayalimde.

Yürürken şu çamurlu yollarda,

Sen varsın hep yanımda.

Sağ kolum sıcacık bu soğukta,

Neden dersin? 

Çünkü, sen varsın kolumda.

Işıksız, sessiz gecelerimde,

Sen varsın odamda.

Sabah kalkıp baktığım ayna da bile,

Aksim yerine, sen varsın.

................ hep sen.

	

1992 – Mardin', 'Her şeyimde sen varsın, İçimde, dışımda, Benliğimde, hayalimde. Yürürken şu çamurlu yollarda, Sen varsın hep yanımda. Sağ kolum sıcacık bu s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-664-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-ali-osman-yilmaz-3ev8v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sevda yüzünden,

Gurbet ile düşsende,

Sabretmelisin,ya gönül.

Yaban ilde ağlayıp,

Sevdanı dillere,

Düşürmeyesin,ha  gönül.

Seher vakti  güneş,

Sana da doğar elbet,

O gün geldiğinde,

Ah demeden koşarak,

Atıl sevdalının boynuna,

Çatma kaşın,ey gönül.

Bir karakaş,

Bir mavi göz ile,

Aklını başından alıp,

Yüreğini dağlayan,

Sevdanın yangınıyla,

Seni gurbet  İl’e katan,

Dağ bayır demeden,

Enginleri aştıran,

O kutsal sevdaya,

Asi olma,del gönül,

Ateş böceklerini,

Avuçlarına toplayıp,

Savur göklere,

Sevda yıldızları gibi,

Geceler boyu bizlere,

Dedem Ay’ın yanından,

Sevdalımın gözlerinden,

Yayılan ışıklar gibi,

Göz kırpsınlar,her gece.

Gözün kaçırma,bak gönül', 'Bir sevda yüzünden, Gurbet ile düşsende, Sabretmelisin,ya gönül. Yaban ilde ağlayıp, Sevdanı dillere, Düşürmeyesin,ha  gönül. Seher vakti  g...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gonul-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkulu Rüya', 'korkulu-ruya-ahmet-ormanci-24knf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin ortasında sensizim.

Gaz lambasının aydınlatamadığı,

Soluk sarı duvarlardan olsa gerek,

Hüzün kaplıyor yüreğimi.

Ümit ederim, sabah duyacağım haberin,

Hüznü değildir bu.

Neden, şu son zamanlar bir tuhafım,

Umarım sensiz kalacağım demek değildir bu! 

Korkulu rüyanın sonu hayırdır derler,

Hayırdır inşallah! 

Ama; korkarım korkulu bir rüya değildir bu! 

1992- Mardin', 'Gecenin ortasında sensizim. Gaz lambasının aydınlatamadığı, Soluk sarı duvarlardan olsa gerek, Hüzün kaplıyor yüreğimi. Ümit ederim, sabah d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korkulu-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-ahmet-ormanci-qw36e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah ayrılık...

Adına türküler yakılmış,

Şiirler yazılmış sana yıllarca,

Ümitle bakılmış hep ardından.

Bazıları mutlu, kavuşmuş sevdiklerine,

Bazıları hüzünlü, o türküleri okuyor,

Bazıları da benim gibi ümitli,

Hâlâ o şiirleri yazıyor.

Ve korkarım daha çok yazacaklar.

1992- Mardin', 'Ah ayrılık... Adına türküler yakılmış, Şiirler yazılmış sana yıllarca, Ümitle bakılmış hep ardından. Bazıları mutlu, kavuşmuş sevdiklerine, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayrilik-302-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamıyorum', 'unutamiyorum-ahmet-ormanci-h751d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte ayrıldık sonunda,

Şimdi sen,

Daha mı mutlusun bensiz.

Ben mi? 

Ben ha! 

Hiç yapmadığım şeyleri yapıyorum artık,

Sensiz kalmışçasına,

Hayattan bezmişçesine, ayyaşım.

Beni arasan, istesen bile,

Eski saflığımda değilim artık.

Şimdiye kadar hep seni düşünürdüm,

Şimdi ise sensizliği.

Sensizliğe alışmaya çalışıyorum,

Aşk ve sevgi şarkıları dinlemiyorum artık,

Aşk ve sevgi şiirleri yazmıyorum.

Ama, bilmem neden,

Seni unutamıyorum farkındaysan,

Yine seni düşünüyor,

Yine seni yazıyorum satırlarıma.

	

1992-Mardin', 'İşte ayrıldık sonunda, Şimdi sen, Daha mı mutlusun bensiz. Ben mi?  Ben ha!  Hiç yapmadığım şeyleri yapıyorum artık, Sensiz kalmışçasına, Ha...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unutamiyorum-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-husam-hasret-3ml8g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben güneş gibi doğar, güneş gibi batarım

Ben istediğim yerde çulum atıp yatarım

Ben bir ülküye kanıp ona başım çatarım

Beni zaman değişmez, ben böyle bir Türkmen''im

Ben bildiğim ederim, kimseden emir almam

Ben kimseye baş eğmem, kimse rahmına kalmam

Ben inandiğim doğru ülküyü zaten salmam

Beni baskı döndürmez, ben özgürüm, ben benim

Ben düz yolda yürürüm o yan bu yana bakmam

Ben yaptığım iş belli, onu övmeye kalkmam

Ben ülkümden başka bir ülkü kabına akmam

Ben kendimi kandıran kandırıcı imanım

Ben ne boş söze, ne de doğru söze aldanmam

Ben doğru bildiğimden başka bir şeye kanmam

Ben ülküme inanır, ham hayale  inanmam

Ben ''''çakçakaya dalmam, iş gören değirmenim''''

Ben özgür bir ağacın meyvesiyim, barıyım

Ben her özgür kimsenin kardeşiyim, yarıyım

Ben ülkümün sarsılmaz Türkmen fedakarıyım

Ben Türkmen anaların Türkmen sütün emenim

Ben bir avuç mal icin doğru yolumdan sapmam

Ben yoksullar agzından kuru lokmayı kapmam

Ben ülküme hizmetkar, hiçte kölelik yapmam

Ben insanı hür bilen vicdanli Müslümanım

Ben millet çıkarından başka çıkar gözetmem

Ben kısa biten işi, boşuna hiç uzatmam

Ben ülküme sığınır, onu düşe benzetmem

Ben gerçek aşığıyım, ben seraba düşmanım', 'Ben güneş gibi doğar, güneş gibi batarım Ben istediğim yerde çulum atıp yatarım Ben bir ülküye kanıp ona başım çatarım Beni zaman değişmez, ...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-208-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değmezmiş', 'degmezmis-ahmet-ormanci-zj52a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkımızı gerçek sanmıştım,

Gördüm ki yanılmışım.

Sana söylediğim güzel sözleri,

Verdiğim güzel duyguları geri alıyorum,

Çünkü, sen bunları hak etmedin.

Sana yazdığım duygu yüklü mektuplar,

Adına bin düşünüp, bir yazdığım şiirler,

Bunlar için harcadığım mürekkep bile boşa.

Seni görmek için çabalarım,

Hele hele, senin sahteliğinle beraberken,

Ve seni düşünürken harcadığım zamanım.

Geleceğimizi hayal ederken,

Uykusuz kaldığım geceler.

Meğer sen bunlara lâyık değilmişsin.

Ne fayda ki bunu çok geç anladım.', 'Aşkımızı gerçek sanmıştım, Gördüm ki yanılmışım. Sana söylediğim güzel sözleri, Verdiğim güzel duyguları geri alıyorum, Çünkü, sen bunları h...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/degmezmis-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Devrim', 'i-cimdeki-devrim-baris-sevinc-8ts02', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Otururken yine aynı kafede

Yanımda sen ve tanıdık insanlar

Dalmış gitmişim uzaklara

Gözlerim bir hoş bakıyor.

Yine aynı uzaklarda kalabalık var

Dönmüşüm yüzümü insanlara, sırtımı değil

Seçiyorum yoldaşlarımı birer birer

Onlarda da aynı heves, aynı heyecan var.

Yine aynı uzaklarda üzerimde şair ceketim

Yakaları duvar dikliğinde ve sert

Başımda kasketim kan ter içinde

Elimde ise bildiğim tüm öğretiler var.

Yine aynı uzaklarda ellerim havada

Bir avucumda özgürlük ötekinde isyan

Yoldaşlardan yükselen uğultu, çığlık, kargaşa

Sanki devrim öncesi eylem tadında

Bir öpüşüm yetti bana, toparlandım

Etrafıma baktım yine sen ve tanıdık insanlar.

Belki o geniş kalabalıkta değildim ama

Umutluydum, yine de heyecanlı

Geleceğe ertelenmiş hayallerimle

Bir adım yol daha aldım.', 'Otururken yine aynı kafede Yanımda sen ve tanıdık insanlar Dalmış gitmişim uzaklara Gözlerim bir hoş bakıyor. Yine aynı uzaklarda kalabalık ...', ARRAY['Türk Edebiyatı','Şiir','Barış Sevinç']::text[], 8.5, '{"poet":"Barış Sevinç","poet_slug":"baris-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/icimdeki-devrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Zordur', 'yalnizlik-zordur-ahmet-ormanci-5bosk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızım şu dört duvar arasında,

Dilleri yok benimle konuşsun,

Kulakları yok, beni duysun şu duvarlar.

Konuşacak birine,

Duyacak bir sese,

Muhtacım.

Duygusu yok ki duvarların,

Halimi bilsin.

Elleri kolları yok ki,

Beni sıcacık sarsın.

Halimi anlayacak,

Sımsıkı sevgiyle saracak,

Birine muhtacım.', 'Yalnızım şu dört duvar arasında, Dilleri yok benimle konuşsun, Kulakları yok, beni duysun şu duvarlar. Konuşacak birine, Duyacak bir sese, M...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizlik-zordur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-ahmet-ormanci-2p9ik', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kolay şeylerin paylaşması da kolaydır,

Önemli olan zoru paylaşmak.

O, uykusunu paylaştı benimle,

Uyumadı, uyuttu beni.

Ekmeğini, aşını paylaştı,

Belki yemedi fark ettirmeden, yedirdi.

Sıcak tarlalarda suyunu paylaştı,

Çalıştı güneşte, çatladı dudakları,

Hemen içmedi, önce bana içirdi.

Uzun yolları paylaştı benimle,

Aldı sırtına yürütmedi,

Yürüdü kendi.

Acılarımı paylaştı,

Teselli etti, güldürdü beni,

Ama kendi,

Ağladı belki.', 'Kolay şeylerin paylaşması da kolaydır, Önemli olan zoru paylaşmak. O, uykusunu paylaştı benimle, Uyumadı, uyuttu beni. Ekmeğini, aşını payla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anneme-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-ahmet-ormanci-5a2v2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hâlâ unutamadığım iki şeyin var,

Titrek çocuksu sesin ve masum bakışların.

Artık onları da unutmak istiyorum,

Zaten unutmasan ne yazar ki.

Belki de bir başkasına ait şimdi,

Bir başkası seviyor belki onları

Ama belki de değiştin,

O sesin ve o bakışların kayboldu belki.

Baksana, o kısacık zamanda

Ben bile değiştim sensiz.

Görsen belki de tanıyamazsın beni,

Önleri açılmış saçlarıma

Tek tek kar taneleri düştü.

Hayattan bezmiş bir simam var şimdi.', 'Hâlâ unutamadığım iki şeyin var, Titrek çocuksu sesin ve masum bakışların. Artık onları da unutmak istiyorum, Zaten unutmasan ne yazar ki. B...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/belki-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla', 'asla-ahmet-ormanci-tftzk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Simanı bile unuttuğun

Sana yazıyorum bütün bunları.

Sensizliğe alıştım artık,

Ama mısralarım alışamadı.

Hâlâ sitem ediyorlar sana,

Hâlâ seni istermiş gibi diziliyorlar.

Ama ben asla.', 'Simanı bile unuttuğun Sana yazıyorum bütün bunları. Sensizliğe alıştım artık, Ama mısralarım alışamadı. Hâlâ sitem ediyorlar sana, Hâlâ seni...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/asla-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaller – Gerçekler', 'hayaller-gercekler-ahmet-ormanci-snn4t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evim dediğim, o küçük odamdayım.

Öğrencilerim de gitti artık, yalnızım.

Dışarısı buz kesiyor,

Ben teneke sobamın karşısında oturuyorum,

Elimde sigaram dumanlar dağıtıyor.

Dumanlardan,

Senin resmini çizmesini bekliyorum.

Biliyorum, mümkün olmayacak bir şey bu

Tıpkı, senin burada olmanı istemek gibi.

Seni ancak hayalimde canlandırıyorum,

Seninle konuşuyor,

Hatta şakalaşıyorum.

Sonra yine yalnız olduğumu anlıyorum,

İçimi bir burukluk sarıyor,

Boğazımda bir şeyler düğümleniyor,

Yutkunamıyorum.

Sigaram yavaş yavaş bitiyor,

Seni hayal etmekten

Korkunç gerçeklere dönmek gibi.

Biraz sonra akşamın hüznü de çöküyor,

Ben yine seni arıyorum

Karanlık boşluklarda.

Yine seni bekliyorum,

Yatağımda uykulu.

Seni düşünüyorum

Gecenin ortasına kadar.

Ama yine anlıyorum

Hayaller boş,

Hayat ise çok acımasız.

		1991 – Mardin', 'Evim dediğim, o küçük odamdayım. Öğrencilerim de gitti artık, yalnızım. Dışarısı buz kesiyor, Ben teneke sobamın karşısında oturuyorum, Elim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayaller-gercekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tozkoparan İskender Destanı', 'tozkoparan-i-skender-destani-alper-kuruk-p9r0q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman aka aka geldi

Ta on beşinci asra kadar...

Bu asırda, bu yurtta Nevcivanlar içinde

''Tozkoparan İskender'' de yüceldi.

Daha çocuktu yaşı

Ama cesur mu cesur,

O kadar da güzeldi...

Atıcılar dergâhında

Yay kabzası kavradı,

Birgün arslan pençesiyle

Kirişini bağladı.

Ağzından ''Bismillah'' yükselirken

Çekiverdi yayını

Hayrette bıraktı âniden

Kemankeş Alayını.

''Toz''u kopmuştu yayın...

İhtiyar kemankeş ''Yıldırımlı Baba''

Seslendi içinden alayın:

Bu nevcivan kemankeşten

Dâim kuvvet akacak,

Görürsünüz bizi birgün

Gölgesinde bırakacak...

O esnada bütün alay

İskender''i çembere aldı

Bundan böyle lâkabı:

''TOZKOPARAN İSKENDER'' kaldı.

Dillerde bütün hep o,

Kuvvetini kıskandı kemankeşler,

Bu uğurda kazandı nice nice 

Dostlar,düşmanlar,eşler...

Bıyıkları terlemişti henüz

On altı yaşındayken

Bir sefer yeli esti tatlı tatlı

Venedik''e doğru.

Kaptan Paşa ''Küçük Davut''a

Bir muhafız takımı verilirken

Tozkoparan İskender de

Biriydi kırk kemankeşten.

''Burak Reis'' o seferde

Şanlı deniz tarihinin 

Sayfaları arasına 

Şehitlikle gömülürken,

Savaşın geleceği

Bilinemezdi önceden.

Bir Venedik kadırgası

Ustaca bir manevrayla

Rampaladı

Paşa Gemisinin kıç yanına.

Zırhlı bir Venedik''li

Zırhına güvenerek

Sarıldı şimşek gibi

Amiral Sancağına.

Suya düşmüştü Sancak! 

Aman ne felâket? 

Arslan Türk Kaptanları

Görürse şanlı Sancağı

Öyle savaşırdı ancak...

Durur mu hiç İskender gayri

Nişan aldı o an

Venedik''liye karşı.

Ok, göğüs ve arkadan

İki defa zırhı deldi...

Sıra Sancağa geldi.

Yıldırımcasına birden

Atladı denize yalın pala

Kara sulara gömülürken

Sancağı aldı

Ve kâfirin boynuna 

Bir de palasını çaldı.

Sancağı tutmuştu bir elle

Bir elinde de kesik kelle

Tırmandı Paşa Gemisine.

Başı sapladı önce 

Sancağın alemine

Sonra dikti Sancağı yerine.

Bu baş döndüren sahne

Sürmemişti bir dakikacık bile.

Kaptanlar Sancağı görünce

Sevinçten deliye döndü

Binlerce top düşmanı dövdü...

Tozkoparan İskender Pehlivan...

Bu nevcivan,bu yiğit

Helâl süt emmiş anadan,

Yücelik dilerken Tanrı''dan

Nihayet düştü şehit...

İstanbul''da Ok Meydanı

Şan,şeref veriyordu bir zamanlar.

Pazusuna güvenen pehlivanlar

Sıra sıra merasimle ok atar

Dikilirdi ''Nişan Taşları''...

On beşinde taşını 

Dikerken Tozkoparan

Fethetti cesaretle,imânla

Şehitlik kalesini,

Dikti kalplere oradan

Unutulmaz bir ikincisini...', 'Zaman aka aka geldi Ta on beşinci asra kadar... Bu asırda, bu yurtta Nevcivanlar içinde ''Tozkoparan İskender'' de yüceldi. Daha çocuktu yaşı ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":96,"source_url":"https://www.antoloji.com/tozkoparan-iskender-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz', 'olmaz-ahmet-ormanci-s87fk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakamam.

Masumiyetinin altındaki,

Sinsi kalleş bakışlarına.

Dayanamam artık dayanamam

Sahtelikle süslenmiş

O nazlı tavırlarına.

Koyulamam yine ardından

Geriye zor döndüğüm

Fırtınalı yollarına.

Yetmez artık gücüm, inan yetmez,

Seni tekrar arayıp bulmaya.', 'Bakamam. Masumiyetinin altındaki, Sinsi kalleş bakışlarına. Dayanamam artık dayanamam Sahtelikle süslenmiş O nazlı tavırlarına. Koyulamam yi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olmaz-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Meleğe', 'beyaz-melege-ahmet-ormanci-a3ac2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevsimin ilk kar’ı yağıyor

Dışarıda.

Yollar, dağlar, hatta yeşil yapraklar bile

Yavaş yavaş kalıyor,

Beyazlar altında.

Sevindiriyor çocukları.

Beni biraz daha hüzünlendiriyor.

Seni hatırlatıyor bana,

Beyazlar içindeki her şey.

Bir zamanlar “Beyaz Meleğim” dediğim,

Seni.

15.11.1993 Mardin', 'Mevsimin ilk kar’ı yağıyor Dışarıda. Yollar, dağlar, hatta yeşil yapraklar bile Yavaş yavaş kalıyor, Beyazlar altında. Sevindiriyor çocuklar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beyaz-melege-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erken gelirdi gün / g ü n yitmeleri...', 'erken-gelirdi-gun-g-u-n-yitmeleri-zafer-zengin-etnika-0xrag', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.

erken gelirdi gün 

hep erken

tamda biterken

biz sessizken

nasıl soyuldum

nasıl ellerin gibiyse

çıplağım bende

giydirmek zor

ölümü gence

bayramdan bayrama beyaz

ahh yaz 

ahh yaz

unut beni

sonralarıma yaz denizi

yüzümde kalsın izi

tuz

bir garip serseri

hayatın kiri

iç’i hiç etmeli

bilmeli

denizde sevgili

13 07 2005

.', '. erken gelirdi gün  hep erken tamda biterken biz sessizken nasıl soyuldum nasıl ellerin gibiyse çıplağım bende giydirmek zor ölümü gence ba...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/erken-gelirdi-gun-g-u-n-yitmeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çilen dolacak', 'cilen-dolacak-gulcin-aksekili-cf0hf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dostum deme yalan kırk kat ellere

Sen kendine bile dost değilsin

Ben seni bilirim seni tanırım

Merhametin varya en sahte yanın

İçinde insanlığın ilkel kopyası

Kes kalbini al eline bir kör makası

Ne kopar ruhundaki hoyrat resimler

Kötülükler, nankörlükler hepsi seninler

Senin de solacak yüzün zamanla

İçinde yalnızlık cirit atacak

Ruhunu yakacak vicdan azabın

Küllerin bile kömür olacak

Sende bir gün güçsüz olmaya gör

Başında akbabalar cirit atacak

Ahiret dediğin yeri bekleme

Önce bu dünyada çilen dolacak', 'Dostum deme yalan kırk kat ellere Sen kendine bile dost değilsin Ben seni bilirim seni tanırım Merhametin varya en sahte yanın İçinde insanl...', ARRAY['Türk Edebiyatı','Şiir','Gülçin Aksekili']::text[], 8.5, '{"poet":"Gülçin Aksekili","poet_slug":"gulcin-aksekili","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cilen-dolacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürekli', 'yurekli-gulcin-aksekili-dc6ho', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey gönül sabret dedi uğuldayarak

Bir demir kapı kapandı gürültülü

Sonra aralandı sabaha karşı

İçinden koca bir yürek çıktı kanayan

Koca bir yürek geçti bu kapıdan

Can havliyle koştu önce sonra durdu aniden

Bakmak istedi sonra bakmam dedi ardıma

Bakmam o karanlığın o küstahlığın

İnsanlıktan bile bihaber karanlığına

Alıcı kuşlarla dolu açlığına

Kanayan bir yürek geldi sonra geçti bu kapıdan

Bolluk içinde açlık çekti

Gürültüler içinde sağır oldu

Yağmura fırtınaya meydan okudu

Kurtuldu geçmiş olsun bu vebanın kucağından

Aradı yürek adam gibi yürek gibi bir yürek

Hiçbiri onun kadar asil onun kadar sade olamadı

Ve hiçbiri alamadı sevilmek için müsade

Dert doldu önce sonra baktı hayata

Başladı yürek yürekli yaşamaya', 'Ey gönül sabret dedi uğuldayarak Bir demir kapı kapandı gürültülü Sonra aralandı sabaha karşı İçinden koca bir yürek çıktı kanayan Koca bir ...', ARRAY['Türk Edebiyatı','Şiir','Gülçin Aksekili']::text[], 8.5, '{"poet":"Gülçin Aksekili","poet_slug":"gulcin-aksekili","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yurekli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir duzqabı duz', 'bir-duzqabi-duz-ahmet-hani-weeax', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir küze su,

Bir davarçıq çörek,

Bir duzqabı duz,

Bir torba qatıq,

Demir qapıları bağladıq,

Seher vaxtı,

Yola düşdük.

Qara gözlerinden,

Işıq damırdı,

Qara günlerime.

Ellerin elimde,

Çöllerden keçdik,

Dağlardan aşdık.

Çox şükür,

Gery qayıtdıq.

Xoruz banladı,

Palçıq duvarların içinde,

Yaşayış başlandı.

Dağların dalında yaşamaq,

Dağların dalında ölmek,

Güneşin yaşayışıdır.

Demir qapılar size qalsın.', 'Bir küze su, Bir davarçıq çörek, Bir duzqabı duz, Bir torba qatıq, Demir qapıları bağladıq, Seher vaxtı, Yola düşdük. Qara gözlerinden, Işıq...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-duzqabi-duz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-ugur-kilic-ui6c3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gitme,

Gitme iki gözüm

Gitme,

Gitme yeminli sözüm

Gitme,

Gitme gönlümün sahibi

Gitme,

Gitme ruhumun hakimi

Gitme,

Gitme ne olursun

Gitme,

Gitme yok olursun

Gitme,

Gitme unutamam

Gitme,

Gitme sensiz yapamam

Gitme,

Gitme yıkılırım

Gitme,

Gitme hayattan sıkılırım

Gitme,

Gitme mutlu olamam

Gitme,

Gitme sensiz yapamam

Gitme,

Gitme ömrümün baharı

Gitme

Gitme gecelerimin sabahı

Gitme,

Gitme kalbim parçalanır

Gitme,

Gitme anılarım canlanır

Gitme,

Gitme ben kimseye yalvarmadım

Gitme,

Gitme ben hiç ağlamadım

Gitme,

Gitme birtanem,

Gitme gözümden akan bir damla yaş olursun,

Gitme sonum olursun.', 'Gitme, Gitme iki gözüm Gitme, Gitme yeminli sözüm Gitme, Gitme gönlümün sahibi Gitme, Gitme ruhumun hakimi Gitme, Gitme ne olursun Gitme, Gi...', ARRAY['Türk Edebiyatı','Şiir','Uğur Kılıç']::text[], 8.5, '{"poet":"Uğur Kılıç","poet_slug":"ugur-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gitme-134-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutfak', 'mutfak-yusuf-ter-vvwjp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahçeli  şirin bir ev, bahçesinde  birkaç tavuk ve köşede küçük bir  kaplanın  kulübesi. Buraya taşınalı  birkaç ay olmuştu. Çam  ağaçları,  meşe ağaçları ve söğütler karışmıştı.Yüz yılık kavak ağacı vardı. Gövdesi  oldukça geniş ve kabukları  taş gibi sağlam. Bu yüz yılık kavak ağacı çevresinde neler görmüş geçirmişti. Bir çobanın diktiği ağaçtı. Ne kısraklar, ne kuzular,  ne kuşlar... kimisi konmuş kimisi gölgesinden yararlanmıştı. Sonbahar gelmiş yaprakları dalından dökülüyor,  ömründen bir son bahar daha kayboluyordu. Gelip gececeği  mevsimlerden birini daha yaşıyordu. 

        Evin içinde  iki çocuk birde anne  vardı. Ahmet yedi yaşında,  sümüklü gözlerini yıkamaz, ağır grip  içinde ateşli salonda dolanıyor. Lyon on bir yaşında, kendi halinde  çok kıskanç,  eşyalarını kimseyle paylaşmaz.  Annesini kızdırmaz kızmasına ama  mutfaktan hiç çıkmaz. Deniz otuzuna yeni değmiş, güzel bir hanım.  Oldukça duygusal sesiz ve  sakin. Kimse damarına basmadığı sürece sinirlenmez  ve tepki göstermez.  Çocuklarına çok düşkündür. Dünya bir yana,  çocukları bir yana...  Üzerlerine titrer. 

        Gel gelelim, Ahmet''in yüksek ateşine sebep olan,  grip oluşuna.Çaresizdir. Kendi başına ateşini düşürmek için elinden geleni yapar ama  beceremez.  Sirkeli su hazırlar, başına ve ayaklarına koyar.  Terletir yine,  çocuktur ne de olsa yerinde duramıyor.  Mutfaktan başka yere de çıkmıyor.  Bazı zamanlar annesi çocuğun yatağını mutfağa taşır, orada uyutur ve  sonra odasına çıkarır…

        Yine bir gün  böyle günün günden güzel olması için dua ederken,  Lyon’unun çığlığını duyar, Ahmet le kavga etmektedir ki,

Anne: 

        -Yeter artık didişmeyin  akılı oynayınız, onca işin güçün arasında, birde sizinle uğraşmayım. Lyon!  o senin küçüğün  biraz anlayışlı ol! 

Lyon:

        -Anne  veriyorum  oynamıyor, benim elimdekileri alıyor, kendi oyuncağı var onla oynasın. 

Ahmet  sessizce  yerinden doğrulur, elindeki oyuncakla kardeşine vurmaya başlar. Mutfak o kadar çok dağınıktır ki,  anne işe nerden başlayacağını, nerden bittireceğini şaşırır. Umursamaz  kavgalarını ve yarım kalan yemek işine olduğu yerden devam eder.

         Rüzgar dışarıda  esmekte ve uğuldayan sesi kulaklara gelmekte. Sanki, diğer fırtınaların habercisi. Verdiği ses,  çatıların  yerlerinden oynadığını düşündürüyordu. Bu uğultu içinde yemekti ev temizliğiydi...Yalnızlığın verdiği hafif ürperti olmuştu ama aldırış etmeden pencereye yaklaşarak  sesleri dinledi. Yukarıda da çocukların sesi kesilmişti. Düşündü, onların yanına çıkıp bakmalıyım korkmasınlar diyerek,  üzerindeki  önlüğü çıkardı ve kapının arkasına astı. Yavaş yavaş adımlarla yukarı çıkmaya başladı.  Çocuk odasına vardığında durdu. Sanki, arkasından rüzgarda  onunla geliyordu.  Hafifledi ama cesaret edip arkasına bakmadı  kapıdan.  Çocuklar uslanmış. Dışarıdaki  rüzgarın uğultusu,  onların oyuncaklarla oynamasını kesmemişti Ahmet annesini gördü  koşarak boynuna sarıldı.  Ahmet''i kucağına aldı. Ahmet  feryat edercesine çığlık atı. birden,  mosmor olacak şekilde.

Anne şaşkınlık içinde: 

         -Ne oldu ne oldu

diye sormaya başladı. Ahmet’in döşüne,  annesinin  üzerinde taşıdığı çatal inenin ucu açık kalmış ve o batmıştı. Anne bir an  korkmuştu.  Korkulacak bir şey olmadığını anlasa da  Ahmet''in çanı çok yanmıştı. 

Lyon aldırmadan  oynuyordu  ve pencereye koştu: 

         -Anne anne  bakın yapraklar dökülüyor... 

          Kavak ağacından  rüzgar şiddetli esiyordu. Lyon da korkmaya başladı. Rüzgarın bu denli uğultulu sesler çıkararak,  yaprakları, daları  ve hatta ağaçları sallamasına şaşkınlık içinde bakıyordu.Çok rüzgar esintileri  görmüştü ama bu denli şiddetli ve uğultulusunu da görmemişti.

Annesine sordu:

        - Neden  böyle esiyor.

          Gök bulutları aşağıya inercesine siyahlaşmış her yerin üzerini örtüyordu. Sustu, cevap veremedi. 

Gözleriyle bulutlara baktı:

         -Korkmayın bu gelip geçicidir, sakin olun. Ben bir mutfağa gidip geleyim.

          Adımları  adatarak salondan yine, arkasında birinin soluğunu farketti. Hafifledi esene kadar. Sanki derin derin biri soluk alıp veriyordu  boynunu döndermek ten dönderince bir şey görmekten korkarak  mutfağa geldi. Masa üzerindeki içinde  elma, armut, muz, mandalinalar olan meyve tabağını seyretti. Çekmeceyi açtı meyve bıçağı çıkardı,  mayhoş yeşil duran elmayı  aldı. Kabuğunu soyarak yemeye başladı.  Elini meyve tabağına yeniden uzattı  sanki bir insan eli yumuşaklığında bir cismin ona dokunduğunu sandı.  Elindeki bıçakla vurmaya başladı. Meyvelere ne olduğunu anlamadan. Birden kendine geldi, meyveleri  haşat etmişti. 

Bu neydi? Afalladı, olamaz böyle şey!  bir el,  insan eli hissetim, diye düşünmeye başladı. Kendi kendinden  mutfaktaki hayali güçten  korkmaya başlamıştı. Ayak sesleri  ordan oraya koşmalar tıkırtılar duydu. Çocukların yine oynadığını hissetti, garip  olan  bir durum yok. Gök bulutların rüzgarın havanın  etkisi olabilir. Buzdolabını açtı  baktı  içinde fazla bir şey kalmamış. Sabah olsun alışverişe çıkarım,  çocuklarda büyüdüler  kendi başlarına  yalnız kalmayı biliyorlar artık diye düşündü. Özenle yerleri temizledi,  sildi,  bulaşık olan tabakları yıkadı,  kuruladı ve yerlerine yerleştirdi.  Yıkanacak çamaşırları çamaşır makinesine koydu:

        -Bunlar yıkanana kadar bende  bir şeyler yapayım yoksa sabah olmaz dedi.

         Lyon  Ahmet le  oynuyor, ara sıra pencereden dışarı bakıyor.  Gariplikler karşısında şaşkınlığını atamıyor, resmini yapıyor. Rüzgar,  ev, bulut,  kavak ağacı,  kendinin, kardeşinin ve annesinin resmini  çiziyor.  Birde mutfak resmi çiziyor.   Uyku saatinin geldiğini,   kardeşinin de iyice oyundan bitkin düştüğünü ve boynunun bir oyana bir buyana düşerek uykusuz kaldığını görüyor...

Annesine sesleniyor:

       -Anne,anne Ahmet uyuyor.  Benimde uykum geldi.

         Ses gelmiyor  annesinden,  mutfak kapısı kapalı. Basamaklardan koşarak iniyor,  kapıya yöneliyor ve  annesinin gayretle iş yaptığını görüyor 

       -Anne, anne! Ahmet  uyuyor,  benimde uykum geldi. Ahmeti yerine yatır.

Anne:

       -Oldu birazdan geliyorum, sen çık ve yatağına yat. Az işim kaldı  diyerek cevap veriyor. Lyon  boynu bükük bir şekilde yatağına girip uyumak için odasına  gidiyor. Kardeşi  köşede kalmış  çoktan uymuştu bile.  Kaldırmak istedi kaldıramadı.  Annesine kızdı içinden.  Zorla   ayağından asılarak  yatağına kadar götürdü, kardeşini kucaklayarak yatağına yatırdı. Kendi yatağına  yürüdü yatağının üzerine uzandı ve gözlerini kapadı. Annenin işi bitti  yukarıya  çıktı  çocuk odasına,  kapıyı açtı yavaşça  çocuklar yatmış uyumuşlardı bile. Seslenmeden geri yavaşça kapıyı örttü ve  aşağı mutfağa indi.  İçinden, işlerinin bitiğini  tertemiz olduğunu, kendisinde uyuma vaktinin geldiğini söyleyerek yatak odasına  gitti. Saçlarını taradı, kokulu parfümünden sürdü,   geceliğini giydi ve yatağına uzandı. Alış veriş yapacaktı, ''''alacağım şeyleri unutmadan yazmalıyım eksik olanları  sabah unuturum'''' diyerek, eline kağıt kalem aldı ve yazmaya başladı. Olduğu yere sızıverdi, yorganın içine girmeden.

         Uyandı  baktı yatağına ve kendi kendine, ''''olduğum yere sızmışım belim tutulmuş,  bende yorganın içine girmemişim'''' dedi. Kıyafetlerine baktı  dışarı çıkarken,  ''''şunu mu bunu mu giyinsem? '''' dedi

         Lavaboya yürüdü elini yüzünü yıkadı.   Aynaya bakarak:

       -Neydi o akşamki gariplikler dedi

Bir buharın  aynada şekillendiğini gördü:

      _Aman Tanrım! Bu ne? dedi ve çığlık atı.

        Çocuklar uyuyordu,  yutkundu,  gözlerini eleriyle ovaladı ve güzelce yıkadı.  Alış veriş çantasını aldı,  evi   işlek  cadde üzerinde   arabalarının vızır vızır gecdiği bir cadde. Bahçeli de olsa  arabasını yolun kenarına koymak zorundaydı. Arabasına yürüdü  kavak ağacına  baktı, dalında yaprak kalmamıştı. Yüz yılık bir ağaç çırıl çıplak kalmıştı. Uzun uzun baktı ağacı süzdü.

        Arabalar geciyordu. Çocuklar uyanmadan karşıya gecip  arabama  binip  alış verişe gitmeliyim dedi.  Arabasına vardı, kapıyı açtı   koltuğuna oturdu.  Eyvah cüzdanı evde  unutmuşum dedi ve arabadan çıktı.  O anda acı bir firen sesi duyuldu arkasını döndüğünde. Tır’ın üzerine geldiğini gördü? …..

Yusuf Ter 23.10.05

Saat 17:27 İsviçre', 'Bahçeli  şirin bir ev, bahçesinde  birkaç tavuk ve köşede küçük bir  kaplanın  kulübesi. Buraya taşınalı  birkaç ay olmuştu. Çam  ağaçları, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/mutfak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapatıp g ö z lerini / g ö z yanılmaları...', 'kapatip-g-o-z-lerini-g-o-z-yanilmalari-zafer-zengin-etnika-yzg4q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.

olmazı bilir söylemezdim

nasıl dar dünya

gömleğimin yakasına

şimdi silkelesem

saçlarım dökülür

ne yar’a ne yara’ya

dayanmıyor koca sevda

adını sorma

yaşamak hala

ah bir bıraksa

gün katlanırda

gül katlanmaz mı burada

kim çalıyor defterleri

kim sayıyor günleri

kim koyuyor gülleri

günlükler içine

-yirmi dört saati sığdırmak

on satır arasına

kendimiz mi çalıyoruz 

ömrümüzü yoksa

kahrolsun günler

ellerimize dokunmuyorsa-

su vermeyi unuttum

bu yüzden

defter arasında kuruttum

renginin değişmesi huysuzluğum

huyumda kurusun



seni koyuyorum

defterim yok

ellerim işte iki sayfa

kuruma bordo gülüm

ad bulamadım sana

ne olsunlardayım hala

otur yanıma

sen ad koy bana

afacan olsun mesela...



kapatıp gözlerini

hatırlatma yalnızlığı

ne zaman unutsam

sarıyor elimi ayağımı

al git beni

gezdir diyar gurbet

bir hayli zaman

az al

çoktan anlamam

gün azalır elimde

ellerimi yıkamam

bu yüzden

şiirlerin ortasında dağılmam

toparlanıyorum şimdi

kundağımda ben

ağlamadan ölmem

06 07 2005

.', '. olmazı bilir söylemezdim nasıl dar dünya gömleğimin yakasına şimdi silkelesem saçlarım dökülür ne yar’a ne yara’ya dayanmıyor koca sevda a...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/kapatip-g-o-z-lerini-g-o-z-yanilmalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatayım', 'anlatayim-yakup-icik-64lpi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ara ara yazsamda sana can kardeşim

Bir derdimden değil, kırgınlığımdan hiç değil

Adın yazılı kalbimde saraylarında nakış nakış

Evimde, işimde, arabamda, bahçemde

Baktığım her güzelliklerde sen varsın...

Bazen canım sıkılır işten, güçten

Fındık kabugunu bile doldurmaz şeylere

Kalbimin cennet köşesi şatosundan

Hayalini çıkartırım canım gözönüme

Aklıma koyarım adını, anarım rahatlarım.

Bal isterse dilim, şiirlerini okurum tat ala ala.

Dolanır senden keyifler damarlarımda

Duygulanırım duygularından yazılanlarada

Kader bağlarımız sanki bircesine ağlarım

Senin acılarını, sızılarını ta kalbimde hissederim...

İnsanlar insanlıktan anlamıyor senin gibi insanca

Yaradandan kader bağlarımız bir sallanınca

Kalp kalbe karşıdır derler ya hani can dostum

Hislerimle seni yaşıyorum, çabalıyorum duymaya,

İnsan olmaya gayretim, arkası erdemliktir varmaya.', 'Ara ara yazsamda sana can kardeşim Bir derdimden değil, kırgınlığımdan hiç değil Adın yazılı kalbimde saraylarında nakış nakış Evimde, işimd...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlatayim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Elle Tutulmaz', 'ask-elle-tutulmaz-i-srafil-hanci-j0is9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dağlar taşımaz gülüm,

denizler almaz sevdamı benim.

ferman gibi dürsen 

yeryüzünü elinle,

köpürsen 

o mavi, 

o deniz

gözlerinle; 

gözlerin yetmez,

ellerin tutmaz! 

yazılmaz benim sevdam

kağıtlara,

ağıtlara,

yazıtlara

yazılmaz; 

ağaçlara kazılmaz! 

taşınmaz benim sevdam

ölümsüz aşkların

efsane adında! 

kuşların kanadında

taşınmaz! 

benim sevdam, 

bir yıldızın

parlak ve berrak

sıcaklığında...

benim sevdam, 

ansızın,

günahsızın,

bir kızın 

yüreğinde

yüreğidir yıldızın.

benim sevdam ezelden gelir,

güzelden gelir; 

güzelliği bitmeyen,

hep çağıran,

itmeyen; 

elleri ellerimizde,

tutamadığımız,

unutamadığımız

O elden gelir! 

benim sevdam ummandır

yüreğinde senin:

dalga dalga 

aşkınlaşırda

taşar, taşar,

aşar seni, 

sonra aşk olur, 

sıcak olur 

ve kaybolur sende,

senden ötedir artık; 

benim desen de

tutamazsın,

unutamazsın,

unutulmaz! 

aşk elle tutulmaz!', 'dağlar taşımaz gülüm, denizler almaz sevdamı benim. ferman gibi dürsen  yeryüzünü elinle, köpürsen  o mavi,  o deniz gözlerinle;  gözlerin y...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Hancı']::text[], 8.5, '{"poet":"İsrafil Hancı","poet_slug":"i-srafil-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/ask-elle-tutulmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isırmam lazımdı s a d e ce/ s a d e kırılmalar...', 'isirmam-lazimdi-s-a-d-e-ce-s-a-d-e-kirilmalar-zafer-zengin-etnika-ecriq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.

ısırmam lazımdı sadece

sadece öpmek belki

............... 

ya da susmak

koklamak sadece

sarılmak

varolmayı

anı düşünmek

ya da düşünmeden ne varsa elde

onu hissetmek

tohum bırakmak rahmine

bir şey söyle

böyle ölemiyorum

- nasıl öleceksin

bilsem istediğini söylerim -

hep o zaman ölüyorum

bana dair ne varsa

ve dünyaya dair

unutuyorum

kimse bağışlamıyor

bir saat gölgesinde durmamı

şimdi ne desem boş

vazgeçiyorum ağır ağır

ya alışırsam ölmeye

ya gidersem

dönmezsem geriye

bana bir şey söyle

böyle gülemiyorum

- şiir doldurmuş içini - 

şiir değil

ben doluyum

ağzı bozuk küfürler etmeliyim

dile gelmeyen

ışığın girmediği yerde

sigara içmeliyim

ve kızıl bir dudak öpmeli

uyandırmalı beni

koparmalı

satır aralarım boş kalmalı

bir şeyler söyle bana

böyle göremiyorum

-.............. -

anlatma boşluğu 

biliyorum sancılarını

ne kadar saklasan da

konuyor karşıma

bize ait değil

sabah beri sigara kırıyor

gölgeme bulutlar yapıyorum

üfledikçe başa dönüşler

bir şey söyle bana

böyle sevemiyorum

- yeter, sus -

hep susuyorum

su içmeyi unuttukça

sana harcadığım terler

ellerimde birikirler

dönüyorum

en azgın yanımla

vahşi kölelikler yapıyorum

ne zaman yere düşsem

uykulardan uyanıyor

yarım yamalak kalmalarda

güne fışkıran su oluyorum

bir şey söyle bana

böyle akamıyorum

-sus ne olur –

susuyorum evet

nasıl susarsa çöl

susuyorum

kuruduğuna bakma

gece oldukça

yeninden dirilen

bir ben oluyorum

bana gül

beni sev

bir başıma kaçamıyorum

ne varsa anlat

giz illeti tutmasın yakamı

seni böyle sevmiyorum

bana bir şeyler söyle

teklikten korkuyorum

-ben yokum –

07 07 2005

.', '. ısırmam lazımdı sadece sadece öpmek belki ...............  ya da susmak koklamak sadece sarılmak varolmayı anı düşünmek ya da düşünmeden n...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/isirmam-lazimdi-s-a-d-e-ce-s-a-d-e-kirilmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek Ağacımsın', 'dilek-agacimsin-i-srafil-hanci-33k6v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hayalini sevdim ben senin

içimde dalga dalga

büyüttüğüm

nehirlerden 

okyanuslar kurdum gözlerinde 

hayalin 

hayalim

hayallerimiz

beyazdı

sarı mavi mor

renk renk

mevsimlere denk

bahardı yazdı

fırtınalar boranlar

en acı en tatlı 

ve en mutlu anlar

sen tenha göllerimde

süzülen kuğu

gözlerimdeki buğu

ve ağacın kabuğu gibi

saracaktın beni

koparacaktın

benim olacaktın yani

kalacaktın hep

hep uzakta oldun ama sen

içime doldun yalnızca

yalnız bir ağaç gibi

dal verdin

çiçek açtın 

zirvelerimin 

en ulaşılmaz

en aşılmaz

bir yerinde gizlendin

şimdi sen yalnız 

mağrur tahtında

yalnız göğe bakar dalların

dalların sonsuza akar

giderken bilmiyorsun

ağladım

ıslatıp mendilleri

dallarına bağladım

umut olsun

dilek olsun diye 

uzayan kollarına

rengarenk çaputlardan

gökkuşağı kurdum

ve geçerek altından

senin en yakın 

ve sana en uzak köşende durdum

uzağındayım şimdi 

uzağa yakınım senden

artık duymayacaksın 

nefesimi ensenden

sen bana işaret sen bana yoldun

sen benim kolum kanadım oldun

yürüyorsam şimdi 

yüklerimden arınmış

anladımki aradığım

senin yarınmış

sen benim figanım

pir-i muganımsın

kederimsin acımsın ilacımsın

ey sevgili sen benim

dilek ağacımsın', 'hayalini sevdim ben senin içimde dalga dalga büyüttüğüm nehirlerden  okyanuslar kurdum gözlerinde  hayalin  hayalim hayallerimiz beyazdı sar...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Hancı']::text[], 8.5, '{"poet":"İsrafil Hancı","poet_slug":"i-srafil-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/dilek-agacimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevilene', 'sevilene-i-smet-akin-u27t8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kış demedim

Yaz demedim

Her an seni düşündüm; 

Sana bir türlü gelemedim.

Yanlış anlama

Benim sevdalım; 

Bu yalnız kalbi

Başka birine de veremedim! ..', 'Kış demedim Yaz demedim Her an seni düşündüm;  Sana bir türlü gelemedim. Yanlış anlama Benim sevdalım;  Bu yalnız kalbi Başka birine de vere...', ARRAY['Türk Edebiyatı','Şiir','İsmet Akın']::text[], 8.5, '{"poet":"İsmet Akın","poet_slug":"i-smet-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevilene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Dediysem', 'seviyorum-dediysem-i-srafil-hanci-1e4n8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seviyorum dediysem 

Bil ki 

ben seni

hava gibi 

Su gibi

Toprak gibi 

Üzerine çiğ düşmüş

Yaprak gibi

Değil

delicesine bel bağlanan 

yürekten ağlanan 

aşk gibi

umut gibi

hülyalar

rüyalar 

dualar

ve hasret gibi değil

ne varsa dünyada

yıldızlar gökyüzü

ay ve güneş

bütün alem

ve kainat

bana inat

toplansa da

beni aşamaz 

ve hiçbir şey 

ulaşamaz

bendeki sana

ben seni 

benim sevdiğim gibi seviyorum', 'Seviyorum dediysem  Bil ki  ben seni hava gibi  Su gibi Toprak gibi  Üzerine çiğ düşmüş Yaprak gibi Değil delicesine bel bağlanan  yürekten ...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Hancı']::text[], 8.5, '{"poet":"İsrafil Hancı","poet_slug":"i-srafil-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seviyorum-dediysem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Saatim', 'ben-ve-saatim-i-srafil-hanci-dy0py', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen gidinceye dek

hiç olmamıştı

zamana itaatim

ama şimdi 

elpençe donakaldık

ben ve saatim', 'sen gidinceye dek hiç olmamıştı zamana itaatim ama şimdi  elpençe donakaldık ben ve saatim...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Hancı']::text[], 8.5, '{"poet":"İsrafil Hancı","poet_slug":"i-srafil-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ben-ve-saatim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağırdım Seni', 'cagirdim-seni-i-srafil-hanci-0euis', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni aradığımda 

benim ellerimde 

hazır kelimelerim

yaldızlı cümlelerim yoktu

ben vardım

boğazımda düğümleyip volkanları

bir bahar yağmurunun 

ılık serinliğinde

yıkanmak üzre

bekleyen 

ben

bir de umutlarım

titrek tüylerine rüzgar dokunmuş

dualar okunmuş

umutlarım

umutlarımı ben 

göçmen kuşlarının avucuna

klavye tuşlarının

ucuna değil

yüreğinin burcuna

bağladım

ama sen 

açmadın telefonu

cevap vermedin

umursamadın belkide

duyumsamadın bu yüzden

anlamadın 

anlayamadın

çünkü sen

başka iklimlerin

ot bitmez yamaçlarında

yeşermeye durmuş

bir gül adayıydın

ayıydın

karanlık gecelerin

dolunay olurum diye

bekledin 

bekliyorsun

ısınamadın

kendi sıcaklığında

sınamadın bile

güneş olmayı

sağanak halinde yağacağın

sımsıcak doğacağın

bir yürekte 

bahar olmayı

yar olmayı

halbuki sen

baharsın

harsın

güneşi de yakan

gönlüme akan

aydınlık ufuklarıma

anlam bırakan

şimdi ben senin

uzak diyarlarına

güvercinler uçurdum

beyaz güvercinlerin 

beyaz kanatlarına

beyaz çiçeklerden

saraylar kurdum

gelirsin diye birgün

kıtalar arasından

seni çağırdım

çağırdım seni', 'seni aradığımda  benim ellerimde  hazır kelimelerim yaldızlı cümlelerim yoktu ben vardım boğazımda düğümleyip volkanları bir bahar yağmurunu...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Hancı']::text[], 8.5, '{"poet":"İsrafil Hancı","poet_slug":"i-srafil-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/cagirdim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Ağlamak Yoktu', 'hani-aglamak-yoktu-i-srafil-hanci-0jjxn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni

soğuk ve sisli

sessiz ve bensiz gecelerin

ayazında bıraktığım gün

süzüldün

üzüldün düşmüşçesine yürekten

bir yaprak gibi 

kırılgan nahiv

ve koparılmış gibi dalından

hazan oldun

soldun

saçların boranlarda

şimdi kızıl saçların

isyanını duyuyorum

içindeki açların

biliyorum şimdi senin

nefeslerin daralır

daralırda yanarsın

al olur yanaklarında

gelincik çiçekleri

baharını taşıdığın

o gül yüzünde

aşkımızın gülleri tazelenir

ellerin 

çaresiz ellerin

uzanır da tutamaz ellerimi

yüreğin damla damla

yüreğime akıyor

süt buğusu gözlerinden

hani ağlamak yoktu 

üzülmeyecektin

toroslar göğsümüzden akıp

mavi Akdeniz gibi

dalgalanmayacak mıydı

içimizde 

içimizde büyüttüğümüz 

sevgimiz için

ayrılıklar ümidi

özlemler aşkımızı

yeşertmeyecek miydi

öyleyse neden

yavrusunu sele vermiş

bir ceylan gibi 

titrek sesin

sözlerin ilmek ilmek 

boğazımda düğümlenir

kaderimiz 

uzaklara itilmek

ne acıdır ahh

üzgün olduğunu bilmek

06.10.02', 'seni soğuk ve sisli sessiz ve bensiz gecelerin ayazında bıraktığım gün süzüldün üzüldün düşmüşçesine yürekten bir yaprak gibi  kırılgan nahi...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Hancı']::text[], 8.5, '{"poet":"İsrafil Hancı","poet_slug":"i-srafil-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/hani-aglamak-yoktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözemedim Ben Seni...', 'cozemedim-ben-seni-pinar-koc-8heth', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çözemedim seni,

Ne gerçeklerimde,Ne rüyalarımda

Çözemedim seni,

Ne sevdalarımda,ne yarınlarımda…

Her sorduğumda seni kendime

Kendimle yüzleştim

İçinden çıkamadığım geçmişimle…

Çözemedim seni,

Ne sevdalarımda

Nede yanık yarınlarımda…

Avuçlarımdan akıp giderken zaman,

Yanıkları kaldı ellerimde, içimi acıtan

Kimi zaman masum, kimi zaman şeytan

İçimde beliren duygularımla kafam,

Kimi zaman sakin,kimi zaman duman…

Çözemedim seni,

Çözmedim! ! ! 

Belki de açmak istemedim

İçindeki gizlerini,

Beklide seni bu halinle sevdim.

Ne gerçeklerimde ne rüyalarımda

Çözmedim seni…

Korktum beklide,

Doğrularınla  yüzleşmekten,

Beynime bir çamur gibi sıvanacak olan

Gerçeklerinden korktum…

Korktum beklide

Hayallerinin berisindeki geleceğinden,

Umutlarından,sevdalarından,

Tanımadığım senden korktum…

İçimde alev topu ateşler yanarken,

Seni görmekten korktum,

Gözlerinin derinliklerinde kaybolup,

Kendimi bulamamaktan korktum….

Çözemedim seni 

Zamanlı zamansız çıkışlar yapan,

Arzularımdan korktum.

Çözemedim seni,

Seni çözecek olan kendimden korktum.

Çözmedim seni….                                               29.08.05    01:26', 'Çözemedim seni, Ne gerçeklerimde,Ne rüyalarımda Çözemedim seni, Ne sevdalarımda,ne yarınlarımda… Her sorduğumda seni kendime Kendimle yüzleş...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cozemedim-ben-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmez Oldu Yüreğim', 'gulmez-oldu-yuregim-burhanettin-akdag-xc03u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasret düşeli gönlüme, tutuşmuşum yanarım					

Delisi oldum sevdanın, divaneyim ağlarım					

Aştım dağların ardını, sandım ki ulaşırım					

Bu derdimin dermanı yok, gülmez oldu yüreğim.					

 					

Soluğum yetmedi aşka, onulmaz acılarım					

Gülün dikenine vurgun, gözlerimden akarım					

Bülbülün derdiyle yangın, bedenimi dağlarım					

Bu derdimin dermanı yok, gülmez oldu yüreğim.					

 					

Sensin gönlümün sultanı, aşkının esiriyim					

Dizlerim çözüldü düştüm, hallerimle inlerim				

Yolların ardına sardım, gurbet elde gezerim					

Bu derdimin dermanı yok, gülmez oldu yüreğim.					

 					

Çileli doğmuş garibim, barışamam dargınım					

Kaderim ateşle düşmüş, kederimle şaşkınım					

Alemde yarsız mecnunum, ben Leyla''yı ararım					

Bu derdimin dermanı yok, gülmez oldu yüreğim.					

					

Issız çölde bir mahzunum, ürperir titrer canım					

Sıcak günün gecesinde, ayazından donarım					

Boğulmuşum harmanında, nefessiz darlanırım					

Bu derdimin dermanı yok, gülmez oldu yüreğim.					

 					

Hayatın sırrın beynime, inceden nakşederim					

Bu ayrılık  benden aşmış, avare gezinirim					

Allah''ım gör bu kulunu, sensin benim efendim					

Bu derdimin dermanı yok, gülmez oldu yüreğim.					

 					

(21.09.2005)', 'Hasret düşeli gönlüme, tutuşmuşum yanarım					 Delisi oldum sevdanın, divaneyim ağlarım					 Aştım dağların ardını, sandım ki ulaşırım					 ...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gulmez-oldu-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir misin', 'bilir-misin-i-srafil-hanci-6uoly', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'iyi bilirim ayrılıkları

bana sor

gidenlerin ardından

yalnız ellerim değil

bir sağa bir sola yalpalanan

yüreğimdir

ve hüznü 

ve kederi

ve bir yumruk gibi

düğümlenen buruklukları

bilirim

ama sen bilir misin sevgili

insanı yaşatan

ümididir

bir gün kavuşacak olmanın

24.09.02', 'iyi bilirim ayrılıkları bana sor gidenlerin ardından yalnız ellerim değil bir sağa bir sola yalpalanan yüreğimdir ve hüznü  ve kederi ve bir...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Hancı']::text[], 8.5, '{"poet":"İsrafil Hancı","poet_slug":"i-srafil-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilir-misin-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyumak ya da uyuyamamak', 'uyumak-ya-da-uyuyamamak-hakki-karadeniz-kafhy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaralıydık aslında herbirimiz kendi yatağımızda; uyumaya az kala.

Yaraların kapanması için elbette uyumak gerekliydi.

Ama biz uyuyamadık,hiçbirimiz uyuyamadı belkide', 'Yaralıydık aslında herbirimiz kendi yatağımızda; uyumaya az kala. Yaraların kapanması için elbette uyumak gerekliydi. Ama biz uyuyamadık,hiç...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Karadeniz']::text[], 8.5, '{"poet":"Hakkı Karadeniz","poet_slug":"hakki-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/uyumak-ya-da-uyuyamamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet - 2', 'gurbet-2-elazigli-mustafa-kaya-q61j8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dalından koparılmış

çiçek gibiyim.

gözyaşlarımla ördüm

hayatımı.

çok uzaklarda bir yerdeyim,

düşmekten kurtulan

bir gurbet kuşuyum..

ne geceler yaşadım

sessizliğinde inlediğim.

vatanımdan uzakta

başıma  atıldı,

paslanmış kalplerin toprakları.

bencilliğimi okşadı

yaban eller

en gurbet günlerime 

serpiştirildi  hayaller 

ve dokunsalar

yıldırımlar yağdırır

bulutlarım..

Mustafa kaya

25.10.2005 / İstanbul

www.mustafakaya.net', 'dalından koparılmış çiçek gibiyim. gözyaşlarımla ördüm hayatımı. çok uzaklarda bir yerdeyim, düşmekten kurtulan bir gurbet kuşuyum.. ne gece...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gurbet-2-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Girdap', 'girdap-elazigli-mustafa-kaya-bald8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yağmur damlalarına hasret

bir ırmak gibiyim

düğüm düğüm boğazım 

bir denize kavuşamadım.

gönül aynam,

acı yüzlü deniz.

ve,

yalnızlığımın korkularında

girdaplar yaşarım …

Mustafa kaya

25.10.2005 /  yeşilyurt

www.mustafakaya.net', 'yağmur damlalarına hasret bir ırmak gibiyim düğüm düğüm boğazım  bir denize kavuşamadım. gönül aynam, acı yüzlü deniz. ve, yalnızlığımın kor...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/girdap-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İç Ses', 'i-c-ses-melih-coskun-jpgab', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimsenin duyamadığı sesler duyarım

Dost diyerek uzanan elin 

Kendi içindeki yaptığı pazarlığı 

Konuşulanın 

Her zaman düşünülen olmadığını

Görebilirim 

Sizin sadece baktıklarınızı 

Veya görüp de görmezlikten geldiklerinizi 

Asfaltta kuruyan kan lekesinin kızıllığını,

Üç yaşındaki mezar taşını 

Beni hep ileri sürükleyecek 

Rüzgarları alırım sırtıma 

Sırf bu yüzden

Her rüzgarda yönünü değiştiren akıllılar! 

Deli derler çoğu zaman adıma 

Bilirim kıymetini bardağın su dolu yarısının 

Ama sorgularım aynı zamanda

Neden boş olduğunu geri kalan kısmının 

Çok soru sorarsam eğer 

Çalarlar soru işaretlerimi cümlelerimden. 

Daha da ileri gidersem 

Düşerim mavi boyalı bir binanın dördüncü katından 

Ellerim ve gözlerim bağlı.

Koşarım sonsuzluğun o yemyeşil ormanlarında

Ağaçların rüzgara eşlik ettiği o en güzel şarkıda

Güller biten yaralı ayaklarımla 

Koşarım yaralanmış yarınıma...

2005', 'Kimsenin duyamadığı sesler duyarım Dost diyerek uzanan elin  Kendi içindeki yaptığı pazarlığı  Konuşulanın  Her zaman düşünülen olmadığını G...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ic-ses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuçlarının İçinde', 'avuclarinin-i-cinde-hatice-bediroglu-zmq9t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dalgalar...

Devam ediyor,

Dövmeye sahili,

Kızgın hoyrat.

Denizin mavisi koyu.

Düşersen eğer,

İçinden çıkacak bir girdap,

Yutuverecekmiş gibi,

Korku salıyor içime.

Poyraz...

Kavgaya tutuşuyor,

Kareli masa örtüsüyle.

Gözlerine bakıyorum,

Öyle sıcak ki...

Perde perde yükseliyor,

Gülüşlerin.

Kalp atışların,

Düşüyor yüreğime.

Avuçlarının içinde,

Eriyor ellerim.

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Dalgalar... Devam ediyor, Dövmeye sahili, Kızgın hoyrat. Denizin mavisi koyu. Düşersen eğer, İçinden çıkacak bir girdap, Yutuverecekmiş gibi...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/avuclarinin-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keman Çığlığı', 'keman-cigligi-hulya-simsek-kkltc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En tiz perdeden bir keman çığlığısın

sesini avuçlayıp urgan yaptığım,

gece sehpasının üzerinde

titrek bekleyişlerimin

süsü… 

Ürkmüş ceylan bakışların

Hangi dağın ardında

Hangi aslan ininden

Habersiz

Düşten bir diyarda sekmekte

sesin...

damıtılmış bir ezgi

tane tane

duyduğumda yüzüm içime dökülür

ancak bir şairin 

beyaz koynuna süzülürsen 

hece hece

acının kalemi kırılır

Bakir yalnızlığın

Çıplak gezer aynalarda

Kim bilir

kaç yalnızlık daha

Doğurdun el sürdüğün geceye

elimde bir tuval

resmedeceğim 

siyahını beyazını:

yaprak kımıldamayan ince bir yüz

dudağının kenarında gece damlası 

ve en tiz perdeden bir keman çığlığı…', 'En tiz perdeden bir keman çığlığısın sesini avuçlayıp urgan yaptığım, gece sehpasının üzerinde titrek bekleyişlerimin süsü…  Ürkmüş ceylan b...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/keman-cigligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektuplar-3', 'sevgiliye-mektuplar-3-kemal-tahir-ozcan-54f6f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok özledim seni, ansızın bir gün,

Karşında yüzümü, görebilirsin.

Haykırdım ismini, inanki her gün,

Dağlara taşlara, sorabilirsin.

Kederli yüreğim, vefana muhtaç,

Uykusuz geceler, sevdana muhtaç,

Ruhum ve bedenim, hep sana muhtaç,

Bir sen bana huzur, verebilirsin.

Yaş kırkı devirdi, ölüm son durak,

Günüm hasret dolu, hayatım kurak,

Sen de özlüyorsan, ufuklara bak,

Belki bulutlarda, görebilirsin.', 'Çok özledim seni, ansızın bir gün, Karşında yüzümü, görebilirsin. Haykırdım ismini, inanki her gün, Dağlara taşlara, sorabilirsin. Kederli y...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar-3-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçur Bizi', 'ucur-bizi-rifki-kaymaz-efxwd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözler beyaza hasret

Tertemiz rüyalara

Acı, bize yardım et, 

Götürüp uzaklara...

Uçur bizi beyaz kuş, 

Götürüp uzaklara...

Al bizi buralardan

Uzak diyarlara at! 

Şu derin uykulardan

Uyandır kanat kanat...

Uçur bizi beyaz kuş, 

Uyandır! Kanat kanat...

Sesliyor yücelerden

Bir ses bizi; tık, tık, tık...

Bu karanlık geceden,

Ah! Bunaldık, bunaldık.

Uçur bizi beyaz kuş,

Ah! Bunaldık, bunaldık.', 'Gözler beyaza hasret Tertemiz rüyalara Acı, bize yardım et,  Götürüp uzaklara... Uçur bizi beyaz kuş,  Götürüp uzaklara... Al bizi buralarda...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ucur-bizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-kemal-tahir-ozcan-5k1bv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlamak nafile, sızlanmak boşa,

Çaresi yok inan, bu ayrılığın.

Hiç akla gelmeyen, geliyor başa,

Çaresi yok inan, bu ayrılığın.

Anı kervanına, dalıyor günüm,

Yarınım meçhuldür, kül oldu dünüm,

En az senin kadar, ben de üzgünüm,

Çaresi yok inan, bu ayrılığın.', 'Ağlamak nafile, sızlanmak boşa, Çaresi yok inan, bu ayrılığın. Hiç akla gelmeyen, geliyor başa, Çaresi yok inan, bu ayrılığın. Anı kervanına...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-303-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Biri', 'oylesine-biri-suleyman-davut-kenanli-48jhn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ters dönmüş aynada tersinden biri

