INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim çarpar gözlerim dalar', 'yuregim-carpar-gozlerim-dalar-cevat-ustun-ch4wt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğim çarpar gözlerim dalar

Şu an şimdi burada

Amasya’da mıyım Tokat’ta mı? 

Ankara’nın bir ucundayım.

Sivas’ta 

Banaz’da Yıldız dağında turnalar katarında,

Ateşli dağında.

İzmir’de karşıyaka’da,

Ankara’da tiyatro sahnesinde,

Terlemiş bir gösteri sonrası sevinçlerdeyim.

Gözlerim dalmış ateşli dağında sevdalardayım.

                                                                           Cevat ÜSTÜN', 'Yüreğim çarpar gözlerim dalar Şu an şimdi burada Amasya’da mıyım Tokat’ta mı?  Ankara’nın bir ucundayım. Sivas’ta  Banaz’da Yıldız dağında t...', ARRAY['Türk Edebiyatı','Şiir','Cevat Üstün']::text[], 8.5, '{"poet":"Cevat Üstün","poet_slug":"cevat-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregim-carpar-gozlerim-dalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay Değil', 'kolay-degil-i-brahim-halil-demir-anj96', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kolay değil

Zalimin zulmüne boyun eğmek

Kolay değil

Aşkın deryasında yüzebilmek

Kolay değil

Kangren olmuş bu bedene şifa bulmak

Kolay değil sevdiceğim 

Bu aşk için diyar gurbet gezmek

Kolay değil 

Güller bahçesinde diken dermek

Kolay değil

Uzun ve sıkıntılı gecelerde sessizce ağlamak

Kolay değil

Hep seni sana sormadan yaşamak

Kolay değil sevdiceğim

Yıldızlar altında, ay ışığnda sana türküler yakmak

Kolay değil

Bu sevgiyi bu bedende bu yürekte gizlemek

Kolay değil

Bu aşk için kapı kapı dilenci misali dilenmek

Kolay değil

Yazın temmuzunda zemheriyi yaşamak

Kolay değil sevdiceğim

Sekerat anında seni sayıklamak

Kolay değil

Her hazan mevsiminde seni hatırlamak

Kolay değil

Birlikte arşınladığımız yollara seni sormak

Kolay değil

Her ismin çağrıldığında bir acayip olmak

Kolay değil sevdiceğim

Başkasına gelin giderken ölümü istemek

Kolay değil

Canı gönülden sevdiğine seni seviyorum diyememek

Kolay değil

Ulu dağların doruğundaki karlara ismini yazmak

Kolay değil

El ele tutuşan sevgilileri seyrederken onlara özenmemek

Kolay değil sevdiceğim

Yazdığın mektuplara yürek sıcaklığıyla cevap vermemek

9/01/2005', 'Kolay değil Zalimin zulmüne boyun eğmek Kolay değil Aşkın deryasında yüzebilmek Kolay değil Kangren olmuş bu bedene şifa bulmak Kolay değil ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kolay-degil-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgam hırçın karadeniz sevdam egede balıkçı kız', 'kavgam-hircin-karadeniz-sevdam-egede-balikci-kiz-cevat-ustun-9jp8m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşam çöker yollara vururum kendimi 

Sokaklar uzun

Lambalar aydınlatır ıslak geceyi

Hız alır yüreğim kilometrelere

Yüreğimin götürdüğü yere giderim

Yollar boyu kesik çizgiler

Anılar parça parça

Yıldızlar salınır ayın koynunda

Issız sokağın çöplerini karıştırır bir kedi 

Biraz ileride üç beş sahipsiz köpek bir de ben

Ben otobüste puslu camdan dışarıyı izleyen 

Otobüs yolda dağlar tepeler çaylar köprüler aşılır

Yolculuklar ah şu yolculuklar beni benden alan

Yüreğimin sesine kulak verip kilometreleri tüketen bedenim

Anılara işlenen nice desenli yaşam motifleri

Her bir ilmeğiyle yüreğime işlenen kavgam

Kavgam hırçın Karadeniz

Sevdam Eğede balıkçı kız

                                              Cevat ÜSTÜN', 'Akşam çöker yollara vururum kendimi  Sokaklar uzun Lambalar aydınlatır ıslak geceyi Hız alır yüreğim kilometrelere Yüreğimin götürdüğü yere ...', ARRAY['Türk Edebiyatı','Şiir','Cevat Üstün']::text[], 8.5, '{"poet":"Cevat Üstün","poet_slug":"cevat-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kavgam-hircin-karadeniz-sevdam-egede-balikci-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık', 'isik-mehmet-coban-399p8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Işıktır sanma önemli olan

Kaynağı önemlidir ışığın 

Kimi kaynak ışıktır kendinden 

Kimi alır ışığını başkasından 

Aydınlanmışsan 

Kaynak olmayan ışıktan

Ortalıkta kalırsın

Alamazsa ışığını kaynağından

Akıl ışıktır karanlığa

Alır ışığını tanrıdan

Kalırsan sadece aklın aydınlığına

Kurtulamazsın hiç karanlıktan', 'Işıktır sanma önemli olan Kaynağı önemlidir ışığın  Kimi kaynak ışıktır kendinden  Kimi alır ışığını başkasından  Aydınlanmışsan  Kaynak olm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isik-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daüssıla bandırma', 'daussila-bandirma-asya-gulgun-ozkan-n3wle', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daüssılabandırma 



Köşe başında güne inat direnen, taş fırın 

yıllara dayatan birkaç apartman 

birinin penceresinde gelmiş geçmiş en güzel kadın 

tığında dantel, adının zarafetinde hala inciler dizili.. 

gözlerinde sönen, 

yüreğinde alevlenen kördüğüm ilmekler 

saçlarında yıllanan aklar… 

aklımda hala o alımlı tavrı… 

Kırık dökük, eskilerden kalma 

derme çatma, kaşları çatık ama 

sofasında hüzzam makamı yankılanan 

verandasında sardunya kırmızısı gölgeleri ağırlayan ev 

pencere önünde oturan etliye sütlüye karışmayan 

ancak 

rakısına asla buz koydurmayan çingene adam… 

aklımda gözleri dalgın hala… 

ve delikanlılar geçiyordu kapıların önünden... 

uzunundan kısasından 

mavi gözlü, 

yeşil gözlü, 

kahvesinden..güleç 

yüzlerde hüzün göz ardı edilen 

kahkahaların arasına hıçkırıklar saklanan 

bana mısın demeyen tavırlarla 

gün ola ana avrat düz giden.. 

dolgunundan, sıskasından 

kırıtkan adımlı 

fettan göz süzüşlü 

fingirdek gülüşlü 

saçlarında bakir düşlerin 

ellerde ilk heyecanın 

masum öpücüğü 

gönül alıcı, sevda tutuşlu dokunuşlarla 

salın salın salınan edalarıyla 

genç kızlar geçiyordu kapıların önünden… 

Bir başka havası vardı sokağın, 

bir başka tavrı.. 

en babasından, 

en hasından.. 

Ucuz diye alınan 

bir kolu kırık 

başı kel oyuncak bebek 

parmaksız marangoz Mehmet amca 

arabacı Hüseyin’in tekeri 

komşu Mübeccel teyze’nin çoktan yaşlanmış 

aklımı çelen bıçkın, Harun oğlu 

aldırmayın siz bana 

sallayıp kadehi şeytan uçurtmalarına 

suskun, 

kırık bir bakış attım 

sokağımdaki adımlara 

Divane bir evvel 

acısı kıvrak yarın 

son kez tanıklığında bir mavi şehrin 

geçmiş hatıralara uzanarak 

görüntüsü unutulmuş balıksırtı yüze 

hırpalanmış tebessümü takınıp 

uzun zaman sonra gelen 

hatıralar salatasının nostaljisine 

bandırdım, kandırdım gönlümü... 



loda/ geçermiş kapıların önünden…./ bir varmış, bir yokmuş/ varlığa yok, yokluğuyla çokmuş...', 'Daüssılabandırma  Köşe başında güne inat direnen, taş fırın  yıllara dayatan birkaç apartman  birinin penceresinde gelmiş geçmiş en güzel ka...', ARRAY['Türk Edebiyatı','Şiir','Asya Gülgün Özkan']::text[], 8.5, '{"poet":"Asya Gülgün Özkan","poet_slug":"asya-gulgun-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/daussila-bandirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazım ustanın şeker yemeye hasret çocukları', 'nazim-ustanin-seker-yemeye-hasret-cocuklari-cevat-ustun-lysl5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kar yağar ağaçlar bürünür beyaza

Hüzün çöker yüreğime

Çatılara serpilen kar taneleri savrulur esen rüzgarla

Ürperir bedenim kaşkolla sararım yüzümü

Sokaktan geçen çocuklar gelir akılıma 

Kağıt mendil satan

Kızaran burnunu koluyla silen

Yoktur çünkü satın alacak parası kağıt mendil

Üşüyen elini ovuşturan çocuk ısınırken

Sıcacık gevrek simit kokusu savrulur

Gözümün önünden çocuklar geçer

Nazım ustanın şeker yemeye hasret çocukları

Maviliklere uçurtma salacak çocukları 

Kar yağar ağaç dalları üşür kuşlar üşür 

Çocuklar üşür bedenim üşür

Yüreğim sımsıcak

Kucaklarım karlar ülkesinde umutları ve çocukları', 'Kar yağar ağaçlar bürünür beyaza Hüzün çöker yüreğime Çatılara serpilen kar taneleri savrulur esen rüzgarla Ürperir bedenim kaşkolla sararım...', ARRAY['Türk Edebiyatı','Şiir','Cevat Üstün']::text[], 8.5, '{"poet":"Cevat Üstün","poet_slug":"cevat-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nazim-ustanin-seker-yemeye-hasret-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Cumhuriyet ve Mustafa Kemal', 'cumhuriyet-ve-mustafa-kemal-oznur-karayumak-jc82f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'CUMHURİYET VE MUSTAFA KEMAL

1933 29 Ekim’de 

“Türk Milleti! ” diyerek başlamıştı sözüne

“Bu kutlu günümüzde bir ferdiyim milletin 

Ulaştıysak bugüne, milli birlik içinde

Az zamanda, çok büyük işler yaptıysak... 

Kutlu olsun! Hakkındır hakkın ile aldığın

En büyük pay senindir bu büyük idte

Bunun temelinde yatar kahramanlığın 

Bunun temelinde derin kültürün izi 

Ve Cumhuriyetin vardır! ” dedi sevinç içinde 

Çelik bakışlı gözler dikilmiş çok önceden

1923’e ta 1905’lerden

Vatana kast edenin dikilerek önüne

Çıkartıp karanlığı mil çekilmiş gözlerden

Yırtarak mavisini en uzak ufukların

Yıkamış kan gülleri toprağın zerresini

Yazdırmış destanları Çanakkale’den beri

Önünde toz dumanlar, sarsarak tüm dünyayı

Uluslar uyandırıp, esaretler yıkarak

Samsun’da tohum ekip, besleyerek Sivas’ta

Ankara’da derlemiş kızıl gonca gülleri... 

Kılıca kın olarak sarılmış yüreğiyle,

Ruhun gücü üstündür her silahtan savını

İspatlamış dünyaya, Sakarya’dan Afyon’a 

Zafer sümbüllerini derleyerek İzmir’de! 

Yırtarak hüzünleri Ulus’un yüreğinden

İnleyen gönüllere umutları serdiyse

Ve sonunda kavgalar, barışla örtüldüyse... 

Dinle! 

Toplar ve zaferler seslenir bu toprağın bağrından 

Ve selam olsun altında yatan tüm şehitlere! 

Bugün çiçekler açıyorsa bahçemizde

Düşünebiliyorsak özgürlüğü

Sarabiliyorsa yavrularını analar 

Ve ezanlar susmuyorsa camilerinden... 

Yüzyılların cesur yüreği millet ve 

Cumhuriyet gülleri, yurdumda sere serpe! 

Ve sen! 

Ey yıldırımların çocuğu! 

Titre ve uyan! 

Karakterin hürriyet, özgürlüğün, soyundan

Şimdi bu üç beş engel kesecek mi yolunu? 

Seni doğurmuş çağlar en derin bağırından 

Atıl tarihlerine Mustafa Kemal gibi! 

Unutma teslim aldın mirasını Ata’ndan

O’nun emanetidir, Cumhuriyeti koru! 

Yaşat sonsuza değin, aydınlansın bu vatan!

22.Ekim.2005, Öznur KARAYUMAK

"GÜNLERDEN VUSLAT" Şiir kitabı ve sesli Şiir albümünden

29.Ekim.2005 Tarihinde, İstanbul Fatih Belediyesinin Attila İlhanın anısına düzenlemiş olduğu, ''Cumhuriyet'' konulu Şiir yarışmasında 1. lik ödülü almış olan Şiirdir.', 'CUMHURİYET VE MUSTAFA KEMAL 1933 29 Ekim’de  “Türk Milleti! ” diyerek başlamıştı sözüne “Bu kutlu günümüzde bir ferdiyim milletin  Ulaştıysa...', ARRAY['Türk Edebiyatı','Şiir','Öznur Karayumak']::text[], 8.5, '{"poet":"Öznur Karayumak","poet_slug":"oznur-karayumak","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/1-cumhuriyet-ve-mustafa-kemal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılırmak', 'kizilirmak-cevat-ustun-6b1zc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Volkandır yüreğim

Patlar umutlar bir lavdır dökülür vadilerden 

Bir volkandır yüreğim sevgi ırmağına karışır

Kızılırmaktır

Bir şehrin topraklarını sular volkanlar püskürür

Yüreğim atar bir şehrin ötesinden 

Kimi zaman durgun kimi zaman hırçın 

Bir su akar kızıl Kızılırmaktır 

Dize dökülür şiir süzülür

Hasan Hüseyin dilinden 

Sevgi bağı gibi düğümlenir meri kekliği gibi öter

Enver Gökçe dilinden 

O şehrin şafaklarında 

O şehrin şafaklarından kızıl akan kızılırmaktır 

				Cevat ÜSTÜN', 'Volkandır yüreğim Patlar umutlar bir lavdır dökülür vadilerden  Bir volkandır yüreğim sevgi ırmağına karışır Kızılırmaktır Bir şehrin toprak...', ARRAY['Türk Edebiyatı','Şiir','Cevat Üstün']::text[], 8.5, '{"poet":"Cevat Üstün","poet_slug":"cevat-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kizilirmak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yer beni', 'yer-beni-mustafa-yazka-c0vfq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkımı söylemezsem,

İçim içimi yer beni,

Aşkı iletemezsem,

Kabul etmez yer beni,

Sözümde duramazsan,

El içinde yer beni.

Bazı insanı ne etmeli,

Yanan ormana itmeli

Dedi kodu değirmeni

Bu yara yer beni,

İftiracıyı ilmeli,

Yağlı kurşun değmeli,

Cahilliğin bedeli Artık bu yara yer beni.', 'Aşkımı söylemezsem, İçim içimi yer beni, Aşkı iletemezsem, Kabul etmez yer beni, Sözümde duramazsan, El içinde yer beni. Bazı insanı ne etme...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yazka']::text[], 8.5, '{"poet":"Mustafa Yazka","poet_slug":"mustafa-yazka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yer-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay parlar yüreğim deniz', 'ay-parlar-yuregim-deniz-cevat-ustun-jq6m3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıldızımız yine doğdu 

Ay doğdu yüreğim parlar

Ay parlar yüreğim deniz

Saroz körfezinde deniz dalgalı yine

Bir başıma ben sen uzaklarda

Bir adım ötede masmavi deniz

Gece mavisi

Sen uzaklarda olmasan

Ben yakındayım 

Aklım düşünceden sınıfta kaldı

Yazmak istersem eğer duygularımı kağıtlara 

Ne beyaz dosya kağıt ne de kalem

Seni seviyorsam eğer

Bir parça kağıda en saf duygularımla 

Kızıl saçlı turnam derim

Kulağına mırıldanırım

Yıldızımıza bakarak yayla sahilinde

Göz yaşları arasında

				Cevat ÜSTÜN', 'Yıldızımız yine doğdu  Ay doğdu yüreğim parlar Ay parlar yüreğim deniz Saroz körfezinde deniz dalgalı yine Bir başıma ben sen uzaklarda Bir ...', ARRAY['Türk Edebiyatı','Şiir','Cevat Üstün']::text[], 8.5, '{"poet":"Cevat Üstün","poet_slug":"cevat-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ay-parlar-yuregim-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Bıraktın Ki Bende', 'ne-biraktin-ki-bende-i-brahim-halil-demir-jq2ee', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey zalim sevgili

Hafıza mı bıraktın bende

Mazimi hatırlayabileyim

Yaş mı kaldı didelerimde

Öldüğünü duyduğumda ağlayabileyim

Ey zalim sevgili

Takat mi bıraktın dizlerimde

Sana gelebileyim

Fer mi kaldı gözlerimde

Seni görebileyim

Duygu mu bıraktın bende

Duygulanayım

Sevgi mi bıraktın bende

İhtiyacı olanlara sevgi dağıtayım

Düşman gibi arkamdan vurdun sen de

Söylesene sen gibilerini nasıl seveyim

Ey zalim sevgili

Açılmaz oldu güller gül bahçemde

Söylesene nasıl gül gibi olayım gül gibi kokayım

Kan pompalamıyor artık bu yürek

Söylesene seni nasıl hissedebileyim

Çınlamaktan kulaklarımın zarı delindi 

Söylesene seni nasıl duyayım

Bekleye- bekleye,yollarını gözleye-gözleye

Bir hal oldum

Söylesene başka birini nasıl bekleyeyim

Ey zalim sevgili

Yaşanacak ömür mü bıraktın bende

Söylesene nasıl kabuğuma çekilmeyeyim

Basiret mi bıraktın bende 

Yanmakta olan gençliğimi söndüreyim

Söylesene umut mu bıraktın bende

Geleceği olmayan yarınım için umutlanayım

01/11/2004', 'Ey zalim sevgili Hafıza mı bıraktın bende Mazimi hatırlayabileyim Yaş mı kaldı didelerimde Öldüğünü duyduğumda ağlayabileyim Ey zalim sevgil...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ne-biraktin-ki-bende-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay ışığı ve hüzün', 'ay-isigi-ve-huzun-cevat-ustun-946gc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Su akar derinden

Yüreğim iki yakaya bölünür

Bir tarafta ışıklı lambaların altında

Müziğin ezgileri 

Öte yanda alabildiğine yalnızlığım

Ve sen

Ay ışığı ve hüzün 

O hep vardı 

Su akar bilinmez nehir yataklarına 

Sen öte yakada

				Cevat ÜSTÜN', 'Su akar derinden Yüreğim iki yakaya bölünür Bir tarafta ışıklı lambaların altında Müziğin ezgileri  Öte yanda alabildiğine yalnızlığım Ve se...', ARRAY['Türk Edebiyatı','Şiir','Cevat Üstün']::text[], 8.5, '{"poet":"Cevat Üstün","poet_slug":"cevat-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ay-isigi-ve-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum / Yorgun', 'yorgunum-yorgun-kenan-mim-eryigit-2ybhk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '..tek dünyalılar, koymadınız mı sepetinize

benim gibi, ötesi için azık? 

..bir de; sinemde kurşunu sevdamın,

vurgunum, vurgun...

..yaşanmış anların çöplüğünde 

kalmış ahlara-vahlara  yazık! 

..''dağların çekemediği yükü'' çekmekten 

yorgunum, yorgun...', '..tek dünyalılar, koymadınız mı sepetinize benim gibi, ötesi için azık?  ..bir de; sinemde kurşunu sevdamın, vurgunum, vurgun... ..yaşanmış ...', ARRAY['Türk Edebiyatı','Şiir','Kenan Mim Eryiğit']::text[], 8.5, '{"poet":"Kenan Mim Eryiğit","poet_slug":"kenan-mim-eryigit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yorgunum-yorgun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevdam', 'benim-sevdam-i-brahim-halil-demir-88gwn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim sevdam sevdaların son durağı,

Benim sevdam yüreğimin en güzel konağı,

Benim sevdam sevenlerin çıkmaz sokağı,

Ve benim sevdam dağların yanar dağıdır.

Benim sevdam sevdaların en parlağı,

Benim sevdam coşkun akan aşk ırmağı,

Benim sevdam en duygusal aşk barınağı,

Ve benim sevdam tuzakların en kötü tuzağıdır.

Benim sevdam korlaşmış sevdanın aşk otağı,

Benim sevdam konuşamayan aşk papağanı,

Benim sevdam fokur-fokur kaynayan aşk kazanı,

Ve benim sevdam çok nadir yaşanan aşk destanıdır

Benim sevdam nadasa bırakılmış aşkın toprağı,

Benim sevdam henüz doğmuş ayın aydınlığı,

Benim sevdam gecenin zifiri karanlığı,

Ve benim sevdam semayı süsleyen yıldızların uzaklığıdır.

Benim sevdam yüreğimdeki kanın sıcaklığı,

Benim sevdam seni seviyorum diyememenin kabalığı,

Benim sevdam yetim bir çocuğun ezilmişliği,

Ve benim sevdam balta girmemiş ormanlarda yaşanan aşk duygusallığı dır.

Benim sevdam henüz yeni bestelenmiş aşk şarkıları, 

Benim sevdam asırlar önce inşa edilmiş aşk köprüleri,

Benim sevdam kızgın kum çölünde yol gidenin açlığı ve susuzluğu,   

Ve benim sevdam ellerini açmış af bekleyenin umududur.

28/12/2004', 'Benim sevdam sevdaların son durağı, Benim sevdam yüreğimin en güzel konağı, Benim sevdam sevenlerin çıkmaz sokağı, Ve benim sevdam dağların ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/benim-sevdam-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözün Aydın', 'gozun-aydin-i-brahim-halil-demir-208gt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret- hasret dedin

Şimdi hasretindeyim gözün Aydın!

Ağulu hançer ile vurulasın dedin

Şimdi hançerlenen oldum gözün aydın!

Çıkmaz sokaklara yolun düşer dedin,

Şimdi karanlık çıkmazlardayım gözün aydın!

Varlık içinde yoksulluk çekesin dedin!

Şimdi varlık içinde yoksulluk çekenlerdenim gözün aydın!

Tak takabildiğin kadar başına kır çiçeklerini!

Özlemini çektiğin günlerdeyim gözün aydın!

Sür sürebildiğin kadar ellerine kınayı!

En sıkıntılı en ızdıraplı yaşantıdayım  gözün aydın!

Çal en kıvrak çiftetellileri!

Ettiğin bedduaların kabul olduğu anlardayım gözün aydın!

Sevgi atlı sen yaya olasın dedin!

Şimdi çaresiz yaya kalanlardanım gözün aydın!

Temmuz ayında soğuktan tir-tir titreyesin dedin!

Şimdi ısınmayı unutmuş titreyenlerdenim gözün aydın!

Bir yuvan bile olmasın serçelere özenesin dedin!

Şimdi sokaklarda itilip kalkan yuvası olmayanlardanım gözün aydın!

Gülmeye hasret gözlerinden yaş gelemesin dedin!

Şimdi aynen öyle olanlardanım gözün aydın!

29/007/2004', 'Hasret- hasret dedin Şimdi hasretindeyim gözün Aydın! Ağulu hançer ile vurulasın dedin Şimdi hançerlenen oldum gözün aydın! Çıkmaz sokaklara...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozun-aydin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biçare', 'bicare-i-sa-altunbay-cmdov', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk tasına düşünce elden kaşığım

Acından yar yoluna düşmüş aşığım

Yare hasret kalmışım sönmüş ışığım

Nefesimi çöllere savurmuşum ben

Nefesimle çölleri kavurmuşum ben

Ciğerlerde nefesin damarlarda kan

Sevdaya yelken olsam zulme de kalkan

Kanatlanıp uçupta aşka gelirken

Tahammül edememiş yorulmuşum ben

Sevdaya kanat çırpan anka kuşum ben

Bir çiçektim benimde hayalim vardı

Belki kalplerde güneş başka doğardı 

Bir vicdansız geldi de beni kopardı

Her baharda bir aşka dalarmışım ben

Hazan gelip vurdumu solarmışım ben

Hüzünlü bir buluttum ağlardım her an

Gözlerimde yaş vardı kalbimde duman 

Gün gelip bu diyaradan gittiğim zaman 

İçim burkulur başka olurmuşum ben 

Her şeyde bir teselli bulurmuşum ben

Yelkenleri açtımmı tam açarmışım 

Zorda kaldımmı durmaz hep kaçarmışım

Korkup aşk şarabından su içermişim

Aşta kurşun değilde gururmuşum ben 

Attımmı tam ortadan vururmuşum ben', 'Aşk tasına düşünce elden kaşığım Acından yar yoluna düşmüş aşığım Yare hasret kalmışım sönmüş ışığım Nefesimi çöllere savurmuşum ben Nefesim...', ARRAY['Türk Edebiyatı','Şiir','İsa Altunbay']::text[], 8.5, '{"poet":"İsa Altunbay","poet_slug":"i-sa-altunbay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bicare-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör bir kuş gördü ihaneti', 'kor-bir-kus-gordu-ihaneti-selda-arslan-vd46k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ihanet 

kor ateşte yalın ayak yürümektir

sevgisizlik

kar altında buz tutmaktır çıplak bedenin

yalnızlık

koca okyanusda boğulup dibe vurmaktır

kor ateşte yürüdüm yalın ayak

dağlandı ayaklarım

dağlandı yürek

kar altında kaldı çıplak bedenim

buz tutdu açmadı kardelenler

okyanusda boğuldum dibe vurdum

kapandı yosun tutdu kara gözlerim...', 'ihanet  kor ateşte yalın ayak yürümektir sevgisizlik kar altında buz tutmaktır çıplak bedenin yalnızlık koca okyanusda boğulup dibe vurmaktı...', ARRAY['Türk Edebiyatı','Şiir','Selda Arslan']::text[], 8.5, '{"poet":"Selda Arslan","poet_slug":"selda-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kor-bir-kus-gordu-ihaneti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Ki Sen Üzülme', 'yeter-ki-sen-uzulme-i-brahim-halil-demir-gyc9c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeter ki sen üzülme!

Sana başı dumanlı karlı dağlardan, kar getireyim!

Senin için kapı-kapı sevgi merhamet dileneyim!

Aşılmaz dağları aşıp, sana muhabbet tellallığı yapayım!

Yanan bağrına buz, kanayan yarana merhem olayım!

Yeter ki sen üzülme! 

Ben senin emrine amade, aşkına çoban olayım!

Ben gözlerine baktıkça, sevinçten ağlayayım!

Kucağında süt bekleyen, günahsız bir çocuk gibi,

Şefkatinle, sıcaklığınla, sevginle beslenip büyüyeyim!

Yeter ki sen üzülme! 

Ferhat''ın Şirin''ine Kavuşma arzu ve iştiyakı gibi,

Kerem''in Aslı için cayır-cayır yandığı gibi,

Yusuf''un Zuleyha için yıllarca zindanlarda yattığı gibi,

Zuleyha''nın da Yusuf''un güzelliği karşısında, elini kestiği gibi olayım!

Yeter ki sen üzülme!

Sevgi, saygı, aşk bizim düsturumuz olsun!

İlk hedefimiz, ahde vefa ve samimiyet olsun!

Hayatımız, gülüşümüz bizden sonrakilere, örnek olsun!

Yüce yaradan dan da dileğimiz hep bu olsun!

Yeter ki sen üzülme!

Ben sana hayran ben sana müptela!

İçtikçe içiyorum ama yüreğim yanıyor hala!

Sen tacını takmış oturmuşsun sultan tahtına!

Ben ise kalbi düzensiz çarpan bir mazlumum hala!

Yeter ki sen üzülme!

Ben senin için, yağmur, bora, fırtına, kasırga olayım!

Ben senin için, bu yolda ser verip sır vermeyenlerin fikirleriyle dolayım!

Ben yetim, ben öksüz, ben ezilmiş ve ben köle olayım!

Ben sana aşık, ben sana meftun ve ben sana hayran olayım!

Yeter ki sen üzülme!

Ben ayaklarında prangalar,  köle pazarında satılayım!

Ben sevgin için, bacalarda tüten, duman olayım!

Ben aşıklar meclisinde, hep bu aşkı anlatayım!

Ve ben halden anlayanlara, yar ve yaren olayım!

14/10/2003', 'Yeter ki sen üzülme! Sana başı dumanlı karlı dağlardan, kar getireyim! Senin için kapı-kapı sevgi merhamet dileneyim! Aşılmaz dağları aşıp, ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yeter-ki-sen-uzulme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Irmağı', 'sevda-irmagi-i-brahim-halil-demir-iqhm5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sevda ırmağı oldum

Hep seni aktım!

Sen ise güneş oldun,

Hep beni yaktın!

Ben rahmet yağmurları oldum!

Hep susuzluğunu giderdim!

Sen ise çığ tufan bora oldun!

Yaz kış hep yollarımı kapattın!

Ben sevgin uğruna dilenci oldum!

Hep seni kapı-kapı dilendim!

Sen ise acımasız ve gaddar oldun!

Hep sevgini benden esirgedin!

Ben neşteri elinde telaşlı bir doktor,

Sen ise, şifa istemeyen hasta oldun!

Ben yar peşinden koşan yaralı ceylan,

Sen ise, sevgiden anlamayan sevgili oldun!

Ben nadasa bırakılan çorak arazi oldum! 

Sen ise, rengarenk açılan gül bahçesi.

Ben yavrularını emziremeyen anne oldum!

Sen ise, yeni kanatlanmış şatır bir güvercin.

04/05/2004', 'Ben sevda ırmağı oldum Hep seni aktım! Sen ise güneş oldun, Hep beni yaktın! Ben rahmet yağmurları oldum! Hep susuzluğunu giderdim! Sen ise ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevda-irmagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıymetin Yok Artık', 'kiymetin-yok-artik-i-brahim-halil-demir-4w794', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollarımı kapadın düşürdün heyelan!

Dokunma bana bugün başım duman!

Gözlerimden akıyor yaşlar halim yaman!

Farkında olmadan nasıl da geçiyor zaman!

Yüreğimde duruyor halen sakladığım sevdan!

Gözün aydın mübarek olsun sinsi gazan!

Yine mevsimlerden geldi hüzünlendiğim hazan!

Bu kadar mı gaddar ve acımasız olur insan!

Dağlara   düştüm oldum aşkına çoban! 

Gönlümde yanıyor cayır-cayır aşk soban!

Arı oldun ama gönlümde yok ne bal ne de kovan!

Uçarım bir gün elbet matemli olur yuvan!

Hiç kıymetin yok artık oldun gözümde saman!

Oldun varımı yokumu pazarlarda satan!

Hep bir haber bekledim oldum yollarına bakan!

İyileşen yaralarımı sen yine ettin kanayan!

Can evimi unuttum oldum hep seni hatırlayan!

Sen vurdun beni arkamdan ben ise oldum bağışlayan!

Dikenler içinde hep ben oldum gül dağıtan!

Çok zalimsin yar oldun hep derman aratan!

01/04/2004', 'Yollarımı kapadın düşürdün heyelan! Dokunma bana bugün başım duman! Gözlerimden akıyor yaşlar halim yaman! Farkında olmadan nasıl da geçiyor...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kiymetin-yok-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gelirde Bir Gün', 'gun-gelirde-bir-gun-munevver-senol-e4sza', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün gelirde birgün, gözlerimi yumarsam eğer

Arkamdan ağlamak boşuna olur, bunu unutma

Hatırına getir beni gördüğün o ilk günü

Kırmızı paltomu belime uzanan kızıl saçlarımı

Hani hiç olmayan o üç abimi

Nasılda kandırmıştım seni değil mi? 

Onlar aklına gelsinde gül biraz

Salon tutamayıpta, komşunun temelinde yaptığımız düğünü

Hani, kızımızın doğduğu  o ilk günü.

Onun kara gözlerine bakar, nasıl   severdik.

Ardından bir tane,   bir tane daha, tam beş tane.

Tıpkı dama taşı gibi, bir  artı,  bir eksi.

Ama olsun, üçü sağlıklı,  hayatta ya şimdi.

Kızım dünya güzeli, artistim benim,

Murat''ıma da  kıyamam.

Tombili Burağım da,  evimizin direği,

Ne mutlu bize

Kırsaçlı prensim,

Birbirimizi sevdik  ama öldüresiye

Onlar akılna gelsinde, gül biraz 

Evet gül biraz.', 'Gün gelirde birgün, gözlerimi yumarsam eğer Arkamdan ağlamak boşuna olur, bunu unutma Hatırına getir beni gördüğün o ilk günü Kırmızı paltom...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gun-gelirde-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Birisi mi Var?', 'i-cimde-birisi-mi-var-i-sa-altunbay-kac64', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerim kapalıdır açıktır önüm 

Bir kalbe sahibim ki yirmidört dönüm

Ne kadar acımasız geçsede günüm

Gülmemi sağlayacak bir sebep vardır

Yüreğim hızlı çarpar durmaz soluğum

Sevgi akan pınarda paslı oluğum

Üzülmem bu olsa da son yolculuğum

Ardımdan ağlayacak bir habib vardır

İsa diyor ki insan ağlamaz çabuk 

Ağlasa bile sebep hep abuk sabuk

Durmadan kanayıpta tutmasa kabuk 

Yaramı bağlayacak bir tabib vardır', 'Gözlerim kapalıdır açıktır önüm  Bir kalbe sahibim ki yirmidört dönüm Ne kadar acımasız geçsede günüm Gülmemi sağlayacak bir sebep vardır Yü...', ARRAY['Türk Edebiyatı','Şiir','İsa Altunbay']::text[], 8.5, '{"poet":"İsa Altunbay","poet_slug":"i-sa-altunbay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icimde-birisi-mi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değermiydi', 'degermiydi-i-brahim-halil-demir-80ugd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Değer miydi senin için bu kadar üzülmeye

Söylesene hakkım yok muydu benim de gülmeye

Değer miydi senin için bu kadar uykusuz kalmaya

Söylesene hakkım yok muydu benim de mışıl-mışıl uyumaya

Değer miydi senin için avare-avare gezmeye

Söylesene hakkın var mıydı beni yaşarken öldürmeye

Değer miydi senin için soğuk geceler de nara atmaya

Söylesene hakkım yok muydu seninle bir çift söz etmeye

Değer miydi senin için onun bununla yaka paça olmaya

Söylesene hakkın var mıydı beni ona buna kul etmeye

Değer miydi senin için kuşlar misali cıvıl-cıvıl ötmeye

Söylesene hakkım yok muydu gözüme bakarken tebessüm etmeye

Değer miydi senin için bu kötü günlerde yalnız kalmaya

Söylesene hakkın var mıydı beni ona buna mahcup  etmeye

Değer miydi senin için saatlerce duraklarda seni beklemeye

Söylesene hakkın var mıydı gözlerimi yollar da koymaya

Değer miydi senin için dostlarımla kanlı bıçak olmaya

Söylesene hakkın var mıydı sevdiklerimden beni ayırmaya

Değer miydi senin için bu kadar kederli şiirler yazmaya

Söylesene hakkın var mıydı düşüncelerime kilit vurmaya

16/01/2004', 'Değer miydi senin için bu kadar üzülmeye Söylesene hakkım yok muydu benim de gülmeye Değer miydi senin için bu kadar uykusuz kalmaya Söylese...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/degermiydi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Buna Sevmek Diyorsan', 'sen-buna-sevmek-diyorsan-i-brahim-halil-demir-y5c98', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen buna sevmek diyorsan, olmaz olsun bu sevda!

Sen gününü gün ettin beni koydun hep yarı yolda. 

Sen hep rahatlıktasın ama bu zavallı bedenim zorda.

Ben yoruldum. Ben usandım Bu üç günlük dünyada.

Sen buna sevmek diyorsan, ben yokum bu sevgide!

Yürüyorum geride bıraktığın acılarla birlikte.

Yer yok artık bundan böyle bu saf ve temiz yüreğimde,

Bitirdim ben bu aşkı zira güç kalmadı bedenimde.

Sen buna sevmek diyorsan, ben katılmıyorum asla ve asla sana!

Sevmen ne bir umut nede bir heves bırakmadı bana!

Hep avukat oldun ama hiç sahip çıkmadın bu aşk davasına!

Katlanamam artık karşılığı olmayan bu sevdanın sonucuna!

Sen buna sevmek diyorsan, ben bu işi çoktan kaldırdım rafa.

Zira bırakmadın bende ne düşünce ne de aklı selim düşünen kafa.

Ben çile çekerken, sen hep sürdün orada burada sefa

Bitti bu sevda biraz da sen çek bu dünyada cefa!

Sen buna sevmek diyorsan, ben bu sevgiyi anlatmadım hiç kimseye.

Sevmek bence olmalı kızgın güneşte sevdiğine şemsiye!

Hep özendim gıpta ettim bu yoldakilerin hepsine!

Ne güldün ne de güldürdün hep beni attın gerisin geriye!

Sen buna sevmek diyorsan, sevmeyi bilenler güler bize

Ben sana büyük bir çizgi çektim bir daha gelmem size!

Mevsimlerimi döndürdün hep hüzünlendiğim güze!

Hep yaprak döktürdün söyle kim dayanır bu naza!

07/01/2004', 'Sen buna sevmek diyorsan, olmaz olsun bu sevda! Sen gününü gün ettin beni koydun hep yarı yolda.  Sen hep rahatlıktasın ama bu zavallı beden...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-buna-sevmek-diyorsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Bir Türkü Oldun', 'huzunlu-bir-turku-oldun-i-brahim-halil-demir-9clab', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hüzünlü bir türkü oldun düşmedin dilimden

Hayalin hiç ama hiç gitmedi gözlerimin önünden

Meğer seviyormuş bu yufka yürek seni çok ezelden

Sen bana hatırasın uzun ve sıkıntılı gecelerden

Aşık olanlar ile alay ediyordum çok eskiden

Şaşırdım kaldım ne yapacağımı bilemiyorum öfkemden

Bir hırçın ses diyor ki bana yüreğimin derinliğinden

Vazgeç zira sevmemişti seni ve sevmeyecek de canı gönülden

Boynum büküldü gelincik misali ağladım derinden

Yetim ve ezilmiş biriydim sen de vurdun ta can evimden

Mis kokular gelmez oldu artık bahçemdeki güllerden

Uykularım kaçtı korkar oldum meçhul geleceğimden

Sevmek insanı bazen derbeder eder bazen de yaşatırmış yeniden

Ben hiçbir fayda görmedim bu karşılıksız sevgiden

Bazen haşin bir bakış oluyorsun yaralıyorsun beni ciğerimden

Bazen de çekilmez oluyorsun çıkarıp atmak istiyorum düşüncelerimden

Çok narin ve nazenin çiçektin koparmadım dalından

Kıskanıyordum seni aniden esen bahar rüzgarından

Korkuyordum sana nazar değer diye kem gözlerden

Ne kadar da yanılmışım Henüz anladım bana bu yaptıklarından

İhmal etmedim hiçbir zaman seni yaptığım dualardan

Hep seni diledim seher vaktinde yüce Allah tan

Tükendi gözyaşım artık çıldıracağım sana olan aşkımdan 

Senin için kovuldum büyük zatların dergahlarından

22/12/2004', 'Hüzünlü bir türkü oldun düşmedin dilimden Hayalin hiç ama hiç gitmedi gözlerimin önünden Meğer seviyormuş bu yufka yürek seni çok ezelden Se...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/huzunlu-bir-turku-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi bir kefenle bu dünyadan göçtüler', 'hepsi-bir-kefenle-bu-dunyadan-goctuler-halil-colak-tlz7g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimi ağa oldu kimi dünyaya hükümdar

Hepsi sırayla bu dünyadan geçtiler

Kimi sevdalanıp çöllere de düştüler 

Hepsi  bir kefenle bu dünyadan göçtüler

Kimin hamamı vardı kiminin hanı

Servetinin çokluğunun veremezdi hesabı

Yoksullarda çekerdiler her türlüde çileyi

Hepsi  bir kefenle bu dünyadan göçtüler

Kimileri güzeldi Belkıs’ e benzeyen periler gibi

Güzellerin boyları vardı göğe uzanmış selviler gibi 

Gül bahçelerinde süzülüp gezerdi kuğular gibi

Hepsi  bir kefenle bu dünyadan göçtüler

Kimisinin Karun kadar zenginliği var dı

Fakir fukaranın geçimleri de çok zor du

Hayır sever mert insanlarda çok az dı

Hepsi  bir kefenle bu dünyadan göçtüler

Kimisi dertten ağlarken diğeri neşeden güler

Mazlumun bakarak küçümser gülüp de geçer

Hepsi Allah‘in bu dünyada yarattığı bir nefer

 Hepsi  bir kefenle bu dünyadan göçtüler

Halil Çolak 25.10.2005 Ankara', 'Kimi ağa oldu kimi dünyaya hükümdar Hepsi sırayla bu dünyadan geçtiler Kimi sevdalanıp çöllere de düştüler  Hepsi  bir kefenle bu dünyadan g...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hepsi-bir-kefenle-bu-dunyadan-goctuler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-i-sa-altunbay-sn5bj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizi denizler bilir bizi bilir dalgalar 

Bizi yazacak yarın bizi altın sayfalar

Tahta güvertedeki yorgun düşen tayfalar

Günü gelir dirilir canlanır belki birgün

Gönüllerden ve kalpten kalkar bu sinsi sürgün

Gümüşten bir güvercin kondu gönül çatıma 

Yakaladım o kuşu binip de kır atıma

Kuş beyaz kanadını çarparken suratıma 

Doğuşundan o güne özgürlükmüş telaşı

Ben özgürüm der gibi arşı gösterdi başı

Sonsuzluk deryasında yüzemeyenlerdenim 

Sabrım bir hükümdardır padişahtır erdemim

Buğulu pencerelerden bakarken bu gözlerim 

Ye kürküm ye der gibi kürk yalarken kaşığı 

Ben bi çare o kürkü yapanların aşığı

Bilmek vardır ve birde gerçeği görebilmek

Canına zulm etmeden nefsi öldürebilmek

Hayat denilen çile düğüm ki ilmek ilmek

Taşlayıp zindanları esareti öldürdük

Yaşayasın hürriyet ve yaşasın özgürlük', 'Bizi denizler bilir bizi bilir dalgalar  Bizi yazacak yarın bizi altın sayfalar Tahta güvertedeki yorgun düşen tayfalar Günü gelir dirilir c...', ARRAY['Türk Edebiyatı','Şiir','İsa Altunbay']::text[], 8.5, '{"poet":"İsa Altunbay","poet_slug":"i-sa-altunbay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozgurluk-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Boncuğu', 'goz-boncugu-alper-kuruk-7pavz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denize batmış çıkmış elbiseyle

Masmavi olmuş her yeri,

Az da olsa dost olmuş

Mavi renkle gözleri.

Saçları kurumuş ta güneşten

Sararmış deniz suyuyla

Dem vurmuş kestane renginden.

Çocuk değilim ama

Gel benim boncuğum ol

Seni göğsüme takayım,

Gel nazarlık boncuğum

Sevdim renginle seni

Nazardan sakla beni...', 'Denize batmış çıkmış elbiseyle Masmavi olmuş her yeri, Az da olsa dost olmuş Mavi renkle gözleri. Saçları kurumuş ta güneşten Sararmış deniz...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/goz-boncugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sual', 'sual-i-sa-altunbay-pwu6t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her uzvum başka telden çalar benim

Gözlerim hüsran yüklüdür kalbim aheste

Madem kuşlar içindir sonsuz gökyüzü

Peki benim gönül kuşum n''için kafeste...', 'Her uzvum başka telden çalar benim Gözlerim hüsran yüklüdür kalbim aheste Madem kuşlar içindir sonsuz gökyüzü Peki benim gönül kuşum n''için ...', ARRAY['Türk Edebiyatı','Şiir','İsa Altunbay']::text[], 8.5, '{"poet":"İsa Altunbay","poet_slug":"i-sa-altunbay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sual-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit', 'umit-alper-kuruk-cbcjm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül ümitler tarlası

Açar çeşit çeşit

Renk renk ümitlerin

Pembesi,yeşili,karası...

Kimi koca koca ağaç olur

Tatlı tatlı meyva verir,

Kimi donmuş filiz gibi

Hakikatler karşısında

Henüz fışkırmadan erir.

Hepsi solsa da bana yeter

Yeşil,taptaze ümitler...', 'Gönül ümitler tarlası Açar çeşit çeşit Renk renk ümitlerin Pembesi,yeşili,karası... Kimi koca koca ağaç olur Tatlı tatlı meyva verir, Kimi d...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/umit-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-alper-kuruk-duczz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık geceleri sevmezdim küçükken

Yıldızlı geceler dostumdu benim,

Bir şeyler arardım gecelerde ben

Yıldızları teker teker gözlerdim.

Her insanın bir yıldızı varmış

Aradım yıldızımı bulurum ümidiyle,

İnsanlar yıldızlara sıkı sıkı bağlıymış

Bir yıldız aktığında

Bir insan da batarmış...

Bin korku duyardım yıldız aktığı akşam

Ümitsizliğe kapılırdım birden

Karmakarışık olurdu rüyam.

O gün,bu gün hep yıldızımı ararım

Belki de her gün gözlerimin önünde,

Ne çare ki ben görmeden akacak

O akınca vücudum da kalkacak...', 'Karanlık geceleri sevmezdim küçükken Yıldızlı geceler dostumdu benim, Bir şeyler arardım gecelerde ben Yıldızları teker teker gözlerdim. Her...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yildizlar-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Başağı', 'yagmur-basagi-selcuk-kiraz-toy4a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gülüşlerini saklayan martıların

dağlara uzanan kanatlarında 

geldin 

falı bitmiş papatya 

hüznünde tanıdım seni

sesin

postane raflarında

yazıldıkça kumsallara koşan

yaz aşkıydı

her sabah adımların büyürdü

sana uyanan kaldırımlarda

özleminle yeşeren ağaçların

coşkusunda düşerdi gözlerine

buğday başağında gizli

yağmur damlası

pencerende

sağanak yağışlı saçların

yıldızların düşmesini beklerdin	

farklıydın

mercansı düşlere dalardın

boş sıraların en kuytu

karanlığında

çıkış zilini bekliyordun	

bulutların öpmekten

sakındığı bu şehirde

									

yükselirken sessizliği		

yorgun aşkların

bakışlarını kaçırırdın		

soğuk ışıklardan

gittin		

kelimeleri kırılmış

şiir sessizliğinde

ardında meltemleri bırakırken

kumbaramda biriktirdiğim		

bakışların kaldı

		

yalnız kalan yaşam sahnesinde		

kıyısına vuracak liman

bulamadığın zaman

yağmurun bittiği yere gel

balıkçı ağlarına takılan

yakamozlarda bulacaksın		

beni', 'gülüşlerini saklayan martıların dağlara uzanan kanatlarında  geldin  falı bitmiş papatya  hüznünde tanıdım seni sesin postane raflarında yaz...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Kiraz']::text[], 8.5, '{"poet":"Selçuk Kiraz","poet_slug":"selcuk-kiraz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yagmur-basagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım, bi tanem, herşeyim', 'canim-bi-tanem-herseyim-selcuk-kiraz-kq0ga', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'cinayeti gören olmadı

ansızın geldi rüzgar

nabız yok

ışığın geldiği yerde

maviler patlıyor

bir yangın başlıyor

izi nasırlaşmış ayaklarımda

taşlık yollarda

akıntıya kapılma zamanı

ne zaman gelir

ecel duraklarının

menekşe kokulu treni

hesap vakti yaklaştı

en büyük günahım

resimlerinle avunmak

şeytana uydum

ellerim alevleniyor

yatağımda ölmek istiyorum

isli çaydanlığım önümde

masamda bitmeyen sevdam', 'cinayeti gören olmadı ansızın geldi rüzgar nabız yok ışığın geldiği yerde maviler patlıyor bir yangın başlıyor izi nasırlaşmış ayaklarımda t...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Kiraz']::text[], 8.5, '{"poet":"Selçuk Kiraz","poet_slug":"selcuk-kiraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canim-bi-tanem-herseyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıklarda Büyüyoruz', 'ayriliklarda-buyuyoruz-selcuk-kiraz-w77wl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çiseleyerek başladık

yarım kalan sözlerin 

tamamlandığı mevsimde

aşk dantelli caddelerin

serinliğinde geçtik

sesinde uzayan yollardan

umudu sayıklıyorduk

ayaklarımıza kapanan

kaldırım taşlarında

bir şarkı mırıldanıyordun

yıldız olup

kayıyordum gözlerinden

titreyen ellerim değil

düşlerimdi parmak uçlarında

gittiğin yöreden döndüğünde

son satırda olduğumuzu bilmiyorduk

çaresizliğimizi yazmıştık

boş bıraktığımız sorulara

ışığı beklerken 

karanlığımıza yenildik

mayıs geldi

umut düşüyor toprağa

saçların 

ikindi yağmurlarında

güneşi bekliyor

avuçlarımda kardelenler

yürümeyi öğreniyorum

ayrılığın ikliminde

lodosa dokunabildiğim

kadar yanımda olsan da

seni sevmekten

vazgeçemiyorum

ay ışığı dağılıyor pencereme

sessizce üşüyorum

okyanusun en uzak

dalgasında sürüklenen

yalnızlığımda kayboluyorum

içimde bir nehir

taşıyor gözlerimden 

sevda kokan sayfalara

kapatıyorum lâmbayı

gece soluk alıyor

büyüdüğüm aşkın 

ihanetinde', 'çiseleyerek başladık yarım kalan sözlerin  tamamlandığı mevsimde aşk dantelli caddelerin serinliğinde geçtik sesinde uzayan yollardan umudu ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Kiraz']::text[], 8.5, '{"poet":"Selçuk Kiraz","poet_slug":"selcuk-kiraz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ayriliklarda-buyuyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu Geçirirken', 'yolcu-gecirirken-alper-kuruk-ap7kx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasretlik saati yaklaştıkça 

Gözlerde yaş,ruhlarda sükûnet,

Atiden bir şeyler sezerken gönül

Nerdeyse insan getirecek cinnet...

Bir düdük sesi koparır birden

Bağlı gönüllerin son bağını

Ya şimdilik ya da ebediyyen.

Bir acı gülümseme dolaşır

Üzgün,bîçare,solgun yüzlerde,

Tam hareket saati yaklaşır

Yaşlar çözülüverir gözlerde.

Yırtıcı,acı bir düdük sesi,

Ani,zorakî bir gülümseme,

Söner ruhların en son neş''esi

Bir ara insan döner serseme...

Toplanabilen son kuvvet

Sarfedilir mendil sallamak için,

O,uzaklaşıp gittikçe artık

Görünür ön kapısı hasretin...', 'Hasretlik saati yaklaştıkça  Gözlerde yaş,ruhlarda sükûnet, Atiden bir şeyler sezerken gönül Nerdeyse insan getirecek cinnet... Bir düdük se...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yolcu-gecirirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöp Çatan', 'cop-catan-alper-kuruk-xmyg5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ihtiyar bekler heran

Hayat denizinin önünde.

Dallar keser evlilik ağacından

İrili-ufaklı çöpler yapar

Gönlünün dilediği gibi

Birleştirir onları çifter çifter

Sonra önündeki suya atar

Ve burada işi biter...

Sessiz,dalgasız günlerde denizde

Çöplerde bir durgunluk

Bir hayat akışı var.

Ama olmaz ki bu dâima böyle

Güvenilmez denize.

Birgün bir rüzgâr çıkar

İşte bu hengâmeyle

Kimi ayrılır çöplerin,

Kimi didinir,çabalar

Sanki yekvücud olur

Başlar bin minnetle duaya:

''Ey çöp çatan kırılmasın ellerin...''', 'Bir ihtiyar bekler heran Hayat denizinin önünde. Dallar keser evlilik ağacından İrili-ufaklı çöpler yapar Gönlünün dilediği gibi Birleştirir...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cop-catan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyut Geçmişi', 'uyut-gecmisi-figen-aydogmus-agkp8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana gül bahçesinden binlerce gül 

Mutlu kalplerden kahkahalar getirdim

Sevdamı sundum çam altlarında

Geçmişi yok saydım 

Sana tekrar döndüm.

Bırak artık bu hüzünlü bakışları arkana

Unutmak zorda olsa unut

Bir daha yaşanmayacak saltanatlar

Bir daha taklardan geçmeyecek padişah

Bir daha, bir daha olmayacak 

Geçmişi gelecekle uyut

Gidilecek yerin yeni umutları var

Gül kokan dudaklardan alınan buseleri

Şimarık tavırlar altında sallanılacak

Görkemli ağaçları 

Sevda nameleri okuyan neyleri var

Sana susamış bu yürek kanmak istiyor

Ebedi aşkını kan kırmızısı bir şarapla süslüyor

Bırakalım haydi can cana sevdalım

Ömrümüz bak nasıl hızla geçiyor

Ölüm beklenmez beklenmemeli

Varımız hayatımız muhteşem geçmeli

Tadına doyulmaz tatlılardan tatlı

Zevkini ince ince kalbe işlemeli

Geçmişe artık çizgi çekmeli', 'Sana gül bahçesinden binlerce gül  Mutlu kalplerden kahkahalar getirdim Sevdamı sundum çam altlarında Geçmişi yok saydım  Sana tekrar döndüm...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/uyut-gecmisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simitçi Necati', 'simitci-necati-munevver-senol-moom6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Simitçi necati

Kaderle buluşup dertleşelim,diye radevulaştık,ben gittim ama nedense kader gelmedi,gelseydi ona simitçi,necatiyi,soracaktım,izmirde simite gevrek diyorlar,necati henüz ilkokul çağında,sabahın köründe,başında simit dolu tepsisi,düşmüş yollara,üstünde doğru dürüst kıyafetiyok ayağında yıtık kesler,necati o cılız sesiyle,taze gevrekk,diye bağırıyor,onun akranları sıcacık yatağında,uyurken necati,bir lokma ekmek peşinde,ama baktım,birkaç gündür necati görünmüyor ortada,sorduğumda,onon siteye girmesi yasak dediler,merak ettim sebebi ne diye sordum,sıkışmışta,asansöre,çişini yapmış diyorlar,peki,gözüyle gören varmı? diye sorunca,pantolonunun önü ıslakmış ondan dediler,ee be kardeşim,necati sıkışamazmı? altınamı yapsaydı yani? keşke birinizin kapısını çalıpaffedersiniz çok sıkıştım tuvaletinize girebilirmiyim diyebilseydi,ama çekindi,besbelli diyemedi garibim,bak kardeşim biz suçlu arıyacaksak eğer? çöplerini sulu,sulu,servis

dışı asansöre bırakanlardan,leş gibi kokutanlardan,hesap soralım,necati gibi

 garibanlara,iftira atmak kolay,ellerin çocukları,sıcacık yatağında,yatarken kırk çeşit kahvaltıyla büyürken,içimden,gücünüz o garip necatiyemi yetti,diye bağırmak geldi,ne olurdu sizde bir annesiniz,babasınız,anlasaydınızya,necatinin o zor halinden,nasihat etseydiniz,tutsaydınız ya necatinin elinden,şimdi necatiyi kovdunuz,siteden vicdanınız rahatmı? soruyorum size,tabi vicdanınız varsa eğer.', 'Simitçi necati Kaderle buluşup dertleşelim,diye radevulaştık,ben gittim ama nedense kader gelmedi,gelseydi ona simitçi,necatiyi,soracaktım,i...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/simitci-necati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eeey yalnızlık', 'eeey-yalnizlik-erol-haluk-cagdas-rcd4p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eeey yalnızlık, 

Benim sadık dostum, 

             Yalnızlık 

Ne kadarda seni istemesemde, 

Beni yalnız bırakmadın 

be dostum 

yalnızlık 

Ah kalbim

ne işe yararsın? 

Kırılmaktan baska birşey degildir......, 

unutma yalnız

yalnız

Senin sayende bi dostum var 

yalnızlık

yalnız', 'Eeey yalnızlık,  Benim sadık dostum,               Yalnızlık  Ne kadarda seni istemesemde,  Beni yalnız bırakmadın  be dostum  yalnızlık  Ah...', ARRAY['Türk Edebiyatı','Şiir','Erol Haluk Çağdaş']::text[], 8.5, '{"poet":"Erol Haluk Çağdaş","poet_slug":"erol-haluk-cagdas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eeey-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 55', 'resaran-siir-ve-beyitsiler-55-huseyin-avdic-3vca6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kurtuluş Kur''anda

Dinsizlik kurtuluş değil kardeş, arkadaş; kurtulmak gerek ondan.

Bu da, ''doğa üstü gerçek''le olur, yardım almak gerek Kur''andan.

Berlin, Ekim 2005.', 'Kurtuluş Kur''anda Dinsizlik kurtuluş değil kardeş, arkadaş; kurtulmak gerek ondan. Bu da, ''doğa üstü gerçek''le olur, yardım almak gerek Kur''...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/resarani-siir-ve-beyitsiler-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İspirli Müştehak Emmi.', 'i-spirli-mustehak-emmi-veysel-alkan-pcft0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Erzurum''un İspirlisi,

Yaman olur her birisi.

Bizimkisi zır delisi,

İspirli Müştehak Emmi.

Sekiz yıldır tanışırım,

Dertlerini paylaşırım,

Hep onunla uğraşırım,

İspirli Müştehak Emmi.

İstanbul''a göçmüş alık,

İstanbul ki kalabalık.

Şehir deniz o bir balık,

İspirli Müştehak Emmi.

Kafasında telleri az,

Saç yönünden fakir biraz.

Anasından doğmuş maraz,

İspirli Müştehak Emmi.

Dört kızı var pırıl pırıl,

Çalışırlar harıl harıl,

Onda çene zırıl zırıl,

İspirli Müştehak Emmi.

Konuşursa kolay susmaz,

İddiadan geri durmaz,

Sanırsın ki nefes almaz,

İspirli Müştehak Emmi.

Üstü başı kir pasaklı,

Her mevzuya erer aklı,

Herkes haksız o hep haklı,

İspirli Müştehak Emmi.

Din,siyaset,fen ve müzik,

Ayet,yasa,töre,tüzük,

Bilgisi çok sanki sözlük,

İspirli Müştehak Emmi.

Irık biri ama güçlü,

Kahkalı,bol gülüşlü,

Sözcükleri süslü püslü,

İspirli Müştehak Emmi.

Yıkamacı yağlamacı,

Hem sıvacı hem boyacı,

Bazen yolcu bazen hancı,

İspirli Müştehak Emmi.

Cami bilmez,namazı yok,

Dili tutmaz,ayıbı yok,

Dostu yoktur, düşmanı çok,

İspirli Müştehak Emmi.

Sanma sakın aldatamaz,

Aldananlar hiç anlamaz,

Keriz görse dayanamaz,

İspirli Müştehak Emmi.

Açık yeşil yazlık ceket,

Sırtındadır ilelebet,

Ya temizlet ya ütület,

İspirli Müştehak Emmi.', 'Erzurum''un İspirlisi, Yaman olur her birisi. Bizimkisi zır delisi, İspirli Müştehak Emmi. Sekiz yıldır tanışırım, Dertlerini paylaşırım, Hep...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ispirli-mustehak-emmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin', 'neredesin-i-lknur-er-u6bq0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neredesin

Adını anmaktan dudaklarım kurudu

Resmine bakmak dindirmiyor sana olan özlemimi

Rüyalarımdan çık kollarıma gel istiyorum her gece

Sabaha yine kollarım sımsıkı sarılmış uyanıyorum hayalinle

Neredesin

Adına yazdığım kalemimde mürekkep kalmadı

Hiçbir kelime anlatmaz oldu sana olan özlemimi

En büyük hasret şarkıları yalan geldi gönlüme

Kapılarım açık her gece belki yolunu şaşırıpta gelirsin diye

Neredesin

Seni aramaktan güç kalmadı bacaklarımda

Yokluğunda çarpmayı unutan kalbim durmak üzere

Kalp krizleri yalan geldi gönlüme

İnan sonum olacaksın dayanamıyorum hasretine

Nerdesin', 'Neredesin Adını anmaktan dudaklarım kurudu Resmine bakmak dindirmiyor sana olan özlemimi Rüyalarımdan çık kollarıma gel istiyorum her gece S...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neredesin-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ele Veriyor', 'seni-ele-veriyor-okan-nar-944v9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hissedebiliyorum seni ceylan bakışlı..! 

Sende kayıtsız degilsin artık..! 

Gözlerindeki ışıltı ve ara,ara yutkunmaların,

Ele veriyor seni ve yüreğini..! 

Kaçamak dokunuşlarımda ellerine,

Ürperen tenin ele veriyor bedenini..! 

Rol yaparken mimiklerinle..! 

Kuruyan dudakların ele veriyor seni..! 

''''Seni Seviyorum'''' derken sana..! 

Ani ayrılışların ele veriyor seni..!', 'Hissedebiliyorum seni ceylan bakışlı..!  Sende kayıtsız degilsin artık..!  Gözlerindeki ışıltı ve ara,ara yutkunmaların, Ele veriyor seni ve...', ARRAY['Türk Edebiyatı','Şiir','Okan Nar']::text[], 8.5, '{"poet":"Okan Nar","poet_slug":"okan-nar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-ele-veriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Ettim Olmadı', 'umut-ettim-olmadi-selim-bayrak-3anfc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umut ettim olmadı

Yar elinde durmadı

Ben senden haber aldım

Aşk-ı selvim olmalı

Güneşle dans edilmez dedin

Ay ışığı yalnızlık

Sözlerin bulunmaz dedin

Unutuver olanları

Ne de olsa

Hep bir sonra

Sen öncesinde kalınca

Kalınmıyor ki yarında', 'Umut ettim olmadı Yar elinde durmadı Ben senden haber aldım Aşk-ı selvim olmalı Güneşle dans edilmez dedin Ay ışığı yalnızlık Sözlerin bulun...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umut-ettim-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey..!', 'ey-ozkan-karaca-xke0o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey çöl seraplarına kapanmış canım

Ey göz serhatlerine saklanmış sazım

Ey söz şerbetlerine yapışmış sazım

Ey köz kalemlerine yığılmış yangınım

Şiirlerimin destesi seninle okunur

Duygularımın bestesi seninle dokunur', 'Ey çöl seraplarına kapanmış canım Ey göz serhatlerine saklanmış sazım Ey söz şerbetlerine yapışmış sazım Ey köz kalemlerine yığılmış yangını...', ARRAY['Türk Edebiyatı','Şiir','Özkan Karaca']::text[], 8.5, '{"poet":"Özkan Karaca","poet_slug":"ozkan-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ey-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durak''ta...', 'son-durak-ta-ali-orhan-gunaydin-ymokb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat; 

Kimi zaman,bir ipin ucunda,

Kimi zaman,silahın ucundaki kör kurşunda,

Hayat; 

Hayallerin yaşattığı sürece, umut yolculuğunda,

Sensizlik beklentisinin bittiği, Son Durak''ta...', 'Hayat;  Kimi zaman,bir ipin ucunda, Kimi zaman,silahın ucundaki kör kurşunda, Hayat;  Hayallerin yaşattığı sürece, umut yolculuğunda, Sensiz...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/son-durak-ta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(* Razıysan Yanmaya *)', 'raziysan-yanmaya-i-brahim-dikmen-2-so8al', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şafak yelim,yakamoz gözlüm

         Ağlama sakın,utanma kadınlığından

                    Farklı olsa da,seninle dünyalarımız

                             Anlat,anlat bana,aşkını saklama

                                       Kuytularda bırakma, ceylan yüreğini

Eğilme,engellerin dev cüssesinde

         Yüzüne, hüzün yağmurları düşürme sakın

                     İnceden, gece karası,kirpik aralarına

                                 Boncuk boncuk,şebnemler akmasın 

İmgesel boyutta kalmasın,aşk''ı mabet''in

            Lal bakışların,solmasın hüz''nü hazan da

                         İste ki, sevişmekten korkmasın, ürkek tenin

                                      Razıysa yanmaya,kor gibi,bedenimde bedenin

                           

25/10/2005

Aydın''lı_İbrahim Dikmen', 'Şafak yelim,yakamoz gözlüm          Ağlama sakın,utanma kadınlığından                     Farklı olsa da,seninle dünyalarımız               ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/raziysan-yanmaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Bana', 'yeter-bana-hikmet-yaman-3ba8s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaçırıyorsun gözlerini gözlerimden hani doymazdın,

Tutmuyor ellerin ellerimden hani bırakmazdın,

Birgün gelir bıkarsın derdim hani inanmazdın,

Seninle aynı havayı paylaşmakta yeter bana.

Hayır hayır o yaşlar yalan olamazdı,

Yoksa deyyusun birimi girdi kanına,

Bu sevda böyle yarım bırakılmazdı,

Seninle aynı şehri paylaşmakta yeter bana.

Sevdanın tadına varmamış sevda fakiri,

Sakın sevinme seviliyorsun diye,

Benim sevgim sizin felsefenize aykırı,

Seninle aynı Dünyayı paylaşmakta yeter bana.

Artık seni değil sendeki aşkımı seviyorum,

Döneceksin diye hiç ama hiç beklemiyorum,

İnanmasanda mutlu olmanı diliyorum,

Seninle aynı Güneşi paylaşmakta yeter bana.', 'Kaçırıyorsun gözlerini gözlerimden hani doymazdın, Tutmuyor ellerin ellerimden hani bırakmazdın, Birgün gelir bıkarsın derdim hani inanmazdı...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yaman']::text[], 8.5, '{"poet":"Hikmet Yaman","poet_slug":"hikmet-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeter-bana-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Yokluğuna Dokundum / Ellerime Çiy Düştü...', 'yokluguna-dokundum-ellerime-ciy-dustu-i-mdat-ozcan-5r5gz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sana 

bir şiir borcum vardı 

yorgun düşen akşamların gölgesinde 

haykırıştı o vuslat acemiliği 

yarım kalmış bir uykuydu hüzün 

bu deli kentin sabahına inat 

senli geceler kuşandım 

gözlerini dokudum 

kapanmak bilmeyen göz kapaklarıma 

bir şiir borcum kaldı 

yüreğime mıhlı 

gizemli öyküler esrarında 

saman alevi hayata inat 

yangınlar kuşandım aşka dair 

ondandır susuşum 

düşüşüm ondan / gecenin kuytu yanına 

yanlızlığımla 

hani kanar ya gece 

hani yıldız yıldız dökülür ya kelimeler 

öylece uzatıp ellerimi 

yokluğuna dokundum 

yokluğun 

bir suret aynaya her bakışımda 

gözlerimin içinde bir koca dünya 

yokluğun 

çığlıklanmış bir dize 

kalemime bağdaş kurmuş 

yokluğun 

bir zehirli nân 

oyy 

yokluğun isyan 

belki bu son şiiri gençliğimin 

belki yazılacak yeni bir ömrün başlangıcı 

gözleri kısık bir İstanbul yokluğun / karanlık 

zaman erirken sarhoş gülmeler ısrarında 

tenha sokaklarda kırıldı adımlarım 

peşimde iri gölgeler 

bir şiir yazacaktım sana 

ellerime çiy düştü 

alnı ak bir kaç harf kopardım gökyüzünden 

çiy düşen ellerimle 

gecenin en karanlık yanına adını yazdım 

düştüm 

kanadım 

yokluğun 

şiirimi kuşatmış en anlamsız cümle 

yokluğun 

bir apansız kurşun kalbimi dağıtmış 

yokluğun 

zemheride kurulmuş bir dâr 

oyy 

yokluğun intihar... 

16/10/2005 - Kartal', 'sana  bir şiir borcum vardı  yorgun düşen akşamların gölgesinde  haykırıştı o vuslat acemiliği  yarım kalmış bir uykuydu hüzün  bu deli kent...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/yokluguna-dokundum-ellerime-ciy-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Gel', 'gel-ahmet-bektas-t9xeq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gümüş saçlarımı dağıtan 

Serin sonbahar rüzgârlarıyla 

Arınıp yılların hüznünden, 

Bunca acıya kedere inat 

Yüzünde tatlı bir tebessümle gel. 

Dinle yüreğinin sesini… 

Gözlerindeki iki damla yaşı 

Yanağıma silerim. 

Firari kalbimi de al, 

Yüzünde tatlı bir tebessümle gel. 

Hani ertelemiştik ya 

Kavuşmaları... 

Ben çoktan sözümü bozdum. 

Sen de bana uy, 

Yüzünde tatlı bir tebessümle gel. 

Bu can bu bedende durdukça 

Bitmez hasret, dinmez özlem. 

Kırma kolumu kanadımı 

Ani bir karar ver, 

Yüzünde tatlı bir tebessümle gel.', 'Gümüş saçlarımı dağıtan  Serin sonbahar rüzgârlarıyla  Arınıp yılların hüznünden,  Bunca acıya kedere inat  Yüzünde tatlı bir tebessümle gel...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bektaş']::text[], 8.5, '{"poet":"Ahmet Bektaş","poet_slug":"ahmet-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-216-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durağan Ekim Düşleri', 'duragan-ekim-dusleri-ertugrul-sakar-rp8yy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarı eylülün ardından

Göç mevsimi başladı göklere

Bilinmezliğe bir şarkı

Durağan ekim düşleri

Yerde kalmış yapraklar gibi

Topraksı sevinişleri

Ağzımı açmıyorum görüyorsun

Tohumlarca toprağa ekilip

Kayboluyorum karanlıklarında

Kanatları yok düşen silahın

Geceye yapışan gözyaşının

Duruyor hayallerin yanaklarında

Bu ekim bir başka

Atilla İlhan oldu şiir

Toprak doydu aşka

Seni seslemek istemiyorum

Ses yırtıcı bir silah

Acı bir ah

Bu ekim  yandım yıkıldım

Yüreğimi bantladım

Bir arpa boyu adım', 'Sarı eylülün ardından Göç mevsimi başladı göklere Bilinmezliğe bir şarkı Durağan ekim düşleri Yerde kalmış yapraklar gibi Topraksı sevinişle...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/duragan-ekim-dusleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-savas-dincbas-2xwjs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayat zor fakat yaşanılası

sevgiyledir ki katlanılası

sevgi kırılgan

narin ve zarif

sevgi şiir gibi akıcı

su gibi berrak

yaşamsal kaynağı ruhların

en güzel elbise benliğin giydiği

kol düğmeleri ilikli

ama bağrı hep açık...', 'hayat zor fakat yaşanılası sevgiyledir ki katlanılası sevgi kırılgan narin ve zarif sevgi şiir gibi akıcı su gibi berrak yaşamsal kaynağı ru...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgi-214-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlam seni', 'mevlam-seni-osman-taspinar-di5rk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanarım senin aşkınla

Şereflenem ben köşkünle

Gökte uçan her kuş ile 

Çağırayım Mevlam seni

Yunus pişmiş dergahlarda

Beni pişir sahralarda

Kutlu günler sabahlarda

Çağırayım Mevlam seni.

Muhammed''ın aşkı için

Beytullah''a hürmet için

Hak yolunda islam için

Çağırayım Mevlam seni

Sabah, öğle, ikindi''yle

Akşam''yla,yatsısıyla

Namazımın kutsusiyle

Çağırayım Mevlam seni

Hacı Bektaş Veli gibi

Hasbahçe de güller gibi

Coşkun akan seller gibi

Çağırayım Mevlam seni

Yörükoğlum günah dolu

Göster ona doğru yolu

Gözlerim de yaşlar dolu

Çağırayım Mevlam seni.', 'Yanarım senin aşkınla Şereflenem ben köşkünle Gökte uçan her kuş ile  Çağırayım Mevlam seni Yunus pişmiş dergahlarda Beni pişir sahralarda K...', ARRAY['Türk Edebiyatı','Şiir','Osman Taşpınar']::text[], 8.5, '{"poet":"Osman Taşpınar","poet_slug":"osman-taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mevlam-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıklara dair', 'baliklara-dair-h-hikmet-esen-68b6y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşin,

Tutuşan bir çıra aleviyle

Denizde

Van Gogh sarısının

Maviyi, yeşile boyadığı saatlerde

Derinlerde; 

Yosunların salınımına

Eşlik ederken yüzgeçleriyle

Biliyorlar mı acaba balıklar

Sınırlı olduğunu yaşamlarının

Deniz yüzeyine kadar..', 'Güneşin, Tutuşan bir çıra aleviyle Denizde Van Gogh sarısının Maviyi, yeşile boyadığı saatlerde Derinlerde;  Yosunların salınımına Eşlik ede...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/baliklara-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk olsun', 'ask-olsun-osman-taspinar-6lygw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düştük günah girdabına

Çıkarana aşk olsun

Düşürdü şeytan tuzağına

Kurtarana aşk olsun.

Beni benden aldı gitti

Ağlatıp da güldü gitti

Üç kuruşa sattı gitti

Geri alana aşk olsun

Bilmem neyidi suçumuz

Erken ağardı saçımız

Yetmişe geldi yaşımız

Döndürene aşk olsun.

Tüm kötülük sardı beni

Kararttılar beyaz teni

Feleğe olan sitemi

Duyurana aşk olsun.

Döndük doğru yolumuzdan

Şüphe var mı kanımızdan

Ne kaybettik şanımızdan

Bildirene aşk olsun.

Yörüğümün göz yaşını

İçindeki sırdaşını

Hakka olan duasını

Duyurana aşk olsun.', 'Düştük günah girdabına Çıkarana aşk olsun Düşürdü şeytan tuzağına Kurtarana aşk olsun. Beni benden aldı gitti Ağlatıp da güldü gitti Üç kuru...', ARRAY['Türk Edebiyatı','Şiir','Osman Taşpınar']::text[], 8.5, '{"poet":"Osman Taşpınar","poet_slug":"osman-taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-olsun-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibir Heykeli...', 'kibir-heykeli-mehmet-demir-atmali-zl3xf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsana tepeden bakar,

Bilgiçlenir, cahil çıkar.

Devşirme soyuna çeker,

Şu bizim Kibir Heykeli...

Yemiş-içmiş gengiriyor,

Sonra burun kangırıyor,

Ara sıra angırıyor*; 

Şu bizim Kibir Heykeli...

İnkarcıdır, adam olmaz.

Gusül Abdesti''ni bilmez,

Hiç alnı secdeye gelmez; 

Şu bizim Kibir Heykeli...

Tınmaz Hipokrat Andı''nı,

Yıkar da gider bendini,

Ölmez zanneder kendini,

Şu bizim Kibir Heykeli...

Küçük dağları yaratmış(!) ,

Onca hayatı karartmış...

Firavunlar''ı aratmış; 

Şu bizim Kibir Heykeli...

Çalmak için gayret eder,

Kalmak için feryat eder,

Dört kişi omzunda gider; 

Şu bizim Kibir Heykeli...

Mirasçılar kısmet arar,

Münker-Nekir hesap sorar.

Kellesinde topuz kırar; 

Şu bizim Kibir Heykeli...

23.10.2005

*Hovardalık manasına.', 'İnsana tepeden bakar, Bilgiçlenir, cahil çıkar. Devşirme soyuna çeker, Şu bizim Kibir Heykeli... Yemiş-içmiş gengiriyor, Sonra burun kangırı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kibir-heykeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum Arkama Bakmadan', 'gidiyorum-arkama-bakmadan-yusuf-ter-xtevr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I

Yürüyorum sessiz şehrin içinde

Gidiyorum kalabalıktan yırtılan kağıt gibi

Geriye dönüp arkama bakmadan

Senin hatıralarını da yanımda alıp götürüyorum

Kahverengi gözlerin kına renginde saçların

Özleyerek dünya bulutlarla kaplı

Bu akşam sen ve ben uyanık olmalıyız

Ara sokaklar ıssız şehir uğultusuz olmalı

Gözlerim buğulanıyor gecenin zifir karanlığında

Her sokak aralarından sen çıkıp geleceksin

Kına renginde saçların ışıldar ışıklar renginde ay tutar

Kahverengi gözlerin beni tutar

II

Ara sokaklar caddeler kaldırımlar

Yüreğimde bin bir acı ıstıraplar

Gidiyorum arkama bakmadan 

Senin tenin yüreğindi bana can veren

Ahşap evler saraylar köşkler yalıları geride bıraktım

Bu büyük şehrin içinde senle beraber

Ben yolcuyum aşk sevdiğim arkamdan bakar ağlar

Yürüyorum sis duman çökmüş şehrin üstüne

Sisler arasında bir hayal görünüyor

Düşünmeden o hayale yürüyorum sen olmalıydın

Korkularımı akan suya bıraktım alıp götürdü denize

Bu cesaretle dönmek istedim sana sense hayaldın bana

III

Ben yürüyorum yürüdükçe yollar uzuyor

Yollar bitmek bilmiyor şehrin kalabalığında

Denizler kabarıyor gecenin sensiz ay altında

Kaderim alın yazım eskimiş şu şehir gibi

Sisler bulutlar senin gölgeni getirdi

Ben benisem ömrümün ruhunu alıp götürdü

Seni sisler bana seni bir hayal olarak getirdi

Ne bu şehir beni anlaya bildi nede sen

Kaldırımlar gibi yerinden  oynayan

Denizler gibi dalgalanan

Kayıklar gibi sallanan

Kahverenginde gözler kına renginde saçlar

IV

Şehrin başından sonuna kadar aşkımız var

Her sokağın arasında kaldırım taşlarında

Deniz dalgasında ay altında

Bir gün bizim aşkımız da bu şehrin sonunda

Sislerle dumanlarla kavuşacağız

Ruhlarımız cansız duran bedenimizde

Şehri karartacak kadar  büyüyecek

Rüzgarlar ruhumuzu ebedi sonsuz süpürecek

Aşkımız sisler bulutlar içinde can bulacak

Şehir suç işlediği karanlığında kalacak

Gidiyorum dönüp arkama bakmadan

Şehirlerin aşkını şehirlerde bırakıyorum

V

Karanlıklarla geldim göze görünmeden

Sislerle bulutlarla gidiyorum gün doğmadan

Buharlanır şehir denizler kabarmadan

Uzaklaşıyorum senin gözlerinin içinde

Şimşekler yıldırımlar ay derinliğinde

Senden başka kimse olmasın bu şehirde

Kalabalık gördüm bu şehir

Senin hayallerinle doluymuş anladım

Ne sen benden ne de ben senden

Kopabiliyoruz aşkımızı çalabiliyoruz

Deniz üstünde ayağımızı denize batırmadan yürüyoruz

Sislerin bulutların üstünde ikimiz de uyuyoruz

VI

Uyanmadan uyuduğumuz aşkımızı

Şehirler üstünden başka şehre

Sürükleyelim kaldırımlarla ara sokaklarla

Yeni bir şehirde yeni bir aşkın kapısını çalalım

Sen sis ben bulut rüzgar savursun ikimizi

Fırtınalar kopuyor geride bıraktığımız şehir alev içinde

Denizler taşıyor yollar bozuluyor

Gidiyorum dönüp arkama bakmadan aşk

Yusuf”um aşkı şehirlere dağıtım bulana

Benden çıkmış olan kurşunlar savurdum

Her kurşun ucunda aşkı yazdım

Her bir şehri aşklarla büyütüp yücelttim', 'I Yürüyorum sessiz şehrin içinde Gidiyorum kalabalıktan yırtılan kağıt gibi Geriye dönüp arkama bakmadan Senin hatıralarını da yanımda alıp ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/gidiyorum-arkama-bakmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cücenin Aşkı', 'cucenin-aski-mehmet-akif-gulhan-s1ux3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'onu pamuk bulutlar içinde otururken gördüm

otur yanıma sana anlatacaklarım var dedi

kimsin sen, dedim şaşkınlıkla

ben buraya nasıl geldim 

sus sorma dinle, dedi, öykü bu ya

kimsin sen

görüyorsun işte bir cüceyim ben

adın ne 

adım mı, adım

daldı uzaklara adını hatırlamıyordu

bu soruyu soran ikinci kişisin sen dedi

ya başka kim sordu sana adını dedim

aşık olduğum kız dedi

ya aşık mı oldun sen

olamam mı der gibi yüzüme baktı

sonra devam etti 

dinle anlatacağım sana hikaye bu ya

onu ilk kez sahne kenarında beni seyrederken gördüm

o kadar güzeldi ki saçları ve gülen yüzü

aşık oldum

ben sahne de bir devdim o oturduğu yerde bir cüce

hani uzaktan insanlar küçücük gözükürler ya

boyum aklıma bile gelmezdi sahnede

hani o alkışlar ve gülüşler var ya

hani insanın sevgiden yüreği kocaman olur ya

sevdim işte hiç düşünmeden masal bu ya

akşam evime gittim küçücük evime

masası küçük,sandalyeleri küçük

yatağı küçük, işte öyle küçücük dünyama

rüya gördüm o kızı gördüm 

hesapsız,bilinçsiz,sorgusuz

hani sevmiştim ya işte o kızı gördüm

el ele koştuk,sarıldık biri birimize

öptüm onu yanaklarından kocaman

boyum onun boyundaydı 

nasıl oldu bu bilmiyorum rüya bu ya

bir kırmızı gül aldım, yine gelecek diye

geldi,beni seyre daldı el salladı,öpücük gönderdi

bundan cesaret aldım gülü ona yolladım

aldı kokladı,Tanrım sanki beni kokladı

sevgim bin kat arttı arzum yüz bin kat

ben ben onun da beni sevdiğini sandım akıl bu ya

misafirin var dediler merak ettim

koştum bakmaya gittim

o gelmişti, uzaktan bana doğru geliyordu

yürüdükçe o küçük kız bir dev oluyordu

geldi önümde durdu,

bakmak için yüzüne başımı kaldırdım,

başımdaki komik şapka yere düştü

yüzümdeki boyaları silmeye çalıştım

o bana baktı kahkaha ile güldü

benim üç katım uzunluğundaydı

yere çöktü,beni yanağımdan öptü

ne şirin şeysin sen dedi

adın, adın ne senin

banim hiç adım olmamıştı

herkesin cücesiydim ben

cüce,cüce, cüceyim ben dedim

bu sözün bu kadar  ağır olacağını

hiç düşünmemiştim ben

burada mı yaşıyorsun,ben buraya sığamam ki dedi

doğru sığamazdı,yüreğime sığmıştı ama; 

yaşamıma sığamazdı,uyamazdı,olamazdı

başımı okşadı,hoşça kal dedi ve uzaklaştı

o uzaklaştıkça küçüldü,.ben daha küçüldüm

daha küçüldüm daha küçüldüm

yüzümdeki boyaya göz yaşlarım karıştı

yok olmak istedim,hiç yaşamamış olmak

ve bir rüzgar esti küçük bedenimi 

bu bulutun üstüne bıraktı

buraya en yüksek yere,tüm insanları

ve sevdiğim kızı görebileceğim yere

bak ne kadar küçük gözüküyor insanlar

baktım doğru söylüyordu 

ne kadar küçük gözüküyordu insanlar

ama bu doğru değil, bu görüntü gerçek değil dedim

insan her zaman doğruyu görmeli

doğruyu anlamalı

haklısın bende öyle yaptım dedi

doğruyu gördüm,doğruyu anladım

hadi git dedi cücenin hikayesi anlat insanlara

haydi git, doğru ve gerçek bu ya

Mehmet Akif Gülhan  25.10.2005 Saat 17.09', 'onu pamuk bulutlar içinde otururken gördüm otur yanıma sana anlatacaklarım var dedi kimsin sen, dedim şaşkınlıkla ben buraya nasıl geldim  s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/cucenin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döndü Dönmedi', 'dondu-donmedi-abdulvahap-kocaman-ao587', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaylaya gitmişti yayla zamanı, 

Gülizar döndü de Döndü dönmedi. 

Demek ki unutmuş ahti-amanı, 

Yaylacılar geri döndü, dönmedi. 

Ben baktıkça o yılıştı yüz verdi, 

Aşkımıza ümit verdi hız verdi. 

Yemin etti sapasağlam söz verdi, 

Demek ki sözünden döndü dönmedi. 

Aşkıma inansa beni arardı, 

Sevda çeke çeke benzim sarardı. 

Tansiyonum düştü gözüm karardı, 

Sevdasından başım döndü, dönmedi. 

İsmini andıkça ah çekerim ah, 

Sevende mi sevilende mi günah? 

Yepyeni bir ümit başlar her sabah, 

Akşam oldu güneş döndü, dönmedi. 

Bir of çektim dağ sallandı taş düştü,

Ahımdan cihana bir ataş düştü,

Bulutlar ağladı gökten yaş düştü,

Kuru çöller göle döndü, dönmedi.

Ben gönlümü o sunaya bağladım, 

Aşkı ile ciğerimi dağladım. 

Gözlerimden kanlı yaşlar ağladım,

Selinden değirmen döndü, dönmedi. 

Ah çektikçe gözlerimden yaş geldi, 

Ümitlerim dolu gitti boş geldi. 

Yaz da gitti, güz de bitti kış geldi, 

Zaman geçti devir döndü, dönmedi. 

Bu zalim engeller bize nettiler, 

İki aşık arasına gittiler. 

Kaş göz oynattılar fiskos ettiler, 

Arada bir dümen döndü, dönmedi. 

Kokusunu arıyorum yellerde, 

Boynu bükük bekliyorum yollarda. 

Aşkı ile ölüyorum çöllerde, 

Üzerimde kuşlar döndü, dönmedi. 

Şu halime ne söyliyem, ne diyem, 

Bana dönse bir canım var hediyem, 

Ham kelama izin vermez terbiyem, 

Bedduadan dilim döndü, dönmedi. 

Kara sevda çekmek zor gardaşım zor, 

Bana inanmazsan çekenlere sor, 

Benim sonum tımarhane ve doktor, 

KOCAMAN ölümden döndü, dönmedi.', 'Yaylaya gitmişti yayla zamanı,  Gülizar döndü de Döndü dönmedi.  Demek ki unutmuş ahti-amanı,  Yaylacılar geri döndü, dönmedi.  Ben baktıkça...', ARRAY['Türk Edebiyatı','Şiir','Abdülvahap Kocaman']::text[], 8.5, '{"poet":"Abdülvahap Kocaman","poet_slug":"abdulvahap-kocaman","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/dondu-donmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar....', 'aynalar-pinar-koc-y1paj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç mevsim geçti bilmiyorum,

Aynalar mı değişiyor

Yoksa eskiyen benim yüzümü? 

Bu yüzüm bilmiyor sensizliğimi 

Diyemiyorum….

Çünkü geçen yıllar ve değişen yüzüm

Bir sonrakine miras bırakıyor yalnızlığımı…

Unutulmuşluğum besliyor sancılarımı,

Paylaşılmaktan korkan yalnızlığım

Sensizliğe vurulan acı darbeleri

Ve,ve bilinmezlikte savrulan

Gelecek yıllar….

Yalnızsın diyor her doğan gün 

Ve yıldızsız karanlık geceler…

Karlar üzerinde yürürken, 

Ayağımın altında eriyen milyonlarca kar taneleri 

Ağlarken! ! ! ! ! ! 

Ben sadece

Ben sadece düşünüyorum…

Her adımda kaybolan hislerimi

ve her adımda biraz daha yaklaştığım 

sensiz sonumu….

Olmuyor  işte…

Olamıyor ve olamaz diyorum! 

Ama …

Yürek bu dayanmıyor işte,

Dayanmıyor bu lanetli kadere…

Alıp başımı giderim diyorum kimi zaman…

Kimi zaman hayır diyorum.

Kaç mevsim geçti bilmiyorum,

Aynalar mı değişiyor

Yoksa eskiyen benim yüzümü? ? ? ? ? 

                                           

24.03.05	23:47', 'Kaç mevsim geçti bilmiyorum, Aynalar mı değişiyor Yoksa eskiyen benim yüzümü?  Bu yüzüm bilmiyor sensizliğimi  Diyemiyorum…. Çünkü geçen yıl...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aynalar-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Kalpler Emanetçisi', 'kirik-kalpler-emanetcisi-hilal-sakar-yu4hu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üstü örtülü kavuşmalar, 

Ve bir ayrılık karesi akılda kalan. 

Duaların kabulu, 

Sonu gelmez bilmecelere dolan. 

Akıl almaz bir bendeyim, 

Gece gündüz aynı yerdeyim. 

O koridorlar meskenim, 

Sesinin duyulduğu yerdenim. 

Huzurumu sordun uzaklara, 

Orda arama. 

Aynalarda bulacaksın, 

O hisle mana katacaksın. 

Işıldayan güzel iki taş, 

Sevgi ve huzurla yoldaş. 

İçlerindeki coşku, 

Görünenle anlamdaş. 

Kırık kalpler emanetçisi, 

Bulunamayanlar bekçisi. 

Huzur dolu odanın, 

Belki son nöbetçisi. 

Yolcu kıskanç, 

Yol ıssız ve yabancı. 

Huzurun anlattığı, 

Sonsuz ve tacı. 

Bilinen gerçek, 

Işıltı o değil pek. 

Vakit bu vakittir, 

Belki gitmek gerek. 

yağmurmah 2005', 'Üstü örtülü kavuşmalar,  Ve bir ayrılık karesi akılda kalan.  Duaların kabulu,  Sonu gelmez bilmecelere dolan.  Akıl almaz bir bendeyim,  Ge...', ARRAY['Türk Edebiyatı','Şiir','Hilal Şakar']::text[], 8.5, '{"poet":"Hilal Şakar","poet_slug":"hilal-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kirik-kalpler-emanetcisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey vallah dost', 'ey-vallah-dost-mikdat-bal-3ic0o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Volkan gibi ta derinden ses verdin

Ey vallah dost, sağol, var ol, çok yaşa

Dostlar için nice çiçekler derdin

Ey vallah dost, sağol, var ol, çok yaşa

Dost deyince akan dereler durur

Dostluk sevgi, nazdır değildir gurur

Kalpten kalbe yolda, hoş görü yürür

Ey vallah dost, sağol, var ol, çok yaşa

Sevgi yoksa gurbette yok, olamaz! 

Sevmiyenler selam sabah yollamaz

Sevmeyenler, doğru yolu bulamaz

Ey vallah dost, sağol, var ol, çok yaşa

Seven selam sunar, anar ve yanar

Seven her an kendini dostla sanar

Seven dostu ne yerer, ne de kınar

Ey vallah dost, sağol, var ol, çok yaşa

Mikdat’ım ben dostlar için ölürüm

Gerçek dostun ben kurbanı olurum

Böyle bir dost başka nerde bulurum

Ey vallah dost, sağol, var ol, çok yaşa', 'Volkan gibi ta derinden ses verdin Ey vallah dost, sağol, var ol, çok yaşa Dostlar için nice çiçekler derdin Ey vallah dost, sağol, var ol, ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ey-vallah-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge de özgürlük', 'golge-de-ozgurluk-ali-orkac-zm7yh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biri olma ya da birine ait olma eğilimini gösteren özgürlüğün sınırlandırılmış biçimi olarak tanımlanabilen gölgede özgürlük. 

Günümüz hayat koşollarında karşımıza çıkmakta. bu kavram insanımızı edilgen durumua düşürülerek başkasının üzerinde dilediği gibi renk dökme fırsatını doğurur. 

Bu renk dökme kişinin kendi gölgesinde bıraktığı kişiyi ileride her türlü oyunu sergilemeyi kendisine uygun bulur.Gölgede kalan kişi ise kendi olmayı reddedip gölgeye ait olma özgürlüğünü kazanır ve aynı zamanda beşeriyetini gölgesinde kaldığı kişi adına kullanmak zorunda kalır. 

Kişi her türlü eylemi gölge adına yaşar ve ait olduğu grup üyelerini de bu yöne doğru sevk eder. kişi gölgesinin altında yaşadığı insanın,özgürlüğüyle özgürdür. ve özgürlüğünü de onun adına kullanır. peki başkasının gölgesi altında kalan kişinin renk dökme becerisi tecelli bulur mu? ya da bulsa da ne kadar devam eder? 

Bunu sorguladığımızda başkasının gölgesinde özgür olan kişi kısa vadeli çıkar elde etme yolundadır. 

Kısa vadede gölgede kalıp hedefine ulaşma eğilimini gösteren kişi kısa vadede kişiliğine darbe indirir. toplum arasında dürüslüğü'' renk dökme kişilik'' diye bilinip bu tip insana pek itibar edilmez. 

İkinci bir gölgede kalma kişi vardır. o da başkasının gölgesinin altında kalıp yine kısa vadeli bir çıkar eğilimini gösterip ama gölgesinde kaldığı kişinin özgürlüğüyle özgür olmayan ''ben merkezli kişidir'' bu tip insan toplumda ''türlü renk döken kişilik'' diye tanımlanır. bu kişi toplumda güven yaratmayan kişidir. 

Üçüncüsü ve son kişilik ise kendisi olup özgürlüğünü başkasının gölgesi adına kullanmayan ama ondan yararlanan, uzun vadeli çıkarları gözeten kişiliktir. bu tür kişilik toplum arasında ''rengini döken kişi'' diye bilinip ona göre değer biçilen ve ona güven verici telkinlerde bulunulan ve aynı zaman da kısa vadeli çıkarlarından mahrum kalan kişidir. 

Bu üç kişilik,gölgede özgürlük arayanlar olarak tanımlanırken toplumda yer edindikleri konumuda belirlemiş olurlar. Nitekim çağlar boyu süre gelen ve aynı zamanda herkesin az çok yer edindiği gölgede özgürlük gerçeği, günümüzde hala devam etmektedir. 

Fakat bu kavram ne yazık ki çoğu zamanlarda kişiyi buhranlara sürüklediği de oluyor.Diyojen''in '' gölge etme başka ihsan istemez'' söylemi bu bağlamda kişi için gölgede özgürlük olmaz gerçeğini vurgular nitelikte.ve aynı zamanda insan hayatına olan olumsuz etkisini dile getiriyor. 

kişi belli bir çıkar gözetse de asıl hedeflediklerinin gerisinde kalır. çünkü bu tür bir ilişki anlık iletiden başka bir anlam ifade etmez. önemli olan sonucun kişi için nereye varmasıdır. 

lakin kişi gölgedeki özgürlük altında hak arayışından hak arama vasfından hapis olmuştur. O kişinin özgürlüğü gölgesinde yaşadığı insanın buyruklarıyla sınırlandırılmıştır. Dolayısıyla hayat boyu gölgede yaşam olamayacağına göre hayat boyu birilerinin özgürlüğüyle de özgür olunamaz. 

Çünkü gölgede özgür olan kişi gölgesinin altında yaşadığı kişinin özgürlük sopası gibidir. gölge sahibi kişi, istediği zaman özgürlük sopasını başkasını sırtına indirebilir.yalnız sopasını vurduğu kişi incinmez aynı zamanda özgürlük sopası da incitir. 

bu anlamda gölgede özgürlük aramak kişi için: 

özgürlük,zaten kişiliğimin sakat tarafında yer alır'' ifadesini kullanır. dolayısıyla gölgedeki kişi için özgürlük '' özü görmemek ve ama aynı zamanda kendini başkasında görmektir.'' 

07 10 2005 

Ali ork...', 'Biri olma ya da birine ait olma eğilimini gösteren özgürlüğün sınırlandırılmış biçimi olarak tanımlanabilen gölgede özgürlük.  Günümüz hayat...', ARRAY['Türk Edebiyatı','Şiir','Ali Orkaç']::text[], 8.5, '{"poet":"Ali Orkaç","poet_slug":"ali-orkac","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/golge-de-ozgurluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sana İnat Sevdim', 'seni-sana-i-nat-sevdim-deniz-yavuz-zyzeq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzündeki gamzenin 

Tebessüme çalış saatlerinde 

Sevdim ben seni

Göz kenarlarındaki kırışıklığın 

Gülüşlere yenik saatlerinde 

Ayışığının gizlenmiş saç aklarını parlattığı 

Saklılıkta sevdim ben seni

Zamanın kulak duyumlarındaki azalışlarında

Haykırdım yırtılan boğazıma inat 

Ve öyle sevdim çığlık çığlığa

Gözlerin uzakları kesişinde ki kısılmalarında 

Gördüm sevdamın rengini

Ellerinin titreyişlerinin zamanın eşlik edişinde

Güçsüz kalışlarında sevdim ben seni 

Kalp atışlarının ritim bozulmaları ile

Yeniden başlayan göğüs kafesi sancılarında 

Girdim en ücralarına 

Çıkılmaz buhranlarında sevdim 

Yürek verdim 

Ve dedim ya sevdim ben seni 

Seni hayata inat sevdim

Seni herşeye inat sevdim 

Göz göz olmuş yaram derinliklerine inat sevdim

Seni sana inat sevdim...', 'Yüzündeki gamzenin  Tebessüme çalış saatlerinde  Sevdim ben seni Göz kenarlarındaki kırışıklığın  Gülüşlere yenik saatlerinde  Ayışığının gi...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yavuz']::text[], 8.5, '{"poet":"Deniz Yavuz","poet_slug":"deniz-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-sana-inat-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesişme Noktası', 'kesisme-noktasi-bahri-yildirim-q98ff', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu sabah kararlıyım

Her sabahtan daha çok

Yüreğim özlemlerimin

Çırpınışlarına tutsak

Oysa ben bu sabah.

Sana hiç kimsenin bakmadığı

Pencerelerden bakacağım 

Hiç kimsenin  görmediği gözlerle 

Süzeceğim seni,

Hiç kimsenin bilmediği kokuda

Goncalar sunacağım sana.

İnsanlık hali değil sadece bu

Aşk hali aynı zamanda

Aşığın gönlüne düşerse bahar

Gökten sabaha sadece

Goncalar yağar.

Bu sabah  daha da kararlıyım

Kavuşacağım sana yolu yok başka 

Bahar gözlüm,gül yanaklım

Hasretimi tutuşturan varlığım

Kadınım..

Ellerin benimde elimse

Gözlerin benimde gözümse

Çarpıyorsa yüreğim

Adını  her anışımda

Kalmaz dikenler taşlar,gül biter hep yollarda

Biter tüm tükenmezlikler

Buluşuruz zamanın en güzel noktasında

An gelir zaman olur

An gelir devran olur

Samanlıklar seyran olur

Dillere destan olur bu sevda

Ve sen...

Hiç bitmeyen  hasretim olursun

Yeni günün başladığı her sabahta

Ve bütün sabahlarda

Kimsenin daha önce hiç duymadığı sözcüklerle 

Anlatacağım sevdalarımı sana.

Gözlerim ve yüreğim

Senin emanetinde kalacak hep.

İyi sakla  kadınım

Emanete hıyanet yazmaz sevdanın kitabında

Biliyorsun

Ortak paydalardır,yaşama anlam katan

Bir kesişme noktasıdır

Sevda denilen kavga.

Benim seni aradığım gibi

Beni arayacaksan sen de sabahlarda

Ben sadece ordayım.

Mutlaka o noktada 

Seni bekliyor olacağım.', 'Bu sabah kararlıyım Her sabahtan daha çok Yüreğim özlemlerimin Çırpınışlarına tutsak Oysa ben bu sabah. Sana hiç kimsenin bakmadığı Pencerel...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/kesisme-noktasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara gözlüm', 'kara-gozlum-salim-erben-je9rv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara gözlerine bir kere baktım

Aşık oldum ben sana ne yaptım

Rüyada gördüm mühür gözlerini

Aklımı aldın dedin ben umutlandım

Gözlerine baktım muhabbet dolu

Özveride bulun kutlayalım bunu

Ziyarete açık kığnın yolu.

Laleler, papatyalar açtı mühür gözlüm

Üzüntü keder gülleri kuruttu

Menekşe sümbül dağları unuttu zalım', 'Kara gözlerine bir kere baktım Aşık oldum ben sana ne yaptım Rüyada gördüm mühür gözlerini Aklımı aldın dedin ben umutlandım Gözlerine baktı...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kara-gozlum-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne işin var İstanbul’da söz ve müzik:Gaziantepli bestekar ve şair Erol Güngör', 'ne-isin-var-i-stanbul-da-soz-ve-muzik-gaziantepli-bestekar-ve-sair-erol-gungor-erol-gungor-rjppl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adalara gitmedinse

                                   Boğazda hiç gezmedinse

                                   Modayı da görmedinse

                                   Ne işin var İstanbul’da.

                                   Köprüleri geçmedinse

                                   Balık ekmek yemedinse

                                   Beyoğlu’nu sevmedinse

                                   Ne işin var İstanbul’da.

                                   Emirgâna gelmedinse

                                   Orda bir çay içmedinse

                                   Güzelliği sezmedinse

                                   Ne işin var İstanbul’da.

                                   Şiir şarkı yazmadınsa

                                   Nostaljiyi tatmadınsa

                                   Şehre aşık olmadınsa

                                   Ne işin var İstanbul’da

                                   Anlatacak derdin çoksa

                                   Çalışacak işin yoksa

                                   Kalacak bir yerin yoksa

                                   Ne işin var İstanbulda.

                                   Mutluluğun azaldıysa

                                   Acıların çoğaldıysa

                                   Umutların daraldıysa

                                   Ne işin var İstanbulda.

                                   Erol Güngör', 'Adalara gitmedinse                                    Boğazda hiç gezmedinse                                    Modayı da görmedinse        ...', ARRAY['Türk Edebiyatı','Şiir','Erol Güngör']::text[], 8.5, '{"poet":"Erol Güngör","poet_slug":"erol-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ne-isin-var-istanbul-da-soz-ve-muzik-gaziantepli-bestekar-ve-sair-erol-gungor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Bu Kumsala İnsem', 'ne-zaman-bu-kumsala-i-nsem-murat-berk-b3s26', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman bu kumsala insem

Sende gönlüme girer

Usumu teslim alırdın.

Uzun bir zaman kumsala inemedim

Bu nedenle korkudan,

Ta üç gün öncesine kadar.

Bu kez  indiğimde

İsterdimki çıkıveresın 

Sandalların arasından.

Bilemedim

O uzun zamanın

On yıla mal olacağını.

Ölüm iniyor artık o kumsala,

Gölgem yok oluyor,

Kaplayıveriyor

O hain, vefasız usumu,

Kapkaranlık oluyorum

Ve gönlümü kurtarmaya 

Çalışıyorum,

O bana gerek

Çünkü içinde sen varsın.

Usum seni istemezken

Vazgeçmiyor gönlüm senden.

Son kez, son kez 

Gidiyorum kumsala

Zorla; 

O yağmurlu 

Issız ama muazzam geceyi

Ve

Öpmeye doyamadığım

Seni anımsamaya,', 'Ne zaman bu kumsala insem Sende gönlüme girer Usumu teslim alırdın. Uzun bir zaman kumsala inemedim Bu nedenle korkudan, Ta üç gün öncesine ...', ARRAY['Türk Edebiyatı','Şiir','Murat Berk']::text[], 8.5, '{"poet":"Murat Berk","poet_slug":"murat-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ne-zaman-bu-kumsala-insem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenildi', 'yenildi-i-brahim-kilinc-1s6kb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu sevda da galip malup yok ama

Yıllara yenildi bu sevda gülüm

Rivayet laf söz çok doğru yok ama

Kullara yenildi bu sevda gülüm

Vakitsiz yeşerdi vakitsiz soldu

Temiz suydu kirli bardağa doldu

Seni de beni de bir hayli yordu

Yollara yenildi bu sevda gülüm

Hep ince düşündüm daldım derine

Yazları bitirdim düştüm serine

Boğulmadı geçti deniz yerine

Çaylara yenildi bu sevda gülüm', 'Bu sevda da galip malup yok ama Yıllara yenildi bu sevda gülüm Rivayet laf söz çok doğru yok ama Kullara yenildi bu sevda gülüm Vakitsiz yeş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yenildi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Namlusudur Gözlerin', 'askin-namlusudur-gozlerin-selahattin-yetgin-gzakz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana beslediğim bütün sevinçleri kızıl bir şafakta görmelisin

Acılarla örülü yıkık bir duvardan, yaşanası nice ormanlar yarattın

Suskun bir denizin renk cümbüşünde önce kendini izlemelisin

Öyle çoğul, soylusun bu yürekte, beni karanlıktan aydınlığa çıkarttın

Sensizlik duvarlarını aşayım derken, bir sessizliğin alacasına düştü bedenim. Gözlerimin hıncı, sözlerinin kılıncı düşlerimi doğrarken fildişi kadehlerden içtim aşk meyini ben. Deştikçe, karıştırıldıkça ve örselendikçe onulmaz bu yaranın korkulu bakışlarında kaldım, sözlerimin balçık üşümelerinde yarınsızlığa daldım, saplandım. Geceler paslı bıçaktı, tatlı dillerinin sofrasında, ezgisinde şerefine nice kadehler kaldırdım.

Küf bağlamış bütün safkan koşuşlarımda yelelerimi rüzgara serdim, koştukça bizi içine çeken bir ırmakta günlerce can verdim. Kendime, yüreğime kırgın bir yüz, estikçe anılarımı bana yeniden getiren bir güz, bütün kavimlerin sonsuzlukta kaldığı bir çift göz oldum. Döşeğimdeki uykular derin, sevda çadırımda gönlüm serin kaldı. Söndürdüm sensizken tüm ışıkları, kapattım aşkın tüm perdelerini, yükledim sırtıma acının heybelerini ve kimsesizliğe yürüdüm.

Yaşamdan önceki son bahardı, gölgem gibi peşimden gelen. Bir masalın yapraklarını karıştırarak, kirli topraklarda yalın ayak yalpalayarak, okuldan kaçan bir çocuğun tanımsız korkusu, içindeki infiallerin yarınsız tortusu rengimi toprağa karıştırdı her seni düşündüğümde. Çok hülyalı bakışta kanayan dileklerim, melankoli nice sevdada çok kalp çiziklerim kaldı. Gözyaşıyla yıkanan bütün mendillerde, gecenin eteklerine tutunan tüm sevgilerde, acının gramerine çizildi resmim.

Dokunmaya kıyamadığımız o sol yanımızdan, çok yıldızlar düşürdük gecelerce. Adımlarımız sürgün kentlerin haritasına ne çok götürdü bizi biliyorsun. Oyalı mendil bıraktığımız sisliistasyonların kirli banklarında, bayram coşkusuyla yaktığımız tütsü ve buhur coşkularında her şeyimizi yüreğimizden kopardık biz. Kelimelerin bizi uzaklara götürdüğü, dalgalara bıraktığı o deniz ülkelerinden nice nice dönmedik mi sevgiyle. Gözlerindeki bensiz alınganlığın tortularında, benden başka hiç kimse alamaz gönlünü, çözemez tortunu, bilemez sendeki o kutsal yontuyu.

Sevdanın renklerle örülü o gökkuşağında her anımızın, her sancımızın raks duruşlarında aydınlığıma dane dane damlalarla nice göller olmadın mı? . Sen yüreğimin nazlı leylimi, hiçbir harfin seni anlatamadığı, hiçbir sözün seni tanıtamadığı sevgilisi. Kalbimin Zümrüt imparatorluğunda cennetim oldun, cehennem öksüzlüğümün renk renk çarşılarında panayırlar kurdun. Bilirim ki, beni tutsak eden asaletinle, sözcüklere yol veren onulmaz cesaretinle bu sevda kamasını hiç çekmezsin yüreğimden.

Bilmelisin ki, yaşanmamış, tadına doyulmamış baharları çoktan aşmışım ben. Ülkenin bakir topraklarındaki gül destelerini gezmektir dileğim. Yalancı güneşlerin bedenimi ısıtmadığı, sevda gemilerimin bir türlü çalkantılı denizlerimin sığ kayalıklarına ulaşamadığı ülkelerde yaşıyorum. Hayat için, zaman için ve yaşamak için çıktığım bu sevgi güvertesinde sensizliğe dayanamam ben.

Kıyım hasretlerin pusulasız sularında al beni, götür uzaklara. Az sonra yine gün dönecek geceye, sensizlik düşecek kim bilir bilmeceye. Terinde harman, insansız denizlerinde tayfan, kutsal yüreğinde sevdan olayım. Aşkın dağlarda gezmediğini, sevginin ovalarda yetişmediğini, sevdanın gökkuşağından inmediğini biz sevişerek öğrenmedik mi? . Şaraba banıp yüreğimizi, birbirimize dikip gözlerimizi her açlıktan doyumlarla, her şölenden çocuksu kahkahalarla kalkmadık mı? .

Gönlümüzün duvarlarındaki takvimlerin bayram coşkularında sevince kadeh kaldırıp, sessizce düşen yıldız dileklerimizde balıkçıların kaderine ağlamaktır yaşamak. Rengini denizlerden alan mavi öpüşlerinle, tüm yunusları kıskandıran gülüşlerinle martılar çekmedi mi sevgi ağlarımızı derinlerden? . Sevdamıza geceler bile çekemedi tetiğini. Sana sevdam, sana susamışlığım bitmedi, bitmeyecek. Aşkın namlusudur gözlerin, bilirim ki o tetik hiçbir zaman düşmeyecek.', 'Sana beslediğim bütün sevinçleri kızıl bir şafakta görmelisin Acılarla örülü yıkık bir duvardan, yaşanası nice ormanlar yarattın Suskun bir ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askin-namlusudur-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Ermiyor', 'aklim-ermiyor-gunduz-aydin-9v5n6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saçlarını salsana, rüzgarlarla bu yana

Bilir misin geceler, sabahlara varmıyor

Gün doğumu gelmezsin, biliyorum gelmezsin

Bekliyorum nedense buna aklım ermiyor.

Ne martılar geliyor, ne de çifte kumrular

Paramparça geceler, bölük-pörçük uykular

Nazlı nazlı bakışlar, kahır dolu sorular

Resimlerin buz gibi bana cevap vermiyor.

Bilir misin geceler, sabahlara varmıyor

Bekliyorum nedense, buna aklım ermiyor.

Resimlerin buz gibi bana cevap vermiyor.

Neden beklerim seni, buna aklım ermiyor?', 'Saçlarını salsana, rüzgarlarla bu yana Bilir misin geceler, sabahlara varmıyor Gün doğumu gelmezsin, biliyorum gelmezsin Bekliyorum nedense ...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aklim-ermiyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırış', 'haykiris-yavuz-bayram-caliskan-7iisu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir duman, sızlıyor yüreğim ta derinden,

Özlemlere mi geliyoruz yoksa,

Bir garip gidiş mi bu? 

Limanda mendil sallayanlar,

Güneşine kavrulanlar,

Katran karasına bulananlar,

Haykırışım size.

Sığdıramıyorum, bir garip geliyor.

Sislere gömülüyorum,

Karanlıklar bezeniyor,

Kor yüreğim kırka bölündü.

Mahrum kalacak bu yürek,

Sızılarıyla, inlemeleriyle, ağıtlarıyla.

Haykırışım kimseye değil.

Tanımsız kavramlar, birbirini çelmeliyor,

Güneş doğsa da gün karanlık.

Mahzenlerdeyim, sıkıntılıyım,

Don vurmuş yüreğimi.

İsyan günlere sancılanıyor,

Çek bir nefes acılarda,

Ey garip Yavuz Bayram..!', 'Bir duman, sızlıyor yüreğim ta derinden, Özlemlere mi geliyoruz yoksa, Bir garip gidiş mi bu?  Limanda mendil sallayanlar, Güneşine kavrulan...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/haykiris-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşım Mehmet', 'arkadasim-mehmet-resul-ustun-1l0a8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '14 Nisan 2001 tarihinde bir akşamüstü Çermik İlçesinden Diyarbakıra dönerken Erganiye bağlı Pirahmet (Ahmetli)   Köyü yakınlarında geçirdiği trafik kazası sonucu yitirdiğimiz 1978 kuşağı öğrenci gençliği önderlerinden sevgili Mehmet İzin anısına...

Güleç dostum! 

Sevdaydın en karasından,

Sindiremediler.

Yiğittin en alasından, 

Çekemediler.

Az bulunur bir merttin bu namert dünyada,

Kabullenemediler.

Sen mert gençliğin alnı açık mert yüreğiydin,

Bitiremediler.

Arkadaşım! 

En güzel sen gülerdin,

Ağlatamadılar.

Elinde Kesk û Sor mendilinle en güzel sen oynardın.

Durduramadılar.

Hazanda gazelleri,

Mezarda ölüleri diriltirdi kahkahaların,

Susturamadılar.

Sen yüreklerde sevgi, gözlerde ışıltıydın,

Karartamadılar.

Esmerim, karagülüm. 

Varsa günahı, 

Günahıydın özgürlüğe kaçışların.

Işıltıydın,

Beyaz geceydin mayınlı sınırda,

Karartamadılar.

Sevgide okyanustun,

Zerresini eksiltemediler.

Karanfildin, kekiktin, papatyaydın…

Çiçek çiçek bahardın dağlarımda

Her mevsim bir başka kokardın.

Ey güzel insan! 

Giderken iz bıraktın ardından.

İzciler izini sürdüler.

Tipi, boran, kıyamet demeden

Çirkin mi çirkin,

Hain mi hain ittifaklar kuruldu.

Sınır antlaşmalarına konu oldun.

Hasan Keyfli bir sürgün tarihini

Yine ölü dirilten gülüşünle yazdın.

Gülüşüne,

Bakışına,

Sevdana bizi hasret koydun be dostum.

Bir özgürlük tohumuydun

Mücadele tarihinden arta kalan.

Sen aşkın en kısa ömrü,

Umudun sonsuzluğuydun.

Ah be tatlı dillim,

Güler yüzlü çocukluğum! 

Sen her şafakla yeniden yeşerip,

Gün batımlarında sararan bir yiğit başkaldırıydın.

Güneş sana hasretken,

Sen Güneş’e hasret gittin be dostum.

Ne gecede kaldın,

Ne de gündüze doydun.

Ahhh! Ah be ciğerim.

Doyamadık, doyamadık sana.

Bakışına,

Gülüşüne,

Dostluğuna bizi hasret koyup gittin.', '14 Nisan 2001 tarihinde bir akşamüstü Çermik İlçesinden Diyarbakıra dönerken Erganiye bağlı Pirahmet (Ahmetli)   Köyü yakınlarında geçirdiği...', ARRAY['Türk Edebiyatı','Şiir','Resul Üstün']::text[], 8.5, '{"poet":"Resul Üstün","poet_slug":"resul-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/arkadasim-mehmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Sensiz Olmadım', 'hic-sensiz-olmadim-yavuz-bayram-caliskan-rhom1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'HİÇ SENSİZ OLMADIM

Ne kışı öldür can evinden

Ne ılık mevsimlerin sandalıyla okyanus aş

Koyu gölgelerden çık

Ağaçlar ve kayalar dursun yerinde

Gök gürültüsüyle kükreyen yağmuru sev

Bir pamuk örtüsüyle yağan karı

Suları sev, çağlayanları,

Yeryüzünden fışkıran pınarları,

Tablolarını sev doğanın, her kırıntısını tanı

Yaşamak gülmekse, gül güneşe

İçmek mutluluksa iç ve kanat sevdayı yüreğinden

Umudu ekmeğinden hiç çıkarma

Katıksız yaşanmaz, çiçeksizde.

Sensiz yaşanır mı? 

Bilmem ki,

Hiç sensiz olmadım.

Soğuk testilerde uyuyan sular,

Kor yürekleri serinlet,

Kanımla kan ol,

Damarlarımda dolaş,

Yüreğimle at,

Çıkma canımdan can evimden,

Tutup yakamdan gelmeden ölüm,

Aşk ol kaynaş, benim canım Ayşegülüm…', 'HİÇ SENSİZ OLMADIM Ne kışı öldür can evinden Ne ılık mevsimlerin sandalıyla okyanus aş Koyu gölgelerden çık Ağaçlar ve kayalar dursun yerind...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hic-sensiz-olmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Değil Bir Günüm', 'mutlu-degil-bir-gunum-gunduz-aydin-tbe54', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıldızların altında, seni sana sordum hep

Akşam diye martılar, bir yanıma gelmedi

Rüzgarların önünde, senli hayâl kurdum hep

Yıllar geçti aradan, kara bahtım gülmedi

Tutuşsaydık el ele, martılar kıskanırdı

Şiirlerde sen vardın, herkes seni tanırdı

Masallar söylenirdi, neler neler denirdi? 

Olmadı be güzelim, ne yaparsın olmadı

Saçlarında çiçekler, sana dargın,diyorlar

Gözlerin ağlamaktan, yine yorgun, diyorlar

Ayakların gönlüne, kırgın kırgın, diyorlar

Şafaklar sevdiğimi, hiç bir zaman bilmedi

Bir sordun mu böylece, nerelere gelindi

Her sabah kaldırdığım, yüzündeki tülündü

Mektuplarım gitti de, üçe beşe bölündü

Postacılar kapımı, bunca yıldır çalmadı

Yarasalar şahidim, martılara kırgınım

Nazlarını çekerim, saçlarına dargınım

Bırak aylar-yılları, mutlu değil bir günüm

Parmakların uzanıp, gözyaşımı silmedi

Artık çok geç gündüzler, gecelere karıştı

Yüzümdeki umutlar, senle birlik kırıştı

Birgün sevdam gizlice, hayâlimle görüştü

Böylece umutlarım, şarkılarda solmadı', 'Yıldızların altında, seni sana sordum hep Akşam diye martılar, bir yanıma gelmedi Rüzgarların önünde, senli hayâl kurdum hep Yıllar geçti ar...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mutlu-degil-bir-gunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'His', 'his-yavuz-bayram-caliskan-30hl6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neredesin? 

Gözlerimin ufuklara erdiği yerdesin.

Neredesin? 

Hayallerime daldığım yerdesin.

Neredesin? 

Bakıp ta göremediğim bir puslu penceredesin.

Hissediyorum da...', 'Neredesin?  Gözlerimin ufuklara erdiği yerdesin. Neredesin?  Hayallerime daldığım yerdesin. Neredesin?  Bakıp ta göremediğim bir puslu pence...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/his-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Kaynıyor', 'i-cim-kayniyor-yavuz-bayram-caliskan-uh7rn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıldızlara ne kadar yakınsın.

Yıldızlar ne kadar uzak, yetemiyorum.

Sılanı özlüyorum, içime doğuyor güneşin.

Gurbeti yetimliği ile yaşadım.

Fırtınalara egemen olmak kolay mı? 

İçimin kaynağı, içimin pınarı.

Beni denizlere çiviledin,

Sahilin miyim? Kumsalın mıyım? 

Tutsağın mıyım? İç ettin beni...', 'Yıldızlara ne kadar yakınsın. Yıldızlar ne kadar uzak, yetemiyorum. Sılanı özlüyorum, içime doğuyor güneşin. Gurbeti yetimliği ile yaşadım. ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/icim-kayniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçYüZ', 'i-cyuz-asima-azra-smdjq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özümsettiler yıllarca 

-içimize tıka basa-

her mahlûkat eremiyor diye aşka…

Altı çizilmeliydi oysa

-gözümüze soka soka-

insan doğmak başka, insan olmak başka!', 'Özümsettiler yıllarca  -içimize tıka basa- her mahlûkat eremiyor diye aşka… Altı çizilmeliydi oysa -gözümüze soka soka- insan doğmak başka, ...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/icyuz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Gülüm Çok Özledim', 'sari-gulum-cok-ozledim-gunduz-aydin-1mk47', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarı gülüm bilir misin yaz geldi

Çık yuvandan, salın da gel bize gel

Çok özledim saçlarının rengini

Savur da gel, koşaraktan düze gel

Uzat silem, gözlerinin yaşını

Çatma öyle, yakışmıyor kaşını

Kaldır bir bak, bana doğru başını

Seni çalan, çok özleyen saza gel

Bak başaklar, saçın rengi olmuşlar

İşte gözler, sensiz-garip solmuşlar

Senli olan tüm anılar gelmişler

Bu yaz gelmez isen, gelen yaza gel', 'Sarı gülüm bilir misin yaz geldi Çık yuvandan, salın da gel bize gel Çok özledim saçlarının rengini Savur da gel, koşaraktan düze gel Uzat s...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sari-gulum-cok-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-yavuz-bayram-caliskan-u3zmp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül solunca,

İnsan ölünce,

Ok yaydan çıkınca,

Eser insan olunca,

Gönüllere bir ateş alacası düşer,

O gönüller ömürlere yelken açar...', 'Gül solunca, İnsan ölünce, Ok yaydan çıkınca, Eser insan olunca, Gönüllere bir ateş alacası düşer, O gönüller ömürlere yelken açar......', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/insan-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler (98) ''''Lale,gül,hanımeli...''', 'maniler-98-lale-gul-hanimeli-abdullah-atay-xal51', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostluğun ve aşkın ateşini sevginin kıvılcımları yakar. 

İhanetin acı rüzgarları da söndürür... 

Yarimin gözü ela 

Gönül aşka müptela 

Saçlarıma ak düştü 

Yari beklerim hala... 

Yar yanıma gelince 

Şakır kendi dilince 

Kor dudakta gül açar 

Yarim bana gülünce... 

Yar tutmuyor elimden 

Anlamıyor halimden 

O musalla taşında 

Tutsa bari salımdan... 

Gurbetin yolu uzak 

Orada binbir tuzak 

Kurt kuşun yuvası var 

Biz de yuvamız kursak 

Susuz dere akmıyor 

Yar yüzüme bakmıyor 

Yaban elin gülleri 

Yarim gibi kokmuyor... 

Yari her dem anarım 

Hasretiyle yanarım 

Yarimi verirseniz 

Hem güler,hem oynarım... 

Lale,gül,hanımeli 

Onlar sevenin dili 

Yarin ılık nefesi 

Sanki bir bahar yeli... 

Yarim yakmış kandili 

Oyalıyor mendili 

Mendili oyalarken 

Oyalıyor kendini...', 'Dostluğun ve aşkın ateşini sevginin kıvılcımları yakar.  İhanetin acı rüzgarları da söndürür...  Yarimin gözü ela  Gönül aşka müptela  Saçla...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/maniler-98-lale-gul-hanimeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-yavuz-bayram-caliskan-8iagp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutsağı oldukları yüreğin çarkında,

Döner durur bir ay, dünyasında.

Yürek de para etmiyor,

Eskimiyor yaralar,

İçin için kanıyor.

Gönlümden sürgüne çalıştım,

İçime batıp çıkan gözlerini.

Ey umursamayan insan,

Kaldırıp attığın yüreğimin ta kendisidir...', 'Tutsağı oldukları yüreğin çarkında, Döner durur bir ay, dünyasında. Yürek de para etmiyor, Eskimiyor yaralar, İçin için kanıyor. Gönlümden s...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/insanlar-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanım Var', 'i-syanim-var-yavuz-bayram-caliskan-lyznv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerine dolan yaşa,

Bahar ile gelen kışa,

Ardından atılan taşa,

İsyanım var.

Yüreğini kıran dile,

Seni çekemeyen ele,

Gözlerine batan güle,

İsyanım var.

İyilik perimi üzenlere,

İnsanım diye gezenlere,

Haksız yere ezenlere,

İsyanım var.

Huysuz, tozlu, kalmışlara,

Kibire, gurura dalmışlara,

Beyinleri ot olmuşlara,

İsyanım var.

İsyanım kine dönüşür,

Canım sarı çiçeğim rüzgarlarda üşür,

Ömrü köhne geçenler elbette çürüşür,

Allah’ın yalnızlarına isyanım var…', 'Gözlerine dolan yaşa, Bahar ile gelen kışa, Ardından atılan taşa, İsyanım var. Yüreğini kıran dile, Seni çekemeyen ele, Gözlerine batan güle...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isyanim-var-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilimsel Aşk', 'bilimsel-ask-ezel-i-lhan-gxi6p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilimsel Aşk

Bir coşkuya esir olmuş bütün duygular,

Benliğini sarmış hastalık gibi.

Saatleri,saniyeleri doldurmuş

Bomboş umutlar.

Öyle boş ki bir boşluk gibi.

Duygu mantık çatışmasını

Hisler kazanmış.

Hiç hesapta yokken

Bütün anılar,hayallerde yaşanmış,

Yaşanacak şey çokken.

Kalbimiz etkisi altında kalmış,

Duyduğu masalların,

Ve aşık olmasını istemiş; 

Bu masalları yazanların.

Sonuçta ise olmuşsun şaşkın.

İşte budur,açıklaması

Bilimsel aşkın.', 'Bilimsel Aşk Bir coşkuya esir olmuş bütün duygular, Benliğini sarmış hastalık gibi. Saatleri,saniyeleri doldurmuş Bomboş umutlar. Öyle boş k...', ARRAY['Türk Edebiyatı','Şiir','Ezel İlhan']::text[], 8.5, '{"poet":"Ezel İlhan","poet_slug":"ezel-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bilimsel-ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader ''e Sitem (Aslan Mustafa''ya -İç Anadolu''nun Darbukatörü)', 'kader-e-sitem-aslan-mustafa-ya-i-c-anadolu-nun-darbukatoru-yavuz-bayram-caliskan-mmoyp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmem ki ne sebeple dünyaya attı kader,

Atıp ta hiç durmadan böyle ağlattı kader.

Bir yolcuyum yol bilmez, iz bilmez, geçit bilmez,

Bir kuru yaprak gibi önüne attı kader.

Boynu bükük süründüm hayat sokaklarında,

Her köşenin başında kaşını çattı kader.

Gözlerimde kan, gönlümde hicran oldu,

Her fırsatta kalbimi deşti, kanattı kader.

Anlaşamadık. Kabul, fakat neden

Şu çekilmez hayatı, böyle uzattı kader? 

Dönüp  bakamadım geriye birden? 

Genç yaşlarda bu dünyadan beni aldı, attı kader...

Bu web sayfasındaki yazıların, şiirlerin ve bestelerin yasal hakları,

5846 sayılı telif hakları yasası gereğince Yavuz Bayram Çalışkan''a aittir. İzinsiz kopyalanamaz', 'Bilmem ki ne sebeple dünyaya attı kader, Atıp ta hiç durmadan böyle ağlattı kader. Bir yolcuyum yol bilmez, iz bilmez, geçit bilmez, Bir kur...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kader-e-sitem-aslan-mustafa-ya-ic-anadolu-nun-darbukatoru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affedersin', 'affedersin-ezel-i-lhan-w4zdf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Affedersin

Farkında olmadan 

Seni kırdımsa.

Biliyorum kırılan kalpler 

Onarılmaz ama,

Ben bağışlanmak istiyorum.

Lütfen benden nefret etme,

Af diliyorum.

Biliyorum sen harika birisin.

Benim seni üzmeye ne hakkım var ki? 

Ama bende çok üzüldüm inan ki

Belliki  bu olayda en masum sensin.

Suç benim tamam biliyorum.

Seviyorum seni affedersin.', 'Affedersin Farkında olmadan  Seni kırdımsa. Biliyorum kırılan kalpler  Onarılmaz ama, Ben bağışlanmak istiyorum. Lütfen benden nefret etme, ...', ARRAY['Türk Edebiyatı','Şiir','Ezel İlhan']::text[], 8.5, '{"poet":"Ezel İlhan","poet_slug":"ezel-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/affedersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahır', 'kahir-yavuz-bayram-caliskan-zmmc6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kahırlara verdim adımı sevda yollarında,

Doğan güller benden uzakta.

Açan çiçekler kokularını getirmiyor,

İğdelerle meltemler oynaşıyor,

Denizlere ben koşamıyorum,

Sevemiyorum dalgaları.

Çöl yalnızlığı esiyor ruhumda,

Adım kahır, soyadımı bilen yok,

Alınyazım yalnızlık,

Geleceğim ayrılık,

Gecelere yürüyorum.

Karanlıklar kollarını açıyor,

Aydınlıklar can çekişiyor,

Bulutların gözyaşına, eşlik ediyor gözlerim,

Odalar kahır dolu, odalar yalnızlık,

Katarları taşıyorum.

Sımsıcak ekmeği özledim,

Boğazıma duran, bir yumruk gibi,

Bir taş gibi yalnızlık,

Kalbimin feryadı uzak denizlere,

Gönlümün ışığı ırak sabahlara,

Avuçlarıma bakıyorum,

Sımsıkı tuttuğum çakıl taşlarını bırakıyorum,

Ellerim kan içinde.

Yüreğime bakıyorum,

Sevdiğim seni bırakıyorum,

Yüreğim kan içinde.

Arzuların son yanışı bu bedende,

Dopdolu yaşamak neyimize,

Dağıldık, dayanamadık rüzgarına,

Ne de ağırmışsın kahır, taşıyamadık.

Kuytu kaçamaklar bile hayal oldu

Duldalarda yaşamıyorum,

Sefilce şarabımı çekiyorum.

Ne serin ormanlar,

Ne yeşile sevdalı çamlar.

Saçaklardan uzanan buzlardan hep kahır damlıyor.

Yanmak var ya yürekten delicesine,

Saklasam da duygularımda,

Zor, nefes bile zor.

Yalnızlık dolu dizgin, 

Kanıma girdin ya.

İpini çektin bitmeyecek sandığımız,

Ömür dediğimiz günlerin,

Çılgın arzularımı yaşayamadım,

Sevdiğimi kalbine söyleyemedim.

Saçlarını okşayacak ellerim,

Taşları denizlere atıyor.

Yıldızlara hep baktım gıpta ile,

Bir yıldız bile olamadım.

Öpmeliydim sevdanın tâ yüreğinden,

Körkütük sarhoşluk beni mahvetti.

Efkar bastı mevsimleri,

Aynalar paramparça,

Limanlar köhne,

Rıhtımlarda bekleyiş yolcuları,

Bir bulut arıyorlar, ağlamak için.

Sensiz ölsem de cehennemle,

Sessiz ölmeye gidiyorum, dostum...', 'Kahırlara verdim adımı sevda yollarında, Doğan güller benden uzakta. Açan çiçekler kokularını getirmiyor, İğdelerle meltemler oynaşıyor, Den...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/kahir-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilse', 'bilse-ezel-i-lhan-rg30o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilse

Çocuk bilse,

Ateşin sıcaklığını.

Uzatır mı hiç elini? 

Kadın bilse,

Anneliğin derinliğini,

Üzer miydi hiç annesini? 

Ve aşık bilse,

Sevgilinin riyasını

Böylesine sever miydi?', 'Bilse Çocuk bilse, Ateşin sıcaklığını. Uzatır mı hiç elini?  Kadın bilse, Anneliğin derinliğini, Üzer miydi hiç annesini?  Ve aşık bilse, Se...', ARRAY['Türk Edebiyatı','Şiir','Ezel İlhan']::text[], 8.5, '{"poet":"Ezel İlhan","poet_slug":"ezel-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bilse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sergır', 'sergir-resul-ustun-lgam0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bağdaş kurmuşsun ağa sofrasına,

ekmek topraktan, ayran inekten,

alınterimizi de tuz niyetine,

ye ha ye sergır, iç ha iç sergır.

Bir elin ensede, bir elin göbekte.

harmana sürü mü dalmış, neyine.

Nasılsa her kış bir bahara gebe,

ye ha ye sergır, iç ha iç sergır.

Açlıkmış, sefaletmiş bu ne masal,

vur hançeri, vur gitsin yüreğime.

Sakın ola acımak nedir bilme.

Ye ha ye sergır, iç ha iç sergır.', 'Bağdaş kurmuşsun ağa sofrasına, ekmek topraktan, ayran inekten, alınterimizi de tuz niyetine, ye ha ye sergır, iç ha iç sergır. Bir elin ens...', ARRAY['Türk Edebiyatı','Şiir','Resul Üstün']::text[], 8.5, '{"poet":"Resul Üstün","poet_slug":"resul-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sergir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Gördüm', 'seni-gordum-ozkan-karaca-cxf6x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni gördüm kirli bulutların altında

Küçük izlerimizle çiğnediğimiz sokakların alnında

Yılların an taşları hayatıma dolmuş

Sevdanın rengi bende donmuştu

Geçmişin çocukluğundan çalarak kadın haline saldın

Hasretin karanlığından çıkarak gözümü aldın

Seni gördüm uzun suların akıntısından sonra

Düşlerin penceresini elimizle aralardık

Sevdamızın serçesini ufuklara salardık

Gözün gözümde erirdi

Sözün sözüme esirdi

Ah..! Dişlerimde öğüttüğüm pişmanlık taştı

Yüreğimin intizarı damarımı yırtarak aştı

Sana dönseydim, sevgimize örseydim

Yıldızları avuçluyarak kalbine koymuştum

Dalgaları kucaklıyarak başına dökmüştüm

Şafakların tebessümüne seni sormuştum

Hülyalarımız arasına seni sarmıştım

Sokakların seninle eskiyen kirlerinde

Anılarını getirerek aklımın kalıbına bıraktın

Seni gördüm ince dilin akrebinde

Senden çocukluğumuzun şadında kopmuştum

Gördüğümde ise; alnı kırışmış, gözleri yırtılmış

Birde: şefkatle ellerini tuttuğun evlatların vardı

Seni hayalimin tarağında eşim yapmıştım

Derme çatma bir evimiz

Yuvamızı şenlendiren çocuklarımız...

Karanlığın hasretinden ansızın göründün

Ve... bende akşamın karanlığında karardım

Yitik şehrin kaldırımlarına vurdum

Gözlerimi acının yağmuruna sürdüm', 'Seni gördüm kirli bulutların altında Küçük izlerimizle çiğnediğimiz sokakların alnında Yılların an taşları hayatıma dolmuş Sevdanın rengi be...', ARRAY['Türk Edebiyatı','Şiir','Özkan Karaca']::text[], 8.5, '{"poet":"Özkan Karaca","poet_slug":"ozkan-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/seni-gordum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar İzleri', 'kar-i-zleri-yavuz-bayram-caliskan-ivt9y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adını Eylül koydum sevdanın,

Tutkular, çiçekler ve bulutlarla seni tanıdım,

Yaşamak ve ümit, inan baharı seninle anladım.

Başlamak hem de sevecen bakışlarla,

İçimizden geleni yaşadık.

Aşk yoluna düştük ve kaderden payımızı aldık.

Külfeti çok da olsa,

Ne acıları susturmuştur derin sevgiler.

Şefkatin kolları ne de yumuşaktır.

İçime bastırdım seni, korlara gömdüm yüreğimde.

Dağ gibi sevgi seli çağlıyor tüm bedenimde.

Tıklım tıklım bekleyiş yolcuları şafakta,

Süzülüp gelen ışıkları gözlerine almakta.

Sığıntı yaşamak istemiyorum.

Hüzün kıyılara vurmuş, yürü ve sil izleri,

Sevdaya karışan deniz şarkıları seni anlatıyor.

Başı boş günlerin acısını yaşayan yürek,

Mevsimini gömüyor sonbahara.

Avuçlarıma alıyorum ve okşuyorum, sevdanın saçlarını,

Taze bir aşkın ışıklarında kayboluyorum.

Gün benim için doğuyor,

Aşk şafağında sevdama çiğ düşüyor,

Ve ben ağlıyorum,

Yüreğimde kar izleri var...', 'Adını Eylül koydum sevdanın, Tutkular, çiçekler ve bulutlarla seni tanıdım, Yaşamak ve ümit, inan baharı seninle anladım. Başlamak hem de se...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kar-izleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevda', 'kara-sevda-yavuz-bayram-caliskan-xkapn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kara bulutlar yığıldı gözlerime,

Bir kara sevda yağacak.

Aşıklar ıslanacak kuytu yağmurlarda,

Bir dünya ağlayacak.

Dökülüyor çınarın hazan yaprakları,

Bir ömür dökülüyor,

Bir can tükeniyor.

Kararıyor duygular,

Sarıyor sevdaları, kara sevdalar.

Gönlüm sonbahar, yüreğim yaprak,

Gün batımında tükenişlerde kavuşacak.

Yalnızlığına kahredenleri sarmalayacak,

Bir kara toprak...', 'Kara bulutlar yığıldı gözlerime, Bir kara sevda yağacak. Aşıklar ıslanacak kuytu yağmurlarda, Bir dünya ağlayacak. Dökülüyor çınarın hazan y...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kara-sevda-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katlanamıyorum', 'katlanamiyorum-yavuz-bayram-caliskan-j2ipa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşi sevsem de, 

Batışını daha çok seviyorum.

Yağmuru sevsem de,

Kaçışımı daha çok seviyorum.

Bülbülü sevsem de,

Yakarışını daha çok seviyorum.

Gülü sevsem de,

Dikenine katlanamıyorum...', 'Güneşi sevsem de,  Batışını daha çok seviyorum. Yağmuru sevsem de, Kaçışımı daha çok seviyorum. Bülbülü sevsem de, Yakarışını daha çok seviy...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/katlanamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Güller', 'kirmizi-guller-yavuz-bayram-caliskan-jb5v4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su yine sessiz akar,

Sevdan kor olmuş kalbimi yakar.

Neredensin bilemiyorum şimdi sen? 

Bu sevdayı bir garip Bayram çeker…

Akıyorum hayallerle, sensizlikle,

Nisan yağmurlarının yağdığı yerde,

Aşkın canlanır gözümde perde perde,

Ararım seni hep o mavi körfezde.

Seni beklerim, seni yaşarım,

İliklerime değin ıslansam bile.

Düşmez elimden sevdiğim,

Sana getirdiğim o kırmızı güller...', 'Su yine sessiz akar, Sevdan kor olmuş kalbimi yakar. Neredensin bilemiyorum şimdi sen?  Bu sevdayı bir garip Bayram çeker… Akıyorum hayaller...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kirmizi-guller-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Kulesinde Akşam', 'kiz-kulesinde-aksam-yavuz-bayram-caliskan-m3p27', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deniz yalnızlığa çırpınır,

Bir martı balıklar için kanat kırar.

Suların valsinde Kız Kulesi

Akşamın yakamozunu kucaklar.

Geceye bir ayrı tebessüm,

Geceye bir başka selam,

Seni anlamak çok zor be! 

Güne bir başka, geceye bir başka.

Sabahı beklerim yıldızlarla,

Koynundan çıkamam karanlığın,

Ağıtlarımı bile gizler,

İstanbul’un yüreğindeki Marmara...

Bu web sayfasındaki yazıların, şiirlerin ve bestelerin yasal hakları,

5846 sayılı telif hakları yasası gereğince Yavuz Bayram Çalıkan''a aittir. İzinsiz kopyalanamaz', 'Deniz yalnızlığa çırpınır, Bir martı balıklar için kanat kırar. Suların valsinde Kız Kulesi Akşamın yakamozunu kucaklar. Geceye bir ayrı teb...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kiz-kulesinde-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Olsun', 'kor-olsun-yavuz-bayram-caliskan-1jjpm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıldızlar benim, gözlerinden tapuladım.

Nasıl anlamadım, yüreğime kayan gözleri.

Köhne mahzenlerde yıllanan şaraplar,

Değerini içenler anlayacaklar.

Bir yudum sevdayı, yıllarla anlatacaklar.

Çat kapıyı kapatmayacaklar yüzüne,

Yaşadığın yer sokaklar ve kaldırımlar olsa da.

Değerler yaşanmak içindir.

Güneşi aşklarına sokmazsan,

Bilir misin yüceliğini? 

Bakışları yüreğine çakmazsan bilirsin yakışını,

Ey sevdalara yelken açmış kürekler,

Yüreğine yaşayın sevdanın.

Gözlerinden vurun aşkın,

Vurun ki gözleri kör olsun...', 'Yıldızlar benim, gözlerinden tapuladım. Nasıl anlamadım, yüreğime kayan gözleri. Köhne mahzenlerde yıllanan şaraplar, Değerini içenler anlay...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kor-olsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahsun Bakışlar', 'mahsun-bakislar-yavuz-bayram-caliskan-8g7ll', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Titreyen mumlar bir rüzgar bulur,

Gönlü titreten hangi şimşek? 

Akşam olur, sabah olur,

Bir bakışa her şey biter.

Akışların gizeminde bir garip kokar,

İğde çiçekleri.

Saçları seven eller,

Gözleri seven gözler,

Gönül bu ya hep,

Mahzun bakışları özler...', 'Titreyen mumlar bir rüzgar bulur, Gönlü titreten hangi şimşek?  Akşam olur, sabah olur, Bir bakışa her şey biter. Akışların gizeminde bir ga...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mahsun-bakislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehtapla', 'mehtapla-yavuz-bayram-caliskan-tn8wl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mehtapla birlikte buluştuk yeniden.

Ayrılığımız asırlarca sürmüşçesine

Özlem dolu dudaklarımız bir hasreti dindiriyor.

Hırçın bir deniz gibi bakışan gözlerimiz,

Sevi rüzgarları kalbimizde uğulduyor.

Kumsala uzanırken kollarımda sen,

Gecenin kararan gözlerinde bir ümit sandalı

Işıldayan bir emele kürek çekiyor.

Bizdik o geceyi yaşayan karanlığın koynunda.

Gözlerimizden boşanan yaşlarla, dinen hasretimizle,

Kucağındaydık sabahın alacasının, mutluluğun kucağında...', 'Mehtapla birlikte buluştuk yeniden. Ayrılığımız asırlarca sürmüşçesine Özlem dolu dudaklarımız bir hasreti dindiriyor. Hırçın bir deniz gibi...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mehtapla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleğim', 'melegim-yavuz-bayram-caliskan-ghlt0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Taze sabah güneşi,

Okşayıp uyandırsa,

Işısa gözlerin,

Gözlerimde seninle.

Göklerde kanatlanıp, 

Uçsam ümit yeliyle,

O sevdalı gözlerinde.

Yaşasam seni, seni yaşasam,

Körpecik aşkınla,

Yeşeren beni,

Bir kırık kalpliyi,

Anlarsın belki de! ..', 'Taze sabah güneşi, Okşayıp uyandırsa, Işısa gözlerin, Gözlerimde seninle. Göklerde kanatlanıp,  Uçsam ümit yeliyle, O sevdalı gözlerinde. Ya...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/melegim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapacaksınız?', 'ne-yapacaksiniz-yavuz-bayram-caliskan-mxbwt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşündüm de; Ölürsem nefretleri benimle mi gömeceksiniz? 

Kin tohumlarınızı yeşertecek yer bulabilecek misiniz? 

Kahırlarınızı kimlere edeceksiniz? 

Hasretleri kimlere tattıracaksınız? 

Hangi gözleri tuzlayıp dalgalarla denizlere yollayacaksınız? 

Gurbet akşamlarını kimlerle karşılayacaksınız? 

Söyle bana gonca daha hangi cevahirleri parçalayacaksınız? 

Cevap verebilir misiniz?', 'Düşündüm de; Ölürsem nefretleri benimle mi gömeceksiniz?  Kin tohumlarınızı yeşertecek yer bulabilecek misiniz?  Kahırlarınızı kimlere edece...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-yapacaksiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapsın?', 'ne-yapsin-yavuz-bayram-caliskan-lrfmm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Esirgeme gözlerini,

 Verebiliyorsan sevgini.

 Dağları yüklendim,

Aldandık, bir bakışa satıldık.

Gül bir günde ölüme açarsa,

Biz günde bir ölüm yaşıyoruz.

Yapraklar ağlar sabah çisesinde,

Sürgüne sancılar başlamıştır,

Bir beddua dillerde.

Tebessümüne sığındım.

Bakışlarının menzili,

Ne de yakınmış meğer.

Yağmur indirir gözlerim,

Sana fırtına, sana sel ne yapsın?', 'Esirgeme gözlerini,  Verebiliyorsan sevgini.  Dağları yüklendim, Aldandık, bir bakışa satıldık. Gül bir günde ölüme açarsa, Biz günde bir öl...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-yapsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-yavuz-bayram-caliskan-kpmff', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kahredip tütüyor mazimiz,

Kalplerimizde külleniyor.

Dudaklardan dökülen isimler,

Mezar taşlarında küfleniyor.

Sızıp kalan sevgiler son kadehlerde,

Arar son yudumunu, ıslatır gözleri.

Can damarına dolan kan yüreklendirir sevdayı.

Yürür yolları, sürüklenir hayallerde,

Kurumuş pınarlarda soluklanan dudaklar,

Çatlar, kurur ve acımasızca yanar.

Emellerin zinciri sıkar boğazları,

Umut yağan gözlerdeki yağmur dinerse,

Başlar bir ışıltı, makberi beklemez ruhlar,

Dudaklarda birleşir tüm hisler ve duygular.

Gün ışıltısı karaları gömer,

Ta içine çeker denizleri.

Çınarlar neden uludur? 

Sevdalar neden yücedir? 

Hasret neden acıdır? 

Neden özlemlerde yaşar umutlar? 

Denizle dalga neden koyun koyuna yaşar sevdalarını.

Dilek taşları neden parlaktır? 

Neden yıldızlarda buluruz dünyamızı? 

Ulaşılmaz olan her şey neden çok istenir? 

Toz pembe dünyaların yolcusu ne de çoktur.

Neden bir çok şey bu günde yoktur da yarınlardan istenir? 

Anlamsız karalar neden temiz kayaları kirletir? 

Neden aşık olmak için nisan yağmuru gerekli bu şehirde? 

Neden ölümüne severler de ölümüne ölemezler?', 'Kahredip tütüyor mazimiz, Kalplerimizde külleniyor. Dudaklardan dökülen isimler, Mezar taşlarında küfleniyor. Sızıp kalan sevgiler son kadeh...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/neden-190-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Perisi', 'su-perisi-ali-baydere-n2vh1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanı geldi git demeden gideceğim

Ezdirmem sana kendimi, günü gelince döneceğim

Lanetim senin değil, o gözlerine bakan benim

İnan bana sevgilim seni bir gün sileceğim

Hoyrat akan yaşlarımı yana yana keseceğim

Anlamazsın bilirim, sen bana ait değilsin bilirim

Zannetme ki her şey senin elinde

Elimi kaldırmam güle güle değince

Lale devri yaşattın ya içimde

İnan bir daha gelmeyeceğim görmeye

Hoş bu seni pek etkilemese de

Ama nasıl olduğunu görürsün sevince', 'Zamanı geldi git demeden gideceğim Ezdirmem sana kendimi, günü gelince döneceğim Lanetim senin değil, o gözlerine bakan benim İnan bana sevg...', ARRAY['Türk Edebiyatı','Şiir','Ali Baydere']::text[], 8.5, '{"poet":"Ali Baydere","poet_slug":"ali-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-perisi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni ben de sevdim ey güzel İstanbul Gaziantepli şair Erol Güngör', 'seni-ben-de-sevdim-ey-guzel-i-stanbul-gaziantepli-sair-erol-gungor-beste-goksel-baktagir-s6nfq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni ben de sevdim ey güzel İstanbul

                              Seni ben de sevdim, ey güzel İstanbul

                              Bir şiir de benden sana, aziz İstanbul

                            

                              Denizlerle kol kola, sen ne güzelsin

                              Adalarla yan yana, ömre bedelsin

                              Aşığınla can cana gönüllerdesin

                              Sen güzeller güzeli bir şehirsin.

                              Boğazında gemiler, köşkler yalılar

                              Dilimizden düşmeyen yeşil korular

                              Tarihi öğretiyor, camilerle saraylar

                              Sende yaşanmıştır, en büyük aşklar.

                              Seni ben de sevdim, ey güzel İstanbul

                              Bir gönül de benden sana, aziz İstanbul.

                                                    Erol Güngör

 Erol Güngör', 'Seni ben de sevdim ey güzel İstanbul                               Seni ben de sevdim, ey güzel İstanbul                               Bir ş...', ARRAY['Türk Edebiyatı','Şiir','Beste Göksel Baktagir']::text[], 8.5, '{"poet":"Beste Göksel Baktagir","poet_slug":"beste-goksel-baktagir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-ben-de-sevdim-ey-guzel-istanbul-gaziantepli-sair-erol-gungor-siiri-beste-goksel-baktagir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-ayse-pehlivan-pw75l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kabuk tutmuş yaramı

Kanatıyor bu hayat

Dünkü kötü günümü

Aratıyor bu hayat

Duymak istemesem de

Anlatıyor bu hayat

Ölümü özleterek

Yaşatıyor bu hayat

Tam anladım diyorum

Şaşırtıyor bu hayat

Bir damlayken bardağım

Taşırtıyor bu hayat', 'Kabuk tutmuş yaramı Kanatıyor bu hayat Dünkü kötü günümü Aratıyor bu hayat Duymak istemesem de Anlatıyor bu hayat Ölümü özleterek Yaşatıyor ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Pehlivan']::text[], 8.5, '{"poet":"Ayşe Pehlivan","poet_slug":"ayse-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-253-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik', 'yitik-mevlut-ulugtekin-yilmaz-d9zaw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Türk Gençliğine''

Haydi tutun ellerimizden

Düşelim peşine yitiğimizin

Zümrüdüanka kanatlarıyla

Tez varalım Kafdağı’na

Ateş giysili ejderhalarla güreşelim

Doruklarda bulalım eski izimizi

Kurda kuşa Süleyman’ca soralım

Gaflet uykusunda yitirdiğimizi! 

Haydi tutun ellerimizden

Binelim rüzgârın kanatlarına

Yedi diyâr, yedi iklim aşalım

Akıl beşiğinde belediğimiz

Gökçek umutlarla höllük elediğimiz

Yitiğimize kavuşalım! 

Yakaları “dest-i takva ile” alanlar hey! ..

Göklere Semerkant’tan uzananlar hey! ..

Tez tutun ellerimizden

Yüzyıllar var ayrıyız yitiğimizden! 

Bu çağrı, kanı sebillerin çağrısı

Bu çağrı, alnı akların çağrısı

Dinsin artık kör zamanın ağrısı! 

Haydi tutun ellerimizden; 

Yaşanacak görkemler niyetine

“Yitik malı bulun! ”  diyen,

Kutlu buyruk hürmetine!', '''Türk Gençliğine'' Haydi tutun ellerimizden Düşelim peşine yitiğimizin Zümrüdüanka kanatlarıyla Tez varalım Kafdağı’na Ateş giysili ejderhala...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Uluğtekin Yılmaz']::text[], 8.5, '{"poet":"Mevlüt Uluğtekin Yılmaz","poet_slug":"mevlut-ulugtekin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yitik-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimin Kopan Telleri', 'yuregimin-kopan-telleri-dervise-guneyyeli-citvq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimin teline ince ince dokunur zaman

Bağlamanın huzurlu edası,

Tanburun yanık sesi, gitarın hoyrat çıkışları, 

Derken uyku vakti gelir.

Dışarıda yağmur, dışarıda rüzgâr, 

Fırtınayla göçer dallar ve yapraklar

Karşımda aşk-ı beşer, ellerimde nefis

Okşandıkça, kapanır gözler 

Uyku hali körlük verir ruhuma

Rüya hali işarettir dilime

Gönlüm kalksa yattığı yerden

Gerçeğe ulaşır mı sarınıp bedenime? 

                        -Bedenim uyanır mı gönülde

                         Gönlüm uyanır mı bedene-

Sarhoşluk haliyle yürüdüğüm yollar

Uzar gider eksilse de notalar

Anlamsız bakarım çoğalınca eksikler

Mana ne, gerçek ne, hatırlamam sorsalar

Dünyanın seyrine dalarken

Unuttuğum kopan tellerim kanar

Yüreğimde dört mevsimin sonu var

Geri gelmez giden nefes alışlar

-Ekim 2005-', 'Yüreğimin teline ince ince dokunur zaman Bağlamanın huzurlu edası, Tanburun yanık sesi, gitarın hoyrat çıkışları,  Derken uyku vakti gelir. ...', ARRAY['Türk Edebiyatı','Şiir','Dervişe Güneyyeli']::text[], 8.5, '{"poet":"Dervişe Güneyyeli","poet_slug":"dervise-guneyyeli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yuregimin-kopan-telleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerkük Güzeli', 'kerkuk-guzeli-mevlut-ulugtekin-yilmaz-0a2nb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gerilmiş yay kara kaşa

Men ürekten vurulmuşam

Çift hörüklü nazlı başa

Men ürekten vurulmuşam! 

Mahsun yüzde ince kirşan

Güzelliğin ülkeye şan

Hurmatı’da gördüm akşam

Men ürekten vurulmuşam! 

Canlar kurban sen dilbere

Bağrımı ez basma yere

Cepkeninde mor güllere

Men ürekten vurulmuşam! 

Gamzelerin özde yara

Di gel ceyran koyma dara

Halhal değen ayaklara

Men ürekten vurulmuşam! 

O büyülü gülüş kime? 

Çok naz etme bu Türkmen’e

Ak alında top perçeme

Men ürekten vurulmuşam! 

Hörük: Belik-Bölük saç

Kirşan: Pudra

Hurmatı: Kerkük yakınlarında mesire yeri', 'Gerilmiş yay kara kaşa Men ürekten vurulmuşam Çift hörüklü nazlı başa Men ürekten vurulmuşam!  Mahsun yüzde ince kirşan Güzelliğin ülkeye şa...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Uluğtekin Yılmaz']::text[], 8.5, '{"poet":"Mevlüt Uluğtekin Yılmaz","poet_slug":"mevlut-ulugtekin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kerkuk-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Güzel...', 'ey-guzel-alper-kuruk-bd7dc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey gözleri hayâlim kadar güzel kadın

Her bakışın bir başka umut vermekte bana,

İnsan için bir umut bir bağıdır hayatın

Hoş gördürmek nâfile hülyasız yaşayana.

Melek yapar çıkarsın bir bakışla beni sen

Şeytan şerrimden korkar,elimde sen istersen,

Ey gözleri hayâlim kadar özel kadın...', 'Ey gözleri hayâlim kadar güzel kadın Her bakışın bir başka umut vermekte bana, İnsan için bir umut bir bağıdır hayatın Hoş gördürmek nâfile ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ey-guzel-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mola', 'mola-humeyra-yilmaz-dr6m9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ölümle yarışıyorum ahir zamanda 

karanlığı şakağıma dayadım 

mat geçmişimi cilalıyorum 

göz yaşlarımla

bir a(v) cının okuyla

ikiye bölünüyor yüreğim

yine zamansız

ve yine 

ateş böcekleri düşüyor içime

yanıyorum

buna yanmak denirse...!', 'ölümle yarışıyorum ahir zamanda  karanlığı şakağıma dayadım  mat geçmişimi cilalıyorum  göz yaşlarımla bir a(v) cının okuyla ikiye bölünüyor...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mola-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Kasım', 'on-kasim-alper-kuruk-9u1se', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşen yapraktaki bu hüzün neden? 

Neden böyle boynu bükük Bayrağın? 

Gözlerdeki yaş gibi havadaki nem

Yine geldi On Kasım anlayacağın...

Ölünün büyüklüğünden ölüm bu kadar acı,

Bir insandı ki o başlarımızın tacı,

Öldüğü gerçek ama Türk''lerin inancı:

İsmiyle,eseriyle kalpte yaşatcağın

Tek örneğindir o,gönül bağlayacağın...', 'Düşen yapraktaki bu hüzün neden?  Neden böyle boynu bükük Bayrağın?  Gözlerdeki yaş gibi havadaki nem Yine geldi On Kasım anlayacağın... Ölü...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/on-kasim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Ve Diken', 'gul-ve-diken-alper-kuruk-0bmy8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülün güzelliği yalan,

Ne renk,koku ve katmerindendir.

Arzuları kamçılayan

Yasaklayıcı dikenindendir...', 'Gülün güzelliği yalan, Ne renk,koku ve katmerindendir. Arzuları kamçılayan Yasaklayıcı dikenindendir......', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gul-ve-diken-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geliyorum Bu Gece', 'sana-geliyorum-bu-gece-salim-erben-tu7lb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bensizliğin izi çizik çizik

Yüreğinde varken

Bu gecede uyuyamazsın

Buğulanır göz bebeklerin 

Beklerken ağlarsın belki de

Yokluğum hüzünlü olur benim

Bilirim bu gece üşürsün de 

Isınman için 

Güneşi değil beni bekle

Sana geliyorum bu gece

Bu dağları bir kez daha 

Terk ediyorum senin için

Uzak diye gelemediğin yerde 

Ben hala seni seviyorum 

Ve bu gece uyuyamazsın 

Bende uyuyamam 

Bütün heyecan üzerimde

Çünkü çok iyi biliyorum 

Sende heyecanlısın zalım sende', 'Bensizliğin izi çizik çizik Yüreğinde varken Bu gecede uyuyamazsın Buğulanır göz bebeklerin  Beklerken ağlarsın belki de Yokluğum hüzünlü ol...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sana-geliyorum-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk', 'dostluk-alper-kuruk-sbr3t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir dağ başı uykusunun mutluluğudur

Dostluğunda bulduğum huzur,

Böyle bir uykuda haşre kadar uyunur

Belki de bu mezarlıklarda bulunur...', 'Bir dağ başı uykusunun mutluluğudur Dostluğunda bulduğum huzur, Böyle bir uykuda haşre kadar uyunur Belki de bu mezarlıklarda bulunur......', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dostluk-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son İstek', 'son-i-stek-alper-kuruk-2w0eu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüme mahkûm olmuş suçlu gibi olsaydım

Söylemek isterdim ben,ismini son sözümde,

Yıllar öncesi birgün eğer seni bulsaydım

Ne hayata küserdim,ne de dünya gözümde...

Sen şimdi benim için yarım kalan şarkısın

Ben terkedilmiş âşık,gönülden öksüzüm de...', 'Ölüme mahkûm olmuş suçlu gibi olsaydım Söylemek isterdim ben,ismini son sözümde, Yıllar öncesi birgün eğer seni bulsaydım Ne hayata küserdim...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/son-istek-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine İyi Bak!', 'kendine-i-yi-bak-emin-akduman-b9y4p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bitti! 

Bitti bitmesine bu aşkta,

Toplanıp yüreğimden, gittin mi sanıyorsun? 

Hangi zamanda,saate baksam,

Hiç sensizliği göstermiyor ki! 

Aklımın her köşesinde, senden bir hatıra var.

Gözlerim, 

Baktığım aynalarda,senli zamanları arıyor. 

Kırık dökük umutlarıma, teselli oluyor.

Bana yürekten “Aşkım” dediğin günler.

Gittin! 

Sana yakışır bir biçimde, 

Onurluydu gidişin bile.

Git güzel gözlüm! 

“Yüreğinin götürdüğü yerlere git”

Bende kalmasın aklın.

Senden sonra değişmeye karar verdim.

Beni bilirsin.

Hani hiç yalan söylemezdim ya! 

Bu gün yüzlerce kez söyledim.

''-seni hiç sevmedim” diyorum

“-seni hiç özlemiyorum”

“-hiç aklıma gelmedin bugün mesela”

“-adını içimde defalarca anmadım”

“-üzülmedim yokluğuna, gidişine yanmadım.”

Kendine iyi bak bitanem! 

DOĞRULARIM KIRDIYSA SENİ

YALANLARIMLA ÖZÜR DİLİYORUM', 'Bitti!  Bitti bitmesine bu aşkta, Toplanıp yüreğimden, gittin mi sanıyorsun?  Hangi zamanda,saate baksam, Hiç sensizliği göstermiyor ki!  Ak...', ARRAY['Türk Edebiyatı','Şiir','Emin Akduman']::text[], 8.5, '{"poet":"Emin Akduman","poet_slug":"emin-akduman","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kendine-iyi-bak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapsan Kabulüm', 'ne-yapsan-kabulum-alper-kuruk-3hy9d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dua yerine geçer beddua etsen bana,

Sevinir,zevk duyarım,hergün zûlmetsen bana.

Dünyada kötülükler yeter ki senden gelsin,

Başkalarına çirkin,sen bana hep güzelsin...', 'Dua yerine geçer beddua etsen bana, Sevinir,zevk duyarım,hergün zûlmetsen bana. Dünyada kötülükler yeter ki senden gelsin, Başkalarına çirki...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-yapsan-kabulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimi Göreceksin', 'i-cimi-goreceksin-alper-kuruk-6ytlq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerime iyi bak

İçimi göreceksin,

Bu kapalı mâbede

Oradan gireceksin.

Yakarsan sen beni yak

Yine söndüreceksin,

Bir çiçek dünyasında

Sen başka bir çiçeksin...

Kendini bana bırak

Herşeyi bileceksin,

Bir hayâl rüyasında

Uçup,gezineceksin...', 'Gözlerime iyi bak İçimi göreceksin, Bu kapalı mâbede Oradan gireceksin. Yakarsan sen beni yak Yine söndüreceksin, Bir çiçek dünyasında Sen b...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icimi-goreceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla Ağlama', 'agla-aglama-cihan-kaya-pzjim', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlarsan ağlayamadığına

ağla ağlayarak geçen zamana

Ağla yetişir ağlayamadığına

çırpınır denizde ama

ağlayana ağlamak yanaşmaz

Ağla donansa yürek

yanar mı? kaçar mı? kurur mu? 

Ağla/ma için ağla

ama sen yine de ağlama

ağla kaplansa gönül

bir mahiyi ağlama', 'Ağlarsan ağlayamadığına ağla ağlayarak geçen zamana Ağla yetişir ağlayamadığına çırpınır denizde ama ağlayana ağlamak yanaşmaz Ağla donansa ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/agla-aglama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Bu...', 'kader-bu-alper-kuruk-mp9un', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Izdırap çekmek için yaratılmışsa insan

Bir tatlı ânı bile ürkek kalp ile yaşar,

Ona aittir ızdırap,onundur bütün hicran

Bir ancık yüzü gülse ardından kalbi ağlar...', 'Izdırap çekmek için yaratılmışsa insan Bir tatlı ânı bile ürkek kalp ile yaşar, Ona aittir ızdırap,onundur bütün hicran Bir ancık yüzü gülse...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kader-bu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertleri Sarhoş Yaptım Salıverdim Hüzünlerin Üstüne', 'dertleri-sarhos-yaptim-saliverdim-huzunlerin-ustune-ahmet-nural-ozturk-w4vv1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dertleri sarhoş yaptım

salıverdim hüzünlerin üstüne

koyu bir söyleşiye daldılar

kaç tan ağardı karanlığın üstüne 

ne dertler ayıldı

ne dağıldı hüzünler

ben de 

kızıştırmak için ortalığı

el ele tutuşturup

gurbet ile yalnızlığı katıverdim yanlarına

hasret durur mu hiç

hele gariplik üşüşüverdi yakalarına

böyle panel görülmemiştir

of anam of

yaşam bu işte

bir ahenk dolaşıyordu o ahenksizlikte

kaçırmamak için işte bu anı

ben de geçiverdim karşılarına

yasladım sırtımı yaşlı bir çınara

yaktım bir de cigara

tam gel keyfim gel diyecektim ki o ara

dumanlar içinden efkar çıka geldi

kısmet işte 

o da düştü benim başıma

anam çok demişti oğlum gülme komşuna...', 'dertleri sarhoş yaptım salıverdim hüzünlerin üstüne koyu bir söyleşiye daldılar kaç tan ağardı karanlığın üstüne  ne dertler ayıldı ne dağıl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dertleri-sarhos-yaptim-saliverdim-huzunlerin-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saadet Katili', 'saadet-katili-alper-kuruk-hhzap', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neş''esiz,renksiz kuru dallarımla

Saadeti ağacıma konduramadım,

Saadeti aradım kör ellerimle

Boğazına geçti tırnaklarım.

Ben saadet katili

Ben kendime karşı suçlu,

Ben günahkâr,zehirli yem

Saadet bana oruçlu.

Saadeti aradım kör ellerimle

Boğazına geçti tırnaklarım...', 'Neş''esiz,renksiz kuru dallarımla Saadeti ağacıma konduramadım, Saadeti aradım kör ellerimle Boğazına geçti tırnaklarım. Ben saadet katili Be...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/saadet-katili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toplantı', 'toplanti-alper-kuruk-x98y5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsan gözünü bir kere 

Dünyaya açmaya görsün

Bakar ilk topluluk nazarıyla

Doğumevinde 

Yolunu bekleyenlere.

Artık arkası gelir toplantıların...

Ta ölünceye kadar

Hatta daha da uzar.

Dünyadaki toplantılar bir yana 

Saymakla tükenmez:

Doğumda,düğünde,ölümde...

Fakat âlem değişir değişmez

Başlar bir son toplantı 

Ki kâinat içinde...', 'İnsan gözünü bir kere  Dünyaya açmaya görsün Bakar ilk topluluk nazarıyla Doğumevinde  Yolunu bekleyenlere. Artık arkası gelir toplantıların...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/toplanti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapılar', 'kapilar-alper-kuruk-k8syq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapılar da azap çeker 

Tıpkı insanlar gibi.

Açılıp kapanırken 

Çıkardığı o sesler

Azabının sesleri.

Kimi kapanmış iyice

Dünyasından bıkıp

İçine kapanan insanlar misâli.

Kimi gerilmiş gerildikçe

Gelsin,geçsin diyor ahâli.

Kimi Devlet kapısı 

Başında boy boy memurlar,

Kimi han kapısı

Önünde gurbetçi yolcular.

Bu kapı,şu kapı

Hepsi insan yapısı,

Dilerim açık olsun 

Her an ''Hâcet Kapısı ''...', 'Kapılar da azap çeker  Tıpkı insanlar gibi. Açılıp kapanırken  Çıkardığı o sesler Azabının sesleri. Kimi kapanmış iyice Dünyasından bıkıp İç...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kapilar-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk Dönemi-İçlerinden Biri', 'cocukluk-donemi-i-clerinden-biri-ulug-celik-y5riw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ÇOCUKLUK DÖNEMİ-İÇLERİNDEN BİRİ

Çocuklarınız sizin çocuklarınız değil,

Yaşam''ın kendisini özleyişinin

     kız ve erkek evlatlarıdır.

Sizinaracılığızla dünyaya geldiler.

    ama sizden gelmediler.

Yanınızda olmalarına karşın,

    sizin malınız değil onlar.

Onlara sevginizi verebilir

    oysa düşüncelerinizi veremezsiniz; 

    Çünkü kendi düşünceleri var.

Eviniz onların bedenlerine barınak olabilir,

    ama ruhların barınağı olamaz; 

    Çünkü onların ruhları yarının evinde yaşar-

    Ve siz bu evlere konuk olamazsınız,

    düşlerinizde bile.

Onlar gibi olmak için büyük çaba harcayabilirsiniz,

   ama onların sizin gibi olmasını istemeyin; 

   çünkü yaşam ne geriye gider

  ne de oyalanır dünün olaylarıyla

                       K.G.', 'ÇOCUKLUK DÖNEMİ-İÇLERİNDEN BİRİ Çocuklarınız sizin çocuklarınız değil, Yaşam''ın kendisini özleyişinin      kız ve erkek evlatlarıdır. Sizina...', ARRAY['Türk Edebiyatı','Şiir','Uluğ Çelik']::text[], 8.5, '{"poet":"Uluğ Çelik","poet_slug":"ulug-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cocukluk-donemi-iclerinden-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-gunduz-aydin-s4hxx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin şirin hallerin

Senin tatlı dillerin

Kokuların, güllerin

Hâlâ duruyor Babam

Gözlerde akan yaşlar

Sevenler, arkadaşlar

Kaldırımdaki taşlar

Seni soruyor Babam

Torunların yollarda

Kuşlar bekler dallarda

Hatıralar kollarda

Seni arıyor Babam

Bulutlar arasında

Anneciğim yasında

Rüyalar, ortasında

Seni görüyor Babam

Seni ata-can bilmiş

Mübarek terin silmiş

Gelinin-kızın gelmiş

Sofra kuruyor Babam

Bu gece rüyamdasın

Bitecek artık yasın

Yumşacık, ince sesin

Bana varıyor Babam

Gözlerim yaşla doldu

Hayâlin uykum böldü

Hasretin dağlar oldu

Beni yoruyor Babam

Seni sorar her yerde

Benim gülüm nerlerde

Gündüzün resimlerde

Saçın tarıyor Babam

Saçın tarıyor Babam', 'Senin şirin hallerin Senin tatlı dillerin Kokuların, güllerin Hâlâ duruyor Babam Gözlerde akan yaşlar Sevenler, arkadaşlar Kaldırımdaki taşl...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/babam-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-gunduz-aydin-3ml0b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağların doruklarında

          ıtırlar kokularını

              saçlarından almış.

Rüzgarlar kokunu

         uykusuz sabahlarda

               yorgun gözlerime 

                                  salmış.

Zavallı gözlerim

          her gelen günde

                soluk güneşlerin

                      ışığıyla yanmış.

Seni sevmeseydim

         hasretin olmasaydı içimde

               nasıl olurdu bilemiyorum? 

                    bir kere daha anladım

                              dünya yalanmış.', 'Dağların doruklarında           ıtırlar kokularını               saçlarından almış. Rüzgarlar kokunu          uykusuz sabahlarda            ...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalan-171-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koltuk Sevdası', 'koltuk-sevdasi-i-lhan-kirbac-lf0vv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani evlerde vardır ya,

Renk renk, desen desen,

O marka,bu marka koltuklar.

Onlardan bahsetmiyorum.

Bir de makam koltukları vardır,

Dönerli, yaylı,en has deriden.

Nedendir bilinmez bir oturan,

Bir daha kalkmak istemez.

Ele geçirmek için o koltuğu,

Uğruna neleri feda etmezler,

Yukarıdakilere ne taklalar atarlar,

Ne sinsi planlar,ne tuzaklar kurarlar.

Ne cambazlıklar,ne dümenler,

Maskeler hazırlanır,iktidara göre.

Bizans oyunlarına taş çıkartırlar,

Bir ipte birden çok cambaz.

Oysa dostlarını,arkadaşlarını,

Ve dahası haysiyetlerini kaybederler.

Ve otururlar da o koltuklara,

Olurlar birer kukla.

Allahım,o koltuklara,

Layık olanları oturt.

Oturt da, biz de rahat edelim,

O güzelim koltuklar da...', 'Hani evlerde vardır ya, Renk renk, desen desen, O marka,bu marka koltuklar. Onlardan bahsetmiyorum. Bir de makam koltukları vardır, Dönerli,...', ARRAY['Türk Edebiyatı','Şiir','İlhan Kırbaç']::text[], 8.5, '{"poet":"İlhan Kırbaç","poet_slug":"i-lhan-kirbac","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/koltuk-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diye', 'diye-nazan-i-zmirli-4b25z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'özlemlerimi...........

bulutlara yükledim.

yağmur olup.................

tenide değen....................

her damlacıkta.......................

beni hatırla.................................

diye....................................................

Nazan İzmirli-2.10.2005-antalya', 'özlemlerimi........... bulutlara yükledim. yağmur olup................. tenide değen.................... her damlacıkta........................', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/diye-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Yaşıyorum', 'seninle-yasiyorum-esat-anik-um27z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmezsin neler çektim,bu ayrılık yüzünden.

Hasretini yıllardır içimde taşıyorum.

Dertlere aşinayım,her mihnete alışık; 

Bu şifasız yarayı,bilerek kaşıyorum.

Gurbete boyun eğdim; Kaderde var diyerek.

Hep kandırdım kendimi,bekliyor yar diyerek.

Bizler ayrıyız ama,gönlümüz bir diyerek; 

Sensiz nasıl yaşadım? Vallahi şaşıyorum.

Hayallerin,hatıran; Dermanım oldu belki.

Bir gün sana kavuşmak,fermanım oldu belki.

Mecnun,Ferhat ve Kerem; Hayranım oldu belki,

Bu sabır yoktu bende,kendimi aşıyorum.

Vefaya güvenirdim,''Benden bıkamaz'' derdim.

Aşkımın kalesini,''Ölüm yıkamaz'' derdim.

Senin özlemin varken,''Ateş yakamaz'' derdim; 

En hazin ayrılığı seninle yaşıyorum.

Esat ANIK', 'Bilmezsin neler çektim,bu ayrılık yüzünden. Hasretini yıllardır içimde taşıyorum. Dertlere aşinayım,her mihnete alışık;  Bu şifasız yarayı,b...', ARRAY['Türk Edebiyatı','Şiir','Esat Anık']::text[], 8.5, '{"poet":"Esat Anık","poet_slug":"esat-anik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seninle-yasiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklar', 'asiklar-alper-kuruk-2bvk0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çağ çatıp aşka tutulanlar

Arzunun ateşiyle yanarmış,

Ruhunda birgün isyanı duyanlar

Sızlanarak yine cânanı anarmış.

Masallar gibi başlayıp biten

Bir varmış...bir yokmuş...insan oğlu

Bir de ah şu aşk varmış...

Ki onunla tutuşup yandı gönlüm

İtirafı bile dilimi yakar,

Nice nice âşıklar  gördüm

Bencileyin hepsi de ağlar...', 'Çağ çatıp aşka tutulanlar Arzunun ateşiyle yanarmış, Ruhunda birgün isyanı duyanlar Sızlanarak yine cânanı anarmış. Masallar gibi başlayıp b...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/asiklar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirim Bekle beni', 'gelirim-bekle-beni-gunduz-aydin-8iz94', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece vakitte, bendim gelen sessizce

Karanlık uykunu, bendim çalan gizlice

Üşüyen gözyaşını, bendim silen bu gece

           Yarın gece yeniden, gelirim bekle beni

           Bu yorgun yüreğimi, koynunda sakla e mi

Rüzgâr değil o sesler, kalbimin atışları

Gözlerimin bekçisi daktilomun tuşları

Yağmur mu sanıyorsun? ! ... Duyduğun gözyaşları.

           O köşede bekle can, gelirim bekle beni

           Bu yorgun yüreğimi, koynunda sakla e mi

Telefon değil çalan, kapın zili duysana

Ben geldim, geldim işte, tık tıkları saysana

Herkes gibi olsan can, herkeslere uysana

           Yumma sakın gözlerin, gelirim bekle beni

           Bu yorgun yüreğimi, koynunda sakla e mi

Sıcaklığın bendendir, bacanda tüten benim

Heyecanın unutma, içinde atan benim

Dönsene sol yanına, yanında yatan benim

           Çık pencere önüne, gelirim bekle beni

           Bu yorgun yüreğimi, koynunda sakla e mi

Söylesene; pişmansın, bırakıp gittiğine

Pişmansın, biliyorum, eziyet ettiğine

Sevgim; yanıbaşında, uzatsan kolun yine

           Yine sana gelirim, gelirim bekle beni

           Bu yorgun yüreğimi, koynunda sakla e mi

Rüya diyorsun sen, ben gerçeğim yanında

Niye yarar ki gülüm, pişman olmak sonunda

Sana gelirim, sana, her hüzünlü gününde

           Her gece geç vakitte, gelirim bekle beni

           Bu yorgun yüreğimi, koynunda sakla e mi', 'Bu gece vakitte, bendim gelen sessizce Karanlık uykunu, bendim çalan gizlice Üşüyen gözyaşını, bendim silen bu gece            Yarın gece ye...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gelirim-bekle-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Geldin', 'sen-geldin-gunduz-aydin-lylkd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen geldin,

Ufuklarda martıların siluetleri belirdi

Rıhtıma yaklaşan vapurlardan

Sevgililer indi bekleyenlerin kucaklarına

Bir çiğ tanesi düştü yanaklarımdan

Her taraf yeşerdi...

Güller açtı gözlerin bebeklerinde

Kahrolası ayaz bir daha hiç uğramadı bize

Ne deyim; beklediğime değdi

Sabahın ilk ışıkları ile içim ısındı

Çam kokulu ellerini tuttum ya! 

Artık ölsem de gam yemem.

Itırların, kekiklerin dağ kokuyor şimdi.

Sen geldin,

Nazlarını bıraktın da geldin

Bir daha gitmeyesiye geldin...

Hani mektuplarda martıları yazmıştım sana

Gözyaşlarımın sararttığı mektuplarda

Onlarla birlikte hasret şarkıları söylerdik

Bir gün,

Martılar beklemekten yoruldu

Uzaklara gitti, çok uzaklara

Ben hiç yorulmadım, bıkmadım

Hep seni bekledim.

Beklediğime değdi; 

Sen geldin...

Kumsala uzanmış umutlarımın üzerine

Başımı dayadım, yorgun ve mutlu...

Eskisi gibi meltem rüzgarlarında

Ne de güzel savruluyor saçların

Saçların özgür, saçların altın sarısı

Gözlerin ne kadar kararlı, ela gözlerin

Her şeyini sevdim senin

Ama o duruşunu en çok sevdim.

Ateş sarısı saçlarında üşüyen ellerim

Nazlarında ısındı...

Yıllar sonra sen geldin; 

Yokluğunda sevginin ne olduğunu öğrendim

Yokluğunda hasreti, ayrılığı tattım

Yokluğunda ıslak gözlerim hep seninle oldu

Açıldı; hayâllerim seninle

Kapandı; rüyalarım seninle

Aşım, ekmeğim, havam ve suyum

Biliyor musun kalbim hep seninle.

İyi ki geldin; 

Tam umudumun bitmeye yüz tuttuğu anda

Baharla birlikte sen de geldin

Gelirsin diye yıllardır açık kalan kapım

Gelirsin diye penceremde bekleyen kumrular

Gelirsin diye hiç solmayan dağ kokuları

Çok sevindiler,

Ben de çok sevindim...

Hayâllerimde taradığım saçların

Şimdi ellerime can olacak,

Seni öylesine çok bekledim ki; 

Itırlar saçın kokusu oldular

Rüzgârlar gözlerimde kaldılar

Kuru otlar yüreğimde yandılar

Seni öylesine çok özledim ki; 

Martıların çığlıklarında ben vardım

Yalın ayak aşıkların hıçkırıklarında ben,

Senin olmadığın yıllarda

Bana umut olan dağ kokularına minnettarım

Gece nöbetlerimde yalnız bırakmayan

Martılara minnettarım

En güzel şarkıları senin için söylemiştik.

Sen geldin

İyi ki geldin...

Gir koluma,

Dağların zirvelerinde, bulutlara yakın

Yeni bir dünya kuralım, ikimiz

Yeni bir dünya kuralım tertemiz

Saçların sarsın gözlerimi

Ellerin dolansın boynuma

Gözlerin bir karış gözlerimde

Dünyanın bütün kuşları şarkımızı söylesin

Bütün çiçekleri taç olsun saçlarına

Sen geldin; 

Kahrolası bekleme kapım önünde

Biliyorum geldin işte, sen geldin; 

Açık olan kapımdan gir gönlüme

Girsene, nolursun girsene

Bana ayrılan vakit bitiyor

Geldin işte

Sen geldin

Biliyorum sen geldin...', 'Sen geldin, Ufuklarda martıların siluetleri belirdi Rıhtıma yaklaşan vapurlardan Sevgililer indi bekleyenlerin kucaklarına Bir çiğ tanesi dü...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/sen-geldin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoktan...', 'coktan-alper-kuruk-ic2m2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biz evlenmesek de sevgilim ne çıkar? 

Ruhlarımız düğün-dernek yaptı çoktan...

Gönüllerimiz bir oldu

Aşkı yaratıverdi yoktan.

Biz gülmesek de sevgilim

Göz yaşımız kurudu çoktan...

Bir de kurtulsaydı gönlümüz

Hasret denilen oktan.

Biz ağlasak da sevgilim ne çıkar? 

Delice âşıkız çünkü Hak''tan,

Gülen göz bizde de bizde de var...

Aman yok ki ayrı yaşamaktan.', 'Biz evlenmesek de sevgilim ne çıkar?  Ruhlarımız düğün-dernek yaptı çoktan... Gönüllerimiz bir oldu Aşkı yaratıverdi yoktan. Biz gülmesek de...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/coktan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Ben mi Sevdim', 'bir-tek-ben-mi-sevdim-gunduz-aydin-vnusk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir tek ben mi sevdim, seni güzelim

Solduğun ellerin bakışlarından 

Saçındaki aklar hazan rüzgarı

Bir tek ben mi sevdim, seni güzelim.

Baktım ki eller de, sıcacık sarmış,

Baktım ki eller de, hayaller kurmuş,

Seherde saçların, hep eller örmüş,

Bir tek ben mi sevdim, seni güzelim.

Nazımı çekenler sırada bekler,

Kelebekler konmuş, saçını koklar,

Dağlarda ıtırlar kokunu saklar,

Bir tek ben mi sevdim, seni güzelim.

Şafaklar yorulmuş, geceler dargın,

Üç-beş nöbetinde, martılar yorgun,

Çiçekler sararmış, hep sana kırgın,

Bir tek ben mi sevdim, seni güzelim.

Saçına ak düşmüş, gözlerin fersiz,

Kalbimi çalan o, o eller hırsız,

Şiirlerim garip, şiirler yârsız,

Bir tek ben mi sevdim, seni güzelim.

Seni saran eller, günah işlemiş,

Yıllar sonra sende, hasret başlamış,

Sana köle olan, artık boşlamış,

Bir tek ben mi sevdim, seni güzelim.

Bekleme gelemem, ben de yorgunum,

Kapat pencereni, sana dargınım,

Sensiz geçmez idi, sensiz bir günüm,

Bir tek ben mi sevdim, seni güzelim.

Herkes sevdi seni, ben de çok sevdim,

Yıllarımı çaldın, hiç sevmeseydim,

Kadere yıllardır, boynumu eğdim, 

Bir tek ben mi sevdim, seni güzelim.

Göçmen kuşlar bile, hayrandı sana,

Candın eskiden sen, candın bu cânâ,

Nazların yığınla, düne baksana,

Bir tek ben mi sevdim, seni güzelim

Yollar sevdi seni; ağaçlar, kuşlar,

Görmedin mi sana, çevrili başlar,

Sana doğru akar, gözlerde yaşlar,

Bir tek ben mi sevdim, seni güzelim.

“Sevginle ne hale, düştüm” diyorsun,

Yıllar sonra gelip, “şaştım” diyorsun,

Çok geçti, sen beni anlamıyorsun,

Bir tek ben mi sevdim, seni güzelim.

Sevmekle saçlara, ak mı düşermiş? 

Hasreti yenmeyi, kimler başarmış? 

Kalbinde ne de çok “ben”ler yaşarmış,

Bir tek ben mi sevdim, seni güzelim.

Dönüp bakma artık, gözlerim ona,

Ne de çok bağlanmış, yüreğim sana,

Ben de çok yorgunum beni suçlama,

Bir tek ben mi sevdim, seni güzelim.

Kader bizi ayrı yollara atmış,

Uzaktan uzağa, sevgimiz bitmiş,

Senle sevdiğimiz herşeyler gitmiş,

Bir tek ben mi sevdim, seni güzelim.', 'Bir tek ben mi sevdim, seni güzelim Solduğun ellerin bakışlarından  Saçındaki aklar hazan rüzgarı Bir tek ben mi sevdim, seni güzelim. Baktı...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/bir-tek-ben-mi-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyuyormusun-1', 'duyuyormusun-1-nazan-i-zmirli-gzkiy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dolunayda  işlerim  seni,

yakomazlara  şiir   gibi

ıslak saçlarımı okşayan rüzgarla,

dalgalarla   sevişen     martıların

kanatlarında..............

özlem  çığlıklarım  var

duyuyormusun...............................

Nazan İzmirli-06.05.2005-antalya', 'dolunayda  işlerim  seni, yakomazlara  şiir   gibi ıslak saçlarımı okşayan rüzgarla, dalgalarla   sevişen     martıların kanatlarında..........', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/duyuyormusun-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Yüzlüm', 'ay-yuzlum-gunduz-aydin-eorbh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gelseydin sıcacık, sesinle uyanırdım

Hep gelmedin, günlerim; zehir oldu ay yüzlüm

Yıkılmazdım böylece, hep sana dayanırdım

Dalıp giden gözlerim; yaşla doldu ay yüzlüm

Çile bitti, dert bitti; aslında dağlar bitti

Gün değil, mevsim değil; uzunca çağlar bitti

Umutlarım küstü de, beni bırakıp gitti

Umutlarım saksıda, çoktan soldu ay yüzlüm

Beklemenin adına “çile” dediler birgün

Bu beden, o güzele “köle” dediler o gün

Yolculuk uzun sürdü “mola” verdiler son gün

Hüzünler kırış kırış, bana geldi ay yüzlüm

Herşey yalanmış meğer, sen de yalansın, yalan

Bir tutam hüzün şimdi, sevgiden bana kalan

Sen de yalansın artık, git nazınla oyalan

Gecenin sessizliği, uykum böldü ay yüzlüm

Vakit çok geç, geç kaldım; ulaşmak sana uzak

Senin duruşun bilsen; yollarda bana tuzak

Yine de olmaz yine, o geçmişi unutsak

Güzelliğin kaybolmuş, sana noldu ay yüzlüm', 'Sen gelseydin sıcacık, sesinle uyanırdım Hep gelmedin, günlerim; zehir oldu ay yüzlüm Yıkılmazdım böylece, hep sana dayanırdım Dalıp giden g...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ay-yuzlum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık', 'karanlik-gunduz-aydin-2vnap', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece noktayı koydu, zamanın bir yerinde

Saatin tiktakları seni arıyor Leyla

Yıldızlar toplanmışlar, meraklı sorularda

Uzanıp bana kadar, seni soruyor Leylâ

Çok şey değişti bilsen, saçlara aklar düştü

Yandı gözlerin yandı, gözlere oklar düştü

Seni ararken her an, önüme yoklar düştü

Bıraktığın gibi can, öyle duruyor Leylâ

Rüzgâr gelse esse de, saçlarımı dağıtsa

Sen gelsen bahar ile, özlemlerim bir bitse

Çekilen bunca acı, yetse diyorum yetse

Sensizlik-sessizlikle, beni yoruyor Leylâ

Gecelerde bir inat, sardı beni gitmiyor

Yıldızlar alay eder, ellerimi tutmuyor

Ay şavkında söylenen, şarkılar avutmuyor

Bu gönlüm başkasını, hayal kuruyor Leylâ

Şimdi ne yapıyor o, alay eden gözlerin

Karanlıkta göremem, duruyor mu nazların

Uzat bir yol, uzat da, nasıl nasıl sözlerin

Görmez misin tellerim, sana varıyor Leylâ

Alo desen, gelmesen, gelme gülüm, gelme sen

Hâlâ seni yıllardır, sevdiğimi bilmesen

Bana ait izleri, bir kalemde silmesen

Hatıralar öylece, beni sarıyor Leylâ.', 'Gece noktayı koydu, zamanın bir yerinde Saatin tiktakları seni arıyor Leyla Yıldızlar toplanmışlar, meraklı sorularda Uzanıp bana kadar, sen...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/karanlik-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Leyla', 'yine-leyla-gunduz-aydin-vw0le', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu şafağın sonunda, şu köşede, şu uçta

Sen varsın, sen varsın hep; bilir misin sen Leylâ

Pınarda akan sensin, içilen her avuçta

Kapım açık beklerim, gelir misin sen Leylâ

  

 Martılar seni söyler, çiçekler senli kokar

Çiğdemler güne değil, sevgine doğru bakar

Sensizlik gündüzlere, kara bulutça çöker

Bir yudum hasret sunsam, alır mısın sen Leylâ

Gözlerim hiç uslanmaz, gelir diye hep bekler

Boynu bükük ve garip, vazolarda çiçekler

Boşa çıkıyor hep, tutulan o dilekler

Yıllar sonra benimle, kalır mısın sen Leylâ

Biliyorum beklemek, hayallerde bile zor

Çekilen bunca zor’u, bir gözlerim biliyor

Her gelen hasret yeli, hep yanımda kalıyor

Gözlerimi yakan yel, olur musun sen Leylâ', 'Şu şafağın sonunda, şu köşede, şu uçta Sen varsın, sen varsın hep; bilir misin sen Leylâ Pınarda akan sensin, içilen her avuçta Kapım açık b...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yine-leyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla', 'leyla-gunduz-aydin-njd3o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çiçekler  bak  ağlıyor,  bahar  mı  geldi  ne 

Bir  doğrulsam,  doğrulsam, uzansam  ellerine 

Koluna  girsem gülüm, seninle  olsam  yine 

Leylâ... Ah  Leylâ, Leylâ... Bitmez, bitmez  hasretim 

Her  seherde uyanık; seni, seni  beklerim 

Bayram  mı  geldi yine, gözlerde  yaş  duruyor 

Ben  bayramı  unuttum, gönlüm  gönlüm  soruyor 

Ne  uslanmaz  şu  gözler, senli  hayal  kuruyor

Leylâ... Ah  Leylâ, Leylâ...Gelmez  oldu  bu  bahar

Gözlerime  bak  gülüm, senli çokça  sırlar  var 

Özlemiştim  can  seni, senin  kolların  var  mı? 

Serap, serap  hep serap...Sen  mi  geldin  bahar  mı? 

Yem  verdiğim  can  kumru, gizli  gizli  ağlar  mı? 

Leylâ... Ah  Leylâ, Leylâ... Kavuşmak  sana  uzak 

Eskisi  gibi  yine, yine  birlikte  olsak 

Bak  dizlerim  tutmuyor,  nerdesin  sen  nerdesin 

Şu  ışıkta,  şu  seste, gizemli  bir  yerdesin 

Çık  artık,  çık  diyorum; biliyorum  ordasın 

Leylâ... Ah  Leylâ, Leylâ... Dizde  derman  kalmadı 

Uzadıkça  erir can, olmadı  hey  olmadı 

Sevmiyorum  şafağı,  şafakta  annem  ağlar 

Çölde  kaldı  gözyaşım,  eridi  sensiz  dağlar 

O  gözler  ki, o  gözler... Dünü  bugüne  bağlar 

Leylâ... Ah Leylâ, Leylâ... Sen  gideli  yorgunum 

Yalnız  bıraktın  beni, sana  sana  dargınım 

Dargınım  çokça  sana, bırakıp gittin  gülüm 

Dönüp  ardıma  bakıp, sarılmak ister  gönlüm 

Aramızda  bir  çizgi, “ güzel “ denilen  ölüm 

Leylâ... Ah  Leylâ, Leylâ... Rüyama  gir  bu  gece

Sensizlik  ilahî  sır, sensizlik  bir  bilmece', 'Çiçekler  bak  ağlıyor,  bahar  mı  geldi  ne  Bir  doğrulsam,  doğrulsam, uzansam  ellerine  Koluna  girsem gülüm, seninle  olsam  yine  Le...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/leyla-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-gunduz-aydin-ww5ou', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uyandım  uykudan, sana sarıldım 

Sen  bu  cana ilaç, olsana Leyla 

Yılların  verdiği, dertle  yoruldum 

Yorulan  gönlüme,  dolsana Leyla 

Rüya  mı gördüğüm, hayâl  mi  dersin 

O  gönül  de  n’olur, bir  beni  sevsin 

Varsın  şiirlerim,  hep  seni  övsün 

Bu  gece  mehtapta, kalsana  Leyla 

Mehtapta  ay  yorgun, bekler  uyumaz 

Bekler  de  sevdiğin, sana  kıyamaz 

Çiçekler  uykuda, seni  duyamaz 

Şafakta  gizlice,  gelsene  Leyla 

Mayısta  bahara,  sitemlerim var 

Gelmezmiş  bu  bahar,  şiirler  ağlar 

Aşılmaz  bir  türlü,  her  yan  dört  duvar

Sevdiğin  ne  halde,  bilsene  Leyla', 'Uyandım  uykudan, sana sarıldım  Sen  bu  cana ilaç, olsana Leyla  Yılların  verdiği, dertle  yoruldum  Yorulan  gönlüme,  dolsana Leyla  Rü...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sitem-197-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tezkere Havası', 'tezkere-havasi-gunduz-aydin-wdcqr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden midir yârim, coşmakta gönlüm

Şiirlerim nakış nakış uzuyor

Sabırsız taşıyor, koşmakta gönlüm

Kalemim hep seni, seni yazıyor

Ne güzel ne güzel senli hayâller

Nasıldır haber ver, bensiz o eller

Günlerce hasretle esen bu yeller

Sevinç dolu bana doğru tozuyor

Çok da zormuş güne günler eklemek

Ne de güzel sabır gülü koklamak

Uzaklarda gurbet günü beklemek

Yüreğime hasret hasret sızıyor

Asker tezkeresi birgün dolar da

Gözler uzar gider, bitmez yollarda

Zaten bir orada, gönül bir burda

Kâh senli kâh sensiz durmaz geziyor', 'Senden midir yârim, coşmakta gönlüm Şiirlerim nakış nakış uzuyor Sabırsız taşıyor, koşmakta gönlüm Kalemim hep seni, seni yazıyor Ne güzel n...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tezkere-havasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Mektubu', 'gurbet-mektubu-gunduz-aydin-klw4d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ak başlı dağlara duman bürümüş

Gurbetlik çekilmez sırmış be anam

Sana gelen yollar kucak açmıyor

Çileler gönlümü sarmış be anam

Gurbet derdi çeke çeke yoruldum

Dün coşkun sel idim, bugün duruldum

Sabır denen nazlı güle sarıldım

Gül derdini çekmek zormuş be anam

Yolun incesinden geçemez oldum

Günler oldu kara sevdayla doldum

Ekmeğin-aşın yok sarardım soldum

Örümcek ağını örmüş be anam

Dört yanımda dağlar bırakmaz oldu

Kurudu pınarım bir akmaz oldu

Ne de çok üşürüm kor yakmaz oldu

Sensiz dünya bana darmış be anam

Duruldu denizim ayrı kalalı

Yanaklar karardı, gayrı yok alı

Mektupla haberin bana geleli

Bu gurbet ne güzel yermiş be anam

Geçer elbet gurbet, bu böyle gitmez

Şefkatin, gayretin, sevgin hiç bitmez

Gündüz’ün seni hiç kalbinden atmaz

Sıcaklığın kalbe girmiş be anam', 'Ak başlı dağlara duman bürümüş Gurbetlik çekilmez sırmış be anam Sana gelen yollar kucak açmıyor Çileler gönlümü sarmış be anam Gurbet derdi...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gurbet-mektubu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Özledim', 'cok-ozledim-gunduz-aydin-d1u7l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnanmazsan gel de bir bak halime

Yemin olsun çok özledim ben seni

Sana ait hatıralar taptaze

Yemin olsun çok özledim ben seni

Sabah akşam, kapım açık bekledim

Siyah beyaz resimlerin sakladım

Saçın sanıp, çiçekleri kokladım

Yemin olsun çok özledim ben seni

Itır kokan gerdanında kaldım ben

İnan gülüm, hasretinle soldum ben

Bir tek seni, sevdiceğim bildim ben

Yemin olsun çok özledim ben seni

Artık sevdam dağlar oldu yığıldı

Özlemlerim paramparça dağıldı

Gel, dizlerim yere kadar eğildi

Yemin olsun çok özledim ben seni

Şu rıhtımda, şu köşede, şu yolda

Şu sarıda, şu mavide, şu alda

Çık karşıma apansızın bir gel de

Yemin olsun çok özledim ben seni

Gelmem deme, sakın deme, küserim

Sonra canım, suratımı asarım

Sen yaşarsan, ben de senle yaşarım

Yemin olsun çok özledim ben seni

Bildim artık, çabalarım boşuna

Girmem desem yalan olur düşüne

Bir baksana şu gözlerin yaşına

Yemin olsun çok özledim ben seni

İnanmazsan gel de bir bak halime

Anlatır mı bir bak bunu kelime

Uzat nolur ellerini elime

Yemin olsun çok özledim ben seni', 'İnanmazsan gel de bir bak halime Yemin olsun çok özledim ben seni Sana ait hatıralar taptaze Yemin olsun çok özledim ben seni Sabah akşam, k...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cok-ozledim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Sonra', 'yillar-sonra-gunduz-aydin-sus0t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu güzellik nerdeydi, yıllardır ben hasretim

Susadım, gözyaşlarım, hep canıma akıyor

Gittiğin günden beri, sevgiler sensiz yetim

Gittiğin günden beri, yıllar hasret ekiyor.

Bir baktım; karşımdasın, benim gözlerim bitmiş

Güzelliğin duruyor, benim yıllarım gitmiş

Nazların parça parça, beni öteye atmış

Gözlerim yaş yerine, seni seni döküyor.

Artık çıkma karşıma; dayanamam, kıyamam

Ne kadar da kızsam da, sevmiyorum diyemem

Sevmesem de ''gözleri'' kavlimiz var cayamam

Saçlarının rüzgârı, yüreğimi yakıyor.

Saçlarında papatya, ellerin gül kurusu

Gözbebeğin menekşe, yüzün leylak sarısı

“Nasılsın'' deme bana, soru ahret sorusu

Yoruldum, çok yoruldum, güller senli kokuyor.

Bitti artık,yorgunum; bu sevda burda bitti.

Umutlarım isyanda, alıp başını gitti

Sen mi geldin bu sabah, yıllar beni terketti

Yıllar sonra gözlerin, bana nasıl bakıyor.

Sen tükettin sevdayı, yeniden başlamak zor

Sensin şimdi saçların, içimdeki yanan kor

Şiirlerim zamansız, baktım el''i seviyor

Fallar baktım sen yoksun, yollar nere çıkıyor?', 'Bu güzellik nerdeydi, yıllardır ben hasretim Susadım, gözyaşlarım, hep canıma akıyor Gittiğin günden beri, sevgiler sensiz yetim Gittiğin gü...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yillar-sonra-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lâle', 'l-le-gunduz-aydin-43qsv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen  lâlesin, kırılırsın, elimde

Uzakta dur, gelme artık, yanıma

Hep seveyim, gözlerini, hasretle

Can katarsın, can çekişen, canıma

Ah be güzel, nerdeydin sen, yıllardır

Şu gönlümde, senden başka, kim vardır? 

İşte geldin, işte bugün, bahardır

Can kattın sen, can çekişen, canıma

Baktım lâlem, boynun bükmüş, sararmış

Mevsim bitmiş, günler çoktan, kararmış

Yıllar sonra, nazlım beni, ararmış

Can kattın sen, can çekişen, canıma

Hayâl mi bu, gerçek nedir, nasıldır? 

Dünya yalan, yaşadığım, asıl''dır

Söylediğim, senli birkaç, fasıldır

Can kattın sen, can çekişen, canıma

Kapat gözün, yanağından, öpeyim

Çok özledim, başka sana, ne deyim

Bir işaret, çağır hemen, geleyim

Can kattın sen, can çekişen, canıma

Nefes almak, sensiz inan, olmuyor

Postacılar, adresini, bulmuyor

Lâlem artık, sevdiğimi, bilmiyor

Can kattın sen, can çekişen, canıma

Sabah oldu, beklemenin, tadında

Bir kız sevdim, solgun lâle, adında

Yanarken ben, hasretliğin, od''unda

Can kattın sen, can çekişen, canıma', 'Sen  lâlesin, kırılırsın, elimde Uzakta dur, gelme artık, yanıma Hep seveyim, gözlerini, hasretle Can katarsın, can çekişen, canıma Ah be gü...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/lale-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılar Şahidimdir', 'acilar-sahidimdir-resul-ustun-d9cen', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben ilkim beyler! 

Sevdalı toprağın döl rahmine

ilk kazmayı ben vurdum.

Sevdalar üresin diye; 

tırmıkladım,

tırpanladım,

harmanladım tarihsel sevdaları.

Tırnakladım,

acıyla yoğurdum

canevinde gülücükleri.

Tüm acılar şahidimdir.

Yalanı bilmez acılar.

Ben ilkim beyler! 

Benimdir zulme karşı

ilk direniş,

ilk başkaldırı.

Benimdir ilk red-i itaat.

Ben başlattım sevmeyi.

severken alnı açık,

başı dik direnmeyi.

Direnç alevleri küllenecekken,

ben avuçladım,

koynumda sakladım kor ateşleri.

Ben ilkim beyler! 

Adem ile Havva''dan beri,

beni anlatır kavimler.

Beni yazar tüm tarihler.

Tüm acılar şahidimdir,

Yalanı bilmez acılar.

Sorun isterseniz; 

Ben sevdayım,

sevda yüreğimdir.', 'Ben ilkim beyler!  Sevdalı toprağın döl rahmine ilk kazmayı ben vurdum. Sevdalar üresin diye;  tırmıkladım, tırpanladım, harmanladım tarihse...', ARRAY['Türk Edebiyatı','Şiir','Resul Üstün']::text[], 8.5, '{"poet":"Resul Üstün","poet_slug":"resul-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/acilar-sahidimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyazları Düşledim', 'beyazlari-dusledim-nazan-i-zmirli-92jbw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'beyazları  düşledim  bugün

küme  küme  bulutlar,bizi sarmışlar

pamuklu  şeker gibi uçan bir halıda

sonsuzlığun  yolculuğuna   çıkmışız

beyaz   düşlerle.........

beyazları  düşledim  bugün

yüksek yüksek tepelerde karlı

çatısına  kadar  karla  kaplı

yolları kapanmış dış dünyalara

beyaz dumanlar bacasında

bir dağ evinde, odun ateşindeki

beyaz düşlerle.......... 

beyazları düşledim bugün

gelin olmak istedim telli duvaklı

tacında beyaz güller,elinde  menekşeler

eteklerinde kır çiçekleri, beyaz kardelenler

uçuşsun  üzerinde  kar  taneleri

buz üzerinde gülümseyen

beyaz düşlerle.................

beyazları düşledim bugün

düşlerimdeki beyazlar

geçmişimdeki beyazlar

bugünkü beyazlar

gelecekteki beyazlar

sonsuz beyazlar 

beyaz düşlerle.......................

beyazları düşledim bugün

papatya tarlasında

beyaz pelerini uçuşuyor arkasında

beyaz umutların  prensi

dört nala koşturuyor beyaz kısrağını

beyaz düşlerle........................

beyaz düşlerle.......................

Nazan İzmirli-24.01.2002-antalya', 'beyazları  düşledim  bugün küme  küme  bulutlar,bizi sarmışlar pamuklu  şeker gibi uçan bir halıda sonsuzlığun  yolculuğuna   çıkmışız beyaz...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/beyazlari-dusledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinsel Politika', 'cinsel-politika-ulug-celik-l6sqp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'CİNSEL POLİTİKA

 '''' Eğer gerçekten özgür olmak istiyorsak,herkesçe benimsenen görüşleri körükörüne kabul etmek zincirinden kendimizi kurtarmamız gerekir.İçine hapsolunduğumuz üç büyük kafesin demirlerini kırmak zorundayız.

  I.Bilinci; Varlığı kendinden menkul,mucize,keramet ve olağanüstülük gibi

bir anlamsızlığa zincirleyen,papazların,ilkel kurama bağlı yargıçların,savaşçı kahramanlar gibi-büyük adamlar-mitinden kurtarmalıyız.    

                                                  

  II.Demokrasi erdemlerini altüst eden polis devletinin egemenliği(Demokrasinin temeli toplumu kimin yöneteceği  değil,yönetimini beğenme diklerimizin şiddete başvurmadan,kan dökmeden nasıl-yönetimden-uzaklaş tırılabileceği sorunudur.

  III.Cinsellikle ilgili görüş ve kavram değerlerinin değiştirilmesi:Çünkü 

bütün temel sorunlar cinselliğe dayanır.Kadın kısrak gibidir.İçinde iki irade birbiriyle çatışır.Bunlardan birisi,kendisini tamamen teslim etmeye zorlar.İkincisi ise şahlanmaya ve binicisini üstünden atmaya zorlar ve kışkırtır.

  Doğulu anlayışında veya dinin belirlediği mitle,kadın pasif olmalı,boyun eğmeli,aşkın altında kalmalı.Sandaldan eğilip baktığı zaman suyun altında gördüğü yosunlar gibi olmalı.Hiçbir zaman ömrü boyunca su yüzüne çıkmamalı ve suyun üstünü görmemeli.

  Daha fazlasını görmek,daha fazlasını anlamak,doğulu erkeğin asla tahammül edemeyeceği şeydir.Başkaları tarafından anlaşılmamak için yüzlerini peçe ile örtmek gerekir.

  İşte böyle kadın biliincinden koparıldığı zaman köle edilebilir ve dolayısıyla erkeğin-erkekliği tatmin olur.

  Son yıllarda yapılan embriyolojik araştırmalar göstermiştir ki,kadın insan soyunun temel tipidir,yani bütün embriyonlar kız olarak oluşmaya başlar,sonra içlerinden bir kısmında kromozom yapısındaki androjen etkisiyle erkek çocuklar olur.

  Eski ve yıpranmış bir yapının temel direkleri olan büyük adamların dayandıkları günah ve erdem miti,suç suçsuzluk miti,kahramanlık miti,hep cinsel safsatalara saplanmıştır.

  Düzene hakim olmak isteyen bu eski kokuşmuş ideolojinin temel taşlarını yerinden oynatmadan onu kendi karanlığında boğmak mümkün değildir''''

                                                                                          K.M - Cinsel Politika', 'CİNSEL POLİTİKA  '''' Eğer gerçekten özgür olmak istiyorsak,herkesçe benimsenen görüşleri körükörüne kabul etmek zincirinden kendimizi kurtarm...', ARRAY['Türk Edebiyatı','Şiir','Uluğ Çelik']::text[], 8.5, '{"poet":"Uluğ Çelik","poet_slug":"ulug-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cinsel-politika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D e r di denilse/ d e r denmeyenleri', 'd-e-r-di-denilse-d-e-r-denmeyenleri-zafer-zengin-etnika-zya2p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.

o kadar hızlı gidiyoruz ki; ruhumuz geride kalıyor*

.derdi denilse

melodi ölümlü sesten

başlamış her şey

doğmamışım

.yol

uzaklaşır

ayrılmadan

sus’u bağladığı el

söylenir dönüşte

dışına kaçan gövde

git deyip gelmekte

iç’te

iki çizgi karışır

seçilmez ışıklar

ne varsa

uzakta var

dolan çıkar karşısına

kapar gözlerini

ölümlü her şey nasılsa

ıskalamak yok karanlıkta

alır yol insanı ortasına

.yürek

öyle ya

bir öpücük bile 

ödül değil

kanı alıp

gönderdiğin can’a

hatırla arada

aşk’a yakalan bu sıra

benim

sesi bilirim

sesi

sessizi

.sıvama sıyırma

içimden kattıklarım

peşi sıra izli mermi

ve çekirdek

tapınağı yıkacak deli

bozulmamış

kesip alınan irin

biriktirin

yaz ortası sevişin

bahar sonu meyve

ısırın

göz kapanınca ayrılık

uyandırmayın

11 09 2005 / kaş

*bir filmden/orta ve güney amerika söylencesi

.', '. o kadar hızlı gidiyoruz ki; ruhumuz geride kalıyor* .derdi denilse melodi ölümlü sesten başlamış her şey doğmamışım .yol uzaklaşır ayrılma...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/d-e-r-di-denilse-d-e-r-denmeyenleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yaz adını Şiirin', 'sen-yaz-adini-siirin-kerem-kayar-kcegk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi şiirin içine sığdırmalı

Bir kaç mısra arasına

Koca denizin tek bir kıyısı

Bir pencereden doğmasını beklemek güneşin

Tanrı değilim ben

Sığdırmak istemiyor yüreğim 

bir kaç mısraya seni

Her öpüşe 

Bir gece uykusuzluguna

Boğazdan geçmeme inadına lokmanın

Aşk denildiği zaman

Aşkı tüketiyoruz işte

farkına varmadan...

Bir kez daha yanılmaya hazırmısın? 

Yanıltmaya vahşetinde ki insanları

Garipseyişlerde, gülümsemeye

Hazır mısın bir kez daha sevmelere

Bir yanın kurumaya yüz tutmuş

papatya senin

Diğer yanın ona inat yeşeren tohumu

sanki papatyanın

Ben iki yanında vâr olmaya

hazırmıyım sende? 

Hani bilirsin iki insan yakınlığını

Arkadaş, dost, sevgili

Bende her anlamda varsın

Ya sende? ....Ben varmıyım? 

Bilirsin beni absürt olmaktan yana

Çığlıklarında sevişmeleri sever

Ya da en mahsum tarafı ile

Kurdugum ütopyamda yaşamayı

Kolaydır belki seni anlatamadıgım 

mısralara beni sığdırmak

Dedim ya Tanrı değilim

Kolaylıgında ki yüreğin 

Acısı ağırdır, taşıyorum

Kimselerde bilmesin yükünü

İşte burada şiire ünlem koyma niyetim var

Kimse olmadıgını

bilmeni, istemek için...', 'Hangi şiirin içine sığdırmalı Bir kaç mısra arasına Koca denizin tek bir kıyısı Bir pencereden doğmasını beklemek güneşin Tanrı değilim ben ...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sen-yaz-adini-siirin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize ne', 'bize-ne-nazan-i-zmirli-p6dmg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben; seni gezdirirken 

kendi  yalnızlığımda

ıssızlığımda

sessiz sessiz............

sen;  kendi kuytularında

kendi  yalnızlığında 

ıssızlığında

damla damla.............

neden bu hasret

            bu işkence

            bu keder

sandalımız uyuyan bir denizde 

sessiz sessiz  yol alsa 

yaralı yerlerinden 

damla  damla su  dolsa

bize ne! 

batmazki  bu  yürekler

AŞKI  çekmişse  içine........', 'ben; seni gezdirirken  kendi  yalnızlığımda ıssızlığımda sessiz sessiz............ sen;  kendi kuytularında kendi  yalnızlığında  ıssızlığın...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bize-ne-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelip s a r ılırım / s a r kavuşmaları', 'gelip-s-a-r-ilirim-s-a-r-kavusmalari-zafer-zengin-etnika-xyg3g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.

.

gelip sarılırım

omzuna koyarım başımı

susarım demiştin

yok mu göz yaşın

.

beklerken ağlattın

liz öldü içimde

gözleri menekşe

tuhaf koşulardan gelip

dağıtma

toparlanamam sonra

zırhımdan eksikler var

ilişirsen

kan sızar kenarına

ölümü de görmedim

anlatamam

.

derdimi anlatırdım

deremedim

şaşkın ifademle

kendimi dinledim de

büyümeyi öğrenemedim

07 09 2005

.', '. . gelip sarılırım omzuna koyarım başımı susarım demiştin yok mu göz yaşın . beklerken ağlattın liz öldü içimde gözleri menekşe tuhaf koşul...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gelip-s-a-r-ilirim-s-a-r-kavusmalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Acıların Şahıyım', 'ben-acilarin-sahiyim-resul-ustun-fbwrk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Davullar çalınmasın,

halaylar,

peşrevler gereksiz.

Zılgıtlar anlamsız artık.

Koşullar gerektirdi ya,

nasılsa gideceğim.

Ben gidince,

siz kalanlar paylaşın mirasımı.

biraz suç,

bir kaç hata,

kucak kucak da sevgi bırakıyorum.

Zulada biraz acı,

biraz keder de var ya...

Birkaçınız acıların,

can alıcı sancıların; 

geri kalanlarınız da

sevinçlerimizin bekçisi olun.

Hatta

rehin alın ben gidince.

hem acıları,

hem sevinçleri...

Olur ya; 

bir gün ararsanız,

özlerseniz beni

azat edin tüm acıları.

Zerresi kalmasın sancıların.

Çıkıp gitsinler yüreklerinizden.

Gülmeler,

sevinçler tutsak kalsınlar.

Ses geçirmez duvarlar,

çelik kapılar ardına kilitleyin.

Hatta sevinçlerin tümünü

bir bir zincirleyin.

Ben sevgilerin şahıyım.

Bakın o zaman 

kelepçelerimi nasıl kırar,

firar eder uçarım size.', 'Davullar çalınmasın, halaylar, peşrevler gereksiz. Zılgıtlar anlamsız artık. Koşullar gerektirdi ya, nasılsa gideceğim. Ben gidince, siz kal...', ARRAY['Türk Edebiyatı','Şiir','Resul Üstün']::text[], 8.5, '{"poet":"Resul Üstün","poet_slug":"resul-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ben-acilarin-sahiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimin Umurunda', 'kimin-umurunda-erdogan-ergin-45cwt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çiçek açmış kimin umrunda

uğrunda ağarmış saçlarım

gözlerimin altındaki isyan

varken içimde sensizlik korkusu

yediverenler serilmiş önüme kimin umurunda

gece ay''a doymuş,ay kimin umurunda

altında ben yokken seninle el ele

gölgemiz oluşmazken bir ağacın dibinde

kor bir ateşin içinde, 

gözlerimizden dökülmezken

damla damla aşk

ay griye boyasa yeşili

ben gönlüne düşmezken senin

bahar yeli, yüzüme vururken seni

atarken gizlice tokadını ruhuma

sensizken yeryüzüm,

gizlice mehtabı seyretmek kimin umurunda

sersefil olmuşken ben,

kana kana içsem hasreti

içimde demlense tüm duygular

tam kıvamında desem aşk

sen olmadıktan sonra kimin umurunda

kimin umurunda

açelyalar, karanfiller

menekşeler, al al güller

sen çıkmazken papatyalardan

bin bir çiçek kimin umurunda', 'çiçek açmış kimin umrunda uğrunda ağarmış saçlarım gözlerimin altındaki isyan varken içimde sensizlik korkusu yediverenler serilmiş önüme ki...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kimin-umurunda-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senmiydin', 'senmiydin-sair-dilenci-6nxk6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'senmiydin birtanem gelen....

kapılar hala kapalıyken 

ve birdaha açılmayacakkken

nerden esti bu kaçış...

cisminden değil sarhoşluğum

ruhumdan boşalıyor eskimeyen iniltirler...

senmiydin kayboluşum gelen,

yıkılmışlığım, özlemim,kabuslarım.

olmamıştım daha senden sonra

doğmamıştım, eskiydim, açılmamıştı gözlerim,

kesilmemiştim sensizlikten,

nerden çıktın geldinki..

senmiydin gelen..

keşke gelmeseydin...

keşke.................................

dilenci..............................', 'senmiydin birtanem gelen.... kapılar hala kapalıyken  ve birdaha açılmayacakkken nerden esti bu kaçış... cisminden değil sarhoşluğum ruhumda...', ARRAY['Türk Edebiyatı','Şiir','Şair Dilenci']::text[], 8.5, '{"poet":"Şair Dilenci","poet_slug":"sair-dilenci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senmiydin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçmen Kuşlar', 'gocmen-kuslar-nazan-i-zmirli-q8c2v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'özlenendir  buram  buram

kırçiçeklerinin  saflığında

balkondaki  saksının  son  kuruyan dalında

filizlenen umutlardır.

onlar kaçarken soğuk ülkelerden

biz kucaklardık onları

akdenizin poyraz esintilerinden

sıcak sıcak.

süzülürken mavilerde dizi dizi

şiirlerde  dize dize  mısra gibi

özenirsiniz özğürlüklerine

kapatıp gözlerinizi 

oturmak gövdelerine

kanat çırpmak bilinmez bir geleceğe...

tükenmişliğin,bezginliğin bitişi

yeni bir doğuşun habercisi

göçmen kuşlar.............

nasıl boyadılar kanatlarınızı

rengarenk

nasıl yazdılar alın yazınıza

adını koydukları ölüm fermanını

özgürlüğün tadını çıkartırken

bizlere özgürlüğün hazzını yaşatan 

göçmen kuşlar... 

göçmen kuşlar...

Nazan İzmirli-10.10.2005-antalya', 'özlenendir  buram  buram kırçiçeklerinin  saflığında balkondaki  saksının  son  kuruyan dalında filizlenen umutlardır. onlar kaçarken soğuk ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gocmen-kuslar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım', 'anladim-yasar-aksit-wtw8p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin kıyısında durmuşum,

Kararsız adımlar atan,

Ama Kendisinden emin...

Biraz yıkık bir sesle; ''-benim yolum budur

Gerçektende öyleydi,

Orda duran biz aslında bzi değildik,

Önceden hep hastalıktan ölünür sanırdım...

Meğer hasrette öldüüryormuş...anladım

Öyle insanlar sıkıştırmışımki şu kısa ömrüme,

kendisine saygısı olmayanlar,

kendi öfkesinde boğulanları tanıdım,

AŞKI TANIDIM...

Yağmurlar yağdı serin eylül akşamlarında üstüme,

Islandım...Yalnızlığıma ağladım...

Derler ya erkekler ağlamaz...

ağlarmış anladım.', 'Gecenin kıyısında durmuşum, Kararsız adımlar atan, Ama Kendisinden emin... Biraz yıkık bir sesle; ''-benim yolum budur Gerçektende öyleydi, O...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akşit']::text[], 8.5, '{"poet":"Yaşar Akşit","poet_slug":"yasar-aksit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anladim-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Mevsim Bahardık', 'dort-mevsim-bahardik-resul-ustun-hpg3l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birlikte yola koyulurken

tek bedende birleşen canlar,

bir çınarda yüzlerce dallar gibiydik.

Umuttuk,

kara sevdaydık yüreklerde.

Şimşek şimşek bilinçtik serde.

Sarptı,

dolambaçlıydı,

aşılmaz bir labirentti yolumuz.

Gencecik fidanlardık.

Duyguların en safı,

en temizi vardı yüreklerimizde.

Ve bu duygularla âşıktık bir çoğumuz.

Nedense aşk yasaktı lisede.

''Olsun dedik,

yasaklar baş göz üstüne''dedik.

Ama yeminler olsun ki...

Yeminliydik en güzel sevdalar üstüne.

Ferhat''la Şirin gibi,

Mem û Zin gibi sevda yüklüydük.

Kaypaklığı bilmezdik hiç birimiz.

Belki eski püsküydü giysilerimiz,

ama bahar kadar yeni,

filiz kadar tazeydik tümümüz.

Mutlu

ve umutluyduk yola koyulurken.

Çelik çomak,

kartopu oynamak yerine

tarihi yargılardık lisede.

Tarihi yazanların 

yargıç olduğunu düşünemeden.

Henüz yarılamışken yolu,

iflas etmiştik birçoğumuz.

Umutlarımızı,

sevdalarımızı,

ve yeminlerimizi unutmuş gibiydik.

Kasırgalara meydan okurken,

basit esintilerde

yelken bile olamadık bazılarımız.

Dökülenler, 

kopan tespih taneleri gibi 

sağa sola dağılanlar...

ayak bağı olanlar oldu zaman zaman.

Hatta; 

sabahsız gecelerin

lümpen serserileri oldu bazı dostlarımız.

Kolayı seçtik beyler,

yazık ettik sevdalarımıza.

Hani ya ağalar

biz sevgilerin simgesiydik! 

Hani ya biz; 

gökyüzünün yağmuru,

yeryüzünün bereketiydik...

Hani ya ağalar,

hani ya  biz dört mevsim bahardık...?', 'Birlikte yola koyulurken tek bedende birleşen canlar, bir çınarda yüzlerce dallar gibiydik. Umuttuk, kara sevdaydık yüreklerde. Şimşek şimşe...', ARRAY['Türk Edebiyatı','Şiir','Resul Üstün']::text[], 8.5, '{"poet":"Resul Üstün","poet_slug":"resul-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/dort-mevsim-bahardik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-yavuz-agir-9vt3n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sürgünde bir garip divaneyim

Dert üstüne dert çekerim

Acıların çileli çocuğuyum

Gam üstüne,gam çekerim...

Sevgi denen aşkı ararım 

Karşıma cefa çıkar

Sefa sürecek yer ararım

Bahtıma çilehane çıkar.

Garip gönlüm sevda çeker

Aşkıma gül ararım

Tikenleri fena batar

Çıkaracak yar ararım...', 'Sürgünde bir garip divaneyim Dert üstüne dert çekerim Acıların çileli çocuğuyum Gam üstüne,gam çekerim... Sevgi denen aşkı ararım  Karşıma c...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/garip-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anka', 'anka-yasar-aksit-67cui', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmur damlasıyla yıkılan karınca yuvasının,

gölgesinde oynanan bir oyundum yıllarca,

Baktım öylece derin etrafıma,

Uyumuş kalmışım büyük bir oyunun içinde...

Yolsuz,yordamsız ve apansız kalmışım çoğu zaman,

ama bilmişim yolumu...

yol gösteren yıldızlar.

onlar değilmiydi binlerce insanı kendine hayran eden yanıp sönen ışıklar? 

Ve gece güneşim olduğunu söylüyorum şimdi,

Nedenmi? Bilmiyorum...

Görmüyormusun nasıl titriyor ellerim? 

Ve kaçırıyorum ondan gözlerimi...

Onun gözlerine bakamıyorum,

Acuyor biryerlerim,isyan çıkıyor zindanlarımda,

Yıllar boyu arkasından ağladığım o güzel anka,

Meğer sen olmalıymışsın...', 'Yağmur damlasıyla yıkılan karınca yuvasının, gölgesinde oynanan bir oyundum yıllarca, Baktım öylece derin etrafıma, Uyumuş kalmışım büyük bi...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akşit']::text[], 8.5, '{"poet":"Yaşar Akşit","poet_slug":"yasar-aksit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anka-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemekteymişim', 'beklemekteymisim-yasar-aksit-sjwug', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin soğukluğu vurmuş ellerime,

Birde senin yokluğun sarmış,

Kalbim sana kanarken,

Benklemekteymişim güneşi...

Güneş ışığı vurmuş yüzüme,

Birde senin bağrının sıcaklığı,

Kalbim sana kanarken 

beklemekteymişim yıldızları...

Yıldızlar parlamış gözlerime,

Birde senin ay parçası yüzün,

Kalbim seni severken,

beklemekteymişim yakamozu...

Yakamoz vurmuş denizin üstüne,

Birde senin sahte gözyaşların,

Kalbim sana sahte aşıkken,

Beklemekteymişim baharı...', 'Gecenin soğukluğu vurmuş ellerime, Birde senin yokluğun sarmış, Kalbim sana kanarken, Benklemekteymişim güneşi... Güneş ışığı vurmuş yüzüme,...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akşit']::text[], 8.5, '{"poet":"Yaşar Akşit","poet_slug":"yasar-aksit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beklemekteymisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne oldu bizlere bilen söylesin', 'ne-oldu-bizlere-bilen-soylesin-mikdat-bal-8vzfa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar bizler nasıl millettik

Ne oldu bizlere, bilen söylesin

Dünya ya hakimdik güçlü devlettik

Ne oldu bizlere bilen söylesin

Maddi yönden bundan daha fakirdik

Bir çok memlekete çarıkla girdik

İnsanlığa çağlar boyu yön verdik

Ne oldu bizlere, bilen söylesin

Karadan yüzerdi bazen gemimiz

Surları yıkardı bizim mermimiz

Kralı yargılar bir hakimimiz

Ne oldu bizlere bilen söylesin

Saygı sevgi vardı gönüller zengin

Tahammül sonsuzdu hoş görü engin

Türk hamisi, dostu idi her rengin

Ne oldu bizlere bilen söylesin

Amirin sözüne uyardı herkes

Verilen her emri duyardı herkes

Büyükleri sevip sayardı herkes

Ne oldu bizlere bilen söylesin

Rüşvet yoktu herkes hakkına razı

Zaten her Türk asker, ya şanlı gazi

Bu kadar güzelken parlakken mazi

Ne oldu bizlere bilen söylesin

Zengin zekatını vermiyor artık

Komşusu aç yatar görmüyor artık

Fakirin halini sormuyor artık

Ne oldu bizlere bilen söylesin

Güzelim töremiz yobaz  sayıldı

Her tarafa fitne, fesat  yayıldı

Eşkıya sehirde, cana kıyıldı

Ne oldu bizlere bilen söylesin

Eskiler her şeye Besmele derdi

Yarım kilo şeker bir ay yeterdi

Komşu komşusuna yardım ederdi

Ne oldu bizlere bilen söylesin

Kalmadı bereket iştah kesildi

Lüks fakiri olduk her şey kısıldı

Bu son gelen nesil nankör nesildi

Ne oldu bizlere bilen söylesin

Der Mikdatî  dostlar cevap yazınız

Benim gibi üzgün müdür bazınız? 

Yazın ozanlarım çalsın sazınız

Ne oldu bizlere bilen söylesin', 'Bir zamanlar bizler nasıl millettik Ne oldu bizlere, bilen söylesin Dünya ya hakimdik güçlü devlettik Ne oldu bizlere bilen söylesin Maddi y...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ne-oldu-bizlere-bilen-soylesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar - Rüzgar Şairi -', 'ruzgar-ruzgar-sairi-i-sa-sari-4wlkb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki şairi olurum 

Tükenmiş akşamların 

Belki yalan şarkılar 

Hayali zor masallar anlatırım 

Bir dalgınlık sizi sarmışken şakaklarınızdan... 

Belki haberi olurum 

Güler yüzlü sabahların 

Belki eski türküler 

Notası zor senfoniler okurum 

Gözleriniz bir tebessüm çizerken yanaklarınızdan... 

Belki güzel bir yalan kadar tanıdık 

Belki olmaz bir hayal kadar yalan 

Çehresi olmayan ben 

Ruhumun aynasında 

Bakarsınız tutar çekerim 

Başıboş yürüyen ayaklarınızdan.... 

Ne rüzgar ne dalgalar 

Dindirmez ruhlarda fırtınaları 

Sonsuz bir uzay kadar yakın 

Ve insana kendisi kadar uzak 

Nesnesiz uzanır ellerim 

Ve tam da siz mırıldanırken 

En güzel senfoniyi yakalar parmak uçlarınızdan... 

....2000....', 'Belki şairi olurum  Tükenmiş akşamların  Belki yalan şarkılar  Hayali zor masallar anlatırım  Bir dalgınlık sizi sarmışken şakaklarınızdan.....', ARRAY['Türk Edebiyatı','Şiir','İsa Sarı']::text[], 8.5, '{"poet":"İsa Sarı","poet_slug":"i-sa-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ruzgar-ruzgar-sairi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum Sözlerimi', 'sustum-sozlerimi-aysun-erat-eqqt3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sandığa kaldırmalı bütün sözleri.

Ve...

Kilit vurmalı bir de üstüne! 

Söylenmemiş sözlerin ne anlamı var ki? 

Şöyle söz dediğin,

Dolu dolu çıkmalı ağızdan

Ardına bakmadan varmalı hedefine.

Ah benim sözcüklerim! 

Kim zavallı etti sizi böyle? 

Boynunu büken  bir çiçek gibi,

Solduran şey ne renginizi? 

Vazgeçtim her şeyden

Ve her mihnetinden dünyanın.

Kabuğum ve ben.

Böyle iyi..

Artık sustum hepinizi.

10/2005', 'Sandığa kaldırmalı bütün sözleri. Ve... Kilit vurmalı bir de üstüne!  Söylenmemiş sözlerin ne anlamı var ki?  Şöyle söz dediğin, Dolu dolu ç...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sustum-sozlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet - 3', 'gurbet-3-elazigli-mustafa-kaya-fv1wy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bilmem nasıl anlatılır

bir hazan yaprağı gibi

çok uzaklara gelmek.

sıkıntıların korkularıyla

yerlerde sürünmek.

kan damlayan,

acılı gecelerim oldu

yanıma bağlanıp saklanan.

ruh tarlamın çoraklığına bak..! 

bir ezan nağmesine hasret.

yabanda gördüm,

neymiş kahır.

hayatımın zorlu yılları

figanlara emanet.

Ve,

göğsümde nefes gibi

beslenir

her günü acı gurbet…

memleketimin ırmağıydım

denizimi kaybettim

ancak,

hatıralarımı taşıdım 

kimliğim daha ayakta

ne zaman çıksam  sokaklara

bulutum bırakmaz beni

yabanda…

Mustafa kaya

26.10.2005 / sirkeci

www.mustafakaya.net', 'bilmem nasıl anlatılır bir hazan yaprağı gibi çok uzaklara gelmek. sıkıntıların korkularıyla yerlerde sürünmek. kan damlayan, acılı geceleri...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gurbet-3-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meşale', 'mesale-elazigli-mustafa-kaya-yozua', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'içinde gün ışığı

çıkmayan sevgilim.

üşümelerinden 

ateş damlayan,

ve

ateşten,

gül çıkartan sevgilim,

sen,

kıskanç gönlümün meş’alesi

yalnızlığımın şulesi….

Mustafa kaya

26.10.2005 / Sarayburnu

www.mustafakaya.net', 'içinde gün ışığı çıkmayan sevgilim. üşümelerinden  ateş damlayan, ve ateşten, gül çıkartan sevgilim, sen, kıskanç gönlümün meş’alesi yalnızl...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mesale-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mimoza', 'mimoza-elazigli-mustafa-kaya-5cbau', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir ağaç dikeyim, 

mimoza olsun 

uzakta ki sevgilim için

uzak kökenli bir ağaç 

mimoza 

sardı sarısı şimdiden 

sardı kokusu, 

kokusu sevgilimin 

üşür,rüzgar ve soğukta 

mimoza 

sevgilim de üşür. 

bir vazoya alırım ısınır, 

kokuludur çiçekleri

mimozanın

sevgilimin elleridir 

mimoza yaprakları

severim onları

titrek bir mum ışığı vurur 

kalplerimizi

geceleri yalnızız

mimoza bekler ikimizi.. 

Mustafa kaya

26.1o.2005 / salacak

www.mustafakaya.net', 'bir ağaç dikeyim,  mimoza olsun  uzakta ki sevgilim için uzak kökenli bir ağaç  mimoza  sardı sarısı şimdiden  sardı kokusu,  kokusu sevgili...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mimoza-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Babam', 'benim-babam-suleyman-tunc-d9bb7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim babam,

Bir öğretmen.

Güneş''i doğdurmaz üzerine.

Her gün imamlardan bile önce uyanır.

Kalkınca ilk işi potinlerini boyamak.

Sonra sinek kaydı bir traş.

Kahvaltısı üç bardak çaydır benim babamın.

Çantasını kaptı mı doğru okula.

Annem bağırır kapı aralığından:

''''Uğurlar ola! ''''

Benim babam,

Başı dik, gözü pek insandır.

Yalanı hiç sevmez,

Parayı da.

Bu yüzden kiralarda geçer ömrümüz yıllardır.

Annem sitem eder bazen babama:

''''Bir evimiz bile yok! ''''der.

Babam gayet olgun ve mütevazi,

Sadece gülümser.

Benim babam bir öğretmen! 

Çocuklar ve kitaplardır bütün dünyası.

İçki içmez, kumar oynamaz.

Boş laflarla zaman öldürmez kahve köşelerinde.

O bilir matematiği, Türkçe''yi,...

Feni.

Benim babam adalet abidesi.

Fırat kıyılarında bir koyun kaybolsa,

Suçlu hisseder kendini.

Benim babam, 

Takım tutmaz.

Doğru dürüst maçları bile izlemez.

Oysa ben Beşiktaşlı olmasını istemişimdir hep.

o hala tarafsız.

Ah! ...birde milli maçlarda görseler babamı.

Değişiverir ansızın.

Fanatik mi fanatik.

Hiç bir rengi tanımaz.

Varsa yoksa kırmızı beyaz.

Benim babam,

Çocukları çok sever.

Hepsini gelecekte birer Nene Hatun,

Birer Atatürk görür.

Bu yüzden,

Sokakta dilenen bir çocuk görse üzülür.

Uykuları kaçar sabaha dek.

''''Sen mi kurtaracaksın bu ülkeyi''''diyemez kendine,

Elinde değil.

Benim babam mertliğe şapka çıkarır.

Düşman olduğu tek cümle:

''''Bükül ve eğil''''.

Benim babam bir öğretmen.

Özel bir insan.

Menfaat uğruna bayrağına küfretmez.

Dostlarını terk etmez.

Vatanını satmaz.

Gerekirse,...

Meydanları üç beş çapulcuya da bırakmaz.

Benim babam,

Türklük için yaşar.

Vatan için harcar.

Bayrak için ölür.

    Çünkü benim babam,

    Adam gibi adam! ...

Çünkü benim babam bir öğretmen.', 'Benim babam, Bir öğretmen. Güneş''i doğdurmaz üzerine. Her gün imamlardan bile önce uyanır. Kalkınca ilk işi potinlerini boyamak. Sonra sinek...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Tunç']::text[], 8.5, '{"poet":"Süleyman Tunç","poet_slug":"suleyman-tunc","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/benim-babam-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Fidan', 'i-simsiz-fidan-melih-coskun-6zrp9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İkinci günüydü içeri alınışının 

Kulağından kan geldiğinde 

Eğildi ve fısıldadı kulağıma usulca

‘Biz kolay ölmeyiz reis’ dedi

Daha çok işimiz var yapılacak 

Bakışlarını güneşten ödünç almıştı sanırım 

Adı neydi hala bilmem

Fidanlara isim konmaz derdi eski bir dostum 

Hürriyet; karşılıksız aşkıydı bütün kahraman çocuklarının 

Gidip de dönmemenin diğer bir adıydı gece yarıları

Daha yola çıkmadan bütün kalemler kırılmıştır oysa 

Yazılmıştır bütün fermanlar daha barikatlar kurulmadan

İkinci günüydü içeri alınışının

Kulağından kan geldiğinde 

Eğildi ve fısıldadı kulağıma usulca

‘Aldırma’ dedi 

‘Ben bir yaprağım 

Koparsalar da dalımdan   

Ağaçta yaprak tükenir mi hiç’

Şimdi bütün devrimler 

Söylenememiş aşklar gibi yarım 

Bütün isimsiz çocuklarının

Dudaklarının kıyısında kurumuş kan izleri 

Fidanlara isim koymaya başladım bugün 

Kırmızı yazılarla yazdım bütün sahipsiz duvarlara 

Bin yıllık bir türküyü okudum her gün gibi 

Her gün gibi geçtim acıların ormanından 

Yaralı ayaklarımı sürüyerek 

Ve bitmek tükenmek bilmeyen bir inatla yürüyerek 

İkinci günüydü içeri alınışının 

Kulağından kan geldiğinde

Eğildim ve fısıldadım kulağına usulca

‘artık seninde adın var

hiç bitmeyecek kavganın adı gibi''...

2004', 'İkinci günüydü içeri alınışının  Kulağından kan geldiğinde  Eğildi ve fısıldadı kulağıma usulca ‘Biz kolay ölmeyiz reis’ dedi Daha çok işimi...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/isimsiz-fidan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '24 Mart', '24-mart-sair-dilenci-z4lnt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi ayrıldım bu inatçı mevsimden

İşveli bir bahar kapımda

Kendini kaybetmiş bir sevinç

Çığırından çıkmış bir güneş doğuşu

Ve adresini kaybetmiş bir cumartesi sabahı

Nazlanıp durur karşımda

Bir türlü geçmez vakit.

Şimdi ayrılım seni özlemekten

Saatler adım adım seni getiriyor bana

Aynı bir bahar gibi

Aynı 24 mart akşamları gibi.

Yavaş yavaş kopuyor zincirlerim

Tüm dümenler sana doğru artık

Yolumu şaşırmam merak etme

Güneş hiç batmaz çünkü bakışlarında

Güneş hiç batmaz böylesi hasretlerde

Bütün kuşlar beni sana götürür

Bütün rüzgarlar ana eser de bu okyanusta

Sen hep beni beklersin.

Şimdi ayrıldım ölümlerden

Şimdi terk ettim bu zamanız gel gitleri

Binlerce kez ölmüşken bu dar ağaçlarında

Sen hiç görmedin ölülerimi

Hiç duymadın son nefeslerimi

Çünkü ben sana hep

                 Doğuşlarımda geldim

Saf günahsız, biçare

Bir berf misali

Aynı bakışların gibi.

Şimdi daha çok seviyorum seni

Ve  daha çok özlüyorum

Bu ikindi yağmurları hapsetti beni yokluğuna

Saatler bir ileri bir geri

Ama hep sana doğru birtanem.

Şimdi bakışlarını bana çevir başımın tacı

Gülüşlerini gönder bu titrek gecede

Çağır beni bütün haykırışlara inat.

Ve daha çok sev beni

             Bütün ayrılıkları yok sayarak

Sev ki çocukluğumdan kurtulayım 

              Büyüyeyim avuçlarında........', 'Şimdi ayrıldım bu inatçı mevsimden İşveli bir bahar kapımda Kendini kaybetmiş bir sevinç Çığırından çıkmış bir güneş doğuşu Ve adresini kayb...', ARRAY['Türk Edebiyatı','Şiir','Şair Dilenci']::text[], 8.5, '{"poet":"Şair Dilenci","poet_slug":"sair-dilenci","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/24-mart-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takanın İnce Çizgisinde', 'takanin-i-nce-cizgisinde-guzin-eye-dundar-lqs3v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ufkun  derin mavisine

dalmış gözler yine

takanın ince çizgisinde

yağmur tülü

alacakaranlığın ertesi

sabah serinliği

umut günü

kıyılarda  yaşlı  balıkçının  türküsü

küreklerde  denizin nefesi

ağlarda kıpır kıpır  gümüş  ışıltı

yosun kokusunda  akşam öğünü

İlahi ikram....  günün öyküsü..', 'Ufkun  derin mavisine dalmış gözler yine takanın ince çizgisinde yağmur tülü alacakaranlığın ertesi sabah serinliği umut günü kıyılarda  yaş...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/takanin-ince-cizgisinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burada Duruyorum', 'burada-duruyorum-sair-dilenci-tnjut', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Burada duruyorum artık

Ve sadece seni hissediyorum.

Tüm yüzleri çamura bulayarak

Sadece seni izliyorum şimdi.

Sesindeki o ilk bahar coşkusunu dinliyorum.

Pişman olarak sensiz geçen günlere

Biraz da kızarak kendime

Şimdi yalnızca seni diliyorum.

Artık her yere yüzünü çiziyorum 

Yüzünün ve o ıslak bakışlarını

Ve varlığının mucizesini çiziyorum..

Burada bitiyor artık 

Kederler, üzüntüler, ağlamalar.

Kabuslar bitiyor.

Bir tek sen büyüyorsun

Bir tek sen doğuyorsun ufuklardan.

Şimdi deli bir telaş var her yanımda

Aşk daha bir sarhoş ediyor başımı

Sen bir başka doluyorsun kalbime.

Burada duruyorum artık

Arkama hiç bakmıyorum.

Aklımda sen

Valizimde gülüşlerin

Bir tek sana yürüyorum artık.', 'Burada duruyorum artık Ve sadece seni hissediyorum. Tüm yüzleri çamura bulayarak Sadece seni izliyorum şimdi. Sesindeki o ilk bahar coşkusun...', ARRAY['Türk Edebiyatı','Şiir','Şair Dilenci']::text[], 8.5, '{"poet":"Şair Dilenci","poet_slug":"sair-dilenci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/burada-duruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ard Arda', 'ard-arda-nazan-i-zmirli-miwaw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'herşey ard arda 

kovalamacada

doğum büyümeyle

büyüme gelişmeyle

sorular cevaplarla

yaşam zamanla

kovalamacada

zaman kayarken tabanlarımdan

yorgun

buz pistinde dansetmek 

zamana nisbet

sonra diz çöküp,gitme; demek mi

yoksa! 

kovalamacada

önden koşmak mı zamana 

Nazan İzmirli-26.10.2005-antalya', 'herşey ard arda  kovalamacada doğum büyümeyle büyüme gelişmeyle sorular cevaplarla yaşam zamanla kovalamacada zaman kayarken tabanlarımdan y...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ard-arda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Ve Ölüm', 'yasam-ve-olum-sair-dilenci-me4ei', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanki daha her şeyi yaşamamış gibiyim

Bir şeyler eksikmiş gibi bilmiyorum.

Bir iki acıyı es geçti sanki kader

Yada geçmedi de bana çok hafif geldi kimbilir.

Yeryüzündeki acıların hepsi seyir defterimde

Ayrılıklar, hasretler, yokluklar, ölümler.

Hayatım hep ikilemlerde

Çelişkiler içinde iki insan yaşadığım

İki hayat, iki savaş, iki kavga...

Ve iki insan var hep özlediğim.

İki deniz kaldı şimdi hatırlarda

Biri sakin diğeri fırtınalı iki efsane

Şimdi ne zaman dalsam uzaklara

İki yürek hatırlıyorum

Yarım kalan iki hikaye

İki kar çiçeği

Ve iki kardeş hatırlıyorum.

Öyle bir acıyla yalnız kaldım ki

Her yanım yangınlar içinde..

Kader en acımasız dönemeçte

Bütün yağmurlar üzerime yağıyor

Yazılanlar hep aynı cümlelere mahkum kalıyor.

Sebepsiz diyemiyorum

Ölümde güzeldir elbet.

Peki ben neresineyim hayatın

Daha çıkacağım kaç basamak var

Daha kaç ölüme şahit gösterecek kader beni

İşlenecek kaç günah var daha.

Bir gün unutabilecek miyim  bunları.

Elbette ölümde güzeldir diyorum

Öyle olmasa ölürmüydü beni sevenler

Ölürmüydü sevdiklerim

Böyle yalnız kalmazdım elbette.

İki hayat var şimdi aklımda

Özlediğim iki çift ela göz var

Göz kapaklarımda resimleri

Ve beklediğim bir tek ölüm var

Adım adım yaklaşan o on nefes var aklımda.

Acaba diyorum “yaşamak mı ölmek? ”

Yoksa “ölmek mi yaşamak? ”

                              Onuda bilmiyorum….', 'Sanki daha her şeyi yaşamamış gibiyim Bir şeyler eksikmiş gibi bilmiyorum. Bir iki acıyı es geçti sanki kader Yada geçmedi de bana çok hafif...', ARRAY['Türk Edebiyatı','Şiir','Şair Dilenci']::text[], 8.5, '{"poet":"Şair Dilenci","poet_slug":"sair-dilenci","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yasam-ve-olum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Adımlar', 'yorgun-adimlar-sair-dilenci-l7iq6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adım adım yürüyorum bu yollarda

Her adımda anıları yitiriyorum.

Elbet bir iz kalacak ardımdan

Elbet susayıp bir damla yağmura 

Bu çöllerde kimsesiz kalacağım

Yada hep geç kalacağım ikindi vakitlerine.

Adım adım yitiriyorum gençliğimi.

Her ayak sessinde yaşlanıyor ümitlerim,

Elbet acı verecek bu yorgun satırlar

Elbet yitik bir aşkın yasını tutacağım sonunda

Yada her aşkı bir bir kusacağım bu satırlara.

Günden güne daha da soluyor güllerim

Tutunamaz oldum artık buralara

Alışkanlıklar bütün isimlerini değiştirmiş yaşamın

Herkes kendi sahasında iç yarası

Her gülüş gözlerde derin bir hayal kırıklığı

Mevsim desen çoktan şaşırmış duraklarını.

Hissedilen sadece günbatımı buralarda….

Asırlardır kayboluyorum bu kalabalıkta

Yaşayandan bir ölüyü oynuyorum

Ama hep kaybederek.

Büyüyorum 

           Ama hep daha da küçülerek

                     Ve de hep karıştırarak.

Adım adım yürüyorum bu yollarda

Her adımda kendimi terk ediyorum

Her adımda korkularıma yaklaşıyorum

Yollarını şaşırarak hayatın

Ve de hep yaşlanarak

            Yürüyorum bu yollarda…….', 'Adım adım yürüyorum bu yollarda Her adımda anıları yitiriyorum. Elbet bir iz kalacak ardımdan Elbet susayıp bir damla yağmura  Bu çöllerde k...', ARRAY['Türk Edebiyatı','Şiir','Şair Dilenci']::text[], 8.5, '{"poet":"Şair Dilenci","poet_slug":"sair-dilenci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yorgun-adimlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüşen Mevsim', 'donusen-mevsim-sair-dilenci-il13n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçmişimi kimse bilmez

Sayıkladıklarım dışında.

Günahlarımı söküp atamıyorum

Bir yerde ya ecelim oluyor

                 Yada kabuslarım..

Yalnızca avuntular var bu güz ikindisinde

Yalnızca kırık dökük bir mevsim var.

Sevinçlerim ilkbahara karışmış sanki 

                     Yüzüm gülmez oldu artık.

Kaç zamandır aynıyım hep

Hep aynı kararsızlıklarım

Acılarım hep aynı 

Dalıp dalıp gitmelerim

Anlık yok oluşlarım hep aynı.

Bilmiyorum değişen benmiyim

             Yoksa dönüşen hep aynı mevsimi? 

Kaç zamandır aynı çukurdayım

Alabildiğine derin

Alabildiğine soğuk

Ben ne kadar kaçsamda

            Aslında hep aynı yerdeyim.

Bir tek umutuzluğum değişmedi

     Birde satırlardaki yalvarışlar.

Şimdi seni sayıklıyorum

Ulaşılmadığını bile bile

                İmkansızlığını hissederek

                Bir tek seni görüyorum gökyüzünde

                Yıldızların uzanamadığı en son nefesinde gecenin

                Karanlığın çaresiz kaldığı aydınlıktasın

                Biliyorum hep ordasın.

Şimdi saçma sapan olmuş alışkanlıklar

Bakışlarım saçma sapan

Terk edilişler, ağlamalar, 

Uyanışlarım hep saçma sapan.

Artık kime baksam hep dumanlı yüzler

Neye dokunsam hep yalan dokunuşlar

           Dedim ya şimdi seni düşünüyorum

           Sebepsiz, umutsuz ama hep daha da pişman….', 'Geçmişimi kimse bilmez Sayıkladıklarım dışında. Günahlarımı söküp atamıyorum Bir yerde ya ecelim oluyor                  Yada kabuslarım.. Y...', ARRAY['Türk Edebiyatı','Şiir','Şair Dilenci']::text[], 8.5, '{"poet":"Şair Dilenci","poet_slug":"sair-dilenci","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/donusen-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bandırma Vapuru''nda Biri Vardı', 'bandirma-vapuru-nda-biri-vardi-suleyman-tunc-m1bhj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bandırma Vapuru''nda biri vardı.

Azimli

Ve kararlı.

Denize dönmüştü yüzünü.

Aldırmıyordu azgın dalgaların hırçınlığına.

Gök mavisiydi gözleri,

Gece karanlığına inat.

Çöken bir vatanı yüklemişti sırtına.

Türklüğün hamalıydı.

Bandırma Vapuru''nda biri vardı.

Adı...

Mustafa Kemaldı.

Samsun''da biri vardı.

Kuruyan toprağın su,

Kundaktaki bebeğin ekmek,

Ağlayan ananın umut aradığı an.

Samsun''da biri vardı,

Mayıs ortasıydı zaman.

Ve Samsun''da biri vardı.

Adı...

Mustafa Kemal''dı.

Sakarya''da biri vardı.

Elinde sigara,

Başında kalpak.

İtaat ediyordu heybetine,

Mehmetleri şehit,

Fatmaları yiğitlikle ödüllendiren dağlar.

Suların köpüğünde arınıyordu,

Zulmün bıraktığı kir.

Ve,...

Sakarya''da biri vardı.

Adı...

Mustafa Kemal''dı.

Ankara''da biri vardı.

Gün doğuşunu andırıyordu saçları.

Elinde kalem,

Üzerinde simokin.

Ağartmıştı isyankar geceyi.

Ağıt yakmıyorlardı artık,

Gidenlerin arkasından analar.

Gülümsüyordu toprak.

Gülümsüyordu vatan.

Ankara''da biri vardı,

Tanrı lütufu insan.

Ve,...

Ankara''da biri vardı.

Adı,

Mustafa Kemal''dı.', 'Bandırma Vapuru''nda biri vardı. Azimli Ve kararlı. Denize dönmüştü yüzünü. Aldırmıyordu azgın dalgaların hırçınlığına. Gök mavisiydi gözleri...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Tunç']::text[], 8.5, '{"poet":"Süleyman Tunç","poet_slug":"suleyman-tunc","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/bandirma-vapuru-nda-biri-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öksüz Gül', 'oksuz-gul-hamdi-oruc-1xy1u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başında en zalimi eylüllerin

Gül nasıl dirensin eylüle

Yaprak yaprak açan gül

Yüzümdeki gülücük nerde

Elimdeki cömertlik

Dilimdeki ışık gitti...

Git öksüz gül masal ülkesinde aç

Orda kokular saç

Güzel koku saçarak yaşadın sen hep', 'Başında en zalimi eylüllerin Gül nasıl dirensin eylüle Yaprak yaprak açan gül Yüzümdeki gülücük nerde Elimdeki cömertlik Dilimdeki ışık gitt...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Oruç']::text[], 8.5, '{"poet":"Hamdi Oruç","poet_slug":"hamdi-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oksuz-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yediveren', 'yediveren-sair-dilenci-sjqtr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşadıkça o büyük depremleri

Yok olan sadece var oluşum değildi.

Aydınlığı sönüyordu umutların

Ve ben hep aynı karanlıklardayım

Dibe vurunca bütün vazgeçilmezliğin

          Ben her gece seninle demleniyorum.

                  Ve sen bilemezsin böylesi sarhoşluğu…

Düşündükçe 

          Daha çok sıyrılıyorum yaşamaktan

                                                Yaşlanmaktan…

Biliyorum ne kadar solsam

Senin o yediveren sularında

Sen hep yeniden ekiyorsun beni.

Hiç bıkmadan ve de usanmadan

                         Hep yeniden açıyorsun beni.

Kim bilir belki de seni vazgeçilmez yapan buydu

                                 Yada daha da imkansız………..', 'Yaşadıkça o büyük depremleri Yok olan sadece var oluşum değildi. Aydınlığı sönüyordu umutların Ve ben hep aynı karanlıklardayım Dibe vurunca...', ARRAY['Türk Edebiyatı','Şiir','Şair Dilenci']::text[], 8.5, '{"poet":"Şair Dilenci","poet_slug":"sair-dilenci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yediveren-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi', 'mavi-sair-dilenci-mapmt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kadar avunsam 

      Ve de avutsam kendimi boş.

Bunlar hep yalancı doğuşlar.

Kim hayat verir şimdi bu topraklara

         Oysa bir yanım hep sağnaklar içinde..

Şimdi dönüp dolaşıyor bu soluksuz kader

Aldanan yok bu çaresizliklerime..

Herkes doğacak güneşin peşindeyken

Ben hep maviyi özlüyorum bu çöllerde

               Maviyi ve tenindeki o deniz kokusunu..

Binbir özlemler içinde kavrulurken

Ben en çok 

             Yüzündeki o batmayan doğuşu özlüyorum……..', 'Ne kadar avunsam        Ve de avutsam kendimi boş. Bunlar hep yalancı doğuşlar. Kim hayat verir şimdi bu topraklara          Oysa bir yanım ...', ARRAY['Türk Edebiyatı','Şiir','Şair Dilenci']::text[], 8.5, '{"poet":"Şair Dilenci","poet_slug":"sair-dilenci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mavi-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Almanya Mektubu', 'almanya-mektubu-suleyman-tunc-t2i5m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gezindim, dolandım, gördüğüm o ki,

Amirin boluğu Alamanya''da.

İçki, kumar, fuhuş,...pisliğindeki,

Memurun bolluğu Alamanya''da.

Zaman bile iğrenç boşuna akmaz.

Aç-susuz kalırsın kimseler bakmaz.

Freulein yakamı tutmuş bırakmaz.

Ömürün bolluğu Alamanya''da.

Dazlaklar yol keser amaç dövüşmek.

Kadınlar sokakta ister sevişmek.

Benimse dileğim yurda kavuşmak.

Çamurun bolluğu Alamanya''da.

Bırakın buzları eriye dursun.

Sorunlar diz boyu, geriye dursun.

Biz Türkler işinde farıya dursun.

''''Kemir''''in bolluğu Alamanya''da.

Fabrika öksürür sis olup durur.

Ne kimse dert eder, ne kimse korur.

''''Çevreci''''haybeden atıp savurur.

Kömürün bolluğu Alamanya''da.

İnsanı kalıplı, insanı zinde.

Hamburger yenilir hemi her günde.

Yanıma gelirsen görürsün sende.

Hamurun bolluğu Alamanya''da.

İzaha gelmezki dahası neler.

Koyun ağılında domuzlar meler.

Sapıklarla dolmuş hapishaneler.

Demirin bolluğu Alamanya''da.

İnsanlar değişik, Hans, Helga, Helen.

Dilini öğrenmek esas zor olan.

Er, Sie, Es benlardan aklımda kalan.

Zamirin bolluğu Alamanya''da.', 'Gezindim, dolandım, gördüğüm o ki, Amirin boluğu Alamanya''da. İçki, kumar, fuhuş,...pisliğindeki, Memurun bolluğu Alamanya''da. Zaman bile iğ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Tunç']::text[], 8.5, '{"poet":"Süleyman Tunç","poet_slug":"suleyman-tunc","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/almanya-mektubu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar  - Rüya -', 'ruzgar-ruya-i-sa-sari-ipir2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimsenin görmediği bir rüyadan uyanıp

Kimsenin duymadığı bir rüzgarı dinle

Alıp başını uzaklara git

Sen sana nasıl bakarsan öyle görsün gözlerin

Kimsenin duymadığı bir tebessümle gül

Yanına ekmek ve tuz almadan

Ve sigara ve çay olmadan bir orman kuytusunda esrarengiz

Gemiler geçerken akşamüstleri güneş parıltısıyla

Boğazda parlayan dalgalara dalıp git

Bir hüzün bir tebessüm 

Bir muhteşem mavilik 

Ve senin yüreğin 

Derin koyu mavilikler kadar büyük 

Ve günbatımı ve ayrılık

Ve senin yüreğin gökyüzü kadar güzel

Ve senin gözlerinde gökyüzü.........', 'Kimsenin görmediği bir rüyadan uyanıp Kimsenin duymadığı bir rüzgarı dinle Alıp başını uzaklara git Sen sana nasıl bakarsan öyle görsün gözl...', ARRAY['Türk Edebiyatı','Şiir','İsa Sarı']::text[], 8.5, '{"poet":"İsa Sarı","poet_slug":"i-sa-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruzgar-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dü/et', 'du-et-yasemin-sezer-tulgar-xr8dh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'karalardan 

nefesim

soluğunla

(s) aklandı

ağızında

ıslandı

yemiş

dudaklarım

iki

taptığım sayı

afiyet olsun

dü/etimize

26.10.05', 'karalardan  nefesim soluğunla (s) aklandı ağızında ıslandı yemiş dudaklarım iki taptığım sayı afiyet olsun dü/etimize 26.10.05...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/du-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sehere Varana', 'sehere-varana-yasemin-sezer-tulgar-b52ma', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tercih ettik

Harsız uykulara

Kor ıraklıkları

Yar/asa bilse

Dokun/m/aklı duvarlarımda

Parmak uçları

Söndürmesini de bildik

Masalsı solukla

Yaktığımız şehirlerin tayfını

Yankılanıyor sehere

Kanat çırpışlarında

Uçarı “ah” ları

25.10.05', 'Tercih ettik Harsız uykulara Kor ıraklıkları Yar/asa bilse Dokun/m/aklı duvarlarımda Parmak uçları Söndürmesini de bildik Masalsı solukla Ya...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sehere-varana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firûze – Leylâ ve Mevlâ', 'fir-ze-leyl-ve-mevl-zafer-sik-aae6l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Leylâ; iki “lâm”, iki “ye”

Leylâlar gider

Mevlâ kalır geriye! 

İnsân sevmeyince ölür Firûze

Bir kalp yetmiş kâbe, kırarız neden? 

Ve insân sevdikçe büyür Firûze

Vermek için varız, alırız neden? 

Dermân olur

Her Nebevî söz:

“Kader gelince kör olur göz! ”

Güneş ancak akşam batar Firûze

Karanlığa düşer bir dervişân söz

Vuslat damla damla akar Firûze

Sana esir kalbin miâdı sonsuz! 

“Zaman gösterdi ki

__________ Cennet ucuz değil”

Kişi sultan da olsa hür değil! 

Bakmışız kapıda bir kara mevsim

Kendi aşımıza zehir katmışız! ..

Yediden yetmişe yıpranmış resim

Dünyâ yaldızlı kız, sevip batmışız! 

Ve Firûze

Günâh elde kir

Tevbe göze nur...

Ve Firûze

Çıkmak için düze

Duâ duâ

Dermân gerekir günâhlarımıza! 

Sevgi Yolu - Kasım 2005 / 55. Sayı

Kainata Mektup - Mart 2006', 'Leylâ; iki “lâm”, iki “ye” Leylâlar gider Mevlâ kalır geriye!  İnsân sevmeyince ölür Firûze Bir kalp yetmiş kâbe, kırarız neden?  Ve insân s...', ARRAY['Türk Edebiyatı','Şiir','Zafer Şık']::text[], 8.5, '{"poet":"Zafer Şık","poet_slug":"zafer-sik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/firuze-leyla-ve-mevla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Kalmak', 'sensiz-kalmak-nazan-i-zmirli-7mo8j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bugün  sensiz  kalmak  istedi 

sensizliği  tatmak  istedi  gönlüm

kalbimin  sesini  dinledim

özgür olmak istedim.

ne bilirdim öfkenin dayanılmazlığını

fırtına oldun,kasırga oldun

başladın vurmaya kapalı kapılara

ıslıklar çalmaya başladın,titreyen camlarıma.

önce korktum,ürktüm,bu da ne zamansız dedim

sonra bir an düşündüm, öfkenin zamanımı olur 

sendin; 

etrafı kasıp kavuran,kalbimin sesine isyanları yağdıran

taş taş üzerinde bırakmayan,toz duman koşan

anladım bir kez daha anladım ki

sensiz kalmak değil, düşünmek dahi anlamsız

nasıl seninle olmak istedikçe,

günüme güneş,geceme samanyolu oluyorsan

istemedikçe,hırçınlaşan kasırga                                             

köpük köpük dalgalar olursun                                                    

doğanın  sesiyle türküler çağırırsın 

bensiz olmak yok dercesine.........

Nazan İzmirli- 12.12.2004-antalya', 'bugün  sensiz  kalmak  istedi  sensizliği  tatmak  istedi  gönlüm kalbimin  sesini  dinledim özgür olmak istedim. ne bilirdim öfkenin dayanı...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensiz-kalmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Don Quixote ve ZaZü', 'don-quixote-ve-zazu-yasemin-sezer-tulgar-cn2m8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“Don Quixote” mükemmel muhteviyatı aradı

Buldu sandı...

Dulcinea soluklu “ZaZü”

“Kadın Don Quixote” asıl adı

2 Don bir ipte durmazdı

“Don Quixote” kaçtı

“ZaZü” dürüst/hasta

Hatta çokça algın

Yeldeğirmenli tarlalara uzandı

Es rüzgar! 

Savur! 

Savur deliliğimizi

“Rozinante” de delirdi

Bak koşuyor...

Hey “Sancho Panza”! 

Hadi kaldır beni...

07.08.2005

14:46

.........ZaZü: takma isim...', '“Don Quixote” mükemmel muhteviyatı aradı Buldu sandı... Dulcinea soluklu “ZaZü” “Kadın Don Quixote” asıl adı 2 Don bir ipte durmazdı “Don Qu...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/don-quixote-ve-zazu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Rüya Gibi', 'bir-ruya-gibi-nazan-i-zmirli-tnhnb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sensiz olmak, bir oyun gibi

sonsuzluğun derinliklerinde

sensiz olmak,sessiz olmak

yokluğun değerlerinde.

sensiz olmak,ölüm ömür boyu

can çekişmenin pençesinde

sensiz olmak,anmadan yaşamadan

duygularda düşlerde seni tatmadan.

sensiz olmak, bir oyun gibi

alacakaranlıkta emeklemek

ay ışığında saklambaç

gün doğumunda,bu oyuna son vermek 

bir rüya gibi.............

Nazan izmirli-18.10.2005-antalya', 'sensiz olmak, bir oyun gibi sonsuzluğun derinliklerinde sensiz olmak,sessiz olmak yokluğun değerlerinde. sensiz olmak,ölüm ömür boyu can çek...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-ruya-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım sana varsın gitsin', 'canim-sana-varsin-gitsin-mikdat-bal-ijzo1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölmek için yaşıyorum

Canım sana varsın gitsin

Seven bir kalp taşıyorum

Kanım sana varsın gitsin

Dertlerimi sen hallettin

Rızık verdin halal ettin

Doğru yola sen ilettin

Yönüm sana varsın gitsin

Ömür verdin ibadette

Darlıkta ve saadette

Her mescitte her mabette

Anım sana varsın gitsin

Esmanda ki Rahman ile

Rahmetini güman ile

Son nefeste iman ile

Sonum sana varsın girsin', 'Ölmek için yaşıyorum Canım sana varsın gitsin Seven bir kalp taşıyorum Kanım sana varsın gitsin Dertlerimi sen hallettin Rızık verdin halal ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/canim-sana-varsin-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığın İçinden', 'karanligin-i-cinden-nazan-i-zmirli-e4vza', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'karanlıklar ürkütürdü beni,seninle tanışmadan

oralar ıssız,soğuk,korku tüneli gibi acımasız

geceler üzerimde  yün yorgan                                         

anlamını veremediğim sesler karabasan 

karanlıklar gece gelir,  basar boğar

şafaklara ulaşır senden kaçar

ne bilirdim, birgün  gün ortasında güneş başımda

karanlıklar, sabahları olmayan karanlıklar içinde kalacağımı

anlam veremedim,akşam karanlıklarına kavuşsam dedim

bitmiyordu gün,bitmiyordu gün karası, çaresizdim

bir değil bin ışık belirdi birden

simsiyah gökyüzü,avuçlarımın içinde yıldız cümbüşü gibi

karanlıklar içinden çıktın geldin,

önce avuçlarımı aydınlattın  ödüllendirircesine

avuçlarımı gün karasının gölgelediği yüzüme kapattım

gitme diye! 

Tanrım,beni asla terketmedin,ben seni istedikçe

karanlıklar aydınlandı,karabasanlar kayboldu

karanlıkların içinden çıktın geldin

ruhumun derinliklerinde gizlendin gitmemelicesine

Nazan İzmirli-1990-Trb', 'karanlıklar ürkütürdü beni,seninle tanışmadan oralar ıssız,soğuk,korku tüneli gibi acımasız geceler üzerimde  yün yorgan                    ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/karanligin-icinden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hisset', 'hisset-nazan-i-zmirli-75elf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tanıdık bir rüzgara rastlarsan

avucuna al hisset...................

öp  ki   üşümüşlüğü   geçsin

esmek   kokunu   bana 

getirmek için..........................

Nazan İzmirli -25.09.2005-antalya', 'tanıdık bir rüzgara rastlarsan avucuna al hisset................... öp  ki   üşümüşlüğü   geçsin esmek   kokunu   bana  getirmek için..........', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hisset-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abdürrahim Karakoç', 'abdurrahim-karakoc-cihan-kaya-qcr0l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üstadıma hitaben....

Saygılarımla.....

Aşk tarifsiz tarif, adı Mihriban

Bu derde düşersen adın Gariban

Dünya düzenine, düzen kuruyor

Ümidin yaşlansa üzen kuruyor

Resmedip saklanır açık gözlerde

Rabbe duadır tüm kötü sözlerde

Akıl baştan gider, sen de senden

Hüküm giyer huzur, bol gelir enden

İmkan yok, kalp varsa, aşktan kaçarı

Menzil gözden gönle, düşten uçarı

Kendini bulursun derdin içinde

Aşk geldimi, dünya hiç mi hiçinde

Ruh baksa görmüyor, gölgede gölge

Aşığa hasreti buldurmaz bölge

Kanar göz damlamaz akarsa zaman

O zaman tutulur dökülür derman

Çözülüyor kör düğüm..................

Bu şiir asla bitmemeli....', 'Üstadıma hitaben.... Saygılarımla..... Aşk tarifsiz tarif, adı Mihriban Bu derde düşersen adın Gariban Dünya düzenine, düzen kuruyor Ümidin ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/abdurrahim-karakoc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün hesap soracağım', 'bir-gun-hesap-soracagim-mikdat-bal-h2md6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözüm sözdür yemin olsun

Herkes bundan emin olsun

Fırsat geçsin zemin olsun

Bir gün hesap soracağım

Dünyada hem vatanımda

Yaşadığım her anımda

Yoksa bir el tutanım da

Zulme karşı duracağım

Soysuzların dalgasını

Migferini tolgasını

Zincirin her halkasını

Teker teker kıracağım

Geleceğim hak ederek

Rantçıları şok ederek

Zulmü kökten yok ederek

Yeni dünya kuracağım', 'Sözüm sözdür yemin olsun Herkes bundan emin olsun Fırsat geçsin zemin olsun Bir gün hesap soracağım Dünyada hem vatanımda Yaşadığım her anım...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gun-hesap-soracagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlenendir', 'ozlenendir-nazan-i-zmirli-4qmth', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'uzaklar  özlenendir  dokunamasanda

uykusuz  gecelerime  ninnidir  sesin

kokun  rüzgarla  gelen  nefesim

adını  koyamadığım

binbir  kır  çiçeği

kokusu  tadıyla

şafaklarıma  sunduğun

kokun  kaldı  tenimde

doyamadığım..............

Nazan İzmirli-22.10.2005-antalya', 'uzaklar  özlenendir  dokunamasanda uykusuz  gecelerime  ninnidir  sesin kokun  rüzgarla  gelen  nefesim adını  koyamadığım binbir  kır  çiçe...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ozlenendir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanan', 'yasanan-nazan-i-zmirli-uumpx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaşanan kısacık anlar

paylaşılan   tatlar

kalın ve uzun bir roman

ömür boyu anlatacak

yüreğimde taşıyacak kadar...

Nazan İzmirli-01.01.2005-antalya', 'yaşanan kısacık anlar paylaşılan   tatlar kalın ve uzun bir roman ömür boyu anlatacak yüreğimde taşıyacak kadar... Nazan İzmirli-01.01.2005-...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yasanan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk muydum O Gece', 'cocuk-muydum-o-gece-agah-adiguzel-g0n6e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Parıltılı bir su türkü söylüyor,

Yaylanın  ayazına karşı

İlkyaz bulutları suya dokunuyor,

Ve sudan bir ışık düşüyor gözlerime

Gençliğim bakıyor karşı tepelerin ardından

Ay okşuyor alnımı

Altın bir tepsiye dönüşüyor gökyüzü

Ağzımda ekşimsi tadı dolaşıyor gecenin

Delikanlılığımın uçarı bulutları

Çimenlere düşüyor.

Gitgide koyulaşan bir hüznü çağırıyor.

Ve dokunarak yaşamın saçlarına

koynuna alıyor.

Serin bir yaz gecesini.... 

Sonra gün ışığına binip

Kuşluk vakti ay yolculuğuna çıkıyorum.

Baharın bin bir renginde atlarla

Şaha kalkıp yıldızlara sürüyorum.

Ve yeniden başlıyorum çocukluğuma

Uzun kış gecelerinin nerede başlayıp

Nerede bittiğini 

Kar yığınlarının neden erimediğini

Sorguluyorum durmadan

İliklerimi donduran soğuğu

Cebimde sakladığımı düşünüyorum

Ve şaşırıp kalıyorum

Ben aslında çocuk muydum o gece.

Yoksa donan kırağı mıydı kirpiklerimde

Anıları bir bir yoklasam

Alsam içlerinden oyuncaklarımı

Karpuz kabuğundan arabamı

Yüklesem çilelerimle

Ve dönüp baksam gökyüzüne

Harman zamanı uykularımı sakladığım

Buğday ambarına

 ve durmadan dönen uçurtmama 

takılıyor ellerim.

Sonra oturup ninemin dizlerine

Bir masal anlat diyorum

Kaf dağının ardında mıyım 

Ağlayan nar gülen ayvada mıyım.

Ben aslında çocuk muydum o gece.', 'Parıltılı bir su türkü söylüyor, Yaylanın  ayazına karşı İlkyaz bulutları suya dokunuyor, Ve sudan bir ışık düşüyor gözlerime Gençliğim bakı...', ARRAY['Türk Edebiyatı','Şiir','Agah Adıgüzel']::text[], 8.5, '{"poet":"Agah Adıgüzel","poet_slug":"agah-adiguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/cocuk-muydum-o-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman/Arınma', 'zaman-arinma-yasemin-sezer-tulgar-l5lq3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayırmalı bazen

İtmeli bir kenara yükleri

Zihin bağlarını koparmalı

Serbest kalmalı us dedikleri

Pirüpak bir beyine boşalan

İyileri doldurmalı sade

İyi gelenleri

Şakaklar pamuk olmalı

Hassas olmalı her ısı değişimine

Çıplak düşünmeli

Düşürmeden kor/donları

Esnemeli beden

Şöyle “oh” dedirtircesine

Sormadan nedir, neden

Zamanı yarmalı göbeğinden

Safralarını boşaltmalı

Hatta yakmalı

İçinden parlak inciler çıkarmalı

Arındırmalı kumundan kirinden

Yerleştirmeli sonra 

İtinayla 

Tek tek boşluğuna

Yarığı sim ilmeklerle dikmeli

Gezinirken avuç içleri

Tertemiz üzerinden

Hiç yarılmamış gibi

Kaynamalı zaman 

Yeniden

Sormadan nedir, neden

24.10.05', 'Ayırmalı bazen İtmeli bir kenara yükleri Zihin bağlarını koparmalı Serbest kalmalı us dedikleri Pirüpak bir beyine boşalan İyileri doldurmal...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/zaman-arinma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-fedai-koc-xb91l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öğretmenim sana kurban olayım

Evladımı okut bizi öğrensin

Onlar okusunda ben aç kalayım

Okuma öğrensin yazı öğrensin

Bu vazife kutsal, omzunuzda yük

Dünyada ahrette ödülün büyük

Cehaletin yüzü her yerde soğuk

Ana’yı baba’yı sizi öğrensin

Yüce Allah emrediyor okuyun

Çocukları nakış nakış doku’yun

Örettikce siz onlardan haz duyun

Oğlanı öğrensin kızı öğrensin

Okumakla döner dünyanın çarkı

Okursa cahilden olacak farkı

Dünyada korktuğum sadece korku

Cesaretle ilme hazı öğrensin

Tarihi örensin tarih dersinde

Coğrafyada gezsin venüs mars’ında

Öğret Edirnede öret Kars’ında

Türkçe dersde dili’mizi öğrensin

Tarihinde yazar parlak mazi’si

Okusunlar nedir şehit gazi’si

Türkiyenin bunlar alın yazısı

Ocakta ateşi közü öğrensin

Tekerür etmesin hatalarımız

Atatürk’ümüzle ata’larımız

Bizi kurtaracak yarınlarımız

Astarı öğrensin yüzü öğrensin

Öğretmenim sensin derdime doktor

Yunus Emremizin yararı çoktur

Batı müziğinin yararı yoktur

Ozan fedai`yi sazı öğrensin...

©zan Fedai

25.09.2005 Almanya

Okulların yeni ders yılına başladığı bu günlerde

Vefakar öğretmenlerime hediyem olsun istedim.

Cümle öğretmenlerime selam ve hürmetlerimle...', 'Öğretmenim sana kurban olayım Evladımı okut bizi öğrensin Onlar okusunda ben aç kalayım Okuma öğrensin yazı öğrensin Bu vazife kutsal, omzun...', ARRAY['Türk Edebiyatı','Şiir','Fedai Koç']::text[], 8.5, '{"poet":"Fedai Koç","poet_slug":"fedai-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ogretmenim-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazırmısın İsmail', 'hazirmisin-i-smail-fedai-koc-gb559', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Almadıkca Allah bizden bu canı

Yağmur gibi yağacağız İsmail

Bayrağı,Vatanı yüce kur’anı

Ömür boyu öğeceğiz İsmail

Lüzum yok kedere gama tasaya

Tokat vurulacak tokat aklı köseye

Vurulursa yumruk birgün masaya

Güneş gibi doğacağız ismail

Bal tutanın parmağından balını

Kurtarıp yetimin dulun malını

Devletimi soyanların kolunu

Birlik olup eğeceğiz İsmail

Taşa çalıp şöhretleri şanları

Yerde kalmaz şehitlerin kanları

Mehmedi o ateşe salanları

Gırtlaklayıp boğacağız İsmail

Hedefimiz Turân,Ülkü‘m aracı

Vatan,Kur’ân daim; insan kiracı

Yeri geldiğinde gelsede acı

Zülfüyâre değeceğiz İsmail

Sırtımıza saplanan bıçakları

Her telde oynayan köçekleri

Vatanımı satacak alçakları

Evel Allah koğacağız İsmail

Türk’üz müslümanız beri gel beri

Türk oğlu Türk olur sözünün eri

Kâhyanın elinden alıp ipleri

Vermezlerse döğeceğiz İsmail

Kim gelirse gelsin gidenden beter

Yeter vatanımın çekdiği yeter

Beraber olunca enseden tutar

Bir tarafa yığacağız İsmail

İşin yok Fedai şöhret, şan ile

Uğrunda vereceğim can ile

Yetmiş milyon birgün bir gönüle

Beraberce sığacağız İsmail

©zan Fedai

22.10.2005 almanya', 'Almadıkca Allah bizden bu canı Yağmur gibi yağacağız İsmail Bayrağı,Vatanı yüce kur’anı Ömür boyu öğeceğiz İsmail Lüzum yok kedere gama tasa...', ARRAY['Türk Edebiyatı','Şiir','Fedai Koç']::text[], 8.5, '{"poet":"Fedai Koç","poet_slug":"fedai-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hazirmisin-ismail-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Ben sana inandım affet Allah’ım', 'a-ben-sana-inandim-affet-allah-im-mikdat-bal-gfq9b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Suçlarım dağ gibi bağışla beni 

Rahmetine döndüm affet Allah’ım! 

Pak eyle bir nurlu yağışla beni 

Ben sana inandım affet Allah’ım! 

Günah işledikçe setredip sildin

Hidayet eyledin tövbekâr kıldın

Her başım döndükçe aklıma geldin

Hemen seni andım affet Allah’ım! 

Kuranı Kerimden bir ayet duydum 

Ramazan boyunca emrine uydum 

Aşını terk ettim aşkınla doydum 

Aşkın ile kandım affet Allah’ım! 

Günahkâr kulunu bağışla Ya Rab 

Eğer affetmezsen, halimiz harap 

Dünya ahrette verme ıstırap 

Güvendim, dayandım affet Allah’ım! 

Ben senin kulunum bir yanaşmanım 

Kör nefsime uydum odur düşmanım 

Tövbe ettim nadim oldum pişmanım 

Gafletten uyandım affet Allah’ım! 

Yolundan ayırma kaydırma bizi 

Rahmet et ateşe koydurma bizi 

Bu nurlu caddeden caydırma bizi 

El açtım uzandım affet Allah’ım! 

Ozan Mikdadî

.', 'Suçlarım dağ gibi bağışla beni  Rahmetine döndüm affet Allah’ım!  Pak eyle bir nurlu yağışla beni  Ben sana inandım affet Allah’ım!  Günah i...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/a-ben-sana-inandim-affet-allah-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sular Bazen Yokuşa Akar', 'sular-bazen-yokusa-akar-kaya-alp-7g3gx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte gene dopdoluyum bugün de; 

      Yağmura gebe bulutlar gibi.

      Ne sevincim belli,ne de kederim.

      Bir tuhaf his ki; sardı rûhumu,

      Anladım; güldürmeyecek beni kaderim.

      Ben ki,bir goncaydım hârler içinde,

      Ümitlerim,hayâlim ummâna akıştaydı.

      Şimdi rûyalarda kalan bir çift güzel göz,

      Kadehime dolan mestâne bakıştaydı...

      O bakış ki; ellerime güneşi değdirirdi...

      O bakış ki; mehtâbı da büyüler,

      Cümlesine yıldızların, baş eğdirirdi.

      Donduğumda ateşim,yandığımda kar''ımdı...

      Gün onunla ağarır,buz onunla erirdi.

      Ne gecem var artık,ne de gündüzüm; 

      Mehtap doğmuş,güneş batmış ne çıkar...

      Sahi; sular, bazen neden yokuşa akar? 

      Onsuz geçen yıllarım,yüreğimde nârımdı, 

      Gönül bahçemde gülüm,benim diğer yarımdı; 

      Arkadaşım,dostumdu; can içre can yârimdi.', 'İşte gene dopdoluyum bugün de;        Yağmura gebe bulutlar gibi.       Ne sevincim belli,ne de kederim.       Bir tuhaf his ki; sardı rûhum...', ARRAY['Türk Edebiyatı','Şiir','Kaya Alp']::text[], 8.5, '{"poet":"Kaya Alp","poet_slug":"kaya-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sular-bazen-yokusa-akar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Özlemi', 'vatan-ozlemi-mehmet-isikoglu-cyg9n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzun yıllar ayrı kaldık vatandan

Sahtelerden bıktık hası özledik

Ayrılık ateşi yakar bir yandan

Bizler sılamızdan ısı özledik

Kaynaşamıyoruz kültürler ayrı

Kaybettik sağlığı çoğumuz sayrı

Susadık vatana sılaya gayrı

Bize su verecek tası özledik

Yaşananlar vahim acı veriyor

Genc nesiller günden güne eriyor

Gönül katlanmıyor gözler görüyor

Devlet erkanında usu özledik

Gözümüzde tüter dağı denizi

Sılamızdan yana döndürdük yüzü

Vatan kucak açmış bekliyor bizi

Gökte dalgalanan süsü özledim

Işıkoğlu vatandaşlar sözcüsü

Çevresinin dikkatli bir gözcüsü

Hayalimiz olayların izcisi 

Bizi çağıracak  sesi özledik', 'Uzun yıllar ayrı kaldık vatandan Sahtelerden bıktık hası özledik Ayrılık ateşi yakar bir yandan Bizler sılamızdan ısı özledik Kaynaşamıyoruz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vatan-ozlemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiirin İçinde...', 'bu-siirin-i-cinde-zulfikar-yapar-kaleli-7pals', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçeriye girsen, dışardan baksan

Sır gülüyor bu şiirin içinde.

Gereksizden  fazla, idraki noksan

Şer gülüyor bu şiirin içinde.

Akıl almazlığın şeref payını

Kiralığa verdim, çekti yayını

Ezber etti, muhteremi, sayını

Gör gülüyor bu şiirin içinde.

Zalimlere giydirecek taç yetmez

İmkânsıza meze diye koç yetmez

Kanun yetmez, ceza yetmez, suç yetmez

Gür gülüyor bu şiirin içinde.

Tur atanlar, tor atanlar burada

Çok atanlar, yel yutanlar sırada

Akıl, fikir, izân, idrâk kirada

Kir gülüyor bu şiirin içinde.

Bir yanda yiğite dar gelen Eruh

Bir yanda sayısız saygısız güruh

Biraz azim, biraz gayret, biraz ruh

Der gülüyor bu şiirin içinde.

Çağdaşlığı terk edeli firavun

“Bana kaldı” diye avun ha avun

Su alıyor gemi, deleni savun

Yer gülüyor bu şiirin içinde.

Yağmur yağar ırmağımız yas tutar

Akıl, fikir zıvanada pas tutar

İdrak, izân birbiriyle küs tutar

Kör gülüyor bu şiirin içinde.

Şiir değil bir bilmece mübarek

Bu işi çözmeye Nuh Nebi gerek

“Ne günlere kaldık,eyvah” diyerek

Er gülüyor bu şiirin içinde.', 'İçeriye girsen, dışardan baksan Sır gülüyor bu şiirin içinde. Gereksizden  fazla, idraki noksan Şer gülüyor bu şiirin içinde. Akıl almazlığı...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bu-siirin-icinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hür - Zelzele Kitabından', 'hur-zelzele-kitabindan-omer-ekinci-micingirt-8kcz7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu semahat ehline bak ne söylüyor ey ahmak 

Kadir-i  zülkemalin yolundaki nur biziz

Nutka gelmiş mevcudat hâk lisânı söyler hâk 

Sikkemiz bir tuğra bir rabbimiz bir er biziz

Rengârenk arza bakan nurefşanı gülüyüz 

Hâkim-i Zülcelâl''in birer mahzun kuluyuz 

Biz vahdete kudrete mecnun âşık deliyiz 

Sikkemiz bir tuğra bir rabbimiz bir hür biziz

Yıldızları seyreyle neyi takrir eylerler 

Mucize-i kudretten aşk-ı nağme söylerler 

Daire-i kudretle emri aşkla boylarlar 

Sikkemiz bir tuğra bir rabbimiz bir var biziz

Kör olası göremez akletmez mi ezelden 

Bestesi esmasından müjdelenen güzelden 

Hû yağıyor heceler muştuluyor tek elden 

Sikkemiz bir tuğra bir rabbimiz bir sır biziz

Buyurdunuz efendim “keşke şair olsaydım”

Şiir nedir şair kim ben bir Tahir olsaydım 

Micingirt ''ten Urfa’ya bir mücahir olsaydım

Sikkemiz bir tuğra bir rabbimiz bir nur biziz', 'Şu semahat ehline bak ne söylüyor ey ahmak  Kadir-i  zülkemalin yolundaki nur biziz Nutka gelmiş mevcudat hâk lisânı söyler hâk  Sikkemiz bi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hur-biziz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennete gider', 'cennete-gider-halil-colak-702fa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin mehtapsız, yıldızsız karanlığında

İslam’ın nur olan yol gösteren aydınlığında

Gönüller derbederde olsa da zaman içinde

İnan masada kul bütün yollar Allaha gider

Bilinmez insanoğlu ne zaman erer kemale

Bir felaketle karşılaşır iman eder Allah’a

Ömür içinde hayatı zillet içindede olsa

Bir tövbeyle kemale erer kul zaman içinde

Boş amaçlar gayeler içinde geçmiştir hayat

Manevi yöndense kendine vermiştir zayiat

Dizinde, gözünde insanın kalmamıştır takat

Tek hakikat Allah olduğunu görür hayat içinde

Kardeşim Allah kula hakkı nasip etmişse eğer.

Sonunda ebedi mutluluk vardır tövbeye değer

Kul en sonunda bütün gönlüyle Allah’a döner

Son nefesinde kelimeyi tevhitle cennete gider

Halil Çolak 26.l0.2005 Ankara saat 02.45', 'Gecenin mehtapsız, yıldızsız karanlığında İslam’ın nur olan yol gösteren aydınlığında Gönüller derbederde olsa da zaman içinde İnan masada k...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cennete-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Bestesi', 'yalnizlik-bestesi-sedat-erdogdu-p71b6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YALNIZLIK BESTESİ

Yıldız yıldız düşerken, mevsimin ilk karları

Dudağımda en kıvrak, İspanyol şarkıları

Gözlerimde Akdeniz, Yüreğimde Toroslar

Balıkçılar toplasın, saçımdaki akları...

Duvarlardan dinledim, ıssızlığın sesini

Kendim çalıp söyledim, yalnızlık bestesini

Kafesinden bıraktım, gökyüzüne kuşları

Başım öne eğildi, seyrettim gölgesini...

Efkar bastı gönlümü, küllerimi savurdum

Yazdığım son mektubu, ezberimden okudum

Karanlıkta mest oldu, kardelen çiçeklerim

Kar üstüne kan düştü, can evimden vuruldum...

Sedat ERDOĞDU', 'YALNIZLIK BESTESİ Yıldız yıldız düşerken, mevsimin ilk karları Dudağımda en kıvrak, İspanyol şarkıları Gözlerimde Akdeniz, Yüreğimde Torosla...', ARRAY['Türk Edebiyatı','Şiir','Sedat Erdoğdu']::text[], 8.5, '{"poet":"Sedat Erdoğdu","poet_slug":"sedat-erdogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yuru-a-ziyan-omrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Uzaksın Bana Çok Uzak…..', 'simdi-uzaksin-bana-cok-uzak-sair-saheser-qk0kv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözpınarlarım kurudu ağlayamadım

Yüreğim sıkıldı boğulacaktım

Anladım geri dönmeyecektin

Ne olurdu izin verseydin baba.

Halimi kimselere anlatamadım

Derdime bir çare bulamadım

Bildiğim her yerde seni aradım

Ne olurdu izin verseydin baba.

İnsanlardan köşe bucak saklandım

Neşeli gözükmek için çok çabaladım

Gözyaşımı hep içime akıttım

Ne olurdu izin verseydin baba.

Ayrılık ne yamanmış bilemedim

Kıymetini yanımdayken anlayamadım

Yoksun artık hiç olmayacaksın

Ne olurdu izin verseydin baba.

Babam, canım babam

Evladının çaresizliğini gör babam

Gör da yüreğindeki zincirleri kır babam

Ne olurdu izin verseydin baba. 

Haykırıyorum artık duy feryadımı

Ne olur duy da dön artık bana

Bitsin bu işkence bu ayrılık

Ne olurdu izin verseydin baba.', 'Gözpınarlarım kurudu ağlayamadım Yüreğim sıkıldı boğulacaktım Anladım geri dönmeyecektin Ne olurdu izin verseydin baba. Halimi kimselere anl...', ARRAY['Türk Edebiyatı','Şiir','Şair Saheser']::text[], 8.5, '{"poet":"Şair Saheser","poet_slug":"sair-saheser","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/simdi-uzaksin-bana-cok-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-dilek-conik-gcp6e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her duraktan geçen ve her durakta duran 

ama inmeyen yolcu olmak istersen eğer bir gün,

güngeldiğinde, işte ozaman anlarsın hislerimi.

Sen olmaktan çıkıp, bir başına 

ve hiç kimse olarak bakmak istediğinde dünyaya

yardımcı olacak sana bu anlatacaklarım.

şimdi fişini çekme zamanı,

kendini şarjetme vakti geldiğinde

bilmediğin kelimelerin sözlüğü olacaktır söylediklerim.

Şimdi susma zamanı,

çünkü zamanı geldiğinde anlayacaksın beni

ve hak vereceksin sensizliğime.', 'Her duraktan geçen ve her durakta duran  ama inmeyen yolcu olmak istersen eğer bir gün, güngeldiğinde, işte ozaman anlarsın hislerimi. Sen o...', ARRAY['Türk Edebiyatı','Şiir','Dilek Conik']::text[], 8.5, '{"poet":"Dilek Conik","poet_slug":"dilek-conik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yolcu-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapsetti Beni', 'hapsetti-beni-nuri-ozoglu-5e02d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle bir hayali güle vuruldum,

Gün be gün aradım, hayli yoruldum,

Bir virane gördüm, hemen kuruldum,

Sorgusuz, yargısız hapsetti beni.', 'Öyle bir hayali güle vuruldum, Gün be gün aradım, hayli yoruldum, Bir virane gördüm, hemen kuruldum, Sorgusuz, yargısız hapsetti beni....', ARRAY['Türk Edebiyatı','Şiir','Nuri Özoğlu']::text[], 8.5, '{"poet":"Nuri Özoğlu","poet_slug":"nuri-ozoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hapsetti-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaştım Anlamadım', 'sastim-anlamadim-mustafa-kemal-bal-7rn4n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sihirli sözlere kandım

Her sözü hakikat sandım

Dara düştüm imdat aradım

Ne oldu şaştım anlamadım

Anladım sa da anlatamadım

Gelecekten umutluydum

Ninnilerle uyutuldum

Bir çözüm bekleyip durdum

Ne oldu şaştım anlamadım 

Anladım sa da anlatamadım 

Bu adamlar hafız gibi

Kürsülerde vaiz gibi

Sermayeye faiz gibi

Ne oldu şaştım anlamadım? 

Anladım sa da anlatamadım

Gelen giden fason biri

Şanslı ama naylon biri

Güya bizden, mason biri

Ne oldu, şaştım anlamadım 

Anladım sa da anlatamadım

Viraneyim kırık, dökük

Ne hak kaldı nede hukuk

Ya Bilge Han ya  Tonyukuk

     

Çok bekledim, bulamadım

Neden, şaştım anlamadım', 'Sihirli sözlere kandım Her sözü hakikat sandım Dara düştüm imdat aradım Ne oldu şaştım anlamadım Anladım sa da anlatamadım Gelecekten umutlu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kemal Bal']::text[], 8.5, '{"poet":"Mustafa Kemal Bal","poet_slug":"mustafa-kemal-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sastim-anlamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '\\..Küpelerim..\\', 'kupelerim-dilek-egri-g1ylw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bize benzettiğim taşlı küpelerim..

biri bir kulağımda parlıyor sen

diğerinin taşı düştü yaslı ben..

ayrıyken arada asık yüzüm

çıkarıp yanyana koyduğumda yüzsüzlüğüm..

kulağıma küpe olsun bu ayrılık

taşım, gözyaşım düş/tü

yalnızım artık..

/.... kimseler bilmez

......süsüme düşkünlüğüm aşkımdandı.../

25/10/05', 'bize benzettiğim taşlı küpelerim.. biri bir kulağımda parlıyor sen diğerinin taşı düştü yaslı ben.. ayrıyken arada asık yüzüm çıkarıp yanyan...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kupelerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutasım Geldi O Güzel Ellerini', 'tutasim-geldi-o-guzel-ellerini-huseyin-erdogan-0dq3b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu gün derin derin düşündüm seni

birdenbire tutasım geldi o güzel ellerini

şiirim sen yanımda değildin ne yazık ki

biliyor musun yokluğun ne denli üzdü beni? 

sevdiğim her zaman sen varsın hayalimde

bir gece bile seni göremezsem düşlerimde

korkarım karabasanlar cirit atar yüreğimde

zaten hüzünlenip duruyorum sensizliğimde

buralarda resimlerinle avutuyorum kendimi

işte budur sana büyük sevdamın tek tesellisi

hayalimde  seninleyimdir rüyamda sen olursun

senin de o harika yüreğin bir tek benimle dolsun

benden başkasına değse bile o muhteşem ellerin

bil ki dayanamaz buna seni delicesine kıskanır  şairin

ölenceye değin ellerim ellerinde gözlerim gözlerinde olsun

sen de bundan böyle yalnızca benim için yaşa ne olursun

                                                            26.10.2005

                                                       Hüseyin Erdoğan', 'bu gün derin derin düşündüm seni birdenbire tutasım geldi o güzel ellerini şiirim sen yanımda değildin ne yazık ki biliyor musun yokluğun ne...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tutasim-geldi-o-guzel-ellerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BABAM’a', 'babam-a-selamet-gundogdu-om54h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BABAM’a

Yere düşen kan damlası

Kalbimden koptuğunu bilircesine

Hüzünle yayıldı yere

Kaç kere

Acımın dindiğini sandım 

Her seferinde yanıldım

Sevgili babam 

Bugün seni andım….

Babam

Hep olmak istediğim adamdın.', 'BABAM’a Yere düşen kan damlası Kalbimden koptuğunu bilircesine Hüzünle yayıldı yere Kaç kere Acımın dindiğini sandım  Her seferinde yanıldım...', ARRAY['Türk Edebiyatı','Şiir','Selamet Gündogdu']::text[], 8.5, '{"poet":"Selamet Gündogdu","poet_slug":"selamet-gundogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/babam-a-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yamur ve Toprak', 'yamur-ve-toprak-selamet-gundogdu-l92r6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her yağmur öncesi

Kararınca gökyüzü

Hüzün kaplar içimi.

Birbirine hasret kalmış

Su ve toprağın 

İçindeki karamsarlık dolar gönlüme.

Sonra

İlk damla düştüğünde

Yerden kalkan toz bulutu

Bir kavuşma anının sevinç çığlığı gibi

Dolar kulaklarıma.

Ve ardından o coşku…

Çığlık çığlığa doyasıya sarılan iki sevgili.

Biliyor musun

Ben bu yüzden kıskanıyorum seli……', 'Her yağmur öncesi Kararınca gökyüzü Hüzün kaplar içimi. Birbirine hasret kalmış Su ve toprağın  İçindeki karamsarlık dolar gönlüme. Sonra İl...', ARRAY['Türk Edebiyatı','Şiir','Selamet Gündogdu']::text[], 8.5, '{"poet":"Selamet Gündogdu","poet_slug":"selamet-gundogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yamur-ve-toprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Direnis', 'direnis-selamet-gundogdu-m0c5b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'DİRENİŞ

Bin kere çıktınız karşıma

Bir kere yere eğmedim başımı

Terk etmeden toprağımı taşımı

Bir lokma yedirmedim size aşımı.

Sizler çoktunuz

Bense tek

Ama ben cesurdum

Sizler ürkek.

Çok düşündüm sizlerle uğraşmayı

Ama babam yasak etmişti

BULAŞMAYI…', 'DİRENİŞ Bin kere çıktınız karşıma Bir kere yere eğmedim başımı Terk etmeden toprağımı taşımı Bir lokma yedirmedim size aşımı. Sizler çoktunu...', ARRAY['Türk Edebiyatı','Şiir','Selamet Gündogdu']::text[], 8.5, '{"poet":"Selamet Gündogdu","poet_slug":"selamet-gundogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/direnis-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadakat', 'sadakat-selamet-gundogdu-uqw55', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sadakat

Bir gün beni öldüreceksin

Her gün daha fazla kemireceksin

Damarımı,kalbimi,ciğerimi…

Hep vazgeçmeyi umacağım senden

Defalarca terk edeceğim.

Lanetler okuyacağım adına…

Sonra,

Bir bardak bira içince

Yine sana döneceğim.

Ahh! ...   Sigaram,

Senden vazgeçemeyeceğim', 'Sadakat Bir gün beni öldüreceksin Her gün daha fazla kemireceksin Damarımı,kalbimi,ciğerimi… Hep vazgeçmeyi umacağım senden Defalarca terk e...', ARRAY['Türk Edebiyatı','Şiir','Selamet Gündogdu']::text[], 8.5, '{"poet":"Selamet Gündogdu","poet_slug":"selamet-gundogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sadakat-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük İçin Karar Senin', 'ozgurluk-i-cin-karar-senin-mustafa-kemal-bal-gdvlo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ya boğuşup dirileceksin

Ya da küsüp esir olacaksın

Mücadele edersen  destanlar yazar

Küsersen esir olup çok mezarlar kazarsın

                                        

                     (Irak, Filistin üzerine)', 'Ya boğuşup dirileceksin Ya da küsüp esir olacaksın Mücadele edersen  destanlar yazar Küsersen esir olup çok mezarlar kazarsın               ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kemal Bal']::text[], 8.5, '{"poet":"Mustafa Kemal Bal","poet_slug":"mustafa-kemal-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ozgurluk-icin-karar-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teselli', 'teselli-selamet-gundogdu-uja0j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Teselli

Kimi zaman 

Garip bulurum kendimi

Aşmak

Gaflet ve delaletle olur ancak

Cebren ve hile ile

Geçirilse de ele

Bedenimin her zerresi

Damarımdaki alkol olur

Varlığımın tek tesellisi.', 'Teselli Kimi zaman  Garip bulurum kendimi Aşmak Gaflet ve delaletle olur ancak Cebren ve hile ile Geçirilse de ele Bedenimin her zerresi Dam...', ARRAY['Türk Edebiyatı','Şiir','Selamet Gündogdu']::text[], 8.5, '{"poet":"Selamet Gündogdu","poet_slug":"selamet-gundogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/teselli-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-selamet-gundogdu-z9xdc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KADINIM

Koridorda duydukça ayak seslerini

Kıpır kıpır oluyor içim

Bir bardak su getirdiğini bilmekten

Ve bunu hevesle yapıyorsun.

Her yudumu içtikçe ben

Sen kanıma karışıyorsun.

Ağlayınca içimdeki çocuk

Belki acı,belki açlıktan

İlk önce sen koşuyorsun

Biliyorsun naz yaptığımı ama

Geliyorsun.

Sanmam ki acıyorsun

Seviyorsun.

Hep böyle olacak mı diye

Korkuyorum kendime sormaya

Ama sebebi

Cevabını bilmemek değil.

Biliyorum,

Belki terk edeceksin

Olmamasını diliyorum.

Ama giderken bir veda busesi

Vereceğini de biliyorum.

Kadınım

Seni seviyorum…', 'KADINIM Koridorda duydukça ayak seslerini Kıpır kıpır oluyor içim Bir bardak su getirdiğini bilmekten Ve bunu hevesle yapıyorsun. Her yudumu...', ARRAY['Türk Edebiyatı','Şiir','Selamet Gündogdu']::text[], 8.5, '{"poet":"Selamet Gündogdu","poet_slug":"selamet-gundogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kadinim-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç inanmadım ki…', 'hic-inanmadim-ki-selamet-gundogdu-5ueg5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben size hiç inanmadım ki…

Neler istemediniz benden,

Büyümemi

Yemek yememi

Oyun oynamamı istediniz.

Sonra okula gitmemi

En çalışkan olmamı

Hep taktirname almamı

Birinci olmamı

Evlenmemi,çocuk sahibi olmamı

Çocuklarıma en iyi benim bakmamı

Saygın olmamı,size saygı duymamı

Gerektiğinde size akıl

Gerektiğinde para vermemi

Faturaları ödememi

Çok çalışmamı

Hep istediniz.

Sonra bir gün

Ben bir şey istemeye kalkınca

Çok şaşırdınız.

Dedim ya,

Ben size hiç,

Hem de hiç inanmadım ki…….', 'Ben size hiç inanmadım ki… Neler istemediniz benden, Büyümemi Yemek yememi Oyun oynamamı istediniz. Sonra okula gitmemi En çalışkan olmamı H...', ARRAY['Türk Edebiyatı','Şiir','Selamet Gündogdu']::text[], 8.5, '{"poet":"Selamet Gündogdu","poet_slug":"selamet-gundogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hic-inanmadim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemedim!', 'soyleyemedim-saim-bastik-hgxo9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gizliden gizliye yanar dururum

Seni sevdiğimi, söyleyemedim.

Diyecektim, engel oldu gururum

Seni sevdiğimi, söyleyemedim.

Aşkınla düz olur bana yüceler

Seni düşünürken bitmez geceler

Düğümlendi boğazıma heceler.

Seni sevdiğimi, söyleyemedim.

Belki, gözlerimden anlarsın dedim

Anlayıp sevgimi bilirsin dedim

Ha bugün, ha yarın deyip bekledim.

Seni sevdiğimi, söyleyemedim.

Aynada prova yaptım, kaç defa

Bugün tamam deyip, çıktım kaç defa

Lâfı dolandırdım başka tarafa

Seni sevdiğimi, söyleyemedim.

Bilmediğim şuydu benim, belki de

Gurur olmaz diyorlardı sevgide

Dilimin ucuna kadar geldi de

Seni sevdiğimi, söyleyemedim.

24/10/2005', 'Gizliden gizliye yanar dururum Seni sevdiğimi, söyleyemedim. Diyecektim, engel oldu gururum Seni sevdiğimi, söyleyemedim. Aşkınla düz olur b...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/soyleyemedim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Karıştı', 'aklim-karisti-kaya-alp-jqao1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gurbet éllerinde geçti seneler; 

Ay yıla devretti; eyyam yarıştı. 

Mutluluğu ararken,sâdece bir dem; 

Acılar,hüzünler,dertler karıştı. 

İnsan,ümitlerle gelir dünyaya; 

Dalar hayâllerle, binbir rüyâya. 

Yolun başındayken daha,kaldım da yaya; 

Patikalar,duraklar,éller karıştı. 

Néyleyim ben, kime déyim hâlimi, 

Ayrılığın acısı büktü bélimi. 

Uzatıp da semâya açtım elimi; 

Dualar,niyazlar,diller karıştı. 

Neye idi niyet,neye çıktı fal,

Dilim tutuldu da; sanki oldu lâl...

İşte böyle şimdi,hâl-i pürmelâl; 

Kahveler,telveler,küller karıştı.

Bağımda ısırganlar,güller karıştı.', 'Gurbet éllerinde geçti seneler;  Ay yıla devretti; eyyam yarıştı.  Mutluluğu ararken,sâdece bir dem;  Acılar,hüzünler,dertler karıştı.  İnsa...', ARRAY['Türk Edebiyatı','Şiir','Kaya Alp']::text[], 8.5, '{"poet":"Kaya Alp","poet_slug":"kaya-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aklim-karisti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiraz Ağaçları Ve Türküm', 'kiraz-agaclari-ve-turkum-fidan-bulut-6ymsb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sığamıyorum kabıma, enginime

Ne gün avutuyor ne gece.

Vuruyorum yollara asvalt kayıyor ayaklarımdan,

Adımlarıma dolanan çocukluğumun çakıl taşları.

‘’uzaklık hiç önemli değil 

   değil de; 

   elim yetmiyor yüreğim

   yanında olmam gereken zamanlarda’’

Canım, yolum beton grisine yumdum gözümü

Nasılsa bir türkü düşüyor özüme...

Gelinmez uzağından saz çalmalısın bana.

Oysa bilmemki türkülerin dilini töresini yöresini....

Elimin değmişliği bile yokken,

Nazlı bir bağlamanın ucuna

Dokunacağın tellerine hapis ruhum şimdi.

Nasılsa bir türkü işte; hani yanık, hani sevda gibi.....

Toprağınıda bilmem senin, sızılarını da

Sen de Söğüt ü bilmezsin gerçi...

Türkün gibi Söğüt düşüyor usumda uzanmış

Kiraz tadında çocukluğum ve sevdan yakıyor genzimi.

Toprağa değmemiş ayakları düşünüyorum

Dalında meyvayı bilmeyen çocukları.

Buralarda kapılara kilit vurulu çifter çifter

Kimsenin budak deliğinden sarkan kapı ipi yok.

Hoş, ağaç kapı da yok ya zaten.

Sazının namelerine toprak kokusu sar,

Tellerine, yüreğimle bir dokun.

Çalmalısın bana bu gece uzaklarından 

Dinlemeliyim bir türkü, özümde yanık sevdalısından........', 'Sığamıyorum kabıma, enginime Ne gün avutuyor ne gece. Vuruyorum yollara asvalt kayıyor ayaklarımdan, Adımlarıma dolanan çocukluğumun çakıl t...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kiraz-agaclari-ve-turkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Pusuda', 'zaman-pusuda-resul-ustun-qb1q4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne sen atmaca olup

kuşlara hükmedebildin; 

ne de ben kuş olup

özgürlüklere uçabildim.

Sen ey saksağan havalı serçe! 

Ne kendin uçabildin,

ne de beni özgürlüklere saldın.

Korkak yüreğin,

ve küflü beyninle düşler kurdun.

Hep karanlık,

hep fırtınalı günler gözledin.

Tufanlar kopsun,

yıldırımlar düşsün istedin.

Ben se güneşi özledim.

Yıldızlı bir gökyüzünü gözledim.

Yeryüzü çiçeklenirken,

kanat çırpıp uçmayı düşledim.

Sen beni,

ben de seni gözetledim.

ikimiz de,

bizi oyalayan zaman tuzağında 

zamanı pusulamaya çalıştık.

Ne sen beni anlayabildin,

ne de ben seni savuşturabildim.

Belki senindir bugün,

ama yarınlar benim olacak inan.

Sen ve ben; 

herhangi bir gün,

Yurdumun herhangi bir yerinde...

Belki bir köy meydanında,

belki de bir sanayi kentinde,

sağanak olup yağacağız bilesin.

Sen karanlıkları ve çirkinlikleri,

ben aydınlıkları ve güzellikleri...

Yarınların upuzun yolculuğunda

sırılsıklam ıslatacağız bilesin.

Velhasıl Dünya döndükçe,

sen benim için korkuları,

ben senin için

cesareti yaşatacağım bilesin.', 'Ne sen atmaca olup kuşlara hükmedebildin;  ne de ben kuş olup özgürlüklere uçabildim. Sen ey saksağan havalı serçe!  Ne kendin uçabildin, ne...', ARRAY['Türk Edebiyatı','Şiir','Resul Üstün']::text[], 8.5, '{"poet":"Resul Üstün","poet_slug":"resul-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/zaman-pusuda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat 18.30', 'saat-18-30-mehmet-akif-gulhan-n64rp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neredesin be Ahmet Salih

Buluşmaya ya gelmezsin yada hep geç gelirsin

İskelenin önündeyim,beklemekten ağaç oldum

Denize bakıyorum,ruhumun karanlığı gibi deniz 

Karşıda adalar,sahipsiz elmas gerdanlık gibi

Saat 18.45

İskelenin önünde gazete büfesi

Haberlerden bana ne 

İleride balıkçı tezgahları

Daha ileride “temiz” dürüm büfe

İki sevgili geçiyor yanımdan

Sarmaş dolaş,kıskanıyor muyum ne 

Saat 19.00

Balıkçı tezgahlarını seyretmeye gidiyorum

Palamut var,lüfer var

Balıkçı buyur ediyor

Bilmiyor alıcı olmadığımı

Fersiz balık gözleri ile bakışıyorum

Ayrılıyorum tezgahların önünden

Balıkçı kesin küfür ediyor bana 

Balıkçı kesin küfür ediyor  kaderine 

Saat 19.15

Solda bir otomobil,lüks sayılır

Bana bakan pencerede bir kadın oturuyor

Sarı saçlı mavi gözlü,hüzünlü yüzlü

Direksiyonda bir adam

Kadın denize bakıyor, adama arkası dönük

Adam yola bakıyor 

Kadın hüzünlü, kadın ağlamaklı

Tartışmışlar diyorum aklımdan

Belki de kavga etmişler

Hayır bunlar ayrılma kararı almış

Adam bu iş bitti artık demiş

Kadın adamın karısı mı

Belki de öteki kadın o

Arabanın boyu beş adım

Ben iki adımda anlamaya çalışıyorum olayı

Bakamıyorum kadına ısrarlı gözlerle

Saat 19.30

“Temiz”dürüm büfenin önündeyim

onlar da  buyur ediyorlar beni

büfenin bir tayfası geçen arabalara el ediyor

arabalar vızır vızır geçiyor

kime ne temiz büfeden

büfenin bir tayfası,elinin parmaklarını

sanki bir çekirgeyi yakalayacak gibi yapıyor

ve burnuna götürüyor,burun kemerinden

burun deliklerine kadar sıvazlıyor

parmaklarına gelen sıvıyı,belli etmeden

görünmez bir yerlere siliyor

Saat 19.45

Biraz ileride park var,banklar var 

Gidip oturmaya niyetleniyorum

Gençler var parkta oynaşıyorlar

Bir çift daha var kızın başı örtülü

Devamlı telefon ile konuşuyor

Serseri kılıklı bir adam geliyor ta ileriden

Önce oynaşan gençlere bakıyor 

Gençlerin önünden geçiyor ama

Kafasını arkaya çevirip ısrar ile bakmaya devam ediyor

Başı örtmeli kız ile delikanlının önüne geliyor

Bu defa onlara bakıyor ısrar ile 

Birkaç adım geçmesine rağmen hala bakıyor

Çok kızıyorum edepsize,bana da bakacak mı öyle

Bakıyor,bana da bakıyor kafasını hiç ayırmadan

Gövdesi ileride,kafası bana sabit,bakıyor

Göz göze gelmemeye çalışıyorum onla 

Saat 20.00

Aynı yolu gerisin geriye gitmeye başlıyorum

Temiz büfe solumda 

Burnunu silen adam beni buyur ediyor

Ters ters bakıyorum adama 

Adam bir anlam veremiyor bu bakışıma

Hüzünlü kadının olduğu araba sağımda

Bu defa arabanın ön camından 

Olduğu gibi görüyorum onları

Arabanın içinde zaman durmuş

Adam hala yola bakıyor 

Kadın hala denize bakıyor

Aramızda bir adım var 

Kadının gözünden yaş süzülüyor

Pencere açık olsa,uzansam,gözünün yaşını silsem

Haydi bırak şu adamı, benimle gel desem

Hiç dayanamam oldum olası,ağlayan kadına 

Saat 20.15

Ulan Ahmet Salih neredesin be

Gelsin bir,yapacağımı bilirim ben

Salih beni eve bırak oğlum diyeceğim

Bu saatten sonra seninle ne konuşacağız

Kızdığımı anlayacak

Ne oldu ağabey ne yaptım ben diyecek

Hiç Salih hiç, hiç bir şey yapmadın

Beni eve bırak,benim bir şeyler yazmam lazım

Saat 20.30

Mehmet Akif Gülhan  26.10.2005 Saat  10.29', 'Neredesin be Ahmet Salih Buluşmaya ya gelmezsin yada hep geç gelirsin İskelenin önündeyim,beklemekten ağaç oldum Denize bakıyorum,ruhumun ka...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/saat-18-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil Gözlü''ye', 'yesil-gozlu-ye-necati-keceli-r3zrm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Attığın her adım nazlımı, nazlı

    Yeşil gözlerinde ferman yazılı

    Gözlerin alevdir, dudağın ballı

    Sanki üzerin de derman yazılı

    Kaşların yay gibi pozisyon almış

    Kirpikler ok olup kalbime dalmış

    Kulağımda sesin bir şarkı olmuş

    Sazımın üstünde hicran yazılı

    Taralı saçların bak lüle, lüle

    Ne güzel yakışmış kemerin bele

    Sam yeli gibisin dokunsam ele

    Sanki kaderim de hüsran yazılı

    Açılmış gerdanın süt gibi beyaz

    Yanakların olmuş bitişik kiraz 

    Filizlenip açan goncasın bu yaz

    o güzel yüzün de destan yazılı

    Cemalin ay gibi ışık dünyama

    Gözlerin düşüyor gece rüyama

    Ben, yeşil gözlüye aşığım ama 

    İsmi yüreğim de Şükran yazılı

    Necati KEÇELİ 

    İZMİR', 'Attığın her adım nazlımı, nazlı     Yeşil gözlerinde ferman yazılı     Gözlerin alevdir, dudağın ballı     Sanki üzerin de derman yazılı    ...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yesil-gozlu-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü İstemek', 'olumu-i-stemek-yunus-yurdakul-bw3rt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne bahar...

Ne yağmur var okşayan...

Ne yaz,ne sıcak,ne bir tatlı telaşım...

Dışarda kar yağıyor ve tokmak gibi başım...

Ne duygular hareketli,ne de ruhumda his var

Gündüzler gece gibi, şehrin içinde sis var

Herkes özgür konuşmakta, sadece bana sus var

Bilinen şu alemde:burda garip Yunus var.

Ne yaşam...

Ne geçen günlerin tadı...

Ne hayatın hoşluğu...

Yüreğimde sadece,faniliğin adı var...

Elim açık umuda...

Umut sanki küs bana...

Gel nolur bana tam artık diyecekken

Kızgınca bir suratla somurtuyor sus bana

Eller gökkuşağının renkleriyle barışık

Benim dünyam hep gri,dört bir taraf pus bana.

Ey ölüm neredesin? 

Ey ölüm gelmez misin? 

Bozkırda bir şehir var ve şehirde bir adam

O adam ki gülerken bile sade duyar gam

İşte ona gitmenin sırası değil mi tam? 

Yavarıyor Allah''a tez salsın diye seni

Bilesin...

Sonuç hüsran elbette...

Sonuç tam bir fiyasko...

Boşa geçen bir ömür...

Boşa geçen zamanlar...

Ölüme koşulur mu,koşulurmuş meğerse

Ölüm neyi anlatır,yaşarken ölen anlar.', 'Ne bahar... Ne yağmur var okşayan... Ne yaz,ne sıcak,ne bir tatlı telaşım... Dışarda kar yağıyor ve tokmak gibi başım... Ne duygular hareket...', ARRAY['Türk Edebiyatı','Şiir','Yunus Yurdakul']::text[], 8.5, '{"poet":"Yunus Yurdakul","poet_slug":"yunus-yurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/olumu-istemek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Kahvesinde', 'kir-kahvesinde-savas-dincbas-psrm8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yalnızlığımı yudumluyorum

kır kahvesinde

bir bardak çayla

sigara dumanında yalnızlığım

okuduğum kitaba bile dalamıyorum

olmayacak böyle,yalnızlık canımı sıktı

öldürücü bir duygu yalnızlık

çıkarıyorum seni gönlümden

kahvedekileri bir bir sana boyuyorum

çehresini değiştiriyorum herkesin

işte şimdi oldu

bütün kahve seninle dolu

seninle paylaşıyorum

kır kahvesinin güzelliğini

tavşan kanı çayın

tadı daha güzel şimdi

sigaramın dumanı

garson bize iki çay daha getir...', 'yalnızlığımı yudumluyorum kır kahvesinde bir bardak çayla sigara dumanında yalnızlığım okuduğum kitaba bile dalamıyorum olmayacak böyle,yaln...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kir-kahvesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Sarhoşluğu Suçlu', 'askin-sarhoslugu-suclu-kamil-soylemez-yypiw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sevmişsem

Bilki doğrudur

Kırmışsamda zaman,zaman

Bil ki suçum deil

Çocukluğumun işidir

Özleminle yanan yüreğimin

Dağılmış sevdan başım işidir

Aşkının sarhoşluğudur

Yoktur bilirim senden ötesi

Bir çığırtkanlıklar alıp,gittiysede

Bilki geri dönüşümün

Sokak ucunda ki gölgesidir

Senin özleminle koşuşan

Seni sevmişsem söylemişsem doğrudur

Bunu bil isterim

Geçmişi hatırla

Dön bir an geriye

Neyimiz kalır ki

Sevgi yoksa özlem içimizde

Bir sarhoşluk geçidi bu dünya

Hemde iki kapılı

Birinden nasıl geldiysem

Diğerinden de bilki gidicem

Ama seni görmeden duymadan sevmeden edemem

Öldür isterim gerçekten beni sevmeyeceksen

Yada söyle gerçeği sevmiyorum yada seviyorum de

Dağılıp,gitsin ömür bu sevgi peşinden bunu sen iste derim

İsteki sen vermeyeceksen ümitlerimi goncasında dökerken güllerimi

Ben son diyeceğim çıkışı son kapının hazır yolcusu ha bu gün olur ha yarın', 'Seni sevmişsem Bilki doğrudur Kırmışsamda zaman,zaman Bil ki suçum deil Çocukluğumun işidir Özleminle yanan yüreğimin Dağılmış sevdan başım ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/askin-sarhoslugu-suclu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emzirilen Umutlar', 'emzirilen-umutlar-resul-ustun-f6ux6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş batıp 

kaybolunca aydınlıklar,

ve cümle yıldızlar

birer birer parladıkça gökyüzünde

bir hüzün,

bir özlem esir alır bedenimi.

Ne kadar gizlesem de

sensiz olmuyor,

Özlüyorum seni bir tanem.

O gülüşünü,

yürüyüşünü özlüyorum.

Bazen geçmişimi,

çocukluğumu anımsıyorum.

anamın ninnilerini,

türkülerini özlüyorum.

anam emzirirken bizi,

düşlerini de emzirirdi büyüsünler diye.

Biz büyüdük,

düşlerimiz küçüldü yıllar geçtikçe.

Düşlerimin içinde

sadece sen,

bir tek sen büyüyorsun bir tanem.

Ve sen büyüdükçe,

uzaklaşıyorsun nedense.

Meraklanıyorum,

Hayıflanıyorum gidişine.

Her gece gökyüzüne dikip gözlerimi,

kayan yıldızları izliyorum.

Her biri senmişsin gibi algılıyorum.

Bir de

gece şahinlerini izliyorum bazen.

Gündüz olsa,

bulutları bıçak gibi kesip geçerler.

Ya geceleri? 

Geceleri neyi biçtiklerini göremiyorum.

Meraklanıyor ve ürküyorum.

İstemeden,

tekrar çocukluk günlerime dönüyorum.

Umutlarımız vardı o zaman.

Kocaman kocamandılar.

Anam umutlarımızı da emzirirdi,

Bizimle birlikte büyüsünler diye.

Biz büyüdük,

Umutlar küçüldü yıllar geçtikçe.

Ama; 

Özlemlerim büyüdü biliyor musun? 

küçülen umutlara,

umutsuzluklara inat,

özlemlerimin ardından sana geliyorum.

Sen tüm dişiliğinle

kara bulutların ardında bekleye dur.

Saçlarınla set çek

pusudaki yağmur bulutlarına.

İzin verme sakın,

sönmesin yüreğindeki kıvılcımlar.

Fırtınalar yaratsın sevdan.

Benim her karanlık gecede

özlemleri emzrdiğim gibi,

Sen de benim için

sevdamızı emzir bir tanem.

Daha sonra bulutların ardında,

Yıldızların en tepesinde bekleye dur.

Ben,

Emzirilen sevdamızın ardından

Bulutlara tırmanıp geliyorum.

Bekle beni.', 'Güneş batıp  kaybolunca aydınlıklar, ve cümle yıldızlar birer birer parladıkça gökyüzünde bir hüzün, bir özlem esir alır bedenimi. Ne kadar ...', ARRAY['Türk Edebiyatı','Şiir','Resul Üstün']::text[], 8.5, '{"poet":"Resul Üstün","poet_slug":"resul-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/emzirilen-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veni Vidi', 'veni-vidi-murad-ertaylan-j2mcg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir tohumla can buldum,

Doğumla bebek,

Sünnetle erkek oldum.

Siyah önlükle talebe,

Aşıkla maşuk,

Diplomayla adam oldum.

Tahta tüfekle asker,

Nikahla damat,

Ada’yla baba oldum.

Özel okulla veli,

Köpekle sahip,

Kitapla yazar olacağım.

Zamanla patron,

Torunla dede,

Ölünce sır olacağım.', 'Bir tohumla can buldum, Doğumla bebek, Sünnetle erkek oldum. Siyah önlükle talebe, Aşıkla maşuk, Diplomayla adam oldum. Tahta tüfekle asker,...', ARRAY['Türk Edebiyatı','Şiir','Murad Ertaylan']::text[], 8.5, '{"poet":"Murad Ertaylan","poet_slug":"murad-ertaylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/veni-vidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk bahar gelecek', 'i-lk-bahar-gelecek-ramazan-kayak-0y0zb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün ilk bahar gelecek

Gönül yaralarımıza bir bir

Kan kırmızısı güller açacak

Talan edilmiş yüreğimize

Bir daha sarılacağız yaşama

Özgür bir hayat için

Barış dolu bir dünya için

Feda edilen geçmiş için

Yokluk''la geçen ömür için

Bir gün ilkbahar gelecek

Biliyorum...

Karacadağın ardından...', 'Bir gün ilk bahar gelecek Gönül yaralarımıza bir bir Kan kırmızısı güller açacak Talan edilmiş yüreğimize Bir daha sarılacağız yaşama Özgür ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ilk-bahar-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahadet edecek ahrette her bir uzvun sana', 'sahadet-edecek-ahrette-her-bir-uzvun-sana-halil-colak-v7rlw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağlar, taşlarda  Mehmet’im şahittir sana,

Nice canlar,gözlerde verdin sen bu vatana

Parçalanmış kollar,kafalar dağılmış bir yana

Şahadet edecek ahrette her bir uzvun sana

Gabar dağlarıdır şahittir her şeyi de gören

Toprağıdır senin kanınıda kana kana emen

Şahittir ağaçlar böcekler gökyüzüde sana

Şahadet edecek ahrette her bir uzvun sana

Kınalı bacaksızlar destanı dağlarda yazdılar

Hepsi gencecik analarının  birer fidanıydılar

Anaların bağrı da tutuşup, yandı kavruldular

Şahadet edecektirler ahrette her uzvun sana

Kimisi anıllarından  vurulmuş düşmüştü yere

Vatanı içinde savaşta kolları kopmuştu bile

Mehmet’im destanlık kahraman olmuş gine

Şahadet edecek ahrette her bir uzvun sana

Sen bu vatan uğruna kendini feda etmişsin

Anadan, babadan, kardeşten, yardan geçmiş

Şahadet şerbetini kelimeyi tevhitle içmişsin

Şahadet edecek ahrette her bir uzvun sana

Horasan ereni dahil hiçbir kalem unutamaz seni

Şehitlik mertebesidir Müslümanın en son  rütbesi

Döktüğün her damla kan senin kurtuluş müjdesi

Şahadet edecek ahrette her bir uzvun sana

Halil Çolak 26.10.2005 Ankara', 'Dağlar, taşlarda  Mehmet’im şahittir sana, Nice canlar,gözlerde verdin sen bu vatana Parçalanmış kollar,kafalar dağılmış bir yana Şahadet ed...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sahadet-edecek-ahrette-her-bir-uzvun-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Ağlıyorum', 'sana-agliyorum-zeynep-nilgun-gokceoz-dcknd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Farkında olmadan

Sana geliyorum her gece,

Karanlıklara dokunduğumda

Gözlerin parlıyor,

Sıkıyorum dudaklarımı kanatırcasına

Gülüşlerim ağlıyor öptüğünü andıkça,

Hayallerimde artık ayrılık zamanı

Umutlarımın sönme

Ufuklarımın solma zamanı,

Gizli bir yalan içinde

Bulanık  aşk masalı var

Dinlerken canım yanıyor

Anlatırken hüznüm kanıyor

Ve biraz daha ölüyorum

Dönüşü olmayan vedalarda,

İncinmiş kalbimin içinde

Bendeki seni saklıyorum

Şafaklar sökerken yüreğimde

Ben her sabah sana ağlıyorum…

Sessizlik var başucumda

Kimliksiz düşlerdeyim her gece,

Şimşekler çakıyor yağmayan bulutlarda

İçim vurgun yemiş gibi isyanlarda

Paramparça gözlerimdeki yıldızlar

Ve bir o kadar da karşılıksız sevgiler,

Tutki hiç yaşanmadı

Tutki hiç sevmedim seni

Sevdalı bir rüzgar gibi,

Hiç solumadım göç eden mutluluğumda

Anladım, yok artık kapımdaki bahar

Ruhumun duvarlarında

Sadece ayrılığın izi var.

Bilki uzaklıklar değil bizi ayıran

Bilki nankör değil benim sevdam

Sana mahkum yaşıyorum

Pişmanlıkları ardıma almadan

Pencereme konan şafaklara inat

Ben her sabah sana ağlıyorum…', 'Farkında olmadan Sana geliyorum her gece, Karanlıklara dokunduğumda Gözlerin parlıyor, Sıkıyorum dudaklarımı kanatırcasına Gülüşlerim ağlıyo...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sana-agliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyle-i Kadir Gecesi', 'leyle-i-kadir-gecesi-i-brahim-sahinoglu-t1nsx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir nur doğdu fecri sadıktan

Leyle- i Kadir gecesinde

Alemlere nurlar saçtı

Leyle-i Kadir gecesinde

Ol geceki rahmet saçar

Cenneti alaya kapı açar

Mümin olan ordan geçer

Leyle-i Kadir gecesinde

Bir sevabın binbir olur

Arayan nasibin bulur

Nasibin kapına gelir

Leyle-i Kadir gecesinde 

Bütün varlık secde eder

Yaradan Mevla-yı birler

Diller hep onu söyler

Leyle-i Kadir gecesinde

Hulusoğlu doğru söyler

Yaradandan affın diler

Dilerim Mevlam af eyler

Leyle-i Kadir gecesinde

		İbrahim ŞAHİNOĞLU

		         Hulusoğlu', 'Bir nur doğdu fecri sadıktan Leyle- i Kadir gecesinde Alemlere nurlar saçtı Leyle-i Kadir gecesinde Ol geceki rahmet saçar Cenneti alaya kap...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Şahinoğlu']::text[], 8.5, '{"poet":"İbrahim Şahinoğlu","poet_slug":"i-brahim-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/leyle-i-kadir-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fasıl', 'fasil-h-hikmet-esen-vhzl1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönül

Aksak ritmindeyse ömrün 

Yürük semai umutlarla

Coşar duygular.

Yürekte maya

Tende can

Ve damarlardan

Akan 

Kan

Bir fasıl ki yaşanan 

Es geçmedikten sonra

Ne Gam...', 'Gönül Aksak ritmindeyse ömrün  Yürük semai umutlarla Coşar duygular. Yürekte maya Tende can Ve damarlardan Akan  Kan Bir fasıl ki yaşanan  E...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fasil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-h-hikmet-esen-ekidd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşümde; 

Ellerim ceplerimde,

Tanıdık sokaklardayım bu gece..

Nice sevdalarım,

Nice acılarla kolkola; 

Geçmişin,

O pek aşina,

Amansız yokuşunda,

Uygun adım anılarla…

Gemi azıya almışken zaman,

Duygularımı çekiyorum kınından.

Tutkularım,

Sokak lambalarının,

Göz kırpan gülüşüyle,

Tükenen civalı ampullere

Can verircesine,

Saplanıyor geceye..

Yenilgiler, zaferler,

Geçip giderken,

Gözlerimden; 

Hüzünler,

Usulca demir alıyor şiir nöbetlerimden..

Bir ömrü yakar gibi birden,

Şafak söküyor,

Ağaran saçlarımdan.

Ve tutkular,

Ve sevdam; 

Bir tetik dokunuşu kadar yakın,

Bir o kadar da uzak,

Yüreğimin namlusundan..', 'Düşümde;  Ellerim ceplerimde, Tanıdık sokaklardayım bu gece.. Nice sevdalarım, Nice acılarla kolkola;  Geçmişin, O pek aşina, Amansız yokuşu...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ruya-208-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açıyorum kapıyı', 'aciyorum-kapiyi-i-brahim-ethem-bingul-661lv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğmadan şifrelenmiş ismin kalbime

Senmişsin anahtarı

Açıldı yüreğimin tüm odaları

Bir bakışınla gözlerime...

Evindeydin gönlümde

Kendini kiracı sandın

Yoruldum, ağlarım boynu bükük sevgime

Aşk tek kişiliktir derdin hep

Haydi yine de...

Üstünden kilitlemiştim yüreğimi,yıllarca

Çıkmayasın diye dışarı

Açabilsem şu kapıyı

Bilirim ne sen kalırsın orda

Ne de ben tutarım artık aşkını...

Yeter bu kadar acı 

Kayboldum sevda çıkmazlarında

Vurma, yumruklama, sakin ol

Az kaldı, açıyorum kapıyı...

www.iebingul.com', 'Doğmadan şifrelenmiş ismin kalbime Senmişsin anahtarı Açıldı yüreğimin tüm odaları Bir bakışınla gözlerime... Evindeydin gönlümde Kendini ki...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aciyorum-kapiyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Günleri...', 'bayram-gunleri-ulvi-ziya-3hblg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaman zaman coşku artar ömrümüzün günlerinde

Bayram yapar eğleniriz; sevinç,huzur demleridir...

Kiminin de bayram yeri yıkıktır gönüllerinde; 

Yoklamaya gelenler,evvel zaman elemleridir...

Mâzide açılmış yara,kabuk bağlamış da olsa; 

Bir şey,böylesi günlerde kanatmak için uğraşır...

Yitirilmiş bir can için çok kez ağlanmış da olsa; 

Hafıza,göz yaşlarını bu mutlu günlere taşır...

Yenen tatlı zehir olur,eğlenilse de yalandır...

Tebessüm et sağa sola,gülerek kendini kandır...

Mâdemki elâlem coşmuş,zevk alıyorlar hayattan; 

Öyle ise havalar hoş,bu günler kutlu bayramdır...', 'Zaman zaman coşku artar ömrümüzün günlerinde Bayram yapar eğleniriz; sevinç,huzur demleridir... Kiminin de bayram yeri yıkıktır gönüllerinde...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bayram-gunleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Bayramlara...', 'nice-bayramlara-ulvi-ziya-llk2p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül şâd oldukça,hayat güzeldir

Dilerim her şey gönlünüze râmolsun...

Durmadan geçer zaman,sanki esen bir yeldir

Dilerim her gününüz ayrı bir bayram olsun...', 'Gönül şâd oldukça,hayat güzeldir Dilerim her şey gönlünüze râmolsun... Durmadan geçer zaman,sanki esen bir yeldir Dilerim her gününüz ayrı b...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nice-bayramlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alim!', 'alim-ahmet-bektas-a7r1p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Azıcık ilahiyat etmiş talim.

Sanır kendini en büyük alim.

Tepeden bakar insanlara daim.

Belli ki o; bir ahmak zalim.

Ben de ona uyarsam; ne olur halim?', 'Azıcık ilahiyat etmiş talim. Sanır kendini en büyük alim. Tepeden bakar insanlara daim. Belli ki o; bir ahmak zalim. Ben de ona uyarsam; ne ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bektaş']::text[], 8.5, '{"poet":"Ahmet Bektaş","poet_slug":"ahmet-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/alim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizemli kadın', 'gizemli-kadin-ahmet-bektas-3q36c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gizemli, asil, şerefli, 

Belli her halinden.

Onu ilk gördüğümde etkilendim, 

Ta derinden.

Daha hakkında hiç bir şey bilmezken.

Kapıldım, tutuldum, aşık oldum. 

Aniden.', 'Gizemli, asil, şerefli,  Belli her halinden. Onu ilk gördüğümde etkilendim,  Ta derinden. Daha hakkında hiç bir şey bilmezken. Kapıldım, tut...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bektaş']::text[], 8.5, '{"poet":"Ahmet Bektaş","poet_slug":"ahmet-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gizemli-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-sair-yaman-fukf8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün ufukta bir başkalık var

Belli belirsiz bir kızıllık alır mavisini

Sensizliğimi anlamış mı ne? 

Kızıl örtüsünü çekmiş üstüme

Bir başka yakıyor yüreğimi.

Ben miadı dolmuş bir yolcuyum aşkında

Bir daha açılmamak üzere kapanan

Kara kaplı defterim nazarında

Ve bir o kadar da talihsiz bir sevdalı

Yıkılmayan tek burcuyum aşkının

Senin için hep ayakta kalan

Belki anlarsın beni diye anlatıyorum bunları sana

Biliyorum ne kadar uğrşsam boş ama

Burçlarda gezinen şaşkın bir umut işte

Öylesine...

Bir kış sabahı görmüştüm seni rüyamda

Bin bir çeşit çiçek açtırdın dünyamda

Geceler gündüz, dağlar dümdüz olmuştu

Elzem bir anda

Neden sonra farketmiştim sen olduğunu

Geç kalmıştım ama

Elimi uzattım hissetmek için yokluğunu

Öylesine...

Fazla durmamıştın, olsun, geldin ya

Derman oldun miadı dolmuş gönlüme

Gerçek değildi olanlar, biliyorum

Sadece bir rüya

Ne kadar isterdim gelmeni bir bilsen

Boş bir ümit işte öylesine...

Nereden nereye geldik bak yine

Kapıldık bir an mazinin seline

Çıkmıştık yola ne ümitle, ne hevesle

Öylesine bir yolculukmuş benimki öylesine...

Z.Ç', 'Bugün ufukta bir başkalık var Belli belirsiz bir kızıllık alır mavisini Sensizliğimi anlamış mı ne?  Kızıl örtüsünü çekmiş üstüme Bir başka ...', ARRAY['Türk Edebiyatı','Şiir','Şair Yaman']::text[], 8.5, '{"poet":"Şair Yaman","poet_slug":"sair-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/oylesine-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ottepel*', 'ottepel-esref-karadag-9gn6r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şehir rengindeydi kasabalı aşklarım /yalan

can çekişirken yüreğim nasırların işgalinde

sustuğum şarkılarda saklıyordum

dar (z) amanlı korkularımı

cenaze arabaları gibi umarsız / kayıtsız

sırtlamıştım yaşamın ölü tarafını

çok boyutlu yalnızlıklar kundaklarken

tümcelerimin (g) izli öznelerini

ikinci el bir yaşamaktı / yaşlanmaktı sessiz günün terkisinde

tesbih tanesi mevsimlerden kimliğimde kalan

sesine dokunduğumda çözdüm baharı / inan

aşktı altıncı duyu

güne çıktı / sana çıktı

tipiye tutulan masallarım

yasaksız bahçelerde kuşluk vakitleri

ıslıkla tırmandı kiraz ağaçlarına bir çocuk

çözüldüm tutunduğum geceden / er(i) dim

gecikmiş bir ırmağım şimdi kıyılarına dayanan

ötesi diyeceksin

ötesi dayanılmaz bir talan

*(Rusca) Donun çözülmesi, buzun erimesi. Kruşev''in iktidarda olduğu yıllarda, Stalin döneminin katılıklarını hafifletmek amacıyla getirilen serbestlikler için kullanılan bir sözcük.', 'şehir rengindeydi kasabalı aşklarım /yalan can çekişirken yüreğim nasırların işgalinde sustuğum şarkılarda saklıyordum dar (z) amanlı korkul...', ARRAY['Türk Edebiyatı','Şiir','Eşref Karadağ']::text[], 8.5, '{"poet":"Eşref Karadağ","poet_slug":"esref-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ottepel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü-Hışmınan Uçarsa Şahin Yuvadan', 'turku-hisminan-ucarsa-sahin-yuvadan-asik-osman-feymani-mfb0e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hışmınan uçarsa şahin yuvadan,

Vay gele turnanın başına, oy oy.

Pençe vurur, kanat çarpar, yaralar,

Uğtır, kaderin kışına, oy oy.

Düşte gör, düşte, gör,

Hayalde gör, düşte gör.

Bol gününde dost çok olur,

Hele bir dar güne düşte gör.

Düşer bir gün, düşer bir gün,

Yıkılır, düşer bir gün.

Felek sana düşen fırsat,

Bize de düşer bir gün.

Dünya bir bahçedir, ömürse güldür,

Kimine zehirdir, kimine baldır,

Kimi ağlar, kimi güler; ne haldır,

Akıl yetmez Hakk’ın işine, oy oy.

Aman ok değdi geçti benden,

Vallah çok değdi geçti benden,

Merde köprü olmuş idim,

Namertte geçti benden.

Kazan ağlar, kazan ağlar,

Su kaynatır, kazan ağlar,

Ben öldüğüme gam yemem,

Mezarımı kazan ağlar.

Feymani cahilin olmaz pazarı,

Tembelin kendine değer nazarı,

Garibin künyesiz olur mezarı,

Baykuş bile konmaz taşına, oy oy.

Taşı yana, taşı yana,

Bu dağın taşı yana,

Belki bir gün gerek olur,

Kaldır da koy, taşı yana.

Dil yarası, dil yarası, 

Derin olur dil yarası,

Kurşun değse iyi olur,

Hiç iyolmaz dil yarası.', 'Hışmınan uçarsa şahin yuvadan, Vay gele turnanın başına, oy oy. Pençe vurur, kanat çarpar, yaralar, Uğtır, kaderin kışına, oy oy. Düşte gör,...', ARRAY['Türk Edebiyatı','Şiir','Aşık Osman Feymani']::text[], 8.5, '{"poet":"Aşık Osman Feymani","poet_slug":"asik-osman-feymani","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/turku-hisminan-ucarsa-sahin-yuvadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabristan:sana Kendimi Getirdim (106)', 'kabristan-sana-kendimi-getirdim-106-i-brahim-arslan-0pfkj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kabristan,sana kendimi getirdim

İlk gün misafir muamelesi yap bana

Münker-Nekir gelmesin...

Hiçbir cevap vermem gelseler

Ben cevap alamdım hayatta hiçbir soruma...

Varsın cennet bahçesi olmasın yerim,

Ama cehennem çukuruda olmasın,

İlk gün misafir muamelesi yap bana

Yılan-çıyan sonraki gün uğrasın

Dünyadaki yamyamlardan ne kalmışsa

Ve kemiklerimi sunayım onlara

Etimi verip kemiğimi sahiplenenler

Avucunu yalasın...

Rahat rahat uyuyayım bir gecelik

Keyfimi çıkartayım dünyadakilere inat,

Geçim sıkıntısı,para,yer kavgası olmadan

Bir rüyamdan da uyandırılmayayım...

Yahut siz bana hiç karışmayın,

Şöyle bir gezeyim bu öbür alemi,

Akrabalarımı ziyaret edeyim evvel ölmüş olan

Müşahede edeyim hallerini

Biraz da kopya çekeyim onlardan...

Ve yahut ruhumu salıverin

Dünyada bir kaç kişiyi korkutayım

Bilhassa bizim ev sahibini

Ve haramzede recep''i

Anasından emdiği haram sütü

Burnundan getireyim...

Sonraki akşamlarda burdayız nasıl olsa

Yok mu benden başka bu gece ölen

Bana yarın uğrasanıza

Kabristan:sana kendimi getirdim

Eyvah azrail,bavulum kaldı...

2005', 'Kabristan,sana kendimi getirdim İlk gün misafir muamelesi yap bana Münker-Nekir gelmesin... Hiçbir cevap vermem gelseler Ben cevap alamdım h...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kabristan-sana-kendimi-getirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinçli,Kutsal Günler...', 'sevincli-kutsal-gunler-ulvi-ziya-58rvh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bayramdı...

adı,Kurbandı...

Elâlem şen şakrak

kurbanlık hayvanlarını kesiyor; kestiriyorlardı...

Hayırlar ediliyor; 

yoksulu,bayı,

insanı,hayvanı

kızarmış et yiyorlardı...

Esti bir amansız,gizli rüzgâr

indi feleğin sillesi

anamı toprağa verdim ertesi gün

günlerden  1 Nisan'' dı...

Kaderin çok garip cilvesi,

hayâtın,çekilmez,daha çoook çilesi vardı...

Bayramdı...

Bu kez adı Ramazan''dı...

Tutulmuştu bütün bir ay oruçlar,

işte yine bir bayramdı...

Ağızlarda şeker vardı,

insanlar tatlı yiyor,

tatlanıyorlardı...

Ve mevsimlerden sonbahardı...

Ecel,benden sevdiğimi aldı o gün

toprağa verdim 15 Kasımda karımı

bayramın ikinci günü dünyam karardı...

Sararmış yapraklar toprağa düşüyorlardı...

Feleğin kastı mı var bana; ne? ...

Neden eller gülüp eğlenirken

oklar hep bana değer? ...

Haram mıdır bana yaşamak,gülmek? ...

Bilsem; böyle kader karşısında

başkaları ne yapardı? ...

Esti bir zâlim rüzgâr; 

Benden,sevdiğimi kopardı...', 'Bayramdı... adı,Kurbandı... Elâlem şen şakrak kurbanlık hayvanlarını kesiyor; kestiriyorlardı... Hayırlar ediliyor;  yoksulu,bayı, insanı,ha...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sevincli-kutsal-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem ayşeyle halam nebiş 2', 'annem-ayseyle-halam-nebis-2-munevver-senol-n2n3o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Annem ayşeyle halam nebiş 2

Annem ayşeyle halam nebiye hem akranlar hemde biribirilerini çokseverler,

nereye gitseler beraber giderlerdi,gene ikisi istanbuldan izmire bana geldiler,biz çiğli hv.lojmanlarında oturuyorduk,lojmanlarda çok güzel komşuluk vardır, birinin misafiri geldiği zaman hemen toplanır,hoşgeldine gidilir daha sonra hepsi tek,tek davet eder ağırlarlar,o günde arkadaşlarım annemle halama hoşgeldine geldiler, fakat fenerle,cimbomun önemli bir maçı var,benim iki oğlumda fanatik fenerli,o tarihlerde tanju çolakta fenerde oynuyor,fenerin yenilmesi demek oğlanların kahrolması demek, anneminde büyük oğlum murata aşırı zaafı var,kendi oğlu olmadığı için,oda ilk oğlan olunca,ikinci oğlum buraktan farklı tutardı,misafirler geldi ama o seneler bir televizyonumuz var,oda salonda,ikiside gayet şık giyindiler,hoş,beşten sonra

annem abdest almış bir yandan tesbihini çekiyor,gözüde maçta,heyecanla ya allah at tancu,diye bağırıyor,halam usulca ayşeciğim onun adı tanju,derkende parmağıyla sus işareti yapıyor,aradan biraz geçiyor annem gene ya allah yaa atsana be tancu,deyince halam,bak ayşeciğim, on tane şaşkın,bir topun peşinde koçuyor,sen tesbih çekip günaha giriyorsun

deyip annemin elindeki tesbihi aldı, annem biraz bozuldu,hiç birşey demedi ama suratını astı,iki kolunu kavuşturup oturdu, halam,ayşeciğim,öyle kollarını bağama iyi saymazlar,hemde suratını asma sana gülmek yakışıyor,dedi,annem ellerini iki yana indirdi,halam,misafirlere dönüp ayşeciğim bizim ilk gelinimizdir çok asildir,şimdiye kadar bir dediğimi iki yapmamışyır,ayşeciğim beni kırmadığı için sana teşekkür ederim dedi,

arkadaşlarım onların bu haline şaşırdılar ama annemide çok taktir ettiler bu yaşına rağmen saygıya bak dediler, buda şimdi bir anı kaldı ikiside peş,peşe rahmetli oldu nur içinde yatsınlar.', 'Annem ayşeyle halam nebiş 2 Annem ayşeyle halam nebiye hem akranlar hemde biribirilerini çokseverler, nereye gitseler beraber giderlerdi,gen...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/annem-ayseyle-halam-nebis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Gidiyorum....', 'i-ste-gidiyorum-nurdane-diken-yc2i3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte gidiyorum, gönül sultanım.

İşte gidiyorum, güzel maralım..

Bülbül fiğan eyler, ahuzâr kalır

Yürekleri deler, tortusu durur

Eser bâd-ı sabâ yel gülü vurur

Bülbül fiğan eyler, canözü bulur..

İşte gidiyorum, gönül sultanım

İşte gidiyorum, güzel maralım

Azgın sular gibi çağladım aktım

Elleri vurarak, sinemi yıktım

Yârin gül bağına, çaresiz baktım

Baykuş viranede, şimşekler çaktım

İşte gidiyorum, gönül sultanım

İşte gidiyorum, güzel maralım....

Bâd-ı sabâ: Sabah yeli.

Ahû- zar: Ahlan inleyiş.', 'İşte gidiyorum, gönül sultanım. İşte gidiyorum, güzel maralım.. Bülbül fiğan eyler, ahuzâr kalır Yürekleri deler, tortusu durur Eser bâd-ı s...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iste-gidiyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalansız', 'yalansiz-turgay-yildirim-0r9vx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çıktığımız bu amansız yolda

Ben seni yalansız sevdim

Yüreğime koydum 

Başıma taç yaptım 

Şimdi ulaşılmaz dağlar 

Tepecik gelir bana

Dev orduları çete sanırım

Cellatlarıda melek 

Korkutmaz hiç bir ateş 

Korkutmaz hiçbir yangın

Zaten yaralıdır yürek

Yangın yeridir

Seni saatlere sığdırmak istedim

Sığmadın

Seni mekanlara yerleştirmek istedim

Yerleşmedin

Seni yüreğime koydum 

Yetmedi

Ben seni

Mekansız, zamansız sevdim



Turgay YILDIRIM

 26/10/2005', 'Çıktığımız bu amansız yolda Ben seni yalansız sevdim Yüreğime koydum  Başıma taç yaptım  Şimdi ulaşılmaz dağlar  Tepecik gelir bana Dev ordu...', ARRAY['Türk Edebiyatı','Şiir','Turgay Yıldırım']::text[], 8.5, '{"poet":"Turgay Yıldırım","poet_slug":"turgay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalansiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benle Yönet', 'benle-yonet-mustafa-kemal-bal-76d1e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Laik mi? Bu millet

Neden? Bunca illet

Ya Rabbi, ya Rabbi

Beni benle yönet!', 'Laik mi? Bu millet Neden? Bunca illet Ya Rabbi, ya Rabbi Beni benle yönet!...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kemal Bal']::text[], 8.5, '{"poet":"Mustafa Kemal Bal","poet_slug":"mustafa-kemal-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/benle-yonet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yansımaları', 'gece-yansimalari-recep-recai-nurcan-i1kim', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece kapatma şiir gözlerini

Her gün yaşadığımı yaşa bu gece

Şehrin uykusunu seyret benim gibi

Bir şiir yaz bana yalnız bu gece,

                            sımsıcak ellerinle.

Akan gözyaşlarımı çek kalemine

Bir satır, bir kelime, ya da bir hece,

Beni sevmeyişinin şiirini yaz

Seni ben dinleyeyim yalnız bu gece

                            pembe dudaklarını.

Gündüz yetmezmiş gibi, bilmem kızdın mı

Bilmeden rüyana giriverince.

Bu kez hayallerime dokunmayıver

Seni ben göreyim yalnız bu gece

                             deniz gözlerini.

11 Ocak 1993  İstanbul', 'Bu gece kapatma şiir gözlerini Her gün yaşadığımı yaşa bu gece Şehrin uykusunu seyret benim gibi Bir şiir yaz bana yalnız bu gece,          ...', ARRAY['Türk Edebiyatı','Şiir','Recep Recai Nurcan']::text[], 8.5, '{"poet":"Recep Recai Nurcan","poet_slug":"recep-recai-nurcan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-yansimalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar...', 'bir-zamanlar-ulvi-ziya-ci7dg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eblehlerin nazarında; 

batılı demek,

uygar demekti...

Uygar canavarın gâyesi:

yakıp,yıkıp,öldürmekti...

Ülkeleri böldürmekti...

Ne bulursa sömürmekti...

Toplumların yazgısı; 

sanki,

kirletilmiş beyinlerin emriyle,

güdülmekti...

Normal zamanlarda bile

zâten çok zordu yaşamak

Geçim derdi; 

çok ağır bir yük altında

kan terleyip,yürümekti...

Mahşer yeri oldu dünyâ

bu hengâmede; 

adâleti,uygarlığı,insanlığı aramak

boşuna bir emekti...

Binbir çeşit

kalleş malı silâhlar

sinek gibi kırdı hep mâsumları

ne gören oldu.ne acıyan...

Susturulmuştu vicdan...

Canlıların çoğu; 

yeyip,içip,eğlenen,

keyfeden eşekti...

Ağla ey yoz asır,ağla; 

İnsanlık,insanlardan elini çekti...

Hani ? ...

''Bir insanı haksız yere öldürmek,

bütün insanları öldürmek''....ti....', 'Eblehlerin nazarında;  batılı demek, uygar demekti... Uygar canavarın gâyesi: yakıp,yıkıp,öldürmekti... Ülkeleri böldürmekti... Ne bulursa s...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-zamanlar-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalini Öperken', 'hayalini-operken-recep-recai-nurcan-bn0d6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim kapanmıyor bu gece

gökyüzünde geziniyor yıldızlar

kimsesiz sokaklar.

Çağırıyorum yıldızları,

taa, pencereme kadar

nasıl uyuduğunu anlatıyorlar...

Ürkek bakışların canlanıyor hayalimde

gülüşlerin geliyor aklıma,

sabit fikirliliğin.

Boş vaktinin hiç olmayışı,

koparıyor seni benden, yavaş yavaş.

Lacivert gökyüzü açılmış! 

farkında değilim.

Çıkmıyorsun bir türlü hayalimden,

görmek istemiyorum eskisi gibi,

kararsız rüzgârlarında,

deniz gözlerini.

Artık sensiz hayattan,

bir şey beklemiyorum.

Yıldız dostlarım bile,

terketmiş beni.

Tıpkı, senin gibi.

Yarın ne çabuk olmuş! 

daha uyumadım bile.

Bu kaçıncı uykusuz gecem,

ansızın beliriversen, hayalini öperken.

14 Ocak 1993 istanbul', 'Gözlerim kapanmıyor bu gece gökyüzünde geziniyor yıldızlar kimsesiz sokaklar. Çağırıyorum yıldızları, taa, pencereme kadar nasıl uyuduğunu a...', ARRAY['Türk Edebiyatı','Şiir','Recep Recai Nurcan']::text[], 8.5, '{"poet":"Recep Recai Nurcan","poet_slug":"recep-recai-nurcan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hayalini-operken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza...', 'sonsuza-mustafa-tas-aqn4m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk defa yazarken ellerim titriyor

Nedensiz değil

Ve satırlar upuzun,bitmek bilmiyor

Anlamsız değil

Belki hala anlamadın,anlamayacaksın

Önemli değil

Gözlerime bir daha bak

Boş değil

Orada da sen varsın beni anlamayan

Bu ilk değil

Bir sır değil artık, söyleyeceğim

Seni sevdiğim değil

HER ZAMAN SEVECEĞİM', 'İlk defa yazarken ellerim titriyor Nedensiz değil Ve satırlar upuzun,bitmek bilmiyor Anlamsız değil Belki hala anlamadın,anlamayacaksın Önem...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Taş']::text[], 8.5, '{"poet":"Mustafa Taş","poet_slug":"mustafa-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sonsuza-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldin Yeniden Doğdum', 'geldin-yeniden-dogdum-tulay-sustam-v0imz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir martının gagasında

Adını sayıklamalarım

Ve kanatlarında

Ayağımın yerden kesilip sana gelmelerim

Can ikizim,

Kurumuş bir gülün 

Dikeniyim sensiz…

Anlasana yâr! ...

Yokluğun; 

İliklerine kadar buz kesmiş,

Duvarlar da çivi izi…

Sensiz! ...

Direksiz yüreğim

Çakmak çakmak gözlerinde 

Yakıyorum son sigaramı

Ve bulutlardan anlıyorum

Beni 24 saate böldüğünü

Anla yâr, ben güneşin kızıyım

Rüzgârın oğlu ol... 

Bir nefesle söndür ateşimi

Adını her andığımda 

Bir nefeslik duraksıyorum

Adımdan önce gelir adın…

Bir sonraki cümlem

-Biz- ile başlıyor…

Tırnaklarım geçmiyor adına

Biliyorum ki sen yalnızca bana aitsin

Göz bebeklerinde 

Mavi yolculuğuma çıkıyorum

Uzaklaştıkça gölgem 

Sana daha çok yaklaşıyorum

Gözenekleri aşka susamış

Bir yüreğin çığlığını duyuyor musun? 

Anason kokan yokluğunda 

Aşk sarhoşuyum…

Ey yâr! ...

Deniz gözlerine bir toz kaçsa

Rüzgârın ölümü elimden olur

Anlasana! ...

Gözümdeki tuzu değil,*

Denizde ki tuzu eledim de

Seni kendime öyle seçtim

Apostrofla

Dünden, bugünümü ayırdım

Yarınım sensin…

22-23 ekim

derin aşk kırıntıları', 'Bir martının gagasında Adını sayıklamalarım Ve kanatlarında Ayağımın yerden kesilip sana gelmelerim Can ikizim, Kurumuş bir gülün  Dikeniyim...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/geldin-yeniden-dogdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elif Hemşire', 'elif-hemsire-recep-recai-nurcan-oqoja', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En uzun gecemdin sen,

Yağmur kokan bir sabah,

Aldın başını gittin,

Yine yalnızım, eyvah! 

Lâleler halt işlemiş,

Senin rengin bambaşka,

Uykuyla küs gözlerim,

Düştüm düşeli aşka.

İnan şiir gözlerin,

Ne akılda, ne başta,

Bir göründün, bir gittin,

Güneş ile batışta.

Fütûrsuzca bir gülüş

Çağırır son bakışta

Ruhum seninle gider

Bedenim kalır taşta.

23/Kasım/1992  İstanbul', 'En uzun gecemdin sen, Yağmur kokan bir sabah, Aldın başını gittin, Yine yalnızım, eyvah!  Lâleler halt işlemiş, Senin rengin bambaşka, Uykuy...', ARRAY['Türk Edebiyatı','Şiir','Recep Recai Nurcan']::text[], 8.5, '{"poet":"Recep Recai Nurcan","poet_slug":"recep-recai-nurcan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/elif-hemsire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme...', 'gelme-ozen-oksuz-zg491', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Git...

Ama gülüşünü bende bırak

O eşsiz unutulmaz saflığı...

Bırak git...

Ağlamak olsa da karşılığı...

Git...

Bu son ağlamam arkandan

Dökülen son gözyaşı,

Yüzüne bile bakamadan...

Git...

Yalnızlığı öğretirim yüreğime

Alışırım ruhsuz bedenime

Umursama sakın...

Senden sonrasını bilme...

Git...

Ve GELME...', 'Git... Ama gülüşünü bende bırak O eşsiz unutulmaz saflığı... Bırak git... Ağlamak olsa da karşılığı... Git... Bu son ağlamam arkandan Döküle...', ARRAY['Türk Edebiyatı','Şiir','Özen Öksüz']::text[], 8.5, '{"poet":"Özen Öksüz","poet_slug":"ozen-oksuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelme-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'serpİLker', 'serpi-lker-recep-recai-nurcan-kier3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'S en kalbime girel İ

E ngin deniz çok deği L

R uhundaki güzelli K

P ervasızca sevgin E

İ mâ etmek güç kalı R

