INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yahya Ağa Destanı', 'yahya-aga-destani-alper-kuruk-zcxqc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki metre boyunda 

Bir çam yarması...

Lâkabı:''Adem Ejderhası''.

Henüz bıyıkları terlemiş iken

Yok idi onun bileğini büken.

İlk şöhreti başlar on sekizinde.

Basınca yirmi beşine

Adem Ejderhası,

Macaristan''da Budin''e

Oldu Yeniçeri Ağası.

Pekçe bastığı yer çöker,

Bilek gibi demirleri

Sanki tel gibi büker.

Bin beş yüz doksan beşte

Almanya''ya yapılmıştı bir sefer.

Kış gelince Türk''ler

Barınamazdı sınır topraklarında,

Yeteri kadar donatılır kaleler

Arta kalan ağırlıkla

Yüz binlerce asker

Çekilirdi kışın Belgrad''a.

On bin asker bu arada

Kalmıştı Estonibelgrad''da.

Kırk binlik bir kuvvetle

Almanlar bulundular 

Kaleyi muhasarada.

Kuşatım sürerse uzun

Etraftan da gelmezse

Erzak,cephane,yardım

Yiğitler harbe girse 

Atamazlardı tek adım.

Kalenin imdadına

En yakın yerlerden

Koştu birkaç bin gönüllü birden.

Göze çarptı ilk nazarda

Çam yarması Yahya Ağa

Nice yiğitler içinden.

Kuşatımın ilk haftasında

Bir yudum su kalmadı

Neferlerin tasında.

Belki on kılınç darbesinde

Yere düşürülemeyecek

İri vücudlu babayiğitler

Serim serim serilmişler

Yalıyorlar taşlarını sarnıcın

İçecek bir yudum su bulmak için.

Kaledekiler çok perişan...

Türk Ordusu Belgrad''dan

Kalenin yardımına ancak

İki ayda koşacak.

Bir tek çare vardı:

İstenmiyordu boşuna döküsün kan

Kaleyi VİRE  ile teslim etmek

Sonra da çekilip gitmek...

Düşman teklif etti vire

Estonibelgrad Paşasına.

Bir kişi karşı koydu bu emire.

Zira ağır gelmişti teklif 

Adem Ejderhasına.

Paşa kabul etti

Yoksa red devlete karşı ağır mes''uliyetti...

Kırdırmak istemiyordu susuzlıktan

Kaledeki birçok yiğidi.

Karşılıklı ikişer rehine

Göndererek iki kumandan

İmzaladılar hemen

Vire anlaşmasını.

Konuşmalarda bulunan

Kahraman Yahya Ağa

Söz aldı birden:

''Kabul etmiyorum kendimce

Vireyi ben.

Önüme baka bak başımı eğip

Düşmana kaleyi bırakıp gidemem.

Kalede kalıp susuzluktan yana

Köpek gibi de ölemem.

Önce tek başıma

Kaleden ben çıkacağım.

Ya öleceğim ya da

Düşmanı yıkacağm.

Belli olduktan sonra

Benim kaderim

Ve beni alırsa yer

Vire anlaşması ancak o zaman

Yürürlüğe girer...''

Estonibelgrad Paşası

Çıkarmadı sesini

Onu iyi tanıdığından.

Düşman temsilcisi dahi

Kabu etti teklifi.

Gidecekti daha sekiz fedai

Yahya Ağanın arkasından.

Okudular dokuz kişi

Kırk bin kişiye meydan.

Kale bedenlerinde

Dolaştı bir heyecan.

Yahya Ağa yanına beş yüz ok aldı

Dokuzu da çıktı kaleden

Ve kâfirin içine daldı.

Yanlarını zırhlarla bürülü 

Düşmanlar sardı birden,

Attığı herbir oktan

Yok idi boşa giden.

Okları tüketince

El attı kılıcına

Yüz düşman daha mal oldu

Taşan sonsuz hıncına.

Kılıçtan geçirirken

Sağını ve solunu,

Heyhat bir darb eile düşürdüler

İnsafsızca,sağ kolunu.

Adem Ejderhası Yahya

Ve sekiz yiğit

Nihayet olduar şehit...

Kaldı onlara hayran

Düşman kumandan.

Naklettirdi merasimle cesetlerini

Estonibelgrad''da bir tepeye.

Boş yere tepede dursunlar niye 

Bu büyük kahramanlar? 

Kanlarının aktığı yerde

Ele geçmez şehitlik tacı,

Ayaklarının bastığı yerde

Destan dolu şanlı bir tarih var...', 'İki metre boyunda  Bir çam yarması... Lâkabı:''Adem Ejderhası''. Henüz bıyıkları terlemiş iken Yok idi onun bileğini büken. İlk şöhreti başlar...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":124,"source_url":"https://www.antoloji.com/yahya-aga-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dileğimsin', 'dilegimsin-metin-yalti-skqo6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korkum 

bir gün düşeceksin 

sevdaya diye 

dilek dileyeceğim 

gidip Ayazma''ya... 

anılara tutunmayı bırakıp 

soyunman için 

gözlerimde parlayan yakomazlara 

27 Ekim.2005', 'Korkum  bir gün düşeceksin  sevdaya diye  dilek dileyeceğim  gidip Ayazma''ya...  anılara tutunmayı bırakıp  soyunman için  gözlerimde parlay...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dilegimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsızlık', 'anlamsizlik-savas-dincbas-ib2l4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen yoksun artık

birşeyler de yazamıyorum

sanki, şiirin kalbi sende atıyordu

ve şiir seninle anlam kazanıyordu

dün gece

kağıdı, kalemi ve kelimeleri 

aldım yanıma

yazmaya çalıştım

eksik bir şey vardı

kelimeleri karıştırdım

masanın üzerine yayıp

bir daha karıştırdım

anlamı bulamadım aralarında

bakmadığım

ne masanın altı kaldı, ne kanepenin

bulamıyordum

anlamsız da yazılmazdı ki

sonunda, bir köşede

anlamsızca otururken buldum anlamı

bu sefer kelimeler dağıldı

herbiri bir yere

toparlamak çok zor

kağıdı ve kalemi yatmaya gönderdim

ben de içmeye gittim meyhaneye

anlamsızca içtim, ağladım

boş gözlerle boşalan şişeye baktım

boş boş düşünmemek için

boş sokaklara çıktım dolaştım

eve gidip öylece bomboş yattım

rüyamda anlamı gördüm

valizini toplamış gidiyordu...', 'sen yoksun artık birşeyler de yazamıyorum sanki, şiirin kalbi sende atıyordu ve şiir seninle anlam kazanıyordu dün gece kağıdı, kalemi ve ke...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/anlamsizlik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varim Yogum Herseyim12', 'varim-yogum-herseyim12-ilker-guven-qkpe8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilirsemki uyumuyorsun

Cok mutluyumdur o zaman 

o Zaman ben bilirim aklinin bir kosesinde var oldugumu 

Bilirsemki uyuyorsun 

cok mutluyumdur  ozaman 

Bilirmiki o zaman ruyalarinda var oldugumu 

BeN Seni senden daha cok sevdigimi biliyorum', 'Bilirsemki uyumuyorsun Cok mutluyumdur o zaman  o Zaman ben bilirim aklinin bir kosesinde var oldugumu  Bilirsemki uyuyorsun  cok mutluyumdu...', ARRAY['Türk Edebiyatı','Şiir','Ilker Guven']::text[], 8.5, '{"poet":"Ilker Guven","poet_slug":"ilker-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/varim-yogum-herseyim12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varim Yogum Herseyim13', 'varim-yogum-herseyim13-ilker-guven-8i462', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorum; 

Yine suyunu cikardim bu kadar sms gondererek

Ben bununla mutlu olmayi ogrendim 

seni gonulden severek 

sana iyi geceler diyorum KADINIM 

Seni hasretle öperek', 'Biliyorum;  Yine suyunu cikardim bu kadar sms gondererek Ben bununla mutlu olmayi ogrendim  seni gonulden severek  sana iyi geceler diyorum ...', ARRAY['Türk Edebiyatı','Şiir','Ilker Guven']::text[], 8.5, '{"poet":"Ilker Guven","poet_slug":"ilker-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/varim-yogum-herseyim13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alkol uykusu', 'alkol-uykusu-i-rfan-tansel-turhan-amhgn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlık mağralara kapatıp kendimi

Alkol uykusuna yatıyorum

Anason kokusuna yenik düşlerim

Kadehlerden yansırken

Ardına bile bakmıyor zaman

                                     arada bir ayılıp, 

“geçmişi,seni ve kendimi özlüyorum”

“iyi geceler. öpüldün...”

Şehrin uğultusundan uzaklaşırken güneş

Ve hüznü düşerken korkularıma karanlığın

Sığınılası bir mekanmıydı aradığım? 

Oysa iyi geceler de öpülmeseydim

Gün batımını bu kadar sevmezdim.

Yitip giden zamandı,

                             ben geceye yenildim.

Böyle gecelerde yenilmeseydim

Karanlığımı ışıtan ay’ı

Rakı beyazlığında sevmezdim.', 'Karanlık mağralara kapatıp kendimi Alkol uykusuna yatıyorum Anason kokusuna yenik düşlerim Kadehlerden yansırken Ardına bile bakmıyor zaman ...', ARRAY['Türk Edebiyatı','Şiir','İrfan Tansel Turhan']::text[], 8.5, '{"poet":"İrfan Tansel Turhan","poet_slug":"i-rfan-tansel-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/alkol-uykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varim Yogum Herseyim14', 'varim-yogum-herseyim14-ilker-guven-c1tur', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben yeni sevmedim seni 

anladim bendeki seni 

hic sevmedim bundan once

acemiligime ver; bagisla beni 

eminmisin bana dersen EVET

ysaiyorum bunu ben gonulden severek', 'Ben yeni sevmedim seni  anladim bendeki seni  hic sevmedim bundan once acemiligime ver; bagisla beni  eminmisin bana dersen EVET ysaiyorum b...', ARRAY['Türk Edebiyatı','Şiir','Ilker Guven']::text[], 8.5, '{"poet":"Ilker Guven","poet_slug":"ilker-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/varim-yogum-herseyim14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varim Yogum Herseyim15', 'varim-yogum-herseyim15-ilker-guven-5l5ua', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizligin Hasreti bitmez

sen yanimda olsanda farketmez

sana oyle bir ask yasiyorumki 

dualarim bile kifayetli gelmez', 'Sensizligin Hasreti bitmez sen yanimda olsanda farketmez sana oyle bir ask yasiyorumki  dualarim bile kifayetli gelmez...', ARRAY['Türk Edebiyatı','Şiir','Ilker Guven']::text[], 8.5, '{"poet":"Ilker Guven","poet_slug":"ilker-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/varim-yogum-herseyim15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Gecikme', 'i-lk-gecikme-sair-adem-2v24q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'senden kopmak için

ille mazgallı kapımın sürgüsünü

çözmem gerekmez

adımlarını bilmemek(senli benli olan yollarına dökülen) 

gözlerindeki ifadeyi es geçmek

hatta başka bir diyarı düşünmek dahi

senden kopmak demektir

senden kopmak için

ille bir dış etki gerekmez

kısarım kandilimi

çekilirim köşeme

yalnız sen görürsün beni

kaldırıp yere vurmak 

nede kolay

bir çerçeveyi

ben seni bulana kadar

kaç dil yor(ul) dum

heyula çıkmazıydı hep çoğu

duvarları kimse anlamıyor

kendini ören yosundan başka

ben anladım:

arkadaşı umut

kuzguncuğa yaslanan

senden kopmak için

elveda demem gerekmez

geç kalırım

-söz verilmiş-buluşmaya

                                            (26.06.04) 

                                           f tipi hapishane EDİRNE', 'senden kopmak için ille mazgallı kapımın sürgüsünü çözmem gerekmez adımlarını bilmemek(senli benli olan yollarına dökülen)  gözlerindeki ifa...', ARRAY['Türk Edebiyatı','Şiir','Şair Adem']::text[], 8.5, '{"poet":"Şair Adem","poet_slug":"sair-adem","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ilk-gecikme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varim Yogum Herseyim16', 'varim-yogum-herseyim16-ilker-guven-tak8n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni asik ettin kendine,

Oldum bir avare berdus

Meger alkolikmisim ben

olmazdim ama icmeden sarhos

Seni sevmek ne kadar guzelmis Semram

acisi bile yapiyor mayhos', 'Beni asik ettin kendine, Oldum bir avare berdus Meger alkolikmisim ben olmazdim ama icmeden sarhos Seni sevmek ne kadar guzelmis Semram acis...', ARRAY['Türk Edebiyatı','Şiir','Ilker Guven']::text[], 8.5, '{"poet":"Ilker Guven","poet_slug":"ilker-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/varim-yogum-herseyim16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varim Yogum Herseyim17', 'varim-yogum-herseyim17-ilker-guven-qi1qu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne aklimda seni dusunmeyecek kadar zaman 

ne icimde beni sana surukleyen bir ruzgar

ne seni goremeyecek kadar guclu

Nede sensizlige dayanacak bir kalbim var', 'Ne aklimda seni dusunmeyecek kadar zaman  ne icimde beni sana surukleyen bir ruzgar ne seni goremeyecek kadar guclu Nede sensizlige dayanaca...', ARRAY['Türk Edebiyatı','Şiir','Ilker Guven']::text[], 8.5, '{"poet":"Ilker Guven","poet_slug":"ilker-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/varim-yogum-herseyim17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varim Yogum Herseyim18', 'varim-yogum-herseyim18-ilker-guven-cqgys', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu mesajlar bitmez daimi olark surer

bendeki sevdan varya olume benimle gider

Bir sicak yuz aramistim tenha sokaklarda

sanki hgerkes yabanci herkes garipti bana

ne halimi soran var nede tanidik bir sima

mutsuzluklar goruyorum etrafta sensiz daima', 'Bu mesajlar bitmez daimi olark surer bendeki sevdan varya olume benimle gider Bir sicak yuz aramistim tenha sokaklarda sanki hgerkes yabanci...', ARRAY['Türk Edebiyatı','Şiir','Ilker Guven']::text[], 8.5, '{"poet":"Ilker Guven","poet_slug":"ilker-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/varim-yogum-herseyim18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varim Yogum Herseyim19', 'varim-yogum-herseyim19-ilker-guven-gphuj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suskunlugumun beynimi vurdugu yerde

Ellerimle konustum tutulmusken gozlerim

Meydan okudum insanlari tutsak edene

Ruzgar savas kokusunu tasimasin istedim

Ama ben bu kadar konuda bile yanliz seni sevdim', 'Suskunlugumun beynimi vurdugu yerde Ellerimle konustum tutulmusken gozlerim Meydan okudum insanlari tutsak edene Ruzgar savas kokusunu tasim...', ARRAY['Türk Edebiyatı','Şiir','Ilker Guven']::text[], 8.5, '{"poet":"Ilker Guven","poet_slug":"ilker-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/varim-yogum-herseyim19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyarlık Şafağı', 'i-htiyarlik-safagi-sadik-altinkaynak-pmzxa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İhtiyarlık Şafağı

Bir aynada uyandım 

Gençlik uykusundan

Doğdu ihtiyarlık şafağı

Ağaran şakaklarımdan

Heyhat... gitti gençliğim bir gecede

Ne de uzunmuş gaflet gecesi

Ruhum azapta aklım işkencede

İhtiyarlık hayatın en zor bilmecesi

Ak pak olmuş saçım sakalım

Bin bir sır saklı bu bilmecede

Sizde cevabı var mı bakın bakalım

Bence cevap zaman denen iki hecede

Nasıl da hiç uyanmadım

Ne kar yağdı saçlarıma ne de kırağı

Beyaza da boyamadım

Şaklarımdaki şu kefen beyazlığı

Gelip çatan ihtiyarlık şafağı

			Sadık ALTINKAYNAK', 'İhtiyarlık Şafağı Bir aynada uyandım  Gençlik uykusundan Doğdu ihtiyarlık şafağı Ağaran şakaklarımdan Heyhat... gitti gençliğim bir gecede N...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ihtiyarlik-safagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varim Yogum Herseyim20', 'varim-yogum-herseyim20-ilker-guven-qc3ay', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni ilk gordugumde 

Ellerini tutmak istedim

Merakli gozlerle bana baktiginda

Resmini aklima cizmek istedim

Alirken sen aklimi Basimdan

Maziyi seninle yasamak istedim', 'Seni ilk gordugumde  Ellerini tutmak istedim Merakli gozlerle bana baktiginda Resmini aklima cizmek istedim Alirken sen aklimi Basimdan Mazi...', ARRAY['Türk Edebiyatı','Şiir','Ilker Guven']::text[], 8.5, '{"poet":"Ilker Guven","poet_slug":"ilker-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/varim-yogum-herseyim20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varim Yogum Herseyim21', 'varim-yogum-herseyim21-ilker-guven-1igxt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir deli dalgadir hayat dedigin 

Sayili gun degilmidir omur bildigin 

Cile ceker sevinir, birde aglarsinya

Saili gun degilmidir Huzun dedigin 

Kizginliklarin gelir surekli aklina

Ya! ! !  Cabuk gecmezmi senin su sinir dedigin 

Senki bana KADINIM olmussun 

soylesene canim Semram unutulurmu sevgi dedigin', 'Bir deli dalgadir hayat dedigin  Sayili gun degilmidir omur bildigin  Cile ceker sevinir, birde aglarsinya Saili gun degilmidir Huzun dedigi...', ARRAY['Türk Edebiyatı','Şiir','Ilker Guven']::text[], 8.5, '{"poet":"Ilker Guven","poet_slug":"ilker-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/varim-yogum-herseyim21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varim Yogum Herseyim22', 'varim-yogum-herseyim22-ilker-guven-8tb9x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben yasayamadim seninle gecen guzel gunleri

Beynime yazdim; Tutacagim verdigim sozleri

Sozler keleimelerde kalmayacak canim KADINIM

Yasatacagim sana verdigim her sozun degerini 

bilmem icin senin bendeki degerini 

Yasayabilmek icin seni ve beni 

Gormem lazimmis ayriligin kederini', 'Ben yasayamadim seninle gecen guzel gunleri Beynime yazdim; Tutacagim verdigim sozleri Sozler keleimelerde kalmayacak canim KADINIM Yasataca...', ARRAY['Türk Edebiyatı','Şiir','Ilker Guven']::text[], 8.5, '{"poet":"Ilker Guven","poet_slug":"ilker-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/varim-yogum-herseyim22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Rengi', 'gecenin-rengi-sadik-altinkaynak-eljiv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin Rengi

Gece saçlarından almış rengini

Arasam dünyada bulamam dengini

Gönlüm kin fukarası sevgi zengini

Her yana bu sevgiyi yaysam diyorum

Gündüz gözlerinin parıltısıyla ışır

Bakışın mecnun eder aklım karışır

Gülüşünde dünya sulh olur küsler barışır

Her yüreğe barışı koysam diyorum

Varlığınla ısınır yaz olur kışlar

Teker teker döner göç eden kuşlar

Seni taltife yetmez bütün alkışlar

Yüreğimi buket yapıp sunsam diyorum

Duruşunda bir efsun gülüşünde bir sihir

Sevgi dudaklarından süzülen bir nehir

Az gelir dünyayı versem sana mehir

Yıldızları ayağına sersem diyorum

			Sadık ALTINKAYNAK', 'Gecenin Rengi Gece saçlarından almış rengini Arasam dünyada bulamam dengini Gönlüm kin fukarası sevgi zengini Her yana bu sevgiyi yaysam diy...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gecenin-rengi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dünyanın Düzeni Bu', 'bu-dunyanin-duzeni-bu-nurcemal-ozturk-l2ad6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vur başına al ekmeği elinden

Bu dünyanın düzeni bu kardeşim

Zalim anlamaz mazlumun halinden

Bu dünyanın düzeni bu kardeşim

Göremedim bozanı be kardeşim.

Zenginle fakirin arası açık

Belli değil kim akıllı kim kaçık

Koskoca güneşi sıvamış balçık

Bu dünyanın düzeni bu kardeşim

Göremedim bozanı be kardeşim.

Ezilenin gıkı bile çıkmıyor

Yetime,öksüze kimse bakmıyor

Bu gidişe bir dur diyen çıkmıyor

Bu dünyanın düzeni bu kardeşim

Göremedim bozanı be kardeşim.

Sevgi,şevkat almış başını gitmiş

Edep,haya,ar defterden silinmiş

Herkes birbirine kılıç bilemiş

Bu dünyanın düzeni bu kardeşim

Göremedim bozanı be kardeşim.', 'Vur başına al ekmeği elinden Bu dünyanın düzeni bu kardeşim Zalim anlamaz mazlumun halinden Bu dünyanın düzeni bu kardeşim Göremedim bozanı ...', ARRAY['Türk Edebiyatı','Şiir','Nurcemal Öztürk']::text[], 8.5, '{"poet":"Nurcemal Öztürk","poet_slug":"nurcemal-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-dunyanin-duzeni-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikayet..', 'sikayet-nurdane-diken-0yxgg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Köylüyü efendi, başına koydun.

Halkını yücelttin, değerli kıldın

Şan, şeref, Bayrak ve özgürlük verdin 

Nasıl özlemiyem, seni ben ATAM..

Dünyada güneşsin, saf ışığınla

Türk''lüğün şanısın, nur şafağınla

Bozkurt''un kanısın, Turan yoluyla

Nasıl özlemiyem, seni ben ATAM..

Hain kanı sardı, şanlı vatanı

Şehitler utandı, kanı satanı

Kin tohumu ekti, içe katanı

Şikayetim budur, sanadır ATAM..

Gençler televole, kurbanı oldu

İlim, irfan yolda hainlik buldu

Hırsız başa geçti, başkanlık buldu

Şikayetim budur, sanadır ATAM.

Suları sattılar, paraya taptı

Dürüstlük sınıfta, alaya kaldı

Cumhuriyet''inle AB''ye baktı

Şikayetim budur, sanadır ATAM..

Güney illerimiz, kürdistan oldu

Papaz ruhban diye, kafayı buldu

AB yollarında, hainler kuldu

Şikayetim budur, sanadır ATAM..

Millî, ulusallık, demode oldu 

Resmini, Bayrağı kıskaca aldı

AB yollarında, tıkandı kaldı

Şikayetim budur, sanadır ATAM..

Profesörlere çamurlar attı

Cumhuriyet''ini unuttu kaldı

Soykırımcı diye, suçlara battı

Papazlar ellere, kınalar yakdı

Şikayetim budur, sanadır ATAM..

Bizler yoldan çıktık, şaşırdık yolu

Satılan basının, kartları boldu

Düşman uyumadı, uyuttu durdu

Şikayetim budur, sanadır ATAM..

Bağışla bizleri, tekrar gel Atam

Hadlerini bildir, düşmana atam.

Sensiz ne yaparız, sonra biz atam.

Şikayetim budur, sanadır YÜCEM....', 'Köylüyü efendi, başına koydun. Halkını yücelttin, değerli kıldın Şan, şeref, Bayrak ve özgürlük verdin  Nasıl özlemiyem, seni ben ATAM.. Dün...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sikayet-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet', 'cumhuriyet-ahmet-tigli-ubz5m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saltanat tahtından indi gününde

Halkın  saltanatı  geldi bir günde

Tarihin yazdığı  ı büyük düğünde

Birleştik ulusca Cumhuriyette.

Temeli atıldı Anadolu''da

Dünyaya ihtardır yazdık sonunda

Kemalist devrimin  onur katında

Kabardı göğsümüz Cumhuriyette.

Bir halkın  kararı  kendi yönünde

Özgürlük ateşi yanar gönlünde

Şehitler dururken ulus önünde

İstiklal meş''ale Cumhuriyette.

Yüzyıllar silkindi büyük savaşta

Ulusun başında Atam en başta

Devrimler şahlandı yeni bir aşkta

Aydınlık çağımız Cumhuriyette.

Dediler''ikinci''geçer bu çağda

Bırakın vefayı zillet dorukta

Şehidin kanından bayrak yukarda

Atamın kurduğu Cumhuriyette.

Bir ulus dirildi özgür vatanda

Hilafet gerekmez çağdaş toplumda

Yıkılmaz kaledir millet katında

Devrimler sürecek Cumhuriyette.

                            Ahmet TIĞLI 17.10.2005 saat 1.05', 'Saltanat tahtından indi gününde Halkın  saltanatı  geldi bir günde Tarihin yazdığı  ı büyük düğünde Birleştik ulusca Cumhuriyette. Temeli at...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tığlı']::text[], 8.5, '{"poet":"Ahmet Tığlı","poet_slug":"ahmet-tigli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cumhuriyet-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçemediğim', 'vazgecemedigim-adem-uzun-wfns8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Solgundur bet, benizim.

Sensiz hiçkimsesizim.

Gözünde bir denizim,

Ayırma gözlerinden.

Ne kötü, bahtiyarım.

Dönülmeyen yollarım.

Sende kaldı bir yarım,

Hepsi senin istersen.

Ne günlerim ne ayım.

Harfe karıştı sayım.

Ben sana müptelayım.

Müptelayım sana ben.', 'Solgundur bet, benizim. Sensiz hiçkimsesizim. Gözünde bir denizim, Ayırma gözlerinden. Ne kötü, bahtiyarım. Dönülmeyen yollarım. Sende kaldı...', ARRAY['Türk Edebiyatı','Şiir','Adem Uzun']::text[], 8.5, '{"poet":"Adem Uzun","poet_slug":"adem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vazgecemedigim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzayan bir geyik sesiyle gecede', 'uzayan-bir-geyik-sesiyle-gecede-cengiz-kilcer-mkul2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'UZAYAN BİR GEYİK SESİYLE GECEDE

sertaç canbolat’a 

akrep ne kir ne de kin tuttuğu için akıtmaz zehrini

işte biz şimdi bunun için niye ağlamayalım. 

gökyüzünde şavkı yitik bir ay

gecenin soğuması bundan mı? 

trikotajcıların karanlığı yarasına basması

yanlış İsa’yım ne etim var ne kanım 

uzayan bir geyik sesiyle gecede

ben en belâ mı belâ zamirimizdir çünkü. demeyiz

kırlangıçdönümü düşer kara bir taflan 

düşer avucumuza düşmüştü. anımsa bulacaksın zamirimizdir çünkü.

bağan bir dil kullandığım söyleniyor şiir piyasalarında

oysa yurdum çoktan soğumuş bir krater gölü 

küllerine gömülü anka küçük ilanlar sütununda. 

karakolları kasaturaları unutmayalım

dilsiz operet şarkıcılarını 

yakalım bize  vaat edilmiş toprakları 

ve onların okunaksız evraklarını post-modern çadır tiyatrolarını

kurban ve çığlığı henüz para getiren bir işe dönüşmemişken

bizi bağışlayacak bir yürek var mıdır? 

karanlıkta ve kargışta 

işsiz ve sağanak altında bir sinema kuyruğunda. 

diyorum ki bizi bağışlayacak 

yanıtsız bir soruyum ne de olsa

sevgilim saçlarını tarıyor melankolinin solgun aynasında

bak burada adınla çaprazlanıyor acı 

boşlukta sallanan dört engerek 

ve kaç melek kurban ettim bilmiyorum 

her sabah adlarını ve allahlarını unuttuğum

her biri yaslı bir çiçek gibi durur 

bir fotoğrafçı camekânında.

suretiyle aslı arasında hiç  kapanmayan uçurum gülümsemesi.

bir gün geri döner mi  o uçurumdan çığlımın yankısı? 

herkes bilir yılgınlığı çünkü her yerde biraz kırgınlık vardır

unutulmuş yeminlerde, çekilmeyen telgraflarda

çünkü her yerde biraz eskir aile resimleri 

istasyonlarda herkesin bir şeyini unuttuğu 

istasyonlarda baş dönmesi kuzgun ve kundak 

her yerde günlerden biraz pazartesi. 

ey gökteki en yaşlı yıldız kaç yaşındadır? 

gece karışmadan kanıma söyle bana 

unutmak ve anımsamak bağışlanmak da istemiyorum artık bağışlamak da. 

gökyüzünde şavkı yitik bir ay gecenin soğuması bundan mı 

gecede uzayan bir geyik sesiyle gecede

ve ara yitireceksin denilmiştir bizim için bilcümle tevratlarda 

sonra yedi defa yoksulluk olacak 

sonra yedi defa taun

sonra yedi defa ağılarını içine akıtacak akrepler. 

çün biz yoksulluğun en yüksek liyakat nişanıyla onurlandırıldık 

işte o zaman gümrah bir acı vurdu göğsümüze. 

gümrah bir sudan gümrah ateşlere kaçtık

boğulmak ve boğulmak içindi 

pes imdi adımızla verev acı 

akrep ne kir ne de kin tuttuğu için akıtmaz zehrini

ve ey! işte biz bunun için niye ağlamayalım

tipi kapatmışsa baktığımız bütün atlaslardaki yolları 

gecede uzayan bir geyik sesiyle gecede

kurşun dökülen su, küle dökülen su aynı 

gecede uzayan bir geyik sesiyle gecede 

körüyüz turnasız suyun ve balıksız göğün

anımsa suda ve gökteki ağırlığımız aynı 

eksik ezberlenmiş kahır gecede ağıtla ninni birbirine karışır nasılsa 

bak burada adınla çaprazlanıyor acı

yine de kanına nakışlanan dolunayda 

o elmas hançerleri kalbinde sına 

sına ve alıştır kanını sebil et

tütsün öd ağacı kırgınlığının

kül, tecim ve soyka 

uzayan bir geyik sesiyle gecede

yağmur kesildiğinde 

madem ki, kalplere mil çekmede ustasın 

tetiğin boşluğunu al içindeki ateşi harla 

kâfurun sür şakağına. 

kara bir taflan avucuna düşmüştü anımsa kırlangıçdönümü taşrada

aynı periyi sevmiştik veremin bütün alfabelerde yazılışı tekdüzeydi 

sesiyle gecede uzayan bir geyik sevmiştik 

çok eskiden de eski bir sinema afişinde 

adı neydi bilmezdik. kesindi evlere  temizliğe gitmezdi 

çünkü çorak ve esmerdir temizlikçi kadınların ilmühaberi 

sevmiştik melek miydi iblis miydi 

hâlâ kanırtıyor mu yüreğindeki mührü

masumiyet çocukluğun hakikatiyse 

işsiz babalar savatlı sabahların ölgün saatlerinde gelirse

ve ey! işte çocuklar şimdi bunun için niye niye niye ağlamasın

kan da su da aksın kendince. gecede. sesiyle uzayan bir geyik geceyle

kadıköy 23/07/2005', 'UZAYAN BİR GEYİK SESİYLE GECEDE sertaç canbolat’a  akrep ne kir ne de kin tuttuğu için akıtmaz zehrini işte biz şimdi bunun için niye ağlama...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kılçer']::text[], 8.5, '{"poet":"Cengiz Kılçer","poet_slug":"cengiz-kilcer","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/uzayan-bir-geyik-sesiyle-gecede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burdayım', 'burdayim-hekim-coskun-dk4mq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'önde ve tek başıma

arkamda düzensiz bir yaşam

ve ben yürüyordum

hep yürüdüm.

ülkemin zifiri karanlık sokaklarında

dudaklarımda ıslık

yüreğimde sen vardın.

korkuyordum; 

korkmalıydım da

yaşamın tüm nefretini kuşanmış,

düzensizliğin tüm  korkuları üzerinde insanlardan,

aç ve sefilliklerdi.

karartılmış beyinleri,

pis kokan tüm düşünceleri

iğrenç dedikleri tüm böcekler  gibiydi.

göksümde taşıdığım sevginden güç alarak

sevgiyle baktığım yaşama

tek başıma ve yalnızdım,

yürüyordum.

tüm gücümle yeni bir yaşama. 

bana dost aksanınla  söylediğin

her şey den zevk alarak..

dişe-diş yürüdüm.

bak biraz kırgınım sana bilesin

gecemde yoktun

üzerime örttüğüm battaniye içinde

iki büklümdüm.

bilmediğim tüm dillerde seni sevdim ben

dudaklarımın ucuna kadar gelip

bir türlü söyleyemediğim her şey için

bana kızma.

bir ara aklına gelirsem,

ara.

ben buradayım.', 'önde ve tek başıma arkamda düzensiz bir yaşam ve ben yürüyordum hep yürüdüm. ülkemin zifiri karanlık sokaklarında dudaklarımda ıslık yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/burdayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp zamanlar...', 'kayip-zamanlar-ayfer-yildiz-x41nh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kayıp zamanlarım oldu benim

    Kayıp sevinçlerim

    Bi tek yalnızlığımı yitirmedim

    Yalnızlığımı takıp koluma

    Elele bi kefen biçtik yüreğimi sızlatan anılara.

    Büyük fıtınalarım oldu benim

    Sessiz sessiz yürek depremlerim

    İçimi parçaladı da zehir rengi hüzünlerim

    Ne aynalar bildi acımı nede sevdiklerim.

    Büyük savaşlarım oldu benim

    Bana düşman herşeyi yüreğimle ezip geçtim

    Ne düşmana yenildim ne kadere

    O kaderimide ellerimle çizdim.

    Sahipsiz mektuplarım da oldu benim

    Kime yazdığımı asla bilmediğim

    Belki tanrıya yakarışlarımdı

    Belki vefasızlara haykırışlarım.

    Büyük zaferlerim oldu benim

    Hayata gülen bendim en büyük zaferim

    Ne sızı kaldı yüreğimde

    Ne bir iz kaldı maziden bugünümde.

    Ve ben bugün

    Odamı maviye boyadım

   Mavi umutlarım mavi sevinçlerimle güne başladım

   Geceye gömüp kayıp zamanlarımı

   Bu sabah yüklendim sevda bulutlarını.', 'Kayıp zamanlarım oldu benim     Kayıp sevinçlerim     Bi tek yalnızlığımı yitirmedim     Yalnızlığımı takıp koluma     Elele bi kefen biçtik...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Yıldız']::text[], 8.5, '{"poet":"Ayfer Yıldız","poet_slug":"ayfer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kayip-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tundralarda', 'tundralarda-cengiz-kilcer-62d5i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'TUNDRALARDA

                         Eleni Karaindrou’nun “Ağlayan Çayır”ını dinlerken

ama şimdi niye kesik bir bilek gibi hatırlıyorum? 

hatırlanır! geceyse ve ay derin bir yara gibi açılmışsa

oysa buradayım işte uzakta tundraların arasında 

yağan karın altında bildik bir yarayla

erenköyünde gece evinin içinden geçen trenlere el sallamada

göğsünün ortasında uğul uğul uğuldayan bir gar yalnızlığıyla.

resneli’nin dağlarında neyin kaldı? 

943’te tentürdiyot içerek intihar etmiş 

bir kızın annesi dururuz yine beyciğimle aynı yüreciğin ayazında

sovyetler umumî taarruza başladı 19 temmuz

943’te tentürdiyot içerek intihar etti bir kız tatavla’da

27 yaşında bir bayanım bir annem var hayatta.

çalışıyorum da cibali tütün fabrikasında.

evlenmektir muradım bir bayla.

bekar da olabilir dul da. manolya düğün salonunda.

943’te tentürdiyot içerek intihar etti bir kız tatavla’da

geceydi ve ay beyaz bir gül gibi açılmıştı

dururduk beyciğimle ah dursaydı

                                                yine aynı yüreciğin ayazında...

arkadaşım ki; evinin içinden geçen trenlere el sallamada

göğsünün ortasında uğul uğul uğuldayan bir kar yalnızlığıyla

ha tır la  ke sik bir bi lek ne yi ha tır la tır sa! 

Güz  2004', 'TUNDRALARDA                          Eleni Karaindrou’nun “Ağlayan Çayır”ını dinlerken ama şimdi niye kesik bir bilek gibi hatırlıyorum?  ha...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kılçer']::text[], 8.5, '{"poet":"Cengiz Kılçer","poet_slug":"cengiz-kilcer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tundralarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gelmiş', 'bahar-gelmis-resul-ustun-2yeco', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akasyam,

karadutum,

caneriğim,

güzelim,

kara sevdam! 

''hoş gelmiş,

sefa gelmiş,

başım gözüm üstüne.''

Bahar gelmiş duydun mu? 

bastığın toprak,

erken doğum sancısında.

Karıncalar uyanmış,

hepsinde bir heyecan,

bir telaş...

Bahar gelmiş arkadaş,

bahar gelmiş duydun mu? 

gökyüzü ağlarken,

bağlar, bahçeler halay kurmuş.

Uç uç böceği bile

şaha kalkmış,

dans eder dururmuş.

Yoncalar,

papatyalar,

buram buram kokmadalarmış.

Ahhh! 

Ah be arkadaşım.

sırdaşım,

deli sevdam! 

bahar gelmiş duydun mu?', 'Akasyam, karadutum, caneriğim, güzelim, kara sevdam!  ''hoş gelmiş, sefa gelmiş, başım gözüm üstüne.'' Bahar gelmiş duydun mu?  bastığın topra...', ARRAY['Türk Edebiyatı','Şiir','Resul Üstün']::text[], 8.5, '{"poet":"Resul Üstün","poet_slug":"resul-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bahar-gelmis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 58', 'resaran-siir-ve-beyitsiler-58-huseyin-avdic-taw45', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Herşey Bilim Ve Akıldan Beklenmez

Her şeyi bilim ve akıldan beklemek; hatadır, çıkmaz sokaktır.

En iyi, güzel çare; Allah''ın Kitabı''na, Elçisi''ne sormaktır.

Berlin, Ekim 2005.', 'Herşey Bilim Ve Akıldan Beklenmez Her şeyi bilim ve akıldan beklemek; hatadır, çıkmaz sokaktır. En iyi, güzel çare; Allah''ın Kitabı''na, Elçi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/resarani-siir-ve-beyitsiler-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kazarım Mezarımı', 'ben-kazarim-mezarimi-ferit-gursoy-r0w2b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölmekse ölmek 

Ne canı düşünürüm 

Nede kıyımı

Sana kıyamam yar

Sana kıyamam 

Sen çek tetiği 

Ben kazarım mezarımı

Kurtaramadım, 

Düşlerimi,

Yalan sarılmalarımı

Unuttum saymayı

Sensiz kaç gece

Sabahladığımı yar

Sen çek tetiği

Ben kazarım mezarımı

Ne cennette gözüm 

Nede cehennemden korkum

Kapat bu hesabı yar

Kendini de beni de kurtar

Sen çek tetiği 

Ben kazarım mezarımı

Arama yar

Sakın arama

Kapadım telefonumu da…

Ah birde

Kalbimi kapayabilsem  sana

Olmuyor yar olmuyor

Çek tetiği kurbanın olam

Ben kazarım mezarımı', 'Ölmekse ölmek  Ne canı düşünürüm  Nede kıyımı Sana kıyamam yar Sana kıyamam  Sen çek tetiği  Ben kazarım mezarımı Kurtaramadım,  Düşlerimi, ...', ARRAY['Türk Edebiyatı','Şiir','Ferit Gürsoy']::text[], 8.5, '{"poet":"Ferit Gürsoy","poet_slug":"ferit-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ben-kazarim-mezarimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorsun Kadın', 'seviyorsun-kadin-resul-ustun-u1is8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey ıslak gözlü,

özgür bakışlı kadın! 

Yüreğin kor ateş,

yüreğin bir yanardağ, biliyorum.

Dayan,

ve bastır yüreğindeki iç isyanı.

Durgunsun,

suskunsun,

en kötüsü utandırıyorlar seni

utanıyorsun kadın.

ama gizlisi zordur,

zordur saklısı sevdanın.

Ey sevda yelkenlisinin 

acemi kaptanı! 

Kapılmış sürükleniyorsun.

Azgın dalgalarda boğulmak üzeresin

ve uçsuz bucaksız bilinmezlere

sürüklenip gidiyorsun.

Gizlesen de,

sevdadır bunun adı.

Belli ki yangınlardasın,

kor ateşlerin ortasındasın belli ki...

ve acımasız törelerin,

yargısız infazındasın kadın.

dayan,

ve bastır yüreğindeki iç isyanı.

Bastır ki,

kan revan olmasın umudun.

Feodal yargılar adına,

yüreklerin kelepçelendiği bu evrende,

bil ki tutsaklığı yaşıyorsun.

Saklısı olmaz ki sevdanın,

gizlesen de seviyorsun be kadın!', 'Ey ıslak gözlü, özgür bakışlı kadın!  Yüreğin kor ateş, yüreğin bir yanardağ, biliyorum. Dayan, ve bastır yüreğindeki iç isyanı. Durgunsun, ...', ARRAY['Türk Edebiyatı','Şiir','Resul Üstün']::text[], 8.5, '{"poet":"Resul Üstün","poet_slug":"resul-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/seviyorsun-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenmez Melâl', 'tukenmez-mel-l-arafat-arik-3yok6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kere aştı mı gözyaşı, bendi,

Ağustos ayında yağan kar olur.

Koparsa derinden kalbin kemendi,

Taşıyana külfet, gönle ar olur

Görülmez, dünyada yüreğin fendi,

Kendisi söyledi, dinledi kendi,

Olmasa dünyada eşi menendi,

Ne kimseye maşuk ne de yâr olur

Gökleri indirsen almaz, ganiye,

Bir lokma bir kelam yeter faniye,

Gönül otağında birkaç saniye,

Zamanın durduğu yüzyıllar olur. 

Bir buğulu hasret, ömrün akışı,

Tükenmez melâldir şimdi bakışı,

İçine işleyen hüzün nakışı,

Kendinden geriye bergüzâr olur.

Yürekte; zemheri, yakan nâr olur,

Belki de hayatta bir o kâr olur,

Kelimeler susar bi-karar olur,

Olursa bir düşte bahtiyar olur.

                                      28-Ekim-2005', 'Bir kere aştı mı gözyaşı, bendi, Ağustos ayında yağan kar olur. Koparsa derinden kalbin kemendi, Taşıyana külfet, gönle ar olur Görülmez, dü...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tukenmez-melal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlelebed CUMHURİYET!', 'i-lelebed-cumhuri-yet-veysel-alkan-ksc7j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ülke bizim,biziz devlet.

İlelebed CUMHURİYET! 

Hak,eşitlik ve adalet,

İlelebed CUMHURİYET! 

Bu topraklar sahipsiz mi? 

Sahipleri biziz elbet.

Egemenlik verilir mi? 

İlelebed CUMHURİYET! 

Kan veririz,can veririz,

VATAN için, bizde gayret.

Kıymetini hep biliriz,

İlelebed CUMHURİYET! 

TÜRKİYE''nin her evladı,

Hasan,Ali ya da Mehmet...

Tek yürektir,birdir andı,

İlelebed CUMHURİYET! 

Cumhuriyetin 82. yılı,TÜRK MİLLETİ''ne kutlu olsun.', 'Ülke bizim,biziz devlet. İlelebed CUMHURİYET!  Hak,eşitlik ve adalet, İlelebed CUMHURİYET!  Bu topraklar sahipsiz mi?  Sahipleri biziz elbet...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ilelebed-cumhuriyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur gözlüm', 'yagmur-gozlum-unal-ulas-ydth9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duyguları yüzüne yansıyan kelebeğim benim

Tertemiz bakışlarıyla aşk kokan bebeğim

Sıcacık yüreğiyle 

Saflığın ve temizliğin timsali

Kardelenim benim

Yağmur gökyüzü bulutlanınca yağar

Sert olur rüzgarları üşütür adamı

Sen yağmur gözlüm sen

Akıtırken o güzel gözlerinden güzelim yaşlarını

Ben hiç üşümeden 

Sadece seninle ıslanmak istiyorum

Ve seni kollarıma alıp sımsıkı sarıp

Sonsuza dek koklamak istiyorum', 'Duyguları yüzüne yansıyan kelebeğim benim Tertemiz bakışlarıyla aşk kokan bebeğim Sıcacık yüreğiyle  Saflığın ve temizliğin timsali Kardelen...', ARRAY['Türk Edebiyatı','Şiir','Ünal Ulaş']::text[], 8.5, '{"poet":"Ünal Ulaş","poet_slug":"unal-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yagmur-gozlum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen sakın üzülme', 'sen-sakin-uzulme-unal-ulas-8sghu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen bana sakın üzülme sevgilim

Aldırma hüzünlü bakışlarıma

Ben ittire ittire götürüyorum hayatı

Bilinmezliği bile

Sen üzülme suskunum diye

Yırtıklarını dikiyorum gecenin

Ayla yıldızı geceyle gündüzü 

Çirkinle güzeli birleştiriyorum

Yaşam ile ölüm arasındaki maratonu koşuyorum

Son finalini koşuyorum nefes nefese

Ara sıra ağlıyorum diye üzülme

Ben sevgimizin ağırlığını taşıyorum

Kızma bana gecenin karanlığına takılıp kaldım diye

Gelmek istersen tıklat gönül kapımı

Seni bekliyor olacak yüreğim

Mutluluk geç kalsa bile', 'Sen bana sakın üzülme sevgilim Aldırma hüzünlü bakışlarıma Ben ittire ittire götürüyorum hayatı Bilinmezliği bile Sen üzülme suskunum diye Y...', ARRAY['Türk Edebiyatı','Şiir','Ünal Ulaş']::text[], 8.5, '{"poet":"Ünal Ulaş","poet_slug":"unal-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-sakin-uzulme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşlarının Tuzu', 'gozyaslarinin-tuzu-selma-erdeviren-hueer', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözyaşları tuzludur

Tuz gölleri kadar

Ve hiç kimse bilemez gözyaşlarının tuzunu

Benim bildiğim kadar.

(1979)', 'Gözyaşları tuzludur Tuz gölleri kadar Ve hiç kimse bilemez gözyaşlarının tuzunu Benim bildiğim kadar. (1979)...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gozyaslarinin-tuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutların Kıskançlığı', 'bulutlarin-kiskancligi-selma-erdeviren-kh3pl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bulutlar kıskandı gözlerimi

Gözyaşlarım yağmurlarından fazla diye.

(1997)', 'Bulutlar kıskandı gözlerimi Gözyaşlarım yağmurlarından fazla diye. (1997)...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bulutlarin-kiskancligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her akşam', 'her-aksam-unal-ulas-h5ore', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her akşam bir şiir kanıyor dudaklarımda

Serçeler dilsiz ben biçare

El ayak çekilirken caddelerden

Benim yıldızlara ağladığımı kimse bilmiyor

Yüreğimde her gece depremler oluyor

Ve bu yaralı yürek yıkılışına ağlıyor

Ey yavru bir ceylan gibi 

Düşlerimin arasından uçup giden uçarı kız

Gel tut ellerimden tut çıkar beni

Yalnızlığın mabedinden

Yıldızları sönmüş bir gecenin tam ortasında

Yapayalnız bırakma beni

Her mısrada çığlık çığlık yüreğim

Gel

Bütün sokaklarına kar yağıyor ömrümün', 'Her akşam bir şiir kanıyor dudaklarımda Serçeler dilsiz ben biçare El ayak çekilirken caddelerden Benim yıldızlara ağladığımı kimse bilmiyor...', ARRAY['Türk Edebiyatı','Şiir','Ünal Ulaş']::text[], 8.5, '{"poet":"Ünal Ulaş","poet_slug":"unal-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/her-aksam-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Büyüsü', 'askin-buyusu-selma-erdeviren-uodoq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kelebek olup konmuşken üstümüze

Uçup gitti aşkın büyüsü.

Titreseydik üstüne,

Saklasaydık avuçlarımızda,

Şimdi böyle ayrı ayrı yerlerde

Gizli gizli yaş dökmezdik.

Kaç yılda bir gelir,

Kaç kişiyi bulur sevdanın böylesi? 

Başarabilirsek eğer

Unutabilmek en iyisi.

Bir masal gibi anlatırız,

Başka çaremiz de yok zaten.

Kelebek olup üstümüze konmuşken

Uçtu gitti aşkın büyüsü.

(1997)', 'Kelebek olup konmuşken üstümüze Uçup gitti aşkın büyüsü. Titreseydik üstüne, Saklasaydık avuçlarımızda, Şimdi böyle ayrı ayrı yerlerde Gizli...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/askin-buyusu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Geliyorsun Aklıma', 'sen-geliyorsun-aklima-selma-erdeviren-0ltr1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir şiir okusam,

Ne zaman bir şarkı söylesem,

Ne zaman güzel şeyler dilesem,

Sen geliyorsun aklıma.

Adımlarken kaldırımları,

Vızıldarken havada arı,

Yaz kovalarken baharı

Sen geliyorsun aklıma.

Bir güvercin nazında,

Bir ozanın sazında,

Gülen çocuk yüzünde

Sen geliyorsun aklıma.

Titrerken bazen sesim,

Tutuluverse birden nefesim,

Eylül, ekim, kasım...

Sen geliyorsun aklıma.

Dört mevsim yeşildir sevdanın dalı,

Sevdalı her zaman cesur olmalı.

Omuzlarımda ölümün buz gibi eli,

Sen geliyorsun aklıma.

(1981)', 'Ne zaman bir şiir okusam, Ne zaman bir şarkı söylesem, Ne zaman güzel şeyler dilesem, Sen geliyorsun aklıma. Adımlarken kaldırımları, Vızıld...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-geliyorsun-aklima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Söylüyorum', 'yalan-soyluyorum-selma-erdeviren-vw6nd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ay doğuyor batıyor,

Seni soruyor bana.

Her gece bir yalan buluyorum; 

Eğil de bak diyorum bulutların arasından,

Dudaklarında aşkımızın şarkıları,

Gözleri yaşlı

Arşınlıyor yolları.

Ay doğuyor batıyor,

Seni soruyor bana.

Gir diyorum, rüyasına bir gece gir; 

Gör bakalım, kimi saklıyor sabah kadar.

Böyle büyük aşk mı var? 

İnanıyor bana; nasılsa aramız uzak,

Gizliyorum gözümdeki yaşları.

Ay doğuyor batıyor,

Seni soruyor bana.

Her gece ölüyorum.

Unutmadı diyorum,

Unutamaz diyorum.

Yalan söylüyorum.

(Nisan-2005)', 'Ay doğuyor batıyor, Seni soruyor bana. Her gece bir yalan buluyorum;  Eğil de bak diyorum bulutların arasından, Dudaklarında aşkımızın şarkı...', ARRAY['Türk Edebiyatı','Şiir','Selma Erdeviren']::text[], 8.5, '{"poet":"Selma Erdeviren","poet_slug":"selma-erdeviren","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalan-soyluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansızlığın Şiiri', 'i-mkansizligin-siiri-adem-tok-a9n82', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir şiir yazsam diyorum 

filistin gibi 

attığım taş olsa

filistin gibi

yaşamak şakayada gelmez

çocuk yaşta ölmeyede

ama hayat

filistin gibi

düşlerim filistin

umutlarım kavgamda...

ellerimin düştüğü

parmaklıklar soğuk ve tenha

pencerem melekleri bekleten

zenci nabo gibi

filistin

bir sevgilim var

filistine benzetiyorum

öyle dirençli

ve esmer

öyle imkansiz

bir şiir yazsam diyorum

filistin gibi

attığım taş olsa

filistin gibi

                        (04.08.04) 

                        f tipi hapishane EDİRNE', 'bir şiir yazsam diyorum  filistin gibi  attığım taş olsa filistin gibi yaşamak şakayada gelmez çocuk yaşta ölmeyede ama hayat filistin gibi ...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/imkansizligin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİL (meyen) Aşkı', 'bi-l-meyen-aski-ahmet-kovanci-qormz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karardı...

gece 

günaha

utandı...

yıldızlar

kapattı..

gözlerini

üşüdü..

yası tutulmayan

aşk

sarıldı..

umutlara

kanıldı..

sözlere

gelecek

sanıldı..

gelmeyecek

yanıldı...

gidenlerle

anıldı...

bilmeyenlerce

yazıldı...

aşk....', 'Karardı... gece  günaha utandı... yıldızlar kapattı.. gözlerini üşüdü.. yası tutulmayan aşk sarıldı.. umutlara kanıldı.. sözlere gelecek san...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kovancı']::text[], 8.5, '{"poet":"Ahmet Kovancı","poet_slug":"ahmet-kovanci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bil-meyen-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Şiiri', 'bir-ask-siiri-adem-tok-yc523', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kar altında saklanan kardelen çiçeğiydin

beyaza bürünmüş bir gecenin sabahında

ellerim avuçlarının arasında

                        bakarken gözlerine

duruluyorum sevgilim

gülüşün:kavgamın alevli coşkusu

hüznün:bir serçenin ürperişi

gözyaşın:hayat pınarım

duruluyorum sevgilim

vücudundan akıp 

vücudumu kucaklayan terinde

sabahı olmayan bir gecenin seyrinde

seviyorum dediğin her kelimede

duruluyorum sevgilim

                                       (ağustos 2001) 

                                       f tipi hapishane TEKİRDAĞ', 'kar altında saklanan kardelen çiçeğiydin beyaza bürünmüş bir gecenin sabahında ellerim avuçlarının arasında                         bakarken...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-ask-siiri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delî Osman Destanı', 'del-osman-destani-alper-kuruk-2d3z2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Onaltıncı asır sonlarında 

Bir İran seferinde

Tebriz''i almıştı 

Özdemiroğlu Osman.

Ama ne çare ki 

Ecel vermedi aman.

Hamza Mirza emrindeki

Bir İran ordusu

Kuşattı Tebriz''i.

Kaleyi savunan

Cafer Paşa adında

Kahraman bir kumandan.

Kale duvarlarını uçurmak için

İran''lılar koskocaman

Bir lağım kazmışlardı.

Kahraman Delî Osman

Bu lağımı keşfetti.

Bir tünel açıp

Bin fedaîsi ile

Girdi lağıma oradan.

Yemek zamanı olduğundan

İşi terketmişti lağımcılar.

Geçerek yer altından

Osman''la bin kahraman

Geldiler ansızın

Serdarın otağına.

Hamza Mirza

Soluna ve sağına

Oturttuğu sakiler elinden

İçip içip eğlenirken

Düşüvermişti birden

Hasmının ağına.

Deli Osman hemen:

''Aşkolsun güzel Şah...''

Diye nâra atarak

Yalınkılıç içeri daldı.

Serdar ise yalın ayak

Zor kurtardı canını

Ve arkasından bin gazi

Paylaştılar o anda

Çadırdaki malını.

Delî Osman esir aldı

Bir gözde saki,

Bir de çengi.

Tekrar kaleye döndü

Aynı lağımdan.

Kazanıldı böylece işte

Rahatlıkla İran cengi...', 'Onaltıncı asır sonlarında  Bir İran seferinde Tebriz''i almıştı  Özdemiroğlu Osman. Ama ne çare ki  Ecel vermedi aman. Hamza Mirza emrindeki ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/deli-osman-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler (100) ''Sabah Yeli serindir...''', 'maniler-100-sabah-yeli-serindir-abdullah-atay-a438j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönül bir değirmendir.

Suyu,gözden göze akan bakış

Buğdayı tatlı dil

Unu ise sevgidir...

Değirmenin taşları

Su olunca dönüyor

Yüreğim ataşları

Yar gelince sönüyor...

Değirmenin arkı yok

Hem arkı hem çarkı yok

Şu hercai gönlümün

Kelebekten farkı yok...

Yanar yüreğim yanar

Gönül yarini anar

O vefasız yüzünden

Göz yaşım oldu pınar...

Yar elinden tutulur

Gönüller avutulur

Yar yanıma gelince

Nutkum,dilim tutulur...

Yürek sevda harmanı

Yardır gönlün dermanı

Kanayan şu yaramı

Yar bekliyom sarmanı...

Dünya yarsızmış yalan

Yürek viran, hem talan

İki damla göz yaşı

Bu aşktan geri kalan...

Şu pınarın başına

Türlü türlü kuş konar

Sevda geldi başıma

Gönül ateşte yanar...

Sabah yeli serindir

Açma yaram derindir

Gönülde gizli sevdam

Yar senin eserindir...', 'Gönül bir değirmendir. Suyu,gözden göze akan bakış Buğdayı tatlı dil Unu ise sevgidir... Değirmenin taşları Su olunca dönüyor Yüreğim ataşla...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/maniler-100-sabah-yeli-serindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşa Cumhuriyet', 'yasa-cumhuriyet-munevver-duver-ar50b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bunca şehit kanları döküldükçe 

Analarımız bacılarımız hür yaşadıkça 

O şanlı bayrağımız dalgalandıça. 

Yaşa Cumhuriyet, yaşa Atatürk 

Hep böyle kalacak dünya durdukça,

Herkes hür yaşayacak, güzel oldukça,

Göklerde al bayrağım dalgalandıkça

Yaşa Cumhuriyet, yaşa Atatürk 

27-10-2005-saat:11.52

Cuma

Güzelyalı_ADANA', 'Bunca şehit kanları döküldükçe  Analarımız bacılarımız hür yaşadıkça  O şanlı bayrağımız dalgalandıça.  Yaşa Cumhuriyet, yaşa Atatürk  Hep b...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasa-cumhuriyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçı ve Ben ve Sen', 'balikci-ve-ben-ve-sen-unal-ulas-y5d4z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni terkettiğin günün gecesi,

Kokunu dertlerini pişmanlıklarımı avuçladım.

Bir sigara daha yaktım,

Seni dumanımla çektim içime 

Ve evden çıktım.

Şarabımın son yudumu şişede,

Senin son yudumun bende.

Deniz kapkara ben bembeyaz,

Bir silüet denizin ortasında.

Eski bir sandal ve bir balıkçı.

Hey dayı şarabın var mı?

Şarap kalmadı evlat iksirim var.

Ne iksiri be dayı ben sarhoşum.

İyi ya işte evlat ben mutluluk içiyorum,

İstersen al bir yudum istersen.

Ver be dayı belki geç olmamıştır,

Belki döndüğümde giden geri gelmiştir.

Gelmiştir evlat gelmiştir,

Eğer giderken bırakmışsa biraz gönül kırıntısı,

Kısık gözlerinde yaşlarla gitmişse

Gelmiştir…

Eğer avuçlarında senin bıraktığın pişmanlık varsa,

Bebek yüzü kalmışsa eğer,

Gelmiştir evlat gelmiştir.

Al kalan son yudum şarabını,

Al şu son yudum iksiri,

Eyvallah dayı oltan sevgi tutsun, yüreğin beni.

Terkettiğin günün gecesi,

Ben kahırlarımı, sen sevgini avuçladın.', 'Beni terkettiğin günün gecesi, Kokunu dertlerini pişmanlıklarımı avuçladım. Bir sigara daha yaktım, Seni dumanımla çektim içime  Ve evden çı...', ARRAY['Türk Edebiyatı','Şiir','Ünal Ulaş']::text[], 8.5, '{"poet":"Ünal Ulaş","poet_slug":"unal-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/balikci-ve-ben-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yayabaşıoğlu Şeyh Hızır Destanı', 'yayabasioglu-seyh-hizir-destani-alper-kuruk-w74dz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeniçeri İlyas''ın

Babasıydı Abdülnevvâb.

İlyas''a birgün

Oğlan çocuk verdi Râb.

Bütün güzelliğiyle

Kusursuz vermişti veren,

Güzelliği düştü dile

''Yusuf-u Sâni'' derdi gören.

Olmuştu yeniçeri

On dokuz yaşındayken.

Câmi dersleri

Askerlik hevesine galebe çaldı

Ve bu güzel askeri

Duvarları arasına aldı.

Kaydını sildirtti ocaktan

Yayabaşıoğlu Hızır

Dem vurur oldu Hâk''tan...

Oldu bir Halvetî Şeyhi

Toplandı müridler

Etrafında birer birer.

Yaşlanmıştı epeyce...

Ama taş çıkartırdı

Karşısındaki çok gence...

Üçüncü Mehmed''le beraber

Macaristan seferinde

Oldu bir ihtiyar asker.

Alındı Eğri Kalesi,

Bekliyor şimdi de onu

Haçova Meydan muharebesi.

Harbin ilk safhasında

Bozguna uğrayan askerin

Olması için metin

Şeyh verdi nasihat,eyledi vaaz

Asker düzeldi biraz.

Dedi bir müridine:

''Oğul, bu gece düşümde

Öğrendi zaferi

Benim şehitlik kanımla

Türk askerleri...''

Sonra ihtiyar kahraman

Sıyrılıp asker arasından

Ona olmak içn örnek

Elinde yalın kılınç

Atıldı ön saflara.

Artık bitmişti cenk

Kazanıldı zafer.

Savaş alanını arayan müridler

Buldular Şeyh Hızır''ı

Kan ve çamura gömülmüş

Paramparça bir hâlde.

Sol eli yumulmuş

Kalmış avucu içinde

Bir tutam düşman saçı

Ve kafa derisi de...

Zafer  onlarındı ama

Bu hüzünlümanzara

Müridlere geldi çok acı...

Sahip oldu üç yere

Bu kahraman ihtiyar; 

Biri Allah katında,

Biri tarih içinde

Ve her müridin kalbinde

Birer tane köşkü var...', 'Yeniçeri İlyas''ın Babasıydı Abdülnevvâb. İlyas''a birgün Oğlan çocuk verdi Râb. Bütün güzelliğiyle Kusursuz vermişti veren, Güzelliği düştü d...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/yayabasioglu-seyh-hizir-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buraya Kadar', 'buraya-kadar-aynur-uluc-nqtu2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Buraya kadarmış çocuk

Ninnili masal

Telgraf telinde giz

Ölüsü bebeğini doğuran sis

Yarına çizili iz

Buraya kadar

Ejderhalarla savaşmış prenses

Kurtarmak için aşkını

Prens prensesin bencilliğiyle

Anka kuşundan almış bir tüy

Bal çorbasından tuzlu bir kaşık

Yüzüne gözüne karalar çalmış

Bir gün susmuş tüm sözcükler

Sesler, türküler

Bu masal buraya kadarmış işte

Şimdi uyuma değil

Uyanma vakti çocuk…

Aynur Uluç

(14-07-2005)   

Bu şiiri sevgili Atakan''a ithaf ediyorum, yürek dolusu sevgilerimle..

www.atakanca.hikayesi.com

www.atakanname.com', 'Buraya kadarmış çocuk Ninnili masal Telgraf telinde giz Ölüsü bebeğini doğuran sis Yarına çizili iz Buraya kadar Ejderhalarla savaşmış prens...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/buraya-kadar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadıköy, Eminönü', 'kadikoy-eminonu-ahmet-zeki-karali-rabcl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşam büyük bir olay

güneşin doğuşu

işe giden insanlar

duraklar

dolu insanlar

iskeleden ayrılan bir gemi

Eminönü, Kadıköy

Kadıköy, Eminönü

Kent var Marlboro var abi

abi bir beş lira versene abi

karnım da çok aç hani

Piyade Okulu Tuzla City

yeni bir gün başlıyor randevuevleri! 

sigara, tekila, müzik

sevişmek isteyen bir vücut

yazan bir tek el

düşünen bir beyin

gece yağmurda yürümeyi özleyen bir insan

işte ben ve tarih 17 Mart 1984', 'Yaşam büyük bir olay güneşin doğuşu işe giden insanlar duraklar dolu insanlar iskeleden ayrılan bir gemi Eminönü, Kadıköy Kadıköy, Eminönü K...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zeki Karali']::text[], 8.5, '{"poet":"Ahmet Zeki Karali","poet_slug":"ahmet-zeki-karali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kadikoy-eminonu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığın Yoksulluğu', 'karanligin-yoksullugu-ahmet-zeki-karali-wvykx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birileri ya da insanların çoğunluğu

paraya yaşamı,

maddiyata benliği

Satıyorlar...

Hem de beş parasız! 

yine kimileri

satmayı deneseler de

başaramıyorlar bunu

ve bir kaosa sürükleniyorlar

Sonunda

onlar da böylece

batıp gidiyorlar

Nereye mi? 

Karanlığın Yoksulluğuna! ..

(20 Mayıs....)', 'Birileri ya da insanların çoğunluğu paraya yaşamı, maddiyata benliği Satıyorlar... Hem de beş parasız!  yine kimileri satmayı deneseler de b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zeki Karali']::text[], 8.5, '{"poet":"Ahmet Zeki Karali","poet_slug":"ahmet-zeki-karali","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karanligin-yoksullugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
