INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '&&&& Masum Değiliz Hiçbirimiz &&&&', 'masum-degiliz-hicbirimiz-ayse-kayacan-f1jfv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sudan çıkmış balık gibiyim

şehirde ben.

kalabalıklar boğar

anlayışsızlıklar hakeza..

sevgi nerde kaldı, 

nerede yardımlaşma? 

at bre debreli Hasan, atınca

mangalda kül bırakmayız.

tirtir titreyen çıplak ayaklı çocuğa

yan gözle bakmayız.

hani dinini emri? 

asil geleneğin vardı hani? 

genlerine işleyen! 

bitip tükenmeyen istekler

küçük insancıklar dünyası

hep birbirini dişleyen

birbirini hazır yemeye...

.......................................

hiç birimiz masum değiliz!', 'sudan çıkmış balık gibiyim şehirde ben. kalabalıklar boğar anlayışsızlıklar hakeza.. sevgi nerde kaldı,  nerede yardımlaşma?  at bre debreli...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Kayacan']::text[], 8.5, '{"poet":"Ayşe Kayacan","poet_slug":"ayse-kayacan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/masum-degiliz-hicbirimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elinin Kiri', 'elinin-kiri-ahmet-turan-altunsu-lxxxj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bocalayacak ne var be güzelim? 

zaten elinin kiri! .. 

çırpıver ellerini, 

ardına bakmadan yürü! .. 

sürüsen de ayaklarını giderken; 

inan ki  kimsecikler çağırmaz geri... 

an` ın ne önemi var; bırak anılarda boğulsun: 

kim unutabilir senin gibi bir dilberi? .. 

varsın olsun; 

sen, söylen dur güzelim; 

`beş para etmezmiş ciğeri! ..` 

elinin kiri demiştim hani… 

yüreğindeki kir mi anladın? 

ah be güzelim: 

hani nerdeyse diyeceğim ki 

bende Türkçe nizani! 

vallahi yanlış anladın! 

çekme öyle lâstik gibi geriye geriye; 

halâ çözemedin mi 

__ruhuna çöreklenmiş

____şu kokuşmuş düzeni? 

“bir ben vardır bende benden içerü” 

ufkunu geniş tut da 

biraz bak ileriye! .. 

ah! .. ne kadar kolay yazmak 

sevgiliye nağmeler! 

hele de benim için 

en sevgiliye alay yazmak! ? . 

ben hocamı severim! 

ne demişti üç kez, gülerek: 

susmak gerek, 

susmak gerek, 

susmak gerek! .. 

sus… 

-28.07.2005 / Ankara', 'bocalayacak ne var be güzelim?  zaten elinin kiri! ..  çırpıver ellerini,  ardına bakmadan yürü! ..  sürüsen de ayaklarını giderken;  inan k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/elinin-kiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zıvanadan Çıkıyorum', 'zivanadan-cikiyorum-sahin-yilmaz-fxihm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlat kardeş, senin bayramın nasıl? 

Ben tersine akıyorum bayramda.

Balımız kokuyor, sulandı asil,

Boşa kürek çekiyorum bayramda.

Vaat çok, para yok alın terine,

Mutlu olan var mı, sorun birine.

Dostların elini sıkmak yerine,

Dişlerimi sıkıyorum bayramda.

Orucu fakirin sırtına verdik,

Bayram meydanında zengini gördük.

Fitreyi, zekatı uzağa sürdük,

Eğlenceye bakıyorum bayramda.

Akıl tora düştü medya avında,

Aile esir modernizm devinde.

Torun yurtta, dede huzurevinde,

Duvarları yıkıyorum bayramda.

Kravatlı beyler almasın diye,

Gölgeyi sakladık, çalmasın diye.

Bayram, şeker ile kalmasın diye,

Şekerleri döküyorum bayramda.

Alçak basınç baskı yaptı batıdan,

Kasırgalar eve girdi çatıdan,

Yemek  yaptım zambak, kasımpatıdan,

Yiye yiye bıkıyorum bayramda.

Başımıza yerli malı sam geldi,

Bazen uluk  geldi, bazen ham geldi.

Dert çoğaldı, ümitlere zam geldi,

Zıvanadan çıkıyorum bayramda.

Kalelerim teker teker düşüyor,

Milletçe helvamız pişti pişiyor.

Kardeşlerim çadırlarda üşüyor,

Kainatı yakıyorum bayramda.', 'Anlat kardeş, senin bayramın nasıl?  Ben tersine akıyorum bayramda. Balımız kokuyor, sulandı asil, Boşa kürek çekiyorum bayramda. Vaat çok, ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/zivanadan-cikiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansızdı', 'zamansizdi-adem-tok-8gs5g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zamansızdı herşey

tomurcukların patlaması

günün ışıması

gidişin

umulmadık dönüşün

dağların doruğundan tel örgülerin ardındaki

suretime gülüşün

zamansızdı

ellerimdeki kelepçeleri görüp

ürperişin

gölgenle avludaki adımlarıma

ortak oluşun

uyanırken şafağın seyrinde

içime doluşun

zamansızdı

zamansızdı vedan

ve

o 

güzel

merhaban

                               (mayıs 2002) 

                               f tipi hapishane TEKİRDAĞ', 'zamansızdı herşey tomurcukların patlaması günün ışıması gidişin umulmadık dönüşün dağların doruğundan tel örgülerin ardındaki suretime gülüş...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zamansizdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamani Börü Beg-Şiirhan Yavuz Bayram Atışması', 'karamani-boru-beg-siirhan-yavuz-bayram-atismasi-yavuz-bayram-caliskan-dv15o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dile gelenler dilden değil, hoşluğu candandır,

Sana dostluğum damarımdaki kandandır,

Nefes aldığım zaman coşkuyla yaşanandır.

Zevk insanın demindedir, 

Demleyene bak, para pul kıymet akar gider,

İnsana insan lazım, ömre takar gider.

Bizde gül biter, bizde ot biter, bizde can biter, 

Ömür de biter amma dostluk bitmez dost ölünür.

Sözlerin güzel sözlerin hoş,

Bu hoşluğu bize de aktar,

Bir selamla binlerce coş,

Bu muhabbeti satamaz hiç bir aktar.

Demi söyler, çay içeriz demi söyler,

İnsan kemalet ilmine olmuşsa mahzar,

Dost dedikçe o demi söyler.

Bir ulu dağ gibisin yücelerden yücesin,

Dinmesin dünya durdukça sesin,

    Demlenen dostluklarla bir cihan inlesin,

Kaderim sazım sende,

Sen çal irfan dinlesin.

   Saz çalar, çalan ben değilem,

   Söz söyler, yalan ben değilem,

   Gönül eyler yalan ben değilem,

   Marifet bende değil, sendedir ey ulu insan

Arı vızıldar bal yapar, 

İnsan durulur ar yapar,

Alır satar kar yapar, 

Ekilmemiş fidanlardan gül yapar eren bilir.

Kimler geldi geçti kimler etmedi ah,

Posoflu Zülali, Çıldırlı Şenlik, Erzurumlu Emrah

Zannetme hep karanlık hep matem,

Bak tan yeri ağarmada güneş doğuyor oluyor sabah.

   Bir nefes verir hak

   Bir nefes alır hak,

   İsmin dünyaya kalırsa ne mutlu ak

   Gelse de saçlara, en iyisi güneşle gelen ak

Bir nefes verir hak, bir nefes alır hak,

     İsmin dünyaya kalırsa ne mutlu ak,

Gelse de saçlara, 

En iyisi güneşle gelen ak

Söylenecek sözü bitirdin

Baharsın güzü bitirdin

İnsan yaşayınca iz bırakmalı

Maarifet sanatında bizi bitirdin.

Söz bitseydi dil olmazdı

Güz bitseydi bahar kalmazdı

İnsan insanca yaşamazsa iz kalmazdı,

Yavuz Bayram, Karatay Ustanın yanında öz kalmazdı,

Gölge değil güneş olduğun zaman sönmez,

Bu güneş yanar bilirim. 

Sazımın telleri yok,

Yurdumun elleri yok,

Yağan yağmurum amma,

Çağlayan selle yok.

Sazın var telin var

Yurdun var yerin var

Yağmursun,

Hem de gülün var, gülenin var.', 'Dile gelenler dilden değil, hoşluğu candandır, Sana dostluğum damarımdaki kandandır, Nefes aldığım zaman coşkuyla yaşanandır. Zevk insanın d...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/karamani-boru-beg-siirhan-yavuz-bayram-atismasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin', 'gelin-feyza-nur-cengiz-laon8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mutluluk elimde sihirli bi değnekti 

Onu kullanacak büyülü sözcükleri bulamadım 

Hayatın acı limiti sınırsız 

Mutlulukları ise sınrlı 

Bi insanın çekmesi gereken acıyı çektiğimi düşünüyorum

Şimdi dünyaya yeni gelecek çocuklara 

Gelmeyin diyeceğim ama

Az da olsa mutluluklar var 

İşlevi olamayan bi eşya gibi olsamda 

İşe yaradığım anlar 

Bedelini ağır ödediğim aşklar 

Bi bakışına ömür verebileceğim adamlar oldu

Büyük zaferlerim olmadı belki

Çünkü büyük hırslarım yoktu

Buyüzden çabuk yenildim hemen pes ettim belki.

Kimi zaman........

Kurumuş çiçekler verildi ellerime 

Güzel sözler söylendi gözlerime 

Büyük bi aşkın nefesi üfledi ruhuma 

Sevdanın karanlıkları düştü aydınlıklarıma 

Mutluluk pahalı bi oyuncak 

İlla dünyaya gelip oynamak istiyorsanız 

Buyrun gelin ama acı çekmeye hazır', 'Mutluluk elimde sihirli bi değnekti  Onu kullanacak büyülü sözcükleri bulamadım  Hayatın acı limiti sınırsız  Mutlulukları ise sınrlı  Bi in...', ARRAY['Türk Edebiyatı','Şiir','Feyza Nur Cengiz']::text[], 8.5, '{"poet":"Feyza Nur Cengiz","poet_slug":"feyza-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gelin-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Yeter Bana', 'ay-yeter-bana-yavuz-bayram-caliskan-snarq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sahilde yürü kaldırımlar seni dinlesin

Bir rüzgar uğuldasın yüreklerde bir can inlesin 

Kaldırma başını güneş bat ve git yarına dik ve taze gel,

Seninleyim sensiz gecelerde, bir de  ay yeter bana.

Sebepsiz fırtınalara, hasret ayazlarını estirme,

Gözlerin sende kalsın, bana kestirme,

Yaralı yürek aşkını bıçak gibi bastırma,

Denizleri içerim, yarama tuz olsun diye.', 'Sahilde yürü kaldırımlar seni dinlesin Bir rüzgar uğuldasın yüreklerde bir can inlesin  Kaldırma başını güneş bat ve git yarına dik ve taze ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ay-yeter-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağırdı Gölgem', 'sagirdi-golgem-birsen-ates-ajoyt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gizlenmek istemeyen

sırlı aynalarda suretim

anlamsız gülüş yapıştırıp yüzüme

geliyordum her seferinde düşüne

usumda dağılmış suretin

toplanmaktan yorgun

üzgünüm

sende öldüğüm için

sessizliğin ruhumda yankılanır

umarsız esrikliğinde gidip gelen hayalin

aynada gördüğün bendim oysa

seni anlayacak aksin olmayacak 

ve acı içinde kıvranırken gece

henüz uzatmamışken elleri

söylememişken  sözleri

sen giriyorsun düşüme

ağlıyorum

çekilip gitti ağır ağır

gölgem

artık yalnızım

biliyor musun

güneş artık yok

grileşen bir deniz var önümde', 'gizlenmek istemeyen sırlı aynalarda suretim anlamsız gülüş yapıştırıp yüzüme geliyordum her seferinde düşüne usumda dağılmış suretin toplanm...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sagirdi-golgem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '&&&& Gözler Kalbin aynasıdır &&&&&', 'gozler-kalbin-aynasidir-ayse-kayacan-9jlum', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'beni sevmediğini

bir de gözlerime bakarak söylesene! ! ! 

gözler kalbin aynasıdır.

bunu sen de biliyorsun! ! ! 

.............................................

niye gözlerini kaçırıyorsun ki? ? ? ? ?', 'beni sevmediğini bir de gözlerime bakarak söylesene! ! !  gözler kalbin aynasıdır. bunu sen de biliyorsun! ! !  ...............................', ARRAY['Türk Edebiyatı','Şiir','Ayşe Kayacan']::text[], 8.5, '{"poet":"Ayşe Kayacan","poet_slug":"ayse-kayacan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gozler-kalbin-aynasidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgini Silemedim,Slinmiyor Bebeğim.', 'sevgini-silemedim-slinmiyor-bebegim-gul-gultekin-lti7b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgini silemedim silinmiyor bebeğim

Arkadaş kalalım,dost kalalım diyorsun,

Yüreğimin derinliklerine öyle işlemiş ki gözlerin

Silinmiyor silemedim bebeğim.



Hasretin bir kor olmuş yüreğimde

Hayallerin hep gözlerimin önünde

Yapa yalnız kalmışız bak o sahilde,

Sevgini silemedim silinmiyor bebeğim.



Almayacak mısın beni fırtınalar esen gönlüne? 

Göğsümdeki kör düğümü çözmeyecek misin artık? 

Aşkını itiraf etmek için kaç yıl daha geçecek ömründen

Dönmeyecek misin seni ölümüne bekleyen bu yüreğe? 



Sorular içinde geçse de bu ömür, sevmekten vazgeçmeyecek

Sen mutlu ol,sevdanın kollarında buna da razı bu gönül

Yeter ki  boş bırakma,bir gün de olsa ara

İstemese de dost olarak seni dost sesiyle irkilsin bu gönül.



Talan olsa da gönül bahçem, güllerin arasında kokun var

Sevdan zehir olup aksa da su kalbime, arkadaş olarak kalsan da

Yasadığını bilerek sevmek var, gönül bahçen de solsam da artık

Sevdanı  silemedim silinmiyor bebeğim.



Sen yokken seni sevip sevmediğim sorguladım çoğu kez

Sevmediğim düşündükçe hançerler girdi kalbime.

Acının doruklarına ulaştıkça geceleri,

Senin içinde mutluluğunda avundum çoğu kez.



Bensiz başka dünyalarda mutlu olman duraklattı sevgi fırtınamı

İstedim arkadaş olmayı, mantığım kabul etti sensizliği

Kalbim asla kabul etmedi sensizliği,

Sevdanı silemedim,silinmiyor bebeğim.



Yağmurlar yağdı  gönül tahtıma,

O kadar kolay değilmiş bebeğim

Senin yokluğunla yaşamak.

Sırf seni mutlu görmek için yaşadım.



Belki bir daha konuşmayacağız seninle,

Bir daha birbirmizin aklına düşmeyeceğiz nicedir.

Ayrılık aksamlarına karanlık gözyaşlarımızı dökmeyeceğiz.

Sevdanı istesende silnmiyor silemedim bebeğim.', 'Sevgini silemedim silinmiyor bebeğim Arkadaş kalalım,dost kalalım diyorsun, Yüreğimin derinliklerine öyle işlemiş ki gözlerin Silinmiyor sil...', ARRAY['Türk Edebiyatı','Şiir','Gül Gültekin']::text[], 8.5, '{"poet":"Gül Gültekin","poet_slug":"gul-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevgini-silemedim-slinmiyor-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakarış', 'yakaris-abdurrahim-karakoc-gvxl5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gücümüz kâfi değil, pek naçarız Allah''ım

Tavşan yavrusu görsek hep kaçarız Allah''ım

Yalvarırız kapında el açarız Allah''ım

Bizleri kamusalcı BAŞ''a muhtaç eyleme

Ne zaman yola çıksak yoldan çevrilmekteyiz

Her gün ezilmekteyiz, her gün savrulmaktayız

Dünya cehenneminde yanıp kavrulmaktayız

Ateşin sıkletinden KIŞ''a muhtaç eyleme

Doğacak nesilleri dört başı mamur gönder

Günahsız ellerinde demet demet nur gönder

Rahmetine susadık, hayırlı yağmur gönder

Kurutma kökümüzü, YAŞ''a muhtaç eyleme

Atlayıp geçmek zordur dikili kazıkları

Eğlencede, israfta tükettik azıkları

Sen doyur gönlümüzü, sen artır rızıkları

Yoksulları ekmeğe, AŞ''a muhtaç eyleme

Zulüm bitsin dünyada akmasın masum kanı

Anaların, eşlerin artık yanmasın canı

Atıp kaçırmak için pusudaki şeytanı

No''lur ellerimizi TAŞ''a muhtaç eyleme

Hakikat iklimine girmemize nusret ver

Hakikat güneşini görmemize nusret ver

Hakikat çiçekleri dermemize nusret ver

Kullarını hayale, DÜŞ''e muhtaç eyleme.

31 Ekim 2005/Vakit', 'Gücümüz kâfi değil, pek naçarız Allah''ım Tavşan yavrusu görsek hep kaçarız Allah''ım Yalvarırız kapında el açarız Allah''ım Bizleri kamusalcı ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yakaris-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-i-brahim-sahutoglu-61pbk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülü sevdim, dikeni olduğu halde

Güle gönül verdim, gülüm solmasın diğe

Gülüyorum, gülmüyor

Gülme hastası olduğu halde

Gülü saplıyor kalbime kader

 Gülmeden öleğim diğe....', 'Gülü sevdim, dikeni olduğu halde Güle gönül verdim, gülüm solmasın diğe Gülüyorum, gülmüyor Gülme hastası olduğu halde Gülü saplıyor kalbime...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Şahutoğlu']::text[], 8.5, '{"poet":"İbrahim Şahutoğlu","poet_slug":"i-brahim-sahutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gulum-161-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akbaba, Siyah Çocuk, Açlık', 'akbaba-siyah-cocuk-aclik-berrak-su-yy5om', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlatamam,

Kokusunu bilsem de,

İki çift yıldız,

Karanlığında gecenin,

Kaysada elime.

Cehennemi bilir bu bakışlar,

Doğduğundan beri,

Seçilmiş günahlara.

Ödenecek bedel bedeni,

Bilmediğimiz gibi,

Bilmek istemediğimiz gibi.

Bekliyor akbaba,

An yakın,

Bedel ödeyen bedenin,

Suskun teslimiyetini,

Alacak..

Anlatamam,

Görsemde uzaktakini.

Kurgu olsa,

Dijital, çekilmiş,

Seyirlik sadece.....

Berrak Su', 'Anlatamam, Kokusunu bilsem de, İki çift yıldız, Karanlığında gecenin, Kaysada elime. Cehennemi bilir bu bakışlar, Doğduğundan beri, Seçilmiş...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/akbaba-siyah-cocuk-aclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 61', 'resaran-siir-ve-beyitsiler-61-huseyin-avdic-91pht', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiçlik Kazananların Sonu

Dini dinsizlik olanların kazancı olur bir hiçlik.

Kazanci hiçlik olanların sonu olur cehennemlik! 

Berlin, Ekim 2005.', 'Hiçlik Kazananların Sonu Dini dinsizlik olanların kazancı olur bir hiçlik. Kazanci hiçlik olanların sonu olur cehennemlik!  Berlin, Ekim 200...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/resarani-siir-ve-beyitsiler-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Çocuklarımız', 'bizim-cocuklarimiz-hasan-gorgu-pehsr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuklarımız

Bizim çocuklarımız

Sırtında sopa kırıp ağlattığımız

Kaynar sular döküp haşladığımız

Sonra da sokağa bıraktığımız

Çocuklarımız

Bizim çocuklarımız

Köprü altlarında viranelerde

Tiner çekip uyuyan

Uyandığında bir avuç ekmek için

Kapacak çanta kovalıyan

Çocuklarımız

Bizim çocuklarımız

Bayramlarda hamasi nutuklarla 

Yarınlarımızı teslim ettiğimiz

Ardından terk edip gittiğimiz

Yetimlerimiz

Çocuklarımız

Bizim çocuklarımız

Anasız babasız büyüyen

Yetimhanelerde ayak sürüyen

Islah evlerinde çürüyen

Unuttuğumuz geleceğimiz

Vazgeçtiğimiz yarınlarımız

Çocuklarımız

31.10.2005

Saat: 16,47', 'Çocuklarımız Bizim çocuklarımız Sırtında sopa kırıp ağlattığımız Kaynar sular döküp haşladığımız Sonra da sokağa bıraktığımız Çocuklarımız B...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bizim-cocuklarimiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahtalıköy II', 'tahtalikoy-ii-caner-avci-5zlgb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Masa tahta,tabure tahta 

Yer tahta, tavan tahta 

Kumkapıdaki Agopun Meyhanesi 

Orman kokmuyor 

Tahta pencereden bakıyorum denize 

Tahtadan kayıklar balıktan boş dönüyor

Tahta vapurlar  geçiyor kapkara dumanla

Deniz kokmuyor 

Birgün meyhane açılmadı 

Tahta tabutta götürdüler Agop''u 

Tahtadan mezar başlığı yaptılar 

Üzerine ad bile yazmadılar.', 'Masa tahta,tabure tahta  Yer tahta, tavan tahta  Kumkapıdaki Agopun Meyhanesi  Orman kokmuyor  Tahta pencereden bakıyorum denize  Tahtadan k...', ARRAY['Türk Edebiyatı','Şiir','Caner Avcı']::text[], 8.5, '{"poet":"Caner Avcı","poet_slug":"caner-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tahtalikoy-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aman Dikkat!', 'aman-dikkat-abdurrahim-karakoc-x2vm1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haramsız mal azaldı, haramzade çoğaldı

Bu çağda helâl yemek büyük cesaret ister

İnsanı sıfatıyla anmak geride kaldı

Domuza domuz demek büyük cesaret ister..

29 Ekim 2005', 'Haramsız mal azaldı, haramzade çoğaldı Bu çağda helâl yemek büyük cesaret ister İnsanı sıfatıyla anmak geride kaldı Domuza domuz demek büyük...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aman-dikkat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz kızı', 'deniz-kizi-halime-vatansever-76rbt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mor bir deniz

Güneş yüzüyor üzerinde

Kumsalda midye kırıntıları

Ve bir oğlan

Her gün aynı saatte

O kumsalda

Bir oğlan 

İki karanfille

Sevdiğinin denizden çıkmasını beklermiş

Kız oğlana bir kez görünmüş

Oğlanın gönlü denize düşmüş

Aklı denize düşmüş

Yolu denize düşmüş

O gün bugündür

Aynı oğlan

O kumsalda

Aynı karanfillerle

Bir deniz kızını beklermiş', 'Mor bir deniz Güneş yüzüyor üzerinde Kumsalda midye kırıntıları Ve bir oğlan Her gün aynı saatte O kumsalda Bir oğlan  İki karanfille Sevdiğ...', ARRAY['Türk Edebiyatı','Şiir','Halime Vatansever']::text[], 8.5, '{"poet":"Halime Vatansever","poet_slug":"halime-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/deniz-kizi-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mekanı Karanlık Sokaklar', 'mekani-karanlik-sokaklar-burhanettin-akdag-bkuyu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmurlu, soğuk, kasvetli karanlık geceydi 

Yürüyordum ıssız caddede

Düşünceli, amaçsızca 

Öylesine boş bir günümdeydim 

Birden irkildim kulağıma çalınan tiz sesle 

Karanlığa alışmaya çalışan gözlerlimle baktım 

Simsiyah parlayan bir çift göz 

Bana bakıyordu dikkatlice, ürkek 

Çaresizdi, ümitsiz ve bitkin. 

Belli belirsiz inledi 

“Ekmek parası verir misin ağbi? ”

Şöyle bakındım 

İyice, yukarıdan aşağıya 

İnce kazak, yırtık pantolon, ayaklar çıplak 

İçimi acı bastı, tam kalbimin üzerine 

Karıştım, harmanlandım, alabora oldum 

Sordum kekeleyerek, incitmeden 

''Niye sokaktasın, yok mu kimin kimsen? '' 

Diyebildim hıçkırarak zar zor

Boğuldum 

''Yok ağbim, babam ölünce annem evlendi'' 

İstememişler, sevmemişler, kaçmış sokağa. 

Elinde tinerli pamuk, biraz bali, boş vermiş dünyaya 

''İstemez miydim ben de akranlarım gibi, okumayı 

Sıcak evimde, yatağımda olmayı 

Ama buradayım işte,

Buz gibi betonun bağrında 

Aramızda sadece, kolinin ince kartonu 

Üzerimi örtecek sevgi yorganım bile yok 

Ağlasam kârı yok, çalışmak istesem gücüm yok 

Gücüm olsa da, çalışacak iş yok

Ne yapayım ben şimdi, öleyim mi ağbi? 

Oturdum yanına, elim omzunda 

Ağlaştık sarsılarak, harlandık soğukta 

Ne kadar da beklentisi varmış hayattan 

Yüreği cıvıl cıvıl, bir dolu özlemleri var 

Ama örmüştü ağlarını kader 

Sarmıştı karanlıklar hayatını, geleceğini 

Yıkılmış, yok olmuştu kuytu köşede 

Tek derdi vardı, 

En azından günü kârlı kapatmak.

Başka düşünceleri de vardı,

Aama o karanlıklar yok mu? 

Karartmış, soldurmuştu filizi baharda 

Yaz görmeden, hazana hiç uğramadan 

Çökmüştü kış soğuğu hayallerine

Acımasızca. 

Üşüyordu geleceği, yoktu beklentisi

Biraz ilgi, biraz gülümseme, o kadar

Çok değildi isteği 

Saygıyı çoktan unutmuştu, sevgiye zaten hasret 

Yanıyordu yüreği, hak etmeden yaşadıklarıyla… 

Sormamışlardı doğarken ona, 

İstemezdi belki de doğmayı 

Ağız tadına hasret, ışık arıyor karanlığına 

Üşüyor, hırslanıyor, yanıyor düşleri 

Hayata kızgın, raydan çıkmış raydan, itilmiş çukura 

Beyni karanlık, 

Geleceği ve düşleri simsiyah 

Aydınlatamıyor yolunu tek başına

Çaresizlik bitirmiş

Yetmiyor gücü dikilmek için, çözülüyor 

Vebal kimin, cezası kimin, bedeli ödeyen kim? 

Oysa özlemleri, istekleri tastamam. 

Ne yapsa, ne kadar da çırpınsa

Tutmuyor elinden kaderi 

Geleceği zaten çaresizlik

Mekânı karanlık sokaklar… 

(31.10.2005)

Burhanettin Akdağ', 'Yağmurlu, soğuk, kasvetli karanlık geceydi  Yürüyordum ıssız caddede Düşünceli, amaçsızca  Öylesine boş bir günümdeydim  Birden irkildim kul...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/mekani-karanlik-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya İstiyorum', 'dunya-i-stiyorum-necati-keceli-jcypy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşi şafakta doğmuş tertemiz

   Havası,suyu hep berrak ve leziz

   Ozan tabakası kara deliksiz

   Tertemiz olan, dünya istiyorum

   Hiç deprem fırtına afet olmasın

   Ne bir canlı nede insan ölmesin

   Çeşit çeşit çiçek açsın solmasın 

   Mis gibi kokan, dünya istiyorum

   Çayır çimen, yeşil vadi ovası 

   Her ağaçta birkaç kuşun yuvası

   Tüm insanların bir tatlı duası

   Duası olan, dünya istiyorum

   Her evde bulunsun büyüyen bebek

   Hiç kurumasın gül papatya çiçek

   Çiçekten çiçeğe uçsun kelebek

   Kuşları uçan, dünya istiyorum

   Kavga dövüş asla savaş olmasın

   Bu insanlar kötü yola sapmasın

   Yavrular dünyada yetim kalmasın

   İnsana bakan dünya istiyorum

   Gam keder acısı asla olmayan

   Kötü kadere göz yaşı dökmeyen

   Bu insanlara kem gözle bakmayan

   Savaştan kaçan dünya istiyorum 

   Necati KEÇELİ

   ADANA', 'Güneşi şafakta doğmuş tertemiz    Havası,suyu hep berrak ve leziz    Ozan tabakası kara deliksiz    Tertemiz olan, dünya istiyorum    Hiç de...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dunya-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşmekten Korkma', 'dusmekten-korkma-gozde-hatiboglu-peky5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşmekten korkma, düşersen tutarım ellerinden..

Bırakmam yüreğini..

Sen yeter ki çıkart duyguları zincirlerden..

Hissettiklerine kulak ver..

Gözlerinde gördüğüm aşk hayat bulsun dudaklarında..

Öyle büyük bir sevda biriktiriyorum ki sana..

Hadi içindeki sesler çıksın dışarıya bağıra bağıra..

O kadar yakınız ki arzuya, bir nefes daha..

Hadi uzattım ellerimi, korkuların inadına..

Birlikte var edelim Şehr-i İstanbul’a nispet yaparcasına..

Gözlerim gözlerinde geçerken hayaller..

Dilimizde şarkılar var yüreğe giden..

Birlikte var edelim aşkı yeniden..

Düşersek de; başlarız kalktığımız yerden..

(30.ekim.2005)', 'Düşmekten korkma, düşersen tutarım ellerinden.. Bırakmam yüreğini.. Sen yeter ki çıkart duyguları zincirlerden.. Hissettiklerine kulak ver.....', ARRAY['Türk Edebiyatı','Şiir','Gözde Hatiboğlu']::text[], 8.5, '{"poet":"Gözde Hatiboğlu","poet_slug":"gozde-hatiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dusmekten-korkma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin', 'neredesin-ozkan-karaca-0lqxu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anılarımızın paslı kapısından girerek

Zamanların an koridorlarında geziniyorum

Ahu gözlerinin melteminde

Senin gönlünü hicranıma sürmeliyerek

Ufukların derinliğine kilitliyorum

Hani gözlerin gözlerimde eriyordu

Hani sözlerin sözlerimi arıyordu

Hani nefesin nefesimi soruyordu

Hani sevdan sevdama ortaktı

Şimdi ise yoksun 

Karanlığın sisine kapandın

Seni arıyorum

Kaldırımların kirli kirpiklerinde

Seni soruyorum

Uçan kuşların yankılı sesinde

Karanlığa bürünmüş, hayatımda boğulmuş

Gölgen gölgemi tokatlıyor

Ey! Sevdanın yanlızlığına sokulmuş

Gözlerin gözlerimi kavalıyor

Ruhumun hüznü seninle açılıyor', 'Anılarımızın paslı kapısından girerek Zamanların an koridorlarında geziniyorum Ahu gözlerinin melteminde Senin gönlünü hicranıma sürmeliyere...', ARRAY['Türk Edebiyatı','Şiir','Özkan Karaca']::text[], 8.5, '{"poet":"Özkan Karaca","poet_slug":"ozkan-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neredesin-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibrit Alevinde Yaktım Denizleri', 'kibrit-alevinde-yaktim-denizleri-sebahattin-abi-1c59i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şehrinin yalnızlığı çöktü gözlerime

Sevda yüklü bulutlara bıraktım anıları

Zamanı durdurdum son bakışında 

Ufukta kaybolurken gül yüzün

Kibrit alevinde yaktım denizleri.

Şehirlerarası otobüslerde 

Bilmem kaç numaralı koltukta

 yalnız yüreğim

Şehir ışıklarında saklı umudum

Yüzümde dünden kalma tebessümüm

Gözlerimden süzülen yaşlarla

Kibrit alevinde yaktım denizleri.

Sarhoş cümlelerin dil sürçümünde 

Bir türlü ses olamayan hoşça kal dilimde

Henüz gözlerin gözlerimde

Şimdiden özlemin oturdu yüreğime

Zamanlı ayrılığın içimi yakan dakikalarında

Kibrit alevinde yaktım denizleri

Son sigaramın son nefesinde

Bakışlarında saklı; ne olur gitme

Veda busen titretirken dudaklarımı

Teninin kokusu sarmışken bedenimi

İsyanımı haykırdım sokaklarına

Kibrit alevinde yaktım denizleri.

08.10.2005', 'Şehrinin yalnızlığı çöktü gözlerime Sevda yüklü bulutlara bıraktım anıları Zamanı durdurdum son bakışında  Ufukta kaybolurken gül yüzün Kibr...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Abi']::text[], 8.5, '{"poet":"Sebahattin Abi","poet_slug":"sebahattin-abi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/center-kibrit-alevinde-yaktim-denizleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Ağaçlarında Çiçek Açtı Sevdam', 'dar-agaclarinda-cicek-acti-sevdam-bahri-yildirim-ed8f5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu sabah:

Bütün kötülerine ve kötülüklerine 

 İnat olsun diye Dünyanın

İKorkunç ve inanılmaz

Bir savaş açtım..

Bayrak açtım umutsuz yaşamalara

Onursuz sevmelere

Sana güvenip çıktım yola

Var mısın benle yarışa? 

Ne düşler öldürdüm 

Ne kötülükler sildim bir bilsen

Seni sevmek uğruna

Ama katili ben değilim hiç bir şeyin.

Hatta ve hatta:

Kimseler bulamaz diye

Umutlarımı dar ağaçlarında sakladım.

Kurşunlanacak ora kaldığı için

Orada çiçek açtı sevdam.

Bütün sevda düşmanlarına inat.

''''Gül diktim yollarına'''' ben de.

Birde baktımki değişmiş 

Dünya''nın yörüngesi.

Dönüyor benden sana.

Her şeyin inadına.

Anladım ki artık 

Tam zamanıdır aşkın.

Seni delice sevmelerin

Özlemenin tadında seni beklemelerin

Ve seni yüreğime 

Gömmenin tam zamanıdır.

Hazır mısın? Yüreğimin sultanı

Yüreğinden bir öpücük vermeye

Hazır mısın? 

Delice sevmelerin kuşluk vaktinde beynim

Ben dayanabileceğimi sanmıyorum

Akşam çok uzaklarda

Ama.....

Ben sana yakınım çok şükür..', 'Bu sabah: Bütün kötülerine ve kötülüklerine   İnat olsun diye Dünyanın İKorkunç ve inanılmaz Bir savaş açtım.. Bayrak açtım umutsuz yaşamala...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dar-agaclarinda-cicek-acti-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürüm', 'olurum-emre-cankaya-yradk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin için yaşarım doğdum doğalı beri,

Savaşacağım tabi burası meydan yeri,

Şanlı Türk’ün askeri çekilir mi hiç geri; 

Bir karışına Vatan feda olsun şu canım,

Mermi sineme geldi akar durmuyor kanım.

Kâfir düşman askeri ateş saçtı yarama,

Allahım kurtar beni durmuyor şu kanama,

Aman ya Rabbim aman ölüyorum galiba; 

Vatan için ölürsem ben de şehid olurum,

Sinemi açtım dağa vurun beni ölürüm.', 'Senin için yaşarım doğdum doğalı beri, Savaşacağım tabi burası meydan yeri, Şanlı Türk’ün askeri çekilir mi hiç geri;  Bir karışına Vatan fe...', ARRAY['Türk Edebiyatı','Şiir','Emre Çankaya']::text[], 8.5, '{"poet":"Emre Çankaya","poet_slug":"emre-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olurum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Aşk - Açık Yasa', 'uzak-ask-acik-yasa-yasar-pullu-7znlt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ölüm tasarlanmaşkı sorma

hüznü doldurup koynuna

uçurumlar beslediği aşına

Ağrı dan yavarlanır Nemrut a

******

Bütün sırları tutuklanır bir kentin

sorguya gerek yok 

açıktır yasa

Yağmurdan kaçar adam

haddeden geçer

soyunur uzaklarda

Ne yara sarılır ne dua okunur

çağından uzaktır aşk

çoğalır nemli odalarda', 'Bir ölüm tasarlanmaşkı sorma hüznü doldurup koynuna uçurumlar beslediği aşına Ağrı dan yavarlanır Nemrut a ****** Bütün sırları tutuklanır b...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uzak-ask-acik-yasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Figan', 'figan-yakup-icik-zkedf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir zengin evinde,

Cocuklariyla eglenirken..

Koskoca tv..ekranindan,

Insanlar,

Insanlari öldürüyordu...

...insan mi? insan! 

...evet evet...

Yok yok, adamlari öldürüyorlardi.

Kadinlarda vardi.

Hani var ya bizi insan diye doguran,

Cennet ayaklari altinda olan..

kadinlar iste! 

Ben melek derim onlara.

...Tanri kanat takmis cirpiniyorlardi...

Ölmek ne? 

Ölüm ne? 

Ölümü ve ölmeyi bilmeyen,

Yumlu yumlu avuclu,

Cocuklarda vardi.

Gül gibi solgun gözleri görülüyordu! 

ölü...ölü.

Bu görüntü gündüz cekilmisti.

Ciglik yagiyordu gökten.

Utangac gözlerim,icime yagiyordu! 

Kalbimde figan...

Gördüklerimden her yer,

Alkirmiziydi.

Kipkirmizi.

Kipkizil.

Kizil.

Al...

Zengin cocuklari,da havaya,

Serefe bardak kaldiriyorlardi; 

Güle güle..

Oynaya oynaya! 

Ictikleri sarapti.

Saraplarinin rengi,

Al.

Kizil.

Kipkizil.

Kipkirmizi.

Alkirmiziydi...

Ben mi? 

Koskoca tv.de kendimi izliyordum,

Öle...öle.

Ben mi? 

Insanlar eglenirken,

Insanligimdan nefret ede ede,

Kendimden nefret ediyordum! 

...1989-2005

(31.10.2005)', 'Bir zengin evinde, Cocuklariyla eglenirken.. Koskoca tv..ekranindan, Insanlar, Insanlari öldürüyordu... ...insan mi? insan!  ...evet evet......', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/figan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Olan Tutsaklığım Özgürlüğümdür...', 'sana-olan-tutsakligim-ozgurlugumdur-ozgur-celik-tw9h7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni düşünüyorum kaç zamandır.

yokluğun içimde dal sürüyor.

her yanımda inatçı sarmaşıklar

elim kolum bağlanıyor.

sonra sen çıkıp geliyorsun

tıpkı giderken ki gibi

hiç değişmemişsin.

bir bir koparıyorsun sarmaşıkları

her yanında çiçekler,

orta da yüzün, tüm çiçeklerden daha güzel.

hadi diyorsun bana Özgür''sün artık

kuşlar kadar Özgür,

bir kelebek kadar.

koşup kaybolmak geliyor içimden,

yapamıyorum

Özgür''lük korkutuyor beni,

bir adım atıyorum,

yığılıp kalıyorum yüzükuyun.

dizlerim kanıyor,

tıpkı çocukluktaki gibi.

tutup kaldırıyorsun beni

cesaretlendiriyorsun,

hadi! diyorsun, yapabilirsin! 

anlıyorum ben Özgür olamam artık

anlıyorum, benim Özgür''lüğüm

sana olan tutsaklığımdır.', 'seni düşünüyorum kaç zamandır. yokluğun içimde dal sürüyor. her yanımda inatçı sarmaşıklar elim kolum bağlanıyor. sonra sen çıkıp geliyorsun...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sana-olan-tutsakligim-ozgurlugumdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kararsızlıktan bıktım', 'kararsizliktan-biktim-ali-asli-2hvvf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanki bitmeyecek kurduğum hayellerim,

Ya olmazsa diye giren düşüncelerim.

Bazen kurduğum hayellerim imkansız geldi,

Bazende tek savaşım onlar için oldu.

En büyük savaşım kendimle,

En büyük zararım kararsızlıktaki beynime.

Biraz mutlu,biraz mutsuz olmaktan,

Gülmenin arkasından ağlamaktan,

Seni ayın bir kaç dakikası yaşamaktan,

Diğer kalan dakikalarda hayalini kurmaktan bıktım....', 'Sanki bitmeyecek kurduğum hayellerim, Ya olmazsa diye giren düşüncelerim. Bazen kurduğum hayellerim imkansız geldi, Bazende tek savaşım onla...', ARRAY['Türk Edebiyatı','Şiir','Ali Aslı']::text[], 8.5, '{"poet":"Ali Aslı","poet_slug":"ali-asli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kararsizliktan-biktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni istiyorum', 'seni-istiyorum-selim-ulutas-ehwo7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayal kurduğum saatlerde

Yanına yaklaşıp elini tutmak

Boynuna sarılıp yanağını öpmek

O sıcacık bakışlarını hissetmek

Hayal kurduğum saatlerde 

Nasıl sana gelebilmek

Seni birkez olsun görebilmek

Seni doyasıya sevebilmek

Hayal kurduğum saatlerde

Seni beyazlar içinde görmek

Sana sonsuza kadar ulaşabilmek

Seninle bir ömür boyu beraber olmak istiyorum', 'Hayal kurduğum saatlerde Yanına yaklaşıp elini tutmak Boynuna sarılıp yanağını öpmek O sıcacık bakışlarını hissetmek Hayal kurduğum saatlerd...', ARRAY['Türk Edebiyatı','Şiir','Selim Ulutaş']::text[], 8.5, '{"poet":"Selim Ulutaş","poet_slug":"selim-ulutas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-istiyorum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölenler Ölmeyenler', 'olenler-olmeyenler-yakup-icik-fhk0e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne ölür ki dünyada gözüm

Sen onlara öldü mü diyorsun

Sen ölümü ne biliyorsun

Hem sen hic öldün mü ki

Ölmüste,

Ölümü görmüs gibi konusuyorsun.

Senin bir adin var

Benim de bir adim var gözüm

Ölümün adi da ölüm

Tanri ölümü korkanlara

Korkularindan yaratti

Ne korkarsin ölümden be gözüm

Ölüm nedir sen biliyormusun

Hem ölüm kimin icin gözüm

Ölmek kime nasip olur bilirmisin

Kötüler ölür gözüm

Insanligin erdemligini

Yok eden zavallilar ölür be gözüm.

Unutma gözüm

Hosgörüyle insanliga isik tutan

Bütün erdemli insanlar

Hep yasar dünyada

Anilarak,bil gözüm

Ve Tanri,nin yaninda onlar mutlu

Ölmez ki gözüm.

(30.10.2005)', 'Ne ölür ki dünyada gözüm Sen onlara öldü mü diyorsun Sen ölümü ne biliyorsun Hem sen hic öldün mü ki Ölmüste, Ölümü görmüs gibi konusuyorsun...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olenler-olmeyenler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Aşkın Uç Noktası**', 'askin-uc-noktasi-hulya-simsek-fs36h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın uç noktası…

Kaybetmeyi 

göze alabilmektir sevgili

Nefesi nefesine değse

İçinin titrediği,

Kendinden çok sevdiğin varlığın

Gitmesine izin verdiğin gün

Onu… 

en çok sevdiğin gündür.

Aşkın uç noktası…

Kaybetmeyi

göze alabilmektir sevgili

Aşk dediğin,

Ellerinden bir karış uzun

Dokunsan ölecek

Aşk dediğin,

Hiçbir zaman 

senin olmayandır

Haberin olsun….', 'Aşkın uç noktası… Kaybetmeyi  göze alabilmektir sevgili Nefesi nefesine değse İçinin titrediği, Kendinden çok sevdiğin varlığın Gitmesine iz...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/askin-uc-noktasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-cihan-obelik-eotjo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Riyakar çıksın tüm dostlukların,

Ebediyen dinmesin hiç ızdırabın,

Akarken acı versin damarda kanın,

dermansız dertler peşini bırakmasın.

umutların boşa çıksın,

hayallerin başına yıkılsın,

hep vefasızlar kapını çalsın,

dermansız dertler peşini bırakmasın.

itler bile yüzüne dönüp bakmasın,

gören seni deli divane sansın,

hep vefasızlar kapını çalsın,

dermansız dertler peşini bırakmasın.

Kör olsun gözlerin güzellikleri görme,

çöllerde su ara sürüne sürüne,

umutların paslı hançer gibi batsın kalbine,

dermansız dertler peşini bırakmasın.

yaz ayında karlar yağsın saçına,

doktorlar ilaç bulamasın acına,

akbabalar yuva yapsın yarana,

dermansız dertler peşini bırakmasın

Erisin vücudun yumak yumak,

senin kaderin olsun hep susmak,

cehennem olsun sana son durak,

dermansız dertler peşini bırakmasın', 'Riyakar çıksın tüm dostlukların, Ebediyen dinmesin hiç ızdırabın, Akarken acı versin damarda kanın, dermansız dertler peşini bırakmasın. umu...', ARRAY['Türk Edebiyatı','Şiir','Cihan Öbelik']::text[], 8.5, '{"poet":"Cihan Öbelik","poet_slug":"cihan-obelik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/beddua-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni unutmayacağım', 'seni-unutmayacagim-selim-ulutas-0qp0n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dökülsün gözyaşım andıkça seni

Gözümden yaşları silmeyeceğim

Ömrümce yaksada hasretin beni

Kızıpda kadere küsmeyeceğim

Gönlüme acılar dolup taşsada

En güzel ümitler bitip solsada

Ben aşk senedini yazmışım sana

Senden başkasını sevmeyeceğim

Hasretin vuslatın bir yana 

Hayatım bir yana aşkın bir yana 

Sana kavüşmadan düşsem toprağa

Adını anmadan', 'Dökülsün gözyaşım andıkça seni Gözümden yaşları silmeyeceğim Ömrümce yaksada hasretin beni Kızıpda kadere küsmeyeceğim Gönlüme acılar dolup ...', ARRAY['Türk Edebiyatı','Şiir','Selim Ulutaş']::text[], 8.5, '{"poet":"Selim Ulutaş","poet_slug":"selim-ulutas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-unutmayacagim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Söz', 'son-soz-ayfer-ersoy-mqwo6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalan 

Gözlerimin gülüşüne verdiğin karşılık yalan

Ellerimin içine akıttığın sıcaklık yalan

Ve gideceksin yalanlarını bırakıp bana....

Gün ışığı bakışlarını alıp benden gideceksin....

Bir parçamı alıp benden gideceksin....

Derin bir sancı kaplayacak içimi 

Kıvranarak uyanacağım birkaç sabah

Pencereleri, kapıları kapatacağım... ki rüzgar kokunu getirmesin....

Yokluğun bir, bir duvarlara sinecek....

En güzel hayalleri yaşatıp; umutları paylaşıp; en olmaz yerde gideceksin....

Karanlık tokat gibi hayalini sunacak bana...

Fotoğraflar bir anlık tebessümleriyle bakacak...

Kahkahalarımızı bir, bir azaltıp sessizliğe karışıp gideceksin...

Dolunay şahitliğinde senin oluşlarım çıkacak karşıma

Yıldızların yorgan olduğu geceler ıssızlaşacak...

Saçlarım tarağa alışacak parmaklarından sonra...

Soğuk saatin sesi açacak gözlerimi, buselerin yerine.... gideceksin....

İlk bebeğimizin heyecanı, ilk adımı, ilk sözüne tanıklığımız kalacak video kasetlerinde...

Kanepe üzerinde televizyonun kumandası kalacak tartışmasız sessiz...

Sofrayı hazırlamak bile zor gelecek...

Her gün yeniden sensiz güne başlamaya alışacak bu beden

Gidişine sessizce kabullenişim kalacak....

Koca bir yalan olacaksın...

Gideceksin...

Gelişin bir ömre bedelken

Gidişin bir ömrün bitişini hatırlatacak...

Erken diyeceğim çok erken daha...

Yinede gideceksin....

Avuçlarımın ayasından sıcaklığını alıp gideceksin....

Bedeninin sonsuz yolculuğuna ilk ve son kez uğurlayacağım seni... 

Her gidişinde dönüşünü bekleyen benken bu kez sen bekleyeceksin beni...

Gideceksin ve bir gün ben geleceğim sana... beni sen karşılayacaksın 

Ben de yalan olacağım sonra...... seninle yeni bir gerçeği yaşamak üzere  geleceğim.....

Not: 15 ekim 2005 gecesi vefat eden anne anemin 16 ekim 2005 tarihinde ki cenaze töreninde dedemin;  cenazenin ardından bakışlarında okuyabildiklerimdi paylaştıklarım..

Ve bir gün hayatımı paylaşacağım kişiye rastladığımda ve onunla ömrümün kalanını yaşamaya başladığımda  dilerim ömre sığmaz huzuru paylaşırım ve her ne kadar vakti dolmuşta olsa “daha erken “ diyebilmeliyim......

							 31.10.2005', 'Yalan  Gözlerimin gülüşüne verdiğin karşılık yalan Ellerimin içine akıttığın sıcaklık yalan Ve gideceksin yalanlarını bırakıp bana.... Gün ı...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/son-soz-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümitsiz bir bekleyiş', 'umitsiz-bir-bekleyis-eyup-demirci-bshqv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir hüzünle yanlızklık çöktü ki üstüme; 

öyle ümitsiz öyle soğuk öyle halsiz

pencere mi açmadım rüzgar girsin diye..

kuşlardan ses yok hazana ermiş mevsim

meltemleri esmez olmuş çoktan! 

susmuş heryan, gün akşamına kavuşmadan

güneşler batmış, zamanım geçmiş yaşlanmadan

gönlümün yüzünde sıcak yüzler batmış

o gülen gözlerden eser yok şimdi

yürekler bir bir uçup gitmiş çoktan! 

hansız yollardan kervan geçer gibi 

hiç durmadan gelen geçmis gönül diyarımdan

ne penceremden kuş geçer ne de kapımdan kervan

çöllerde vaha yok artık, hülyasına daldığım

gerçekler serabına ermiş çoktan! 

ansızın çöker gecem akşamından önce 

kalmadı serseri bir ümidim daha gülmeye

duvarlar da aşina artık o soğuk düşlere

hayallerimden ses yok senden yana bir nefes

sensiz yıllarım sevgisiz bitmiş çoktan! 

ve bu sensizliğin bedenimdeki son resmi

her gece görürken, duvarda o soğuk düşünü

tutamıyorum sevğili, titreyen ellerimi

yanlızlığın resmini çiziyorum tenime

yıllarca ümitsiz bir bekleyişin hüznünde

serseri bir şairin hiç bitmeyen ölümünü...

                                                       12.09.2002', 'bir hüzünle yanlızklık çöktü ki üstüme;  öyle ümitsiz öyle soğuk öyle halsiz pencere mi açmadım rüzgar girsin diye.. kuşlardan ses yok hazan...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Demirci']::text[], 8.5, '{"poet":"Eyüp Demirci","poet_slug":"eyup-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/umitsiz-bir-bekleyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiceklerin Anaları', 'ciceklerin-analari-yakup-icik-1q9as', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüzmilyonlarca yil evvel,

Ne vardi bilirmisiniz? 

Seven sevilen yokken! 

Sevgililerinize verdiginiz ciceklerin analari...

...egreltiotlari.

...kibritotlari.

...cigeryosunlari.

...atkuyruklari vardi! (*)     

Simdi birer birer sevgililerinize verdiginiz...

...Kisa bilgi! (1)          

Hayat dünya üzerinde belki de fotosentez ile başladı. Bu, güneş ışığından enerji sağlama yeteneği derin sonuçlar doğurdu ve atmosferi değiştirerek, Dünya''nın koruyucu bir tabaka ile öldürücü radyasyondan korunmasını sağladı. Fotosentez olmasaydı, atmosferde çok az oksijen olurdu. Dolayısıyla bitki ve hayvan da bu ortamda olamazdı. Dolayısıyla fotosentezin yarattığı oksijen, yaşamın gelişmesi için uygun ortamı yarattı.

Fotosentezden önce yaşam tek hücreli bakterilerden oluşuyordu. Bunların enerji kaynakları kükürt, demir ve metandı. Derken 3.5 milyar yıl kadar önce bir bakteri gurubu herhalde kükürt ve demir yemekten bıkmış olacak ki, yakıt ihtiyaçları için gerekli olan karbonhidratı

sağlamak için, güneş ışığından enerji alma yeteneğini geliştirdi ve ortaya fotosentezin ilk tipi çıktı.

Sonra yeni bir fotosentez tipi evrimleşti. Bu yeni tip, ana girdi olarak sudan yararlanıyor ve oksijen üretiyordu. Ancak bu dönemdeki oksijen zehirleyiciydi. Atmosferde oksijen birikiminden olumsuz etkilenmemek için bazı bakteriler özel bir mekanizma geliştirdi. Ve, bakteriler oksijeni enerji kaynağı olarak kullanmaya başladı.

Bu, çok önemli bir gelişme oldu. Çünkü Dünya üzerindeki yaşam, doping almış gibi çok hücreli yaşam şekillerine dönüştü. Bugün doğrudan veya dolaylı olarak fotosentez, Dünya''daki yaşamın kullandığı enerjinin tümünü üretir. Yakıt olarak kullanılan maddeleri yakmak için etkili bir araçtır, ayrıca, fotosentez tarafından üretilen oksijen, yaşamı koruyucu bir rol daha üstlenir. Dünya güneşten gelen morötesi radyasyonun bombardımanı altındadır. Oksijenli atmosferimizin yan ürün olarak ürettiği ve atmosferin 20-60 km arasında olan ozon tabakası zararlı radyasyonun çoğunu süzer. Bu koruyucu şemsiye sayesinde yaşam, denizlerin koruyucu ortamının dışına çıkarak karalarda gelişme şansını yakalayabilmiştir.

...NOT: Bu bilgi icin sayin Murat Alp Tenay beye cok tsk.ediyorum...

...Kisa bilgi! (2)          

Dr. Muvaffak AYVAZ

“Belki dünyada bundan daha büyük bir harika yoktur. Güneş ışığı bir yaprağa değer ve fotosentezin sessiz gizliliği içinde yediğimiz besin ve soluduğumuz hava oluşmağa başlar.”

Güneş ışını 8 dakika süren 149,5 milyon kilometrelik soğuk ve karanlık feza yolculuğunu bitirip, dünyamızdaki yeşil yaprakların yüzüne değdiği an sessiz laboratuarlar çalışmaya başlar. Havanın zehiri ve toprağın suyu hemen birkaç saniye sonra şeker, protein, yağ ve nişasta şeklinde karşınızdadır. Bu akıl almaz ve her yönüyle harikulade hadiseyi bu “uzay çağında” dahi insanoğlunun hiçbir laboratuarı başarmak ve oluşturmak kabiliyetinde değildir ve belki de hiçbir zaman buna muktedir olamayacaktır.

Fotosentez’i günümüzün modern araştırmacıları “Elektromanyetik enerjisinin, biyosentez hadiselerinde kullanılabilen, kimyevi serbest enerjiye dönüşümünü sağlayan reaksiyonlar zinciri” olarak tarif ederler.

Şüphesiz bütün canlılar gibi, bitkiler de hayatlarını sürdürebilmek için, bazı faaliyetlerini durmaksızın yapmak zorundadırlar ve bu faaliyetlerini yapmak için de diğer canlılar gibi enerjiye muhtaçtırlar. Dünyamızdaki canlıların doğrudan ve dolaylı şekilde en büyük enerji kaynağı güneştir. Ancak güneşten bize gelen enerji fiziki enerjidir. Ve bu haliyle hayatı faaliyetlerde kullanılamaz. Canlı sistemlerin bunu kullanabilmeleri için kimyevi, organik gıda enerjisi haline dönüştürülmesi lazımdır.

Fotosentez öylesine bir hadisedir ki bu olay içinde ışık enerjisi kimyevi enerjiye dönüştürülerek hücrenin metabolik sistemine nakledilir ve bu enerji sayesinde karbondioksit ve su gibi iki basit maddeden 6 karbonlu ve yüksek moleküllü “organik” maddeler meydana gelir. Bu ise akıllara durgunluk veren bir hadisedir.

Dünya üzerindeki insanlığın idamesi doğrudan doğruya bu hadiseye bağlıdır. Zira “organik” gıda temini yönünden canlılar, yeşil bitkilerde olduğu gibi, gıdalarını kendileri yapabilen “Ototrof” ve hazır “organik gıdalarla beslenen ve yeşil olmayan bitkiler ile hayvan ve insanlar gibi “Heterotrof” olarak iki kısımda mütalaa edilirler. Biz insanların da içinde bulunduğu ikinci kısım canlılar, hayati faaliyetlerin sürdürülmesi için lüzumlu kimyevi enerjinin sağlanması bakımından “Ototrof” canlılara bağlıdırlar, Bu da fotosentez hadisesinin, bütün yaratıkların beslenmesi yönünden ne kadar mühim bir hadise olduğunu gösterir.

Havadaki Oksijen Dengesi:

Fotosentez denen kimyevi “reaksiyonlar” zincirinde yine hayati yönden çok önemli olan diğer bir husus da “yan ürün” olarak, atmosferi yenilemek üzere “serbest oksijen”in açığa çıkmasıdır. Havaya verilen bu oksijenin, canlılar için önemi çok büyüktür. Şayet fotosentezden oksijen çıkmasının durdurulduğu düşünülecek olursa, havanın oksijeninin, takriben 2000 sene içinde tükeneceği hesaplanmıştır. Bu da jeolojik noktai nazardan çok kısa bir süredir. Zaten atmosferik oksijenin kaynağı fotosentezdir. Nitekim yeryüzünde hayat ilk defa görüldüğü zaman, atmosferde çok az miktarda oksijenin bulunduğu da birçok deliller ile gösterilmiştir.

Fotosentezde açığa çıkan bu oksijenin menşeini bulmak için oksijen -18 izotopu ihtiva eden su ile yapılan denemeler neticesinde, yüksek bitkiler ve yeşil alglerin fotosentezi esnasında havaya verilen oksijenin sudaki oksijen olduğu bulundu. Böylelikle bütün hayati faaliyetlerde başrolü oynayan su, parçalanması neticesinde açığa çıkan oksijeniyle de havayı yenilemekte ve havadaki oksijen kesafet dengesinin muhafazasına yardımcı olmaktadır.

Burada bir an durup çeşitli yönleriyle -ancak şimdi anlaşılabilecek bir hakikat ki- “Her şeyi sudan hayattar kıldık” beyanı karşısında hürmetle eğilme arzusunu izhar etmek isterim.

Havanın Temizlenmesi

Fotosentezde hammadde olarak su dışında karbondioksit kullanılır. Her yıl bu şekilde havanın karbondioksitinden 200 milyon ton karbon, karbonhidrata çevrilir. Eğer havanın karbondioksiti muhtelif kaynaklardan desteklenmese çok kısa zamanda tükenir.

Kara bitkilerinin fotosentezci olarak büyük bir rol oynamalarına rağmen, onlardan iki kat fazla fotosentezin okyanuslarda oluştuğu tahmin edilmektedir. Yeryüzünü saran muazzam saydam satıhlar göz önünde tutulursa bunun bir sürpriz, bu çokluğun da sebepsiz olmadığı anlaşılır. Okyanuslarda fotosentez esas itibariyle alg’ler tarafından yapılır. Suyun dışında başka birşey yaşamasından çok önce, bu bitki dinamoları dünyanın atmosferini zehirli gazlardan temizleyerek, hayata elverişli hale getirmek için belki yaklaşık olarak 2,5 milyar yıl çalışmışlardı. “Diatom”lar denilen bu küçücük algler, fotosentezin su üzerindeki bu muazzam kısmına medar olurlar. Gözle görülemeyen bu mikroskobik canlıları yiyerek geçinen küçük hayvanlar, “zooplankton’lar’‘da sardalya kadar küçük varlıklardan balina kadar büyük su hayvanlarına kadar besin maddeleridir. Böylece bu görünmeyen yeşil çayırların enerjisi ondan ona geçerek beslenmeyi devam ettirir.

Kloroplastlar ve klorofilin rolü:

Cidden harikulade mekanizmaya sahip fotosentez hadisesi, kloroplast diye isimlendirilen şayanı hayret derecede düzenli bir kompleksiteye malik, stoplazmik partiküllerde cereyan eder. Kloroplastlara yeşil rengi kazandıran klorofil pigment maddesidir. Bu, fotosentez için en önemli maddedir. Çünkü güneş ışınları, yeşil bitkilerin bu özel pigmenti sayesinde absorbe edilip, canlı sisteme nakledilir. Klorofi1m en önemli hususiyeti ışığı emmesi ve floresans hassası göstermesidir.

Klorofil molekülü yeter derece enerjiye sahip bir ışık kuantumunu absorbe ettiğinde, kendisinin elektronlarından biri “eksite’’ edilerek daha yüksek enerjili bir hale döner. Bu aktif pigmentten canlı sisteme taşınan enerji ile su parçalanır ve bu esnada serbest kalan hidrojenler sistemdeki (mesela NADP — Nikotin amid dinukleotid adenin fosfat gibi)              özel yakalayıcılarla reaksiyon kademelerinde kullanılmak üzere yakalanırlar. Kabaca bu kademe reaksiyonları şöyle formüle edilebilir; 

Görülüyor ki bu kademede ışık iş görücülüğü zaruridir. Onun için bu reaksiyona “Fotosentezin ışık reaksiyonu kademesi” denir. Bu reaksiyonda ışık enerjisinin absorbe edilmesinden sonra, enerji elektron transferi halinde kademe kademe canlı sisteme aktarılıp neticede sistemde kimyasal enerjiye dönüşümü esastır. Nihayet bu kademede canlı sisteme ulaşan ışık enerjisi, ilk olarak suyu parçalamada iş gördüğünden, fotosentezin bu reaksiyon kademesi “suyun parçalanması reaksiyonu” olarak da anılır.

Güneşten pigmentlerle canlı sisteme transferi yapılan enerjinin esas itibarıyla fotosentezde karbondioksit asimilasyonu için kullanılması gayedir. Özel laboratuar şartlarında klorofil moleküllerince absorplanan ışık enerjisinin % 75 mm kimyevi enerjiye dönüştüğü hesaplanmıştır ki, bunun için kloroplastlar 7o 75 randıman- la çalışan iyi bir fabrika sayılmaktadır. Buna mukabil bugün teknikte güneş enerjisinden elektrik enerjisi elde etmek için termoiyonik dönüşümlerde ancak % 3-15, fotovoltaik dönüşümlerde ise % 10-12 verim elde edilebilmiştir. Bu da insanların canlı fabrikalardaki yerime asla ulaşamayacaklarını göstermektedir.

...NOT: Bu bilgi icin sayin Müjgan AKYÜZ hanimefendiye cok tsk.ediyorum...', 'Yüzmilyonlarca yil evvel, Ne vardi bilirmisiniz?  Seven sevilen yokken!  Sevgililerinize verdiginiz ciceklerin analari... ...egreltiotlari. ...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ciceklerin-analari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aykırı Şiir', 'aykiri-siir-yakup-icik-sh07l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceyle gündüze sarılalım

Ağlamak, gülmek, acı, tatlı var mı

Ne, nasıl, nerede bir iyice tanıyalım.

Hadi gelin ilk önce şu göğü yere serelim

Yıldızlar biz varınca düşer

Koyumavi mi kara geceler

Bir iyicemelen    bakalım.

Bilirsiniz nefes almayı ve vermeyi

Hadi gelin gelin

Üstümüzde çayır çimen

Kimler sulayacak bakalım.

02

Aldım yanıma ihtiyarlığımı, gençliğime gittim kalkıp

Sevinç dolu ve heyecanlı öylece yerinde duruyordu

Hal-hatır sormak geliyordu içimden, ne diyeceğimi bilmiyordum

Soramıyordum da, gıtpa ile gençliğime bakıyordum hayranlıkla

Aydan tenli sevgili yanında, çobanyıldızı gibi parlak gözleri vardı

Naif ama mutlu bir delikanlı, yıllar sonra ihtiyarlığımı güldürüyordu.', 'Geceyle gündüze sarılalım Ağlamak, gülmek, acı, tatlı var mı Ne, nasıl, nerede bir iyice tanıyalım. Hadi gelin ilk önce şu göğü yere serelim...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aykiri-siir-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delice Düşünceler ''Cümleleri Ölmüş Biri''', 'delice-dusunceler-cumleleri-olmus-biri-erdogan-ergin-mzich', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Örtbas edilmiş, ezilmişliğim

insanların, gereksiz konuşmaları içinde

gereğinden fazla anılmışım

yılgınlığım nerden geldi bilmem

sayfa sayfa dolaşıp gazetelerde

satılık köşe hevesindendir belki

belki de boyası bozdu gazetenin beni

elimde gri izler

o da köşe yazılarının çirkinliği

delice düşünceler benimkisi

kim ne yapsın, cümleleri ölmüş birini

diyorum ya, delice düşünceler

içimde kaynıyor,

bazen söz oluyor, gururumu incitiyor

bazen aşk oluyor, içimden dışarı akıyor

lakin kimseye zararım yok

kendimden başka

onu da tanıyamıyorum zaman

yılgınlık düşüyor üzerine

çekilyor damarımdan

damla damla his

duygusuz biri oluveriyorum

sarılıyorum kimse görmeden

aşka

satırlara döküyorum

yetmiyor

hislerim

delice düşünceler benimkisi

kim ne yapsın, hisleri ölmüş birini

Eylül 2005', 'Örtbas edilmiş, ezilmişliğim insanların, gereksiz konuşmaları içinde gereğinden fazla anılmışım yılgınlığım nerden geldi bilmem sayfa sayfa ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/delice-dusunceler-cumleleri-olmus-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin Elimde', 'ellerin-elimde-huseyin-kantar-0j87s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nefesime nefes ver son nefesimde,

tutabilirsin beni belki çizgide,

üşümüyorum sevdiğim,

ellerin elimde..', 'nefesime nefes ver son nefesimde, tutabilirsin beni belki çizgide, üşümüyorum sevdiğim, ellerin elimde.....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kantar']::text[], 8.5, '{"poet":"Hüseyin Kantar","poet_slug":"huseyin-kantar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ellerin-elimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son veda', 'son-veda-aytekin-orhan-y813r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bunca yaşadıklarımızı nerelere sakladın? 

Yüreğinin hangi köşesine gömdün, gizledin.

Hangi yağmurlarda yıkadın gözyaşlarını,

Hangi rüzgar dağıttı saçlarını,

Ve hangi güneş kuruttu içindeki sevda ateşini...

Ben unutmadım seni,

Unutamadım ki; 

............ellerinin sıcaklığını avuçlarımda.

Silemedim ki yüreğimde ki gözlerini...

Atamadım ki üzerimden bedenimde ki sıcaklığını...

Gecelerde aramıyorum artık yalnızlığımı,

Bakmıyorum pencereden yıldızlara,

İlgilendirmiyor beni köşedeki sokak lambası...

Korkmuyorum artık yazmaktan,

...............acılarımı kaleme almaktan...', 'Bunca yaşadıklarımızı nerelere sakladın?  Yüreğinin hangi köşesine gömdün, gizledin. Hangi yağmurlarda yıkadın gözyaşlarını, Hangi rüzgar da...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/son-veda-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçak yalnızlık', 'kacak-yalnizlik-aytekin-orhan-ro8u2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seviyorum yalnızlığı,

Yalnızlığımla baş başa kaldığım zaman

El ayaktan çekilip,

Gecenin masumiyetine daldığım zaman.

Dilimde maziden kalma bir melodi

(her şey gönlünce olsun) 

Dudaklarımdan dökülen iki mısra

(ay ışığında yürüyorum, 

Nereye gittiğimi bilmeden) 

Birde şu yıldızlar olmasa tepemde

Gülmeseler bana sırıtarak alaylı bir şekilde

Ben kalsam tutsak, ben kaçak,

                             .................geceler yalnız...

Giren olmasa dünyama, yerim bilinmese

Geceler zindan.

                   ....................yalnızlığımla tek başıma.', 'Seviyorum yalnızlığı, Yalnızlığımla baş başa kaldığım zaman El ayaktan çekilip, Gecenin masumiyetine daldığım zaman. Dilimde maziden kalma b...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kacak-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedenim belli', 'nedenim-belli-aytekin-orhan-yhevc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'esiyorsa rüzgar hırçın hırçın,

doğuyorsa her sabah, karanlığı yırtan güneş

yağıyorsa deli dolu yağmur durmaksızın

kaplıyorsa yeryüzünü beyaz kar örtüsü

elbet vardır bir nedeni...

ozan söylüyorsa yanık sesi, kırık sazıyla türkülerini

şair yazıyorsa kederini, sevgisini, nefretini

ressam çiziyorsa tuval''e hayallerini

elbet vardır bir nedeni

bende söylüyorsam her kelimde ismini

içime çekiyorsam her rüzgarda nefesini

her güneşin doğuşunda görüyorsam gözlerini

benim nedenim belli! 

seni özlediğim için

seni çok sevdiğim için...

11/12/2003', 'esiyorsa rüzgar hırçın hırçın, doğuyorsa her sabah, karanlığı yırtan güneş yağıyorsa deli dolu yağmur durmaksızın kaplıyorsa yeryüzünü beyaz...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nedenim-belli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki yarın', 'belki-yarin-aytekin-orhan-hnmey', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrılık vakti yaklaşınca, 

Gözlerin gözlerimle buluşur. 

Uzatınca özlemle dudaklarını, 

Ağaçlar kıskanır, silkeler yapraklarını... 

Deniz durulur, süt liman... 

Ne güller kalır ortada, ne gülistan! 

Sadece yaşanan, zamandır anımsanan... 

Ayrılık vakti yaklaşınca, 

Ellerin ellerime dokunur. 

Hasret rüzgarı eser başımda, 

Son bakışın, tatlı gülüşün kalır aklımda. 

Bir zaman donup öylece kalırım, 

Ve umut içimde, belki yarın... 

15/04/2004', 'Ayrılık vakti yaklaşınca,  Gözlerin gözlerimle buluşur.  Uzatınca özlemle dudaklarını,  Ağaçlar kıskanır, silkeler yapraklarını...  Deniz du...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/belki-yarin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asılı dünya', 'asili-dunya-aytekin-orhan-seswp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dinmez yorgunluğu gönlümün,

Dünyamı aydınlatan gözlerin olmasa...

Dalıp gittiğim duvardaki resmin,

Güneş gibi içime doğmasa...

Herkesler uyudu, gökyüzündeki kuşlar bile,

Ne olur esirgeme gözlerini benden

Geldi hazan mevsimi, kapıda çile,

Ne olur koparma resminde ki seni, benden', 'Dinmez yorgunluğu gönlümün, Dünyamı aydınlatan gözlerin olmasa... Dalıp gittiğim duvardaki resmin, Güneş gibi içime doğmasa... Herkesler uyu...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/asili-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler Şahit! ! !', 'geceler-sahit-saim-bastik-x6fgs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani, bırakıpta gittinya beni

Çok boynumu büktüm, geceler şahit.

Gönül pencereme, çizdim resmini

Çok yoluna baktım, geceler şahit.

Baykuş gibi mekân tuttum bacayı

Yokluğunda, yorgan yaptım geceyi

Yutkunarak söyledim her heceyi

Çok gözyaşı döktüm, geceler şahit.

Duvardaki saat, albümde resim

Hepsi şahit, sensin benim nefesim

Gece, karanlığa karıştı sesim

Çok ağıtlar yaktım, geceler şahit.

HARÎMİ der sayamadım dünleri

Derdim beşyüz iken aştı binleri

İlmek ettim birbirine günleri

Çok hasretler çektim geceler şahit.

Saim BASTIK (HARÎMİ)  25/10/2005-Kula', 'Hani, bırakıpta gittinya beni Çok boynumu büktüm, geceler şahit. Gönül pencereme, çizdim resmini Çok yoluna baktım, geceler şahit. Baykuş gi...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/geceler-sahit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Melek kara kuru karakız', 'mavi-melek-kara-kuru-karakiz-seref-ozturk-usta-bpixg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgili Mavi Melek; Bil ki çok zor benim için bundan sonrası.

Su kadar demiyorum, hava kadar elzemdin yaşamım için. Bütün sorunların benden kaynaklandığına inandım.Ne zaman şemsiyene sığınmaya kalksam, sırılsıklam, al kan oluyorum kirpiklerine saklansam. 

Bir gün bile küs duramazdık, üç hafta aramayacağın kadar ciddi kazalar yapmaya, cezaları hak eder olmaya başladığımı fark eder oldum. 

Tam unutmanın pansuman tedavilerine geçiyorum derken, ummadığım yerlerden gelen darbeler, şarapnel gibi açıyor, kanatıyor yaralarımı. 

Bir sevda sarhoşluğu anımda değil, seni hiçbir şekilde kaybetmeyi göze alamazdım.Yaşamımın ikinci baharında toprağımın bereketli olmasından değil, yüreğime ektiğin tohumlar en verimli hasatı almamı sağladı. Hiç böyle zengin duygularım olmamıştı. 

Bağışladığın zenginlikler ömrümün tüm karanlıklarını aydınlatacak güzel anılar, hoş hatıralar, biber lezzetinde acılar, tatlı yaralar ve tükenmesini düşünemeyeceğim dostlukların korunması görevini yükledi yüreğime. Tanışmamızı sağlayan dostlarımız, telepati frekansımızın koordinatlarını, gelişmelerin boyutlarını kestiremezler. Yüreğimdeki rap rapları darbeler sürecinden geçen 68 kuşağının yurtsever bir sevdalısı olarak aynı endişe ve heyecanla yaşamıştım: 

Hayatımda yaşayabileceğim en büyük devrimi yüreğimde yapmayı başaran gönül anarşistimsin. Bizim kuşağımız sadece dram yaşamadı, acıların kendisiyle kucaklaştı… ''Sevgili''nin baş harflerini ağaçlara kazamadı.

Bir nesil susturuldu,susmayı öğrettikleri için.Hastanelerde ki ''SUS'' işaretinin aksine susma diyenlerdensin..Bedenlerimiz kadar ruhlarımızı da sağaltıyorsun.Yaşadığım hiç bir şey seni insanı sevmekten alıkoyamıyor. Şeklen yaşadığın ataerkil toplumda,ana erk il başkaldırının bayraktarısın. 

Bel ki,senden çok,direnen kavgacı bir o kadar sevecen yüreğine tutkulu esaretim.Çok yanarım,kahrolurum seni üzersem,kırarsam..Asıl korkum; özel alanlarına düşürdüğüm patlayıcıların yarattığı tahribatı daha da büyültmeden nasıl onaracağımı bilemeyişimde saklı. 

Uzağında kalmak,yüreğimin hasretinde tutmak zorunluluğu doğdu benim için.

Bitmeyen kavgalarımız,sevdalarımızdı.Her kavgamız biraz daha kaldırdı sınırları aramızdan..Ayrılışlarımızı,kavgalı kopuşlarımızı özlemeye başlamıştım.Kendiliğinden barış doğmuştu,uğruna savaşılmayan barışların ömrü kısa olurdu..Hüzünlenmiştim,kopacak kıyametin acılarını,ayak seslerini duyar gibiydim ta derinlerimde. 

İlk karşılaşmamızı anımsarken zorlanmıştım.Fiziki özelliklerinden haberdar değildim,boyun bos un yüzün yoktu..Bir tek şey biliyordum..Acıların erken olgunlaştırdığı tatlı bir çocuk simâsıydı göreceğim.Kara kuru kara kız. Yaklaştıkça irileşen, baktıkça kaybolabileceğim derin bir göl gibi esrarengiz buğulu koyu ela gözler.Herkesin ilk bakışta fark edebileceği sihirli bir tebessüm,yol yorgunluğunu ve elmacık kemiklerine gizlenen sağ yanağındaki gamzede saklanmayı başaran hüzün çukuru. 

Kucakladığımda yere bırakırsam uçacak sandığım cılız bir beden. 

Yıllardır birbirimizi bekliyormuşçasına samimi bir kucaklaşma,bu kadar yakın duymak,yakın hissetmek,öbür yarını bulduğunu sanmak.''Susmak bazen çığlık atmaktır.'' ya işte öyle bir hal, yarımların bileşkesinden nasıl bir hilkat garibesi bütün oluşacaktı? 

Aradaki çeyrek asır''a rağmen. 

Hemşehrilerinin tanıdığı düş gezgini,yurt sevdalısı, çılgın bir serüvenci, bohem bir edebiyat dostu,Vefalı ve uslanmaz bir hümanist.. Görmeden tanımadan hakkımda bildiklerin bundan ibaretti. 

İstanbul''a gelirken ''Yollar kardan kapalı dilerim beklediğinize değer dost olurum.''diyordun.''Ben bahar çiçeklerini yüreğimde getiririm.'' demiştin. Beklemek işim,hasret aşım,dostlara duyulan özlem yoldaşım oldu hep.İstanbul''a gelirken evinde bıraktığın ne kadar dert,tasa,sıkıntı,endişe,kaygı varsa almadan gel, bizde hepsi var demiştim. 

Çözülmemiş bulmacanın bir sürü karesi boş,doldurulmak için seni bekliyor.Gel kendin oku, yukarıdan aşağıya,soldan sağası yok, hep soldan daha sola bir işaret levhası seni bana getirecektir..Çözülemediği sürece de kimliksizliğiyle yaşayan sıradan bir adam olarak kalacak.. 

Oysa kareler doldukça sıfatlanacak ete kemiğe, sevdaya dostluğa bel ki de aşka bürünecek.Kendi kimliğini bulan biri olacaktı. ''Evinizin ve yüreklerinizin kokusunu alıyorum, ne bileyim özlüyorum işte,yüreğimi sabah evde unutmuşum ben gelene kadar ona iyi bakın'' diyordu bize çektiğin telefon mesajın. Söz vermiştim yüreğini sıcak tutacağıma.'' Yüreğin yüreğimin yanındaydı, giderken ikisini de götürmüşsün.''diyebildim sadece sana.Gel tepeden tırnağa bize şekil verebilirsin, bizi değiştirebilirsin, sevebilirsin, nefrette edebilirsin, küsebilirsin fakat darılabilirsin demedim..Çünkü, o boyuta taşımadım dostluklarımı, ilişkilerimi. Aşktan büyük dostluklar ancak aşka hamallık ederler.Yürek çıkmazlarında kaybettiklerimizi ana caddelerde aradık durduk.İyi ki cezalandırdın, infaz hakkını yargısız kullanmadan.Aldığım cezanın, koptuğum sevdadan ağır olduğunu sanmıyorum. 

Ona rağmen korktum senden, kendimden, tutkularımdan. Ya senleşmedeydim gittikçe ya kendimden vazgeçmede..Oysa ikimiz, birbirimizi tanıdığımız halimizle sevmiştik.Yarımlardan bütün olur öğretilmişti bizlere. Çeyreklerimizin eklenmesiyle barışıklık benzeşmeye taşıdı bizi. 

Farklılıklarımızı seviyorduk. Farklı olmanın ayırtına varamadık, farkı kaçırdık. Ben o kara kuru kara kızı, hâlâ kollarımın arasında kucakladığımda bırakırsam uçacak sandığım cılız bedeni, o derin bakışları ve bana benzemeyen farklı yanlarını seviyorum. 

Bil ki; çok zor benim için bundan sonrası. Benzeşmekten korkarken bütünleşen yüreklerimizi eşit olarak paylaşacabileceğimizi sanmıyorum! .. 

O güzel yüreğin parçalı ve yaralı bölümünü ben alacağım. 

Diğer yarısında da ebediyen gölge gibi kalacağım. 

Hoşça kal Mavi Meleğim. Kara kuru kız hoşça kal.          

  Şeref ÖZTÜRK (Usta) 



''GİT İSTERSEN CÜZZAM KAP BİR YERLERDEN NASIL TUTKULU OLDUĞUMU GÖRMEK İSTERSEN'' 

CEMAL SÜREYYA', 'Sevgili Mavi Melek; Bil ki çok zor benim için bundan sonrası. Su kadar demiyorum, hava kadar elzemdin yaşamım için. Bütün sorunların benden ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mavi-melek-kara-kuru-karakiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki size', 'bendeki-size-seref-ozturk-usta-6yj0w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yanda dostlarım,bir yanda yakınlarım.

Zıvanadan çıktığım doğrudur; doğrudur bir haftadan fazla zamandır kendime gelemediğim; artık sana çok normal davranmam gerektiği doğrudur. 

Bazı şeyler bizim dışımızda gelişiyor istesek de; istemesek de ikimizi de artık biliyorlar ve tanıyorlar! ..

 Aslında bu açmazımızı,ikimiz daha kolay aşardık.

Kendimizi tanıyoruz öbürlerini de.

Bütün hoyratlığım,gizli kıskançlığımdan,ilerleyen yaşımdan; senin gençliğinden,sefaletimizden...

Dost olamayacağımız gün gibi aşikârdı.''Sevenler düşman olabilir ama asla kardeş olamazlar''  denmiş. *

Biz dostluğu aşmış,fakat aşındırmamıştık. Cehennem sevdalarla yüreğim kavrulsa da,seni kendi cehennemimde yakamazdım. O kadar iyisin ki. 

Bu çaresiz adamın yaşamına umut olur,hayata tutunmasını sağlayabilir diye bu arada bende bir kenarından tutunabileceğim dediğin-baştan belki böyle başladığın, ayrıntıda -bir serüvendi..

Gittikçe seni de içine sürükledi bu girdap.

Hayatın dopdoluydu bu genç yaşında.Tanıman gerektiğinden fazla,bilmen gerektiğinden çok insan tanımıştın., her türden,her yaştan.. Baba gibi sevdiklerin,uğruna can vereceklerin. Onlar senin için hayatlarını verebilirdi belki. Usta, başka bir boyutta yaşıyordu çizgisi vardı her şeyden önce çok çizilmişti, çok da çizik atmıştı hayata dair..Hiç böyle kanatılmamıştı yüreği.

Hiç böyle çaresiz hissetmemişti kendini, ne sana yüreğini açabiliyor, ne de senden bir şey bekliyordu, geriye bir tek Kerem gibi kendi kendine yanması kalıyordu.

Platonik ilişkilerde gizli bir dayatma vardır.. Durumdan vazife çıkarmak olasılığı hep mevcuttur. Bir daha görememe olasılığı hep gündemdeydi, onu görememek düşüncesi ise çıldırtıyordu..

Sezdirmeden işe gidiş gelişlerini izlemeye başlamıştı, görülme ihtimali ise utancı katmerlendiriyordu..Uzaktan izlemenin problemlerinden birisi de,ona benzeyen birinin peşine yanlışlıkla  takılmak ve yanılgıydı.

Zamana bırakmıştık; tartışmanın hararetinin düşmesine, yaranın kabuk bağlamasına, sarf edilenlerin hezeyan olduğuna.

Dostlar barıştırmak mı istiyor, karıştırmak mı.. Doğru zaman,yanlış mekân ayırımı yapmadan.

Büyük bir olgunlukla.'' ''Dünyanın sonu değil..Orada konumumu,kim olduğumu ve ne için bulunduğumu anlayamadım.. Ben seni görmeye,seni bulmaya geldim..Orada kendimi tıpkı senin gibi kaybettim '''' dedin. 

O kadar haklıydın ki! ..Benim en yanlış taraflarımı örtmek için lümpen ağzı küfürlerimi bile izole ettin.. 

Sen dostuna vasıf katarak sana yakışanı yaptın; örttün bir çok şeyi.. Hele hiçbir şeyi bilmemesi gereken insanların karşısında beni sınıflandırarak,ailemi yücelterek, yükü rakı şişesine yıkma başarısı göstererek,beni kurtardın başkalarından..

Senden, hoş göründen,toleransından.. Karakter isteyen hümanizminden,ben kendimi kurtaramadım.bu kadar korunmayı hak etmedim.

Kendime sorduğum sorulardan kurtulamadım.Neden? Neden? Neden? .. Bu tersten ''ezme'' olsaydı onu da hissederdim.Çok kırılmıştın,incinmiş.incitilmiştin.

Gözlerinden o kadar çok şey okudum ki, sen çayını yudumlarken,kendinden emin halinle.

Bir tek nefrete rastlamadım bakışlarında.Hâlâ sevecen ve bir o kadar daha güzeldi gözlerin.

Beni oracıkta milyonlarca kez daha öldürüyordu. Bende ne arayıp bulduğunu bir anlayabilseydim, bu kadar eziklik hissetmeyecektim karşında; biraz daha direnmek isterdim gücüm olsaydı.

İade etmek gayretinden hiç vazgeçmediğin külhanlığımı,hiç eğilmez bükülmez sandığım bu yönüm,tuz buz oldu sayende.Senden önce,senden sonra gibi milâdi anılmalara geldim. Hapishanelerin,Tımarhanelerin, bitirim hanelerin ıslah edemeyeceği bu deli oğlana ne oldu.

Zamanı kötü harcadığım da düşünülebilir.Gönül derdinde olmak yerine,et derdindeki kasap kedisi olmadım hiç.Kirletmeyeceğim pırıl,pırıl sevgilerle ördüğüm dünyamı,kirletmeyeceğim beynimi; bunu sen istesen bile.Hak etmediğim hayaller kurmadım kendi kendime.Sadece sevdim ölürcesine,taparcasına,koparcasına sevdim.

Hiçbir delikanlının veremeyeceği mutluluk reçeteleri birikimlerimde saklı dururken.Kimsenin rüyalarını süslememiştir bir sevgili böyle,seveni rüyasında bile utandıracak bir mahçubiyetle.

Bedensel dürtülerin ihtiyaç molalarında değildik ikimiz de.Sevginin ağır oturaklı,sabırlı ve kaygan zemininde kalmayı,birbirimizden utanmamayı öğrettik herkese..bana en çok sen yardım ettin dürüst kalmamda. Çok kızdırdığında oldu,yaşlı adam,ihtiyar delikanlı sataşmalarınla. bundan da gocunmadım,mahcup olmadım şimdiye kadar hiç. Sevgi ile doldurulmuş,sevgi ile sunulmuş kadehlerden içtim hep; sevgisiz uzatılan ekmekten bir lokma almadım.Bir gün mutlaka sevgi ile dolu bir kucaklaşma taşıyacak bizi okyanuslara.Bulutlara yükseleceksek sıcak sevgi dolu bir öpücük doldurmalı balonumuzu.Kaybolacaksak tüm evreni ardımızda unutarak,mutlak sevgi olmalı bizi bu fırtınanın içine gömüp girdaplarında eriten.Sevginin yüceliğidir bütün günahların üstünü örten; ayıplardan arındıran,pişmanlıkları ortadan kaldıran sevgidir; sevdaların karbon kağıdı ile çizilmişçesine tıpatıp duygularla beslenmesini,birlikte soluk alıp vermek gibi,nabız gibi aynı ritm ile çarpmasını sağlayan.

Ey sevgili! Artık sana dürüstçe anlatmalıyım; çünkü yüzümü saklayamıyorum,ağlıyor göz bebeklerim; içime dökülen çağlayanları gizlemek için başkalarından göz yaşlarımı veresiye vermişim.

Pazar günü geleceğim diyordun.Bir gelebilseydin; bendeki heyecanı bir görebilseydin.Seni de dostlarınla paylaştığın sevgi dolu kadehler mi coşturdu ''geleceğim'' demen için.Yüreğimin telepatik frekansına mı yakalandın bilemedim.''Yine yangınlarda yürek/gönülde hasret hep büyüyerek'' demiştim.Özlediğim günlerde yanımda iken de özlediğimdin.''Ben sizdeki kendimi çok özledim; inceliktir,bir gün arayıp onu bana verin.Ben kenimdeki sizi özledim, kimsesizliğiniz bende kaldı.

''* Cezmi Ersöz; son kitabında böyle anlatmış sayfalar dolusu yazsam da özlemimi daha iyi ifade edemezdim.Bu satırları sana mesaj olarak gönderdim.

Pazar günü geleceğim diyordun...Yazarı bulup kucaklamak geldi içimden.

Pazar günü geleceğim diyordun.Bir gelebilseydin.Neler değişirdi hayatımda kim bilir.Belki sen ''değişsin'' istemezdin.Bir gelebilseydin.Yalnızdım,kendi kendimleydim,kendimde değildim; sen de benim gibiydin,gelmek istiyordun,gelemiyordun.

Mesajın geldi; bütün hayallerimi alt üst eden,kahreden.''Özür dilerim,gelemiyorum.''. Bir gelebilseydin.. Gelebileceğini umut ettiğim için asıl ben özür dilerim,seni senden izin almadan sevdiğim için özür dilerim; ama izinsiz sevmeye devam edeceğim için özür dilemeyeceğim.

Gelememiştin. Pazar günü; sırtımda hamak torbada walkmen.Bedirhan Gökçe''den Ahmet Telli''den şiir kasetlerim,Termosumda çay,bardaklarım şekerim.İstanbul ''da görülmemiş bir sıcak hava,kendimi Osmanlı parkına atıyorum..hamağımı iki ağacın arasına bağlıyorum.Bardaklarımı,kalemi kağıdı poşetten çıkarıyorum.Bardağıma daha ilk çayımı dökmeden, bir tek satır yazamadan sana dair,telefonumda bir mesaj beliriyor..''13:30''da Eyüp''te görüşelim mi? '' Henüz,Pazar günü gelemeyişine makul bir cevap bulamamışken,gerekçelerin görüşmeye hazır olmadığımızı pekâlâ anlatabiliyorken, ben umudu tam kesmişken,şaşkınlıkla,hayretle ve büyük bir heyecanla, hamağı bile toplamadan piknik yapmaya gelen bir aileye tembih ederek, Alibeyköy''den Eyüp''te buluşacağımız yerde olmak üzere yola çıkıyorum.Kafamda cevapsız sorular.İçimde tarifsiz bir heyecan.Artık darılmamak üzere barışacağız diyordum.

Sonra aniden kafamda çakan soruya takılıyorum,kavgalardan sonraki bu barışlardan duyulan heyecanı bir daha yaşayamayacak mıyız diyordum? ..

Oysa ki barışın güzelliğinin tadına varabilmeyi bize sağlayan savaşları neden sevmemeliymişim ki.

Yaşasın seninle yaptığımız kavgalar.Bana,seninle tanıştığımız ilk günün heyecanını tekrar yaşatan kavgamız.

Yaşasın aşk savaşları.Barışın mutlu tadına ulaştıracaksa.barışın keyfi çıkacaksa yaşasın aşk savaşları.

''İncelik gösterip,sizdeki beni /bendeki sizle buluşturduğunuz için/sizi daha çok seviyorum. 

* (. C.Ersöz)', 'Bir yanda dostlarım,bir yanda yakınlarım. Zıvanadan çıktığım doğrudur; doğrudur bir haftadan fazla zamandır kendime gelemediğim; artık sana ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bendeki-size-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğumdan Buruk Bir Anı', 'cocuklugumdan-buruk-bir-ani-munevver-senol-1kkyl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocukluğumdan buruk bir anı

Babamı şanssız bir kazada kaybettik,gene sık,sık hastalanıyorum,annem çalıştığı için,izin alması,sorun oluyor,halbuki pazartesi tahliller yapılacak apandisitten şüpheneliniyor,belkide yatıracaklar,annem pazar gününden beni üsküdar sultantepe de oturan halam nebiyeye,yani nebiş,e,götürdü,

ama şanssızlık işte,eniştemde pazartesi,aynıgün,yurtdışından gelmiyormu anahtarıda yok,geliş saatide belli değil,halam teyzesinin kızı nazlı teyzeye 

durumu anlattı ve beni hastahaneye götürmesini rica etti,oda burun kırın kabul etti,çünki kocası huysuz bir insanmış,ondan izinsiz gidemezmiş,ama,

allah razı olsun genede geldi,tahliller yapılırken yatış muamelelerinide yaptırdı daha fazla kalamıyacağını söyleyip evine döndü,bendaha 13 yaşındayım,annem halama güvendi o nazik teyzeye münşi allaha emanet,

nazik teyze dönüşte halama yatırdılar diyor,hastahanede ben birden sancılanıyorum ve bayılıyorum, anons yapılıyor münevver çevik refakatçisi acil gelsin,ama kimse yokki,hemen ameliyata alıyorlar,tabi apandisitim patlamış,karnımın içine yayılmış,uzun süren ameliyattan sonra gene anons,

yapılıyor kimse yok bir kadın doktora benimde kızım ameliyat oldu boş yatakta var ben ikisinede bakarım diyor,şu anda kim olduğunu bilsem kendisine teşekkür ederdim,annem maltepe tarım koruma fabrikasında çalışıyor,işten çıkıp haydarpaşa numune hastahanesine gelmesi saatleri alıyor,sorduğunda,hastanız ameliyat oldu ama ziyaret saati değil giremezsin diyorlar annem durumunu,anlatsada nafile,annem ağlıyarak hastananin,etrafını dolaşıp camlarda beni arıyor numune hastahanesini bilenler bilir,eski binadır calarıda alçaktır,beni görüyor camı çalıyor bana bakan teyze sen merak etme ben kızımla onada,bakıyorum gözün arkada kalmasın,diyor,annaem ağlayarak,şanssızlığına lanet ederek,eve dönüyor,ama halamada güceniyor,halamda çok üzülüyor nazikteyzenin ona böyle anlatmadığını söylüyor,ama öldürmeyen allah öldürmez doğru bir söz,

ömrün varsa bütün şanssızlığa rağmen yaşıyorsun tıpkı benim gibi,ama,

doktorum her sabah bak nihansın diden ey mestinazımı,söylemezsen seni taburcu etmem diyor utanıyorum, meğer ben narkozdan ayılırken o şarkıyı söyleyerek ayılmışım,ben o,olumsuzluklara,rağmen nekadarda kendisiyle,

barışık bir insanmışım 26.6.2004', 'Çocukluğumdan buruk bir anı Babamı şanssız bir kazada kaybettik,gene sık,sık hastalanıyorum,annem çalıştığı için,izin alması,sorun oluyor,ha...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cocuklugumdan-buruk-bir-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı tanımak seni tanımakmış', 'aski-tanimak-seni-tanimakmis-seref-ozturk-usta-b6nov', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsanları en çok yaşadıkları yirmi kilometre karelik alandaki olaylar ve insanlar etkisi altına alırmış.Sevgiye ait duygular bu dar alanda yeşerirmiş.

Yüzlerce kilometre öteden gelip beni buldu,sarmalına aldı.

Hakkım olmadığı kadar sever oldum.Nasıl,neden,niye oldu diyemeden.

O istemeden benden oldu.Tam küsmüşken yaşama,güzelliklere kör bakar olduğum bir sırada,panjurlarımı açıp dışarıda yaşanacak bir dünyayı sever oldum.

Sevginin iki satır arasına saklanabileceğini öğrenip,satırları sever oldum. Tutuluverdim o iki satıra.Okyanusların ve çöllerin seyyahı oldum. Mesafeler vız geldi,sınır tanımayanlar sınıfına dahil olup sever oldum.

Ne güzelmiş sever olmak.

Yüzünde değişen kimyanı gördüm,Aşk sana yaramıştı.Aşka kimya diyenler yanılmıyordu,çok güzelleşmiştin, gözlerin gülüyor.yanakların kızarmış saçların parlıyordu.Ben aşkın insanda yarattığı ihtilale benzetirdim, sevenin bu devrim gibi değişimini sever oldum.

''Yaşadığım aşktan''dedin söylediğine inanır oldum.

Yazdığım ilk şiirlerimin dizelerinde,seni anlamak,anlatmak istemiştim.

''Gülüşünü sevmişler seni sevemeyenler,bakışlarında saklı hüznü göremeyenler'' diye tarif etmeye çalışmışım. Oysa bu sefer! gözlerinde kuşku vardı,endişe hakimdi,ama bir sevecenlik oturmuştu simâna,sorular vardı gülücüklerinde,sormaya utandığım...

Aslında ruh ikiziydik,sormadan bilebiliyorduk korkularımızın nedenini...

Ben seni mutlu gördükçe sever oldum,seni sevenleri, sevindirenleri kimyanı değiştirenleri..

Ama! endişen,kuşkuların,panik halin beni kopardı olduğum yerden.

Gezegenler arası gezer oldum.Yanımda tam karşımda olmasaydın! 

Öldüğümü sanabilirdim,yaşadığımı sandığım kadar.

Bağışla beni Meleğim,bağışla sevgili kelebeğim.Benim seni sevebime ihtimalim gezegenlerin çarpışabilme ihtımali kadar uzaktı görünüşte.

Senin benden koptuğunu sanacak kadar şaşkındım..

Sevdiğimi söyleyemeyecek kadar mahçubiyetimi saklamamı sever oldum.

Yaşarken sevmeyi bilenler! Sevgiye saygı duymayı öğrendikleri gün; Seven yüreklere sahip olduklarını da öğreneceklerdir... Acılarını sevgililerinden çok sever olacaklardır.İyi ki varsın.

İyi ki seni sevmişim...Aşkı tanımadan ölebilrmişim seni tanımamış olsaydım.', 'İnsanları en çok yaşadıkları yirmi kilometre karelik alandaki olaylar ve insanlar etkisi altına alırmış.Sevgiye ait duygular bu dar alanda y...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aski-tanimak-seni-tanimakmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşümdeki Sevgili', 'dusumdeki-sevgili-dilek-kadioglu-an6cw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eyy! 

Düşümdeki sevgili neredesin? 

Neredeysen gel.. 

Yağmurlarımın gözümle yarıştığı 

Köşe başında mısın 

Yoksa 

Akıntılara yol olan 

Sokak arasında mı? 

Uçsuz bucaksız 

Denizin dalgasında mı? 

Yaralı bir martının kanadında mı? 

Nerede! 

Neredesin düşümdeki sevgili.. 

Rüyalarımdan çık gel! 

Düşünlerimin düşmelerine inen 

Kanatlarımın yorgunluğundan, 

Yıllarımın vurgunluğundan, 

Yazgımın kırgınlığından 

Çık gel.. 

Bir sis perdesi var 

Gözlerim buğulu. 

Bulamadığım yollarımın üstünde 

Kim bilir kaç kez karşılaştık seninle! 

Gözlerimiz kim bilir kaç kez 

Selamlaştı birbiriyle.. 

Gel artık ne olursun! 

Günü birlik sevdalardan yoruldum.. 

Seni bekliyorum 

Düşümdeki sevgili. 

Hayat kısa; 

Gözlerimi yummadan gel, 

Ağlayan gözlerimi güldürmek için, 

Canıma can olmak için, 

Aşka yürekten dolmak için gel! 

Düşümdeki sevgili artık gel..', 'Eyy!  Düşümdeki sevgili neredesin?  Neredeysen gel..  Yağmurlarımın gözümle yarıştığı  Köşe başında mısın  Yoksa  Akıntılara yol olan  Sokak...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kadıoğlu']::text[], 8.5, '{"poet":"Dilek Kadıoğlu","poet_slug":"dilek-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/dusumdeki-sevgili-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demek ki...', 'demek-ki-cem-karadeniz-8efyj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben sana böyle mi aktım? 

Yüreğine kanat gerdim, 

Gözlerine umut saldım,

Ellerine sevgi yaktım...

Oysa cinnet saatlerine inat

Bıkkın sorgulara hapsettin beni.

Benliğime silah çattın

Yüreğime ateş yaktın

Kan doğradın dizelerime.

Demek  gittin

Demek ki dönmeyecek

Demek sevmeyeceksin.

Demek ben seni kovdum

Öyle mi? 

Cey Cey

23 Eylül 2005

Kütahya

22:00', 'Ben sana böyle mi aktım?  Yüreğine kanat gerdim,  Gözlerine umut saldım, Ellerine sevgi yaktım... Oysa cinnet saatlerine inat Bıkkın sorgula...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/demek-ki-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çanaq Işıq,Bir çanaq Barış', 'bir-canaq-isiq-bir-canaq-baris-ahmet-hani-thh6x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şey senin,

Bütün sevdiklerin.

Bu senin haqqındır,

Ve menim sözüm yoxdur.

Menim üçün,

Her gece,

Bir çanaq ışıq doldur,

Qaranlıqda 

Doğulmuş uşaqların sağlığına.

Menim üçün,

Her gece,

Bir çanaq barış doldur,

Etom bombasından

Qorxa qorxa

Böyüyen uşaqların sağlığına.', 'Her şey senin, Bütün sevdiklerin. Bu senin haqqındır, Ve menim sözüm yoxdur. Menim üçün, Her gece, Bir çanaq ışıq doldur, Qaranlıqda  Doğulm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-canaq-isiq-bir-canaq-baris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-serkan-karabulut-8yj90', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayal kırıklıkları

Hep son seferde gelir

Hiç aldırış etmeden

Ansızın,

Sızı bırakıp kanatıp yüreğini.

Ağla 

Yüreğim! 

Ağla

Son kez! ..

Hangisine yanayım ben şimdi; 

Gelip giden zamana mı,

Kaybettiklerime mi? 

Vurgun üstünde vurgun…

Ah be kader,

Gül! 

Gül bir kez olsun! 

Gün batarken,

Hava soğurken.

Her şeyi istemiyorum da tastamam

Sen bir gül

Yeter…', 'Hayal kırıklıkları Hep son seferde gelir Hiç aldırış etmeden Ansızın, Sızı bırakıp kanatıp yüreğini. Ağla  Yüreğim!  Ağla Son kez! .. Hangis...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kader-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Evinizin Gülüyüm', 'ben-evinizin-guluyum-munevver-senol-b3y9y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kıymetimi bilin benim, ben evinizin gülüyüm,

Biraz solmuş sararmış, kokusu bile kalmamış.

Boynu yana yıkılmış, ama ölmemek için direnmiş,

Ama bilin ki, sizin için yaşıyorum ben,

Ben olmasam,kapıyı kim açar,size? 

Işıkları yakmasam, karanlıktan korkarsınız.

Acıkınca, kim doyurur karnınızı? 

Hergün dışarda yenmez.

Eee, komşudan da her gün gelmez.

Ben varken koşun eve siz.

Sizin için yaşıyorum, sizin için varım ben.

Canlarım benim, sizleri ÇOKKK,seviyorum.

Not: Ben büyük bir ameliyat geçirmiştim. Tabi benim yokluğumda dışarıda yemeye alışmışlar, bende bu şiiri yazdım kapıya yapıştırdım, ama bayağı da etkili oldu.', 'Kıymetimi bilin benim, ben evinizin gülüyüm, Biraz solmuş sararmış, kokusu bile kalmamış. Boynu yana yıkılmış, ama ölmemek için direnmiş, Am...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-evinizin-guluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geldim', 'sana-geldim-veli-dalbudak-getd0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dönüşüm yok, bütün yollarım sana,

Gülüşüm yok, bütün ağıtlarım sana,

Bir değil, bin ömür katlanırım sana,

....Geldim bak. Yalniz isen,

..........................kapında KUL olmaya.

Sensiz geçmiyor günlerim, uyusam bile,

Hep seveceğim, ayrılıkdan korksam bile,

Vaz geçmek yok, kefene sarılsam bile,

....Geldim bak. Yalniz isen,

..........................ocağında KÜL olmaya.

...Sana Geldim,

.............Ey benim gönlümün sarayı.

...Lutfedip,

.............içeri alırmısın bu fukarayı.

(Stockholm 2002)', 'Dönüşüm yok, bütün yollarım sana, Gülüşüm yok, bütün ağıtlarım sana, Bir değil, bin ömür katlanırım sana, ....Geldim bak. Yalniz isen, ........', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sana-geldim-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Geldi Vazgeçtim', 'bahar-geldi-vazgectim-zafer-ozturk-k5aqd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahar gelmişti sol yanıma, vazgeçmeliydim kahini olmayı dünyanın… 

Ama ruhu, 

gecenin bir anında, 

kim bilir hangi oyunun büyüsüyle avunmakta olan bir çocuk gördüm 

sokakta, 

annesinin eline asmış bedenini, 

gözlerini kendine benzemeyenlere ayırmış. 

Terk etmeyi düşünüyorum şu sıralar, 

ağaçlarının altından yürümeyi sevdiğim bu kenti… 

Yaşanmamış düşleri gösteren anlarını dondurmak istedim insanlığın bugüne, 

belki başarabilirim diye egemenliğinde umudun hayallerini kırmayı. 

Sonra, 

kırdığım her hayal parçasından bir duvar yapmayı düşündüm 

sözcüklerin ikliminde, 

bir daha kimselere hikayeler anlatılmasın 

ve özenmesin diye kimseler, 

kahramanlara.… 

Bahar geldi karanlık yanıma, vazgeçtim. 

Sonraki aklı olmayı istedim bir ara bir delikanlının; 

sonralarını yeniden düzenlemek için belki hayatının. 

Eski yüzlerinde geçmişinin yeni izlerini renklendireyim dedim. 

Lakin bir güneş gördüm bunları düşündüğüm bir sabahta, 

vazgeçtim. 

Terk etmeyi düşünüyorum şu sıralar, 

ağaçlarının altından yürümeyi sevdiğim bu kenti… 

Gözlerine bakmayı denedim yoğunlaşmış insani bir hüznün, 

böylece bir kapı aralayabilir, 

bir kristale dönüştürebilirdim belki bebeğini, 

hazan mevsiminde üşüyen her bir gözün, 

arındırabilirdim belki ruhları hüzünlerden, 

dünyayı mutlu kılabilirdim böylece. 

Bahar geldi lakin ilk aklıma, vazgeçtim. 

Terk etmeyi düşünüyorum şu sıralar, 

ağaçlarının altından yürümeyi sevdiğim bu kenti… 

‘Terk edersen eğer bir sabah, 

ağaçlarının altından yürümeyi kim sevecek artık, 

bu kentin’ 

dedi bir aklım… 

Bu yüzden kıyılarınızdayım hala sizin, 

annesinin eline asılmış bir çocuk, 

hikayesi anlatılmamış bir kahraman 

adına türkü yakılmamış bir hüzünüm şimdi, 

gözlerinizden kaçan…', 'Bahar gelmişti sol yanıma, vazgeçmeliydim kahini olmayı dünyanın…  Ama ruhu,  gecenin bir anında,  kim bilir hangi oyunun büyüsüyle avunmakt...', ARRAY['Türk Edebiyatı','Şiir','Zafer Öztürk']::text[], 8.5, '{"poet":"Zafer Öztürk","poet_slug":"zafer-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bahar-geldi-vazgectim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunma Ağlarım Anne...', 'dokunma-aglarim-anne-bahtiyar-arslan-b1vbc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben sana mektup yazmıştım, anne 

daha doğrusu yüreğimi kanatmıştım 

ama gönderemedim 

bulaşmasın diye kanım gözlerine, anne... 

hüzün ve yürek kolkolaydı 

bizim oralı renk taşıyorlardı 

ve bizim oralı türkü söylüyorlardı 

dokunma 

ağlarım anne...

alnındaki kara yazgının tutsağı olmuştum

ben kaçtım sen kovaladın 

ürkütmedi mi bu seni anne...

hasret kokan mektup taşırken kuşlar 

kurt''un yüreğinden hohlanan nefesle düştüm anne... 



her defasında yağmurdan kaçıp 

yağmura yakalanıyordu düşlerim 

oysa saçlarıma aklar düşmemişti vurulduğumda

güneş yüzlü bir çocuktum 

yağmurda kavruldum 

ben kavruldum anne

sen ağladın... 

namus, benim gözlerimde bağırıyordu namuzsusa 

emek benim gözlerimde gizliydi 

sevdam, senin yüreğinde anne... 

oysa ba-kı-la-bil-seydi dünyaya 

çocukların kocaman yüreğiyle 

sen ağlamazdın anne... 

susmaların, haykırmak olduğunu bildiğim için 

hep susmayı denedim ben anne... 

ayrılık, sırtımda izini taşıdığım kırbaç izi gibi duruyor 

kayan yıldızlar saracak mı sandın, sarmadı, anne...

yağmur senin yüreğinde bir ıslaklık bırakır anne 

bende ölümün gölgesini 

gölgesinde ağıt yak anne... 

oysa anne, sevmek herkesin harcı değildi 

o sevdiğini sandı 

o sevmedi çekip gitti 

benim yüreğim yandı... 

ben hiç sevmedim, alaca karanlığı anne 

ya aşk vurulur, yada gün ölür koynunda... 

alıp gitmek sevdamı buralardan 

bağırmak senin dudağınla 

ve türküye durmak 

ne güzel duyguymuş anne...

uzatmasın bana ellerini tutmayacağım anne 

çünkü o eller ki yabancıdır artık... 

farzetki ayrıldık senden anne 

farzet ki hiç olduk 

ne eksilir ki sevdalardan, yada ne kalır geriye... 

yarin yanağına bir gül çiz anne 

gözyaşını da bana bırak... 

hüznümü,dağların arkasında kalan bahçeden çalmışım ben anne 

gözlerimdeki yaşı, memendeki sütten 

sevdamı ellerindeki çiziklerden almışım 

geceye doğur beni anne 

sen ağlama... 

unutmak seni anne unutmak 

hasret ve ölümle koyun koyuna yatmak gibi birşeydir... 

hatırlarmısın anne 

''dur çocuk dur demiştin, gitme 

bu ölümüne bir sevdadır 

sevdan ölümdür senin''... 

eylül''ün dilindeki isyan türküsüydüm 

kasım''da söylendim 

mayıs''ta dar ağacına çekildim anne... 

ayrılıklar ne güzelde yakışmış ağıtına, anne 

ne yakışıklı ölmüşüm türkünde 

ne güzelde gömmüşsün beni 

nasılda kıydın yakışıklı oğluna anne... 

artık yüreğindeki telaşı at anne 

ellerindeki kanı sil 

sağ beni anne, düşeyim yüreğinden... 

yağmura bırak beni anne 

''acı sevdanın gözüdür'' demiştin ya 

dokunursan acı çekerim 

dokunursan ağlarım... 

ağlarım anne.. 

bu sevdamı ölümüne yatır 

sen tek başına dua et 

sen dokun bana anne 

sen hiç et... 

dokun bana dokun

dokunursan ağlarım anne...', 'ben sana mektup yazmıştım, anne  daha doğrusu yüreğimi kanatmıştım  ama gönderemedim  bulaşmasın diye kanım gözlerine, anne...  hüzün ve yür...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/dokunma-aglarim-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurda sen', 'yagmurda-sen-hekim-coskun-yr775', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bugün yağmurda sen vardın

ellerin ve yüzün ıslanmış

tatlı bir üşütme tutmuştu seni.,

saçlarından süzülen damlacıkları saydım

bir,iki,üç,beş,yedi,sekiz,yüz

yüzünü yıkayan yağmurdan damlalar

seni daha bi güzel ve daha hoş yapmıştı

sen yoktun ama,

kurgularımda öyle güzeldin ki.

yaşanmış tüm romantik aşkların kıskanacağı

sevgiyle sevdim seni

ve düşlediğim tüm güzelliklerde

var oldun.

belki okurken; bu bizmişiz diyeceksin

bana sorarsan,

sana sinir olacağım biliyorsun.

insanların kaçıştığı yağmurun altında

düşüncelerimde sen

ikimiz yürüyorduk umursamadan

ıslaklığı.

yağmur ve sen çok güzeldi.', 'bugün yağmurda sen vardın ellerin ve yüzün ıslanmış tatlı bir üşütme tutmuştu seni., saçlarından süzülen damlacıkları saydım bir,iki,üç,beş,...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yagmurda-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelliğe Eş', 'guzellige-es-gunduz-aydin-1n1hu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cıvıl cıvıl hayat verdin

Kuş musun sen güzel bebek? 

Ne güzelmiş senin derdin

Düş müsün sen güzel bebek

Çok severim canım diye

Yaradan’dan sen hediye

Dünyadaki güzelliğe

Eş misin sen güzel bebek?', 'Cıvıl cıvıl hayat verdin Kuş musun sen güzel bebek?  Ne güzelmiş senin derdin Düş müsün sen güzel bebek Çok severim canım diye Yaradan’dan s...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guzellige-es-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Olur', 'gun-olur-gunduz-aydin-6x4lx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oğlum hayat damarda

Bir sıçrar da BİN olur

Bayrak ona emanet

Milletime ŞAN olur

Melhem odur her derde

O bulunur her yerde

Bir bakarsın büyür de

Yavuz Sultan HAN olur

Bir tek güzellik kalır

Bu çirkinlik kaybolur

Her şey iyi-hoş olur

Gün olur da GÜN olur

Oğlum-kızım büyür de

İlme-fene CAN olur

Bu cehalet, cehalet

Biter biter SON olur.', 'Oğlum hayat damarda Bir sıçrar da BİN olur Bayrak ona emanet Milletime ŞAN olur Melhem odur her derde O bulunur her yerde Bir bakarsın büyür...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-olur-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Bayrağım', 'al-bayragim-gunduz-aydin-1y62e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Atam canı

Şehit kanı

Sevdim onu

         Al Bayrağım

Bayram günü

Yurdun dünü

Bitmez ünü

         Al Bayrağım

Elde durur

Kalpte odur

Düşmana sur

          Al Bayrağım

Canım verem

Yüzün görem

Senli yaram

          Al Bayrağım', 'Atam canı Şehit kanı Sevdim onu          Al Bayrağım Bayram günü Yurdun dünü Bitmez ünü          Al Bayrağım Elde durur Kalpte odur Düşmana ...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/al-bayragim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesaj', 'mesaj-gunduz-aydin-bnh3u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sabah bir kuş

Pençeremi tıklattı

Muştulu haberlerle

Gönlüme neşe kattı

Çocuklar artık

Çöpleri yere atmıyormuş

Büyükler şimdi

Sevgi ile gülümsüyor

Kaşlarını çatmıyormuş

Yalandan, riyadan, kötülükten

Arınmış dünya

Bu mesaj bana

Minik bir kuştan geldi

Sana olsun çocuğum

Anlarsın ya!', 'Bu sabah bir kuş Pençeremi tıklattı Muştulu haberlerle Gönlüme neşe kattı Çocuklar artık Çöpleri yere atmıyormuş Büyükler şimdi Sevgi ile gü...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mesaj-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-gunduz-aydin-l1zib', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bebeğim hiç ağlamaz

Yemek yemez

Uyumaz

Ben hep ağlarım

Hasta olur,

Üstümü kirletir

Herkesi kendime

Bağlarım...

Yine de annem

Beni çok sever

Gün olur sabrı taşar

Yine sever, hep sever

Hakkını ödemek 

Zor, çok zor annem

Bu bebeğin seni çok

Seviyor, seviyor annem', 'Bebeğim hiç ağlamaz Yemek yemez Uyumaz Ben hep ağlarım Hasta olur, Üstümü kirletir Herkesi kendime Bağlarım... Yine de annem Beni çok sever ...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/annem-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul Ah! Istanbul', 'istanbul-ah-istanbul-mehmet-yasar-a-jsw5w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir yanın sarıyer, boğaz, gülmemeler sallanır

		bir yanın avcılar,Sultanbeyli, gök dolusu hüzün

		bin yağmur damlası 

		bir yanın seksüeller, biseksüeller, transseksüellerde

		bir yanın koşup durur cevizlide

		bir sabah uyanır bakarsın yer gök sis

		bir sabah günlük  güneşlik, uçurtmalar

                                hazerfan ahmet çelebi

		bin kez bikri izale edilen bakir 

		bin kez bir doktor raporuna darp ve cebir izi 

                               diye geçen şehir.

		

                               bin bir surat.', 'bir yanın sarıyer, boğaz, gülmemeler sallanır 		bir yanın avcılar,Sultanbeyli, gök dolusu hüzün 		bin yağmur damlası  		bir yanın seksüeller...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yaşar A']::text[], 8.5, '{"poet":"Mehmet Yaşar A","poet_slug":"mehmet-yasar-a","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istanbul-ah-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Çocuk', 'gul-cocuk-gunduz-aydin-eg6f9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Trafik denilen canavar,

Bir sabah erken kalkmış

Bir çocuğu acımadan

Kollarına almış,

Kuşların çırpınışına

Yüreklerin yanışına

Işıkların sönüşüne

Aldırış eden olmamış

Bir “Gül” düşmüş yere 

Sonra yüreklere

Yerler kırmızıya boyanmış

Şimdi gül çocuk

Bulutların arasında

Kuşlarla birlikte

Uçurtma uçuruyor,

Canavarı besleyenler

Hiç duymamış,

Utanmamış...', 'Trafik denilen canavar, Bir sabah erken kalkmış Bir çocuğu acımadan Kollarına almış, Kuşların çırpınışına Yüreklerin yanışına Işıkların sönü...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gul-cocuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım', 'canim-gunduz-aydin-n23mf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elifcik,

Duyuyor musun? 

Zil çaldı.

Sana geleceğim demiştim

İşte geldim

Seninleyim.

Haydi birlikte

Sevgi üzerine

Şarkılar söyleyelim

Şiirler yazalım

Sen umutlarım

Yarınlarım

Sen

Canım.', 'Elifcik, Duyuyor musun?  Zil çaldı. Sana geleceğim demiştim İşte geldim Seninleyim. Haydi birlikte Sevgi üzerine Şarkılar söyleyelim Şiirler...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/canim-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtacım', 'muhtacim-gunduz-aydin-snc8c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgine

Ninnine

Diline

    Muhtacım anne

Duana

Ben sana

Baksana

     Muhtacım anne

Ben sensiz

Ben cansız

Mecalsiz

      Muhtacım anne', 'Sevgine Ninnine Diline     Muhtacım anne Duana Ben sana Baksana      Muhtacım anne Ben sensiz Ben cansız Mecalsiz       Muhtacım anne...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/muhtacim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış', 'baris-gunduz-aydin-7z7la', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocuklar,

Dersimiz resim

Hep birlikte

Barışın,

Mutluluğun,

Sevginin

Resmini çizelim.

Telafer’de, Kerkük’te

Ağlayan çocukların

Gözyaşlarını silelim.

Dersimiz resim

Fırçamızla,

Savaşın,

Çirkin yüzünü bozalım.

Konumuz barış olsun

Hep birlikte

Tarihi yeniden

Yazalım...', 'Çocuklar, Dersimiz resim Hep birlikte Barışın, Mutluluğun, Sevginin Resmini çizelim. Telafer’de, Kerkük’te Ağlayan çocukların Gözyaşlarını s...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/baris-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk İşte', 'cocuk-i-ste-gunduz-aydin-2em5d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç darılmaz,

Hiç yorulmaz

Hiç kırılmaz

Çocuk işte! 

Kavga bilmez

Kin’li olmaz

Hiç de yılmaz

Çocuk işte! 

Derdi oyun,

Binler sayın

Varın deyin

Çocuk işte!', 'Hiç darılmaz, Hiç yorulmaz Hiç kırılmaz Çocuk işte!  Kavga bilmez Kin’li olmaz Hiç de yılmaz Çocuk işte!  Derdi oyun, Binler sayın Varın dey...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuk-iste-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Öğretmenim', 'sevgili-ogretmenim-gunduz-aydin-m014v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bura ayaz, bura soğuk, bura karanlık...

Günlerdir çalmıyor okulumuzun zili,

Günlerdir esmiyor rüzgârın 

Gelmiyor nefesin ılık ılık...

Ne olur sevgili öğretmenim,

Ne olur gel artık,

Ellerinden tutmak istiyorum,

Dillerinden tatmak istiyorum,

Çağrım sanadır öğretmenim; 

Gel diyorum...

Küçücük yüreğimiz dayanamaz oldu,

İçimize doğdu ayrılık,

Yüce dağlardan çığlar düşüyor,

Tabiatta bir çığlık...

Yalın ayak, yırtık mintan, yaşlı göz,

Ansızın ortalıkta kalakaldık! 

Dayanamıyorum hasretine sevgili öğretmenim,

Ne olur gel artık.

Gözlerine bakmak istiyorum,

Yanağından akmak istiyorum,

Çağrım sanadır öğretmenim:

Gel diyorum...', 'Bura ayaz, bura soğuk, bura karanlık... Günlerdir çalmıyor okulumuzun zili, Günlerdir esmiyor rüzgârın  Gelmiyor nefesin ılık ılık... Ne olu...', ARRAY['Türk Edebiyatı','Şiir','Gündüz Aydın']::text[], 8.5, '{"poet":"Gündüz Aydın","poet_slug":"gunduz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgili-ogretmenim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü Dedikleri', 'dogum-gunu-dedikleri-nuray-acar-xb0t4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğmuşum dediler bir kasım gününde 

Bilmem ki nasıl sevindiler ya çok gülümsediler ya epey ağladılar gizli gizli sevinçten

Babam belki büyük annem konu komşuyu tatlıya boğdu sevincini yedi mahalleye duyurdu.

Bugün doğmuşum yılları saymayın kasım soğuğunda annemin koynunda.

Minik bedenimi korumuş yıllar yılı hiç yargılamadan

Ne haytalığımı ne sorumsuz gecen yıllarımı ne kırdığım anlardaki tavırlarımı

Yaşam seni acıtacak o güzel yüzlü biblolar seni yerden yere vuracak

Olgunluk adına diyip gizliden  ağlayacaksın

Sonra  salonlara çıkıp umursamaz gözükürken fersiz güleceksin 

Sen kaya kadar sağlam değil sen narin bir çiçek bedenindeki yavrum

İyi ki doğdun annen baban tüm sevdiklerin gülümsüyor tüm içtenliği ile sana.

Sen yinede bağışla seni anlamakta zorlananları sen anlat sendeki seni 

Tanıyınca tüm pişmanlıklar dile gelecek bir bir.

Ve içten sıcak  halin yayılacak bir kasım gününe.

Mumları üfleme yansın bitene dek 

Sen de düşün geçen tatlı acı yılları 

İyi ki geldim dediğin ne çok çıkacak 

Sev sevil yaşamın gerçeği bu

Kederi askıya en köşeye poşetle

Ölüm soğukluğundaki düşünceleri

Mazgallara akıt gitsin.

Sen kasımı çevir en içten haline. 

nuray67', 'Doğmuşum dediler bir kasım gününde  Bilmem ki nasıl sevindiler ya çok gülümsediler ya epey ağladılar gizli gizli sevinçten Babam belki büyük...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dogum-gunu-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamal.', 'hamal-ercan-akbay-iu2x5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki büklüm yürüyorum

      İn artık sırtımdan kader

      Yaşamak istiyorum.......', 'İki büklüm yürüyorum       İn artık sırtımdan kader       Yaşamak istiyorum..........', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/hamal-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat Bana', 'anlat-bana-nail-oruc-gezch', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'söyle bana yar! kaç zaman oldu? 

bir noktayken bir doğru olalı,

zaman bir su misali akarken

dişi kırılmış bir çarka döneli.

anlat bana yar! 

saçların hala taze bir bahar kadar canlı mı? 

gözlerin hala bir kez daha bakılası mı? 

ya bakışlarındaki melüllenmeler? 

anlat bana yar! 

ellerinin sıcaklığını,taze hamur yumuşaklığını

gülerken nasıl da çocuklaştığını

iğde kokan bedeninin nasıl da titrediğini yalnız gecelerde.

söyle bana yar1

bir yanın hep eksik kaldı mı? 

uzanıp yaslamak istediğinde başını,

seni bekleyen bir sine bulabildin mi?', 'söyle bana yar! kaç zaman oldu?  bir noktayken bir doğru olalı, zaman bir su misali akarken dişi kırılmış bir çarka döneli. anlat bana yar! ...', ARRAY['Türk Edebiyatı','Şiir','Nail Oruç']::text[], 8.5, '{"poet":"Nail Oruç","poet_slug":"nail-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anlat-bana-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bayramlar', 'eski-bayramlar-nail-oruc-o18qt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her bayram arifesi kapıya dayanışında,

''nerde o eski bayramlar'' demeyesin.

değişen zaman değil! İnsan

eskiyen de bayramlar değil öyleyse

birazdan bayramlıklarını giyecek çocuklar,

küçücük bedenleri coşkuyla dolacak

öpülmedik el,uğramadık sokak

kalmayacak önlerinde.

onlara ayak uydurmaya çalışmayasın.

sen çocuk değilsin ki

ne poşetin var elinde

şeker toplamak için

ne de elini öpmek için bir baban.', 'her bayram arifesi kapıya dayanışında, ''nerde o eski bayramlar'' demeyesin. değişen zaman değil! İnsan eskiyen de bayramlar değil öyleyse bir...', ARRAY['Türk Edebiyatı','Şiir','Nail Oruç']::text[], 8.5, '{"poet":"Nail Oruç","poet_slug":"nail-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eski-bayramlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Not Defteri', 'not-defteri-nail-oruc-vn1kf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hatırlayabildiklerimizdir hayat,

yaşadıklarımız değil.

aralamak için daralmış penceresini hayatımın

bırakıyorum kendimi şehrin sokaklarına.

can atıyorum yeni bir insana merhaba için

bir titizlik bulaşıyor üzerime

bir ipucu arıyorum hayatıma dair

bir çift bakışta bazen de gülüşlerde

bir gence takılıyor gözlerim 

inadına yaşayışlar,damlayken sel oluşlar

ve de o bitmez sandığımız aşklar

usulca geçiyor gözlerimin önünden

ipeksi saçlarını okşuyor ellerim

yeşilin gözlerine bulaştığı bir çocuğun

karşılsız bir sevgi, sıcak bir kucak

hissettiriyor kendini derinden.

ve hürmetle öpüyorum yaşlı bir adamın

baston tutan kökleşmiş ellerini.

keşkelerim,pişmanlıklarım çarptıkça

tuhaf bir hüzne bürünüyor yüzüm.', 'hatırlayabildiklerimizdir hayat, yaşadıklarımız değil. aralamak için daralmış penceresini hayatımın bırakıyorum kendimi şehrin sokaklarına. ...', ARRAY['Türk Edebiyatı','Şiir','Nail Oruç']::text[], 8.5, '{"poet":"Nail Oruç","poet_slug":"nail-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/not-defteri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlı Sevgilim', 'nazli-sevgilim-vedat-okkar-5uugh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Narin yapılı çiçeğim 

Ay bu gece çok güzel 

Zorsun benim için özel 

Limanıma yanaş artık yeter 

Iısıtayım seni kalbimle ben 

Sensin kalbimdeki mutluluk 

Evimdeki sorumluluk 

Vaâd ediyorum sana sonsuzluk 

Güneşin sıcaklığı gibi gir içime 

İçimdeki boşluğa merhem ol derdime 

Luzumsuz dargınlıklar olmasın sevgide 

İnancımız olmalı bu gecede 

Mutluluğumsun şu garip gönlümde.NAZLI SEVGİLİM', 'Narin yapılı çiçeğim  Ay bu gece çok güzel  Zorsun benim için özel  Limanıma yanaş artık yeter  Iısıtayım seni kalbimle ben  Sensin kalbimde...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nazli-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapayalnız İSTANBUL', 'yapayalniz-i-stanbul-vedat-okkar-kec9v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu kış ayının soğukluğunda, 

İstanbulda ben, 

Dolaşırım kaldırımsız yollarda, 

İçimdeki çocuk büyür, 

İçime sığmaz olur artık, 

İstanbulun mavi marmarasında, 

Geceleri mahsum bakışlı insanlar dolaşırlar 

Üzerlerindeki bir kazak, 

Ayakkabıları ıslanmış, 

Yinede gönüllerinde çoşkular, 

Benimle beraber yürürler onlarda istanbuldalar 

Terkedişler yaşanır otogarda, 

Zaman zaman kavuşmalar, 

Her gidişin, mutlu bir dönüşünü bekler otogar. 

Caddeler de rengareng ışıklar, 

Işıklarda dans eden gölgeler, 

Gölgelerden bana yansıyan, 

Bir kaç cümle yada heceler. 

İstanbulun cazibesi, 

Dünyanın tek gözdesi, 

Boğazların muhteşem güzeliği. 

İnsanların çokluğu, garip. 

İçine almış bütün sevgileri yada sevgisizleri, 

Bu kadar çokluk içinde, 

Yinede kendince tek başına, 

Yapayalnız istanbul...', 'Şu kış ayının soğukluğunda,  İstanbulda ben,  Dolaşırım kaldırımsız yollarda,  İçimdeki çocuk büyür,  İçime sığmaz olur artık,  İstanbulun m...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yapayalniz-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakıltaşı', 'cakiltasi-vedat-okkar-stpwy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneş ne güzel batıyor karşıkı tepeden, 

Oysa ben sahilde çakıl taşı topluyorum, 

Her bir çakıl taşını yeni bir dilek ile denize atıyorum, 

Aslında dileklerim hep aynı bazılarıyla ismini sahile yazıyorum. 

Dalgalar geliyor siliyor ismini, 

Hiç bıkmıyorum biraz daha uzağa yazıyorum, 

Bir dalga daha... 

Her bulduğum çakıltaşı bir umut daha veriyor gönlüme biraz da huzur, 

Öyle bir yere yazmalıydım ki ismini hırçın dalgalar silmesin seni, 

Bir anda güneşin batışındaki kırmızılık vurgu ismine, 

İsmin belirde yansıma ile sahile, 

Güneş battı sahilde ismin kalmadı, 

Hava karardı gökyüzünde yıldızlar vardı, 

Göz kırmalarıyla birşeyler anlatmaya çalışıyordular bana, 

Denize attığım çakıltaşlarımıydı yıldızlar yoksa. 

Birden üzerime doğru bir yıldız kaydı gökten, 

Tutmalıydım onu, yakalamalıydım koşasım geldi ona doru birden 

Işığıyla sahili aydınlattı, 

Sahilde tek bir çakıltaşı kalmıştı, 

Kıyamadın onu atmaya, 

Kıyamadım ismini sahile yazmaya bu son çakıltaşıyla. 

İsminin silinmesini istemediğimden, 

Hırçın dalgalara seni terk edemeyişimden, 

Kalbime yazdım seni, 

İçimde hissettim seni, 

Mutlu ol kalbimde sen ebediyen...', 'Güneş ne güzel batıyor karşıkı tepeden,  Oysa ben sahilde çakıl taşı topluyorum,  Her bir çakıl taşını yeni bir dilek ile denize atıyorum,  ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cakiltasi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renkler Çalarım Hayatın Özünden', 'renkler-calarim-hayatin-ozunden-melih-coskun-1gufi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Renkler çalarım hayatın özünden 

Maviyi gökyüzünden 

Yeşili ağaçtan, 

İmgeler çalarım 

Eşi benzeri olmayan 

Nehir gözlerinden. 

Adının geçtiği bütün sayfalardan 

Eksilir beş harf 

Güneş saçlarında arar 

En güzelini yedi renginin 

Yıldızlar çalıp gecenin en karanlık yerinden 

Taç yaparım ipekten saçlarına. 

Tenin cennetin en beyaz yeridir 

Düştüğüm yerin cehennemim olur

Yanarım

Su olup buharlaşırım ateşten dudaklarında... 

Çalarım hürriyeti göçmen kuşların kanadından 

Hediye ederim 

Kendi göğsünün kafesinde 

Tutsak kalan çocuğa 

İşte o gün sevdiğim

Yıkılmış olur bütün beton duvarları esaretin 

El ele yürürüz

Güneşin doğduğu yere 

Dilimizde en çok sevdiğimiz türkülerle...

O gün 

En güzel imgelerimi çalarım 

Şiir gözlerinden

Ve yeniden yazarım adını 

Aşkın... 

2005', 'Renkler çalarım hayatın özünden  Maviyi gökyüzünden  Yeşili ağaçtan,  İmgeler çalarım  Eşi benzeri olmayan  Nehir gözlerinden.  Adının geçti...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/renkler-calarim-hayatin-ozunden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksa Gelme Ben Giderim', 'yoksa-gelme-ben-giderim-ahmet-nural-ozturk-c1il7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yıldırım nasıl düşerse bir çınarın bağrına

Yardan kopmuş taşlar nasıl keserse 

Bir dağ geçitinde eşkiya gibi yolu

İşte öyle gel güzelim 

Yoksa Gelme Ben Giderim', 'Bir yıldırım nasıl düşerse bir çınarın bağrına Yardan kopmuş taşlar nasıl keserse  Bir dağ geçitinde eşkiya gibi yolu İşte öyle gel güzelim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yoksa-gelme-ben-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minicik Bir Ölüm', 'minicik-bir-olum-nail-oruc-zef2k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüzgar tüm nezaketiyle esmeye başlardı

Salkımsöğüt saçlarını omuzlarına saldığında.

Bahar kışa inat bir başka canlanırdı,

Utangaç gözlerine gülümseme serpiştiğinde.

Serviler boynu bükükleri oynardı,

Güneşse bulutların arkasında bir sığıntı

Taşlı yollarda endamı filizlendiğinde.

Rüzgar esmez oldu,esse de hırçın

Bahar feragat etti mevsimlik hakkından.

Güneş hep tan vaktinde kalakaldı

Servilerse iki büklüm.

Uyuduğunu sanmıştım,tatlı tatlı

Hani dokunsan uyanack gibi.

Ölen bir kız çocuğu görmemişsem de önceleri

Ölüm bile masum duruyordu körpe bedeninde.', 'Rüzgar tüm nezaketiyle esmeye başlardı Salkımsöğüt saçlarını omuzlarına saldığında. Bahar kışa inat bir başka canlanırdı, Utangaç gözlerine ...', ARRAY['Türk Edebiyatı','Şiir','Nail Oruç']::text[], 8.5, '{"poet":"Nail Oruç","poet_slug":"nail-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/minicik-bir-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimdeki Sen', 'duslerimdeki-sen-nail-oruc-qaq0v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni öylesine büyüttüm ki düşlerimde

her gün biraz daha ulaşılmaz oldun 

sevdan işledikçe nakışını bir bir bedenime

ardındam sürüklenen bir uyurgezer oldum.

merak ettim hep Tanrı''yı sorgulamak gibi,

bir kere de olsa gözlerinin yakından görünüşünü.

kalbimin bir kuş gibi parpazlanacağını bilsem de,

ellerim saçlarından kayarken adımı söyleyişini.

gözlerini yakından gördüm,hem de defalarca.

adımı da duydum,iyelik ekli kelimelerle seslenişini de

artık dikiş tutmaz oldu yorgun bedenim

her geçen gün biraz daha eridin içimde

bir tokat attın yüzüme,uyandım

sen evinin yolunu tuttun,

bense ulaşılmaz olduğun düşlerimin.', 'seni öylesine büyüttüm ki düşlerimde her gün biraz daha ulaşılmaz oldun  sevdan işledikçe nakışını bir bir bedenime ardındam sürüklenen bir ...', ARRAY['Türk Edebiyatı','Şiir','Nail Oruç']::text[], 8.5, '{"poet":"Nail Oruç","poet_slug":"nail-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/duslerimdeki-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Perdelik Oyun', 'dort-perdelik-oyun-nail-oruc-4dltg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'rengini gökyüzünden alırmış denizler

bir bakarsın masmavi,

bir bakarsın katran karasına bürünmüş

mevsimler de beni çarpar aralıksız

bilimin bilgeliği aciz kalır onlara

dört perdelik bir oyuna başlarım kollarında

oynarım payıma düşen rolleri eksiksiz

bahar...

kırlangıçlar yuva yapar odama,

on sekizlik bir genç olurum

aşık olmak gelir içimden

hiç aşık olmasam da

yaz...

bütün gücüyle durur karşımda

yıldızlar beni gözler gökyüzünde

otuz beş yaş olgunluığuna bürünür bedenim

bir gökyüzüne,bir yeryüzüne bakar dururum

sonbahar...

yapraklar yaşlı annemin avucuna benzer

kemiklerimde hayal kırıklıkları baş gösterir

bir sonraki bahara kadar kaynamayan.

ve mevsimlerden kış...

yeryüzü nazlı bir gelin olur

sürekli yere bakar artık gözlerim,

bir alemden bir aleme göçer dururum.', 'rengini gökyüzünden alırmış denizler bir bakarsın masmavi, bir bakarsın katran karasına bürünmüş mevsimler de beni çarpar aralıksız bilimin ...', ARRAY['Türk Edebiyatı','Şiir','Nail Oruç']::text[], 8.5, '{"poet":"Nail Oruç","poet_slug":"nail-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dort-perdelik-oyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendinle Barış', 'kendinle-baris-fatma-caglayan-8rvdf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden yeşilini değil de 

Görürsün kuru ağacı 

Dolusunu değil de 

Görürsün boş bardağı 

Beyazı değil de 

Neden! Boyarsın karayı 

Neden! 

Neden! 

Gözlerini aç, bak etrafına 

Gitme hep soldan sağa 

Yürü! Biraz da ortada 

Yüreğin kabarmış 

Uzanmış çöllere, ovalara 

Koş! Be kardeşim 

Dağlara, ormanlara… 

Karanlıkları mesken tutma 

Aydınlıkta yolunu şaşırma 

Ufkun açık, daraltma 

Dal! Be kardeşim 

Büyük dünyana… 

Zamanını of la puf la geçirme 

Sevdiklerine, aman ha! Sırt çevirme 

Gel kendinle barış artık 

Şu kısa ömrünü zehir etme…', 'Neden yeşilini değil de  Görürsün kuru ağacı  Dolusunu değil de  Görürsün boş bardağı  Beyazı değil de  Neden! Boyarsın karayı  Neden!  Nede...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kendinle-baris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sensiz Yaşamak', 'seni-sensiz-yasamak-mine-yirmili-8bg7x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ömrüme huzur, 

Yaşantıma mutluluk, 

Geleceğime güven,

Veren adam her an... 

Her işin aceleydi, 

Acelelerin,uyum için prensibimdi. 

ve gidişinde alel aceleydi... 

Ama ne yazık ki şimdi, 

Bekleteceğim seni. 

Gittiğinde; 

Ben kırküçtüm, 

Sen kırksekiz. 

Beş yıl geçti aradan, 

Ben oldum kırksekiz, 

Sen ise orada bensiz. 

Ben evliyim hala; 

Seninle ve sensiz. 

2005 Ekim', 'Ömrüme huzur,  Yaşantıma mutluluk,  Geleceğime güven, Veren adam her an...  Her işin aceleydi,  Acelelerin,uyum için prensibimdi.  ve gidişi...', ARRAY['Türk Edebiyatı','Şiir','Mine Yirmili']::text[], 8.5, '{"poet":"Mine Yirmili","poet_slug":"mine-yirmili","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-sensiz-yasamak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılar-06', 'sarkilar-06-kemal-tahir-ozcan-2zef7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sarmaşık gibi sarıp, seni kalbime koysam,

Yüreğimin sesinde, atan nabzını duysam,

Karışırken kanımız, dalsam derin uykuya,

Gül yüzünü gördüğüm, rüyalarımı saysam.', 'Sarmaşık gibi sarıp, seni kalbime koysam, Yüreğimin sesinde, atan nabzını duysam, Karışırken kanımız, dalsam derin uykuya, Gül yüzünü gördüğ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sarkilar-06-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaşlar olmasa', 'savaslar-olmasa-mine-yirmili-q6bei', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bilmem ki hiç savaş, 

Herkesle olurum arkadaş, 

Kainatlada sırdaş. 

Neden böyleyim bilemem, 

Kavgalara hiiiç mi hiç giremem. 

Düşmanım dahi istese, 

Eğer ihtiyacı var ise, 

Yetiştiririm son nefesinde, 

İçiririm o na su bile. 

Biliyorum; ayıp ediyorum ecdadıma, 

Ve; özür dilerim,Ata''larımdan, 

Özür dilerim yedi ceddimden, 

Özür dilerim herkesten, 

Özür dilerim kendimden. 

Mine YİRMİLİ 2005 YILI', 'Ben bilmem ki hiç savaş,  Herkesle olurum arkadaş,  Kainatlada sırdaş.  Neden böyleyim bilemem,  Kavgalara hiiiç mi hiç giremem.  Düşmanım d...', ARRAY['Türk Edebiyatı','Şiir','Mine Yirmili']::text[], 8.5, '{"poet":"Mine Yirmili","poet_slug":"mine-yirmili","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/savaslar-olmasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğa Özlem', 'cocukluga-ozlem-cigdem-altinoz-21njd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaydıkça düşünceler asude çocukluğa,

Nedense bir lastik top ve oyuncakla.

Bayramlar gelir  akla...

göklere ağan renkli uçurtmalar,

fırıl fırıl dönen bir topaç,

Ya da bez bebeklerle,

Biçim biçim urbalar.

Akar gider göz önünden sıra sıra

Bir avuç kirazın verdiği mutluluk.

Bir bayram sabahı heyecanı

Cebe konan pırıl pırıl paralar.

Yarab, ne güzel şeydir

Bu çocukluk.

Geldikçe aklıma tez geçen yılar

Bir gülümsemedir kaplar yüzümü

Yaramazlıklarım

Heyecanlarım

Ve topladığım

Kucak dolusu papatyalarım.

Dile benden dese 

Tanrı bir gün.

Diyeceğim şu:

VER BANA ÇOCUKLUĞUMU....', 'Kaydıkça düşünceler asude çocukluğa, Nedense bir lastik top ve oyuncakla. Bayramlar gelir  akla... göklere ağan renkli uçurtmalar, fırıl fır...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Altınöz']::text[], 8.5, '{"poet":"Çiğdem Altınöz","poet_slug":"cigdem-altinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cocukluga-ozlem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhram', 'i-hram-kemal-tahir-ozcan-xauu2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuruyan kirpiklerin, göz yaşıyla tanışsın,

Aldırma hıçkırıklar, tıkasın gırtlağını.

Ruhun Arş''a  yükselip, günah teninde yansın,

Tövbeler parçalasın, kalbinin buz dağını.

Müjdeler bir sel gibi, doluyorken içine,

Bedenini  tavafın, eritsin damla damla.

Her damlada melekler, karışsın sevincine,

Yeniden şekil bulsun, giyindiğin ihramla.', 'Kuruyan kirpiklerin, göz yaşıyla tanışsın, Aldırma hıçkırıklar, tıkasın gırtlağını. Ruhun Arş''a  yükselip, günah teninde yansın, Tövbeler pa...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ihram-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hergün', 'hergun-aysun-elagoz-i00hp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hergün 

Biraz daha uzar gölgesi yalnızlığımın..

Biraz daha büyür yaşanmışların acısı...

Şafaklar kızıla,  mevsimler hüzne döner...

Hergün 

Biraz daha yabancılaşır aynadaki yansım...

Dost yüzler,

Albümdeki resimlere bırakıp yerlerini,

Özlenenler diyarına yelken açarlar..

Hırçın rüzgarlar gezinir yüreğimde..

Hergün 

Biraz daha solar bahçemde güller..', 'Hergün  Biraz daha uzar gölgesi yalnızlığımın.. Biraz daha büyür yaşanmışların acısı... Şafaklar kızıla,  mevsimler hüzne döner... Hergün  B...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hergun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Oğul', 'ey-ogul-abdullah-yasar-erdogan-blh3h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'EY  OĞUL

Üzme hiçbir Allah kulunu.

Büyüklenme, bırak gururu.

Var her gün beş vakit duyuru.

Kulağın onda olsun ey oğul! 

Okul bitirmekle, 

Adam olunmaz ey oğul! 

Eğilip bükülmekle,

Onur kırılmaz ey oğul! 

Dünya malına hiç aldanma.

Boş şeyle sakın oyalanma.

Allah’tan başkasına dayanma.

Benliğin onda olsun ey oğul! 

Okul bitirmekle, 

Adam olunmaz ey oğul! 

Eğilip bükülmekle,

Onur kırılmaz ey oğul! 

Abdullah Yaşar Erdoğan', 'EY  OĞUL Üzme hiçbir Allah kulunu. Büyüklenme, bırak gururu. Var her gün beş vakit duyuru. Kulağın onda olsun ey oğul!  Okul bitirmekle,  Ad...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ey-ogul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılar-07', 'sarkilar-07-kemal-tahir-ozcan-mwf9k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aktı yıllar su gibi, kaldı yürekte izi,

Sevgili ne eylesin, zaman bitirdi bizi,

Suçlayamam kimseyi, çekerim kader diye,

Dost bildiğim baharlar, kıskandı sevgimizi', 'Aktı yıllar su gibi, kaldı yürekte izi, Sevgili ne eylesin, zaman bitirdi bizi, Suçlayamam kimseyi, çekerim kader diye, Dost bildiğim baharl...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sarkilar-07-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırdaş Oldum Munzur''dan Toros''a', 'sirdas-oldum-munzur-dan-toros-a-ercan-cengiz-8gmq1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağlarıyla çevrili ülkemde

Newroz günleridir,

Govenddedirler

Yetmişine dayanmış ak saçlılar.

Bir kaç atımlık çay, şeker

Bir kaç sarımlık tütünle giderken

Sırdaş olup geceye,

Orta yere koyarlar yüreklerini

Bıyığı yeni terlemiş delikanlılar.

Kürdün kadını hewal,

Arsızca doğurur

Ve toprağa değen 

Her damla kanla

Asırların iz düşümünü bulur

Ülke ülke

Toprağın ezgisinde

Seyit Rıza''nın özlemi

Kenetleşir...

Çukurova''da serpiliyorsa toprağa

Toros''tan Munzur''a

Uzunca bir yolculuktur

Ata külleri kavuşur

Biribirine

Dicle''ye, Fırat''a, Kızılırmak''a...

Filize durur

Nehir yataklarında

Ve hewal''in sıcaklığında

Ayrışıyorsa

Munzur Çayı''na

Munzur welattir hewal

Karadeniz dağlarından 

Toros içlerine

Çivi gibi de saplanır 

Metropolün köşe taşına...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)', 'Dağlarıyla çevrili ülkemde Newroz günleridir, Govenddedirler Yetmişine dayanmış ak saçlılar. Bir kaç atımlık çay, şeker Bir kaç sarımlık tüt...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sirdas-oldum-munzur-dan-toros-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-arif-baltaci-u9cqs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dört kitabın içinde aradım durdum

Bulamadım bu aşkın kanununu ben 

Zalim sevdan ile yandım tutuştum

Göremedin bu aşkın mağdurunu sen

Eyyüpten Yunustan dersimi aldım 

Issız sokaklarda hep yalnız kaldım

Aşkı arar iken ben seni buldum

Kıramadın bu garip gururunu sen

Ne yeminler ettim, aman vermedin

Seni sevdiğimi hiç fark etmedin

Beni uçuruma elinle ittin

Paramparça ettin onurumu sen

Yalnızlığı yaşattın, kıydın hep bana 

Bir an bile dönmedin bakıp arkana

Merhamet diledim yalvardım sana 

Dindirmedin gönlümün yağmurunu sen…

01.11.2005

Saat 01.25

İstanbul / Üsküdar', 'Dört kitabın içinde aradım durdum Bulamadım bu aşkın kanununu ben  Zalim sevdan ile yandım tutuştum Göremedin bu aşkın mağdurunu sen Eyyüpte...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-ve-ben-139-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hükümsüz İlanı', 'hukumsuz-i-lani-aysun-elagoz-1h34k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllardır,

Nereye saklayacağımı

bilemediğim,

sevgili mutluluğumu

Kaybettim..

Hükümsüzdür...', 'Yıllardır, Nereye saklayacağımı bilemediğim, sevgili mutluluğumu Kaybettim.. Hükümsüzdür......', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hukumsuz-ilani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahiplenemezsin', 'sahiplenemezsin-suheyl-turkoglu-bq3vi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Minicik şeylerden çıkar

Yayılır

Ruhunu sarar

Büyür

Dünyanı kaplar

Mutluluk.

Birileri

Üfürmeye görsün,

Saman alevi gibi

Söner

Ortalık

Zından olur.

Benim diyemezsin

Keyfine kalmış,

İsterse gelir,

İsterse gider.

Senin olmaz

Mutluluk

Sahiplenemezsin.', 'Minicik şeylerden çıkar Yayılır Ruhunu sarar Büyür Dünyanı kaplar Mutluluk. Birileri Üfürmeye görsün, Saman alevi gibi Söner Ortalık Zından ...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sahiplenemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümsersin...', 'gulumsersin-hasan-esat-heptunali-qcqer', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sözün bittiği andır...

gün batımında 

erguvan bir sahnede izlemek martıları...

hafifler bedenin

hele de 

kondu mu kadehteki yudumlar dudağına 

damla damla...

sonrası....

dalga dalga...

yüzünde bir tebessüm...

süzülürsün dinginliğe...

pancar motorların yırtan sesi

sessizliği...

rahatsız etmez seni

gülümsersin...

çeşme  01:30         01/11/2005

uyuyor olmalılar....ama EYLÜL’e 

güven olmaz bu saatlerde....... :)', 'sözün bittiği andır... gün batımında  erguvan bir sahnede izlemek martıları... hafifler bedenin hele de  kondu mu kadehteki yudumlar dudağın...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gulumsersin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengim, Şeftalinin Çekirdeğinde', 'rengim-seftalinin-cekirdeginde-ercan-cengiz-yicut', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zindanlarından dağlara doğru

Bir başka mevsim olurum

Dağlarından zindanlarına...

Yaşam tutkusuna örtünür damarım

Yükselen dumana bakmaksızın

Güneşin gülümsemesiyle, 

Yeniden çıkıp

O küllenmiş toprağın içinden 

Filize dururum.

Sevisi ölesiye bağlı,

Sevdasında güneşin sevileri,

Bir kardelen, nasıl ki verir rengini

Meydan okurcasına

Güneş,

Nasıl tat katarsa 

Rengine,

Tadına,

Şeftalinin, çekirdeğine değin,

Bu kara toprağın ezgisi de olsa 

Renklenir, dillenir...

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)', 'Zindanlarından dağlara doğru Bir başka mevsim olurum Dağlarından zindanlarına... Yaşam tutkusuna örtünür damarım Yükselen dumana bakmaksızın...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/rengim-seftalinin-cekirdeginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yüzlü Canavar.', 'i-ki-yuzlu-canavar-suheyl-turkoglu-n9q7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne oyunlar oynandı

Türkiye üstüne.

Tek dişi kalmış

Canavarın

Her zaman

İki maskesi vardı.

Bir yüzü solcu

Diğeri sağcı,

Birbirlerini öldürdüler

Üniversitelerde

Sınıf arkadaşları.

Ne uğruna? 

Kendiler de bilmiyorlardı.

Vatan aşkıydı,

Öyle söyleniyordu.

Ülkede yangın,

Sonra ihtilal.

Zafer canavarındı,

Sessizce gülüyordu.

Alevi, sünni maskeleri

Kullanıldığında

Müslümanlar

Birbirini öldürüyordu.

İki taraf

Aynı din adına

Savaşıyordu.

Kan davası oluştukça

Halk bölünüyor,

Tek dişli canavar

Sinsice gülüyordu.

Laik, anti laik

Maskeleriyle

Çıktı ortaya

Birdenbire,

Amaçları

Madımak Otelinde

Sıkıştı kaldı,

Taraftar bulamadı.

Türk, Kürt meselesi

Fazla tutmadı,

Vatanseverlikle

Terör arasında

Eriyip gitti.

Türk''le Kürt

Komşu akraba,

Canciğer,

Oyuna gelip

Birbirini vurmadı.

Kimlik sorunu deyip

Maskeleri çoğalttı canavar

Türkiye''de yaşayan

Her ırka

Bedava dağıttı.

Hiç biri almadı,

İttiler

Ellerinin tersiyle

Bütünlük adına,

Bu da tutmadı.

Küçüldü sandık

Canavarı

Başı ezilecek

Böcek kadar,

Ders aldık

Acı tecrübelerden.

Bilemediğimiz

İki maskeyle geldi.

Biri ekonomiyi

Diğeri adaleti

Allak bullak ediyor.', 'Ne oyunlar oynandı Türkiye üstüne. Tek dişi kalmış Canavarın Her zaman İki maskesi vardı. Bir yüzü solcu Diğeri sağcı, Birbirlerini öldürdül...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/iki-yuzlu-canavar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fatih''in Kiracısı', 'fatih-in-kiracisi-suleyman-tunc-qtudl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana bir şeyler oluyor! 

İçim dışım sorguda.

Kafamda cevapsız binlerce soru.

İlk kez duygulanıyorum bu akşam.

İlk kez hissediyorum çevremde olan biteni.

Ben beni arıyorum küçük bedenimde.

Kimim ben? ...Neyim? ...Nereliyim? ...Adım ne? 

İlk kez fark ediyorum gökyüzünün karanlığını.

Yıldızların içten ve samimi olduklarını.

İlk kez bu kadar zevk veriyor bana ezan sesleri.

Şimdi gözlerimin önünde,...

Capcanlı,...

Koskoca İstanbul ve minareleri.

Ve ilk kez korkuyorum yalnızlıktan bu kadar.

Ama nafile! 

İşte yine başbaşayız,...

Gece,...karanlık,...korku ve ben.

Yani tinerci çocuk.

Birer birer yanmaya başladılar bile evlerin ışıkları.

Herkes kendi yuvasında.

Çocuklar şen şakrak, mutlu mu mutlu.

Nasıl olmasınlar ki! 

Hepsinin baş ucunda anası, babası, oyuncakları.

Bense evsiz, öksüz ve yapayalnız,

Surların kovuğunda Fatih''in Kiracısı! 

Bir şeyler oluyor! 

Daha düne kadar çöplüklerde yalın ayak,...

Cam kırıklarına meydan okuyan bana.

Hakim olamıyorum göz yaşlarıma.

Yanaklarım bataklığı andırıyor ağlamaktan...

Elimde olmadan.

Geçen gün zabıtaların zehirlediği,

Köpeğin yavruları bile bunun farkında.

Karşıma geçmişler yüzüme bakışıyorlar mıyıl mıyıl.

Vızıktayarak.

Koynuma sokulmuyorlar,...

Parmaklarımı emmiyorlar bu gece,

Ana memesi niyetine.

Sahi! ...benim de bir anam olmalı.

Yüzünü görmediğim, sesini duymadığım,...

Elini tutamadığım...

Beni cami avlusuna koyan,...

Göğsünden bir damla dahi sütü nasip olmayan.

''''Kahrolası''''diyemediğim ANAM! ...

Ölmüş müdür, sağ mıdır şimdilerde kimbilir...

Çıkıp geliverse, duruverse karşımda.

''''Hayalindeki anan benim yavrum''''deyiverse olmaz mı.

Öpsem, ellerini tükenene dek.

Koklasam varlığını doyasıya.

Kabe kokusu gibi.

Durmaksızın, bir daha,...bir daha,...bir daha.

Sarılsam boynuna,...

Hiç mi hiç bırakmamacasına.

Fırlatmaz mıyım o zaman elimdeki şişeyi.

Ateşlemez miyim oracıkta başımın altındaki kağıtları,

Ana dizi gibi yastık dururken.

Çok mu istiyorum acaba Ulu Rabbim! 

O söylese ben sussam.

Fazla değil sadece bir gece,...tinersiz,...

Dizinde ninnileriyle uyusam.', 'Bana bir şeyler oluyor!  İçim dışım sorguda. Kafamda cevapsız binlerce soru. İlk kez duygulanıyorum bu akşam. İlk kez hissediyorum çevremde ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Tunç']::text[], 8.5, '{"poet":"Süleyman Tunç","poet_slug":"suleyman-tunc","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/fatih-in-kiracisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yozgatlı Hasan', 'yozgatli-hasan-suleyman-tunc-sx7hq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toprağın oğluydu o.

Ana toprağının değil, vatan toprağının! 

Dedem Korkut öyküleriyle uyutmuştu anası.

Azman nehirleri iyi tanırdı.

Yol düsturu olmuştu Şeyh Edebali''nin sözleri.

Kartalların buluştuğu sarp kayalıklarda

Geçmişti çocukluğu.

İri kıyımdı.

Mustafa Kemal''e akrandı üç aşağı-beş yukarı.

Aslen Yozgatlı''ydı.

İlk kez görüyordu denizi...

Uzaktan.

Çanakkale sırtlarında mevzi kazarken,

Yozgatlı Hasan.

Mart soğuğu vardı havada.

Gök toprak rengiydi.

Yer ebem kuşağını andırıyordu sanki.

...Toz,...duman,...ve kan! 

Parfüm kokuları değildi sahilden

Çevreye yayılan.

Gemi toplarının barut kokularıydı bunlar.

Martılar bile görev almıştı.

Açları doyurmak için.

Balık taşıyorlardı gagalarında,

Mevziye! 

Karslı Ahmet''e,...

Edirneli Hüseyin''e,...

Diyarbekirli İbrahim''e.

Yorgundu.

Bitkindi.

Düşünceliydi Mehmetler.

Tam o an:

''''Ben sizlere ölmeyi emrediyorum'''' dedi.

Büyük kumandan.

Binlerce ALLAH sesi,

Eh! ...

Yerinde durur mu Hasan.

Ancak onbeşinci kurşun yıkabildi,

O koca devi.

Ey Türk torunu Türk! 

Bundan böyle buralara kimse girmesin.

Burası Cumhuriyetin doğduğu yer,

Burası Çanakkale! 

Burası Yozgatlı Hasan''ın evi!', 'Toprağın oğluydu o. Ana toprağının değil, vatan toprağının!  Dedem Korkut öyküleriyle uyutmuştu anası. Azman nehirleri iyi tanırdı. Yol düst...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Tunç']::text[], 8.5, '{"poet":"Süleyman Tunç","poet_slug":"suleyman-tunc","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yozgatli-hasan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünen Biri', 'seni-dusunen-biri-ayse-birgul-yilmaz-m9oh0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninle yaşadıklarım için pişman değilim.

Bilmek istersen.

Aynı adreste ve o küçük bahçeli evdeyim

Gelmek istersen.

Yüreğindeki seste bıraktığın kafesteyim

Görmek istersen. 

Düşünme hiç hala yolunu beklemekteyim

Dönmek istersen.

Anılar çıkmaz sokak anılar bir salıncak

Yarısı boş bir yatak masada boş bir tabak

Yalnızlık köşe bucak hasretin kör bir bıçak

En iyi ilaç zaman belki acımı uyuşturacak

Tam ortasından ayrılan kırık kalpler misali

Tam ortasından yırtılıp kalan resimler gibi

Yaralı suskun sancılı unutulmuş yerdeyim

Zaman perdesi hayal gölgesi umutlar eski

Hep acaba neden hep kim bilir hep belki 

Beklendiğini ve sevildiğini bilmeyeceksin

Seni anlatan seni yaşatan şiirler yazacağım

Yokluğuna çaresizliğime belki alışacağım

Sen bilmesen de ben hayatında olacağım

Sen bilmesen de ben hep seni düşünen biri

Olarak kalacağım..', 'Seninle yaşadıklarım için pişman değilim. Bilmek istersen. Aynı adreste ve o küçük bahçeli evdeyim Gelmek istersen. Yüreğindeki seste bırakt...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-dusunen-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Hikaye', 'eski-bir-hikaye-ayse-birgul-yilmaz-ozpyq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerelerdeydin bugüne kadar

Geç kalmış olsan da artık benimsin 

Sensiz geçen günler içimi yakar

Eski bir hikayeden çıkmış gibisin

Senden önce darmadağınıktım

Yalnızlık köşelerinde..

Kendimle yaşamaktan bıktım

En umutsuz anımda karşıma çıktın

Onarılmaz zararlarım var

Göz göze gelmeye korktuğum

Pes ettiğim ısrarlarım kadar

Sonlar arasında kaybolmuştum

Aşırı duygusallığımın getireceği

Sancıları biliyor ve seviyorum

Seni bulduğuma seviniyorum

Bir kez daha aşkı göze alıyorum

Bütün tabularımı yıkmış gibisin

Eski bir hikayeden çıkmış gibisin', 'Nerelerdeydin bugüne kadar Geç kalmış olsan da artık benimsin  Sensiz geçen günler içimi yakar Eski bir hikayeden çıkmış gibisin Senden önce...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eski-bir-hikaye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız Aşkların Kadınıyım', 'i-mkansiz-asklarin-kadiniyim-ayse-birgul-yilmaz-n60d7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karar verdim artık hayatından

Çekilip gidiyorum, gidiyorum

Acıyorum, acı çekiyorum

Ben imkansız aşkları seviyorum

Kalbimi böyle savunuyorum

Belki de böyle avunuyorum

İmkansız aşkların kadınıyım 

İmkansız aşklara kapılıyorum

Ben aşkın kanayan yanıyım

Canımı yaralayan ve acıtan

İçimde yer eden yarım kalan

Hep gitmelere tutunuyorum', 'Karar verdim artık hayatından Çekilip gidiyorum, gidiyorum Acıyorum, acı çekiyorum Ben imkansız aşkları seviyorum Kalbimi böyle savunuyorum ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/imkansiz-asklarin-kadiniyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duracağı Yeri Bilirdi', 'duracagi-yeri-bilirdi-ercan-cengiz-7nckw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O bir palamuttu, rengi

Benim gözlerimin rengi gibi

Kahverengi, 

Ama mavi içerdi

Damarlarına kadar inen güneşin

Kuşların kanatlarından 

Getirdiği maviyi...

Bir daha çaldılar, 

Karanlıklar adına

Uçaklarıyla üzerine bıraktıkları 

Rengi beyaz bir tozla hem de

Koyu yeşil meşeyi

Kömür karasına çevirdiler...

Dumanın yükselişinde asırların pası

Zalimin kini,

Kiri yüklü

Bir kibritle çalınırdı gökyüzünün rengi.

Gövdesi kavrulan meşe ki

Yaz - kış yeşil duran çamdan farklı 

Yüklenmez mi damarına? ...

Ve uzun bir yolculuğun ardından

Derin derin soluklanırken,

Yapışırdı tenine öfkenin zinciri...

Üzerine serpilen ak bir tozdan sonra

Çatırdayan dalında yükselirken kızılca alev

Palamutta meşenin kendi

Her rüzgar vuruşunda 

Dalından düşerken

Duracağı yeri bilirdi

Gamsız, korkusuz

Bırakırken kendini toprağa

Ve güneşin renklerine

Koynundaki ezgilerle

Sıcak bir merhabada

Filize durmaya...

''Kürt burada meftundur'' dediler ya

Ora Ararat''ın zirvesiydi

Güneşin ülkeye gülüşünden

Guruba...

Çığırlar açılırdı...

Küllerinin üzerinden.

(Kaynak: Ezgilerde Kaldı Yüreğim 1. Kitap)', 'O bir palamuttu, rengi Benim gözlerimin rengi gibi Kahverengi,  Ama mavi içerdi Damarlarına kadar inen güneşin Kuşların kanatlarından  Getir...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/duracagi-yeri-bilirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.İçimdeki SEN', 'i-cimdeki-sen-fatma-caglayan-42m58', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni bekliyorum! 

Sabırla 

Senelerce 

Seni tanımıyorum! 

Ama 

Sen varsın 

Kalbimde, iliklerimde 

Seni düşlerken, seni yaşarken, burnum sızlar 

Hasretinle kıvrılırım olduğum yerde 

Yerimden kımıldayamam 

Hıçkırıklar dizilir boğazıma 

Nefes alamam 

Boğulurum gözyaşlarıma 

Kendimi kurtaramam 

Sen! Allah’ın bahşettiği güzel varlık 

Seni kucaklarım 

Öperim 

Koklarım 

İçimdeki seni 

Senelerdir yaşarım 

Sana, an be an, uzaklardan bakıyorum 

Sesleniyorum özlemle 

İçime çekiyorum seni 

Sen varsın 

Seni tanımıyorum 

Sen! Var ya sen! 

Canımsın 

Hep seninle yaşıyorum 

Her gün, belki diyorum; 

”—Bak geldim” diyecek 

”—Ben yani sen 

yaşamın, hasretin, nurun geldi” 

Parlatacak gözlerimi 

Dindirecek hasretimi', 'Seni bekliyorum!  Sabırla  Senelerce  Seni tanımıyorum!  Ama  Sen varsın  Kalbimde, iliklerimde  Seni düşlerken, seni yaşarken, burnum sızla...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/icimdeki-sen-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı Zulüm', 'ask-i-zulum-asli-ozer-2bs84', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bir aşk acısıyım; 

Yüreğini yakar,

İçini acıtır,

Ağlatırım,

Çok yanarsın.

Aklından ölüm geçer,

Zulüm geçer,

Meşk olmaz.

Ben bir hatayım,

Üzüntüyüm,

Acıttığım için 

Üzgün değilim.

2004-Samsun', 'Ben bir aşk acısıyım;  Yüreğini yakar, İçini acıtır, Ağlatırım, Çok yanarsın. Aklından ölüm geçer, Zulüm geçer, Meşk olmaz. Ben bir hatayım,...', ARRAY['Türk Edebiyatı','Şiir','Aslı Özer']::text[], 8.5, '{"poet":"Aslı Özer","poet_slug":"asli-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-i-zulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşçu', 'kuscu-asli-ozer-mrhp0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karabenizli,kuşüzümü kılıklı

Dağ kuşlarına bakıp

Aldanma sakın.

Onlar da uzun zamandır,

Aç ve susuz uçuyorlar.

Dağlara varmayalı çok oldu,

Uzun servilerin dallarında

Konaklamayalı da.

Yoktun o zamanlarda

Oralarda...

Olsaydın; 

Daha çok uzun seneler

Kanat yaralarını saracak,

Pek çok uçamayanın

Uçmasına vesile olacaktın.

5 Mayıs 2005', 'Karabenizli,kuşüzümü kılıklı Dağ kuşlarına bakıp Aldanma sakın. Onlar da uzun zamandır, Aç ve susuz uçuyorlar. Dağlara varmayalı çok oldu, U...', ARRAY['Türk Edebiyatı','Şiir','Aslı Özer']::text[], 8.5, '{"poet":"Aslı Özer","poet_slug":"asli-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kuscu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum', 'ariyorum-canan-kosmaz-xur4j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arıyorum

Arıyorum Allahım gerçekleri arıyorum,

Yalan, fesat, hilesiz bir dünya,

Kavgasız, savaşsız, kötülüksüz,

Tertemiz bir hayat arıyorum.

Birini gerçekten çok seveni,

Mutluluk için çaba sarfedeni,

Kötülük değil iyilik edeni,

Arıyorum artık ben gerçekleri.

Parayı değil insanlığı bileni,

Mala değil sevgiye gideni,

Herkese yardım edeni,

Arıyorum hala bulurum belki.

Dostlarının hakkında iyi düşüneni,

Kimsenin dedikodusunu etmeyeni,

Gönlünde sevgi besleyeni,

Arıyorum ben insanlık bileni.

Büyüklerine içten hürmet edeni,

Küçüklerini candan seveni,

Hiç fesatlık düşünmeyeni,

Arıyorum yok mu öyle birileri.

Mutluluk sevgi içinde yaşamak,

İyilik, temizlik, güleryüzlü olmak,

Bütün insanlara iyi davranmak,

Arıyorum düşümdeki dünyayı.', 'Arıyorum Arıyorum Allahım gerçekleri arıyorum, Yalan, fesat, hilesiz bir dünya, Kavgasız, savaşsız, kötülüksüz, Tertemiz bir hayat arıyorum....', ARRAY['Türk Edebiyatı','Şiir','Canan Kosmaz']::text[], 8.5, '{"poet":"Canan Kosmaz","poet_slug":"canan-kosmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ariyorum-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül beyaz çiçek', 'gul-beyaz-cicek-elazigli-mustafa-kaya-7lym4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen beni değil,

seni sevişimi seviyorsun

dediğin günden beri

aklıma seni getiriyorum.

gözyaşlarını

üşümelerini 

yağmura bıraktığın saçlarını

gülbeyaz çiçeklerini 

şafakla ayak seslerini

bir melek olup 

beni uyandırışlarını

kahveni yalnız içmeyişini

çayı ne çok sevdiğimi düşünmeni

her sofradaki yerimi

eline değen elimi hissedişini

her nereye gittiysen

beni de nasıl taşıdığını

seni şaşırtıp 

kah duygularını doruklara

kah duru sulara

bıraktığımı

aradığın sevgiyi bende buluşunu

ve aradığım 

sevgilinin sen oluşundan 

nasıl mutlu olduğunu

kalbini sadece bana açışını

sabırsızlıklarını

beni bekleyen güçlü iradeni

kimseye tahammülün olmadığı

bağışlamaz kıskançlıklarını

avuçlarımın içini öpüşünü

aklıma getiriyorum

öyle güzel sevişin var ki

sen benim

dünya ve ahıret güzelimsin..

Mustafa kaya

01.11.2005 / Çengelköy

www.mustafakaya.net', 'sen beni değil, seni sevişimi seviyorsun dediğin günden beri aklıma seni getiriyorum. gözyaşlarını üşümelerini  yağmura bıraktığın saçlarını...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gul-beyaz-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet - 5', 'gurbet-5-elazigli-mustafa-kaya-jymch', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir nehre karıştı düşlerim

sevinçlerime prangalar vuruldu

ve her güne

ölüm gibi başlıyorum

soğuk yüzlü sokaklarda

bir başka akıyor 

gurbetin suları

gözyaşıyla dolan 

bir başka oluyor geceleri

beni esir alan

hakikatleri ağulayan

ve,

gökyüzümü çalan

yüreklerimizi yitiren

şehirleri taş gurbet

kurtulacağım elbet

kurtulacağım senden…

Mustafa kaya

Üsküdar / 01.11.2005

www.mustafakaya.net', 'bir nehre karıştı düşlerim sevinçlerime prangalar vuruldu ve her güne ölüm gibi başlıyorum soğuk yüzlü sokaklarda bir başka akıyor  gurbetin...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gurbet-5-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HaYaL Mi?', 'hayal-mi-canan-kosmaz-p9eni', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'HaYaL Mi? 

Seninle yasadiklarim hayalimli Birtanem 

O güzel sözlerin yoksa her biri Masalmi 

Sevgiyi sen bana tatirdin yeniden 

Hayatin yasamaya deger oldugunu bildim 

Herseye varim simdi seninle 

Bir Ömür boyu yasayalim göz göze 

Ayrilik olmasin Canim bizim Sevgimizde 

ne engel cikarsa ciksin Önümüze 

Basladik birekere Hayal olsa bile 

Uyandirma beni Biratenem ne olur 

Yasamak istiyorum doyasiya Aski 

Seninle sadece baska kimse olmasin 

Hayatimi sana verdim baskasi almasin 

Söyle simdi bana ne olur dogruyu 

Hayalmi yasadiklarimiz hayalmi.......', 'HaYaL Mi?  Seninle yasadiklarim hayalimli Birtanem  O güzel sözlerin yoksa her biri Masalmi  Sevgiyi sen bana tatirdin yeniden  Hayatin yasa...', ARRAY['Türk Edebiyatı','Şiir','Canan Kosmaz']::text[], 8.5, '{"poet":"Canan Kosmaz","poet_slug":"canan-kosmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayal-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BiTTi', 'bitti-canan-kosmaz-c6nn2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BiTTi

Günes artik dogmuyor, 

Agaclar hic yesermiyor, 

Kuslar artik ötmüyor, 

Bitti gülüm hersey bitti. 

Gülmüyor artik benim yüzüm, 

Gözlerimden yasta akmiyor, 

Konusamiyorum Sevgillim, 

Bitti artik hersey bitti. 

Gözlerim yavas yavas kapaniyor, 

Bedenimde hic derman kalmiyor, 

Nefes alisim artik zorlaniyor, 

Bitti artik hersey bitti. 

Seni artik göremiyorum canim, 

Sevgini hissedemiyorum birtanem, 

Güzel yüzüne bakamiyorum, 

Bitti ömrüm ben gidiyorum...', 'BiTTi Günes artik dogmuyor,  Agaclar hic yesermiyor,  Kuslar artik ötmüyor,  Bitti gülüm hersey bitti.  Gülmüyor artik benim yüzüm,  Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Canan Kosmaz']::text[], 8.5, '{"poet":"Canan Kosmaz","poet_slug":"canan-kosmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bitti-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BIRaKIN', 'birakin-canan-kosmaz-f6662', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde bir yara sanki acıyor, 

Gönlümde bir ateş sanki yanıyor, 

Kalbimde hasretin hiç çekilmiyor, 

Bırakın gideyim beni bekliyor. 

Ellerim tutmuyor o yanımda yok, 

Gözlerim görmüyor ışığım sönük, 

Dizlerim tutmuyor derman kalmamış, 

Bırakın gideyim beni çağırıyor. 

Sesim çıkmıyor ki nefesim bitmiş, 

Bedenim çaresiz yatağa düşmüş, 

Son kelimem bile hep onu sormuş, 

Bırakın gideyim ne hale düşmüş...', 'İçimde bir yara sanki acıyor,  Gönlümde bir ateş sanki yanıyor,  Kalbimde hasretin hiç çekilmiyor,  Bırakın gideyim beni bekliyor.  Ellerim ...', ARRAY['Türk Edebiyatı','Şiir','Canan Kosmaz']::text[], 8.5, '{"poet":"Canan Kosmaz","poet_slug":"canan-kosmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birakin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çevre Babam ve Ben', 'cevre-babam-ve-ben-suleyman-tunc-yfsc6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Babam çocukken,

Bir başka güzelmiş doğa.

Ağaçlar, çiçekler, hava su ve toprak.

Akın akın göçmen kuşlar gelirlermiş buraya.

İlk gelen hacı leylek olurmuş.

Öncü lider! 

Kuşların hocası.

Çünkü yuvası hazır, mekanı belli,

Sarhoş İbram''ın bacası.

     Şimdi Hacı Leylek yok! 

Avcıların hışmına uğramış, suçsuz-günahsız,

Her canlı gibi.

Lanetler yağdırmış tüm insanlığa.

Pirinç tarlasında bırakırken bedenini,...

Yüce varlığa.

Babam çocukken,

Kar eksik olmazmış dağ doruklarından.

Destileri çatlatırmış suların soğukluğu,...

Dört mevsim.

Sazanlar derelere hücum ederlermiş havyar zamanı.

Üremek için.

      Şimdi o balıklar yok! 

Ağlar geçit vermemiş.

Dönememişler bir daha gerisin geri yuvalarına.

Dönememişler,...

Katledilmişler hunharca.

    Babam büyümüş.

Baharda tanımış annemi,

Çiçek tozlarının eşleştiği zamanlar.

Çınarların gölgesinde salıncağa binerken.

Bir hıdırellez günü.

Suyun akışı desteklemiş yüreğini.

Gençliğinin ilk şiirini yazarken.

Geceleri ortak olmuş sevgisine bülbüller.

Gülümsemişler annem gibi, güller ve karanfiller.

    Babam şimdi kırkında.

Can çekişen tabiatın farkında.

Ama yine de güzellikler bulabiliyor anılarında.

Peki ya ben! ...

Yarın neyi anlatacağım çocuklarıma.

Kar düşmeyen dağları mı? ...

Adına türküler yakılan susuz pınarları mı? 

Yoksa lanet yağdıran leylekleri mi? 

Söyleyin Allah aşkına! ...

     Güzel yavrum! 

''''Biz sanal dünyada tanıştık''''mı diyeceğim babanla.

Ya da bir hıdırellez günü,

Lağım sularının aktığı dere kenarında,

Bir kuru ağacın dibinde, kuşsuz, kelebeksiz,...

Diye mi başlayacağım hatıralara.

Ne olur söyleyin! 

''''Sen sabahları arabaların gürültüleriyle uyanırdın yavrum

İlk gördüğün, göğe erişen binalar olurdu mu? 

Diyeceğim.

Doğayı kültürparkta,

Canlıları kafeslerde mi göstereceğim! 

                                                        Zehra Tunç

                                                    (Babasının çırağı)', 'Babam çocukken, Bir başka güzelmiş doğa. Ağaçlar, çiçekler, hava su ve toprak. Akın akın göçmen kuşlar gelirlermiş buraya. İlk gelen hacı le...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Tunç']::text[], 8.5, '{"poet":"Süleyman Tunç","poet_slug":"suleyman-tunc","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/cevre-babam-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan insan istanbul', 'i-nsan-insan-istanbul-elazigli-mustafa-kaya-5itjk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mevsim sonbahar

sicim gibi sağanak

insan insan vapur

insan insan sokaklar

insan insan yağmur

sabahtan akşama kadar..

yer,deniz,gök masmavi akar

İstanbul kalabalık kaynıyor

kaç boyut

kaç hayat

kaç dünya yaşar

İstanbul,

yaşama savaşını yaşatıyor

anlatılamayanları anlatıyor..

surlar..surlar..

sahiler boyunca yalılar

kuleler..mabedler..

süleymaniye

eminönü

yenicami

susma söyle

musluklarından kimler çekti

besmele

söyle kimler geldi geçti..

gezindim durdum

efsane  kentin mavisinde

tükenmez hikayeler dinledim

ömür alacak dillerde

ve iskeleden bir vapur

İstanbul dan istanbul’a gider

dinmeyen yağmur altında

bu şehrin gizemi devam eder..

Mustafa kaya

01.11.2005 / istanbul', 'mevsim sonbahar sicim gibi sağanak insan insan vapur insan insan sokaklar insan insan yağmur sabahtan akşama kadar.. yer,deniz,gök masmavi a...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/insan-insan-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayın gözlerim', 'aglayin-gozlerim-sair-ahbaboglu-a2xgm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün yine görmedim  yari,

Bilmem ki nerlerde, nerelerde,

Rüyamda da olsa göreydim bari,

Görmedin işte görmeyeceksin bir daha,

Ağlayın gözlerim İşte size bir fırsat daha.

Zaten ağlamıyor mu hergün özlerim,

Geçip gitmiyor şu tükenmez özlemim,

Yollarda hergün onu arıyor gözlerim,

Gelmedi işte gelmeyecek bir daha.

Ağlayın gözlerim işte size bir fırsat daha.

Onu ararken olmadın mı ki divane,

Olmadığım şeymi kaldı bu dert sayesinde,

Girdim binbir kılığa bana gülsün diye,

Gülmedi işte gülmeyecek bir daha,

Ağlayın gözlerim işte size bir fırsat daha.

Ahbaboğlum derdini kimse anlamıyor mu? 

Gözünden artık yaş akmıyor mu? 

O güzel halini görmüyor mu? Bilmiyor mu? 

Bilmiyor işte bilmeyecek bir daha,

Ağlayın gözlerim işte size bir fırsat daha.', 'Bugün yine görmedim  yari, Bilmem ki nerlerde, nerelerde, Rüyamda da olsa göreydim bari, Görmedin işte görmeyeceksin bir daha, Ağlayın gözle...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahbaboğlu']::text[], 8.5, '{"poet":"Şair Ahbaboğlu","poet_slug":"sair-ahbaboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aglayin-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milli uyanışın her zaman başlangıc yeri olan canım Erzurum', 'milli-uyanisin-her-zaman-baslangic-yeri-olan-canim-erzurum-halil-colak-hswm1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Erzurum kalemle anlatılmayacak kadar övgüye değer ulu vatandır.

Silsilemden uğrunda cephelerde savaşan uğrunda şehit yatandır.

Babam oğuz anam çeçen o kahraman Türk ırklarından gelendir.

Biz varken hiç bir soysuzda seni işgal edemez canım Erzurum.

Türkün başına Türkoğlu Türk Atatürk ancak baş olur

Yavuz Sultan Selim gibi Tük oğlu Türk Padişah olur.

Nene Hatunlar, Kara Fatmalar Türk’ün başına taç olur.

 Milli uyanışın her zaman başlangıcı yeri olan canım Erzurum

Halil Çolak 1.11.2005 Ankara saat.05.15', 'Erzurum kalemle anlatılmayacak kadar övgüye değer ulu vatandır. Silsilemden uğrunda cephelerde savaşan uğrunda şehit yatandır. Babam oğuz an...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/milli-uyanisin-her-zaman-baslangic-yeri-olan-canim-erzurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çorumun Suyu', 'corumun-suyu-mehmet-isikoglu-arl48', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Almanyadan özel imkan sağladım

Değer bilen erbabını aradım

Umudumu Çorumluya bağladım

Verildi söz değeri yok neyleyim

Aşılamadı bürokrasi engeli

Takıldı çengele ceryanın teli

Dönmedi değirmen kestiler yeli

Kulak sağır duyarı yok neyleyim

Çok aşırı değer verdim Çoruma

Bilinmedi kadri gitti zoruma

Reis, hakim olamadı duruma

Partilerin ayari yok neyleyim! 

Gelmişti nimet halkın ayağına

Çektiler set  enerji irmağina

Hor baktılar sürülen ekmek yağına

Kıymetini bilmediler neyleyim.

Düştü hayallerim Çorumda suya

Güzelim projeler yattı uykuya

Ankara taşı çarptı tramvaya

Sistemlerde uyarı yok neyleyim', 'Almanyadan özel imkan sağladım Değer bilen erbabını aradım Umudumu Çorumluya bağladım Verildi söz değeri yok neyleyim Aşılamadı bürokrasi en...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/corumun-suyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A Güzel', 'a-guzel-zulfikar-yapar-kaleli-b4kkj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur gözlerine sıska beline

Vuruldu bu gönlüm, haberin mi var.

Leyli dudağına, şeker diline

Kuruldu bu gönlüm, haberin mi var.

Gönül işte, bir sevdanın özünden

Vazgeçsin mi ikrarından, sözünden

Senin bu işveli nazın yüzünden

Yoruldu bu gönlüm, haberin mi var.

Feryat fısıldadı, duydu gözlerin

Tuttu gözlerimi oydu gözlerin

Aklımı kafese koydu gözlerin

Buruldu bu gönlüm, haberin mi var.

Göğe bağdaş kurdu, yere yaslandı

Gölge bastı, sırılsıklam ıslandı

İki tepe arasında üslendi

Duruldu bu gönlüm, haberin mi var.

1999', 'Yağmur gözlerine sıska beline Vuruldu bu gönlüm, haberin mi var. Leyli dudağına, şeker diline Kuruldu bu gönlüm, haberin mi var. Gönül işte,...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/a-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimliksiz İ', 'kimliksiz-i-mehmet-fatih-uzut-2nywb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Keşkeyle başlayıp seninle devam eden bütün cümleler kağıttan bir gemi şimdi...

Ama senin sularına açılmaya cesaretim yok artık...

Korkuyorum; 

           ya dalgaların yine hırpalarsa beni.........', 'Keşkeyle başlayıp seninle devam eden bütün cümleler kağıttan bir gemi şimdi... Ama senin sularına açılmaya cesaretim yok artık... Korkuyorum...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Uzut']::text[], 8.5, '{"poet":"Mehmet Fatih Uzut","poet_slug":"mehmet-fatih-uzut","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kimliksiz-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimliksiz İi', 'kimliksiz-i-i-mehmet-fatih-uzut-92kn6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir mum alevi,

Bir sigara,

Ve ince belli bardağın

-belden aşağı-

soğuk bir yudum çayı....

Sevgiliyi düşlemek için muhteşem bir an

Ve ya aileyi uzaklarda...

Ama dostlar düştü

       mum alevinin dumana gömülen soyutluğuna...

Mum erimek üzere,

Derin bir uyku uzak arkadaşları unutturmada yine...

Ama hep hatırlamaktansa 

        arada bir anımsamak en güzeli bence,

İnce belli bardağın o son yudumunda........', 'Bir mum alevi, Bir sigara, Ve ince belli bardağın -belden aşağı- soğuk bir yudum çayı.... Sevgiliyi düşlemek için muhteşem bir an Ve ya aile...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Uzut']::text[], 8.5, '{"poet":"Mehmet Fatih Uzut","poet_slug":"mehmet-fatih-uzut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kimliksiz-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimliksiz İii', 'kimliksiz-i-ii-mehmet-fatih-uzut-q529d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi bütün topraklar kurak kaldı....

Artık dağlarına bahar gelmeyecek memleketimin.......', 'Şimdi bütün topraklar kurak kaldı.... Artık dağlarına bahar gelmeyecek memleketimin..........', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Uzut']::text[], 8.5, '{"poet":"Mehmet Fatih Uzut","poet_slug":"mehmet-fatih-uzut","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kimliksiz-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-mehmet-fatih-uzut-660n3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kader geniş bir seçenekler yumağı sunar bize..

Biz ise apansız serzenişlerde bulunuruz kadere...

Seni sevmek kaderimde vardı...

Beni sevmemen vardı kaderinde...

-Ama elimizdedir yön vermek kaderimize-

Hadi uzat ellerini....

Çünkü seni sevmek var kaderimde...

Uzat ellerini hadi...

Sonsuz sevilmek var kaderinde........', 'Kader geniş bir seçenekler yumağı sunar bize.. Biz ise apansız serzenişlerde bulunuruz kadere... Seni sevmek kaderimde vardı... Beni sevmeme...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Uzut']::text[], 8.5, '{"poet":"Mehmet Fatih Uzut","poet_slug":"mehmet-fatih-uzut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kader-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ertelenmiş Sevdâlar', 'ertelenmis-sevd-lar-mehmet-bicik-2my7w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ertelenmiş sevdâların

Kurbanıyız

Biz seninle…

Sevmeye, 

Sevilmeye 

Bulamadık vakit…

Aklında, 

Başkası vardı.

Başkasının

Kâlbindeydi yerin.

Sınırsızdı hayallerin,

Çoktu 

Hayattan beklentilerin…

Ârsızdın,

Umursamazdın,

Sen benim olamazdın…

Sevdâlarımızdı

Ertelediğimiz…

Hayatımızdı,

Umutlarımızdı…

Kaç kez

Uyardım gönlümü.

İsmini anmayacaktı,

Senin için yanmayacaktı.

Ve

Biliyorum

Yaşanmayacaktı

Ertelenmiş Sevdâmız…

Kader

Çoktan ayırmıştı 

Yollarımızı…

Olmayacağını bile bile

Boşa harcadık

Yıllarımızı…

Ârsızdın,

Umursamazdın,

Sen benim olamazdın…

Beni,

Benden aldın.

Kâlbimi çaldın.

Benim için yanmadın.

İsmimi hiç anmadın.

Sülük gibi yapıştın,

İçtin kanımı,

Kanmadın…

Ârsızdın,

Umursamazdın,

Sen benim olamazdın…

Ertelenmiş sevdâlarımızdı

Bizi bitiren, 

Deli divâne gezdiren…

Bize şiir yazdıran

Ertelenmiş,

Yaşanmamış sevdâlarımızdı…

1 Kasım 2005, Burhaniye 05:30', 'Ertelenmiş sevdâların Kurbanıyız Biz seninle… Sevmeye,  Sevilmeye  Bulamadık vakit… Aklında,  Başkası vardı. Başkasının Kâlbindeydi yerin. S...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/ertelenmis-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can', 'can-belgin-turan-z3kiy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kir  işlemiş, el çatlamış,

Ayaklar nasır bağlamış,

Daha küçücük yaşında,

Şimdiden aklar başında,

Yüzüne çizgiler düşmüş,

Bir parça ekmek avucunda,

Isırdığı  her  lokmada,

Boğazına düğüm düşmüş,

Bir kedi durmuş yanında,

Eliyle  başın okşamış,

Yüzüne gülücük konmuş,

O da bir can, can yanında.

Belgin TURAN

''Güzden Önce Aşktan Sonra'' adlı şiir kitabımdan alınmıştır.

Gündüz Kitabevi Yayınları

Demet 7. Sokak No:7/b

Yenimahalle/Ankara', 'Kir  işlemiş, el çatlamış, Ayaklar nasır bağlamış, Daha küçücük yaşında, Şimdiden aklar başında, Yüzüne çizgiler düşmüş, Bir parça ekmek avu...', ARRAY['Türk Edebiyatı','Şiir','Belgin Turan']::text[], 8.5, '{"poet":"Belgin Turan","poet_slug":"belgin-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/can-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Bilinmezlik...', 'uc-bilinmezlik-pinar-koc-qpqcn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÜÇ BİLİNMEZLİK…

  Sensizlikten,

 Nefes alamadığımı hissettiğim anlarda,

Gözümde küme bulutlar çakışıyor

Ve kan dökülüyor çatışmada…

Kırmızı bir sürü damlacıklar! ! ! 

Islanıyorsun sen altında,

Sırılsıklam…

Özlemlerimle savaşmayı öğrendiğim gün,

Minik bir barış antlaşması imzalıyoruz,

Kendi aramızda, ömür boyu sürecek…

Artık dost kalabiliyoruz,özlemlerim ve ben…

Bazen hasretim de katılıyor bize! 

Özlemlerim hasretim ve ben…

Oturup içiyoruz bazı geceler.

Ağlayıp aşk şarkıları söylüyoruz,

Görülmez köşelerde…

Sessiz sedasız…

Ve bir ağaçta sallanan ipin ucunda

 Bir ilmek…

Sonra onu geçiriyoruz boynumuza,

Sonra kendi elimizle kendi ipimizi çekiyoruz,

Sorgusuz, sualsiz…

İçimizdeki çocuğu bile dinlemeden…

Sonra,

Sonra ölüyoruz

Birer birer…

                                              11.12.2001   12:30', 'ÜÇ BİLİNMEZLİK…   Sensizlikten,  Nefes alamadığımı hissettiğim anlarda, Gözümde küme bulutlar çakışıyor Ve kan dökülüyor çatışmada… Kırmızı ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uc-bilinmezlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Diyarlarda Sevdalar Varmıdır? ? ?', 'uzak-diyarlarda-sevdalar-varmidir-pinar-koc-yo0ut', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'UZAK DİYARLARDA SEVDALAR VARMIDIR? ? ? 

Ve karanlık,

Ve yalnız bir gece…

Keşke hep aydınlık kalsaydı gökyüzü,

Hep aydınlık kalsaydı,yalnız gece…

Sevdalarımın göz alıcı beyazlıkları,

Umutlarımın derin mavisi,

Ve hayallerin yemyeşil yeşili gibi…

Ve yalnız bir gece,

Keşke,

Keşke hep aydınlık kalsaydı gökyüzü…

Uzak diyarlarda da,

Uzak uzaklıklarda da,

Haşin ve mor dağların engin tepeleri,

Ve bu tepelerin,üzerindeki karanlık gecelerde

Hep yalnız ve simsiyah mıdır? ? ? 

Uzak memleketlerde de umutlar mavi,

Hayaller yeşil midir? 

Sevdalar yoktur uzak diyarlar da belki de! ! ! 

Umutlar yoktur,

Hayaller hiç yeşil olmamıştır! ! ! 

Her şey gökyüzü gibi simsiyahtır belki de! ! ! 

Ve can sıkıcı,ve iç karartıcı,

Ve karanlık,

Ve yalnız bir gece…

Keşke,

Keşke hep aydınlık kalsaydı gökyüzü…

                                                                10.01.2002  00:09', 'UZAK DİYARLARDA SEVDALAR VARMIDIR? ? ?  Ve karanlık, Ve yalnız bir gece… Keşke hep aydınlık kalsaydı gökyüzü, Hep aydınlık kalsaydı,yalnız g...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uzak-diyarlarda-sevdalar-varmidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göğün Adaleti...', 'gogun-adaleti-pinar-koc-yvmx5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GÖĞÜN ADALETİ….

Gökyüzü bugün, her zamanki gibi değil! ! ! 

Belki biraz daha içine kapanık,

Belki biraz daha hüzünlü…

Belki de ağlar birazdan,içinden geldiği gibi…

Hıçkırıklara boğulur

Göz yaşlarının içinde…

Belki bir derdi vardır 

Umulmaz,çaresiz…

Anlatmaz,anlatamaz…

İçine kapanıktır o,

Bütün hesaplaşmaları,pazarlıkları 

Kendi içinde yapar! ! ! 

Kendi içinde cezalandırır suçluları…

Yeri gelir affeder,

Yeri gelir ipe çeker…

Ama bugün gökyüzü,

Her zamanki gibi değil…

                                                     30.11.2001   18:29', 'GÖĞÜN ADALETİ…. Gökyüzü bugün, her zamanki gibi değil! ! !  Belki biraz daha içine kapanık, Belki biraz daha hüzünlü… Belki de ağlar birazda...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gogun-adaleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayamam ki Sen Olmadan', 'yasayamam-ki-sen-olmadan-huseyin-erdogan-1ujig', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir gün bile

başını çevirip de

bakmazsan benden yana

İstanbul''da

mevsimler değişir birdenbire

mevsim yaz olsa da

inan karakış gelir

bizim buralara

hazan düşer gönlüme

sararır hayallerim bir gecede

bil ki sen olmazsan yanımda

yeşermezler bir daha

hem de ömrüm boyunca

ağrılarım sızılarım başlar

bütün organlarımda

nefes alamam sensiz kalamam

korkar dururum yokluğunda

yüreğim şiddetlice üşür

el alem bana gülüşür

ne olursun beni sensiz bırakma

razıyım düşlerimde olsa da

hiç gitme benimle uyu ömrümce

yeter ki sevgiyle sarıl bana

sabahlara değin rüyalarımda

ben yıllar sonra düştüm senin aşkına

seni taparcasına seviyorum anlasana

uzaktan da olsa beni sevdanla yakıp da

sakın bir gün benim dünyamı karartma

ne olursun buralarda beni çevirme şaşkına

sevgili şiirim yoksa dayanamam yokluğuna

ben de hemen çeker giderim bu dünyadan

vallahi arkama bile bir kez dönüp bakmadan

zaten bu alemde yaşayamam ki sen olmadan

                                                   01.11.2005

                                                Hüseyin Erdoğan', 'bir gün bile başını çevirip de bakmazsan benden yana İstanbul''da mevsimler değişir birdenbire mevsim yaz olsa da inan karakış gelir bizim bu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yasayamam-ki-sen-olmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Secdelerim hep niyaz', 'secdelerim-hep-niyaz-mine-yirmili-4bncw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İbadetim değil namaz; 

Secdelerim, hep niyaz. 

Her sabah yatağımdan, 

Kalktığımda sağlıkla, 

Şükrederim yaradanıma. 

Giyerken terliğimi, 

Çekerim e - uzu Besmele-mi. 

Dualarımdır her zaman; 

Namusum olmadan ziyan. 

Gireyim yatağıma, 

Baş koyayım yastığıma. 

Huzurla dalayım, 

Kabussuz rüyalarıma. 

Mine YİRMİLİ 2005 Yılı 

Ramazan''ının Kadir''i', 'İbadetim değil namaz;  Secdelerim, hep niyaz.  Her sabah yatağımdan,  Kalktığımda sağlıkla,  Şükrederim yaradanıma.  Giyerken terliğimi,  Çe...', ARRAY['Türk Edebiyatı','Şiir','Mine Yirmili']::text[], 8.5, '{"poet":"Mine Yirmili","poet_slug":"mine-yirmili","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/secdelerim-hep-niyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Böceği...', 'ates-bocegi-pinar-koc-peoor', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ATEŞ BÖCEĞİ……

Asırlardır yaşanmayan en büyük aşktı bendeki! ! ! 

Tariflere sığmayan,kelimelerin anlatamadığı…

Esaretlere sığmayan,mahpusların almadığı! ! ! 

Şiirler kadar güzel,yazıtlar kadar muhteşem…

Birlikte yaşanılıp,birlikte bölünen! ! ! 

Ölüm kadar gerçek,yalan kadar acı…

Canımı yakan,

İçimi kavuran,

Esirgendikçe kuruyan,kurudukça kahrolan,

Güzeller güzeli bir ateş böceği sanki! ! ! 

İçinde aydınlıklar yanarken, 

Mutluluğumun yaralarını kor eden… 

Ellerimde ölme lütfen ateş böceği…

                                                            26.02.2002    00:58', 'ATEŞ BÖCEĞİ…… Asırlardır yaşanmayan en büyük aşktı bendeki! ! !  Tariflere sığmayan,kelimelerin anlatamadığı… Esaretlere sığmayan,mahpusları...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ates-bocegi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bembeyaz Bir Yalansın Sen', 'bembeyaz-bir-yalansin-sen-seyhan-sevgili-n3yxx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bembeyaz bir yalansın sen...

Bildiğim halde kandığım,çoktan yaşadığım küçük bir avuntu.

Canımın kıyısında ara rüzgarlı bi yaşam.

Her nefesi tipi,boran,zelzele...

Unutulmuş bakışlar gibi,

yasaklanmış dokunuşlar gibi uzak tuttuğum,

iki gözümün ardı kadar iyi bildiğim.

Etimden, derimden yakın olduğum.

Bir göz çarpışmasında kırılacağım,toplanmayacak kadar dağılacağım.

Soyut bir hayatsın, diz boyu derinliklerimde...

Bembeyaz bir yalansın sen...

Gelişininde,gidişininde izi var bedenimde.

Baksan birini görürsün,öyle sanırsın.

Bembeyaz bir yalansın sen...

Oturduğu çimlerde izi kaybolan,

sevdirdiğinin kapısı çalınmayan bi yalan.', 'Bembeyaz bir yalansın sen... Bildiğim halde kandığım,çoktan yaşadığım küçük bir avuntu. Canımın kıyısında ara rüzgarlı bi yaşam. Her nefesi ...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bembeyaz-bir-yalansin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçenlere,Göçenler', 'gecenlere-gocenler-kadir-ucvet-45zmu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutturdu zaman,

yüzlerin FEY(Z)   Slerini..(*)

buğulu bir cam ardında

bıraktı:

küçük tarih....

Kandırdı mekan,

küçük bir suret

şeklinde ŞEY(H)   Plerini...(*)

Şeytan gizemi altına vücudunun

sakladı:

küçük zarif....

Dokunaklı limandı,

fotoğraf arşivlerinin 

saklandığı

Ilımandı, 

Geçenlere,göçenler 

sanılarak

bakılandı..

(*) :FEY(Z)  S :  Feyz / Face   (feys)   bulaşımı

(**) :ŞEY(H)  P: Şeyh / Shape (şeyp)  bulaşımı', 'Unutturdu zaman, yüzlerin FEY(Z)   Slerini..(*) buğulu bir cam ardında bıraktı: küçük tarih.... Kandırdı mekan, küçük bir suret şeklinde ŞEY...', ARRAY['Türk Edebiyatı','Şiir','Kadir Üçvet']::text[], 8.5, '{"poet":"Kadir Üçvet","poet_slug":"kadir-ucvet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecenlere-gocenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yakılan Sözler', 'yakilan-sozler-bekir-gedikoglu-1z8ua', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yırtıldı birer, birer

Mazideki resimler

Yakıldı teker, teker

Geçmişimdeki sözler

Atıldı köprülerim

Ben acıdan inlerim

Çılgın savaşçı idim

Bir kediye benzedim

Mırıldanırım bazen

Senden kalan geceden

Berduş oluyorum ben

İçkim gelir maziden

Ben zaman ötesiyim

Seninle birleşirim

O benim telepatim

Nerde olsan gelirim

Ölmez derler hayaller

Soluyor güzel renkler

Ayrılığa set çeker

Güzel huylu melekler

Yüzerim hayallerde

Dalarım gecelerde

Görüşürüz ilerde

Eğer bize nasipse

Ankara 31.10.2005', 'Yırtıldı birer, birer Mazideki resimler Yakıldı teker, teker Geçmişimdeki sözler Atıldı köprülerim Ben acıdan inlerim Çılgın savaşçı idim Bi...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yakilan-sozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryadım', 'feryadim-bilal-altuntas-5qcs2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duyulmamış aşkıma feryadımdır,

Anlayamadığım,anlatamadığım! 

Acılarla içime akan yaşımdır,

Yalanlarla hep sakladığım.

Bak bu kaçıncı gecenin sabahı,

Bu kaçındı acımın göz yaşı,

Sağır sultan duyduda beni,

Sen ey zalim duymadın feryadı,

Umulurki seversin diye,

Bir ömür seni sevdim.

Bin bir renk gönül bahçemde,

Tek renk seni belledim.

Kaç mevsim geçti,

Bu kaçıncı baharım.

Sanmaki başka çiçek yok,

Sanmaki yanlızım

Ama biri olacaksa sen olmalısın,

Ağladık yeter dahamı aglatacaksın? 

Bak bilal''in ahını alacaksın,

Bir ömür kulaklarında,

Bu feryadı duyacaksın! ...', 'Duyulmamış aşkıma feryadımdır, Anlayamadığım,anlatamadığım!  Acılarla içime akan yaşımdır, Yalanlarla hep sakladığım. Bak bu kaçıncı gecenin...', ARRAY['Türk Edebiyatı','Şiir','Bilal Altuntaş']::text[], 8.5, '{"poet":"Bilal Altuntaş","poet_slug":"bilal-altuntas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/feryadim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyim...', 'neyim-emirhan-bala-v0edo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdanın sonsuz yolcusuyum,

Ya bilmiyorum sevmeyi,

Yada ben sevimsizim…

Kana karışır göz yaşlarım,

Ya bilmiyorum ağlamayı,

Yada karardı gönül gözüm….

Kırıntılarım çaylak satırlara,

Ya bilmiyorum dökülmeyi,

Yada kurudu kalemim…', 'Sevdanın sonsuz yolcusuyum, Ya bilmiyorum sevmeyi, Yada ben sevimsizim… Kana karışır göz yaşlarım, Ya bilmiyorum ağlamayı, Yada karardı gönü...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neyim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin? ? ?', 'bilirmisin-gulcan-sakal-tg2m6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğin acıması nasıl olur bilirmisin? 

Bilirmisin bıçak yarasını yüreğinde

Bedeninin küskün bağırışlarını duydunmu hiç

Hiç kaldınmı bedeninle başbaşa

Konuştunmu...

Gerçek korkuyu yaşadınmı ömrün boyunca

Korkunun çaresizliğe, çaresizliğin korkuya dönüştüğü ânı

Tattınmı hiç...

Hissettinmi arkasından bütün vücudunun tamamen uyuştuğunu

Ve gözlerini kapatmamak için direndinmi

Bir daha açılmayacak korkusuyla

Ya hiç anlık zirvelerin oldumu hayatında

Ve baktınmı aşağılardan yukarılara

Sevgiyi kaç kere arzuladın hayatında

Hiç külkedisi hayallerin oldumu

Gerçekten yaşamış gibi oldunmu hiç hayallerini

Gerçeğe dönmenin acısını duydunmu

Karanlıklarda kaldınmı hiç? 

Hayatının karanlıktaki yıldızlara ulaşmak 

Olduğunu hissettinmi yüreğinde

? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ? ?', 'Yüreğin acıması nasıl olur bilirmisin?  Bilirmisin bıçak yarasını yüreğinde Bedeninin küskün bağırışlarını duydunmu hiç Hiç kaldınmı bedenin...', ARRAY['Türk Edebiyatı','Şiir','Gülcan Sakal']::text[], 8.5, '{"poet":"Gülcan Sakal","poet_slug":"gulcan-sakal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilirmisin-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğer', 'meger-ahmet-bektas-olj5q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni nasıl sevmişim,

Meğer...

Kırarken kırılan,

Yüreğimden etrafa; 

Saçılırken sen.

Gururumdu yıkılan,

Kahrettim kendi kendime.

Bir şiirin içinde,

Yaşayacak sevgin.

Bahçemdeki en seçkin,

Çiçek olacaksın.

Gün gelip,solacaksın; 

Ama asla yok olmayacaksın.

Çünkü ebediyen,

Hafızamda kalacaksın.', 'Seni nasıl sevmişim, Meğer... Kırarken kırılan, Yüreğimden etrafa;  Saçılırken sen. Gururumdu yıkılan, Kahrettim kendi kendime. Bir şiirin i...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bektaş']::text[], 8.5, '{"poet":"Ahmet Bektaş","poet_slug":"ahmet-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/meger-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanma', 'i-nanma-birkan-demirci-yqh2r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sana bildiğim en büyük gerçeğini söyledim 

sana ''seni seviyorum'' dedim 

inanmadın 

sana ''seni sevmiyorum'' diye yalan söyledim 

sen,çektin gittin

sana bir yalan daha söylüyorum

''umurumda değilsin artık''

''inanma''', 'sana bildiğim en büyük gerçeğini söyledim  sana ''seni seviyorum'' dedim  inanmadın  sana ''seni sevmiyorum'' diye yalan söyledim  sen,çektin gi...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/inanma-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Balıkçı', 'kor-balikci-seher-gungor-vgkvm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kardeş Olmuş Karanlığa

Fırtınalı Bir Okyanus,

Tam Ortasında Kalmış

Bir Balıkçı Teknesi.

Bir de Kaderine Boyun Eğmiş

Kör Balıkçı…

Durmadan Kürek Çekmekte

Göremediği Umuduna…

Bir Yıldız Parıltısına

Hasret Sürgün Okyanus

Ben ki Bir Umman Olmuşum

Yalnızlığına Gömülmüş….

Ne bir Fener Kalmış Ortada

Ne de Bir Işık.

Bir O Yana

Bir Bu yana Savrulmakta

Kör Balıkçı

Bir Garip Yolcu İşte…

Ne Geldiği Yoldan Haberdar

Ne de Gideceği Yerden Bihaber

Habire Kürek Sallamakta….

Tek Bildiği Kör Balıkçının

Umutsuzluk Çarpan Dalgaların

Bir Bir Söndürmekte Olduğu

Gözbebeğin deki Hasret Ateşini.

Hem de Kendi Öyle Bir Yangın Olmuşken….

Ne Okyanusun Maviliği

Kar Getirir Balıkçı ya,

Ne de..

Nede Balıkların Pırıltısı,

Nede Hasretiyle Yandığı

Göremediği Yıldızlar…

Balıkçının Ne Onları Görecek

Umudu Kalmıştır Artık,

Ne de Küçük Omuzlarında

Kürek Çekmeye Gücü

Ne de..

Nede Tatlı Rüyalara Daldığı

Kapalı Gözlerinde Derman…

Kör Balıkçı; Anladı Artık

Hayat Gibi Okyanusun

Bir Muamma Olduğunu..

Kapadı Kapalı Gözlerini

O Geceden Yanağında

Son Bir Damla Bırakarak….

Bıraktı Kürekleri..

Bıraktı Sandalı..

Göremediği Okyanusun Maviliğine…

Buna Tek Şahit

ALLAH Şahit..

Göremeyen Gözleri

Hayaline Hasret Sürgün Yıldızlar Oldu…

Seher Güngör

(Küçük Pencerem.31.10.2005-Saat:24:00)', 'Kardeş Olmuş Karanlığa Fırtınalı Bir Okyanus, Tam Ortasında Kalmış Bir Balıkçı Teknesi. Bir de Kaderine Boyun Eğmiş Kör Balıkçı… Durmadan Kü...', ARRAY['Türk Edebiyatı','Şiir','Seher Güngör']::text[], 8.5, '{"poet":"Seher Güngör","poet_slug":"seher-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/kor-balikci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesi Ben', 'oylesi-ben-birkan-demirci-wj5so', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir ayağın çukurda belliki gideceksin

ört toprağı üstüne, gitme demeyeceğim

senlede gülüyordum,sensizde güleceğim.

her akşam öylesine bir içki içeceğim.

sen gittinya artık, neşeliyim ben

aklıma gelince birden sen

sordular dert ve hüzün

dedim öylesi bir ben

seninle yaşadığım 

''umurumda değil'' hiçbir gün

senden haber getirince ölüm 

öylece baka kaldım 

dedim öylesi bir hüzün

25.12.1999 Çorum .', 'bir ayağın çukurda belliki gideceksin ört toprağı üstüne, gitme demeyeceğim senlede gülüyordum,sensizde güleceğim. her akşam öylesine bir iç...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oylesi-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkulu Rüya', 'korkulu-ruya-aysegul-atmaca-ptpew', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni rüyalarımda görüyorum hep yüzüme bakıp konuşmadan çekip gidiyorsun gözlerin son sözlerimin şahidi oluyor  katili bulunamıyor üşüyen ellerimin kokun hala odamın bir köşesinde gizli tütün kokan parmaklarım sen kokan geceyi seyrediyor pencereden gölgeler hep aynı hep ürkek utanmışlıkları saklar gibi kanatana kadar ısırıyorum dudaklarımı acıya inat direniyorum son kadehler selamlaşırken bir rüzgar konuk oluyor odama uzun uzun dertleşiyorum anlarmışcasına başını sallıyor kabusum oluyor yokluğun her çırpınış biraz daha dibe batırıyor beni bir çığlık daha ekliyorum gecenin ortasına yalnızlığın şarkısını mırıldanıyorum dalarken son kez uykuya gücüm kalmayana dek haykırıyorum sensizliğe inat sonra çekip gidiyor gece', 'seni rüyalarımda görüyorum hep yüzüme bakıp konuşmadan çekip gidiyorsun gözlerin son sözlerimin şahidi oluyor  katili bulunamıyor üşüyen ell...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Atmaca']::text[], 8.5, '{"poet":"Ayşegül Atmaca","poet_slug":"aysegul-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/korkulu-ruya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuştuk', 'konustuk-birkan-demirci-xi3nq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'konuştum,

konuştun,

konuştu.

''susun! ''

sustu.

konuşmadı.

baktım,

baktın,

baktı,

bakıştık. 

anladım.

anladın.

anlamadı.

sen ve ben dedin.

sen ve ben.

olur dedim olur.

ya o dedim.

oda dedi o da 

hele sen ve ben.

30.12.1999 Samsun', 'konuştum, konuştun, konuştu. ''susun! '' sustu. konuşmadı. baktım, baktın, baktı, bakıştık.  anladım. anladın. anlamadı. sen ve ben dedin. sen...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/konustuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlar', 'bayramlar-suleyman-zaman-ytxsg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlık yitirdi gerçek özünü

Herkesler unutmuş, “kardeş” sözünü

Barışa yöneltse gönül gözünü

İnsanlara sağlar, dostluk bayramlar

Kalmadı insanda, artık fazilet

İnsanlığı sardı, “bencilci” illet

İnsan, insan ile, kurarsa sohbet

Yapar işlevini o an  bayramlar

Olmasa yoksulluk, artsa varsıllık

Özgürse beyinler kalkarmış kulluk

Barış, tokluk olsa, kurulsa dirlik 

Anlamına uygun olur bayramlar

İnsanlığa insan gibi bakmayan

Nifak tohumunu güdüp ekmeyen

Sevgiden, dostluktan, candan bıkmayan

Gönülden gönüle aksa bayramlar

İçi nifak dışı müslim olanın

Dostluklara düşman, kinli kalanın

Her yaptığı işten, çıkar umanın

Bir anlamı olmaz, asla bayramın

Kendine kılmışsa, farzı kibiri

Kamili insanda, oynar sefili

Üretirse ahu, dost olmaz dili

Kalırmı anlamı, bilmem bayramın

Sokulmuş dilenci, konuma insan

Biçare duruma, gelmişse bir can

Şatafat içinde, her gün yaşayan 

Olur mu? Anlamı bilmem bayramın

Her yanda insanlık, suçu işlenir

Bunca haksızlığa, hak bu mu denir? 

Nice birey, nice sorun üstlenir

Paylaşmak olmalı, özü bayramın

Zamanım unutma, sevgi gücünü

Taşıyın gönülde, insan tacını

Paylaşırsa eğer, herkes acını

Her zaman,  var olsun böyle bayramlar.

                                 06.12.2002', 'İnsanlık yitirdi gerçek özünü Herkesler unutmuş, “kardeş” sözünü Barışa yöneltse gönül gözünü İnsanlara sağlar, dostluk bayramlar Kalmadı in...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bayramlar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Buralardan', 'git-buralardan-efsun-aydin-iq67s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Desem …

Bana asik kalir misin? 

Yer yerinden oynasa da,

Yine ilk gunku yerde bekler misin? 

Sev desem beni…

Dünyalara degismez misin? 

Sen beni bırakıp,

Gidemezsin…', 'Desem … Bana asik kalir misin?  Yer yerinden oynasa da, Yine ilk gunku yerde bekler misin?  Sev desem beni… Dünyalara degismez misin?  Sen b...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/git-buralardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Ateşli Zaman', 'en-atesli-zaman-birkan-demirci-8se8y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'en ateşli zamanında dokun tenine

öyle yansın ki; 

kutup buzları bile söndüremesin ateşi

ateşler öyle birleşsin ki; 

ateşlerin birleştiği zamanda 

çıldırsın zevkler

ağaçlar soysunda kabuklarını

en mahrem denilen yerler baksın güneşe

bakıpta doyumsuzluğuna ulaşsın

duyguların dizginleşmiş korkaklığında.

hala esirse doyumsuzluk

ayrılsın ayrıla bilirse 

tatminsiz kalan doğanın kanunundan.

24.09.2000 Samsun', 'en ateşli zamanında dokun tenine öyle yansın ki;  kutup buzları bile söndüremesin ateşi ateşler öyle birleşsin ki;  ateşlerin birleştiği zam...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/en-atesli-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahrem', 'mahrem-birkan-demirci-oo60h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'varoluşun ahlaksız temeliyse

bedenle mahremin kaygızıs çelişkisi

doruğa ulaşmış tatminsizliğiyse 

tutkunun esaret altındaki işareti

vurulsun zincire yada sökülsün yerinden 

devamı gelmeyene kadar zevkin 

ve soyu tükenene dek..... 

14.09.2000 Samsun', 'varoluşun ahlaksız temeliyse bedenle mahremin kaygızıs çelişkisi doruğa ulaşmış tatminsizliğiyse  tutkunun esaret altındaki işareti vurulsun...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mahrem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diller Kör', 'diller-kor-birkan-demirci-2cm56', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'diller kör

gözler sağır 

karmakarışık tüm satır 

cümleler anlamsız 

zaman tam sırası 

harfler manaya hazır 

dil,göz,yumruk hazır 

direniş başladı; 

özgürlük 

ilerde,ilerle 

senin sesinde 

ya kurtuluş ya esaret 

elinde 

ilerde,ilerle

durmadan,yılmadan

ebedi düşersen 

gelenler biraz geride...

19.03.2001  Samsun/Atakum', 'diller kör gözler sağır  karmakarışık tüm satır  cümleler anlamsız  zaman tam sırası  harfler manaya hazır  dil,göz,yumruk hazır  direniş ba...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/diller-kor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli(ce)', 'deli-ce-aydin-bali-6r8gg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Delip çıktım zamanıma, ömrüm bitti.

Delice ağladım, yuvam gitti.

Delice bakındım,gözlerim mertti.

Delik deşik konuştum, kulaklarım sertti.

Delice emekledim, ayaklarım naünsiyetti.

Deli taylarla yarıştım, canım pekti.

Delice aktı kanım, damarlarım çoştu.

Delice kazandım, ceplerim taştı.

Delice seviştim, tenim hoştu.

Delice sevdim, yüreğim boştu.

Delice aşık oldum, ruhum uçtu.

Delice geçtim kendimden, ilkti.

Delice yaşadım kendimi, nihayetti.

Delip çıktı zamanlar, ömrüm doldu.', 'Delip çıktım zamanıma, ömrüm bitti. Delice ağladım, yuvam gitti. Delice bakındım,gözlerim mertti. Delik deşik konuştum, kulaklarım sertti. D...', ARRAY['Türk Edebiyatı','Şiir','Aydın Balı']::text[], 8.5, '{"poet":"Aydın Balı","poet_slug":"aydin-bali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/deli-ce-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesi Sohbet', 'oylesi-sohbet-birkan-demirci-qrqv2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sohbetli gecede ey kara saçlım

art fikirler geçer yaşanan zamandan

çözebildiysem eğer altmış dokuz biçimde 

deprem sarsıntısında bağırtım yankılansın. 

son kez tutarken yasını tan; 

boğulsun göz yaşımla acı hıçkırığın. 

dalgalansın o körpe dudak 

ya beyaz tül savrulsun gökyüzüne 

yada gelsin tadı kokunun en ücra köşesine 

çeksin artık elini çift başlı ejderha

mağarasında tutsak ettiği zevkin

çıksın; tatsın özgürlüğü, en uçuk duygularda.

haykırış çıldırsında yırtılsın gırtlak

akıp gitsin döl yatağından kalleş buğday 

ya zamanın tadı kalsın ağzımda 

yada ölüm emretsin hiddet döngüsüne.

13.07.1999 Samsun/Atakum', 'sohbetli gecede ey kara saçlım art fikirler geçer yaşanan zamandan çözebildiysem eğer altmış dokuz biçimde  deprem sarsıntısında bağırtım ya...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oylesi-sohbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüzdür Aşk', 'olumsuzdur-ask-metin-yalti-bx9qg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece yarısı

Başlayan  aşk

Sabah

Anımsanmaz

Ayrıcalığı

Olan aşklar

Bitti sanılan

Aşklardır

Bitmez aşk

En olumsuzu bile

Yılların estetiğiyle

Kapanmaz

Derin  bir yaradır

İnsanın saklısında

İzi vardır.

Ancak

Yeniden kurulacak

Bir aşk

Sabaha

Yada

Akşama karşı

Ama mutlaka

Güneşe karşı

Kurulur aşk.

Her yangınında

Yeniden

Yeniden doğar

Bu nedenle

Fenikse benzer

Bitti.

Denilse  de

Varsayımdır ancak

Asla bitmez

Ölümsüzdür aşk.

31,10,2005', 'Gece yarısı Başlayan  aşk Sabah Anımsanmaz Ayrıcalığı Olan aşklar Bitti sanılan Aşklardır Bitmez aşk En olumsuzu bile Yılların estetiğiyle K...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/olumsuzdur-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yani', 'yani-birkan-demirci-seesp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'olmazmıydı ki 

ne vardı sevseydi yani 

yani o gün gelseydi 

öpseydi beni yani 

yani diyorumda olmaz ki yani.

2610.2005 Çorum', 'olmazmıydı ki  ne vardı sevseydi yani  yani o gün gelseydi  öpseydi beni yani  yani diyorumda olmaz ki yani. 2610.2005 Çorum...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yani-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşibirlik', 'besibirlik-metin-yalti-ipd4h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1 SİMETRİ

Oğlumun ki Amerika’dan

Taşlanmış özellikle, 

yüz seksen dolara geldi

Dizlerinde iki yırtığı vardı

Onun ki bu hale

Yılların sürtünmesiyle…



2 ASİMETRİ

Beslenme uzmanı arkadaşım

Baktı camdan parka

Hastasınız dedi 

İkinizde

Senin obezliğin 

dengesiz beslenme

Onun halsizliği 

Yetersiz  beslenmeden

3 SPOR

İkisi de parkta koşuyordu

Birinin sağlıklı yaşamdı derdi

Simitçiden kaçıyordu diğeri…

4.TOST

Üç numara mukavvanın arasında

İnce bir dilim sucuk  gibiydi

Köprünün kuytusunda.

Uyurken…

5. KİRLİ

Rahmetli babam

Fakirlik kirlilik değil derdi.

En çok pisliğe kızardı 

Gördüğüm kızın 

Bembeyazken teni, yüzü esmerdi..

1/11/2005

Deli Mavi Dalgalar Gurubunun Sokak Çocukları adlı etkinliği için yazılmıştır', '1 SİMETRİ Oğlumun ki Amerika’dan Taşlanmış özellikle,  yüz seksen dolara geldi Dizlerinde iki yırtığı vardı Onun ki bu hale Yılların sürtünm...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/besibirlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sosyete', 'sosyete-birkan-demirci-ij78f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'birgün sonrası 

yine aynı bilindik manzaralar

ya ölümden korkanlar için 

onda birine yazık oldu sosyetenin 

oysa ki ne umutlarla çizdirmişti

vesikalık resminin portresini

Ey Hayat! sen böyle acımasızsın işte.

27.12.1998 Samsun/Atakum', 'birgün sonrası  yine aynı bilindik manzaralar ya ölümden korkanlar için  onda birine yazık oldu sosyetenin  oysa ki ne umutlarla çizdirmişti...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sosyete-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Sergisi', 'siir-sergisi-aynur-uluc-hvbjn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şiir sergisi olsa bir gün

dizeler uçuşsa birbiri üstünden

kana karışsa harflerin zehri

okuyan, tutulsa sevdasına şairin

yıkık dökük barakaya mı

sulardan dönmüş takaya mı

kadehteki cakaya mı kurulurdu şiirler

hangi şiir, girerdi diğeriyle kol kola

hangisi gülümser, hangisi küserdi

çocuk gözlere mi eşlik ederdi sözler

oyuncak gülüşü asılı kalınca

bebek bezlerinde

ve

yakılan gemilerin hatrına

hangi şiir kahramanı adam

hangi dizesel kadınla sevişirdi

pamuk bahçelerinde

Aynur Uluç

Aynur Uluç



Birinci Elden Mevsimsiz  / 2007

Mevsimsiz Yayınları', 'şiir sergisi olsa bir gün dizeler uçuşsa birbiri üstünden kana karışsa harflerin zehri okuyan, tutulsa sevdasına şairin yıkık dökük barakaya...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/siir-sergisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir Bu?', 'nedir-bu-nurdan-elver-gpild', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acılar,

    Sevimsizlikler geçicidir,

      Zevk de

         Sevda gibi adeta bronza oyulur.

			

Bir derin iç çekiş misali,

   Bir başka boyutta bu sevda,

       Bir başka boyutta...

Sanki vahşi tabiatın kucağında

     Bulduğum bir gelincik

         Ya da bir papatya,

               Bembeyaz.

Sonsuz sevgilerimin bir eşkali,

    Bitiremediğim güzelliklerin izdüşümü,

       Belki de dostluklarımın hası,

          İçtenliğimin yansıması...

Tarifsiz duygulanmaların içinde

    Özlüyorum seni yanımda da olsan,

        Kollarının arasında kaybolmak,

            Kalbine ve beynine oyulmak bütünüyle...', 'Acılar,     Sevimsizlikler geçicidir,       Zevk de          Sevda gibi adeta bronza oyulur. 			 Bir derin iç çekiş misali,    Bir başka boy...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/nedir-bu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı Hiçe Saydım', 'zamani-hice-saydim-birkan-demirci-8r3v1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bütün sevdaların adını uzaklara koydum. 

zamanı hiçe sayan demiryolları 

ne varsa bana ait bir bir ardına koydum.

05.02.2005 Çorum', 'bütün sevdaların adını uzaklara koydum.  zamanı hiçe sayan demiryolları  ne varsa bana ait bir bir ardına koydum. 05.02.2005 Çorum...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zamani-hice-saydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl', 'nasil-nurdan-elver-1xbgs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani bardaktan boşanırcasına yağmur yağar ya,

Hani birdenbire bir bora patlar ya,

Hani,

Hani güneş yakarcasına parlar ya,

Benimki de öylesine apansız.

Ne bir gül gibi aldatan,

Ne bir kedi gibi nankör,

Ne bir bebek gibi doyumsuz,

Ne de buzullar gibi soğuk.

Benimki sadece ürkek.

Nasıl denizlere erişirse çağlayanlar,

Ağaçlara kavuşursa yağmurlar,

Nasıl sabahın ilk ışıklarıyla doğa,

Kavuşursa güneşine.

Benimki de öylesine hasret.

Nasıl özledim doğallığı,

Nasıl özledim sıcaklığı,

Nasıl özledim kahkahaları,

Nasıl özledim nasıl,

Gerçek aşkı...

Binbir türlü entrikadan kurtulmayı.', 'Hani bardaktan boşanırcasına yağmur yağar ya, Hani birdenbire bir bora patlar ya, Hani, Hani güneş yakarcasına parlar ya, Benimki de öylesin...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nasil-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-cengiz-polat-90fyc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlama küçüğüm,

Ben,

Senin yerinede ağlarım...

Oyunda olmalısın,

Oynaşta olmalısın,

Güzel yüreğine hüzün,

Güzel gözlerine yaşlar,

Hiç dolmasın...

Huyun,

Huylardan güzel,

Bir gülümsemen,

Dünyaya bedel,

Öfken bile,

Benim için çok özel,

Yeter ki,

Ağlama küçüğüm,

Ben; 

Senin yerinede ağlarım...

Tek düşünce içimde,

Tek hüzün yüreğimde,

Ben; 

Derman olamadım derdine

Bırakma öyle kendini,

Bu halinle görünce seni,

O yavaş yavaş,

Öldürüyor beni...

Ağlama küçüğüm,

Ben; 

Senin yerine de ağlarım...', 'Ağlama küçüğüm, Ben, Senin yerinede ağlarım... Oyunda olmalısın, Oynaşta olmalısın, Güzel yüreğine hüzün, Güzel gözlerine yaşlar, Hiç dolmas...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Polat']::text[], 8.5, '{"poet":"Cengiz Polat","poet_slug":"cengiz-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kucugum-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım', 'aglarim-nurdan-elver-g15ti', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zaman gökyüzü bulutlarla kaplansa,

Arkasından gökgürültüsüyle birlikte 

Bir yağmur başlasa

Ben de ağlarım.

Ne zaman sonbahar bitip de,

Arkasından soğuklarla birlikte

Kış gelse,

Ben de üşürüm.

Ne zaman yalnız kalsam,

Arkasından düşüncelerle birlikte

Sen gelsen,

Ağlarım mutluluktan.

Gülerim rüyalarımda,

Gülerim sıcacık dokunuşlarınla.

Gülerim ateşine.

Ağlarım düşüncelerimde

Ağlarım yanımdayken bile

Ağlarım özleminle...

Ağlarım hatırlayınca sohbetlerimizi

Felsefi duygularını hissedince.

Ağlarım görünce güçlülüğünü.

Gülerim sıcacık yaklaşımlarındaki

Temkinliliğini görünce.

Gülerim azmine ve hevesine.', 'Ne zaman gökyüzü bulutlarla kaplansa, Arkasından gökgürültüsüyle birlikte  Bir yağmur başlasa Ben de ağlarım. Ne zaman sonbahar bitip de, Ar...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aglarim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(Trajedi,Komedi,Kâbus) Karışımı Bir Rüya....', 'trajedi-komedi-k-bus-karisimi-bir-ruya-ulvi-ziya-8jlnu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cennet gibi mekândı...

Soldu...Sarardı...

Nazar değdi

Şühedâ merkadi gülistana...

Yiğitler harmanını haşare sardı,

bir ülkeyi döndürdüler ate''istan''a...

Yılınlar...

Çiyanlar...

Arsız domuzlar...

Nasip kapmak için birbirini omuzlar...

Bu vahşeti görenin yüreği sızlar...

VE; 

''Dana dana dastana

danalar girdi bostana''...', 'Cennet gibi mekândı... Soldu...Sarardı... Nazar değdi Şühedâ merkadi gülistana... Yiğitler harmanını haşare sardı, bir ülkeyi döndürdüler at...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/trajedi-komedi-kabus-karisimi-bir-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızımın Verdiği Ders', 'kizimin-verdigi-ders-mehmet-ayhan-gunaydin-i800u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'KIZIMIN  VERDİĞİ DERS

Kızım Selen

Henüz ikisinde.

Soruyorum

Ne olacaksın diye,

Büyüyünce.

Adam olacağını söylüyor.

Bilmem, bilerek mi? 

Yoksa, 

Bilmeden mi söylüyor.

Adama hasret günümüzde

Kızımın cevabı

Yüzümü güldürüyor.

Senin de yüzünü güldürenler

Çok olsun yavrucuğum.

Mutlu, güzel, insanca

Ve de adam gibi

Bir ömür sür, sevgili çocuğum.

Ben de; 

İkisindeki tavrını,

Unutmasın diye.

Not düşüyorum.

Şiir’ime. 

Hatırlatmak için,

Ona büyüyünce.

Not: (Adam gibi adam deyimi, eskiden, tüm doğruları, tüm güzellikleri kişiliğinde toplayabilmiş insanlar için kullanılırdı.)

M. Ayhan Günaydın

   29 Ekim 2005

       Ankara', 'KIZIMIN  VERDİĞİ DERS Kızım Selen Henüz ikisinde. Soruyorum Ne olacaksın diye, Büyüyünce. Adam olacağını söylüyor. Bilmem, bilerek mi?  Yoks...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kizimin-verdigi-ders-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Alışmıştım', 'bize-alismistim-seyhan-sevgili-jp98k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırık dökük, dağınık bi haldeyim o geceden sonra.

Duymadığım bir vecize, söyleyemediğim bir beste idi ayrılık.

Belki de yaşayıpta yazamadığım bir şiir.

Hazır değildim...Bize alışmıştım.', 'Kırık dökük, dağınık bi haldeyim o geceden sonra. Duymadığım bir vecize, söyleyemediğim bir beste idi ayrılık. Belki de yaşayıpta yazamadığı...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bize-alismistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Gönül', 'cikmaz-gonul-adem-tok-obtm5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-pencere yalnız dünyasını gösterir

birde konuşmuyorsa...eyvah çıkmaz! içe dönüş-

unutulmak daha mı iyi onarılmaktan

kırılan bir camı düşünüyorum

parçalarını yap(ıp) boz(up) bir araya getirerek

hep bir şeyler eksik arada

tuz harcı

buz malası

rüzgara yapışıyor yanıp sönen

yansı taneleri

öyle bir uğraşsamda

onaylamıyorum işçiliğimi

ustam,yaptığın işi önce kendin beğen

derdi

onarılmak

hep bir mesafe olur geliyor

unutulmak:ihanet! 

barış bu kadar yaralı olur mu

iyileşmesin iyisimi aracı

çekiyorum düşüncemi kurgumdan

                                                          (04.06.04) 

                                                          f tipi hapishane EDİRNE', '-pencere yalnız dünyasını gösterir birde konuşmuyorsa...eyvah çıkmaz! içe dönüş- unutulmak daha mı iyi onarılmaktan kırılan bir camı düşünüy...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cikmaz-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunu Saymıyorum Aşk', 'bunu-saymiyorum-ask-ahmet-selcuk-i-lkan-rw6qf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok zamansız yakaladın beni

Çok acemi

Bunu saymıyorum aşk

Bir daha gel  emi! ...

                        Ahmet Selçuk İLKAN

''Erkekler hep yalnız  ağlar'' kitabından

www.ahmetselcukilkan.com.tr', 'Çok zamansız yakaladın beni Çok acemi Bunu saymıyorum aşk Bir daha gel  emi! ...                         Ahmet Selçuk İLKAN ''Erkekler hep ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bunu-saymiyorum-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşımındın', 'arkadasimindin-seyhan-sevgili-j02px', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görmemeliydim seni, çevirmeliydim yüzümü bakmamalıydım.

Gülmeseydin bana,

        gel demeseydi gözlerin,

                 tut demeseydi ellerin,

                        sarılmamı istemeseydi bedenin.

Ne bakardım yüzüne,ne de kanardım güzelliğine.

Çünkü sen başkasınındın,arkadaşımındın...', 'Görmemeliydim seni, çevirmeliydim yüzümü bakmamalıydım. Gülmeseydin bana,         gel demeseydi gözlerin,                  tut demeseydi ell...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/arkadasimindin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-ahmet-selcuk-i-lkan-72six', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'UNUTMA! 

Bir ağaç yansa ormanlarda

Alevi içime düşer

Bir kuşun kırılsa kanadı uçurumlarda 

Çığlığı uykumu böler

Kaybolan çocukların adresini

Anaların acısını 

Yoksulluğun belasını

Yalnızların sevdasını

Ezbere bilirim

Ve sen

Sarılıp uyurken en güzel düşlere 

Ben ateşler içinde eririm

Unutma sen bir şiirsen

Ben de bir şairim.

                           Ahmet Selçuk İlkan

''Erkekler hep yalnız ağlar'' kitabından

www.ahmetselcukilkan.com.tr', 'UNUTMA!  Bir ağaç yansa ormanlarda Alevi içime düşer Bir kuşun kırılsa kanadı uçurumlarda  Çığlığı uykumu böler Kaybolan çocukların adresini...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unutma-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolmuş Nesiller...', 'kaybolmus-nesiller-ulvi-ziya-6pdqc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her âile târihinde kaybolmuş nesiller olur...

Kimi yoksulluk içinde yaşayıp,yok yere ölür...

Çizgisinden çıkmayan sürünüp gider mezâra dek,

Tâlihini hor görenin başına ağlar örülür...

Kimi anadan/babadan küs gelir dünyâ yüzüne,

Bozuk genlerden olmuştur,türlü dertleri görülür...

Şansını kendi yaratıp,kaderiyle oynar kimi; 

Yükselmek ister batar, diyar-ı gurbete sürülür...

Her âile târihinde mutlu-mutsuz nesil olur,

Kimi şâd ve uzun yaşar,kimisi kazâra ölür...

Kimi kefensiz defnolup,meçhul mezâra gömülür...', 'Her âile târihinde kaybolmuş nesiller olur... Kimi yoksulluk içinde yaşayıp,yok yere ölür... Çizgisinden çıkmayan sürünüp gider mezâra dek, ...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kaybolmus-nesiller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saadet', 'saadet-seyhan-sevgili-78juh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adınla yaşıyorum.

Her duyduğumda yaralıyor derinden.

Usandım artık bu isimden,anlamı gibi değil ki güzelim.

Mutluluk ağlatır mı? Özletir mi? ...

Bunu başarıyosun ya ne mutlu sana.

Hatırlıyorum da o yazı.

Seni gören gözlerimin ışıltısını.

Benden çıkıpta sana koşmak ister gibi çarpan,

şu suç ortağın kalbimi.

Ne kadar da mutluydum.

Ya şimdi...', 'Adınla yaşıyorum. Her duyduğumda yaralıyor derinden. Usandım artık bu isimden,anlamı gibi değil ki güzelim. Mutluluk ağlatır mı? Özletir mi?...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/saadet-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleri Kara''m', 'gozleri-kara-m-seyhan-sevgili-x5ydt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben birini sevdimki,bebek yüzlü.

Hep aradığım melek ruhlu,kara gözlü.

Öyle az zaman da öylesine bağlandımki,dostlarım şaşırdı.

Sordular neden? 

Söyledim...

O,kara gözlü dedim.', 'Ben birini sevdimki,bebek yüzlü. Hep aradığım melek ruhlu,kara gözlü. Öyle az zaman da öylesine bağlandımki,dostlarım şaşırdı. Sordular nede...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gozleri-kara-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-seyhan-sevgili-3jq28', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılık:

      Sana; Denize taş atmak kadar kolay.

      Bana; Onları bulmak kadar zor.

Ayrılık:

      Sana; Yıldızlara bakmak kadar kolay.

      Bana; Onlar ulaşmak kadar zor', 'Ayrılık:       Sana; Denize taş atmak kadar kolay.       Bana; Onları bulmak kadar zor. Ayrılık:       Sana; Yıldızlara bakmak kadar kolay. ...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayrilik-305-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızım', 'sizim-nurdan-elver-5cfwn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanıyor,

Açmayın gömütümün üzerini,

N’olur? 

Orada aşk ve sevda dolu

Güzelim yıllarım saklı,

Değmeyin.

O yılları,

Özenle alıp çıkardım hayatımdan; 

Sırla kaplı bir küpün içerisinde,

Sevdalımla birlikte,

Sevgimle kazdığım

Gömütümün içerisine gömdüm,

Yıllar önce...

Açmayın üstünü,

Kanıyor sızım zira,

Sızım sızım.

İlacı yok, devası yok.

Çaresi yok.

Örtün üstünü, huzuru salıverin.

Rahat bırakın.

Rahat! ...', 'Kanıyor, Açmayın gömütümün üzerini, N’olur?  Orada aşk ve sevda dolu Güzelim yıllarım saklı, Değmeyin. O yılları, Özenle alıp çıkardım hayat...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sizim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Acılarımın Başkenti', 'ey-acilarimin-baskenti-ahmet-selcuk-i-lkan-hhu9p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'EY ACILARIMIN BAŞKENTİ

Ey acılarımın başkenti

Ey gecelerimin cinneti

Öyle kolay olmayacak gidişin

Daha ilk adımında sendeleyeceksin

Bir yangın yayılacak parmak uçlarından

Bu şehrin buz tutmuş taş duvarlarına 

Göreceksin

Gezdiğin bütün sokaklarda

Düşlerim takılacak ayaklarına

Titreyeceksin

Ey hayallerimin kaçağı

Ey gönlümün sustalı bıcağı

İlk darbeyi hatıralar saplayacak sırtına

Bütün şarkılara küseceksin

Sahipsiz mezarlarda bulacaksın ikimizden kalanı

Ve bir duvar gibi çarpacak kimsesizliğin yüzüne

İrkileceksin

Ey yalnızlığımın miladı! 

Ey uykularımın celladı! 

Önce kendi yalanların hançerleyecek seni

Sonra ''keşke''lerin

Bir kar yangınında buzlar misali çözüleceksin

Gözlerinden kara yağmurlar gibi dökülecek pişmanlığın

Tükeneceksin...

Ey çığlıklarımın sireni! 

Ey ömrümün kara treni! 

Köhne bir istasyonda

Tek kanatlı bir kuş konacak omuzlarına

Kırdığın bir kalbi bırakacak avuçlarına

Şaşıracaksın

İşte bu son durağı olacak kaprislerinin

Delik deşik bir  hasretle düşeceksin kaldırımlara

Ellerin bile el vermeyecek sana

Ayakların çoktan çekip gitmiş olacak

Gözlerin en uzak yıldızlara  takılacak

Yıkılacaksın

Bir sen bir de o taş kalbin

Kalacak sokak ortasında 

Kaderinse  yaşlı  bir çöpçünün yorgun ellerinde 

Ağlayacaksın

Belki biraz geç olacak ama

İşte o gün....

Kimi kaybettiğini anlayacaksın....

		

Ahmet Selçuk İlkan

''Erkekler hep yalnız ağlar'' kitabından

www.ahmetselcukilkan.com.tr', 'EY ACILARIMIN BAŞKENTİ Ey acılarımın başkenti Ey gecelerimin cinneti Öyle kolay olmayacak gidişin Daha ilk adımında sendeleyeceksin Bir yang...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ey-acilarimin-baskenti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel de İçme', 'gel-de-i-cme-mehme-arslan-l1pqx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'eskiden üzümü gözlerinden içerdim

şimdi şişede rakıdan

pek farkı yok aslından

önceden tereme peynirini teninden yerdim

şimdi rakının yanında meze olaraktan

boş yere değil her gece içişim

tamamen ihtiyaçtan

31/10/2005', 'eskiden üzümü gözlerinden içerdim şimdi şişede rakıdan pek farkı yok aslından önceden tereme peynirini teninden yerdim şimdi rakının yanında...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-de-icme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölünce', 'olunce-nurdan-elver-lvivf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölürsem; 

Kocaman bir çam ormanının,

Tam ortasına gömün beni.

Sakın ha, gözlerimi kapatmayın; 

Hasretle acıyan gözlerimi.

Giderken,

Dudaklarım kupkuru,

Gözlerim hasret,

Ellerim bomboş,

Burnum duyarsız,

Kulaklarım sağır,

Gönlüm yalnız olacak.

Gömütlük hale gelince beni,

Mutlaka bir çam ormanına gömmeli.

Yanıma da yıllar önce hazırladığım,

Sırla kaplı küpten gömütümü koymalı.

Son bir kez bakmalı bana,

Aramalı yüzümde; 

Eksik geçmiş yılların ayak izlerini.

Yalnız...', 'Ölürsem;  Kocaman bir çam ormanının, Tam ortasına gömün beni. Sakın ha, gözlerimi kapatmayın;  Hasretle acıyan gözlerimi. Giderken, Dudaklar...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olunce-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum', 'unuttum-adem-tok-vdzpp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kaç gece yıldız aradım

kaç şafak eli boş döndüm

çukurda ki hücremin

alçak penceresinden

okudum

şiirler yazdım dünyama dair

kendime kızdım:

geçinemediğimden

küstüm

konuşmadım günlerce

dardı yansıyan

dardı doğal olarak düşler

ağarık suskuyu yırtan

asil kanıydı yalnız inancın

devindikçe gençleşen

kaç akıntı aradım

kaç kez boğuldum

unuttum! ..

                                           (şubat 2004) 

                                         f tipi hapishane EDİRNE', 'kaç gece yıldız aradım kaç şafak eli boş döndüm çukurda ki hücremin alçak penceresinden okudum şiirler yazdım dünyama dair kendime kızdım: g...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unuttum-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenmedi', 'tukenmedi-nurdan-elver-1ppbu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tükenmedi duygular, bitmedi

Aşkım.

Bitmesi beklenemez; 

Böylesine derin bir duygunun.

Ancak durulur belki

Ya da 

Küllenir hislerim; 

Eskiden olduğu gibi.

Aşksız yaşayamam ben; 

Şiir de yazamam,

Kitap ta.

Bu aşk; 

Eserlerimin hammaddesi,

Varoluş sebebim,

Özlemlerim iken

Hele.

Bir başıma yaşamalıyım aşkımı,

Hep ilham kaynağım olarak kalmalı,

Hep kalbimin yakarışları olmalı,

Hep özümde saklanmalı.

YOKSA...', 'Tükenmedi duygular, bitmedi Aşkım. Bitmesi beklenemez;  Böylesine derin bir duygunun. Ancak durulur belki Ya da  Küllenir hislerim;  Eskiden...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tukenmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daim Olsa Dostluklar', 'daim-olsa-dostluklar-suleyman-zaman-hhr6o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Baki kalan muhabbettir

Dostça olan hoş sohbettir

Dosta duyulan mihnettir

Daim olsa şu dostluklar

Sanattır hep, özgür kılan

Üretmektir asıl olan

Ürettiğin, baki kalan

Daim olsa, üretenler

Doğan elbet bir gün ölür

Barış, dostluk, iylik kalır

İnsan sevgiyle can bulur

Daim olsa, hep sevgiler

Kolay insan, gönlü kırmak

Bir gönülü, zor kazanmak

Bir canana, mihman olmak

Daim olsa, canca dostlar

Var dünyada, onca zulüm

Perişandır bundan halim

Hep erdemi söyler dilim

Daim olsa, erdemlilik

Sevgi dolsa, insan özü

Zamanımın budur sözü

Artsa dostluk, dizi, dizi

Daim olsa, iyilikler

              01.11.2005', 'Baki kalan muhabbettir Dostça olan hoş sohbettir Dosta duyulan mihnettir Daim olsa şu dostluklar Sanattır hep, özgür kılan Üretmektir asıl o...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/daim-olsa-dostluklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev Beni Anne', 'sev-beni-anne-meral-yagcioglu-qzo72', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tüm çocuklara iyi, mutlu, sevgi dolu bir bayram dilerim

Altıma kaçırmışım

Vurma anne

Ben daha küçüğüm

Bilmez ki çocuklar

Banyo yaparken 

Alev saçıyor bedenim

Haşlandı körpe tenim

Kaynar su yakar anne

Kimsesiz değilim ki

Dünyaya getiren 

Terk etmiş olsa bile

Bir annem var

Devletin yuvasına

Sığındım çaresiz

Sev beni anne

Muhtacım sevgine

Şefkatle büyür çocuk

Kucağına al,sar beni

Bas göğsüne başımı

Yanağım hazır öp anne

Annem olmasan da

Seviyorum seni

Vurma,vurma anne

Canım acıyor

Biliyorum evladın değilim 

Yürekten sevmesen de

Kucağına alıp öpmesen de

Başımı okşa ellerinle anne

Yaşamdan tek isteğim

Büyüyüp anne/baba olmak

Şefkatle sarıp çocuğumu

Sevgiyle büyütmek anne

Kanadımı kırma anne

    İstisnasız tüm çocukları sevin 

		28/10/2005', 'Tüm çocuklara iyi, mutlu, sevgi dolu bir bayram dilerim Altıma kaçırmışım Vurma anne Ben daha küçüğüm Bilmez ki çocuklar Banyo yaparken  Ale...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sev-beni-anne-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir mi...', 'bir-mi-i-brahim-ethem-bingul-9mf1o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eline bak, ibret sunar:

Beş parmağın beşi bir mi? ..

Var yığın yığın insanlar

Düşüncesi, başı bir mi? ..

Kaşı var, gözü var herkesin

Kimi sevdalı, kimi yâr

Mıknatısı var her sesin

Her sözün akışı bir mi? ..

El ayak var şu insanda

Sever,özler,ilgi duyar

Gezer, dolaşır her yanda

Aşkının nakışı bir mi? ..

Aşkta gün geçer sevmekle

Çeşit çeşittir arzular

Sevgi var olur emekle 

Her gözün bakışı bir mi? ..

Kimini yakar öfke, kin

Gecesi,gündüzü zarar

Kimi yaş döker çöp için

Her aşkın yakışı bir mi? ..

www.iebingül.com', 'Eline bak, ibret sunar: Beş parmağın beşi bir mi? .. Var yığın yığın insanlar Düşüncesi, başı bir mi? .. Kaşı var, gözü var herkesin Kimi se...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fani Dünya Gibi Yalansin', 'fani-dunya-gibi-yalansin-sezen-akoluk-getqc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben deniz sezen, 

her zaman sevilen, 

sevmeyide bilen, 

genede terkedilenim. 

Hatam nerde ben anliyamamisim, 

cok sevdim, cok yanilmisim, 

oda beni seviyor sanmisim, 

sadece as sözcüklerine kanmisim. 

Fani dünya gibi sende yalansin, 

Beni oyuna getiren, kukla yapansin, 

Ben onu seviyor sansin, 

Bence haline yansin.', 'Ben deniz sezen,  her zaman sevilen,  sevmeyide bilen,  genede terkedilenim.  Hatam nerde ben anliyamamisim,  cok sevdim, cok yanilmisim,  o...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fani-dunya-gibi-yalansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yürektedir; Dilde Degil', 'sevgi-yurektedir-dilde-degil-sezen-akoluk-1lfkz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gene lanet masa basindayim. 

Gene üzgün, gene bikkin durumdayim, 

Gene suskun ve mutsuzum, 

Gene kederli ve gene dertliyim. 

Beni ne zaman anliyacan, 

Ne zaman gözlerimden sevgimi okuyacan, 

Ne zaman gönlünü vereceksin, gönlümü verdigim gibi 

BEKLEMEKTEYIM. 

Sevgimi söylemem ben, 

Okumali ve hissetmelisin, 

Askimi haykiramam ben, 

Yüregini verip, yüregimi dinlemelisin. 

Cünkü sevgi dilde degil, gözde ve yürekte saklidir. 

Tipki sevgimin, dilimde sakli oldugu gibi.', 'Gene lanet masa basindayim.  Gene üzgün, gene bikkin durumdayim,  Gene suskun ve mutsuzum,  Gene kederli ve gene dertliyim.  Beni ne zaman a...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgi-yurektedir-dilde-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorular, Sorular, Sorular', 'sorular-sorular-sorular-sezen-akoluk-zw71t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Askmidir beni kovalayan, 

yoksa benmiyim aski kovalayan? 

Benmiyim ''Duydu'' ne oldugunu bilmiyen, 

yoksa duygumudur kendisini unutturan? 

Sevdamidir ölüme kadar götüren, 

yoksa ölmek icin illa sevmekmi lazim? 

SORULAR, SORULAR, SORULAR... 

AhhHH, aklimi allah bullak eden sorular...', 'Askmidir beni kovalayan,  yoksa benmiyim aski kovalayan?  Benmiyim ''Duydu'' ne oldugunu bilmiyen,  yoksa duygumudur kendisini unutturan?  Sev...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sorular-sorular-sorular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bezginim', 'bezginim-sezen-akoluk-9a9rh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bekliyorum seni gündüz ve gece, 

sayikliyorum adini her gece, 

n´olur yanimda ol bu gece, 

olamiyorsun iste. 

Gittin cok uzaklara, 

göremeyecegim diyara, 

ayrilik geldi kapiya, 

demedin “ELVEDA” 

bana bakip gidisin bana yetti, 

bu ask canima tak etti, 

arkadaslarimda gitti, 

bu hayat canimi bezdirdi…', 'Bekliyorum seni gündüz ve gece,  sayikliyorum adini her gece,  n´olur yanimda ol bu gece,  olamiyorsun iste.  Gittin cok uzaklara,  göremeye...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bezginim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Inan Sevgime', 'inan-sevgime-sezen-akoluk-4cbq8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Raki elimde, 

ismin dilimde, 

ruhun bedenimde, 

cismin gözlerimde. 

Özletiyor seni yagmurlar, 

her damle ismini harlar, 

sevdim mi daglar oynar, 

askim – askini boylar. 

Inan sana olan sevgime, 

Inanmazsan vay senin haline, 

Inandirmaliyim seni sevdigime, 

Gene inanmazsan haydi ölüme', 'Raki elimde,  ismin dilimde,  ruhun bedenimde,  cismin gözlerimde.  Özletiyor seni yagmurlar,  her damle ismini harlar,  sevdim mi daglar oy...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/inan-sevgime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-necip-fazil-kisakurek-8m3cj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölecek miyim, tam da söyleyecek çağımda

Söylenmedik cümlenin hasreti dudağımda...', 'Ölecek miyim, tam da söyleyecek çağımda Söylenmedik cümlenin hasreti dudağımda......', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/hasret-291-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakma Anneciğim Beni', 'birakma-annecigim-beni-feride-omur-kmbx0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Orada bir aile dramı yaşanıyordu

Hiç kimse o tarafa bakamıyordu

Herkes gözleri nemli 

Çocuğun yakarışını dinliyordu

Bırakma anneciğim diyordu hıçkırarak

Beni senden ayırma, koparma bağrından

Hadi kalk anneciğim evimize gidelim

Annesi gözü yaşlı, kalkarak yerinden

Yuvan artık burası oğul dedi

Boşunaydı yalvarışlar, ağlayışlar

Anası kararlıydı orada bırakacaktı

Çünkü üvey babası çocuk istemiyordu

Annesinin ardından çocuk öylece kalmıştı

İnanamıyordu artık yalnız olduğuna

Korkuyor, üşüyordu, annesini arıyordu

Neredeydi annesi, o oğlunu üşütmezdi

O gece bir karyolada tek başına

Sabaha kadar titredi

Evi, yuvası burnunda tütüyordu

Ama biliyordu artık dönemezdi

O minicik yüreği acıyla katılaştı

Nefret duydu onu bırakan anasına

Çünkü anası koca yüzünden 

Onu yuvaya bırakmıştı...

Terler içinde uyandı adam

Senelerdir değişmiyor

Her gece aynı düşü görüyordu

O gün; 

Annesinin onu bıraktığı gün

Hafızasına kazınmıştı.

Dönüp yanında uyuyan karısına baktı

Sonra içinden gelen sevgiyle

Sımsıkı sarıldı, karısı anlamıştı

Kocası yine kabus görmüştü

Sakinleş dedi usulca, sakinleş

Ben buradayım yanındayım

Sevgiyle baktı karısına

Sonra alnından öptü onu

Ve teşekkür etti

Çocuklarını bırakıp gitmediği

Kendisini sevdiği için

Onların çocukları mutlu olacak

Asla kabus görmeyecekti

Çünkü; 

Anneleri hep yanlarında olacaktı...

Feride ÖMÜR

Deli Mavi Sevdalar Grubunun ''SOKAK ÇOCUKLARI VE KİMSESİZ ÇOCUKLAR''

konulu şiir yarışması için yazılmıştır.', 'Orada bir aile dramı yaşanıyordu Hiç kimse o tarafa bakamıyordu Herkes gözleri nemli  Çocuğun yakarışını dinliyordu Bırakma anneciğim diyord...', ARRAY['Türk Edebiyatı','Şiir','Feride Ömür']::text[], 8.5, '{"poet":"Feride Ömür","poet_slug":"feride-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/birakma-annecigim-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Gecikme', 'i-lk-gecikme-adem-tok-rr61l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'senden kopmak için 

ille mazgallı kapımın sürgüsünü

çözmem gerekmez

adımlarını bilmemek (senli benli olan yollarına dökülen)

gözlerindeki ifadeyi es geçmek

hatta başka bir diyarı düşünmek dahi

senden kopmak demektir

senden kopmak için 

ille bir dış etki gerekmez

kısarım kandilimi

çekilirim köşeme

yalnız sen görürsün beni

kaldırıp yere vurmak

nede kolay

bir çerçeveyi

ben seni bulana kadar

kaç dil yor(ul)  dum

heyula çıkmazıydı hep çoğu

duvarları kimse anlamıyor

kendini ören yosundan başka

ben anladım; 

arkadaşı umut

kuzguncuğa yaslanan

senden kopmak için

elveda demem gerekmez

geç kalırım

-söz verilmiş- buluşmaya

(26.06.04)

f tipi hapishane EDİRNE', 'senden kopmak için  ille mazgallı kapımın sürgüsünü çözmem gerekmez adımlarını bilmemek (senli benli olan yollarına dökülen) gözlerindeki if...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ilk-gecikme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram gülüşlerinizi savurun ve gülümseyin...', 'bayram-guluslerinizi-savurun-ve-gulumseyin-tulay-eker-ozcml', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Müslümanların iki büyük bayramından biri.Ramazan bayramı Kameri takvime göre Şevval ayının ilk

üç günü, Kurban bayramı ise Zilhicce ayının onuncu gününden itibaren dört gün süreyle kutlanır.

Resulullah (s.a.s)  Medine''ye hicret ettiği zaman Medinelilerin eğlenip neşelendigi iki bayramları vardı. Hz.

Peygamber Medinelilere özgü olan, cahiliye izleri taşıyan bu bayramların yerine bütün müslümanların sevinip 

eğleneceği İslâm''In iki bayramını onlara haber verdi: ''Allahu Teâlâ size, kutladığınız bu iki bayramın yerine,

daha hayırlısını, Ramazan bayramı ile Kurban bayramını hediye etti'' (Sünen-i Ebû Dâvud, Salat, 239) . 

Birlik ve beraberlik amaç olan bayramlarımızda dost ve akrabalar ziyaret edilir,çocuklar sevindirilir,ziyarete gelenlere

önceden hazırlanan tatlı ve şeker verilir.Bu sebeple Ramazan Bayram''ının diğer adı da Şeker Bayram''ı dır.

Bayram sabahında erken kalkmak,duştan sonra güzel kokuları sürmek,en güzel elbiselerimizi giymek,bayram neşesi

ve sevinciyle coşmak,Allah''ın verdiği nimetlere şükretmek dinimizin güzel gördüğü hususlardır.Her ne kadar bulunduğumuz

durum ve olanaklar gölgelemeye çalışsa da bayram en güzel gülüşü ile karşımızdadır.

Hani bayramdan bayrama gördüğümüz büyüklerimizden ziyade bir cam şekerde bulduğumuz o mutlu

bayramları anlatmak istiyorum.Çocukların gözlerinde gördüğüm gerçeğin ta kendisini.Zaman zaman bayram coşkusunun

yanında coşkunun kardeşi hüzün geliyor hemen yamacıma.Büyüdükte neler kaybettik? Büyükte olsak içimizde birşeyler kıpırdamalı.

Beyin fırtınası yapılabilir neden mutlu olamıyoruz? Nedir bizi mutluluğa,coşkuya karşı çekimser yapan? 

--Bence beklentilerimiz arttı,mutlu olmak için daha büyük beklentilerimiz var.Daha madesel,araba,villa vs...

Halbuki sabah kalktığımda günes daha doğmadan dışarı çıkıp temiz birnefes almak bile bir mutluluk kaynagı idi.

İnsan doğadan koptukça mutlulugunu kaybediyor.Doğu inancında prana diye tabir edilen bir sey var soluduğumuz havanın

icinde bize hayat, mutluluk veren seyin bu olduguna inanırlar.

Ben cocukluğumu çok net hatırlıyorum.Dört beş evin içinde bulunduğu bir mezrada yaşardık.Köy bile değildi,sabahın köründe kalkar

abdest alır,sabah namazımızı kılardık.Annem sabah namazı kılmadan bayram namazı kılınmaz derdi.

Kahvaltıda yapmazdık,en guzel kiyafetleri giyer babamla birlikte en yakin caminin oldugu kÖye giderdik traktÖrle,

babam harçligimizi verirdi bayram çıkısı gördügümüz herkesle bayramlasırdık bizim yörede hala devam eder bu alışkanlık

her cami çıkışı bekler bayramlaşmak icin sonra akrabaların, komsuların evleri dolaşılırdı ve tabi şehirde oturan tüm

akrabalar köye gelirdi onlarla da karşılaşma vesilesi olurdu.

___ Bunlara hala sahibiz ve yaşatıyoruz ne güzel.Dalıyorum bazen metrolpolleşme mi bizi daha mekanik hale getirdi? 

Hatırlıyorum da bayram günleri kapı zilinden oturamazdık çocuklar ellerinde torbaları ile biri gider biri gelirdi.O zamanlar

evin küçüklerini yollardım komşu evlerine bayramlaşmaya dönüşte şekerlerle gelirlerdi.Hemen şekerleri şekerliğe koyardım,

gelen çocuklarımızı boş çevirmeyeyim diye.Şimdi ise şekerliğimde en güzel çukulatalar,şekerler mevcut ama kapı zilim susmuş.

Geçen sene ilk kez 3 tane çocuk geldi kapıma sevincimi görünce şaşırdılar.Sarıldım, öptüm hazırladığım mendil ve şekerleri

verdim.O anı o tadı anlatmamın mümkünü yok.Ben bu yaşadığım sevinci özledim.

Ve...

Çocuk gözlerde...Çocuk yüreğinde yaşanır en güzel mutluluklar. 

Bayramların anlamını,önemini sayılı günlere bağlamadan hergünümüzün bayram neşesi ve dudaklarımızda bayram gülüşlerinin

yaşamasını diliyorum.İçinde bulunduğumuz şartlar ne kadar ağır olsa da birlik ve beraberlik içinde olmalıyız.Bayram günlerinde

işsizlik,yoksulluk,açlık,eşitsizlik gibi kavramları geri iteriz.Bayramın gülüşlerini savururuz birbirimize kardeşçe kucaklaşırız.

En iyi dilekleri sunarız, isteriz birbirimiz için.Neden hergünümüz bayram gibi olmasın? 

Bayramımızın,demokrasinin ve çağdaşlığın eksik olan kurumlarında giderilmesine, toplumumuzun gelir düzeyinin ve eşitsizliğinin,

düzeltilmesine,dünya halkları arasında barış ve kardeşliğin oluşumuna vesile olması ve...

Hep bir arada, sevgi dolu ve huzurlu nice bayramlar geçirmek dileğiyle,

Ramazan Bayramınız kutlu olsun! 

Bayram gülüşlerinizi savurun ve gülümseyin...

www.bolgedetufan.com', 'Müslümanların iki büyük bayramından biri.Ramazan bayramı Kameri takvime göre Şevval ayının ilk üç günü, Kurban bayramı ise Zilhicce ayının o...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bayram-guluslerinizi-savurun-ve-gulumseyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Gün', 'ey-gun-ufuk-nazim-5nc4a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gölgeler düşer saçlarına ey gün! 

Senlemi batar benimde bu tahtım? 

Göğün yüzünden bana düşen bugün; 

Saçlarımda ağaran yalağuz bahtım.', 'Gölgeler düşer saçlarına ey gün!  Senlemi batar benimde bu tahtım?  Göğün yüzünden bana düşen bugün;  Saçlarımda ağaran yalağuz bahtım....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ey-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Şiirim Sensin *', 'siirim-sensin-i-brahim-dikmen-2-o5qly', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen! 

şiirlerimde yaşattığım

sevdanla avunduğum

yokluğunda yandığım

kadınım nerdesin

Sen! 

düşlerimde ki melek

sevdamda ki emek

kalbimde bir demet

kadınım nerdesin

Sen! 

içtiğim su kadar saf

anlatmaya yetmez laf

seni sevmek suçtan  muaf

kadınım nerdesin

01/11/2005', 'Sen!  şiirlerimde yaşattığım sevdanla avunduğum yokluğunda yandığım kadınım nerdesin Sen!  düşlerimde ki melek sevdamda ki emek kalbimde bir...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siirim-sensin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 've AŞK!', 've-ask-tulay-sustam-n891e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgili Kardeşim Nuray Alper''in bugün kaydetmiş olduğu aşağıdaki şiirinden yola çıkarak karaladığım iki yorumum... 

*.....ve AŞK! 

  



Adı kalu-belâ dan konulmuş meçhûl; 

Aşk! 

Ve nâr 

Sonsuza uzanan hâr! 

Bir yok’un derinliklerinde yakalandın gözlerime... 

Boğaza düğümlenen hıçkırıklarla uyanmakmışsın 

Gecenin lacivert nöbetlerinde.... 

Masum gözyaşlarının ah’ında soluklanan 

Bir kurşundan kalma adın... 

Ne varsa titreyen sesimde 

Ve neyim dökülmüşse ateşlerin yüreğine 

Hepsi senin yâdın.... 

Hala sökülesi kalbin göğsünde 

Kan revan olmuş başım.... 

Tutuklu yakarışla çileden, 

Titreyen dudaklara konan nakış nakış hüzünden, 

Düşlerde yağmur yakan darmadağın kederden 

Kaç vebaldi aldığın? 

Allah’a yükseltirken 

Yalan mıydı aşk 

Seherlerin şahitlik ettiği çırpınışların 

Hayallerin çoğalttığı 

Bir mendilin içine mi sıkıştırılmış zamanım? 

Sahte inançları buselendirdi seni yalancı hazanların... 

Ve tuttum seni.... 

Sobelenmiş sözlerin gün çıkmazlarıymışsın... 

Görünmez duaların bitmeyen sancısı 

Sevdalı bakışların eğilmez başıymışsın.. 

Kavuşulmazlıkları oluşturan tüm nişanların 

Leke silinmez damgası 

Orta yerinde alnının.... 

Buldum seni aşk! 

Ne hazinki 

Yaşam defterinin son sayfasına gizlenmiş adın.... 

O işte; 

Anlatılmazım 

Kan kokulu bir yaprakta kalmışsın 

Bir gün; 

Gizliden gizliye yürek ağlar 

Çıkmaz sokakların gölgesinde günah solar 

Söz de susar.... 

. 

Nuray Alper

 

*****

İçimden güneşin koynundan rüzgârı almak geçiyor onu can evinden vurmak, yalnızlığı tatdırmak geçiyor... sonra rüzgârın, güneşin saçlarını öptüğü aklıma geliyor... sevenler ayrılmamalı diyorum gökyüzünü onlara bırakıp gidiyorum. 

içimden denizkızının koynundan yunusu almak geçiyor. onu mavinin derinliklerinde boğmak, kumlara gömmek geçiyor aklımdan. sonra yunusun denizkızının saçlarını ördüğü aklıma geliyor.sevenler ayrılmamalı diyorum denizi onlara bırakıp gidiyorum. 

içimden çiçeğin koynundan toprağı almak geçiyor... ayrı kaldığında kurusun, solsun ve yaprakları boynunu büksün istiyorum. sonra toprağın sevgisinin çiçeği ayakta tuttuğu, suyu ve güneşi olduğu aklıma geliyor... sevenler ayrılmamalı diyorum, gönlümün bahçesini onlara bırakıp gidiyorum. 

oysa adım aşk benim. ne rüzgârlar, ne yunuslar, ne topraklar çıktı karşıma... kâh güneş oldum, kâh denizkızı, kâh çiçek... ne var ki ne saçlarıma ne de dallarıma dokunamadılar. ben aşktım aşk... tek başına aşk... 

rüzgâr benim! ... 

aşkın türküsünü söylerim gökyüzüne... 

yunus benim! ... 

aşkın umudunu gizlerim denizin mavisine... 

toprak benim! ... 

ölümsüz aşkları gömerim göğüs kafesime... 

*****

gidersin! ... 

inceden inceye kar yağar yüreğimde ki bir avuç toprağa. erir gülüşün gözbebeğimde, göz yaşım olursun... 

gidersin! ... 

zemheriden kalma bir ayaz vurur yüreğime. üşürüm gecenin koynunda. savrulur duygularım bilmediğim bir dağın yamaçlarına. güneşim olursun sevda ateşim külünden kendini yeniden yaratır... 

gidersin! ... 

zirvede hayat seni bekler, parmak uçlarında ben... bıraktıklarından çok aldıklarındır zehir zemberek sözlerimi yakan. sözcükler girmez sırasına büyükten küçüğü alırsın... ünsüzler kervanına katarsın adımı ünün şahlanır... 

gidersin! ... 

bilmediğim sokakların kapısı açılır yüzüme... beklerim her seferinde gelecek olan sensin diye... inadına gelmezsin... açar gözlerimde kan çiçekleri... son feride söner umudumun. 

gidersin! ... 

her yolun baş ucuna yüreğimi yaslarım. yüreğimin her odası darmadağın olur yokluğunda. giderken bir sürgü çekersin gönül kapıma... gündelikçilerin yolu geçmez kapımdan. uyumazlar yüreğimin eşiğinde... bana bırakırsın sallanan dünyanın boş beşiğini. bez bebeğimi alırlar çocuk ellerimden. söndürürüm kara gözlü gökyüzünün ışıklarını... karanlığa bir mum yakarım bir ben yanarım... 

gidersin! ... 

uğruna son nefesimi tüketirim bir ''''gitme'''' sözü çıkmaz ağzımdan... 

gidersin! ... 

son durağım şiirin koynunda ölene dek uyurum sensiz...', 'Sevgili Kardeşim Nuray Alper''in bugün kaydetmiş olduğu aşağıdaki şiirinden yola çıkarak karaladığım iki yorumum...  *.....ve AŞK!     Adı ka...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/ve-ask-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-abdullah-yasar-erdogan-o09e8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'DUA

Ahkemu’l-Hakimin, olan Sen,

Ezeli ve ebedi olamayan ben,

Geleceği ve geçmişi bilen Sen,

Yoluna baş koydum, affet beni.

İtikaf’a* çekilip sinemi Sana açtım.

Çeşmi a’ladan nurunla yıka beni.

Beşer kalbim dayanmaz, yılgınım.

Esaretinden saadete eriştir beni.

Abd-ı memluk’um* ez bu bedeni,

Adem-i külli* et  ademler içinde.

Her hücreme doldur ki sevgini,

Kendimi bulayım, benler içinde.

Bedbinlikten bu nefsimi kurtar.

Cisr-i Cehennem’de yol et beni.

Hakk yolunda canın ne önemi var.

Binler içinde yok et benliğimi.

Ulvi bir yol eri olarak al canımı,

Her nefeste uyandır bedenimi.

Benim kaleme bayrak et davamı,

Benlik içinde, hep erit benliğimi.

Ahkem’l-Hakimin: Hükümdarların hükümdarı, hâkimlerin hâkimi olan Allah. 

İtikaf: inzivaya çekilip devamlı ibadetle meşgul olmak.

Abd-ı memluk: Kul, köle

Adem-i külli: tam yokluk.

Bedbin: Karamsar, her şeyi kötü gören

Cisr-i Cehennem: Cehennem köprüsü.

Abdullah Yaşar Erdoğan', 'DUA Ahkemu’l-Hakimin, olan Sen, Ezeli ve ebedi olamayan ben, Geleceği ve geçmişi bilen Sen, Yoluna baş koydum, affet beni. İtikaf’a* çekilip...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dua-126-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Olmak', 'adam-olmak-kemal-turk-f1ero', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat bazen gözyaşlarını akıtmaktır toprağa

Hayat bazen düşmanını basabilmektir bağrına kardeşçesine

Hayat bazen egoizmin sınırlarını aşmak demektir.

Bazen üç lokma ekmeğe katık etmektir zeytini

Aç yatıp, aç kalkmaktır bazen de

Bazen, lüks otellere gidip konaklamak

Operaya gitmek,

Puro içmek…

Hayattır işte madalyonun iki yüzü gibi 

Bir bakarsın cennete girmişsin

Bir bakarsın cehennem ateşinde kavruluyorsun

Ama her şeye rağmen adam gibi olan insan

Ne idim, ne oldum, ne olacağım diyebilendir', 'Hayat bazen gözyaşlarını akıtmaktır toprağa Hayat bazen düşmanını basabilmektir bağrına kardeşçesine Hayat bazen egoizmin sınırlarını aşmak ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Türk']::text[], 8.5, '{"poet":"Kemal Türk","poet_slug":"kemal-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/adam-olmak-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '@ Halayık @', 'halayik-sanem-deniz-rt334', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Durulanıp

nikahlanacağım kalemine,

Neşter atacağım

utangaç gülücüklere,

Katışıksız katacağım 

mavileri gölgeme,

Düşeceğim balkabağına

dönüşmeden gecene...

................................Bekle!', 'Durulanıp nikahlanacağım kalemine, Neşter atacağım utangaç gülücüklere, Katışıksız katacağım  mavileri gölgeme, Düşeceğim balkabağına dönüşm...', ARRAY['Türk Edebiyatı','Şiir','Sanem Deniz']::text[], 8.5, '{"poet":"Sanem Deniz","poet_slug":"sanem-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/halayik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasaplık Şiir', 'kasaplik-siir-ahmet-tevfik-ozan-u9kn5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ya bir sığır ahırı, ya bir kuş kafesidir

Bir kelebek misali, beslediğin bu ceset...

