INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalpsizler Şehri', 'kalpsizler-sehri-ahmet-tevfik-ozan-lakux', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir parke taşı, bir,gün 

En zor şey bu alemde 

Kalbi, taşımak; dedi..

Ve içinden gelerek

Bu şehirde olmanın

Sevincine, şükretti! ..', 'Bir parke taşı, bir,gün  En zor şey bu alemde  Kalbi, taşımak; dedi.. Ve içinden gelerek Bu şehirde olmanın Sevincine, şükretti! .....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kalpsizler-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemin Günahı', 'kalemin-gunahi-ahmet-tevfik-ozan-lp3ch', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu kalem, senelerce; yalan akıtmış meğer..

Leyla, bir avuç toprak; günahkar ayaklarda..

Tartıda,sevgililer..belki, yıldızlar değer! ...

O toprak, bu da toprak.. farkı ne, mısralarda? ! ...', 'Bu kalem, senelerce; yalan akıtmış meğer.. Leyla, bir avuç toprak; günahkar ayaklarda.. Tartıda,sevgililer..belki, yıldızlar değer! ... O to...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kalemin-gunahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Bir Yaşanmışlıkta Çağlayan Sonat', 'kirik-bir-yasanmislikta-caglayan-sonat-atilla-guler-9fgwo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'paslı zincirlerin halkalarını birleştirdikçe ortaya çıktı siyah

sildikçe ıslak lekesi bulaştı beyaza kirli akşamların

akşam üstlerine yıkıldı sıkılganlığın kokusuna yatmış ölüm

aptalı oynamak düştü masumiyete rol dağılımında

durağında bekleyen son yolcu yine sabırsız/yine şaşkın

inende bir tokat gibi patlıyor gerçeğin yavşak soğukluğu

illet bir hastalık oldu puslu günlerde fotoğraflara sarılmak

ortalıkta bir küf kokusu

gergefine bir kurban daha işle kader/ağ senin ellerinde

tutuklu sözcükler diken üstünde/ha koptu ha kopacak fırtına

diline dolanan bir şarkıda öldü sevgili

aşk hep yapar bunu

gelir/gider

gider/gelir

dinginliğimi hoş görme

hor kullanma yüreğimin ıssızlığını

yüreğine sar korkunun en vahşi tarafını

susarım…sustukça haykırırım

sezemezsin

çığlıklarım ulaştıkça semaya

utanırsın

varsa yüzün

bakamazsın bir daha

bir daha oyuncak olmaz bu yalnız yılan kollarında

yıkılır kalır bir sarhoş şiirin kaldırımına

kaldıramaz kimse

uyur

bir daha uyanmasa da

siler kırmızıyı şiirlerden

maviyi koyar bağrına

siyaha boyar duvarlarını dünyanın

yatar

aptalı oynar

inanırsın

yırtılır yasak düşlerin sakıncalı sevişmeleri

uçar

uçar

kanatsız…göremezsin

bir travma sonrası

yok olur beden

ruh dağılır sonsuzda

biz artık burada yaşamıyoruz

ağla…', 'paslı zincirlerin halkalarını birleştirdikçe ortaya çıktı siyah sildikçe ıslak lekesi bulaştı beyaza kirli akşamların akşam üstlerine yıkıld...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kirik-bir-yasanmislikta-caglayan-sonat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede Bugün', 'nerede-bugun-suleyman-zaman-vmh8l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İyilik yaparım, görmem karşılık

Hani can dostlarım, nerede bugün

Vurgunum sinemden, kanadım kırık

Hani dost bildiğim, nerede bugün

Poyraz gibi esti, kavurdu teni

Dosttan ayrılanın, artar miheni

Mihriban olanın, vardır seveni

Sevdiğim diyenler, nerede bugün

Ölmüş be insanlık; önde menfaat

Sıkıntı veriyor; dakika, saat

Doyurmaz ki karın; boşuna vaat

Hep akıl verenler, nerede bugün

Anlamıyor bile; en yakınlarım

Düşman kesiliyor, bazen canlarım

Dinmez göz yaşlarım, içten ağlarım

Hani sırdaşlarım; nerede bugün

Çok acılar çektim, ömrüm boyunca

Dostlar dostluğuna, sınır koyunca

Çokluklar içinde, yalnız kalınca

Sorarım canlarım,  nerede bugün

Miskin olup çaba, göstermeyince

Oturup tembelce, üretmeyince

Sana hep gelene, sen gitmeyince

Gönüller sultanı, nerede bugün

Mitlerden uzağım, gerçektir tezim

Doğruca yaşarsan, izlenir izin

Yanlış yapma sonra, bilinir bezin

Hani gerçek dostlar, nerede bugün

Yalnızdır Zamanım, yoktur soranı

Sevmedi yalanı, riya olanı

O değersiz görür, hatır kıranı

Hani gerçek dostlar, nerede bugün

                    01.11.2005

                            Mihen; sıkıntı, eziyet

                            Mihriban; Güler yüzlü, yumuşak huylu.', 'İyilik yaparım, görmem karşılık Hani can dostlarım, nerede bugün Vurgunum sinemden, kanadım kırık Hani dost bildiğim, nerede bugün Poyraz gi...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/nerede-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güze Düşen Aşk', 'guze-dusen-ask-yunus-yakup-x06eg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçlarını bana bırak dokunacak bir şeylerim olsun

İşte bu efkarımın dumanı parmak uçlarımın rengi

Şu kendime dönmüşlüğüm kadar  asi bir şeylerim olsun 

Dilimi bağlayan deniz dudaklarımda öpücük içimdeki sıcaklık

Yağmurlu bir günün ılık esmerliği kahvenin fincanda buğusu

Belli belirsiz adımların ürkek ritimleriyle yürünen yol

Tenime dokunan rüzgar gözlerime tutunan ışıltı

Ellerini bana bırak gelincik kokulu akşamlarım olsun

Sen diyebilmek için okunan şiirler ve şarkılar

Şarap kadehiyle yıkanan ağızlar kelimeler

Gidebilecek misin  gideceğin yer neresi

Bunu ne zaman düşünsem hep bir uykudan uyanış

Her şekilde önüme durur gülün pembesi

Gülüşlerimi yıka ki anacak günlerim özlemlerim olsun

Matemini indiğinde  kuş sürülerinin yorgunluğu gibi gece

Hayali yalan olmayan sarılış omuza konan baş

Çocuk heyecanında sabırsızlık yüreğin titremesi

Seni ey seni güze adadığım yalnız imgeler soyunan kadın

Kendini bana bırak bana bırak ki üşüyecek bir şeylerim olsun', 'Saçlarını bana bırak dokunacak bir şeylerim olsun İşte bu efkarımın dumanı parmak uçlarımın rengi Şu kendime dönmüşlüğüm kadar  asi bir şeyl...', ARRAY['Türk Edebiyatı','Şiir','Yunus Yakup']::text[], 8.5, '{"poet":"Yunus Yakup","poet_slug":"yunus-yakup","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/guze-dusen-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Labirent', 'labirent-asli-ozer-ab3ea', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerim kanıyor,

Dikenli gülleri koklamaktan.

Yazılarıma kan damlıyor,

Kanlı ellerimle yazmaktan.

Hep meşgulüm,

Zihnimde bir labirent

Dolanıp duruyorum

Bulamıyorum üzgünüm.

Kapalı yolların peşinde

Bir ses duyarım 

Hep beni çağıran

Ah keşke derim,

Karanlıktan korkmasam.

2005-Samsun', 'Ellerim kanıyor, Dikenli gülleri koklamaktan. Yazılarıma kan damlıyor, Kanlı ellerimle yazmaktan. Hep meşgulüm, Zihnimde bir labirent Dolanı...', ARRAY['Türk Edebiyatı','Şiir','Aslı Özer']::text[], 8.5, '{"poet":"Aslı Özer","poet_slug":"asli-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/labirent-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya, dünya', 'dunya-dunya-suleyman-zaman-eck2f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya gerçek, yaşam fani

Yaşayanlar nerde hani

Maddeler var, gani, gani

Sonsuzsun sen, koca dünya

Dünya sen de, kavranansın

Kanan seni, yalan sansın

İnsanlara, büyük hansın

Dünya, dünya; yüce dünya

Varlığından, kimlik buldum

Tüm varlıktım, bir ben oldum

Bir bedene; girdim, doğdum

Var edensin, beni dünya

Özneye sen, görünensin

Akıl ile, sorulansın

Kızılınca, sövülensin

Dünya, dünya simge dünya

Sonsuz huzur, var oldu mu? 

Gelen burda, hiç kaldı mı? 

Kendi özün, kavradı mı? 

Bilinmeyen oldun dünya

İvme bulmuş, hep dönersin

Sonsuzluğa, devinirsin

Zaman gelir sen sönersin

Ölümsüzsün koca dünya

Karşıtlık var, her şeylerde

Uyumsuzluk var evrende

Yokluk, varlık; her bir yerde

Kuralcısın sende dünya

Zamanım der ben dünyayım

Ölsem özde, de sendeyim

Yoklukta bile, vardayım

Sonsuzlukta varım dünya

                               		01.11.2005', 'Dünya gerçek, yaşam fani Yaşayanlar nerde hani Maddeler var, gani, gani Sonsuzsun sen, koca dünya Dünya sen de, kavranansın Kanan seni, yala...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dunya-dunya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Değil misin?', 'sen-degil-misin-dursun-elmas-mj54d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün beni terk edip 

Gider misin zamansız. 

Nasıl yaşarım sensiz 

Bilmez misin izansız 

Sen; 

___aşkımın hikâyesi 

Sen; 

___yaşamamın gayesi

Sen; 

___ruhumun günvencesi

Sen! Sen değil misin? 

Kırıp  dalım, yaprağım 

Koyar mısın dermansız 

Bir çırpıda ömrüme

Kıyar mısın fermansız? 

Sen; 

___aşkımın hikâyesi 

Sen; 

___yaşamamın gayesi

Sen; 

___ruhumun günvencesi

Sen! Sen değil misin? 

01.11.2005



NOT:Şiir şarkı sözü olarak yazılmıştır.Nakaratı ''SEN''li kısımdır.', 'Bir gün beni terk edip  Gider misin zamansız.  Nasıl yaşarım sensiz  Bilmez misin izansız  Sen;  ___aşkımın hikâyesi  Sen;  ___yaşamamın gay...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-degil-misin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Gözlüm', 'deniz-gozlum-asli-ozer-dwbpg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mavi gözlerinin kıyısından döndüm.

Ürktüm,

Çünkü küskündüm.

Ah deniz gözlüm

Bilmezsin,

Bu sularda daha önce de yüzdüm.

2004-Samsun', 'Mavi gözlerinin kıyısından döndüm. Ürktüm, Çünkü küskündüm. Ah deniz gözlüm Bilmezsin, Bu sularda daha önce de yüzdüm. 2004-Samsun...', ARRAY['Türk Edebiyatı','Şiir','Aslı Özer']::text[], 8.5, '{"poet":"Aslı Özer","poet_slug":"asli-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/deniz-gozlum-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-derya-aslan-illi8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açtı avuçlarını yer yüzü 

Akıttı yüreğini gök yüzü

Ve tüm evrenin güldü yüzü

Sen yüreğime sefa geldin', 'Açtı avuçlarını yer yüzü  Akıttı yüreğini gök yüzü Ve tüm evrenin güldü yüzü Sen yüreğime sefa geldin...', ARRAY['Türk Edebiyatı','Şiir','Derya Aslan']::text[], 8.5, '{"poet":"Derya Aslan","poet_slug":"derya-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hosgeldin-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçınılmaz', 'kacinilmaz-fatih-kuyucu-iz7e4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çekilirken düşüncelerim

Zihnimin en ücra köşesine

Alışıyorum yokluğun soğuk kollarına

Karantinaya verdim sevgimi

Ölümle eşleşsin diye', 'Çekilirken düşüncelerim Zihnimin en ücra köşesine Alışıyorum yokluğun soğuk kollarına Karantinaya verdim sevgimi Ölümle eşleşsin diye...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kuyucu']::text[], 8.5, '{"poet":"Fatih Kuyucu","poet_slug":"fatih-kuyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kacinilmaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-fatih-kuyucu-uruaj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlamsız bir muamma

Çıkışsız bir sokak

Sokakta bir bank

Bankta bir kutu

Kutuda sıkışmış bir yürek

Yürekte bir iz

İzin üstünde bir yazı 

Yazı da bir şifre

Şifrede bir kilit

Kilitte bir renk 

Renkte bir anı

Anıda bir haykırış

Haykırışta bir ses

Seste bir isim

İsimde bir aşk

Aşkta bir itiraf 

İtirafta yalnızlık

Her yalnızlıkta yeni başlangıç', 'Anlamsız bir muamma Çıkışsız bir sokak Sokakta bir bank Bankta bir kutu Kutuda sıkışmış bir yürek Yürekte bir iz İzin üstünde bir yazı  Yazı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kuyucu']::text[], 8.5, '{"poet":"Fatih Kuyucu","poet_slug":"fatih-kuyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/oylesine-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 62', 'resaran-siir-ve-beyitsiler-62-huseyin-avdic-8eap5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Allah Der:

