INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can', 'can-osman-nuri-ozpekel-74mob', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkın ne güzel tarifi oldun bana sen can

Şi’rinle güneşler gibi doğdun yine sen can

Sevmek ve sevilmek bana nefret veriyorken

