INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satıyorum Yalnızlığı', 'satiyorum-yalnizligi-mahzun-doga-552jc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'satıyorum yalnızlığı

bir şiir, bir şişe şarap

ve bir de

