INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeryüzü Hepimizin', 'yeryuzu-hepimizin-ahmet-guven-cglpr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Değirmeni dönderen biz

Kaymağı yiyen siz

Hep size rap size

Varmı öyle yağma 

Dünyanın bütün güzelliklerini paylaşacağız

Sökeceğiz sınır boylarında

Mayınları,namluları

Gül ekeceğiz

El sıkışacağız

Yok öyle

Saltanatınız için savaşlar

Kan ve gözyaşı istemiyoruz

Yemezler

Siz binlerle

Biz milyarlarla

Yeryüzü hepimizin

İnsanca', 'Değirmeni dönderen biz Kaymağı yiyen siz Hep size rap size Varmı öyle yağma  Dünyanın bütün güzelliklerini paylaşacağız Sökeceğiz sınır boyl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeryuzu-hepimizin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittim', 'gittim-hasan-kostak-ofm84', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani şu cekip gitme zamanları olur ya

Çekip gittim buralardan

Buralar nerelerdi

Yaşadım başka şehirleri

Yalnızdım hep gitmelerimde

Kişi ve aklımdakiler hep buralarda kaldı

Geri döndüm başlangıç noktama

Anladım çekip gitmelerin başlangıcı

Geri dönüşün geri sayımıymış her seferinde

29.02.2004

Ankara/Kızılay', 'Hani şu cekip gitme zamanları olur ya Çekip gittim buralardan Buralar nerelerdi Yaşadım başka şehirleri Yalnızdım hep gitmelerimde Kişi ve a...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kostak']::text[], 8.5, '{"poet":"Hasan Kostak","poet_slug":"hasan-kostak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gittim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-ahmet-guven-7tiz9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bir şairim

Tarafım arkadaş

Emekten,eşitlikten yana

Kim vurur benim koluma zincir

Kim keser dilimi

Kardeşimdir benim

Bütün halklar

İş isterim

Aş isterim

Barış isterim

İnsanca yaşamak isterim

Tersi neyse arkadaş

Kavgalıyım

Kendi safımda

Buradayım', 'Ben bir şairim Tarafım arkadaş Emekten,eşitlikten yana Kim vurur benim koluma zincir Kim keser dilimi Kardeşimdir benim Bütün halklar İş ist...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/arkadas-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Yapraklar', 'sari-yapraklar-ahmet-guven-9w26f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Havada sarı yapraklar uçuşur

Daha Köküne düşmeden

İlk sararanlar 

İlk gidenler

Güz kapıda

Uzaktayım 

Gözlerinden uzak

Seni yaşıyorum

Traş oldum çıktım sokağa

Karıştım kalabalığa

Bir koşuşturmadır gidiyor

Bir mülteci kahvesine uğradım

Bir çay aldım

Zehir gibiydi

Muhabete baktım Geyik

Beni sarmadı

Birkaç yere daha uğradım

Belki iş bulurum diye

O da olmadı

Yasladım sırtımı bir ağaca

Havada sarı yapraklar

Ellerinden tuttuğum

İlk kadını düşündüm', 'Havada sarı yapraklar uçuşur Daha Köküne düşmeden İlk sararanlar  İlk gidenler Güz kapıda Uzaktayım  Gözlerinden uzak Seni yaşıyorum Traş ol...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sari-yapraklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sevdasına Yandığım', 'ey-sevdasina-yandigim-ahmet-guven-ih1vp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey sevdasına yandığım

Sevdan ile büyüt beni

Saçlarını okşadığım

Zülfün teline bağla beni

Bu dağları denizleri

Bu köyleri şehirleri

Gönül ister sevdiğini

Al yanında götür beni

Arıyım baldan ayrılmam

Bülbülüm gülden ayrılmam

Sevda olmuş büyür yürek

Baş ucunda söyle beni

''''2002 Global müzik''''dilimde türkü,gözümde Turna'''' 

albümünden''''', 'Ey sevdasına yandığım Sevdan ile büyüt beni Saçlarını okşadığım Zülfün teline bağla beni Bu dağları denizleri Bu köyleri şehirleri Gönül ist...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ey-sevdasina-yandigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buruk Bayram', 'buruk-bayram-mehmet-can-te3hg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her bayram buruk geçer

içimde alev alev

yalnızlık tüter

dostlar görüşürlermiş bayramda..

hepsi yalan..

dargınlar barışırlarmış bayramda..

hepsi yalan..

görür gözlerim..

yanar yüreğim

içim alev alev tüter

sahte mutlu gülücükler atılır..

birer parça çikolata dağıtılır..

herkes kendi derdinde yanar..

yaralı yürekler daha çok kanar..

aşk vurgunu

ayrılık vurgunu

hüzün dediğin şeyler

bayramda da yaşanır gider..', 'her bayram buruk geçer içimde alev alev yalnızlık tüter dostlar görüşürlermiş bayramda.. hepsi yalan.. dargınlar barışırlarmış bayramda.. he...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/buruk-bayram-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Benim Divane Gönlüm', 'hey-benim-divane-gonlum-ahmet-guven-ucx0n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hey benim divane gönlüm

Yanar oldum tüter oldum

Bir hüsnü cemale sebep

Müptelası giryan oldum

Hey aman yar aman gül aman

Gurbet elde hayli zaman

Derde düşer gezer oldum

Eğildimki gül dalına

Gül kızarmış yanağına

Daldan düşen yaprağına

Bir yanında bakar oldum

''''2002 Global müzik''''dilimde türkü,gözümde Turna'''' 

albümünden''''', 'Hey benim divane gönlüm Yanar oldum tüter oldum Bir hüsnü cemale sebep Müptelası giryan oldum Hey aman yar aman gül aman Gurbet elde hayli z...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hey-benim-divane-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlı Yüreğim! !', 'delikanli-yuregim-ali-biyikli-romantik-4udob', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tedirgin ve ürkek olabildiğince

Dem almış yılgın yüreği

Hasretler sancı olmuş uykularında

Çetin de, yaman da üstelik.

Bir de gamsız, kayıtsız dârıdünya ya

Başına taç etmeden yaşlanacaksın

Ben yaşarken, rahatsızlık olacak

Ezik bakacaksın yarınlara.

Ağır günahsın sırtımda

Delikanlı yüreğim omuzlayamadı sırlarını

Senin payına yalnızlık ve hüsran

Benimkine de yine gülümsemeler düştü … :)

 Ali Bıyıklı (Romantik)', 'Tedirgin ve ürkek olabildiğince Dem almış yılgın yüreği Hasretler sancı olmuş uykularında Çetin de, yaman da üstelik. Bir de gamsız, kayıtsı...', ARRAY['Türk Edebiyatı','Şiir','Ali Bıyıklı (Romantik)']::text[], 8.5, '{"poet":"Ali Bıyıklı (Romantik)","poet_slug":"ali-biyikli-romantik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/delikanli-yuregim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-okan-oztekin-zsnig', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi nedir bilirmisin? 

Bazen bir yudum suya muhtaç kalmaktır.

Bazen dostunu hatırlamak,bazense düşmanını bilmektir.

Sevgi insana hayat veren bir ırmaktır,sevgi dostunu o ırmakta yanlız bırakmamaktır.

Sevgi dostunun zor gününde yanında olmak,kötü gününde bir kenara atılmaktır.

Sevgi inattır.

Sevgi ölümü kesinleşmiş bir kanserlinin herdaim delice yaşama inadıdır.

Sevgi yaraları kapatmaktır.

İMKANSIZ OLSA BİLE...', 'Sevgi nedir bilirmisin?  Bazen bir yudum suya muhtaç kalmaktır. Bazen dostunu hatırlamak,bazense düşmanını bilmektir. Sevgi insana hayat ver...', ARRAY['Türk Edebiyatı','Şiir','Okan Öztekin']::text[], 8.5, '{"poet":"Okan Öztekin","poet_slug":"okan-oztekin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgi-216-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Rüzgar', 'zaman-ruzgar-ahmet-guven-82dun', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman rüzgar bende harman

Alır götürür beni

Ardım sıra özüm kalır

Bir de sende nazım kalır

Yüreğim derin bir derya

Taş attıkça bulanır

İncerekten sarar beni

Ardım sıra duru kalır

Dört mevsimin dördü resim

Her birinde tüter serim

Hey gidi geçen günlerim

Ardım sıra anı kalır

''''2002 Global müzik''''dilimde türkü,gözümde Turna'''' 

albümünden''''', 'Zaman rüzgar bende harman Alır götürür beni Ardım sıra özüm kalır Bir de sende nazım kalır Yüreğim derin bir derya Taş attıkça bulanır İncer...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zaman-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Beni de Götür', 'al-beni-de-gotur-ahmet-guven-r0uzg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bahar ne güzel gülüm

Sevda ne güzel

Elin elime değer

Yüreğime kan damlar

Sevdana ben kurban

Al beni de götür

Dağlar ne güçlü gülüm

Sevda ne güçlü

Dağlara kar düştü

Aklıma yar düştü

Sevdana ben kurban

Al beni de götür

Dilimde türkü gülüm

Gözümde Turna

Düştüm uzağa

Hasretim sana

Sar sol yanına

Al beni de götür

''''2002 Global müzik''''dilimde türkü,gözümde Turna'''' 

albümünden''''', 'Bahar ne güzel gülüm Sevda ne güzel Elin elime değer Yüreğime kan damlar Sevdana ben kurban Al beni de götür Dağlar ne güçlü gülüm Sevda ne ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/al-beni-de-gotur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heryerdeyim', 'heryerdeyim-ufuk-bayraktar-5724s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerim yitirir aydınlığını bir zaman

bir garip sevdaya düşer

ağlarım.

unutma dedi dostum,

iki şehir arası karanlıktır

sular bulanıktır kış günü 

gitme...

gitme dedi babam,

sevdan esir dillere

umudun zindan olur

ay ölür, kararırsın gece vakti.

gözyaşım ardına düşer

oluk oluk akar izlerinden

gitme dedi annem.

öyle bir gittim ki; 

yüreğim zaman ayarlı...

öyle bir patladım ki; 

dağıldım dört bir yanına anadolu''nun.', 'gözlerim yitirir aydınlığını bir zaman bir garip sevdaya düşer ağlarım. unutma dedi dostum, iki şehir arası karanlıktır sular bulanıktır kış...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/heryerdeyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-recep-tuna-9jrr1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyku tutmaz beni böyle gecelerde.

Anatomilerini merak ettiğim tahta kurularının sesleri yok çünkü.

Garip isteklerim oldu ara sıra,bilirsin...

Ölmeden ölmek gibi

Ya da acı çekmeden ağlamak...

En garibi de buydu zaten,

War mıydı öyle bir hayat? 

Yaş dökmeden,

İçine akıtırcasına

We her damlada tekrar tekrar ölmek...

İşte buydu çoğunuzun hakettiği hayat.

Otur da düşün insan kılığına bürünmüş zawallı; 

Ne kadar hakettin mutlu olmayı? 

Sahibine werme zamanı gelmedi mi,

O perilerle süslü rüyaları...? 

Git we öL

Artık bu dünyada yerin kalmadı...', 'Uyku tutmaz beni böyle gecelerde. Anatomilerini merak ettiğim tahta kurularının sesleri yok çünkü. Garip isteklerim oldu ara sıra,bilirsin.....', ARRAY['Türk Edebiyatı','Şiir','Recep Tuna']::text[], 8.5, '{"poet":"Recep Tuna","poet_slug":"recep-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isyan-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece Bir Rüya Gördüm', 'dun-gece-bir-ruya-gordum-ahmet-guven-ar318', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün gece bir rüya gördüm

Takıldım rüzgarın kanatlarına

İhtiyarlığı sattım

Gençliğimi aldım yar

Dün gece bir rüya gördüm

Güneşe semah tuttum

Çirkinliği sattım

Güzelliği aldım yar

Dün gece bir rüya gördüm

Memleketime döndüm

Yoksulluğu sattım

Zenginliği aldım yar

''''2002 Global müzik''''dilimde türkü,gözümde Turna'''' 

albümünden''''', 'Dün gece bir rüya gördüm Takıldım rüzgarın kanatlarına İhtiyarlığı sattım Gençliğimi aldım yar Dün gece bir rüya gördüm Güneşe semah tuttum ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dun-gece-bir-ruya-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Uyuşmazlığı', 'hayat-uyusmazligi-ufuk-bayraktar-ft2px', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yine aynı kendini bilmez savrukluğum

     ve yine aynı hayatla uyuşmazlığım...

..............ve nedendir bilinmez tavırlarımla

yine şaşırtıyorum insanları........................', 'yine aynı kendini bilmez savrukluğum      ve yine aynı hayatla uyuşmazlığım... ..............ve nedendir bilinmez tavırlarımla yine şaşırtıy...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayat-uyusmazligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sen ve O', 'ben-sen-ve-o-begum-aysal-wkzgc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni içimde saklıyorum içimdeki gölgelerde

Ben seni gözlerinin siyahına gömüyorum siyahtaki o asiliğe

Sen en umutsuz anlarımda umudumsun sen asla yağmayacak bir yağmursun

Sen buludumsun yalnızlıklarıma gölge tutan sen asla kesilmeyen soluğumsun

O senin kıymetini bilmeyen bir mavi o aşkın maviliğini siyaha çaldıran bir asi

O bakışlarındaki derinlikte yüreğini bulamayan biri o sendeki beni göremeyen bir deli

Biz yokluklarda var olan bir sevda ve biz birbirimizdeki biz göremeyecek kadar âma 

Biz yağmurlarla kuruyan bir dünya ve biz kendimizi ayrılığın ayazına bırkan bir bela

Siz asla biz olamayacak bir yalan ve siz asla benliğini bilmeyen bir zaman

Siz birbirinizi hergün biraz daha solduran ve siz her varlıkta yoklukla kaybolan

Onlar ne sizi ne bizi bilenler ve onlar hiç doğmadan batan güneşler

Onlar her an biraz daha tükenenler ve onlar asla gerçek olamayacak bahaneler...', 'Ben seni içimde saklıyorum içimdeki gölgelerde Ben seni gözlerinin siyahına gömüyorum siyahtaki o asiliğe Sen en umutsuz anlarımda umudumsun...', ARRAY['Türk Edebiyatı','Şiir','Begüm Aysal']::text[], 8.5, '{"poet":"Begüm Aysal","poet_slug":"begum-aysal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-sen-ve-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Asla Benim Olamayacaksın', 'sen-asla-benim-olamayacaksin-begum-aysal-t6fdw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim içimde senden bir okyanus var

Bakışlarını en derin siyahına gömdüğüm

...

Benim içimde senden bir sevda var

Yokluğunda yalnızlıklarımla büyüttüğüm

...', 'Benim içimde senden bir okyanus var Bakışlarını en derin siyahına gömdüğüm ... Benim içimde senden bir sevda var Yokluğunda yalnızlıklarımla...', ARRAY['Türk Edebiyatı','Şiir','Begüm Aysal']::text[], 8.5, '{"poet":"Begüm Aysal","poet_slug":"begum-aysal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-asla-benim-olamayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-asude-gediz-sfv06', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbini gilümsetecek bir şeyler bul! ! ! ! 

gülmek karanlığı aydınlatan bir güneştir

güneş ısıtır, hayat verir, can verir...onu dinle....! ! ! ! 

Yüreğini kıpırdıyorsa eğer organın olmaktan çıkıpta kalbin olmuşsa eğer...

peşinden gir onu dinle....! ! ! ! ! 

Fırsat verme cimri feleğe

Unutma yaşamak için tek hayatın onu  yaşayamak için ise tek şansın var

Gülümse.............', 'Kalbini gilümsetecek bir şeyler bul! ! ! !  gülmek karanlığı aydınlatan bir güneştir güneş ısıtır, hayat verir, can verir...onu dinle....! !...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gulumse-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kaldırımda Yürürken Sen', 'ben-kaldirimda-yururken-sen-yakup-icik-e9nq3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaldırımda ben yaya yürürken

Karşı ki kaldırımda sen yürüyordun

İyi hatırlarım 

Yaya geçidinde

Trafik lambalarında durduk

Yeşil yandı yürüdük

Benim tarafımdan

Ben sağdan

Sen soldan

Senin tarafından

Sen sağdan 

Ben soldan birbirimize bakıştık

İyi hatırlarım göz göze çakıştık

Elinde evrak tipi çantan

Ayağında ince topuklu mor ayakkabı

Tenini sarmış

Bahar yazdan kalma çiçekli fistan

Ah bir bilsen içimi tutuşturdun selvi boylum

Yürüyüsünü sorarsan

Bugün o gün yok

O günkü halin bugün yok

O günkü varlığım bugün yok

O günler ah ah o günler

Çok iyi hatırlarım

Hayallerden başka eseri yok...', 'Kaldırımda ben yaya yürürken Karşı ki kaldırımda sen yürüyordun İyi hatırlarım  Yaya geçidinde Trafik lambalarında durduk Yeşil yandı yürüdü...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-kaldirimda-yururken-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçersin Beni', 'i-cersin-beni-yasemin-sezer-tulgar-q84sv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıcak avucunun terinde tuzlanmış balık gibi zıplarım

Döne dura

Nehirlerine yol ararım

Aktığım sazlıklardan denizine

Yüzgeçlerimle kaşırım 

Ensene vardıkça elin 

Saçlarını okşarım

Sus pus kalırsın

Anlamazsın

Sonra

Bir bakarsın zıplıyor avuç içlerinde

Bir balık ben/iz

Susarsın

Su niyetine içersin dereleri avuçlarından

İçersin beni….

04.11.05', 'Sıcak avucunun terinde tuzlanmış balık gibi zıplarım Döne dura Nehirlerine yol ararım Aktığım sazlıklardan denizine Yüzgeçlerimle kaşırım  E...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/icersin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'K...lar', 'k-lar-yakup-icik-7iwgy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimimiz,

Kimilerimizce

Konusur anlaşırız bu ayrı

Kimse

Kimseyi anlayamazsa bu önemli bir ayrı

Kimilerimiz

Konuşamadığımızdan mı sanki

Kimse

Kimseyi

Kendi gibi

Kimse hesap etmediğinden mi

Kimse anlayamaz

Kimseyi

Kendine sayğı duymayınca

Kimimiz

Kimilerince

Kimseler oluruz

Kimimizce

Kimseler

Kimseyi anlayamaz

Kim

Kimseye sayğı göstermeyince...', 'Kimimiz, Kimilerimizce Konusur anlaşırız bu ayrı Kimse Kimseyi anlayamazsa bu önemli bir ayrı Kimilerimiz Konuşamadığımızdan mı sanki Kimse ...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/k-lar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizlere Dost Tavsiyesi', 'sizlere-dost-tavsiyesi-yavuz-bayram-caliskan-2nhgh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya gözlerimde yeşillendiğinden beri bir başka iner çağlayanlar, bir başka yağar yağmurlar, bir başka aşık olurum.

Yolları, kaldırım taşlarının çiğnendiği ve yağmurların akıp gittiği meskenler bilirdim ama öyle olmadığını yıllar anlattı bana hem de yazdırdı satırlara.

Titreyişlerin ruhunuzu esir aldığı günler nelere sancılıdır bilir misiniz? 

Gurbeti, batan günlere gömen yaşlı gözler, sizleri karanlıklara götürmez mi sanırsınız? İliklerinize işleyen soğukları bile hissettirmeyenin hasret olduğunu anlamaz mısınız? 

Yüreğinizi ortaya koyduğunuzda geri alamayacağınızı bilmez misiniz? 

Yanan, kavrulan, kor olan yürekleri gönüller taşır, ruhlar taşır, can taşıyamaz.

Sabır ister aşklar, sevdalar, yıllar ister, ömür ister, bir daha geri alamazsınız.

Ağıtları, yalnızlıkları, terk edilişleri, mutsuzlukları yaşarsınız, ömür biter de anlayamazsınız.

İçtenlik, dost içindir; dost bildikleriniz için değil! Sakın karıştırmayın, dümeni kaybedersiniz.

Vakitli yaşayın her şeyi, zamanla demleyin.O zaman iyi çıkar  o demler, iyi tat verir damaklara.

Serüven aramayın, kaçırmayın mutluluğu, girin koynuna ve sabahlayın, yaşanmamış mutluluklar sizlere ders olsun. 

Şair tadında yaşayın ve sevin, sevgiden, sevdadan velhasıl dostlardan zarar gelmez.

Bir garip yaşayın ve tadında son verin baharlara…

Anlaşılmak dileğiyle…!', 'Dünya gözlerimde yeşillendiğinden beri bir başka iner çağlayanlar, bir başka yağar yağmurlar, bir başka aşık olurum. Yolları, kaldırım taşla...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sizlere-dost-tavsiyesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batı Kafası', 'bati-kafasi-yakup-icik-bmnx9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(1)

Hep kafama taktığım, bir garip baktığı bize batının

Unutmak isterim olmuşları

Olanlara takılırım, olacaklara baka baka...

Hep kafama taktığım, bir garip baktığı bize batının

Yüz yıl önce pencereden atarken bokunu! 

Şimdi bana ''pislik'' diyor

Unutmak isterim olmuşları

Olanlara takılırım, olacaklara baka baka...

Hep kafama taktığım, bir garip baktığı bize batının! 

Süslenmeyi biz doğululardan öğrendi ya dün

Elini yıkamayı, temizlenmeyi, koku sürünmeyi

Kalkmış bana ''kokuyorsun pis yabancı'' diyor

Unutmak isterim olmuşları,

Olanlara takılırım olacaklara baka baka...

Hep kafama taktığım.

Bir garip baktığı bize batının!', '(1) Hep kafama taktığım, bir garip baktığı bize batının Unutmak isterim olmuşları Olanlara takılırım, olacaklara baka baka... Hep kafama tak...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bati-kafasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kimim', 'ben-kimim-omer-yildiz-gu3fe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öncenin sonundaki

Sonranın başındki

Türk Milletinin 

Nefes alan nesliyim...

İkibinli yıllarda,

Yeni bir çağa

Damga vurmaya hevesliyim...', 'Öncenin sonundaki Sonranın başındki Türk Milletinin  Nefes alan nesliyim... İkibinli yıllarda, Yeni bir çağa Damga vurmaya hevesliyim......', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ben-kimim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-resul-ustun-rvakp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni sev öğretmenim.

Çünkü sen,

beni sevdiğin kadar öğretmensin.

Ve ben,

sevildiğim sürece severim.

Bana kavgayı ve kini değil,

bana sevgiyle bakmayı

ve insancıl olmayı öğret öğretmenim.

Uzak durma öyle.

Nolursun tiksinme benden.

ellerinle,

bilincinle,

yüreğinle

beni yeniden yarat öğretmenim.

ellerimi tut,

saçlarımı okşa.

Gözlerini gözlerimden

kaçırma nolursun öğretmenim.

Öyleki,

bakışların yüreğimi ısıtsın.

Sınıfta rehberim,

oyunda arkadaşım,

genel yaşamda onurum ol öğretmenim.

Çağdaşlıkta en önde,

sevgide 

gönderdeki bayrak ol öğretmenim.

Çünkü ben; 

senin gibi bakmak,

senin gibi gülmek,

senin gibi konuşmak,

senin gibi yürümek,

senin gibi ''adam'' olmak,

geleceğe umut olmak istiyorum.

Ne olursun,

karşımda çatık kaşlı,

ekşi suratlı,

hele hele eli sopalı

durma öğretmenim.

Sözde değil elbet,

özde rehberim ol.

Sözünle özün çelişmesin.

Dayanamam,

dayanamam öğretmenim.

Matematiği bilmezsem kızma,

Türkçe''yi biliyorum ya; 

güzel resimler yapıyorum ya,

şarkılar söyleyip,

arkadaşlarımla elele

oyunlar oynuyorum ya! ...

Ağustos Böceği ile Karınca''yı,

Kırmızı Başlıklı Kız''ı,

Keloğlan''ı,

Nasrettin Hoca''yı biliyorum ya...

Belki ileride

bilmediklerimi de öğrenirim.

Yeter ki beni sev,

beni destekle,

bana güven öğretmenim.

Sen bana,

sana güvenenler de

geleceğe güvensinler öğretmenim.', 'Beni sev öğretmenim. Çünkü sen, beni sevdiğin kadar öğretmensin. Ve ben, sevildiğim sürece severim. Bana kavgayı ve kini değil, bana sevgiyl...', ARRAY['Türk Edebiyatı','Şiir','Resul Üstün']::text[], 8.5, '{"poet":"Resul Üstün","poet_slug":"resul-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/ogretmenim-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek', 'gitmek-sinan-aydindag-12x81', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '18 ağustos 2004

                 Gitmek

Kader seni neyleyeyim

Kendi vatanımda sanki gurbet eldeyim

Yüzüme gülen dostu söylesene ben neyleyeyim

Sıkıldım bu sahtelikten gitmek istiyorum

Gitmek buralardan uzaklara

Kİmsenin ulaşamayacağı diyarlara

Sözüm bu dur dedikodumu yapanlara

Yıkıldım artık sözlerininzden gitmek istiyorum

Bu kahpelik bu sahtelik canımı acıtıyor

Yetmiş milyon insan var ama kimse duymuyor

Canım acıyor be kardeşim anla canım acıyor

Eyvallah demeden kimseye sinan 

Gidiyor..............', '18 ağustos 2004                  Gitmek Kader seni neyleyeyim Kendi vatanımda sanki gurbet eldeyim Yüzüme gülen dostu söylesene ben neyleyey...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gitmek-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yalnızsın', 'sen-yalnizsin-sinan-aydindag-eol9z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '18 agustos 2004

Yetmiş milyon içinde olsanda sen yalnızsın

Bunca zaman sevsende sen yanılmışsın

KEndini kandırmayı bırak hep sen aldanmışsın

Doğru yerde ve doğru zamanda değişlsin be sinanım

Senin gibiler tarih oldu gitti

O devirler eskidendi bitti

Sana tecrübelerin biliyorum ki yetti

Daha aldanmazsın be sinanım

Dersinki keşke sevmez olaydım

Gözlerine gözlerine bakmaz olaydım

Sonsuz uykuya dalıpta uyanmayaydım

Biterdi acıların be sinanım.', '18 agustos 2004 Yetmiş milyon içinde olsanda sen yalnızsın Bunca zaman sevsende sen yanılmışsın KEndini kandırmayı bırak hep sen aldanmışsın...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-yalnizsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son sarhoşluk', 'son-sarhosluk-sinan-aydindag-ymflg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '22 agustos 2004

Bu senin son sarhoşluğun be kardeşlik,

Tadını çıkarmaya bak

Zamansız tere dökülmüş yaprakları tekmele

İsyan et zamansız yere döküldükleri için

Sende onlar gibi zamansın döküldün çünkü

İsyan et şimdi hayatta tüm olanlara

Çünkü bu senin son sarhoşluğun be kardeşlik

Bu dünyaya zamansız gelmek senin suçun değil

Eyme başını dik tut

Sen değil be kardeşlik,bu hayat utansın

Bu hayat utansın.', '22 agustos 2004 Bu senin son sarhoşluğun be kardeşlik, Tadını çıkarmaya bak Zamansız tere dökülmüş yaprakları tekmele İsyan et zamansız yere...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-sarhosluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durdurun Akan Kanı', 'durdurun-akan-kani-hidir-altas-iawly', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Durdurun akan kanı

Analar ağlamasın

Yavrular boynu bükük

Eşler dul kalmasın

Durdurun akan kanı

Kardeş kardeşi kırmasın

Baban nerde diye sorarlarsa

Yavrucak başı eğik susmasın

Durdurun akan kanı

Babalar garip durmasın

Bacalardan tüten duman

Ocaktaki ateş sönmesin

Durdurun akan kanı

Turhani''min dünyası kararmasın

Gülsün yüzler, parıldasın gözler

Yüzdeki nur, gözdeki fer solmasın', 'Durdurun akan kanı Analar ağlamasın Yavrular boynu bükük Eşler dul kalmasın Durdurun akan kanı Kardeş kardeşi kırmasın Baban nerde diye sora...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/durdurun-akan-kani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlikte Yürümek', 'sensizlikte-yurumek-bahri-yildirim-ng5q3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun ince bir yoldayım''''

Ve öğrendim artık

Dünyanın en uzun yolu:

Kalpten beyne giden yolmuş.

Bunu; Sen anszın bırakıp gidince anladım.

Anladım yolların neden bitmediğini.

Başka başka anlamlar kazandı sevdam

Senin dönüşünü beklerken.

Düşünürüm,beklerim gelmezsin.

Bak! saniyelerde nasılda hızlı akıyor zaman? 

Sanki yüzyıllar ötesindeyim.

Yüreğim sensizliğin hüznündeyken

'''' Dudaktan kalbe'''' seni beklemekteyken.

Neresindesin sana bakan gözlerimin? 

Yürüyorum sevda denilen yolda.

Uzun uzun

İnce ince

Bu bitimsiz yollarda

Bazen sen varsın yanımda

Bazen yalnız başıma.

Geçiyor seni beklemekle günlerim.

Apansız acılar dokuyorum

Sevda yollarımıza.

Budur yani halimiz ahvalimiz.

Sensizliğin hüznünde kavrulurken yüreğim

Ben kalbimden beynime yürümekteyim..', 'Uzun ince bir yoldayım'''' Ve öğrendim artık Dünyanın en uzun yolu: Kalpten beyne giden yolmuş. Bunu; Sen anszın bırakıp gidince anladım. Anla...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sensizlikte-yurumek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmiş Birisine..', 'bitmis-birisine-melek-ozgoz-nke58', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok istedim ellerimden tut.

İçimde yaşattım hep bir umut..

Artık O'' da öldü sayende..

Şimdi sende beni unut..

O umut ki seni padişahı yaptı dünyanın 

Kalbimdeki en görkemli yeri sana verdi.

Büsbütün ışıklı bir çemberdi

Yerin hala aydınlık..

Dehşet bir rüya gibi geldin bana

Sabah uyanıpta öldüğünü görünce..

Hele birde öldüğün halde

Hala karşımda durunca..

Bambaşkaydın benim için

Dalda yaprak damarda kan gibiydin..

Çok savaştım bu işi bitirdim.

Bittiğindeyse domuz kadar çirkindin..

Sen ve umutlarım artık mazi oldu..

Yüreğim aşkından çok yoruldu..', 'Çok istedim ellerimden tut. İçimde yaşattım hep bir umut.. Artık O'' da öldü sayende.. Şimdi sende beni unut.. O umut ki seni padişahı yaptı ...', ARRAY['Türk Edebiyatı','Şiir','Melek Özgöz']::text[], 8.5, '{"poet":"Melek Özgöz","poet_slug":"melek-ozgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bitmis-birisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-hidir-altas-yd6o0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Korkutmak, sindirmek halkı

Polise, askere kurşun sıkmak

Beşikteki bebeyi kana bulamak

Buysa özgürlük istemem arkadaş

Yollara tuzak kurmak

Masum insanları kırıp, ev yıkmak

Kardeşleri öldürüp katili olmak

Buysa özgürlük istemem arkadaş

Öz vatanını gavura kötülemek

Zulüm yaparken mazlum görünmek

İşkence yaparken madur görünmek

Buysa özgürlük istemem arkadaş

Turhani der bey gibi yaşarken

Her kademede iş bulurken

Kimse bana uzak durmazken

Yalan yere özgürlük istemem arkaaadaşşş', 'Korkutmak, sindirmek halkı Polise, askere kurşun sıkmak Beşikteki bebeyi kana bulamak Buysa özgürlük istemem arkadaş Yollara tuzak kurmak Ma...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozgurluk-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sokak Çocuğu*', 'sokak-cocugu-ramazan-ates-j2dnv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Abi bana değmeyin,

Ben sokak çocuğuyum.

Abla üstün pis olur,

Çamurlu ve tozluyum.

Bende güzel anamın,

Sevinçle doğurduğu.

Belki de bir babanın,

Hayalini kurduğu.

İşte öyle bir çocuk,

Bu dünyaya gelmişim.

Adım sokak çocuğu,

Sokağı dost bilmişim.

Kimse beni görmüyor,

Devlet bile kör bana.

Ben ölmüşüm kimene,

Tinercisin der bana.

Kimimiz tiner koklar,

Ki soğuktan ölmesin.

Kimimiz kap kaç yapar,

Doğru eğri ne bilsin.

Alıpta diyen var mı? 

Bu yaptığın yanlıştır.

Açmısın soran var mı? 

Al bir lokma atıştır.

Bırak beni köşemde,

Tek kıvrılıp yatayım,

Ya al beni eğitte,

Ben de adam olayım.

Sorumluluk duyanlar,

Düşünmeli az beni; 

Doğuracak analar,

Kıymetini bilmeli.

Sokak çocuğuyum,

Ne taşım nede kaya,

Bende etten kemikten,

İnsan geldim dünyaya.

Ben sokakta doğmadım,

Doğuranlar var beni,

Sokak çocuğu adım,

Atanlara sor beni.

Ramazan Ateş/ Enschede- 31.10.2005', 'Abi bana değmeyin, Ben sokak çocuğuyum. Abla üstün pis olur, Çamurlu ve tozluyum. Bende güzel anamın, Sevinçle doğurduğu. Belki de bir baban...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sokak-cocugu-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Açan Çiçek Gibi', 'bende-acan-cicek-gibi-ramazan-ates-h9h38', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duygularım dolup taştı,

Ben seni düşünüyorum.

Gönlün benden geçip gitti,

Ben seni düşünüyorum.

Hayal misin yoksa düş mü? 

Yalan mısın, sen gerçek mi? 

Bende açan bir çiçek mi? 

Ben seni düşünüyorum.

Bende varsın benimlesin,

Yüreğinde, gönlümdesin.

Zamanlarım sende durdu,

Ben seni düşünüyorum.

Bu düşüncem arzu gibi,

Seni ister, her şeyini,

Yalnız seni ve tek seni,

Ben seni düşünüyorum,

Gülüm seni istiyorum.

Ramazan Ateş/Enschede, 1.11.2005', 'Duygularım dolup taştı, Ben seni düşünüyorum. Gönlün benden geçip gitti, Ben seni düşünüyorum. Hayal misin yoksa düş mü?  Yalan mısın, sen g...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bende-acan-cicek-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız Şiir', 'adsiz-siir-seval-cihangir-v43kb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşlerime şahitti geceler.

Ay yalınlığındaydı sevgim.

Gökyüzü yatağımdı ve

kara bulutları yorgan yaptım üstüme.

Çobanyıldızı görmedi beni.

Bir de çobanın kendisi.

Seyre daldım yeryüzünü,

dağlar üzerindeki ovalar yeşil...

gözlerin gibi.

Gözlerin görmedi beni.

Bir de gözlerin sahibi.

Billur denizler üstündeydi resmim.

Baktım,

aynaya bakar gibi.

Ne deniz gördü beni,

ne de ben denizi.

Gökkuşağının üstündeyim.

Bir yağmur damlasından kırılıp,

yansıdım semaya.

Düş bile olsa güzeldi,

ebemkuşağından seyir.

Ne ebe! gördü beni,

Ne de ben ebemi! ...

Seyre daldım alemi.', 'Düşlerime şahitti geceler. Ay yalınlığındaydı sevgim. Gökyüzü yatağımdı ve kara bulutları yorgan yaptım üstüme. Çobanyıldızı görmedi beni. B...', ARRAY['Türk Edebiyatı','Şiir','Seval Cihangir']::text[], 8.5, '{"poet":"Seval Cihangir","poet_slug":"seval-cihangir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/adsiz-siir-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni İster Deli Gönlüm.', 'seni-i-ster-deli-gonlum-ramazan-ates-flt2d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arzularım söz dinlemez,

Seni ister deli gönlüm.

Hasretine dayanamaz,

Seni ister deli gönlüm.

Hayalimde düşümdesin,

Ta şuramda içimdesin.

Düşüncemde fikrimdesin,

Seni ister deli gönlüm.

Sen aklımı aldın benden,

Şu gönlümü çaldın benden.

Uzak yakın dinlemeden,

Seni ister deli gönlüm.

Sen gönlüme sultan oldun,

Gönlümde sarayın kurdun.

Gülüm hani nerde kaldın? 

Seni ister deli gönlüm.

Yalnız seni ister gönlüm.

Ramazan Ateş/Enschede, 2.11.2005', 'Arzularım söz dinlemez, Seni ister deli gönlüm. Hasretine dayanamaz, Seni ister deli gönlüm. Hayalimde düşümdesin, Ta şuramda içimdesin. Düş...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-ister-deli-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazı Nerde', 'yazi-nerde-ramazan-ates-2sd10', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazı nerde yazı nerde? 

Okuduğun yazı nerde? 

Dört mevsimi yağmur ve kar,

Hollanda’nın yazı nerde? 

Enschede/12.08.2005', 'Yazı nerde yazı nerde?  Okuduğun yazı nerde?  Dört mevsimi yağmur ve kar, Hollanda’nın yazı nerde?  Enschede/12.08.2005...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yazi-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orda Bir Köy Var', 'orda-bir-koy-var-ramazan-ates-8qg0n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ORDA BİR KÖY VAR

Bakın gardaş neler oldu,

Hollanda’da bir köy vardı.

Ömer Kadan* onu buldu,

Buldu dünyaya duyurdu.

Televizyon ile gittim,

Gittim Türkiye’yi gördüm.

Gittigime mutlu oldum,

İnan orda huzur buldum.

Küçük bir köy Hollanda’da,

Osmanlı’dan kalma oda.

Gezip görmek gerek gardaş,

Türkü yaşatmalı orda.

İnsanları sıcak kanlı,

Türk’den eser kalmış belli,

Nasıl anlatmalı, ne demeli,

Gidip görün Türkiye’yi,

Bakıp görün Türkiye’yi.

Ramazan ATEŞ/Türkiyeköyü-Hollanda 10.09.2000

*  Ömer Kadan, Hollanda’da yaşayan, 45 yaşında gözleri görmeyen bir ozanımızdır. Kendisi hakkında bilgi için www.omerkadan.nl  sitesine bakınız.', 'ORDA BİR KÖY VAR Bakın gardaş neler oldu, Hollanda’da bir köy vardı. Ömer Kadan* onu buldu, Buldu dünyaya duyurdu. Televizyon ile gittim, Gi...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/orda-bir-koy-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedidir Kedi', 'kedidir-kedi-vedat-okkar-p19wa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceleri tıkır, mıkır 

Sesler geliyor bir yerlerden, 

Pencereden baktığımda, 

Ufak tefek gölgeler. 

Gölgeden seyrederim geceleri onları, 

Hiç durmadan sağa sola zıplamaları, 

Biri birinin üstünde, 

Ne yapıyorlar acaba, 

Sesleri çoğaldı kavgamı ediyorlar galiba, 

Öteki sırtını döndü kızdı ona bu defa, 

Kim ki bunlar geceleri meydanda, 

Çözemedim bir türlü tıkır mıkır yukarda. 

Gün doğdu komşu geldi, 

O ses sizdenmi diye seslendi, 

Ben bilmiyorum teyzecim, 

Onlar bence kedidir kedi...', 'Geceleri tıkır, mıkır  Sesler geliyor bir yerlerden,  Pencereden baktığımda,  Ufak tefek gölgeler.  Gölgeden seyrederim geceleri onları,  Hi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kedidir-kedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende benim için herkez gibisin', 'sende-benim-icin-herkez-gibisin-vedat-okkar-nlu4g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim bilir nerde yatıyor bedenin, 

Kim bilir kimin için atyor kalbin, 

Kim bilir kimlere bakıyor gözlerin, 

Artık sen''de benim için her kez gibisin. 

Hatıralar gözümde canlandı birden, 

Gözümdeki yaşların akması neden, 

İçimde büyük bir sızı, senden, 

Artık sen''de benim için herkez gibisin. 

Bana kalleşliği yaptığın o gün 

Hayat yolumuz ayrıldığı gün, 

Kalbime hançeri sapladığın gün, 

Senin gibi artık hepsi dün. 

Dün''ümle yaşamam, Bugünle varım, 

Yarınlara umutla bakarım, 

Yoluma bir daha çıkmamalısın, 

Artık sen''de benim için herkez gibisin.', 'Kim bilir nerde yatıyor bedenin,  Kim bilir kimin için atyor kalbin,  Kim bilir kimlere bakıyor gözlerin,  Artık sen''de benim için her kez g...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sende-benim-icin-herkez-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün benim ol', 'bir-gun-benim-ol-vedat-okkar-ujc0h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birini sevmişsin deliler gibi, 

Yıkmış bu aşk seni hemde yıpratmış, 

Verdiğiniz sözler mazide kalmış, 

Nerede o mutlu günlerin hani. 

Geçmişle yaşanmaz bugününe bak, 

Sözünü tutmayan o idi sen yaşamına bak, 

Seni seven birini al kollarına tak, 

Mutluluğu benimle yaşamalısın. 

Korka aşkımdan sana zarar gelmez, 

Aşkım deyişin güldürür beni, 

Benim olmasanda severim seni, 

Sen mutlu ol bana buda yeter. 

Gülüşün yokmu beni bitiren, 

Diyardan, diyarlara götüren, 

Çaresiz bırakma sevdiğim beni, 

Mutluluk adına bir gün benim ol.', 'Birini sevmişsin deliler gibi,  Yıkmış bu aşk seni hemde yıpratmış,  Verdiğiniz sözler mazide kalmış,  Nerede o mutlu günlerin hani.  Geçmiş...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gun-benim-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıpır Kıpır', 'kipir-kipir-vedat-okkar-zaboz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim içim kıpır,kıpır, 

Kalbimdeki sensin çıtır. 

Elimde bir çiçek, 

Sana vereceğim günü bekleyecek. 

Yüreğimde bir güzel yatar, 

Bu gözler yanlız sana bakar. 

Mutluluklar sevgi ile başlar, 

Gönüller sevgiyi arar, 

Bu kalp bir tek senin için atar, 

Gözlerim uykuya seninle dalar, 

Güzeller güzelim umudum çoktur, 

Sana karşı hislerim budur', 'Benim içim kıpır,kıpır,  Kalbimdeki sensin çıtır.  Elimde bir çiçek,  Sana vereceğim günü bekleyecek.  Yüreğimde bir güzel yatar,  Bu gözler...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kipir-kipir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-vedat-okkar-f13bs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel bakalım, beklediğim gün 

Acıyı kederi terkettiğim gün, 

Kendimi senin için yok ettim ben dün, 

Gözyaşlarımı geride bıraktım bugün. 

Senin için ömrümü bitirmişim ben, 

Benim için oysaki ne yaptın ki sen, 

Çaresizlik içinde yokluğum neden, 

Beni üzen sevdayı bıraktım bugün. 

Mutluluğu bir gün bulurum elbet, 

Beni artık kalbinden yok et, 

Yarınlar için vedat''ım sabret, 

Yokluğumu geride bıraktım bugün. 

Bir garip sevdaydın üzüntü dolu, 

Elbet bitecek ti dikenli sevdanın yolu, 

İşte bugün bu aşkın sonu, 

Hayata sıfırdan başladım bugün 

Çürüttüğün gönlümü sularım yeniden, 

Gönlümde bir toğum yeşerdi birden, 

Senelerce yok olmuşum senin yüzünden, 

Hayatıma yeni bir sayfa açtım ben bugün', 'Gel bakalım, beklediğim gün  Acıyı kederi terkettiğim gün,  Kendimi senin için yok ettim ben dün,  Gözyaşlarımı geride bıraktım bugün.  Seni...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bugun-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rekabet! !', 'rekabet-zulfikar-yapar-kaleli-5o9n4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayaller gülümser hülyalarımda

Tutsak eller hür doğanın rakibi

Keklikler tedirgin kayalarında

Guguk kuşu saksağanın rakibi

Aslından ziyade bodur ekleri

Sığırcıklar mesken tutmuş gökleri

Dayılılar hor görüyor tekleri

Çulsuz çoban  üç ağanın rakibi

Züğürdün rüzgarı akşamdan eser

Bir hoyrat dal diye kökünü keser

Serçe feryat eder serkeş gülümser

Kara karga ak doğanın rakibi

Emeksizler emekleri yediler

Bir adım ileri götürmediler

Üstelik de kimin hakkı dediler

Şu sarımsak şu soğanın rakibi

İdare zulümle altları güder

İdare idari idare eder

Bu idare işi ne kadar gider

Kaplumbağa kurbağanın rakibi

2000', 'Hayaller gülümser hülyalarımda Tutsak eller hür doğanın rakibi Keklikler tedirgin kayalarında Guguk kuşu saksağanın rakibi Aslından ziyade b...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/rekabet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşlarım', 'gozyaslarim-cagatay-filiz-b5xs4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hava soğuktu, üşüdüm

Yürüdüm yol boyunca

Önüme çıkmaz sokak çıkana kadar yürüdüm

Bulutlara göz kırptım yağmur yağsın diye

Islanmak istedim

Dudağımda tuz kokusuna hasrettim

Bekledim...! 

Yağmur nedense eşlik etmedi bana

O da beni benle bıraktı

Bana eşlik eden sadece sesiydi ayaklarımın

Gölgem bile yoktu arkamda

Yüreğim dayanamadı hıçkırıklara

Bu çaresizlikle başa çıkamadı

Belirsizliğe tahammül edemeyip

Beni bensiz bıraktı

Ve kavuştu dudaklarım

Arzuladığı tuz kokusuna

Yüreğimin pınar olup damladığı

Gözyaşlarımla! 

(Ankara - 2001)', 'Hava soğuktu, üşüdüm Yürüdüm yol boyunca Önüme çıkmaz sokak çıkana kadar yürüdüm Bulutlara göz kırptım yağmur yağsın diye Islanmak istedim D...', ARRAY['Türk Edebiyatı','Şiir','Cagatay Filiz']::text[], 8.5, '{"poet":"Cagatay Filiz","poet_slug":"cagatay-filiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozyaslarim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalamış ta Sonbahar', 'kalamis-ta-sonbahar-zahide-handan-erengil-13pdi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine bir sonbahar da Kalamış ta Fener de, 

Yaşananlar rüya mı,gerçekler hani nerde? 

Hüzün başlar umudun,tükendiği her yerde. 

Anılarla yaşarsın,aklında binbir hece, 

Gizemlidir sır saklar,sessiz uzundur gece. 

Hayat içinde hayat,iç içe bir bilmece, 

Bir türlü uyku tutmaz,sağa sola dönersin, 

Sanki hatıralarla,bire bir dans edersin. 

Bitmeyen gecelere, teslim olur ağlarsın, 

Ardına baktığında,geçmişine yanarsın. 

Sisli camın ardından,seyredal Kalamışı, 

Yine gönül hasretle,terk etmez yaşanmışı. 

Yeni bir gün doğuyor,Kalamış ta Fener de, 

Asırlara sır olmuş,çınarlar da ilerde. 

Biraz ötede sıra,sıra çay bahçeleri, 

Sessiz sakin seyredal,Kalamış ta Feneri, 

Ayaklar altındadır,hazanın yaprakları, 

Aşinadır Kalamış,beyi ve hanımları. 

Görünür denizdeki, pike yapan martilar, 

Dalgaların sesinde,kaybolur hep çığlıklar. 

Karşılardan duyulur, Kalamışın güftesi

Sanki çıkagelmiştir,üstadın da gölgesi 

Yankılanır kulakta,Münür Nurettin sesi, 

Böylece sürüp gider,Kalamış efsanesi. 

Zahide Handan ERENGİL 

4,11,2005', 'Yine bir sonbahar da Kalamış ta Fener de,  Yaşananlar rüya mı,gerçekler hani nerde?  Hüzün başlar umudun,tükendiği her yerde.  Anılarla yaşa...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kalamis-ta-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizemedim, Olmadı', 'cizemedim-olmadi-cagatay-filiz-quty8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Resmini çizmek istedim

Hayaline değil de gözlerine bakmak istedim

Ama olmadı,

Çizemedim.

Ellerim hep bir başka kadını çiziyordu

Her defasında bir başkasını

Sana bu kadar ihtiyacım varken

Çizemedim, olmadı.

Duvarlara değil kulaklarına fısıldamak istiyordum

Çizemedim kulaklarını

Paylaşmak istiyordum

Olmadı, koyamadım yüreğini bedenine 

Sığmadı

Baktım olmuyor

Kuş olup ucmak istedim kucağına

Ne uçabildim, ne dindirebildim içimdekileri

Ne kaçabildim buradan, ne de kendimden

Bir de çizemedim seni,

Çizemedim, olmadı.

Sen çizilemiyordun

Seni yasamak gerekirdi

NE kendimi yasayabildim 

NE seni

Olmadı, Olmadı.

(2001)', 'Resmini çizmek istedim Hayaline değil de gözlerine bakmak istedim Ama olmadı, Çizemedim. Ellerim hep bir başka kadını çiziyordu Her defasınd...', ARRAY['Türk Edebiyatı','Şiir','Cagatay Filiz']::text[], 8.5, '{"poet":"Cagatay Filiz","poet_slug":"cagatay-filiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cizemedim-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebep...Sonuç...Körlük', 'sebep-sonuc-korluk-hasan-esat-heptunali-rsnfz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sigaranın dumanı 

Bulut olmuş çöker üzerine

Nikotin yağmurları başlar sonra

Zira mevsimidir artık

Kaçamaz … ıslanırsın…

Islanan yanakların gibi….

Boğulurken sonuçlarda…

Sebepler…

İçi acıyarak izler seni 

Zifiri bi aydınlık çöker

Kamaşır gözlerin…

Bi bok göremezsin…

Çakmağın taşı bitmiş…

Kahretsin…', 'Sigaranın dumanı  Bulut olmuş çöker üzerine Nikotin yağmurları başlar sonra Zira mevsimidir artık Kaçamaz … ıslanırsın… Islanan yanakların g...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sebep-sonuc-korluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün baharı', 'huzun-bahari-sair-pinarkirci-sc861', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir vuslat yaşanacak sanki kuşluk vakti

bir deniz çosacak arkasından 

o öyle bir denizki aglayacak

gök yüzünde ay parlayacak

günbatımında dolunayda akşamlar ne güzeldir bilirmisin

o gün yıldızlar yagacak gökyüzünden

bir deniz dogacak sevgi denizi

ama sonsuz olacak

aglama aykaranlık

güz karanlıgı bu

gecenin izdüşümlerinde

bir sonbaharda böyle bitti nihayet', 'bir vuslat yaşanacak sanki kuşluk vakti bir deniz çosacak arkasından  o öyle bir denizki aglayacak gök yüzünde ay parlayacak günbatımında do...', ARRAY['Türk Edebiyatı','Şiir','Şair Pınarkırcı']::text[], 8.5, '{"poet":"Şair Pınarkırcı","poet_slug":"sair-pinarkirci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/huzun-bahari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martıların yüzünden...', 'martilarin-yuzunden-hasan-esat-heptunali-3sd6j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugünlerde bi hayli sıkkın içim…

Buruldukça buruluyorum…

Güneşte mi sorun var

Yoksa soluduğum havada mı

Kestiremiyorum…

Daha bi gri sanki 

Göğün mavisi…

Martılar da pek bi neşesiz canım…

Çığlık çığlığa hepsi…

Yahu…

Var bu işte bi bit yeniği …

Oradan oraya

Kaldırıp kaldırıp 

Vuruyorlar kendilerini

Dedim ya

Bugünlerde pek bi  sıkkın içim…

Yok canım…

Gidişinden falan değil…

Martıların yüzünden bu halim…', 'Bugünlerde bi hayli sıkkın içim… Buruldukça buruluyorum… Güneşte mi sorun var Yoksa soluduğum havada mı Kestiremiyorum… Daha bi gri sanki  G...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/martilarin-yuzunden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ararım', 'ararim-sener-ozdemir-thtpi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her satırın arasında ararım

Bulamam da varır ötede ararım

Düştüğüm kuyuda ararım

Bulamam da varır ötede ararım

Suni yüzlerde ararım

Meleklere,perilere sorarım

Dağ,taş,ova,deniz gezerim

Bulamam da varır ötede ararım

Başımı eğer ararım

Kaldırır döner ararım

Özüme varır ararım

Bulamam da varır ötede ararım

Leyla’da ararım Mecnun’da ararım

Nihal’e uğrar Nafiz’e yanarım

Gider çoban çeşmesine sorarım

Bulamam da varır ötede ararım

Neyle Hakk’a yakarırım

Firaktan şikayet ederim

Feraha hasret, huzur dilerim

Aradıkça bulur,buldukça ararım…', 'Her satırın arasında ararım Bulamam da varır ötede ararım Düştüğüm kuyuda ararım Bulamam da varır ötede ararım Suni yüzlerde ararım Melekler...', ARRAY['Türk Edebiyatı','Şiir','Şener Özdemir']::text[], 8.5, '{"poet":"Şener Özdemir","poet_slug":"sener-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ararim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suç mu İşlerim?', 'suc-mu-i-slerim-kemal-tahir-ozcan-bn19m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbimi hasretle, sana uzatıp,

Al desem, birtanem,suç mu işlerim? 

En güzel sözleri, çağrıma katıp,

Gel desem birtanem, suç mu işlerim? 

Geçtiğin yollara, çiçekler eksem,

Her mevsim,her saat, seni beklesem,

Şarkımda adına,nağme eklesem,

Çal desem birtanem, suç mu işlerim? 

Çileden süzülüp, düşmüşüm aha,

Sen gelmezsen belki, çıkmam sabaha,

Ne olur yanımda, bir gece daha,

Kal desem birtanem, suç mu işlerim?', 'Kalbimi hasretle, sana uzatıp, Al desem, birtanem,suç mu işlerim?  En güzel sözleri, çağrıma katıp, Gel desem birtanem, suç mu işlerim?  Geç...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/suc-mu-islerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıymetini bil.', 'kiymetini-bil-ercan-akbay-qsnfp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat bazen tatlı,bazen acıdır

   Sen tatlı günlerin, kıymetini bil

   Yollar bazen atlı,bazen yayadır

   Sen atlı günlerin,kıymetini bil.

   Bir varmış bir yokmuş,günler geçerken

   Kader bir gün küsüp,bir gün gülerken

   Gönül nice nice,aşklar içerken

   Sen.seni sevenin kıymetini bil.

   Hayat bazen beyaz,bazen karadır

   Sen beyaz günlerin,kıymetini bil

   Aşklar bazen tatlı,bazen yaradır

   Sen tatlı günlerin.kıymetini bil....', 'Hayat bazen tatlı,bazen acıdır    Sen tatlı günlerin, kıymetini bil    Yollar bazen atlı,bazen yayadır    Sen atlı günlerin,kıymetini bil.  ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiymetini-bil-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-salih-yilmazgil-1xfi2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hepsi de hasret dolu, vuslattan bi haber,

Sarmış beni bir ağ gibi; yılan yollar.

Sevgilimi götürüp, beni eden derbeder,

Toz yüklü, dert yüklü, gurbete dalan yollar.

Bakışırız birbirimize, bomboş gibisin, niye? 

Yalvarırım gün boyu, yare götürsen diye

Sizden isterim, bir tanecik hediye

Yare götürün, hasrette kalan yollar.

Bulut olup yağmurumla yıkayayım kirini,

Güneş olup ışığımla ısıtayım tenini,

Derdin varsa söyle ki; vereyim tesellini,

Verin sevgilimi, kederle dolan yollar.

Benim gibi kaç aşık yalvardı yana yana,

Kim bilir kaç dertli şiirler yazdı sana,

Dilesin yeter ki; can verilir canana,

Bir çiçek gibi ufkumda solan yallar.

Hasretin yüküyle ezilmedinmi daha? 

Ulaştır sevgilime, sonu gelmez sabaha,

Tövbe edeceğim, işlediğim günaha,

Yağmur, tipi, kar…hepsi de yalan yollar.', 'Hepsi de hasret dolu, vuslattan bi haber, Sarmış beni bir ağ gibi; yılan yollar. Sevgilimi götürüp, beni eden derbeder, Toz yüklü, dert yükl...', ARRAY['Türk Edebiyatı','Şiir','Salih Yılmazgil']::text[], 8.5, '{"poet":"Salih Yılmazgil","poet_slug":"salih-yilmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yollar-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mumlarda Sen', 'mumlarda-sen-sair-serjan-1w80g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mumlarda sen, gözlerimde sen,

Düş sokağının en güzel evi benim...

Sensiz...Düşlerde sen... 

Gece de sen... İmkansızım... 

Bende sen...', 'Mumlarda sen, gözlerimde sen, Düş sokağının en güzel evi benim... Sensiz...Düşlerde sen...  Gece de sen... İmkansızım...  Bende sen......', ARRAY['Türk Edebiyatı','Şiir','Şair Serjan']::text[], 8.5, '{"poet":"Şair Serjan","poet_slug":"sair-serjan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mumlarda-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-sair-hasret-n-0907y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Derin vadilerin arasında yitip giden bir ırmağın sesiyim şimdi.

 Gerçek olanlara, hissetmeyi bilenlere söylüyorum şarkımı.

 Akıyorum usul usul.

 İşte ben! az olan, gizli olan. O benim; yitik olan, hayran bırakan,kıyısında  durup serinlemek için yeşile boyanmış ırmak

Sadece dakikalık bir seyir için yol kenarında durulan bir gölüm ben.  İki adım ötende zannettiğin, nefesin kesilene dek koşup, ulaşmana ramak kalmışken zamanının dolduğu ve geri döndüğün.Sazlıklarına kuşlar saklamış,kayıklarına maviler asmış,rüzgarı avare

Bir gülümsemeyim,bir hüzün bazen,bir kutu boya kalemi rengarenk

kimi mavi, kimi kırmızı, kimi siyahla boyanmış bir tuval

Issız bir yolum, gönlü ıssızlara refaket eden,sessiz ve anlayışlı

güneşli, yagmurlu, karlı, tozlu

Bir damla ışık hasretlere,sevdalara 

Agır bir yürek,dolu aldanışlarla bir de sevgilerle karşılıklı karşılıksız

Bir çift gözüm çogu zaman takılıkalmış birşeylere,dalgın, beyindeki merkezine inat başka şeyler gören baktıgında, asi, aglamayı unutmuş 

ve kırık bir bisiklet tekerlekleri yamulmuş,boyası dökülmüş olsa da hep O çocugun kanayan dizlerini özleyen neşe,kahkaha.Çamlıca gazozundaki kabarcıklar ben.', 'Derin vadilerin arasında yitip giden bir ırmağın sesiyim şimdi.  Gerçek olanlara, hissetmeyi bilenlere söylüyorum şarkımı.  Akıyorum usul us...', ARRAY['Türk Edebiyatı','Şiir','Şair Hasret_n']::text[], 8.5, '{"poet":"Şair Hasret_n","poet_slug":"sair-hasret-n","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-210-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manalı Gözler', 'manali-gozler-yusuf-ter-nykmz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimden kopan rüzgâra eğil 

Ağzından çıkan öz olsun söz değil 

Sözlerinde bana ateş yanmasın 

Gözlerinde kanlı yaşı görmeyim 

Uzaksın şu dağın doruğu kadar 

Kır çiçeği misin dikenin batar 

Yelin beni gurbet ellere atar 

Gözlerinde kanlı yaşı görmeyim 

Sen bilirsin Figen gerçek acıdır 

Sevgi denen şey gönlümün tacıdır 

Yusuf’um yabanın garip koçudur 

Gözlerinde kanlı yaşı görmeyim 

Yusuf Ter 04.12.04 

Saat 23:45 İsviçre', 'Yüreğimden kopan rüzgâra eğil  Ağzından çıkan öz olsun söz değil  Sözlerinde bana ateş yanmasın  Gözlerinde kanlı yaşı görmeyim  Uzaksın şu ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/manali-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Âhım mısın', 'him-misin-osman-nuri-ozpekel-0i7gy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baktığım her yerde varsın dilde mihmânım mısın

Gördüğüm her şey senin aksin benim cânım mısın

Hem görüp her gün seni hem hasretim gül rûyine

Yandı artık bitti gönlüm âteşim âhım mısın 

                                    

(26.07.2000-Maçka) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Baktığım her yerde varsın dilde mihmânım mısın Gördüğüm her şey senin aksin benim cânım mısın Hem görüp her gün seni hem hasretim gül rûyine...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ahim-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şey', 'sey-dogan-senyurt-f61c3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tutam şey daha düştü

Yüreğimin tam orta yerine,

Hergün çoğalan o şeyi bilir misin? 

Şey işte,

O,anlatılamayacak kadar tabiri olmayan şey.

O şey...

Kelime karşılığını bulamadığım,

Ama içimde kusursuzca büyüttüğüm o şey.

O şey,sence ne? 

Oysa öncelerde çok küçük birşeydi o şey,

Ama neydi? 

Ne olduğunu kimseler bilemezdi,

Ben de bilmelerini istemezdim zaten.

Nerden bilebilirdim birgün,

Saklayamayacağım kadar büyüyeceğini o şeyin.

O şey,

Sanki henüz kendine,

Sözlüklerde bir yer edinememiş bir kelime.

Yani öylesine yeni,öylesine keşfedilmemiş,

Öylwsine taptaze.

O şey,

Seni kendisiyle bütünleştiren,

Beni her seferinde parçalara bölüp,

Yeniden şekillendiren.

O şey,sence ne? 

O şey,

Sen üzüldüğünde içimdeki acıyla başkaldıran,

Kızdığında bana ve görmek istemediğinde beni,

Kalbime dört koldan saldıren...

O şey,

Gözümden kendine haz gözyaşlarını akıtan,

O şey,

Yokluğunda; 

Kokunu odamdan,

Hayalini gözlerimden eksik etmeyen...

O şey,sence ne? 

Yani sözün kısası sevgilim,

Birşey var işte bilmediğim.

Ve belki bir gün ne olduğunu,

İlk ben keşfedeceğim.

Ne olduğunu bulduğum o şeyi,

İlk sana söyleyeceğim.

Ve o şeyi kalbimde,

Seninle büyüteceğim.', 'Bir tutam şey daha düştü Yüreğimin tam orta yerine, Hergün çoğalan o şeyi bilir misin?  Şey işte, O,anlatılamayacak kadar tabiri olmayan şey...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şenyurt']::text[], 8.5, '{"poet":"Doğan Şenyurt","poet_slug":"dogan-senyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sey-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-dogan-senyurt-j7vbp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep bir duvar var sırtımı yaslayacağım,

Ya da öfkemden yumruklayacağım.

Hep bir yatak var uyuyacağım,

Ya da uzanıp seni düşüneceğim.

Hep bir lamba var odayı aydınlatan,

Ya da beni karanlıkta bırakan.

Hep bir boş kağıt var yazdıkça dolan,

Ya da doldukça boşalan.

Ama sen hep yoksun,

Ben de hep senden yoksun...', 'Hep bir duvar var sırtımı yaslayacağım, Ya da öfkemden yumruklayacağım. Hep bir yatak var uyuyacağım, Ya da uzanıp seni düşüneceğim. Hep bir...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şenyurt']::text[], 8.5, '{"poet":"Doğan Şenyurt","poet_slug":"dogan-senyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yoksun-123-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda', 'yoklugunda-dogan-senyurt-hhmcu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deniz bugün de anlattı seni bana,

Kendisi bile farkında olmadan.

Bir martı gelip kondu yamacıma ve,

Bana iyi olduğunu haber verdi,

Ama o da farkında değildi bunun.

Sevgililer hep senden bahsettiler bana,

Ama bundan haberleri bile yoktu.

Ben hep seni düşündüm,

Yani geleceğimi.

Ama hep farkına vararak,

Hep farkında olarak...', 'Deniz bugün de anlattı seni bana, Kendisi bile farkında olmadan. Bir martı gelip kondu yamacıma ve, Bana iyi olduğunu haber verdi, Ama o da ...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şenyurt']::text[], 8.5, '{"poet":"Doğan Şenyurt","poet_slug":"dogan-senyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yoklugunda-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden kırdım', 'neden-kirdim-osman-nuri-ozpekel-u3fvi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Belki anlarsın dedim de anlaşılmaz derdimi

Bilmedim üzdüm neden kırdım senin saf kâlbini 

Bence aşkın en ilâhî aşkların şâheseri

Böyle sevmek şâdeder ancak bu mahzûn kâlbimi

	          

(10.08.1985-Fatih)                          

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Belki anlarsın dedim de anlaşılmaz derdimi Bilmedim üzdüm neden kırdım senin saf kâlbini  Bence aşkın en ilâhî aşkların şâheseri Böyle sevme...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/neden-kirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-dogan-senyurt-ztka2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yoldayı iki yanı karanlık,ağaçlarla dolu,

Ayaklarım çıplak ürüyorum bu yolu.

Seni arıyorum ismini gökyüzüne haykırarak,

Bakıyorum gökyüzüne,ne kadar da parlak.

Seni arıyorum soluk soluğa,

Biiyorum kavuşacağım yolun sonunda.

Ve uyanıyorum gözyaşıyla.

Yine arıyorum seni ve yine gözyaşı...', 'Bir yoldayı iki yanı karanlık,ağaçlarla dolu, Ayaklarım çıplak ürüyorum bu yolu. Seni arıyorum ismini gökyüzüne haykırarak, Bakıyorum gökyüz...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şenyurt']::text[], 8.5, '{"poet":"Doğan Şenyurt","poet_slug":"dogan-senyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruya-209-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyarısı Versiyonu', 'geceyarisi-versiyonu-dogan-senyurt-mzp4s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve gecenin bir yarısında telaşlı bir uyanışla,

Kapıma dayanması hayalinin.

Ve sesini duyar,ellerini tutar gibi olmak.

Boynumun iki yanından sırtıma,göğsüme akan,

Soğuk ter damlaları...

Uyumayı istemenin; 

Seninle sevişme,göğüslerinde yatma hazzını,

O eşsiz arzuyu bir sona erdirme çabasında olması.

Ve istemeye istemeye,

Ağzına kadar gözyaşıyla dolmuş kalbimin,

Bedenimi taşırması.

İşte sana olan aşkımın geceyarısı versiyonu', 'Ve gecenin bir yarısında telaşlı bir uyanışla, Kapıma dayanması hayalinin. Ve sesini duyar,ellerini tutar gibi olmak. Boynumun iki yanından ...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şenyurt']::text[], 8.5, '{"poet":"Doğan Şenyurt","poet_slug":"dogan-senyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geceyarisi-versiyonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahın Köründe', 'sabahin-korunde-dogan-senyurt-j6jnc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce bembeyaz minik ayakların geldi gözümün önüne,

Sonra sırayla tüm vücudun...

Ardından teninin kokusunu alır gibiyim.

Sabahı getirmek ne kolay oldu.

Ben yaşamıyorum oysa,yaşıyormuş gibi yapıyorum.

Saate bir bak ve bir de bana bak sonra.

Belki tanırsın...', 'Önce bembeyaz minik ayakların geldi gözümün önüne, Sonra sırayla tüm vücudun... Ardından teninin kokusunu alır gibiyim. Sabahı getirmek ne k...', ARRAY['Türk Edebiyatı','Şiir','Doğan Şenyurt']::text[], 8.5, '{"poet":"Doğan Şenyurt","poet_slug":"dogan-senyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sabahin-korunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dâğ olur', 'd-g-olur-osman-nuri-ozpekel-gw9ik', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bakış bâzen gönülde bir onulmaz dâğ olur

Bir bakış bâzen de kâlpte bir çözülmez bâğ olur

Bir bakış bâzen bedende sanki yanardâğ olur

Bir bakış bâzen de tende bülbül öten bâğ olur

                                      

(15.01.2005- Maçka) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Bir bakış bâzen gönülde bir onulmaz dâğ olur Bir bakış bâzen de kâlpte bir çözülmez bâğ olur Bir bakış bâzen bedende sanki yanardâğ olur Bir...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dag-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erenleri', 'erenleri-osman-nuri-ozpekel-sjn36', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir Ferâhnâk şarkı bağlar vuslata erenleri

Bir ilâhî nûr yağar gökten sarar sevenleri

Rûha dolmuşken ayın on dördü rü’yâ son bulur

Bir bulut birleştirir bâzen sevenleri

           

(17.09.2005-Erzurum Sitesi) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Bir Ferâhnâk şarkı bağlar vuslata erenleri Bir ilâhî nûr yağar gökten sarar sevenleri Rûha dolmuşken ayın on dördü rü’yâ son bulur Bir bulut...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/erenleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-osman-nuri-ozpekel-5p1m8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazdım senin sevginle ilhâmınla ben

Besteler yap rûha dolsun ben çalarken söyle sen

Haşre dek sürsün bu sevdâ şen gönüller inlesin

Her seven kâlp şevke gelsin aşkı bizden dinlesin

(10.01.2005- Maçka) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Bir şiir yazdım senin sevginle ilhâmınla ben Besteler yap rûha dolsun ben çalarken söyle sen Haşre dek sürsün bu sevdâ şen gönüller inlesin ...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ben-211-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım', 'aglarim-osman-nuri-ozpekel-mhawv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok zamandır ayrı düştüm sevdiğimden ağlarım

Geçmiyor günler güzel gözlüm efendim ağlarım

Gelmedin mehtâba kandım dinmiyor göz yaşlarım 

Geçmiyor günler güzel gözlüm efendim ağlarım

(22.09.1989-Fatih) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Çok zamandır ayrı düştüm sevdiğimden ağlarım Geçmiyor günler güzel gözlüm efendim ağlarım Gelmedin mehtâba kandım dinmiyor göz yaşlarım  Geç...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aglarim-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nûr yok', 'n-r-yok-osman-nuri-ozpekel-dtmwr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nûr yok

Ehl-i aşkın meclisinde ‘ayş bitmiş nûr yok

Bir harâb-âbâd hacle-gâhı yitmiş nûr yok

Mâh-i tâb elbet doğar bir gün dil-i nâ-şâdıma

Sevdiğim çehrende artık hande gitmiş nûr yok

(30. 04. 2004- Maçka)', 'Nûr yok Ehl-i aşkın meclisinde ‘ayş bitmiş nûr yok Bir harâb-âbâd hacle-gâhı yitmiş nûr yok Mâh-i tâb elbet doğar bir gün dil-i nâ-şâdıma Se...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nur-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yüzden', 'bu-yuzden-asima-azra-ebxj2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl ki,

hoyratça koparılan bir gülün

hesap sorulmazsa dikeninden

öyle lüzumsuz yaralar aldım

kurşun rengi cümlelerden…

Yazık ki,

dilimden düşürdüğün türkümün

dizelerini kaldırmadan yerden

gözden çıkarılmış insan yanım

telif hakkı ödenmeden...

Şimdi,

saramam kanayan ellerini 

açamam bakan kör gözlerini

…………….....sırf bu yüzden!', 'Nasıl ki, hoyratça koparılan bir gülün hesap sorulmazsa dikeninden öyle lüzumsuz yaralar aldım kurşun rengi cümlelerden… Yazık ki, dilimden ...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-yuzden-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mâtem', 'm-tem-osman-nuri-ozpekel-7x80k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Erguvanlar soldu burda nerdesin ey nazlı yâr

Mor menekşe büktü boynun sensiz ağlar her bahar

Küstü hep salkımsöğütler bitti mehtâb yok gurûb

Sustu bülbüller Boğaz’da gizli bir mâtem mi var                

	

(30. 05. 2004- Maçka) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Erguvanlar soldu burda nerdesin ey nazlı yâr Mor menekşe büktü boynun sensiz ağlar her bahar Küstü hep salkımsöğütler bitti mehtâb yok gurûb...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/matem-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feyz-i Yektâ', 'feyz-i-yekt-osman-nuri-ozpekel-bdok1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Feyz-i Yektâ yaktı gönlüm câna te’sîr eyledi

Can şerer-efşânı her bir yâna te’esîr eyledi

Ufk-ı ümmîd-i sabâdan pek ırâk oldum bugün

Âteş-i âhım nihâyet kana te’sîr eyledi

		

(16.10.2002-Maçka)', 'Feyz-i Yektâ yaktı gönlüm câna te’sîr eyledi Can şerer-efşânı her bir yâna te’esîr eyledi Ufk-ı ümmîd-i sabâdan pek ırâk oldum bugün Âteş-i ...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/feyz-i-yekta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cânımsın benim', 'c-nimsin-benim-osman-nuri-ozpekel-zfg4o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinden gitmesin çehren nigârımsın benim

Sevgilim sen hem sevâbım hem günâhımsın benim 

Sanma cevrinden bıkar gönlüm ilâhımsın benim

“Gizlesem de âşikâr etsem de cânımsın benim”

(10.11.1985-Fatih) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün) 

(“Şeyh Galib’in mısrâ’ını terbî’”)', 'Gözlerinden gitmesin çehren nigârımsın benim Sevgilim sen hem sevâbım hem günâhımsın benim  Sanma cevrinden bıkar gönlüm ilâhımsın benim “Gi...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/canimsin-benim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Penbedir “Zeynep Gül’e”', 'penbedir-zeynep-gul-e-osman-nuri-ozpekel-ifhqh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül kokar yârim benim gül rûyi gülden penbedir

Gül dehen güldükçe gülden goncalar gül femdedir

Gül nefeslim gül heveslim gül ki gül gamzendedir

Gül benim sînemde saklı gonca gül gül-femdedir

			

(21.04.2000-Maçka) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Gül kokar yârim benim gül rûyi gülden penbedir Gül dehen güldükçe gülden goncalar gül femdedir Gül nefeslim gül heveslim gül ki gül gamzende...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/penbedir-zeynep-gul-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On dokuz yıl', 'on-dokuz-yil-osman-nuri-ozpekel-tmaud', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her geçen yıl sevgimiz sonsuz ve dağlarca büyür

Aşk benim kâlbimde tûfandır ki sessizce yürür

Bir değil binlerce sevdim her şeyinle ben seni

Bir bilen vardır ki sevdâmı benim her ân görür

				      

(11.05.2004-Maçka) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Her geçen yıl sevgimiz sonsuz ve dağlarca büyür Aşk benim kâlbimde tûfandır ki sessizce yürür Bir değil binlerce sevdim her şeyinle ben seni...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/on-dokuz-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar gibi “Zeynep Gül’e”', 'daglar-gibi-zeynep-gul-e-osman-nuri-ozpekel-uzm3m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karların üstünde bir ceylân gezer oynar gibi

Buzların altında bir sevdâ durur kaynar gibi

Güllerin yapraklarından gizli şebnemler düşer

Gözlerin nûrunda sırlar saklıdır dağlar gibi

(21.04.2003-Maçka) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Karların üstünde bir ceylân gezer oynar gibi Buzların altında bir sevdâ durur kaynar gibi Güllerin yapraklarından gizli şebnemler düşer Gözl...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/daglar-gibi-zeynep-gul-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cânıma', 'c-nima-osman-nuri-ozpekel-7yunq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nabz-gîr olmakta cânân âşık-ı bîmârına

Dest’den nûr sunmak ister hasta-i hicrânına

Çeşminin ihsânı evvel cân verirken cânıma

Mürde-i hûn eyler artık nâvek-i müjgânına

				

(21.01.2000-Maçka) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Nabz-gîr olmakta cânân âşık-ı bîmârına Dest’den nûr sunmak ister hasta-i hicrânına Çeşminin ihsânı evvel cân verirken cânıma Mürde-i hûn eyl...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/canima-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceylân mısın', 'ceyl-n-misin-osman-nuri-ozpekel-6ujc4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim karşımda ürkek nazlı bir ceylân mısın

Yoksa mehtâba bürünmüş âteş-i sûzân mısın

Okşasam her lâhza zülfün bil usanmam haşre dek

Ömrümü târâc eden bir âfet-i devrân mısın

	                             

(18.04.2004- Maçka) 

(Fâilâtün Fâilâtün Fâilâtün Fâilün)', 'Sen benim karşımda ürkek nazlı bir ceylân mısın Yoksa mehtâba bürünmüş âteş-i sûzân mısın Okşasam her lâhza zülfün bil usanmam haşre dek Ömr...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri Özpekel']::text[], 8.5, '{"poet":"Osman Nuri Özpekel","poet_slug":"osman-nuri-ozpekel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ceylan-misin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mide Ağrısı', 'mide-agrisi-durmus-karakus-f5z7y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karın ağrısıyla alakası yok

Feryar figan kalktım gece yarısı

Vallahi dostlarım hiç şakası yok

Öldürecek beni mide ağrısı

Eğile büküle mutfağa daldım

İlk önce şekerli sıcak su aldım

Kıvranırken kanter içinde kaldım

Öldürecek beni mide ağrısı

Acıyı yağlıyı ayırdım seçtim

Bu sefer kötüydü kendimden geçtim

Bir iki bardak ta sıcak süt içtim

Öldürecek beni mide ağrısı

Bir taşı ısıtıp havluyla sardım

Naneyi limonu kaynatıp kardım

Ey Allah''ım dedim yardım et yardım

Öldürecek beni mide ağrısı

Belki geçer diye yüz üstü yattım

Dalmışım midemi birine sattım

Kaç defa çıkardım kaç defa attım

Öldürecek beni mine ağrısı

Geceler uzundu sabaha çoktu

Bu ne biçim ağrı dindiği yoktu

Galiba azrail boynuma çöktü

Öldürecek beni mide ağrısı

Karakuş: Şifalı ne varsa yedim

O da beni yedi hep didim, didim

Eşime hakkımı helal et dedim

Öldürecek beni mide ağrısı.', 'Karın ağrısıyla alakası yok Feryar figan kalktım gece yarısı Vallahi dostlarım hiç şakası yok Öldürecek beni mide ağrısı Eğile büküle mutfağ...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mide-agrisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyim', 'neyleyim-mikdat-bal-d1iqb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskiden ben böyle gergin değildim

Mutluluktan iz kalmadı neyleyim

Felek bana sile vurdu eğildim

Bende eski hız kalmadı neyleyim

Betbaht deyin ister talihsiz sayın

Güvendiğim dostlarım çıkmış hain

Ya bataktır ya da her taraf mayın

Yürünecek iz kalmadı neyleyim

Terkedildim bilmem nedir nedeni

Affedemem bana bunu edeni

Bunca yükün altında bu bedeni

Taşıyacak diz kalmadı neyleyim

Kaçamam ki veda ettim koşmaya

Yorgun düştüm engelleri aşmaya

Ne hakkım var köpürmeye taşmaya

Her yer yokuş düz kalmadı neyleyim

Vefasız dostlarım dalga geçerler

Böyleleri zayıf anı seçerler

Satar bunlar ucuz fiyat biçerler

Utanacak yüz kalmadı neyleyim

Mikdat’ı  sormuşlar dedi ki kimdi? 

İyi günün dostu tanımaz şimdi

Öyle bir ağırlık üstüme bindi

Söyleyecek söz kalmadı neyleyim', 'Eskiden ben böyle gergin değildim Mutluluktan iz kalmadı neyleyim Felek bana sile vurdu eğildim Bende eski hız kalmadı neyleyim Betbaht deyi...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/neyleyim-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Sevgi Tuzağı', 'gozlerin-sevgi-tuzagi-celal-topo-e06y2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'G--özlerin birer sevgi tuzağı

Ü--rkerek onlara bakıyorum

L--eyla mecnunu böyle yakmadımı? 

S--ende beni yakarsın diye çok korkuyorum

E--limde değil gem vuramıyorum yüreğime

R--ehine almışçasına tutsak ettin kendine

E--lli yaşındada olsam yenik düştüm kalbime

N--asıl anlatsam duygularımı kelimeler bulamıyorum....



2001 / Çanakkale', 'G--özlerin birer sevgi tuzağı Ü--rkerek onlara bakıyorum L--eyla mecnunu böyle yakmadımı?  S--ende beni yakarsın diye çok korkuyorum E--limd...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozlerin-sevgi-tuzagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Küskün Ben Dargın', 'sen-kuskun-ben-dargin-celal-topo-rof5h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tüm acıların bulutları

Birikmiş gözlerimde

Yüreğime bir dokunsan

Dinmeyen yağmur damlaları

Dökülecek ellerime

Tüm  yaşananları sürükleyerek

Bulanık seller akacak belki de

Sen bana küskün 

Ben sana dargın

Denizlere karışacağım

Gerçekleşmeyen hayallerimle...



2001 / Çanakkale', 'Tüm acıların bulutları Birikmiş gözlerimde Yüreğime bir dokunsan Dinmeyen yağmur damlaları Dökülecek ellerime Tüm  yaşananları sürükleyerek ...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-kuskun-ben-dargin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuştuğunda', 'tutustugunda-yavuz-bayram-caliskan-dx1qy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen kahredici bir karanlık,

Bir mutluluk simgesi bazen de.

Bazen denizin ortasında ümitlerin,

Gözlerin içinde emellerin doğduğu an bazen de.

Acıyı, ıstırabı çekeceksin,

Yaşayacaksın ağlaya sızlaya,

İşte o an anlayacaksın aşkı,

Belki de ödeyeceksin hayatınla.

Mutluluğu avuçlayacaksın,

Ama bekleyişle, ama acıyla,

Varabilmek için gerçek aşka,

Eriyeceksin bir çift göz uğruna.', 'Bazen kahredici bir karanlık, Bir mutluluk simgesi bazen de. Bazen denizin ortasında ümitlerin, Gözlerin içinde emellerin doğduğu an bazen d...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tutustugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Yitişi', 'umudun-yitisi-yavuz-bayram-caliskan-ew0ov', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gecenin sensizliğinde,

Akar gözlerimden yaşlar.

Buğulanmış camın ötesinde,

Karanlık bir gece daha başlar.

İçkiler, meyhaneler benim artık,

Ankara sokakları benim artık.

Günü görene dek, aydınlığı bulana dek,

Yalnız başına dolaşan benim artık.

Sensizliğin ıstırabında sokaklarda,

İki hecelik ismin dudaklarımda,

Kaybolurum sensiz karanlıklarda,

Giderim hayallerinle umudumun yittiği yere dek...!', 'Bir gecenin sensizliğinde, Akar gözlerimden yaşlar. Buğulanmış camın ötesinde, Karanlık bir gece daha başlar. İçkiler, meyhaneler benim artı...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umudun-yitisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutsal aşk', 'kutsal-ask-i-brahim-kilinc-k5bmb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıktığım çileli hayat yolunun

Yarısı tükendi, yarısı kaldı

Sevdim birisini Tanrım kulunun

Gönlümde acısı, yarası kaldı

Sade sevdim onu, kem söz etmedim

Israr edip arkasından gitmedim

Ağzını açana laf söyletmedim

Gitti, arkasında kölesi kaldı

Senin zerren imiş meğer sevdiğim

Kutsal bir sevgiyle gönül verdiğim

Onu arar iken seni bulduğum

Gönlümde nurlu bir hâlesi kaldı', 'Çıktığım çileli hayat yolunun Yarısı tükendi, yarısı kaldı Sevdim birisini Tanrım kulunun Gönlümde acısı, yarası kaldı Sade sevdim onu, kem ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kutsal-ask-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmeyen Uğurböcekleri...', 'donmeyen-ugurbocekleri-pinar-koc-3q9h9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bin gün geçti gözlerim gözlerinde erimeyeli…

Dört kış ve üç sonbahar…

Yüreğime sorarsan bin asır oldu…

Bin asırdır yalnız kalbim ve üç ilk bahar…

Uğurböcekleri uçtu gitti kilometrelerce.

Binlerce kişiye umut oldu,mutluluk oldu! ! ! 

Bir seni getirmediler bin asır boyunca…

Ve bir seni döndüremediler inat yolundan..

Ölü bir uğurböceği bulduğumda anladım ki

Milyonlarca asır geçecekti ve binlerce kış, sonbahar…

Kalbim kırık ağlarken köşe odalarda,

Hıçkırıklarını bir sen duymadın! ! ! 

Ve bir sen hissetmedin masumiyet yalnızlığımı…

Geri dönüşünde oldu elbet,uğurböceklerinden önce! 

Ama bir sen fark edemedin

Uğurböceklerinin gittikleri yoldan dönmeyeceklerini………….

                                                                        20.02.05   01:16', 'Bin gün geçti gözlerim gözlerinde erimeyeli… Dört kış ve üç sonbahar… Yüreğime sorarsan bin asır oldu… Bin asırdır yalnız kalbim ve üç ilk b...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/donmeyen-ugurbocekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yamalı Yürekler.', 'yamali-yurekler-pinar-koc-p627n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YAMALI YÜREKLER…

Sen aşkını öldürürken,

Gülen insanların,yamalı yüreklerini

Kimseler görmedi..

Kimininki tek kurşun,

Kimininki delik deşikti…

Yamalı yüreklerindeki aşkları

Kimseler bilmedi…

Gülüyorlardı artık katledilen aşklara! ! ! ! 

Veya aşklar için katedilen yollara….

Sen aşkını gömerken,

Kara bir sandıkla toprak altına,

Acın yükseliyordu

Yaralı yüreklerin ruhları gibi arş-ı alaya…

Kimininki tek kurşun,

Kimininki delik deşikti…

Sen aşkını gömerken,

Ağlayan insanların yanık yüreklerini

Bir tek sen görmedin…

Kimininki tek kıvılcım,

Kimininki alev alevdi…

                                                       04.11.05    01:20', 'YAMALI YÜREKLER… Sen aşkını öldürürken, Gülen insanların,yamalı yüreklerini Kimseler görmedi.. Kimininki tek kurşun, Kimininki delik deşikti...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yamali-yurekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle kal', 'benimle-kal-seyhmus-sait-aydin-rsb49', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '. 

Benimle kal

Odam karanlık, 

Işıldayan, bir tek gözlerin. 

Ruhum karanlık, 

Aydınlatan, 

Güzel sözlerin. 

Ya Hep Benim ol benimle kal, 

Ya uzat hançerini canımı al. 

Bitmesin seninle geçen saatler, 

Söyle Akrebe,yelkovana, 

dursun yerinde. 

Öyle doyulmazsınki, 

Ne olur gitme 

Bu gecede yanımda kal 

Ilık nefeslerimiz Karışsın Biri birine, 

Ellerimiz Ayrılmasın tenimizden. 

Yanardağ gibi tutuştur beni, 

Yeni bir Volkan yarat bedenimizden. 

Başını omuzuma koy, 

Saçlarını Gögsüme sal, 

Ne olur gitme. 

Mahşere kadar 

Benimle kal. 

Şeyhmus Sait Aydın

26.10.2005', '.  Benimle kal Odam karanlık,  Işıldayan, bir tek gözlerin.  Ruhum karanlık,  Aydınlatan,  Güzel sözlerin.  Ya Hep Benim ol benimle kal,  Ya...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/benimle-kal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirim Aradı Beni', 'siirim-aradi-beni-huseyin-erdogan-ck07j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'müjde müjde biraz önce

şiirim aradı beni

şairsiz şiir olur mu? 

ben de seni seviyorum dedi

hem de birkaç kere

sevdiğini hasretini yineledi

bir gün mutlaka sana

geleceğim diye de söz verdi

uzattığım üşüyen ellerimi

telefonda olsa da tutuverdi

bedenimi sıcacık ediverdi

sözlerinden sevgi akıyordu sanki

bir deniz bir okyanus oluverdi

vallahi sesinin tonu beni çok etkiledi

her kelimesi bir aşkın bir sevdanın 

en güzel ifadesiydi bir sevgi seliydi

bu benim kalbimin müthiş bir fethiydi

yarabbim ne de şanslı bir şairim ben

bütün sevgisini bana verdiğini söyledi

biliyordum sevgim karşılıksız değildi

bu umutla yaşıyordum aylardan beri

onun ''ben de seni seviyorum''deyişiyle

yüreğimdeki aşkım rengarenk açıverdi

yoksa ona kavuşacağım  yer mahşerdi

oysa şimdi gözlerim takılı kaldı yollarına

şiirimi bekleyeceğim ömrüm boyunca

bir gün çıkıp gelecek diye yanıma

gelmese de onun yolunda ölürüm ya

hiç olmazsa sevdam kalır bu dünyada

dilden dile dolaşır durur benden sonra

                                       05.11.2005

                                     Hüseyin Erdoğan', 'müjde müjde biraz önce şiirim aradı beni şairsiz şiir olur mu?  ben de seni seviyorum dedi hem de birkaç kere sevdiğini hasretini yineledi b...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/siirim-aradi-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzbaşım', 'yuzbasim-ekrem-sama-yc5p0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Erlerin mektupları yüzbaşıya geldi

Mehmet’in mektubu çok kısa çok özeldi.

“Mehmet’ten Allah’ına” diye yazılmıştı,

Yüzbaşı okuyunca, ciğerini deldi.

“Ey Allahım! ” diyerek girmiş satırına,

“Ortak ol garip Mehmet kulunun sırrına,

Hiç kimim kimsem yoktur, harçlığım da bittti,

Bana yüz lira gönder, Resul hatırına.”

Yüzbaşı üzülmüştü, yüzü bembeyazdı,

“Allah’ından Mehmet’e” diye bir zarf yazdı.

Elli lira koyarak, geriye gönderdi,

Hayırdı bu geç kalmak hiç iyi olmazdı.

Mehmet Allah''a cevap yazdı ertesi gün. 

''Rabbım kesin yüz lira bana uygun gördün! 

Yarısına el koymuş, garip gördü beni,

Yüzbaşım mektubuna bakıyor bölüğün''

(İstanbul:05.11.2005)', 'Erlerin mektupları yüzbaşıya geldi Mehmet’in mektubu çok kısa çok özeldi. “Mehmet’ten Allah’ına” diye yazılmıştı, Yüzbaşı okuyunca, ciğerini...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yuzbasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmek parası', 'ekmek-parasi-muzaffer-sarikilic-kg19q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir dilenci belirdi sokağın başında

Belliydi utanıyordu,mağrurdu,birazda buruk,

Omuzları çökmüş, üstünde bir elbise, yırtık, pırtık,

Yaklaştı, ağır ve yürümek istemeyen adımlarıyla,

Mahcuptu,o zamanında dik bakışlı olan gözleri,

Belki şimdi konuşsa da önemsizdi insanlar için sözleri,

Bir an durdu: önüne eğdiği başını kaldırdı ve içli içli; 

Dedi ki; Oğlum Allah rızası için bir ekmek parası,

Bunu derken o kadar sönüktü ki kömür gibi gözlerinin karası,

Anne düşünsene, sorun bir ekmek parası,

Ne dünyayı dileniyor,ne hayatı, ne de sevdayı,

Onun titreyen  avucuna konulacak bir kaç kuruş,

Evet anne; belki de bir kaç kuruş onu bütün dünyası 

Belki uykusu boyunca gördüğü bir ekmek parası rüyası,

Tüm hayelleri ve hülyası bu günü kurtardıktan sonra,

Yarın toplayıp toplayamayacağı belli olamayan,

Bizim şerefsiz dediğimiz, onursuz gördüğümüz

İnsanlardan alacağını düşündüğü 

BİR BAYAT EKMEK PARASI', 'Bir dilenci belirdi sokağın başında Belliydi utanıyordu,mağrurdu,birazda buruk, Omuzları çökmüş, üstünde bir elbise, yırtık, pırtık, Yaklaşt...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Sarıkılıç']::text[], 8.5, '{"poet":"Muzaffer Sarıkılıç","poet_slug":"muzaffer-sarikilic","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ekmek-parasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok', 'yok-mesut-toprak-5zb9z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bağırıyorum! 

hıçkıra hıçkıra.

ağlıyorum,

kise yok.

sesim gidiyor uzaklara,

elleri boş dönüyor sokakları.

artık

yerin bile kulağı yok...', 'bağırıyorum!  hıçkıra hıçkıra. ağlıyorum, kise yok. sesim gidiyor uzaklara, elleri boş dönüyor sokakları. artık yerin bile kulağı yok......', ARRAY['Türk Edebiyatı','Şiir','Mesut Toprak']::text[], 8.5, '{"poet":"Mesut Toprak","poet_slug":"mesut-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yok-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Ey Canım', 'gel-ey-canim-guney-donmez-qb9kg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ahu dedim seyrin ne hoş

gül yanağın kaşın ne hoş

varsam bir buse almaya

eyler misin beni sarhoş

gel ey canım gel ey canım 

sensin benim tek dermanım

söyle beni sevdiğini 

kulun olam ey sultanım

leblerin ıslak olunca

saçından yıldız kayınca

boynum bükük gelsem sana

öper misin kış boyunca

güneyim akar sözlerim

sevdiğin arar yüreğim

seni istemeye gelsem 

varır mısın bana minim', 'ahu dedim seyrin ne hoş gül yanağın kaşın ne hoş varsam bir buse almaya eyler misin beni sarhoş gel ey canım gel ey canım  sensin benim tek ...', ARRAY['Türk Edebiyatı','Şiir','Güney Dönmez']::text[], 8.5, '{"poet":"Güney Dönmez","poet_slug":"guney-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-ey-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişti/m', 'degisti-m-mesut-toprak-5dlai', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kafam kanadı

