INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan Sevdam', 'uzaktan-sevdam-zeki-savci-go271', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdan basima bela, 

Biraksam, gitse sele. 

Saclar agartsam bile 

Ne anlarsin, Ne gorursun, Ne de farkima varirsin... 

Tukettim nefesimi, 

Daglar duydu sesimi. 

Kuslar tuttu yasimi, 

Ne aglarsin, Ne bilirsin, Ne de kabrime gelirsin...', 'Sevdan basima bela,  Biraksam, gitse sele.  Saclar agartsam bile  Ne anlarsin, Ne gorursun, Ne de farkima varirsin...  Tukettim nefesimi,  D...', ARRAY['Türk Edebiyatı','Şiir','Zeki Savci']::text[], 8.5, '{"poet":"Zeki Savci","poet_slug":"zeki-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzaktan-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşen Yapraklarda Umudum', 'dusen-yapraklarda-umudum-nurten-tarim-va23h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonbahardır adım

Eylüldür can damarım

Yarenlerin türküleri rüzgarım

Düşen yaprakta umudum

Güz gelini derler bana

Sararmış yapraktır tacım

Serin sularda kader terim

