INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir An', 'oyle-bir-an-nurten-tarim-jzbir', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle anlar var ki

Bıçaklasanda kalbimi acı duymaz

Dünyanın çiçeklerini toplasanda

Dindiremezsin acılarımı

Gelmeyeceğini bile bile

Beklersin canından çok sevdiğini

Öyle an ki çok şeyler söylesede ruhun 

Ne dilin söyler  ne de kalemin yazar.

Sonsuz ufuklara bakan gözlerin 

Çölde yağmayan yağmur bulutu.

Zaman durur bir an

Ne bir saniye ileri nede geri gider

Kaçmak istersin karanlıklara 

Uçmak istersin göklere

Buhar olup yok olmak istersin belkide

Öyle anlar var ki

Bakışlarını kaçırırsın

Yaşamın güzelliğini görmek istemezcesine

Gözyaşını damla damla akıtırsın

Buz gibi olmuş kalbine

Boğazın düğümlenir

Günün adını andığın an.

Hiç bir sevinç ve heyecan

Kalbindeki boşluğu dolduramaz

Etrafına dağıttığın tebessümün 

Yalan olduğunu anlarsın 

Anlarsın kendini nasıl  da kandırdığını.

Yıkılırsın  yıkılırsın bir daha

Öyle bir yıkıntı ki

Dimdik duran vücudun içinde 

Kimseye göstermek istemediğin.

Öyle anlar var ki

Acılarla birleştiğin

Yüzlerini bile görmediğin

Tanımak bile istemediğin

İşte o anlardan bir an

Canım dediğim

Doyamadan kaybettiğim

El diye toprağını öptüğüm

Babalar günü

Günün kutlu olsun sevdiğim', 'Öyle anlar var ki Bıçaklasanda kalbimi acı duymaz Dünyanın çiçeklerini toplasanda Dindiremezsin acılarımı Gelmeyeceğini bile bile Beklersin ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/oyle-bir-an-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parola:Hüzün', 'parola-huzun-edip-caki-z174h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Parola 

Saat sekize çeyrek kala

Bir devrin kapısındayım

Bir dinozor fosili

Ve de aralanmış tüm kapılar

Kilidi şifreli bir kadın sesi

Ve kalbinin sınırındayım

Demir sürgülü ve de pençeli

Elim kapıyı döver

Tellere takılmış bir çocuk gibi

Parola

Saat on ikiye beş kala

Gavur dağının ardındaki peri

Parola iki yürek bir deli

Ağlıyorum şimdi

Beni içime almayan

Bir vezin gibi

Kapısındayım bir devrin

İçerde yedi uyuyanlar

Verdiğin aşk geçmez geri

Hangi kimliğin üyesisin

İçime iltica eden

Ve bir mülteci gibi

Yüreğimden sığınma hakkı isteyen

Hangi devrik hüznün liderisin

Parola

Ölümüme sen kala

Dışarıda  ilahi bir komedi

Anımsadım

Kimliğini yeniler şimdi

Bir sessizlik senfonisi

—Parola! 

—Parola hüzün', 'Parola  Saat sekize çeyrek kala Bir devrin kapısındayım Bir dinozor fosili Ve de aralanmış tüm kapılar Kilidi şifreli bir kadın sesi Ve kalb...', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/parola-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımsız Bir Ölüm', 'tanimsiz-bir-olum-edip-caki-97v44', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tanıklık etmek bir gülüşe

Tanıyamadan seni ve kendini

Ve affetmek bir güneşi

Kurtarılmış bir bölge gibi

Hissetmek her hücrenle ayrılığı

Boğulmak bir yağmurun hüznünde

Sana benzetmek her günahı

Ve ekildiğin toprağa

Demirlemek kendini çıkarsız

Efendi bir çocuk gibi ömrümde

Ben diye sevmek seni

Kestirme bir yoldan

Bence,

Sevmek budur seni işte 

Tanımsız bir ölümden önce', 'Tanıklık etmek bir gülüşe Tanıyamadan seni ve kendini Ve affetmek bir güneşi Kurtarılmış bir bölge gibi Hissetmek her hücrenle ayrılığı Boğu...', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tanimsiz-bir-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve...', 've-edip-caki-bqmaj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve tanrı,

Bir anın sesiyle

Mahmurlu gözleriyle

Derin uykusundan uyandı

Yalnızlığıyla yıkayıp yüzünü

Elinin çamuruyla

Kadını yarattı.', 'Ve tanrı, Bir anın sesiyle Mahmurlu gözleriyle Derin uykusundan uyandı Yalnızlığıyla yıkayıp yüzünü Elinin çamuruyla Kadını yarattı....', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ve-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Ve Diğerleri Gibi', 'yalnizlik-ve-digerleri-gibi-edip-caki-18ewc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlık ve diğerleri gibi

Beynimi çiğniyorum

Dişime bağladığım her ip

Darağacına yolcu ediyor yüreğimi

Yalnızlıkta senin gibi

Ve seni çekiyorum

Canımı dişime taktığımdan beri

Yalnızlık ve diğerleri gibi

Yüreğimde bir mey ikindisi

Sarhoşluğumu yağmalıyorum

Dedim ya

Bir ben bilirim bir de yalnızlık

Kukumav gibi

Yontulmuş bir hüzün

Çağırıyor diğerlerini

Yalnızlık ve diğerleri gibi

Gölgeni seviyorum

Dışımda yanan bir dişi

Dişime takıyorum seni

Ve yalnızlık bir sevgili

Seni sevdiğimden beri

Yalnızım işte

Diğerleri gibi

Murdar kahkaların yüzümde

Yüzüne yüzüyorum

Yüreğim 

Deniz seviyesine indiğinden beri

16.08.05', 'Yalnızlık ve diğerleri gibi Beynimi çiğniyorum Dişime bağladığım her ip Darağacına yolcu ediyor yüreğimi Yalnızlıkta senin gibi Ve seni çeki...', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yalnizlik-ve-digerleri-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerek...Şart...', 'gerek-sart-ulvi-ziya-e7udf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Târihteki gücümüz ancak moral verir bize...

Asıl mühim olanı şimdi güçlü koşmamızdır...

Mâzîdeki coşkun seller akıp gitti denize...

Bize elzem olan şey: deryâ olup taşmamızdır...', 'Târihteki gücümüz ancak moral verir bize... Asıl mühim olanı şimdi güçlü koşmamızdır... Mâzîdeki coşkun seller akıp gitti denize... Bize elz...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gerek-sart-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarı Açık Gözlerin', 'yari-acik-gozlerin-edip-caki-cl7qp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yarı açık gözlerinde

Hapsoldum sevdiğime

Negatif bir kan gurubunda

Pozitif düşler zerk ettin

Damarlarıma 

Ellerin demir parmaklık

Gözlerini terk ettim

Bir görüş gününde

Yarı açık gözlerinde

Hapsoldum sevdiğime

Eksildi mateminden

Artırılmış hayat işkenceleri

Ve her ölüm orucunda

Artı eksi bir hayattı

Başucunda uyuklayan

Yarı açık gözlerinde

Firar etmek sevdiğine

Kapalı yüreğinde

Tüneller kazılır alabildiğine', 'Yarı açık gözlerinde Hapsoldum sevdiğime Negatif bir kan gurubunda Pozitif düşler zerk ettin Damarlarıma  Ellerin demir parmaklık Gözlerini ...', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yari-acik-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehrini Sür Yaramın Yüzüğüne', 'zehrini-sur-yaramin-yuzugune-edip-caki-so1pk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bırak beni

Yüzüğünün zehrine

Zehrini sür

Yaramın yüzüğüne

Beni bırak

Matemin eteğine

Eteğin ağır

Ağrımı taşlasana

Ehli dubara! 

Ehli fukara! 

Devir devini

Devrinde deve güreşi

Bırak beni

Hüznünün ovasına

Salını içime

İçime zehrine akıt

Bul beni

Bulutun ağlayan evini

Ağla ör evimin eteğini

Beni bırak

Zehrinin merhemine

Emerek emini

Öl beni

Ehli ulema! 

Ehli cühela! 

Devir devini

Devrinde deve güreşi

Güreşi sen kazandın

Zehrini diğer eşi

Beni bırak

Tutma yüreğimin elini

Yüzüğünün Ummanında

Boğmadan kurtar beni', 'Bırak beni Yüzüğünün zehrine Zehrini sür Yaramın yüzüğüne Beni bırak Matemin eteğine Eteğin ağır Ağrımı taşlasana Ehli dubara!  Ehli fukara!...', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/zehrini-sur-yaramin-yuzugune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Ve İhanet', 'zaman-ve-i-hanet-edip-caki-rjsze', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zamana ihanetten

Yargılanır düşüncem

Seni sevmek için

Ne gündüz var ne gecem

Zamanı durdurdu ahın

Saatler yanlış çalar

Yüreğim ezan sesi

Beynimde yasak çanlar

Tarihin sayfasında 

Gül kırmızı döküldü kanlar

Tazelenmiş bir fermanda

Değişti tüm kanılar

Mevsimler ter yazında

Nasırlı hep ayalar

Günlerim roman oldu

Takvimde işsiz aylar', 'Zamana ihanetten Yargılanır düşüncem Seni sevmek için Ne gündüz var ne gecem Zamanı durdurdu ahın Saatler yanlış çalar Yüreğim ezan sesi Bey...', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-ve-ihanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilemma', 'dilemma-edip-caki-i6k9i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sürgündeki içgüdü

Varsıllık hikâyeleri anlatır

Başkentleri istila eden

Hüzün alayları sancır

Kabakulak duymazlığım içinde

Kendini kandırır

Ve her sürgün ülkesinde

Adını andırır soyadının matemi

Asılacak tüm karıncalar

Cepheye aşk taşıdığı için

Ve istila eden ben

Seni sürgündeki içgüdü

Bileyip bütün ölümleri

Bu bir çelişki

İkilemin içindeyim

Bu ikincisi

Ve yıkılacak tüm kalelerin

Yanı başımda

Ta yüreğinin derinliklerinde

Grizu patlamaları 

Top ve tüfek sesleri

Kandırır yalnızlığını

Payitahtımın sultanısın

Ama

Bu bir varlık fiyaskosu

Ya da bir dilemma', 'Sürgündeki içgüdü Varsıllık hikâyeleri anlatır Başkentleri istila eden Hüzün alayları sancır Kabakulak duymazlığım içinde Kendini kandırır V...', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dilemma-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük ve Adâlet...', 'ozgurluk-ve-ad-let-ulvi-ziya-x1ez4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yöneticilerimiz; 

global dünyâya,

aynen uymak neşvesinde...

Hür düşünce,

hür hayat,

müreffeh bir toplum

oluşturmak hevesinde...

Mahkeme salonlarında.

''Adâlet Mülkün Temelidir'' diye yazar; 

Özgür irâdeyle başlar bile örtülemez,

adâlet bunun neresinde? ...

..', 'Yöneticilerimiz;  global dünyâya, aynen uymak neşvesinde... Hür düşünce, hür hayat, müreffeh bir toplum oluşturmak hevesinde... Mahkeme salo...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozgurluk-ve-adalet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük...', 'ozgurluk-ulvi-ziya-lhyyi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimseyi incitmeden isteneni yapmaktır...

Kötülüğü atarak iyiliği kapmaktır...

Tesettürlü bayanın giysisiyle uğraşmak; 

Nûrlu yolu terkedip,karanlığa sapmaktır...

Kıyıma uğratılan o taptâze fidanlar; 

Türbanı,taç yaprağı; yüzleri,gonca güldür...

Bırakın hür ufkun rüzgârıyla salınsınlar; 

Apansız çöken kâbus yurdumuz için züldür...

Nedir bizleri saran bu vehim.bu vesvese? ...

Özgürlük,güneş gibi ışık sunsun herkese...

Isıtsın,aydınlatsın; ruhlarda çiçek açsın

Bayrak ve ülkemiz bir,yer yok başka hevese...', 'Kimseyi incitmeden isteneni yapmaktır... Kötülüğü atarak iyiliği kapmaktır... Tesettürlü bayanın giysisiyle uğraşmak;  Nûrlu yolu terkedip,k...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozgurluk-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kahve Davettir Bir Şeylere Bu Vakitlerde', 'bir-kahve-davettir-bir-seylere-bu-vakitlerde-abdullah-karabag-5yaow', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haber gönderdim sizlere içimden gelen bir sesle.

Dedim ki Seyhan kıyısında, baraj gölüne bakan

Bir yazlığa gidin bu hafta deniz karası Cengiz’le,

Cevheri alın terinden ibaret Mustafa’ya.

Sizler ki iki arkdaşsınız, öyle görünüyor bana.

Bugün kahveler benden, yudumlanırken kahveler,

Kırkını aşan yaşların tecrübesiyle bakışlarınız

Dağlarda olsun, her ne kadar kar mevsimi değilse,

Karsız da muhteşemdir Çukurova’da dağlar.

Ve Çukurova’nın sevecenliği gibi sıcaktır

Yürekleri insanların, sofraları ve hürmetleri de,

Ünlüdür, işi, ekmeği aslan gibi tutanı severler.

Ve dedim ki dilinize sıvanırken ilk yudumunda kahve 

Bir gözünüz dağlara gitsin, her ne kadar kar mevsimi

Henüz başlamamışsa da yine dağlardan iner Seyhan,

Dipten içe bulanır, burgulanır baraj gölünde

Binlerce dalgalı sudan sarmal hortumlar gibi.

Nasıl anlatabilirim uzaklardan birkaç sözle, 

Kahve sakinliğiyle baraj setinde duranlara,

Aynı saatlerde parçalanmış hatta parçaları bile

Parçalanmış ve yaşına akrep iğnesi gibi

Saplanan ve gün boyu çalışmaktan canı çıkanların,

Bir ek işte koşuşturmalarını, elden, hafif bir şeyler 

Satmak için köşe bucak dolaşmalarını? 

Tam bu vakitlerde pamuk fideleri taraklanır

Komşu apartmanın balkonuna sarkan perdelerinde.

Ve sigaramın dumanıdır, bre, kahvenin dostudur,

Koza gibi gül bağlatır balkondaki saksılı güzellere

Dışarıdan içerilere çekilirken saatler bu vakitlerde.

Güldestan Gibi, toplu şiirler, 2.baskı', 'Haber gönderdim sizlere içimden gelen bir sesle. Dedim ki Seyhan kıyısında, baraj gölüne bakan Bir yazlığa gidin bu hafta deniz karası Cengi...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-kahve-davettir-bir-seylere-bu-vakitlerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Hayat Olamaz', 'sensiz-hayat-olamaz-cuneyt-okkan-7le8x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutluluğuma ışık tuttun

    Doğdun Gönlümde

     

    Benliğimi sardın

    Tüm güzelliğinle

    Aşkımız hep zirvede

    Birbirimize olan sevgimizle

    Beraberliğimizi süsledik

    İki tatlı meyvemizle

    Seni seviyorum

    Dünyalar kadar

    Bir parçamsın

    Sonuna kadar', 'Mutluluğuma ışık tuttun     Doğdun Gönlümde           Benliğimi sardın     Tüm güzelliğinle     Aşkımız hep zirvede     Birbirimize olan sev...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Okkan']::text[], 8.5, '{"poet":"Cüneyt Okkan","poet_slug":"cuneyt-okkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-hayat-olamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Tutsak', 'aska-tutsak-sedat-alkan-rnspc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte geldi aşk, sormadan yine.

Güller soluyor, ellerim kanayarak.

Sözlerime kanma, onlar aşka tutsak.

Sakın aldanma, Yürekler aşka tuzak.

Güneş yetmiyor, yetmiyor yakmaz.

Yağmur dinmese bir an, bir damla ıslatmaz.

Yüreğin kanar geceleri, yarası kapanmaz.

Aşk üstüne aşk, istesem olmaz.

İsteme olmaz.

Ellerimde gül, kanma, gülümü alma.

Gözlerimde yaş, ilk değil ki aldırma.

Gönlüm aşka hovarda,  uslanmaz. 

Ben ağlarım her gece uslanmam, sen ağlama.', 'İşte geldi aşk, sormadan yine. Güller soluyor, ellerim kanayarak. Sözlerime kanma, onlar aşka tutsak. Sakın aldanma, Yürekler aşka tuzak. Gü...', ARRAY['Türk Edebiyatı','Şiir','Sedat Alkan']::text[], 8.5, '{"poet":"Sedat Alkan","poet_slug":"sedat-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aska-tutsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Beni de Okula Gönder', 'baba-beni-de-okula-gonder-devran-demir-i7prr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '/Küçük bir kız çocuğunun 

babasına, büyük bir isyanıdır.../

Baba

Sen beni sevmiyor musun? 

Baba ben bugün tam, on yaşına girdim.

Biliyor musun? 

Baba inan ki hiç para istemem senden.

Gözüm kör olsun istersem eğer.

Baba, ne olur beni de okula gönder.

Arkadaşlarımın hepsi gittiler.

Benden daha küçükler bile.

Baba, ne olur beni de

Beni de okula gönder.

Hem kardeşlerimde artık büyüdüler, tamam.

Ellerim kırılsın onları bir daha döversem eğer.

Baba, ne olur beni de

Beni de okula gönder.

Baba içme şu zıkkımı artık yeter! 

Baba, ne olur beni de

Beni de okula gönder.

Merak etme yine bakarım eve, yine yemek yaparım.

Yine yıkarım çamaşırları, yine ütülerim elbiselerini.

İnan hepsini yine yaparım baba, yaparım söz.

Baba, ne olur beni de

Beni de okula gönder.

Mahalledeki bütün amcalar teyzeler

Biz senin herşeyini alırız dediler.

Sen yeter ki izin ver.

Baba, ne olur beni de

Beni de okula gönder.

-Hem bugün televizyonda söylediler.

Kayıt parası da almıyorlarmış artık.

Baba, ne olur beni de

Beni de okula gönder.

Baba, baba

Baba konuşsana! 

Baba, yine sarhoş mu oldun? 

Baba, uyudun mu yine? 

Of baba of! 

Keşke annem değil sen ölseydin...

Baba,

Baba kızdın mı bana? 

Sen beni...

Sen, beni sevmiyorsun...

Sen içki içmeyi hep...

Sen, içkiyi seviyorsun...

Baba, ne olur beni de

Beni de okula gönder.

Baba, ne olur beni de

Beni de baba...

Baba, beni de...

Beni de okula gönder

2005', '/Küçük bir kız çocuğunun  babasına, büyük bir isyanıdır.../ Baba Sen beni sevmiyor musun?  Baba ben bugün tam, on yaşına girdim. Biliyor mus...', ARRAY['Türk Edebiyatı','Şiir','Devran Demir']::text[], 8.5, '{"poet":"Devran Demir","poet_slug":"devran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/baba-beni-de-okula-gonder-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünleri Satın Umuda', 'huzunleri-satin-umuda-necmi-unsal-deiwc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tutun denizlerden yakamoz.

Renk renk ışık katın umuda.

Alın her güneşten parlak koz.

Bir cesaret atın umuda.

Bırakın paniği, telaşı! 

Hülyalarla yatın umuda.

Akıtmayın gözden dert yaşı! 

Hüzünleri satın umuda.

11 Temmuz 2004 Pazar, Danimarka-Frederikssund 19.18', 'Tutun denizlerden yakamoz. Renk renk ışık katın umuda. Alın her güneşten parlak koz. Bir cesaret atın umuda. Bırakın paniği, telaşı!  Hülyal...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/huzunleri-satin-umuda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zelal', 'zelal-hasan-cangir-tr67z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdim seni,

Sadece sevdim,

Sende tüm kötülükler bende toplanmış sanki,

Tüm acıları yükledin,

...', 'Sevdim seni, Sadece sevdim, Sende tüm kötülükler bende toplanmış sanki, Tüm acıları yükledin, ......', ARRAY['Türk Edebiyatı','Şiir','Hasan Cangir']::text[], 8.5, '{"poet":"Hasan Cangir","poet_slug":"hasan-cangir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zelal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'iyi Ki...', 'iyi-ki-dilek-egri-v5fpa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bana söylediğin tüm seni seviyorumları toplasan 

bir seni seviyorum etmezdi

etseydi

gitmezdi

_eller

__sözler 

___gözler

ve gelmezdi

_güzler

__hüzünler

___yılışık geceler

sen..

aşklarına rötüş yapmış yapmacık aşık..! 

kaç kış akşamı daha aşktan bihaber bağırlarda

üşüteceksin yüreğini..? 

ve siz iki elim.

kaç yalnız akşam daha saracaksınız birbirinizi...? 

beni..? 

/.....................................iyiki de iki tanesiniz...../

28/10/05', 'bana söylediğin tüm seni seviyorumları toplasan  bir seni seviyorum etmezdi etseydi gitmezdi _eller __sözler  ___gözler ve gelmezdi _güzler ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iyi-ki-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Dediğin', 'yasamak-dedigin-seher-gungor-h3m2c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dilsiz,Dipsiz Bir Kuyuda

Kanat Çırparken

Umuda Açılan Pencereye..

Kalmaksa Karanlıkta 

Acı Çığlıklarınla...

Sessiz Feryatlarını 

Duyuramamaksa 

Yaşamak Dediğin..

Ben Hiç Ölmedim Annem..

Ben Hiç Ölmedim..

Seher Güngör

(Küçük Pencerem Saat:23:00)', 'Dilsiz,Dipsiz Bir Kuyuda Kanat Çırparken Umuda Açılan Pencereye.. Kalmaksa Karanlıkta  Acı Çığlıklarınla... Sessiz Feryatlarını  Duyuramamak...', ARRAY['Türk Edebiyatı','Şiir','Seher Güngör']::text[], 8.5, '{"poet":"Seher Güngör","poet_slug":"seher-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasamak-dedigin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açıkta Kalmış Yara Misali', 'acikta-kalmis-yara-misali-tunahan-ermihan-s50z1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözleri vardı bilmezsiniz siz

Baktığım zaman alemleri tavaf ettiğim

Kahve rengi gözleri vardı

Ben maviye vurgunken

Rüyalarım yeşile çalarken

Beni benden alan kahve tonları vardı 

Bilemezsiniz

Ağladığı zaman kanardı yüreciğim

Sızlardı kemiklerim açıkta kalmış yara misali

Üzülürdüm her damla için ayrı ayrı

Gözlerine oturan her kan damlasında

Ömrümü tüketirdim sonra

Bilemezsiniz gözleri vardı

Günahlarını gözlerimde söndüren

Hatalarını masum gösteren

Ve hatta gidişine bile susmama sebep

Gözleri vardı

Öyle sıradan

Anlamı bana ait

Kimsenin özellikle fark edemeyeceği

Gözleri vardı bilemezsiniz

Sıradandı gözleri

Sözleri sıradandı

Sıradan olmayan sevdamızdı

Oda yaşanacakken hazan oldu

Gözleri vardı bilemezsiniz', 'Gözleri vardı bilmezsiniz siz Baktığım zaman alemleri tavaf ettiğim Kahve rengi gözleri vardı Ben maviye vurgunken Rüyalarım yeşile çalarken...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/acikta-kalmis-yara-misali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Var Mı?', 'haberin-var-mi-i-brahim-halil-demir-vk1eu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Giderayak gönlüme düşürdüğün kıvılcımın,

Alevlere dönüştüğünden haberin var mı? 

Sevda sürmeli gözlerinle yüreğimde inşa ettiğin,

Aşkının bedenimi kütrüm ettiğinden haberin var mı? 

Alımlı bakışlarınla sana sevdalı gözlerimin,

Ferini alıp beraberinde götürdüğünden haberin var mı? 

Giderayak aşkın kazmasıyla bana en derin mezarı

Kazdırdığından haberin var mı? 

Postacı misali kapı kapı seni ondan bundan,

Hummalıca sorduğumdan haberin var mı? 

Bulamadığımda,izine rastlayamadığımda,

Mum misali yavaş yavaş eridiğimden haberin var mı? 

Giderayak sevda bahçemde senin için yetiştirdiğim,

Rengarenk aşkın güllerinden haberin var mı? 

Elimde sevda çapası,güllerin etrafını bellerken,

Senin adına yaktığım türküyü söylediğimden haberin var mı? 

Tam gölge ve meyve verecekken,

Beni sevdanın kızgın güneşi altında bıraktığından haberin var mı? 

Giderayak döktün kezzabı, sevda ormanlarımın köküne,

Bu yaptığından haberin var mı? 

En beğenmediklerimizin bile arkamızdan bizi yermelerinden

Haberin var mı? 

Gökyüzünü süsleyen yıldızların birer birer,

Bu yaptıklarından dolayı döküldüklerinden haberin var mı? 

06-11-2005', 'Giderayak gönlüme düşürdüğün kıvılcımın, Alevlere dönüştüğünden haberin var mı?  Sevda sürmeli gözlerinle yüreğimde inşa ettiğin, Aşkının be...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/haberin-var-mi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Bayramda / Şiir Perisine', 'bu-bayramda-siir-perisine-i-brahim-usta-6al1l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mübarek Ramazan''ın farkına varmış mıyız? 

Günahkar ruhumuza, ruhundan almış mıyız? 

Kalbimize imanın nurunu sarmış mıyız? 

Nefsimizle bir hesap görelim bu bayramda..', 'Mübarek Ramazan''ın farkına varmış mıyız?  Günahkar ruhumuza, ruhundan almış mıyız?  Kalbimize imanın nurunu sarmış mıyız?  Nefsimizle bir he...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Usta']::text[], 8.5, '{"poet":"İbrahim Usta","poet_slug":"i-brahim-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bu-bayramda-siir-perisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzuhal', 'arzuhal-latif-oz-ebg0d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir çift gözün hayaline düşeli

Sinemdeki yanan hardır köz değil

Otuz üçte şakak akla döşeli

Ömrümün yazıdır kuru güz değil

Yar cefa etmekte nice mahirdir

Bu cevir ne evvel ne de ahirdir

Cefa yardan gelsin sine bahirdir

Mihnet bana zevktir inan az değil

Ey ehibba sorgu sual ettiniz

Her biriniz bir yanımdan tuttunuz

Beni çuval gibi yere attınız 

Çuvalda can dolu sade bez değil

Ah u efgan ettim felekler yuttu

Nalem gözümdeki yaşı kuruttu

Biçare ahvalim dağlar eritti

Cananın kalbi taş karla buz değil

Ne geldiyse bana kendimden geldi

Ayrılık sözleri sinemi deldi

Benimle inleyen sazımda teldi

Yürekteki hançer ince biz değil

Ahdetmiş olanlar ahdin almadı

Arayanlar mutluluğu bulmadı

Dedeye babaya bir şey kalmadı

Dünya üvey ana Latif, öz değil', 'Bir çift gözün hayaline düşeli Sinemdeki yanan hardır köz değil Otuz üçte şakak akla döşeli Ömrümün yazıdır kuru güz değil Yar cefa etmekte ...', ARRAY['Türk Edebiyatı','Şiir','Latif Öz']::text[], 8.5, '{"poet":"Latif Öz","poet_slug":"latif-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/arzuhal-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun.', 'gidiyorsun-ugur-kilic-d1gg8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben gözlerinde

Mutluluğu ve güzelliği görüyorum

Ondandır

Gözlerine dalıp dalıp gidiyorum

Ben huzuru bir evimde

Bir senin yanında buluyorum...

Gidiyorsun  huzurum gidiyor

Gidiyorsun  korkular başlıyor

Gidiyorsun  sol yanım acıyor

Gidiyorsun...

Gidişin kapının eşiğinde duruyor,

Gurbet başlıyor aramızda

Senin sevincin

Benim hüznümü kapatıyor.

Bir yanım hüzün bir yanım mutluluk

Mutluluğum mutluluğuna ortak

Hüznüm sensizliğe....

Gidiyorsun  huzurum gidiyor

Gidiyorsun  korkular başlıyor

Gidiyorsun  sol yanım acıyor

Gidiyorsun...

Dönüş yollarını bekleyecek gözlerim

Bir gün olsun sensiz gecmeyecek günlerim

Elim sol yanımda, kalbimde hissedeceğim seni

Ve inan tutacağım sana verdiğim tüm sözleri..

Gidiyorsun  huzurum gidiyor

Gidiyorsun  korkular başlıyor

Gidiyorsun  sol yanım acıyor

Gidiyorsun...

Yürüdüğümüz yollarda yürümek haram olacak

Evin önünden gecerken pencerede gözlerim kalacak

Gülüşün özlenecek, gül yüzün  aklımdan çıkmayacak 

Biliyorum gidişinin akabinde beni saracak hüzün

Gidiyorsun  huzurum gidiyor

Gidiyorsun  korkular başlıyor

Gidiyorsun  sol yanım acıyor

Gidiyorsun...', 'Ben gözlerinde Mutluluğu ve güzelliği görüyorum Ondandır Gözlerine dalıp dalıp gidiyorum Ben huzuru bir evimde Bir senin yanında buluyorum.....', ARRAY['Türk Edebiyatı','Şiir','Uğur Kılıç']::text[], 8.5, '{"poet":"Uğur Kılıç","poet_slug":"ugur-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gidiyorsun-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiye''yi Dinliyorum', 'turkiye-yi-dinliyorum-hakan-yildirim-v7s8u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Orhan Veli''ye''

Türkiye''yi dinliyorum, gözlerim kapalı; 

Önce bir çatışma rüzgarı esiyor; 

Yavaş yavaş sallanıyor 

Ölüler ağaçlarda; 

Uzaklarda çok uzaklarda

Katillerin hiç susmayan silahları; 

Türkiye''yi dinliyorum, gözlerim kapalı.

Türkiye''yi dinliyorum, gözlerim kapalı

Gençler geliyor derken; 

Meydanlardan sürü sürü, çığlık çığlık

Kanım donuyor damarlarımda

Bir milletin suya düşüyor umutları.

Türkiye''yi dinliyorum, gözlerim kapalı

Tıklım tıklım Çankaya yokuşu,

Karma karışık Beyazıt

Ceset dolu avlular.

Silah sesleri geliyor sokaklardan

Güzelim bahar rüzgârında kan kokuları

Türkiye''yi dinliyorum, gözlerim kapalı.

Türkiye''yi dinliyorum, gözlerim kapalı

Başımda yeni ölümlerin son sarhoşluğu

Loş dersaneleriyle bir okul boş odalı

Dinmiş nârâların uğultusu içinde

Türkiye''yi dinliyorum, gözlerim kapalı.

Türkiye''yi dinliyorum, gözlerim kapalı

Bir kâtil geçiyor kaldırımdan; 

İniltiler, sızlanmalar, hırlamalar, sloganlar

Bir şey düşüyor elinden yere; 

Bir tompson olmalı; 

Türkiye''yi dinliyorum, gözlerim kapalı.

Türkiye''yi dinliyorum, gözlerim kapalı

Bir can çırpınıyor sokaklarında

Alnım sıcak mı, değil mi bilmiyorum

Parkam ıslak mı, değil mi bilmiyorum

Kan çıkıyor gömleğimin arkasından

Kalbimden vurulmuşum anlıyorum

Türkiye''yi dinliyorum.', '''Orhan Veli''ye'' Türkiye''yi dinliyorum, gözlerim kapalı;  Önce bir çatışma rüzgarı esiyor;  Yavaş yavaş sallanıyor  Ölüler ağaçlarda;  Uzakla...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yıldırım']::text[], 8.5, '{"poet":"Hakan Yıldırım","poet_slug":"hakan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/turkiye-yi-dinliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-zahide-handan-erengil-q5tuq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Issız ve soğuk bir gece,

Kaldırımda ayak sesleri tak tak,

Gökyüzü yıldızlarla dolu bir bak.

Sessizlik ve soğuk iliklere işliyor,

Gönül sabahın ilk ışıklarını düşlüyor.

Düşünüyorum neden bu kaldırımdayım? 

Bilmem nasıl duygulardayım? 

Gece insana ürküntü veriyor,

Kaldırımda ayak sesleri,

Kesiyor bütün nefesleri.

Takip eden biri var bak, 

Tanrım beni duygularımla bırak.

İzleyen gölgem olmalı,

Sonsuza kadar peşimi bırakmalı.

Ne kadar kaçabilirsin kendinden? 

Emin misin bırakır diye gölgenden? 

Ayrılamayız o ve ben,bir bedendeyiz,

İstemesem de ebediyen birlikteyiz.

Zahide Handan Erengil', 'Issız ve soğuk bir gece, Kaldırımda ayak sesleri tak tak, Gökyüzü yıldızlarla dolu bir bak. Sessizlik ve soğuk iliklere işliyor, Gönül sabah...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/golge-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sefer', 'sefer-hakan-yildirim-o1cxo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman oldu; 

Bir çamçak kımızı bölüştük seninle,

Zaman oldu; 

Ak yeleli atlarımızla,

Akın eyledik düşman üstüne

Birden; 

Allah Allah! nidâları sardı arşı,

Korkusuzca hücûm ettik düşmana karşı.

Derken; 

Kefen oldu ak esvâb

Defn eylediler o güzel nâşı.

Ey yiğit asker temiz ruhun şad ola,

Yardımcın Habibullah, yoldaşın Kür-şad ola.', 'Zaman oldu;  Bir çamçak kımızı bölüştük seninle, Zaman oldu;  Ak yeleli atlarımızla, Akın eyledik düşman üstüne Birden;  Allah Allah! nidâla...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yıldırım']::text[], 8.5, '{"poet":"Hakan Yıldırım","poet_slug":"hakan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sefer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Aşk / Sağ Şiir', 'olu-ask-sag-siir-tulay-sustam-crk8t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'doğmadan 

öldürdüler aşkımı

yeri dolsun diye! ...

kâh geceden,

kâh gündüzden

şiirler doğurdum

her birinin adını 

''''sen'''' koydum

artık aşkım ölü

şiirim sağ...



05 kasım

derin aşk kırıntıları', 'doğmadan  öldürdüler aşkımı yeri dolsun diye! ... kâh geceden, kâh gündüzden şiirler doğurdum her birinin adını  ''''sen'''' koydum artık aşkım ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olu-ask-sag-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Yıllara Bitanesi', 'nice-yillara-bitanesi-metin-usengec-6q2at', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar gelip geçiyor

İstesek de istemesek de durmuyor yerinde

Bir yıl nedir ki

Bir an bir gün geçmedi hayatım sensiz

Belki bir ömür geçse de, kaderimsin unutmam 

Hatırlarım seni yaşadıkça doğum gününde

Doğum günün kutlu olsun bitanesi..

XX-XXXXX-2005   04:20

Sevgi emektir, emek ise vazgeçmeyecek kadar, ama özgür bırakacak kadar sevmektir..', 'Yıllar gelip geçiyor İstesek de istemesek de durmuyor yerinde Bir yıl nedir ki Bir an bir gün geçmedi hayatım sensiz Belki bir ömür geçse de...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nice-yillara-bitanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-hakan-yildirim-icbie', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biz,

Fırat ve Dicle gibi

Çılgın iki âşık...

Şat-ül Arap''ta buluşup,

Basra''ya akacaktık.

Biz,

Kura ve Aras gibi

Yorgun iki âşık...

Hazar''da bulut olup,

Türk iline yağacaktık.

Biz,

Fâtih ve İstanbul gibi

Güçlü iki âşık...

Ülkümüz için gemilerle

Dağları aşacaktık.

Biz,

Yavuz ve Mısır gibi

Kutsal iki âşık...

Sevdamız uğruna

Çölleri geçecektik.

Biz, 

Anadolu ve Türkistan gibi

Ayrı iki âşık...

Turan Yurdu adında

Tek bir beden olacaktık.

Ve biz,

Büyük Türkiye için

Canımızı verip,

Tarihe

Tuğramızı basacaktık.

(05.12.2000)', 'Biz, Fırat ve Dicle gibi Çılgın iki âşık... Şat-ül Arap''ta buluşup, Basra''ya akacaktık. Biz, Kura ve Aras gibi Yorgun iki âşık... Hazar''da b...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yıldırım']::text[], 8.5, '{"poet":"Hakan Yıldırım","poet_slug":"hakan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/biz-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S e v m e k...', 's-e-v-m-e-k-mehmet-ali-demircan-x8z1i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.       (Sevgi, Sevi, Sevda =  AŞK)     

Sevmek; Yürek ister,

                Cesaret, özveri ister.

                Acıyı, kederi, yalnızlığı, mutluluğu, hissetmek,

                Yüreğini, avuçlarının içinde sımsıcak tutmak ister.

Sevmek; Karlı hava da baharı yaşamak,

                Tipiye tutulduğun da durulmak ister. 

                Soğuk ayazlar da titrerken,

                Sıcağı iliklerin de hissetmek ister.

Sevmek; Azgın dalgaların içinde durulmak,

                Fırtınayı esintiye çevirmek ister.

                Her şeyin bittiği anda yeniden başlamak,

                Zorluklara göğüs germek ister.    

Sevmek; Yıldızların altın da hüzünlenmek,

                Gülü tuttuğun da acıyı hissetmek ister.

                Neşenin için de kederlenmeyi,

                Gülmenin için de ağlamayı ister.

Sevmek; Acının için de tatlıyı,

                Tuzlunun için  de ekşiyi ister.           

                Bıçak yarası, kurşun yarası,

                Dil yarası, gönül yarası, sevda yarası ister.

Sevmek; Yaşamayı sevmeyi,

                Kuşları, ağaçları, taşı, toprağı,

                Canlıyı, cansızı,

                Var olanı sevmeyi ister.                

Sevmek; Kendinle barışık olmayı,

                Kendini sevmeyi ister.

                Yalnızlığın için de birlikteliği,

                Kalabalık için de yalnızlığı ister.

Sevmek; Sevgiyi yüreğinde, beyninde, bedeninde,

                Damarlarındaki kanın akışında hissetmek ister.

                Ağlarken gülebilmeyi,mutluyken hüzünlenmeyi,

                Hele ki Severken, yürekten sevilmeyi ister. 

            

Sevmek; Yalandan uzak kalmayı,

                Doğrudan yana olmayı ister.

                Yaşarken sevilmeyi,

                Her şeyi olduğu gibi sevmeyi ister.

Sevmek; Sevilmek için sevmeyi, 

                Hayatı güzelleştirmek için gülmeyi ister.

                Severken ölmemeyi,

                Hiçbir zaman kahrolmamayı ister.

Sevmek; Kalpleri birbiri için atarken sımsıcak,

                Sevgi öpücükleri ile beslenmek ister.

                Sevdiğine, sevgisini aşk şiirleri ile sunmak,

                Sevdasını kalbine sevgiyle kazımak ister.  

                Güneşin her doğduğunda yeniden açmak ister.

Sevmek; Gerçek sevği, sevdiğine

                SENİ SEVİYORUM diyebilmek ister.

                Varsa o yürek, sev sevebildiğin kadar.

                Çıkarsız, Adam gibi YÜREKTEN SEVMEK...

                Yürekten, içten, sevgiyle söylemek ister. 

                Seni Seviyorum. Seni Seviyorum. Seni Seviyorum.

                Seni Seviyorum. Seni Seviyorum. Seni Seviyorum.

MAD.15.12.2003', '.       (Sevgi, Sevi, Sevda =  AŞK)      Sevmek; Yürek ister,                 Cesaret, özveri ister.                 Acıyı, kederi, yalnızlı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Demircan']::text[], 8.5, '{"poet":"Mehmet Ali Demircan","poet_slug":"mehmet-ali-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/s-e-v-m-e-k-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-hidir-dastan-qack9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve

Şair gebedir geceye

Gece şiire

Sancı; 

çelişkisidir yaşamın

Acı; 

Düşüncesi

Yirmidört saat süren

bir geceden sonra

döküldü mısralar.

Sancı durdu.

Ama

İnsanlar yine kör

yine hissiz.

Ömründen çalınanlar

anarken çalanları sessiz ve sitemsiz

Şair yine gebe şiire

Yine gebe

doğruya ve güzele

Kalemi Siper

Kağıdı kalkan yapıp

Yine gebe

Yine gebe şiire

Doğruya ve güzele

14.10.1993', 'Ve Şair gebedir geceye Gece şiire Sancı;  çelişkisidir yaşamın Acı;  Düşüncesi Yirmidört saat süren bir geceden sonra döküldü mısralar. Sanc...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Daştan']::text[], 8.5, '{"poet":"Hıdır Daştan","poet_slug":"hidir-dastan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sair-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Sustu', 'o-sustu-hakan-yildirim-yj6hi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O sustu, hep sustu

Ben ağladım.

Geceleri ninni söyledim sevdama,

Mevsimlerden,

Hep baharı derdim.

Aynalı beşiklerde, hamaklarda salladım.

O sustu, hep sustu

Ben ağladım.

Ne istediyse yaptım,

''Gak'' deyince et, ''guk'' deyince su.

Sırf kaçmasın diye uykusu

Sırtını poh pohladım,

Altını kuru tuttum.

Sevdamla boğuşurken ben,

Sevdamı unuttum.

Sonra,

Günler, gecelerce hep kendimi yerdim,

Dağlar mı büyüktü,

Yoksa daha mı büyüktü benim derdim.

O sustu, hep sustu

Ben ağladım...

(09.09.2005)', 'O sustu, hep sustu Ben ağladım. Geceleri ninni söyledim sevdama, Mevsimlerden, Hep baharı derdim. Aynalı beşiklerde, hamaklarda salladım. O ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yıldırım']::text[], 8.5, '{"poet":"Hakan Yıldırım","poet_slug":"hakan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/o-sustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tadı Yok', 'tadi-yok-hakan-yildirim-3yf3n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde fırtına, bir garip hüzün,

Ruhuma aksetti o güzel yüzün,

Sensiz ne gecenin, ne gündüzün,

Tadı yok sevdiğim tadı yok inan.

(22.09.2003)', 'İçimde fırtına, bir garip hüzün, Ruhuma aksetti o güzel yüzün, Sensiz ne gecenin, ne gündüzün, Tadı yok sevdiğim tadı yok inan. (22.09.2003)...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yıldırım']::text[], 8.5, '{"poet":"Hakan Yıldırım","poet_slug":"hakan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tadi-yok-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarın çocuğu', 'ruzgarin-cocugu-salim-kabasakal-93ia2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaç yorgun akşam sen.

Duymasam sesini,görmesem yüzümü

Kabus oluyor her günüm

Öyleki; 

İçimde varlığın,

Özümle buluşuyor.

..... lar arkasına bıraktığım

Ahh bir daha olmayacaksın.

Soğuk lodos vurdu yüzüme,

Üşüyen bedenim değildi sanki

Usulca sokuldum,

Beni terk ettiğin güne.

Odamda dolaşan büyün 

Ve ben rüzgarın çocuğu,

Solmuş fotoğraflarımda yılların vurgunu', 'Kaç yorgun akşam sen. Duymasam sesini,görmesem yüzümü Kabus oluyor her günüm Öyleki;  İçimde varlığın, Özümle buluşuyor. ..... lar arkasına ...', ARRAY['Türk Edebiyatı','Şiir','Salim Kabasakal']::text[], 8.5, '{"poet":"Salim Kabasakal","poet_slug":"salim-kabasakal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ruzgarin-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derindir Sana Aşk Yaralarım', 'derindir-sana-ask-yaralarim-kamil-soylemez-ucyfb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sor sorgula beni 

Yüreğinde ara

Var ise ufacık ta sevda

Sor sorgula

Papatyada,gülde savdam sana

Çığlık çığlık martıda ara

Esen her meltemde 

Dağ başlarında karlarda

Seni seyrediyorum unutma

Boz kırlarda benim gözlerine manzara

Çiçek benim sana

Gelincik rengidir umut tarlam

Günde gecede yanındayım

Unutma kara sevdam

Sor sorgula ara

Ufacıkta var ise yüreğinde sevda

Dokun aşkım göz ucunda olsa yanağıma

Yansın tüm hoyratlıklarım

Çekilsin sevdanla kanım

Ne sipere yatarım

Ne de sensizliğe 

Derindir sana aşk yaralarım

Umarım beni sende yüreğinde saklarsın', 'Sor sorgula beni  Yüreğinde ara Var ise ufacık ta sevda Sor sorgula Papatyada,gülde savdam sana Çığlık çığlık martıda ara Esen her meltemde ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/derindir-sana-ask-yaralarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâr', 'y-r-hakan-yildirim-gzmht', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yârin verdiği bir gül bize gülizâr gelir,

Kokusunda muhabbet, renginde bahâr gelir.

Değil yârin kendisi, selâmı gelse dahi,

Yollara dürr-i çiçek zindana envâr gelir.

(22.11.2004)', 'Yârin verdiği bir gül bize gülizâr gelir, Kokusunda muhabbet, renginde bahâr gelir. Değil yârin kendisi, selâmı gelse dahi, Yollara dürr-i ç...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yıldırım']::text[], 8.5, '{"poet":"Hakan Yıldırım","poet_slug":"hakan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yar-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçer Beşer', 'ucer-beser-cumhur-karaca-pk10u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocukluğumdan kalan 

Üç beş şarkı var; 

Gençliğimde geçtiğim

Sokakların söylediği..

Üç beş şarkı var; 

Ama, kaldırımların bilmediği..

Dut ağacından düşüremediğim

Notaları var..

Sazımın perdelerinde gezinmediği..

Gençliğimden kalan

Üç beş damla var; 

Yaşlılığımda geçtiğim anılarımdan

Hasrete düşürdüğüm

Üç beş damla var; 

Ama, sevdalarımın bilmediği..

Yar penceresinden

Seslenişlerim var; 

Çığlığın bile sessiz kaldığı

Damlaların daha çok çağladığı..

Üç beş şarkı ve 

Üç beş damla..

Tüm hayatın uzunluğu, kısalığı..

Üç günlük dünya gibi,

Üç beş sevgi gibi..

Yan yana geldiğinde

Ömrün yarısı gibi..

Üç beş hatıram var,

Üç beş dişim olduğu gibi..

Hayatın basamaklarını çıkmak,

Üçer beşer..

Ya da beşer beşer..

Hayatın girdabında bir beşer,

Öylesine sever, öylesine yaşar..

Kimi dudak büker kimi de şaşar! 

Ne kadar ki gideceğimiz yol? 

Üç beş karış değil mi? 

Kim varmış baki olan,

Gök kubbe altında

Nedir gerçek ve nedir yalan? ..

Üçer beşer geçtiğimiz

Basamaklarda bırakılan

Üç beş hatıra..

Ardımızdan atılan

Üç beş kürek kara toprak..

Sevdalım! 

Üçü beşi bırakalım,

Son ne olur onu söyle! ! 

Habire düşmekte dallarından

Üç beş yaprak...

Sen, en son ne olur? 

Onu söyle...', 'Çocukluğumdan kalan  Üç beş şarkı var;  Gençliğimde geçtiğim Sokakların söylediği.. Üç beş şarkı var;  Ama, kaldırımların bilmediği.. Dut ağ...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Karaca']::text[], 8.5, '{"poet":"Cumhur Karaca","poet_slug":"cumhur-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/ucer-beser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-salim-kabasakal-3bkd5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni göreceksin, içten atıan bir kahkahada

Bazen,

Yanaklarından aşağı usulca süzülen damla damla gözyaşında

Bazen

Kelimelerin ruhu vurduğu, meçhul şairin mısralarında

Bazen

Elma şekeri sarhoşluğunda ve bir çoçuk bakışında 

Ve bazen; bazen olmayan bir zamanda

Hangi günahımın bedeli ise,

Sen bir gün beni göreceksin.

Kanatlarımda güneşin rengiyle', 'Beni göreceksin, içten atıan bir kahkahada Bazen, Yanaklarından aşağı usulca süzülen damla damla gözyaşında Bazen Kelimelerin ruhu vurduğu, ...', ARRAY['Türk Edebiyatı','Şiir','Salim Kabasakal']::text[], 8.5, '{"poet":"Salim Kabasakal","poet_slug":"salim-kabasakal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bazen-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak Taş', 'sicak-tas-aynur-uluc-7n063', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ölüm hayata geliyordu 

hayat ölümsüz oldu!', 'ölüm hayata geliyordu  hayat ölümsüz oldu!...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sicak-tas-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silinmez Yazı', 'silinmez-yazi-mehmet-postalli-vyp2k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlahi kalemle yazılan yazı

Beşer kudretiyle karalanır mı? 

Yar elinden ise kalpdeki sızı

Doktorla, ilaçla aralanır mı?', 'İlahi kalemle yazılan yazı Beşer kudretiyle karalanır mı?  Yar elinden ise kalpdeki sızı Doktorla, ilaçla aralanır mı?...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/silinmez-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşarken', 'yasarken-devran-demir-e9ty0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yatağına sığmayan bir su gibi yüreğin

sabırlı çok telaşlı biraz durgun

bir yer aranır hep akabilsin kendini

umutlu çok kaygılı biraz yorgun

değil mi ki bugün var yarın yoksun

dökemeden içini gitmekten korkun 

ölüm herşeyi bitirir siler bir gün 

seni yaşarken anlasınlar istiyorsun

2005', 'yatağına sığmayan bir su gibi yüreğin sabırlı çok telaşlı biraz durgun bir yer aranır hep akabilsin kendini umutlu çok kaygılı biraz yorgun ...', ARRAY['Türk Edebiyatı','Şiir','Devran Demir']::text[], 8.5, '{"poet":"Devran Demir","poet_slug":"devran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasarken-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvallah', 'eyvallah-salim-kabasakal-rfkum', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç sabaha şarap sarhoşluğuyla merhaba dedik,

Bilmezdik kısamıydı?  yoksa uzun mu? 

Bir sevda ki öylece özgür ve öylece masum

Adını koymuşuz,

Eyvallah', 'Kaç sabaha şarap sarhoşluğuyla merhaba dedik, Bilmezdik kısamıydı?  yoksa uzun mu?  Bir sevda ki öylece özgür ve öylece masum Adını koymuşuz...', ARRAY['Türk Edebiyatı','Şiir','Salim Kabasakal']::text[], 8.5, '{"poet":"Salim Kabasakal","poet_slug":"salim-kabasakal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/eyvallah-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğim gün teknem batmış farzet', 'gittigim-gun-teknem-batmis-farzet-salim-kabasakal-pit9v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gittiğim gün yankılanan sesim kaldı

Kıyılara vurmakta çığlık çığlık,

Maviyi beyaza bölen köpüklerim

Bir martının kanatlarında uzayıp kaybolurum

Deli dalgaları aralayan teknelerin sırrı gibi

Batık bir teknede yosunlaşan umutlarımla

Ağır oldu aşkın 

Gittiğim gün teknem batmış farzet.

Herşeyimsin 

Bilmelisin deniz benden ben senden ayrılamam.', 'Gittiğim gün yankılanan sesim kaldı Kıyılara vurmakta çığlık çığlık, Maviyi beyaza bölen köpüklerim Bir martının kanatlarında uzayıp kaybolu...', ARRAY['Türk Edebiyatı','Şiir','Salim Kabasakal']::text[], 8.5, '{"poet":"Salim Kabasakal","poet_slug":"salim-kabasakal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gittigim-gun-teknem-batmis-farzet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut şehirleri', 'umut-sehirleri-yahya-akbulut-raz56', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllar önce terk ettim,

çıplak ellerimle kurduğum 

umut şehirlerini.

Yalnızca kalbimi çakılı 

bıraktım her direkte...

Ruhumu alıp uzaklara götürdüm 

Acılarımla birlikte.

Bugün havası o şehirlerin

hala burnumda.

Düşüncelerime kokuyor.

Konuşacak hiç bir şey kalmadığında

sessizliği, yine de benim sessizliğim.

Kapattığımda gözlerimi...

Tutuluyor hala nefesim! 

 07.11.2005 / Çorlu', 'Yıllar önce terk ettim, çıplak ellerimle kurduğum  umut şehirlerini. Yalnızca kalbimi çakılı  bıraktım her direkte... Ruhumu alıp uzaklara g...', ARRAY['Türk Edebiyatı','Şiir','Yahya Akbulut']::text[], 8.5, '{"poet":"Yahya Akbulut","poet_slug":"yahya-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/umut-sehirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fısıldayarak Haykırıyorum Adını', 'fisildayarak-haykiriyorum-adini-hatice-yildiz-yasar-6x9qm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne olur, ne olur 

kayan bir yıldız göreyim

bir yıldız kaysın demiyorum

biliyorum ki bir çok yıldız kayıyor

işte 

o kayanlardan birini göreyim

haykırışımı yükleyeyim

içine damlasın

gönlüne damlasın sesim

sesimle ulaşsın yüreğim

yüreğim

yüreğim onun yüreğinin içine damlasın

bir isim bu kadar mı güzel olur

bu kadar mı güzel anlamlar katar

bir yüreğe

fısıltıyla bağırdım

bağıra bağıra çağırdım adını

yıldızları kollayarak

dedim ki

senin  gönlünden geçen de 

benimkiyle aynı olsun 

bozulmasın hiç bir düzen

fiziksel maddesel hiç bir düzen

günlüme düştün

gönlüne düştüm mü

onlar yüreklerimizden umutlarını kessinler

madddemizle yetelim

bencilce mi

peki

tamam

öyleyse

neyin bedelini ödüyorum

onlara kötülük mü ederiz

...

ha canım be

canımsın

hiç mi susayıp uyanmazsın

uyanıp da ne oluyor bana demezsin

o sırada fısıltıyla bağırışımı

adını haykırışımı duymazsın

yüreğine

şöyle ılıkça

akmaz mı bir şeyler

sıcacık oluvermez mi

arzına ulaşınca yüreğinin

o damlacık

kaynamaz mı fokurdayarak

sonra da ''noluyor bana'' derken

ilk aklına gelen ben olmaz mıyım

bana yormaz mısın 

bu harareti

bu halet-i ruhiyeni

eh be canım

eh ben sana diyeyim

daha ne diyeyim ki

kolum yoruldu

boynum belim ağrıdı

başımı dayadığım elim uyuştu

dizlerim sızladı 

pencerenin önüne diz çöktüm diye

yıldızları kollamaktan 

gözlerim kaymaya başladı

kayan bir yıldız bekledim

onunla gönderecektim mesajımı

diğerini almadın ya

bu garantiydi

olmadı

susadım da

su içmeye gitmedim

yıldızları kaçırmayayım diye

eh ben sana ne diyeyim be adam

...

28 temmuz 2000 / Bursa', 'ne olur, ne olur  kayan bir yıldız göreyim bir yıldız kaysın demiyorum biliyorum ki bir çok yıldız kayıyor işte  o kayanlardan birini göreyi...', ARRAY['Türk Edebiyatı','Şiir','Hatice Yıldız Yaşar']::text[], 8.5, '{"poet":"Hatice Yıldız Yaşar","poet_slug":"hatice-yildiz-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/fisildayarak-haykiriyorum-adini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimce', 'kendimce-beytullah-ozturk-jxmb9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Bu gece en hüzünlü şiirleri yazabilirim''

Ne güzel söylemiş şair böyle

Evet gecede saklı hüzün ve beste 

Sevgiler de gecede saklı işte böyle

Gecelerdeydi yine biran kayboldum

Peki neden,niçin heran savruldum

Şöyle demeliydim belki de avunmalıydım

''Gece yıldızlardaydı ve uzakta parlarlar''

Sen bir yıldızdın şu bende

Ama sen uzaktaydın uzaktasın şimdi

Elimi uzatıyorum koşuyorum sana 

Ben koştukça kaçıyorsun uzaklara

Şimdi uzaklardasın orda parlıyor yıldızın 

Ben burda yoksunken senden ışığından

Sen uzaktasın,nerde kimbilir nasıl? 

Uzaktasın işte bir bakışım kadar

Uzatsam elimi dokunabileceğim kadar

Kalbinden kim bilir çoktan attın beni

Aklından yanından kim bilir? 

Sen attın ama ben gitmedim gidemedim

Sen uzaklaştırdıkça beni senden

Ben tuıttum beni sende kendimce...', '''Bu gece en hüzünlü şiirleri yazabilirim'' Ne güzel söylemiş şair böyle Evet gecede saklı hüzün ve beste  Sevgiler de gecede saklı işte böyle...', ARRAY['Türk Edebiyatı','Şiir','Beytullah Öztürk']::text[], 8.5, '{"poet":"Beytullah Öztürk","poet_slug":"beytullah-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kendimce-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Elma', 'yarim-elma-bahri-yildirim-8d11b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle biz:

Bir elmanın iki yarısı gibiyiz

Bölünürsek şah ortamızdan

Tamamen birbirimize benzeriz.

Senin yanakların kızarırsa

Sızlar benim de yüreğim.

İkimizde bir tohumdan 

Bir canda buluşmuşuz.

Tadımız kalır damaklarda

Seninde kurur susuzlukta dudağın

Birimiz kırksa

Kırkımızda birdir bizim.

Ne zamanki bir can oluruz

Geçeriz birlikte meydana

İkimize birden sorulur sorgumuz.

Senin  anlayacağın

Yaşamı paylaşırız

Dostlukların tadında.

Bize güç verir sevdamız.

Çözülür bilinmezliklerin sırrı.

Dostluk denen  deryada

Biz sevdikçe birbirimize benzeriz.

Yalan denen Dünyada.

Kızarır Güneşler altında  birlikte tenimiz.

Bir elmanın iki yarısı gibiyiz 

Seninle biz...

Biz sevince Allahına kadar severiz

 Gülabi Deniz', 'Seninle biz: Bir elmanın iki yarısı gibiyiz Bölünürsek şah ortamızdan Tamamen birbirimize benzeriz. Senin yanakların kızarırsa Sızlar benim ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yarim-elma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kınalı Keklik', 'kinali-keklik-mehmet-postalli-q39pu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koyun otlatırken bir keklik gördüm

Çırpınıp duruyor kınalı keklik

Halini görünce yandı yüreğim

Seni vuran avcı nereli, keklik

Kırılmış kanadı süzemez olmuş

Mavi gökyüzünde yüzemez olmuş

Çiçekli kırlarda gezemez olmuş

Vurulmuş dağların merali keklik

Ne sitem edersin ey bahtı kara

Seni vuran kimse yanmaz mı nara? 

Yüce mahkemede hakkını ara

Bozulmuş dünyanın kuralı, keklik

Ne de belalıymış sürmeli başın

Dilin susmuş, hani kıvrak sekişin

Kuraklarda seni arıyor eşin

Son bir sözün yokmu yaralı keklik', 'Koyun otlatırken bir keklik gördüm Çırpınıp duruyor kınalı keklik Halini görünce yandı yüreğim Seni vuran avcı nereli, keklik Kırılmış kanad...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kinali-keklik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk İçin', 'ask-i-cin-derya-aslan-y8eqj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabahın seherinde 

Soğuk kaldırımları İstanbul''un

Oysa olmak vardı şimdi seninle 

Dumanlı dağlarında Nemrud''un

....................................................

....................................................', 'Sabahın seherinde  Soğuk kaldırımları İstanbul''un Oysa olmak vardı şimdi seninle  Dumanlı dağlarında Nemrud''un ................................', ARRAY['Türk Edebiyatı','Şiir','Derya Aslan']::text[], 8.5, '{"poet":"Derya Aslan","poet_slug":"derya-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-icin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Doğmadan', 'gun-dogmadan-mehmet-postalli-yv510', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sadece dağlara değil 

Umutlara da  kar yağar

Mahzun durma be hey gönül

Gün doğmadan neler doğar.', 'Sadece dağlara değil  Umutlara da  kar yağar Mahzun durma be hey gönül Gün doğmadan neler doğar....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gun-dogmadan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Vedam', 'son-vedam-seyfettin-bilal-ozluk-worda', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İlk seninle tattım hayatı

Şimdi gidiyorum

Bu sana son vedam üzgünüm...

Bakma gözümün içine dayanamam bilirsin

Kaybetmişliği hiç sevmezdim

Ama şimdi ya kaybedeceğim

Ya da yeni başlangıç yapacağım...

Sende hayat buldum

Ve şimdi sen de son buluyorum...

Üzgünüm bu sana son vedam

Çünki kaybetmeyi sevmem...

Eğer dönersem birgün geri

Sanmam ama sen beni kabul et

Çünki yıkılmış ve kaybetmiş onun için dönmüşümdür...

Ama biliyorsun ki her kaybetmek bir kazançtır

Şansım çift ya sen ya o

Ama ben onu tercih ediyorum

Ve sana son defa söylüyorum

Ben gidiyorum bilinmezliklere....', 'İlk seninle tattım hayatı Şimdi gidiyorum Bu sana son vedam üzgünüm... Bakma gözümün içine dayanamam bilirsin Kaybetmişliği hiç sevmezdim Am...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/son-vedam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-salim-kabasakal-ten5e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu sabah İstanbul bana soğuk geldi

Gözlerim buğulu bir cam gibi

İşte  Eminönü, İşte Beyoğlu

Yar, sensiz ömür akıp gitti

Kaç sensiz sabahı kucakladım kaldırımlarda

Yağmur damlaları yüzüme vururken

Her geçen yalnız yüzde seni diledim Tanrıdan

Gözlerim ıslak ıslak

Sineme hapsettiğim hayalinle

Sürerim maviyi bölen bulutları

Bu şehir sensiz soğuk ve ıslak.

İstanbul aldı beni

Vermez sana gayrı geri

Yedi kollu canavar gibi sardı her yanımı', 'Bu sabah İstanbul bana soğuk geldi Gözlerim buğulu bir cam gibi İşte  Eminönü, İşte Beyoğlu Yar, sensiz ömür akıp gitti Kaç sensiz sabahı ku...', ARRAY['Türk Edebiyatı','Şiir','Salim Kabasakal']::text[], 8.5, '{"poet":"Salim Kabasakal","poet_slug":"salim-kabasakal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istanbul-350-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Afrika da Zaman', 'afrika-da-zaman-bekir-necati-f1oto', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne senin saatin, 

         ne de takvimin; 

Uymaz bizim zamanlara! 

Çok uzak kalır, 

       zamanın gösterdiği zamanlara! 

Ben Kara Afrika da

     İçi boş kara bakracında

             Bir avuç pirinç

                     Bir avuç su 

Rüyası peşindeyken

Sen

Atalarımdan aldıklarınla, 

Karnı tok zamanların içindeyken; 

Ne senin zamanların

Ne benim zamanlarım

Uymaz anlatmaya

Ne bugünü 

Ne yarını

Ne de gelecek zamanları! 

Ve ben hala siyah

Ve sen hala beyaz! 

Senin bilmem kaçıncı yüzyılında…', 'Ne senin saatin,           ne de takvimin;  Uymaz bizim zamanlara!  Çok uzak kalır,         zamanın gösterdiği zamanlara!  Ben Kara Afrika d...', ARRAY['Türk Edebiyatı','Şiir','Bekir Necati']::text[], 8.5, '{"poet":"Bekir Necati","poet_slug":"bekir-necati","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/afrika-da-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Böyle Sevdim', 'ben-boyle-sevdim-seyfettin-bilal-ozluk-vjw8n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elin elime değse kesin titrer bedenim

Bırak ellerini sesini duyduğumda kopuyor içim

Sen nesin böyle kimsin? 

Uzakta olduğun için mi hasretsin

Yoksa içimde olduğun için mi? 

O nur yüzüne baktığımda kendimi kaybeder miyim

Yoksa hayata mı dönerim bilmiyorum,

Bir heves değilsin sen içimde

Bir tutku hiç değil

İçimde bir uhdesin.

Bırakacak ve ellerimi hiç tutmayacaksan

İçimde kanayan bir yara olacaksan

Kal öyle duymayayım sesini

Tutmayayım elini

Çünki seni böyle sevdim bırakta böyle seveyim...', 'Elin elime değse kesin titrer bedenim Bırak ellerini sesini duyduğumda kopuyor içim Sen nesin böyle kimsin?  Uzakta olduğun için mi hasretsi...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-boyle-sevdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum Memleketim', 'erzurum-memleketim-erhan-demir-fo06s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat:18:30 yer, İstanbul-Harem

Yoluluk: Erzurum

Hava sisli, pus, duman

Trafik kenetlemiş, otobüs bekliyorum.,

Ve bindim otobüse, kapadım gözlerimi

Gidiyorum...

Saat:06:00 açtım gözlerimi, sabahın tam seher vakti,

Yer Erzurum, her taraf karla kaplı.

Arabadan iniyorum, elimden düştü ceketim,

On senedir gelmediğim Erzurum''un kokusunu farkettim.

Şöyle bir şehre baktım, renk renk ışıklar vardı,

Araba gidemedi, yolda kaldı.

Hemen hemen şehre beş kilometre yol vardı,

Derken dadaşlar diyarını ezan sesleri sardı.

Yola çıktım gidiyorum, ellerim hafiften üşüyor,

Yol nerede bilmiyorum, karlar başıma düşüyor,

Bir yol buldum gidiyorum, kar halen yağıyor,

Bir sigara yakacağım, kibritim donmuş yanmıyor.

Kar gittikçe yoğunlaştı dizlerime kadar,

Kulaklarım buz gibi, üstümde tek ceket var.

Biraz daha gidiverdim henüz şehre varmadan,

Gün ışımaya başlıyordu Palandöken dağından.

Her tarafım kar içinde, dinleniverdim o an,

Birkaç çocuk bakarak bana, dediler ''''Kardan adam''''.

Hava temiz mis gibi, solukladım nefesim,i

Seslendim çouklara duymadılar sesimi.

Saat oldu sekiz, dokuz... kar kesildi sonradan.

Şehre ayak basarak sigaramı içtim bir yandan.

Bir kahveye girdim, dadaşlar sohbet içindeydiler,

Selam verdim oturdum, bir çay ikram ettiler.

Konuştuk sağdan soldan, ''''Nereden yoluluk'''' dediler,

Dedim ki ''uzak yoldan'' bana gülümsediler...

Elim ayağım titriyordu girerken o kahveye, 

Bir kıtlama çay ısıttı içimi,

Teşekkür ederek dadaşlara çıktım mahleye.

İnsanlar cıvıl cıvıl, sokaklar pırıl pırıl.

Uzaktan bir çeşme suyu akıyordu şarıl şarıl.

Cağ kebap kokusunu aldım bir lokantadan,

Varıp girdim içeri, dedi ''''Hoş gelmişsen gurban''''.

Dedim,  ''hoş bulduk dadaş, bir çorba ver hele sen''...

İçtim çorbayı bakır tastan, sonra yedim afiyetle,

O nefis cağ kebaptan.

Karnım doydu güzele ayrılırken dadaştan,

Oltu taşları parlıyordu bir dükkanın camından.

Biraz daha geziverdim ayak üstü çarşıdan,

İki güzel dadaş kızı, gülümseyerek geçtiler karşımdan.

O siyah ceketimi İstanbul da giymiştim, 

Ceket karbeyaz olmuştu, Erzuurm''a girmiştim. 

İşte o karlı günde buz tutmuştu ceketim,

Çifte minareye vararak sona erdi hasretim.

Karıyla, soğuyuyla,  buzuyla bir başka güzeldi seyahatim.

Dadaştan dadaşa selamlarla,

Erzurum, memleketim...

ŞİİR VE YORUM: ERHAN DEMİR

:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

NOT: Ses dosyasını indirip dinlemek için, alttaki  ''Download'' link ''ini tıklayınız

Yaklaşık indirme süresi 1 - 5  Dakikadır 

Not: Sesli mp3 şiirlerimi kaliteli kulaklıklarla dinlemenizi tavsiye diyorum...

Paylaşımlarınız için teşekkürler.', 'Saat:18:30 yer, İstanbul-Harem Yoluluk: Erzurum Hava sisli, pus, duman Trafik kenetlemiş, otobüs bekliyorum., Ve bindim otobüse, kapadım göz...', ARRAY['Türk Edebiyatı','Şiir','Erhan Demir']::text[], 8.5, '{"poet":"Erhan Demir","poet_slug":"erhan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/erzurum-memleketim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-sair-turani-xyuxz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dile gelsin tarih, o gün nasıldık

Aydık, Yıldızdık biz, Çanakkale''de.

Tıpkı kükreyen bir aslan kesildik

Destanlar yazdık biz, Çanakkale''de.

O gün bir bütündük, gövdeydik, baştık

Dört cepheden, yedi koldan savaştık

Tek millet, tek yürek, bacı, gardaştık

Kızandık, kızdık biz, Çanakkale''de.

O gün ne Türk, ne Kürt, ne de Çerkezdik

O gün tek millettik,  o gün herkestik

Bu ruh, bu imanla düşmanı ezdik

Düşmanı ezdik biz, Çanakkale''de.

O gün düşmandan ne korktuk ne sindik

Korkaklardan tarih boyu tiksindik

Biz gazi derviştik, biz alperendik

Türk.Yenilmezdik biz, Çanakkale''de.

Şan şeref şahadet yüklü maziler,

Selâm size ey şehitler, gaziler

Süngülerimizle tunçtan mevziler

Siperler kazdık biz, Çanakkale''de

Zafer burçlarına baktığımız gün

Burçlara hilali diktiğimiz gün

Düşmanı denize döktüğümüz gün

Düşmandan azdık biz, Çanakkale''de.

Çanakkale''m sana paha biçilmez

Vatansın,  vatana paha biçilmez

Turani''yim ''Çanakkale Geçilmez''

Dedirten bizdik biz, Çanakkale''de.

Baba Ocağı (2005)  Sy:  102', 'Dile gelsin tarih, o gün nasıldık Aydık, Yıldızdık biz, Çanakkale''de. Tıpkı kükreyen bir aslan kesildik Destanlar yazdık biz, Çanakkale''de. ...', ARRAY['Türk Edebiyatı','Şiir','Şair Turani']::text[], 8.5, '{"poet":"Şair Turani","poet_slug":"sair-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/o-gun-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O gün', 'o-gun-ruken-bingul-zys5h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu şiirimiz biraz saçma olmuş farkındayım ama acemilik işte ne yapalım. Bu şiirde herkese fazla inanmamak ve yalanla gerçeği ayır etmek geerekir', 'Bu şiirimiz biraz saçma olmuş farkındayım ama acemilik işte ne yapalım. Bu şiirde herkese fazla inanmamak ve yalanla gerçeği ayır etmek geer...', ARRAY['Türk Edebiyatı','Şiir','Ruken Bingül']::text[], 8.5, '{"poet":"Ruken Bingül","poet_slug":"ruken-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/o-gun-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız', 'vefasiz-gul-gultekin-n91gg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üzerinden günler,haftalar aylar geçti

Ayrıldıktan sonra ilk defa bugün ağladım.

Özlemimden mi? Hasretimden mi? 

Nedeni bilinmez...........

Anılara daldı gitti gözlerim

Her dakikanı kana kana özledim.

Bilinmezlerde kaldı hasretin

Kalbim çürümüş, küflenmiş gizlilikte sevgin.

Ne kadar zormuş kara sevda dedikleri,

Azrail’i yaşarken de tanımak varmış,ölüm nedir ki! 

Hırsızlık sadece maddiyat mı çalmak,söyleyin dostlar

Kalp çalan sevgilide hırsız sayılmaz mı? 

Vefasızın düşme kucağına,yanarsın derlerdi

Dünyadaki en kötü hastalıklar nedir ki? 

Sevgili dediğin yar hançer saplamış yüreğine

Dermanı olan hastalığa düşmek nedir ki? 

Kelebekler uçmaz oldu bahçem de,

Güllerim açmaz oldu gönül mahzenimde

Kuşlar ötmez oldu güzelim maviliklerimde

Kefeni  ölürken giymek nedir ki?', 'Üzerinden günler,haftalar aylar geçti Ayrıldıktan sonra ilk defa bugün ağladım. Özlemimden mi? Hasretimden mi?  Nedeni bilinmez........... A...', ARRAY['Türk Edebiyatı','Şiir','Gül Gültekin']::text[], 8.5, '{"poet":"Gül Gültekin","poet_slug":"gul-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vefasiz-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzin Var', 'i-zin-var-serkan-karabulut-njv6y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kenarları kıvrılmış

Mektupların var

Okumaktan ezberlediğim 

senden  bana özel sözler…

benim güzel bebeğim

alı al,

sarısı sarı.

seni sevdim seveli

şu yürekte izin var…', 'Kenarları kıvrılmış Mektupların var Okumaktan ezberlediğim  senden  bana özel sözler… benim güzel bebeğim alı al, sarısı sarı. seni sevdim s...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/izin-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşklarada Değişti', 'asklarada-degisti-serkan-karabulut-3aca7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söylemeyi isterdim

Senin duymadığın sözleri

O kadar abartılı ki aşklar

Sözler unutuldu

Sanki bilindik havadalar

Kullanılmış

Değişmiş

İki anlamda sanki kinayeli

Söylemek istediklerimi sustum

Sırf bu yüzden

Aşklarda değişti

Öyle bildik değil

Koruyamadık hazineleri

Bir bir yitirtip

Eyledik mazi', 'Söylemeyi isterdim Senin duymadığın sözleri O kadar abartılı ki aşklar Sözler unutuldu Sanki bilindik havadalar Kullanılmış Değişmiş İki anl...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/asklarada-degisti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On gün bitti', 'on-gun-bitti-ruken-bingul-hbv2h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'On gün neden bitti yade 

neden kaybolfuk yade 

neden geldik bu saçma dünyaya yade

On gün geldi geçti

Ne çabuk geldi çeçti

On günde neler değişti

On günde savaş olup bitti

On gün bize çok küçük bir zaman gelebilir

Ama aslında on günde 

Ya ölürsün yada ölmez ve kalarsın

On bize çok büyük bir zaman 

On gün içinde herşeyi yaparız

Özgürce ama özgürlüğü yapmak için kimseye zarar vermeyecez

İşte on gün kısa zaman değil

   On gün şiirini beyendiyseniz

    Puan verin', 'On gün neden bitti yade  neden kaybolfuk yade  neden geldik bu saçma dünyaya yade On gün geldi geçti Ne çabuk geldi çeçti On günde neler değ...', ARRAY['Türk Edebiyatı','Şiir','Ruken Bingül']::text[], 8.5, '{"poet":"Ruken Bingül","poet_slug":"ruken-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/on-gun-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşem  1', 'aysem-1-mahmut-simsek-qf4f1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nazlı çiçeğim selvi boylum al yanaklım

Siyah saçlı ela gözlüm biricik gülüm

Aramızda kötülük olmasın sevdalım

Biricik sevgilim köylü  güzeli ayşem.

Senle el ele tutuşup kırlara gitsek

Doyasıya gezsek dolaşsak ve eylensek

Sarılsak biz birbirimize  yuvarlansak

Biricik sevgilim köylü güzeli ayşem.

Al yazmalı İnan her gün seni özlerim

Yeterki sevde seni bir ömür severim

Bir gün seninle öpüşelim sevişelim

Biricik sevgilim köylü güzeli ayşem.

                                                           

                                                             YAZAN VE DERLEYEN 

                                                                   MAHMUT ŞİMŞEK 

                                                                         ADIYAMAN', 'Nazlı çiçeğim selvi boylum al yanaklım Siyah saçlı ela gözlüm biricik gülüm Aramızda kötülük olmasın sevdalım Biricik sevgilim köylü  güzeli...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aysem-1-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beraber', 'beraber-mehmet-erol-zhtk2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gitmek Çok UZaklara 

Yürümek Sevgiye ölesiye Yürümek.

Çalmak Kapını Almak Seni 

Hep Beraber Sen Ben Hepimiz.

Belki sonsuzluğa Bilinmeyene 

Sevda Türküleriyle özgürlüğe.

Hiç Durmadan Koşarak,

Hep Beraber Sen Ben Hepimiz.

Güneşin Ardına daha uzağa,

Bıkmadan Usanmadan Yılmadan.

Korkusuzca Onurumuzla Şerefimizi,

Sevdamızı da Alarak Özgürlüğe Doğru Akmak...

    Sadace Sen Ve Ben......', 'Gitmek Çok UZaklara  Yürümek Sevgiye ölesiye Yürümek. Çalmak Kapını Almak Seni  Hep Beraber Sen Ben Hepimiz. Belki sonsuzluğa Bilinmeyene  S...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Erol']::text[], 8.5, '{"poet":"Mehmet Erol","poet_slug":"mehmet-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beraber-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-mahmut-simsek-anu0g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oyulsun gören bu gözler bakmasın bir daha             

Lal olsun konuşan bu dilim hiç konuşmasın

Esir olsun  bedenim kurtulmasın bir daha

Senden başka birini görüp seversem eyer.

Kırılsın kolum kırılsın kanadım felç olsun

Parçalansın beynim yerlere dökülsün kanım

Karnım deşilsin leş kargalarına yem olsun

Senden başka birini görüp seversem eyer.

Ciğerlerim sökülsün kalmasın hiç takatim

Sokaklarda çürüsün bedenim bu cesedim

Kimse gelmesin mezarıma dua etmesin 

Senden başka birini görüp seversem eyer.

                                                          

                                                               YAZAN VE DERLEYEN 

                                                                   MAHMUT ŞİMŞEK

                                                                           ADIYAMAN', 'Oyulsun gören bu gözler bakmasın bir daha              Lal olsun konuşan bu dilim hiç konuşmasın Esir olsun  bedenim kurtulmasın bir daha Se...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beddua-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeçenyam', 'cecenyam-mahmut-simsek-5wtu0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Genç abazasıyla   Çeçenlisiyle

İslam’a inancıyla imanıyla

Acısıyla yılmaz   mücahidiyle

Benim korkusuz kahraman Çeçenyam.

Oralarda olmazsam bile bilin

Bilin ki gönlüm sizinle her zaman

Yanarım  alev alev içim volkan

Benim korkusuz kahraman Çeçenyam.

Üstünüze düşen hain bombalar 

Hep benim yüreğimde patlıyorlar

Gelemiyorum bilin  sebebi var

Benim korkusuz kahraman Çeçenyam.

Oralarda olmak için can atan

Her,gün uykusuz gecelerde yatan

Ruhunu sizlere katanlardanım

Benim korkusuz kahraman Çeçenyam

                                                                   

                                                                    YAZAN VE DERLEYEN 

                                                                           MAHMUT ŞİMŞEK

                                                                                  ADIYAMAN', 'Genç abazasıyla   Çeçenlisiyle İslam’a inancıyla imanıyla Acısıyla yılmaz   mücahidiyle Benim korkusuz kahraman Çeçenyam. Oralarda olmazsam ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cecenyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelim', 'guzelim-mahmut-simsek-l8zl7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkın şerbetini içtim güzelim

Kaybettim kendimi bilemiyorum

Hayata küstüm sarhoşum güzelim

Sen yoksun ayık duramam güzelim

Dünyayı verseler de sensiz bana

Domdomla kıyarım ben bu canıma

Güzel yalnız kalbimi verdim sana

Sen yoksun ayık duramam güzelim.

Aşkının sarhoşu esiri  oldum

Parçalanmış Yüreğin berduşuyum

Kadersiz kadere boyun eymişim 

Sen yoksun ayık duramam güzelim.

                                                                 YAZAN VE DERLEYEN 

                                                                        MAHMUT ŞİMŞEK

                                                                                ADIYAMAN', 'Aşkın şerbetini içtim güzelim Kaybettim kendimi bilemiyorum Hayata küstüm sarhoşum güzelim Sen yoksun ayık duramam güzelim Dünyayı verseler ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/guzelim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet', 'lanet-mahmut-simsek-gwrhs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kör olsun o ela gözlerin

Lal olsun konuşan o dilin

Kahrolsun o,senin sevdiğin

Benden başkasını seversen 

Sağır olsun o kulakların

Hiç açılmasın dudakların

Dertlerle boğuşup kalasın

Benden başkasını seversen

O saçların tel tel dökülsün 

Tırnakların dipten sökülsün

Belki andını hatırlarsın

Benden başkasını seversen

                                           

                                                YAZAN VE DERLEYEN

                                                     MAHMUT ŞİMŞEK

                                                             ADIYAMAN', 'Kör olsun o ela gözlerin Lal olsun konuşan o dilin Kahrolsun o,senin sevdiğin Benden başkasını seversen  Sağır olsun o kulakların Hiç açılma...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/lanet-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özet', 'ozet-cengiz-kurt-2-xtk4k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben: Bu dünyanın delisi

Sen: Tüm zamanlar perisi

Gerçek: Seni çok sevdiğim

Hikâye: Bunun gerisi', 'Ben: Bu dünyanın delisi Sen: Tüm zamanlar perisi Gerçek: Seni çok sevdiğim Hikâye: Bunun gerisi...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kurt 2']::text[], 8.5, '{"poet":"Cengiz Kurt 2","poet_slug":"cengiz-kurt-2","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozet-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-mahmut-simsek-7y4ld', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstersen bir ömür senin kölen olurum

İstersen bir ömür yanarım kavrulurum

İstersen her gün sana,sana kahrolurum

İstersen eyer sana biran kavuşurum.

Tutamıyorum kendimi ne olur kızma

Seviyorum seni başkasına aldırma

Aşkımdan sevgimden hep eriyorum sana

İstersen  sevgilim kavuşurum ben sana

                                                               

                                                                  YAZAN VE DERLEYEN 

                                                                       MAHMUT ŞİMŞEK

                                                                             ADIYAMAN', 'İstersen bir ömür senin kölen olurum İstersen bir ömür yanarım kavrulurum İstersen her gün sana,sana kahrolurum İstersen eyer sana biran kav...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ozlem-272-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-fatih-kuyucu-cfll6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi solmaya mahkum bir çiçeğin 

Açmasını bekler gibi 

Seni bekliyorum yağmurlarda 

Hazan mevsiminde bozulan bir bağın 

Son hasatı gibi 

Çaresizlikte çareyi bekliyorum

Umudu çoktan bitmiş bir aşkın 

Kendini avutması gibi 

Bir sigaranın dumanını 

Efkarlıca içine çeken biri gibi 

Bende acılar çekiyorum içime

Seni bekliyorum sessizce 

Sonu olmayan yolların 

Vuslat noktası olurum hüzünlere 

Beklentilerin boşa çıktığı gecelerde

Bir kapının gıcırtısını duymak ister gibi 

Sesini duymayı bekliyorum sessizlikte 

Fırtınaların alabora ettiği gemiler gibi 

Yüreğimde boğuyorum duyguları 

Beyaz bir gülün saflığını yitirmesi gibi

Bir çizgi çekerim ellerimi kıra kıra

Umutları yaka yaka bir çigi çekerim sevgiye 

Yüreğimde bestelenmeyi bekleyen ezgiler gibi 

Senin için yazılmayı bekleyen şiirler gibi 

Ay’ ın güneşi beklemesi gibi 

Bende seni bekliyorum 

Gelmeyeceğini bile bile', 'Şimdi solmaya mahkum bir çiçeğin  Açmasını bekler gibi  Seni bekliyorum yağmurlarda  Hazan mevsiminde bozulan bir bağın  Son hasatı gibi  Ça...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kuyucu']::text[], 8.5, '{"poet":"Fatih Kuyucu","poet_slug":"fatih-kuyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bekliyorum-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnat', 'i-nat-mehmet-ayhan-gunaydin-z89n6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İNAT

Kaderimle ben

İki düşman gibiyiz.

Bıkmadan,

Yorulmadan,

Usanmadan,

Didişiriz.

Nerden çıktı bu terslik

Onu ben hiç bilmedim.

İlk günden bu güne dek

Hep gözgöze, hep dişdişeyiz.

O durmadan ters vurur

Ben bir kapaklanırım.

Ama

İnadına, sonunda

Hep ayağa kalkarım.

Kaç yıl oldu unuttum

İlk sillesini yediğim.

Yoo! ..

İnadım inat

Yenilmeyeceğim.

M. Ayhan Günaydın.

     22 Aralık 1993

Dereören / Havran / Balıkesir', 'İNAT Kaderimle ben İki düşman gibiyiz. Bıkmadan, Yorulmadan, Usanmadan, Didişiriz. Nerden çıktı bu terslik Onu ben hiç bilmedim. İlk günden ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/inat-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkumdur İnsan Anılara', 'mahkumdur-i-nsan-anilara-fatih-kuyucu-9myzk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle günler gelir ki; 

Ne dostları vardır insanın 

Umutsuzlukta ellerini tutacak 

Nede sevdikleri yanında olacak

İstemeden kendine benzetir 

Benzemek istemediğin duygular 

İstemesen de bağlanırsın bir gün bitiminde 

Vefasız bir gül dikenine 

Halbuki güle bağlanmak vardır 

Oysaki oda solacaktır

Oysaki gülistan 

Hep gözyaşıyla dolacaktır

Vazgeçmek 

Bir çoban yıldızıdır uzanamadığım 

Çünkü anlamsızdır 

Ellerim, kollarım bağlıyken sözlerinde 

Anla ki göz yaşlarım karışırken tenhalara 

Alışmam gerek yalnızlığa 

Yalnızlık:  yalnız bir zambak 

Gözlerinde açan 

Issız bir çölde seraplar gören 

Mecnunu deliye çeviren yalnızlık 

Sonra bir kuytu içinde 

Aşamadığın engellere sitem etmek 

Ardından çocuklar gibi gülmek 

Öyle günler gelir ki 

Nasıl yaşamak için havaya 

Suya ihtiyacı olursa insanın 

Öyle ihtiyacı olur sevgiye yalnızların

Hayat yalnız geçerken 

Yalnız bir zambağın 

Soluşu kadar kısadır ömür

Anılar vefasızdır insana

İnsansa mahkumdur anılara', 'Öyle günler gelir ki;  Ne dostları vardır insanın  Umutsuzlukta ellerini tutacak  Nede sevdikleri yanında olacak İstemeden kendine benzetir ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kuyucu']::text[], 8.5, '{"poet":"Fatih Kuyucu","poet_slug":"fatih-kuyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/mahkumdur-insan-anilara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sılaya Özlem(1)', 'silaya-ozlem-1-mahmut-simsek-c1c7e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayaliniz hep gözümde tütüyor.

Özledim sizleri hasret bitmiyor.

Geceleri gözüm uyku tutmuyor.

Sizler olmayınca yüzüm gülmüyor.

Yaradanım böyle yazmış yazımı.

Parça,parça yakıyor yüreğimi.

Ne gündüzüm nede gecem var benim.

Sizler olmayınca yüzüm gülmüyor.

Resminize bakarak avunurum.

Sineme korum kalbime yaslarım.

Ağlayıp da yüreğimi dağlarım.

Benden selam olsun yavrularıma.

Bu hayatın ne tadı var ne tuzu.

Başımızdan geçenler alın yazı.

Hiç unutmadım ki verdiğim sözü.

Gör yarap avuç açan bu öksüzü.

                                                                  YAZAN  VE DERLEYEN.

                                                                         MAHMUT ŞİMŞEK.

                                                                                 ADIYAMAN.', 'Hayaliniz hep gözümde tütüyor. Özledim sizleri hasret bitmiyor. Geceleri gözüm uyku tutmuyor. Sizler olmayınca yüzüm gülmüyor. Yaradanım böy...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/silaya-ozlem-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Yarim', 'vefasiz-yarim-mahmut-simsek-dre6m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yok artık gidecek yerim

Yokluk yaktı ben bilirim

Yorgun düştü bu bedenim

Ah donuk kaldı gözlerim

Gurbet elinde garibim

Kimsesiz bir tek fakirim 

Sokaklar mekanım benim        

Ah donuk kaldı gözlerim

Canım senindi tükendim

Aşkım senindi kül ettin 

Birden çekip gittin bilirim

Ah  donuk kaldı gözlerim

                                            YAZAN VE DERLEYEN

                                                   MAHMUT ŞİMŞEK

                                                          ADIYAMAN', 'Yok artık gidecek yerim Yokluk yaktı ben bilirim Yorgun düştü bu bedenim Ah donuk kaldı gözlerim Gurbet elinde garibim Kimsesiz bir tek faki...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/vefasiz-yarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazeninim Seni Çok Özledim', 'nazeninim-seni-cok-ozledim-haluk-cenk-batur-x1esd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu kadar büyük olmalıydı sevmenin bedeli,

Çay sonrası sigara arzusu

Yada tavlanın kahveye sevdası

Akşam alacasında eve dönme kaygısı.

Bu kadar büyük olmalıydı hasretin

Bu kadar büyük sevgilim.

Karnım acıkmıyor değil şu aralar

Bir sigara dumanına bile hasretle bakıyorum.

Ve hiç bir istasyon beklememiştir herhangi bir treni,

Benim seni beklediğim gibi.

N yalan söyleyeyim,

Elim yazmaya varmıyor sevdamı

Bağıra bağıra türkülerimi söyleyeyim istiyorum

İçimde bir çocuğun oyuncak sevdası

Seni kaybettim

Bulamıyorum.

Odanın camından gözüken pencerelere iyi bak

Perdelerin arkasında gizlenenler ben olabilirim.

Tıpkı o sevdiğin şarkı gibi

Hatta bir gece ansızın gelebilirim.

Ben şimdi bir hayalin yılmaz sevgilisiyim

Her çaldığım kapıda senin zerrelerini buluyorum

Hep aynı lafı tekrarlayan bir deliyim.

Nazeninim seni çok özledim.

2005', 'Bu kadar büyük olmalıydı sevmenin bedeli, Çay sonrası sigara arzusu Yada tavlanın kahveye sevdası Akşam alacasında eve dönme kaygısı. Bu kad...', ARRAY['Türk Edebiyatı','Şiir','Haluk Cenk Batur']::text[], 8.5, '{"poet":"Haluk Cenk Batur","poet_slug":"haluk-cenk-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nazeninim-seni-cok-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım Sana', 'asigim-sana-mahmut-simsek-vbvub', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdam sen kırgınım dedin bana

Ne yaptım ki güzelim ben sana

Kırıyorsun benim şu kalbimi

İnan sevgilim aşığım sana.

Dargınlık olmaz sevdalılara

Değişmem ben seni dünyalara

Bir kuş olup uçsan da uzaklara

Duramam gelirim oralara

ikimizde bir ömür severiz

Değişmesin bizim kaderimiz 

Yeter ki sen iste evleniriz

İnan sevgilim aşığım sana.

                                             

                                               YAZAN VE DERLEYEN 

                                                     MAHMUT ŞİMŞEK 

                                                           ADIYAMAN', 'Sevdam sen kırgınım dedin bana Ne yaptım ki güzelim ben sana Kırıyorsun benim şu kalbimi İnan sevgilim aşığım sana. Dargınlık olmaz sevdalıl...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/asigim-sana-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür zaman yansıması', 'ozgur-zaman-yansimasi-salim-kabasakal-hanxf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bal rengi saçlarını okşayan

Rüzgarın güçlü parmağı

Güneşin altın saçan ışığıyım

Kuşların yuvalarına uçtuğu o an

Özgür zamanın yansımasıyım

Bu akşam bir perde daha kapatıyorum

Günden güne azalıyor seyircim

Ey beni çağıran sessizlik

Nasıl anlatsam ki

Dilimin ucuna dolanan bir ömür hikayesini

Doğumdan -Ölüme doğru', 'Bal rengi saçlarını okşayan Rüzgarın güçlü parmağı Güneşin altın saçan ışığıyım Kuşların yuvalarına uçtuğu o an Özgür zamanın yansımasıyım B...', ARRAY['Türk Edebiyatı','Şiir','Salim Kabasakal']::text[], 8.5, '{"poet":"Salim Kabasakal","poet_slug":"salim-kabasakal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ozgur-zaman-yansimasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşem (2)', 'aysem-2-mahmut-simsek-kkyrb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Alıp verdiğim her nefeste sen varsın ayşem

Gözümün gördüğü her yerde sen varsın ayşem

Üzüntümde sevincimde hep sen varsın ayşem

Benim sevgim kalbimde bir tek sen varsın ayşem.

Sana olan duygularım satırlara sığmaz

Sana olan sevgim dünyalara sığmaz ayşem         

Dünya sevenlere karşılıksız kalmaz ayşem

Sana nasıl anlatsam bilemiyorum ayşem.

Gördüğüm zamanlar yiyesim geliyor ayşem

Bu nasıl sevgi bu nasıl bir duygu ki ayşem

Seven anlar seven bilir sevgiyi ayşem

Sana nasıl anlatsam bilemiyorum ayşem.

Konuştuğum her kelimede sen varsın ayşem

Düşündüğüm her konuda bir sen varsın ayşem

Üzüntümde sevincimde hep sen varsın ayşem

Sana nasıl anlatsam bilemiyorum ayşem.

Gelip geçici bir heves değil bu aşk ayşem

Ölümüne seviyorum seni güzel ayşem

Öl desen şuracıkta düşer ölürüm ayşem

Sana  nasıl anlatsam bilemiyorum ayşem.

Seni koklamak seni öpmek istiyor canım

Seninle,duygularımla olmak istiyorum 

Duygularımı seninle paylaşmak istiyorum

Sana  nasıl anlatsam bilemiyorum ayşem.

                                                                                        YAZAN VE DERLEYEN 

                                                                                               MAHMUT ŞİMŞEK

                                                                                                       ADIYAMAN', 'Alıp verdiğim her nefeste sen varsın ayşem Gözümün gördüğü her yerde sen varsın ayşem Üzüntümde sevincimde hep sen varsın ayşem Benim sevgim...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aysem-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bosnamda Kalacağım', 'bosnamda-kalacagim-mahmut-simsek-y00x0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözüm görene kadar 

Sırplar gidene kadar

Burda ölene kadar

Bosnamda kalacağım

Elim tutana kadar

Gücüm yetene kadar

Sevgi olana kadar 

Bosnamda kalacağım

Silah tutana kadar

Tetik çekene kadar 

Güneş doğana kadar

Bosnamda kalacağım

Sırplar kaçana kadar

Savaş bitene kadar 

Barış olana kadar

Bosnamda kalacağım

Şafak sökene kadar

Yalnız kalana kadar 

Bu can durana kadar

Bosnamda kalacağım.

                                   

                                      YAZAN VE DERLEYEN 

                                           MAHMUT ŞİMŞEK

                                                   ADIYAMAN', 'Gözüm görene kadar  Sırplar gidene kadar Burda ölene kadar Bosnamda kalacağım Elim tutana kadar Gücüm yetene kadar Sevgi olana kadar  Bosnam...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bosnamda-kalacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekeceğim Var', 'cekecegim-var-mahmut-simsek-q5tw9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akranlarımdan uzakta kalmak benim için tek çarem

Bugüne kadar kimseden ben bile hiç görmedim harem

Bu laflarla eyer bir gün hastalanıp olmazsam verem

Çekeceğim var bu dünyada dolmamıştır benim çilem.

Benimde hakkım değil mi bende bir gün birini sevem

Sevmek suç ise (Allah) ım bırak bari ömrümü verem

Yalan dolanla yaşamaktansa bırak bari ben ölem

Çekeceğim var bu dünyada dolmamıştır benim çilem.

Eğer bir art niyetim vardıysa benim lal olsun dilim

Eğer onun bildiği kadarını bende bilmiyorsam 

Felç olsun bedenim kör olsun bu gören gözlerim gülüm

Çekeceğim var bu dünyada dolmamıştır çilem benim

                                                                                      

                                                                                       YAZAN VE DERLEYEN 

                                                                                               MAHMUT ŞİMŞEK 

                                                                                                       ADIYAMAN', 'Akranlarımdan uzakta kalmak benim için tek çarem Bugüne kadar kimseden ben bile hiç görmedim harem Bu laflarla eyer bir gün hastalanıp olmaz...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cekecegim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır çiçeğim', 'kir-cicegim-mahmut-simsek-szukb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nazlısın kolların öyle narin

Sana olan sevgim öyle derin

Seninle geçiyor hayallerim

Benim tatlı güzel kır çiçeğim.

Güzel olduğun kadar hırçınsın

Deli dolusun sevgim aşkımsın

Gözümde gönlümde bir sen varsın

Benim tatlı güzel kır çiçeğim.

Bahar gelir çiçekler açarsın

Sen yavru ceylan gibi kaçarsın 

Sen hep benim kalbimde yaşarsın

Benim tatlı güzel kır çiçeğim.

                                                                   YAZAN VE DERLEYEN 

                                                                         MAHMUT ŞİMŞEK

                                                                             ADIYAMAN', 'Nazlısın kolların öyle narin Sana olan sevgim öyle derin Seninle geçiyor hayallerim Benim tatlı güzel kır çiçeğim. Güzel olduğun kadar hırçı...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kir-cicegim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Ol Kardeşim', 'mutlu-ol-kardesim-mahmut-simsek-cwhue', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir satıcı vesilesi ile tanıştık

Bacı olduk kardeş olduk

Kapımı evimi sonuna kadar 

Hatanı düzeltmen için sana açtım.

Seninle baş başa oturup konuşamadık

Yengenin aracılığı ile konuşup anlaştık

Hatanı anladın yuvana döndün

Yuvanda mutlu ol kardeşim.

Hayli zaman oldu kavuşamadık 

Savunmasızdık zalimlerle savaştık 

Birden uçup gittin yuvana

Yuvanda mutlu ol kardeşim.

Yıllar geçti hala unutamadım

Deli gibi divane gibi oldum                                            

Hatırını sorup derman olamadım

Yuvanda mutlu ol kardeşim.

Hatırını sormak için aradım

Ateş püsküren bir kadın çıktı

Söyledikleri karşısında dondum kaldım

Ümütlerimi yıktı hayallerimi yıktı 

Günlerce acılara yaslara boğuldum

Şimdi susuz kalmış tarla gibiyim

Olamaz böyle bir şey delilik dedim

Ümitlerimi yıktı hayallerimi yaktı.

Durmadan tekrar tekrar aradım

Hep aynı kadın aynı cevabı aldım

Yanımda olsaydı belki boğardım

Çıldıracaktım kafamda bin bir soru

Bizdeki cansız hayaline bakıyorduk

Resmin arkasını çevirdim sevindim

Haber alabileceğim ümit ışığı buldum

Öyle sevindim ki sevincimi anlatamam

Daha önce yanında çalıştığın 

Ekmeğini aşını yediğin avukattı

Aradım telefon numaraları değişmiş

Ümidimi yitirmedim sürekli aradım

Nihayet sonunda avukata ulaşabildim

Maşallah Sesimden beni hemen tanıdı

Seni aradığımı söyledim senden bahsettim

Duydum ki evlenip yuva kurmuşsun

Aldığım cevapta yeniden doğdum

Sevinçten ele avuca sığmaz oldum

Rabbime şükürler olsun yaşıyorsun

Yuvanda mutlu ol kardeşim.

Dilerim (Allah) tan mutlu olursun

Sevincimden göz yaşlarımı tutamaz oldum

Annesini bulan kaybolmuş ceylan oldum

Yuvanda mutlu ol kardeşim

Acıların benim kederin benim

Sevgiler mutluluklar senin olsun

Kahır etme seni sevenlerine

Yuvanda mutlu ol kardeşim.

Bir kardeş bir evlat gibiydik

Sen büyük hayaller kurmuştun

Hayli uzun bir zaman oldu

Ne haberleştik ne görüşebildik

Çocuklar seni sorup duruyor

Halamız bizi neden aramıyor

Dargınlık mı var çaresizlik mi

Yoksa diyemediğin derdin mi var

Ne olur üzme canını be ablam

Senindir o tertemiz duygular

Mutluluğun yüzünden okunsun

Yuvanda mutlu ol kardeşim.

Hem annem hem ablam oldun

Canım ciğerim biricik kardeşim

Eyer varsa bir derdin kederin

Ne olur kardeşim olsun haberim

Yıllardır hep senden haber bekledim

Söylerim olmasın derdin acı kederin

Sana sevgiyle saadetler dilerim

Sevincin yüzünde mutluluk sözünde okunsun

Sıhhatli sevgi dolu uzun yıllar senin olsun

                                                                             YAZAN VE BESTELEYEN

                                                                                  MAHMUT  ŞİMŞEK

                                                                                        ADIYAMAN.', 'Bir satıcı vesilesi ile tanıştık Bacı olduk kardeş olduk Kapımı evimi sonuna kadar  Hatanı düzeltmen için sana açtım. Seninle baş başa oturu...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/mutlu-ol-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birikme', 'birikme-adem-tok-xle7p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'buğulu kirpikleri

bulutların

kokusu günebakanların

havada asılı

tenini özlüyorum

ahh melisa

kollarına düşeceğim vakte

nem topluyorum...

                                                  (14.10.05) 

                                                   çamözü', 'buğulu kirpikleri bulutların kokusu günebakanların havada asılı tenini özlüyorum ahh melisa kollarına düşeceğim vakte nem topluyorum...     ...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/birikme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhsuzlar', 'ruhsuzlar-mahmut-simsek-k9cuc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kardeş dedim güvendim  menfaatçi çıktı geç onu 

Akraba dedim inandım  akrep oldu onu da geç

Dostum dedim sevindim sırtımı verdim güvendim boş

Bunları ben elden beklerdim ama çevremden geldi.

Kardeş dediğim şimdi paracı ve çıkarcı oldu

Akraba dediğim sahtekar dolandırıcı çıktı

Dost dedim ekmeğimi paylaştığım  arkamdan vurdu

Sonunda bana yapacaklarını yaptılar işte

Artık benim için güvenilecek kimse kalmadı

Ne kardeşime ne akrabaya nede dostlarıma

Artık inancımı yitirdim böyle çıkarcılara

İnsan kılıklılar sonunda bir canavar yarattı.

Yaşadığımız şu üç günlük dünyada değer miydi

Mala mülke paraya şeytana taptığınız neydi

İnançsız  bu fani dünyada ne anladınız ki

Sonunda bana yapacağınızı yaptınız işte.

Tertemiz saf iyi yürekli yardımsever biriydim 

Acıma duygularımla hislerimle oynadınız

Ben ki herkese ama herkese yardım ederdim

Şimdi ise baktığınız pencereden bakıyorum.

Sonunda beni,de alt ettiniz yendiniz tebrikler

Güzel toplumda beni,de kendinize benzettiniz

Şimdi ise benden ne yüzle siz  yardım beklersiniz

Şimdi ise baktığınız pencereden bakıyorum.

                                                                                 YAZAN VE DERLEYEN 

                                                                                        MAHMUT ŞİMŞEK

                                                                                                ADIYAMAN', 'Kardeş dedim güvendim  menfaatçi çıktı geç onu  Akraba dedim inandım  akrep oldu onu da geç Dostum dedim sevindim sırtımı verdim güvendim bo...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ruhsuzlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatil Özlemi', 'tatil-ozlemi-mahmut-simsek-sknvr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duydum ki okullar tatil olmuş

Memleket hasreti sizleri yakıyormuş

Uçup gidin desem uçacaksınız

Ben ise size hasret size yanıyorum

Duydum ki taktir onur almışsınız

Öyle duygulandım ki sizlere anlatamam

Öyle sevindim ki dünyalara sığmaz

Ben ise size hasret size yanıyorum

Desem yine olmaz az gelir size

Sizleri kucaklayıp böğrüme basmak 

Kokularınızı almak ve koklamak

İsterim burham,burham,burham

Sevincinizi sizinle paylaşamasam da

İsteğiniz dileğiniz olsun istedim

Memleket hasreti yakmasın sizleri

Gittiniz uzaklara sesiniz teselli bana 

Hayat mahküm etmiş beni buraya imkansız

İstesem de zamanı gelmeden kavuşamayız

Yüreğim alev alev yanar sizleri bekler

Ben ise size hasret size yanıyorum

                                                                        YAZAN VE DERLEYEN

                                                                              MAHMUT ŞİMŞEK

                                                                                 ADIYAMAN', 'Duydum ki okullar tatil olmuş Memleket hasreti sizleri yakıyormuş Uçup gidin desem uçacaksınız Ben ise size hasret size yanıyorum Duydum ki ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tatil-ozlemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluk Ve Yoksulluk', 'yokluk-ve-yoksulluk-mahmut-simsek-qxlxo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluk yoksulluk büktü boynumu

Yoğun yoksulu oldum duydun mu? 

Gurbet eldeyim sıhhat buldun mu? 

Yoklukla büktüm çocuklarında boynunu.

Bir zamanlar sadaka veriyordum 

Bir garip görsem yardım ediyordum

Şimdi ise yardıma muhtaç ben  oldum

Yoklukla büktüm çocukların da boynunu.

Geçmişteki günlerim hayal oldu

Doğan güneşim zindan oldu

Bir fidan gibi çocuklarım soldu

Yoklukla büktüm çocukların da boynunu.

Susuz kalmış tarla gibiyim

Çölde dağılmış kum gibiyim

Sevgiye susamış çocuk gibiyim

Yoklukla büktüm çocukların da boynunu.

                                                                        YAZAN VE DERLEYEN

                                                                               MAHMUT ŞİMŞEK

                                                                                       ADIYAMAN', 'Yokluk yoksulluk büktü boynumu Yoğun yoksulu oldum duydun mu?  Gurbet eldeyim sıhhat buldun mu?  Yoklukla büktüm çocuklarında boynunu. Bir z...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yokluk-ve-yoksulluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıttı Hiç Uğruna Kanımızı', 'akitti-hic-ugruna-kanimizi-mahmut-simsek-i9hh9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Verdik (Allah)   yoluna canımızı

Kimse gelip sormuyor halimizi

Paylaşmıyor dert ile acımızı

Akıttı  hiç uğruna kanımızı.

Aldı elimizden baş tacımızı

Ana baba sormadı halimizi

Felek sildi süpürdü canımızı

Akıttı  hiç uğruna kanımızı.

Durdurmadı acı göz yaşımızı

Hep ayrı koydu bizle bacımızı

Birden bine katladı acımızı

Akıttı  hiç uğruna kanımızı.

Dostlar görmesin bizim halimizi

Kimse anlamaz bizim derdimizi 

(Allah)  a yöneltik biz kendimizi

Akıttı  hiç uğruna kanımızı 

                                                         YAZAN VE DERLEYEN 

                                                               MAHMUT ŞİMŞEK

                                                                       ADIYAMAN', 'Verdik (Allah)   yoluna canımızı Kimse gelip sormuyor halimizi Paylaşmıyor dert ile acımızı Akıttı  hiç uğruna kanımızı. Aldı elimizden baş ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/akitti-hic-ugruna-kanimizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Yanaklı', 'al-yanakli-mahmut-simsek-zf6ab', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkın deli eder sevgilim beni

Yarınlar bekler güzelim seni

Şeker balmısın göster sevgini

Ekin mi kaldı şimdi zamanı

Karanfil gibi çok çok güzelsin

Al yanaklı güzel bir çiçeksin

Rakı içmez güler geçersin

Fidan boylu güzel bir gelinsin.

Sen bahar kadar hoş ve tazesin

Bereket kokan tarla gibisin

Rabbim gönlüne göre versin

Güzelim etrafa gülümsersin.

İlkbahar gibi güzel kokarsın.

Al yanaklı güzel bir çiçeksin

Benim için bir ömre bedelsin 

Benim olmazsan da kalbimdesin

                                                           YAZAN VE DERLEYEN 

                                                                  MAHMUT ŞİMŞEK

                                                                          ADIYAMAN', 'Aşkın deli eder sevgilim beni Yarınlar bekler güzelim seni Şeker balmısın göster sevgini Ekin mi kaldı şimdi zamanı Karanfil gibi çok çok gü...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/al-yanakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 16', 'guncel-beyitler-16-huseyin-avdic-bmwkr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '$eytanin Esaretindeyken

Seni zehirledigini bildigin halde, ''sigara ilkellik degildir'' deme.

$eytanin esaretinde oldugun halde, ''özgürlügüm tam elimdedir'' deme.

Berlin, Kasim 2005.', '$eytanin Esaretindeyken Seni zehirledigini bildigin halde, ''sigara ilkellik degildir'' deme. $eytanin esaretinde oldugun halde, ''özgürlügüm t...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bâzen Aklıma Geliyorsun - Gelme', 'b-zen-aklima-geliyorsun-gelme-ayhan-yavuz-acikgoz-iojzq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sakladığım gözyaşlarımı 

Damla damla döküyorum hergün 

Ödüm kopuyor bitecek diye 

Sen gelmeden 

Aklıma geliyorsun zamansız 

Gelme 

Ya yanıma gel, ya aklımdan da git 

Sevgi yok 

Aşk yok 

Mutluluk yok 

Hepsi, aptal âşıkların uydurduğu şeyler 

Varsa yoksa, SEN varsın 

Senin de adın yok 

Son dört damla gözyaşı 

Her güne bir damla desen 

Son dört gün 

Gel artık 

Aklıma değil 

Yanıma 

(adana-23.10.2005)', 'Sakladığım gözyaşlarımı  Damla damla döküyorum hergün  Ödüm kopuyor bitecek diye  Sen gelmeden  Aklıma geliyorsun zamansız  Gelme  Ya yanıma...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bazen-aklima-geliyorsun-gelme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
