INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat 3:30', 'saat-3-30-birkan-demirci-nsbwy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir hikayenin anlatılmayan bölümü gibidir

saat 3:30 civarında söylediğim şarkılar

kaldırım taşları aralarına basmamak için verdiğim çaba

o zamanlarda küçümsenemezdi,

şimdide taktirle karşılanır.

merdiven basamaklarını çift atlayarak çıkmam,

insandaki inceliklerinin tarifidir kendince.

birde o zamanlar oturup yakınırdım; 

bayram arifelerinin zamansız gelişinden

3:30 civarında söylediğim şarkılarda 

hep biraz hüzün vardı 

bir şeylere özlem duymak isteği.

12.11.1993/Çorum', 'bir hikayenin anlatılmayan bölümü gibidir saat 3:30 civarında söylediğim şarkılar kaldırım taşları aralarına basmamak için verdiğim çaba o z...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/saat-3-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat bir dalgaysa eğer', 'hayat-bir-dalgaysa-eger-salim-kabasakal-61mbq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen umudun sabahında dağ çiçekleri 

ve 

dağlara serilen sabah güneşi kadar güzeldin; 

yüreğimiz gökyüzü kadar engin, 

bulutlar kadar beyazdı; 

üşüyorum; 

güneşe ulaşılmazlığı bilerek 

soluğunun sıcaklığına sığınmak istiyorum; 

sen olmadan nasıl bakarım gökyüzünün maviliğine. 

nasıl bakarım engin denizlere, 

hayat bir dalgaysa eğer... 

nasıl yürür sularda sandalım, rüzgarın olmadan, 

dolmadan iliklerime sevdanın iksiri, ufuklara nasıl açılabilirim; Yüreğimdekileri her gece kağıtlara dokuyarak, 

her sabah seher yellerine okuyarak 

uzak çığırlara, uzak yollara savuruyorum şimdi;', 'sen umudun sabahında dağ çiçekleri  ve  dağlara serilen sabah güneşi kadar güzeldin;  yüreğimiz gökyüzü kadar engin,  bulutlar kadar beyazdı...', ARRAY['Türk Edebiyatı','Şiir','Salim Kabasakal']::text[], 8.5, '{"poet":"Salim Kabasakal","poet_slug":"salim-kabasakal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayat-bir-dalgaysa-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hain', 'hain-birkan-demirci-b5kdc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'alnımın aklığına düşerse 

ufak bir kara nokta 

gönlüm rahat değilse dürüstlüğünden 

sıyrılsın kalleş deri

hainliğini sakladığı bedenden.

ki ihanet acıtsın içimi.

23.10.1999/Çorum', 'alnımın aklığına düşerse  ufak bir kara nokta  gönlüm rahat değilse dürüstlüğünden  sıyrılsın kalleş deri hainliğini sakladığı bedenden. ki ...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hain-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tohumdan Sarmaşığa', 'tohumdan-sarmasiga-adem-tok-093ed', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kavganın aleviyle

insan sevgisiyle boy verecek yüreğin

yatağının sıcaklığıyla

kendisine emek veren ellerin özverisiyle

tohum misali göğüs kafasine yavrum

şimdi senin saf yüreğin

kundağına yeni sarılmış tohum

yarın yetişip

ertesi gün saksısına sığmayan

sarmaşık olacak

sonra koşacaksın

bendlerini parçalayan nehirler misali

koşacaksın 

inancının o içerisinde beslediği şafakla

bir kereye mahsus

ilelebet buluşmaya

tutabilene aşk olsun

koşarken sen yolunda

                                                                   (13.06.03) 

                                                                    f tipi hapishane TEKİRDAĞ', 'kavganın aleviyle insan sevgisiyle boy verecek yüreğin yatağının sıcaklığıyla kendisine emek veren ellerin özverisiyle tohum misali göğüs ka...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tohumdan-sarmasiga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boynu Bükük Sevda...', 'boynu-bukuk-sevda-i-brahim-ethem-bingul-1vtyt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Toz-duman oldu duygularım

Anlamadın beni, dondu kanım

Canan olmak zordur canım 

Çok mu ağır geldi sevda lisanım...

Aşk, bakabilmek değil ki aynı yere

Aynı şeyi görebilmektir baktığın yerde

Bakma yüzümdeki sakinliğe

En sevdiğim maskemdir o sadece...

Yüreğine koyamam elimle aşkı 

Ama gösterebilirim vefalı olmayı

Ve alıp kefenlik kumaşı

Gömerim boynu bükük sevdayı...

www.iebingul.com', 'Toz-duman oldu duygularım Anlamadın beni, dondu kanım Canan olmak zordur canım  Çok mu ağır geldi sevda lisanım... Aşk, bakabilmek değil ki ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/boynu-bukuk-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karmaşa', 'karmasa-birkan-demirci-olnwi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben seni sevmiyordum,

sende beni.

ben seni seviyordum 

birazda olsa sende beni 

nefret ederdik birbirimizden,

hergün beraber gezerdik.

hiç konuşmazdık birbirimizle,

hep ikimizi anlatırdık kendimize.

duymayan kalmamıştı 

aşk kumruları derlerdi bize.

alakası bile yoktu ''seviyorduk ikimizde''

ne büyük mutluluktu 

ayrılmıştık işte

ikimizde gururluyduk 

''seni seviyorum'' diyemedik birbirimize.

09.07.1998/Çorum', 'ben seni sevmiyordum, sende beni. ben seni seviyordum  birazda olsa sende beni  nefret ederdik birbirimizden, hergün beraber gezerdik. hiç k...', ARRAY['Türk Edebiyatı','Şiir','Birkan Demirci']::text[], 8.5, '{"poet":"Birkan Demirci","poet_slug":"birkan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karmasa-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İSTANBUL... İki FATİH Bakışı', 'i-stanbul-i-ki-fati-h-bakisi-fatih-taskin-qshv9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki   Fatih bakışı:/İstanbul 

‘’ben sen olmak...sen de ben olmak aşk ‘’dır….

Senin umudun benim adıma kavuşmaktı

Benim umudum ise sende ben olana kavuşmaktı

Ben bir yan baktım  tüm Bizans eridi

Sendeki ben bir yan baktı beni benden et di..

Platonik aşktı  Ankara’nın sana bakışı

Sendeki bana aşıktı Ankara’dakinin bakışı

Sana kavuşunca  manevi hazza  eriştim

Sendeki bana ulaşınca lambadaki alevi titrettim

Ben seni aldım  gül nebinin müjdesiydi.

Sendeki ben aklımı çaldı,güller içinde gül pembeydi

Bana ilahi ruhlar yardım etti seni aldım

Sendeki bana  ruhu yardım etti,onda tutuklu kaldım

Bana özlemin vardı açtın tüm kapılarını

Sende  ben olana hasret  batırdı cam kırıklarını

Köse vaat etti beşikteyken seni alacağımı

Sabırsızlıkla bekliyorum sendeki bana kavuşacağımı

İslam ağacının  yapraklarını döktüm tüm sokaklarına 

Kasımda aşk başkadır yazacağım  tüm mahyalarına

Top döktürdüm Urbana surları aşmak için

İç yaktım mumlarında lal olabilmek için

Ya ben seni.. ya sen beni  alacaksın, demiştim sana 

Kavuşamadım ne sendeki bana... ne de bendeki sana 

siyahbereli

kasım/05', 'İki   Fatih bakışı:/İstanbul  ‘’ben sen olmak...sen de ben olmak aşk ‘’dır…. Senin umudun benim adıma kavuşmaktı Benim umudum ise sende ben ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/istanbul-iki-fatih-bakisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sapanca Dağları', 'sapanca-daglari-mehmet-akif-tiryaki-nq89z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sapanca''nın dağlarını sis bastığında

Gökyüzü karalar bağlar, yağmur şarkı söylerdi.

Yeşilin tonları mor rüzgarla dansa kalktığında,

Ağlayan güllerin yüzü gülerdi.

Yağmurla buluşan toprak buram buram terlerdi,

Ah şu bizim kaderimiz hangi ellerdi? 

Yağmurla buluşan toprak buram buram terlerdi.

Memnuniye yollarını duman bürümüş,

İkbaliye, Mahmudiye, İlmiye parfüm sürünmüş,

Sapanca''nın karlı dağı görünmüş,

Kışmı yazmı toprağından bilinmez,

Sapanca''nın yeşili hiç silinmez.

(Maltepe 08-11-2005)', 'Sapanca''nın dağlarını sis bastığında Gökyüzü karalar bağlar, yağmur şarkı söylerdi. Yeşilin tonları mor rüzgarla dansa kalktığında, Ağlayan ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sapanca-daglari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
